CREATE OR REPLACE FUNCTION "private"."current_user_is_admin"() RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select exists (
    select 1
    from public.profiles
    where id = (select auth.uid())
      and role::text = 'admin'
      and is_active = true
  );
$$;


ALTER FUNCTION "private"."current_user_is_admin"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."add_daily_report_customer"("requested_name" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare actor uuid:=auth.uid(); target_id uuid; target_name text:=trim(coalesce(requested_name,''));
begin
  if actor is null then raise exception 'not authenticated'; end if;
  if target_name='' then raise exception 'customer name is required'; end if;

  if not exists(
    select 1
    from public.job_type_memberships m
    join public.job_types jt on jt.id=m.job_type_id
    where m.user_id=actor and jt.is_active=true and jt.legacy_role is null
      and public.has_dynamic_job_type_permission('daily_reports.add_customer',jt.id,actor)
  ) and not exists(
    select 1 from public.profiles p where p.id=actor and p.role='admin' and p.is_active=true
  ) then raise exception 'not allowed'; end if;

  insert into public.daily_report_customers(name,created_by)
  values(target_name,actor)
  on conflict(normalized_name) do update set is_active=true
  returning id,name into target_id,target_name;

  return jsonb_build_object('id',target_id,'name',target_name);
end;
$$;


ALTER FUNCTION "public"."add_daily_report_customer"("requested_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."add_daily_report_subject"("requested_job_type_id" "uuid", "requested_name" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare actor uuid:=auth.uid(); target_id uuid; target_name text:=trim(coalesce(requested_name,''));
begin
  if actor is null then raise exception 'not authenticated'; end if;
  if target_name='' then raise exception 'subject name is required'; end if;
  if not public.has_dynamic_job_type_permission('daily_reports.add_subject',requested_job_type_id,actor)
     and not public.has_dynamic_job_type_permission('daily_reports.manage_subjects',requested_job_type_id,actor)
  then raise exception 'not allowed'; end if;

  insert into public.daily_report_subjects(job_type_id,name,created_by)
  values(requested_job_type_id,target_name,actor)
  on conflict(job_type_id,name) do update set is_active=true
  returning id into target_id;

  return jsonb_build_object('id',target_id,'name',target_name);
end;
$$;


ALTER FUNCTION "public"."add_daily_report_subject"("requested_job_type_id" "uuid", "requested_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."analyze_dynamic_schedule_feasibility"("requested_job_type_id" "uuid", "requested_year" integer, "requested_month" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  current_user_id uuid := auth.uid();
  job public.job_types%rowtype;
  period public.dynamic_availability_periods%rowtype;
  required_total integer := 0;
  target_total integer := 0;
  aggregate_min integer := 0;
  aggregate_target integer := 0;
  aggregate_max integer := 0;
  shortage_slots integer := 0;
  avoid_fallback_slots integer := 0;
  member_json jsonb;
  min_mode text;
  max_mode text;
begin
  if current_user_id is null then raise exception 'not authenticated'; end if;
  if not exists(select 1 from public.user_permissions up where up.user_id=current_user_id and up.permission_key in ('users.view','users.manage')) then raise exception 'not allowed'; end if;

  select * into job from public.job_types where id=requested_job_type_id;
  if job.id is null then raise exception 'job type not found'; end if;

  select * into period from public.dynamic_availability_periods
  where job_type_id=job.id and year=requested_year and month=requested_month;
  if period.id is null then
    return jsonb_build_object('materialized',false,'mode','shadow','message','יש ליצור קודם תקופת אילוצים ב־Shadow Mode.');
  end if;

  select coalesce(sum(min_workers),0),coalesce(sum(target_workers),0)
  into required_total,target_total
  from public.dynamic_availability_slots where period_id=period.id;

  min_mode:=coalesce(job.scheduling_config->>'minimumMode','soft');
  max_mode:=coalesce(job.scheduling_config->>'maximumMode','hard');

  with members as (
    select
      m.user_id,
      p.display_name,
      coalesce(s.min_shifts,(job.availability_config#>>'{monthlyCapacity,defaultMin}')::integer,0) req_min,
      coalesce(s.target_shifts,(job.availability_config#>>'{monthlyCapacity,defaultTarget}')::integer,
               s.min_shifts,(job.availability_config#>>'{monthlyCapacity,defaultMin}')::integer,1) req_target,
      coalesce(s.max_shifts,(job.availability_config#>>'{monthlyCapacity,defaultMax}')::integer,2147483647) req_max,
      case when job.employment_scope='flexible' then nullif(m.metadata->>'employmentScope','') else job.employment_scope end member_scope,
      case
        when job.employment_scope='flexible' and m.metadata->>'employmentScope'='part_time' then 0.5::numeric
        else 1::numeric
      end employment_factor,
      (select count(*) from public.dynamic_availability_entries e
       join public.dynamic_availability_submissions ss on ss.id=e.submission_id
       where ss.period_id=period.id and ss.user_id=m.user_id
         and e.availability_status in ('available','preferred','avoid')) available_slots
    from public.job_type_memberships m
    join public.profiles p on p.id=m.user_id
    left join public.dynamic_availability_submissions s on s.period_id=period.id and s.user_id=m.user_id
    where m.job_type_id=job.id and p.is_active=true
  ), weighted as (
    select *,greatest(req_target,req_min,1)::numeric * employment_factor weight
    from members
  ), totals as (
    select greatest(sum(weight),1) total_weight from weighted
  ), calculated as (
    select w.*,round(required_total*w.weight/t.total_weight,2) raw_share,
      least(w.req_max,w.available_slots)::integer capacity_cap
    from weighted w cross join totals t
  )
  select
    coalesce(sum(req_min),0),
    coalesce(sum(req_target),0),
    coalesce(sum(case when req_max=2147483647 then required_total else req_max end),0),
    coalesce(jsonb_agg(jsonb_build_object(
      'userId',user_id,'displayName',display_name,'minimum',req_min,'target',req_target,
      'maximum',case when req_max=2147483647 then null else req_max end,
      'availableSlots',available_slots,'weight',weight,
      'employmentScope',member_scope,'employmentFactor',employment_factor,
      'rawProportionalTarget',raw_share,'capacityCap',capacity_cap,
      'proportionalTarget',least(raw_share,capacity_cap::numeric)
    ) order by display_name),'[]'::jsonb)
  into aggregate_min,aggregate_target,aggregate_max,member_json
  from calculated;

  select count(*) into shortage_slots
  from public.dynamic_availability_slots sl
  where sl.period_id=period.id and (
    select count(distinct ss.user_id)
    from public.dynamic_availability_entries e
    join public.dynamic_availability_submissions ss on ss.id=e.submission_id
    join public.job_type_memberships m on m.user_id=ss.user_id and m.job_type_id=job.id
    where e.slot_id=sl.id and e.availability_status in ('available','preferred','avoid')
  ) < sl.min_workers;

  select count(*) into avoid_fallback_slots
  from public.dynamic_availability_slots sl
  where sl.period_id=period.id
    and (select count(distinct ss.user_id) from public.dynamic_availability_entries e
         join public.dynamic_availability_submissions ss on ss.id=e.submission_id
         join public.job_type_memberships m on m.user_id=ss.user_id and m.job_type_id=job.id
         where e.slot_id=sl.id and e.availability_status in ('available','preferred')) < sl.min_workers
    and (select count(distinct ss.user_id) from public.dynamic_availability_entries e
         join public.dynamic_availability_submissions ss on ss.id=e.submission_id
         join public.job_type_memberships m on m.user_id=ss.user_id and m.job_type_id=job.id
         where e.slot_id=sl.id and e.availability_status in ('available','preferred','avoid')) >= sl.min_workers;

  return jsonb_build_object(
    'materialized',true,'periodId',period.id,'jobTypeId',job.id,'year',requested_year,'month',requested_month,'mode','shadow',
    'requiredAssignments',required_total,'targetAssignments',target_total,
    'aggregateMinimum',aggregate_min,'aggregateTarget',aggregate_target,'aggregateMaximum',aggregate_max,
    'minimumMode',min_mode,'maximumMode',max_mode,
    'minimumDemandExcess',greatest(aggregate_min-required_total,0),
    'maximumCapacityShortage',greatest(required_total-aggregate_max,0),
    'slotsWithoutEnoughCandidates',shortage_slots,'slotsRequiringAvoidCandidates',avoid_fallback_slots,
    'canMeetAllMinimums',aggregate_min<=required_total,'canCoverRequiredByMaximums',aggregate_max>=required_total,
    'hasCandidateShortages',shortage_slots>0,'members',member_json,
    'employmentRecommendationEnabled',job.employment_scope='flexible',
    'warnings',jsonb_strip_nulls(jsonb_build_object(
      'minimums',case when aggregate_min>required_total then 'סכום המינימום של העובדים גבוה מכמות ההקצאות הקיימת; המנוע יעבור לחלוקה פרופורציונלית.' end,
      'maximums',case when aggregate_max<required_total then 'גם אם כל עובד יקבל את המקסימום שלו, אין מספיק קיבולת לכיסוי כל המשמרות.' end,
      'candidates',case when shortage_slots>0 then shortage_slots || ' משמרות ללא מספיק מועמדים גם לאחר שימוש ב״מעדיף שלא״.' end,
      'avoidFallback',case when avoid_fallback_slots>0 then avoid_fallback_slots || ' משמרות ניתנות לכיסוי רק באמצעות לפחות עובד אחד שסימן ״מעדיף שלא״.' end
    ))
  );
end;
$$;


ALTER FUNCTION "public"."analyze_dynamic_schedule_feasibility"("requested_job_type_id" "uuid", "requested_year" integer, "requested_month" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_default_user_permissions"("target_user_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  target_role text;
begin
  select role::text
  into target_role
  from public.profiles
  where id = target_user_id;

  if target_role is null then
    return;
  end if;

  insert into public.user_permissions (
    user_id,
    permission_key
  )
  select
    target_user_id,
    defaults.permission_key
  from public.role_default_permissions defaults
  where defaults.role_name = target_role
  on conflict do nothing;
end;
$$;


ALTER FUNCTION "public"."apply_default_user_permissions"("target_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."attendance_distance_m"("lat1" double precision, "lng1" double precision, "lat2" double precision, "lng2" double precision) RETURNS numeric
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
 select case when lat1 is null or lng1 is null or lat2 is null or lng2 is null then null else
 round((6371000 * 2 * asin(sqrt(power(sin(radians(lat2-lat1)/2),2)+cos(radians(lat1))*cos(radians(lat2))*power(sin(radians(lng2-lng1)/2),2))))::numeric,1) end;
$$;


ALTER FUNCTION "public"."attendance_distance_m"("lat1" double precision, "lng1" double precision, "lat2" double precision, "lng2" double precision) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."can_configure_manager_dashboard"("requested_user_id" "uuid" DEFAULT "auth"."uid"()) RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select requested_user_id is not null
     and requested_user_id = auth.uid()
     and (
       exists (
         select 1
         from public.user_permissions up
         where up.user_id=requested_user_id
           and up.permission_key='users.manage'
       )
       or exists (
         select 1
         from public.job_type_managers jm
         where jm.user_id=requested_user_id
       )
     );
$$;


ALTER FUNCTION "public"."can_configure_manager_dashboard"("requested_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."can_delete_daily_report_attachment"("requested_storage_path" "text") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare actor uuid:=auth.uid(); report_id_value uuid;
begin
  if actor is null then return false; end if;
  begin
    report_id_value:=split_part(requested_storage_path,'/',1)::uuid;
  exception when others then
    return false;
  end;

  return exists(
    select 1 from public.daily_reports r
    where r.id=report_id_value
      and r.user_id=actor
      and r.status='draft'
  );
end;
$$;


ALTER FUNCTION "public"."can_delete_daily_report_attachment"("requested_storage_path" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."can_read_daily_report_attachment"("requested_storage_path" "text") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor uuid:=auth.uid();
begin
  if actor is null then return false; end if;

  return exists(
    select 1
    from public.daily_report_attachments a
    join public.daily_reports r on r.id=a.report_id
    join public.job_types jt on jt.id=r.job_type_id
    where a.storage_path=requested_storage_path
      and (
        r.user_id=actor
        or (jt.scheduling_config#>'{dailyReports,recipientUserIds}') ? actor::text
        or public.has_dynamic_job_type_permission(
          'daily_reports.view_attachment',
          r.job_type_id,
          actor
        )
      )
  );
end;
$$;


ALTER FUNCTION "public"."can_read_daily_report_attachment"("requested_storage_path" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."can_upload_daily_report_attachment"("requested_storage_path" "text") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor uuid:=auth.uid();
  target_report_id uuid;
  target_job_type_id uuid;
begin
  if actor is null then return false; end if;

  begin
    target_report_id:=split_part(requested_storage_path,'/',1)::uuid;
  exception when others then
    return false;
  end;

  select r.job_type_id
  into target_job_type_id
  from public.daily_reports r
  join public.job_types jt on jt.id=r.job_type_id
  where r.id=target_report_id
    and r.user_id=actor
    and r.status='draft'
    and coalesce((jt.scheduling_config#>>'{dailyReports,allowAttachments}')::boolean,true);

  if target_job_type_id is null then return false; end if;

  return public.has_dynamic_job_type_permission(
    'daily_reports.upload_attachment',
    target_job_type_id,
    actor
  );
end;
$$;


ALTER FUNCTION "public"."can_upload_daily_report_attachment"("requested_storage_path" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cancel_dynamic_shift_exchange_request"("requested_request_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  current_user_id uuid := auth.uid();
  r public.dynamic_shift_exchange_requests%rowtype;
begin
  if current_user_id is null then raise exception 'not authenticated'; end if;
  select * into r from public.dynamic_shift_exchange_requests where id=requested_request_id for update;
  if r.id is null then raise exception 'הבקשה לא נמצאה.'; end if;
  if r.requester_user_id<>current_user_id then raise exception 'רק מגיש הבקשה יכול לבטל אותה.'; end if;
  if r.status not in ('pending_counterparty','pending_manager') then raise exception 'לא ניתן לבטל בקשה במצב הנוכחי.'; end if;
  update public.dynamic_shift_exchange_requests set status='cancelled',cancelled_at=now(),updated_at=now() where id=r.id returning * into r;
  insert into public.audit_logs(action,actor_user_id,entity_type,entity_id,summary,metadata)
  values('shift_swap_cancelled',current_user_id,'dynamic_shift_exchange_request',r.id,'בקשת חילופים דינמית בוטלה','{}'::jsonb);
  return jsonb_build_object('id',r.id,'status',r.status);
end;
$$;


ALTER FUNCTION "public"."cancel_dynamic_shift_exchange_request"("requested_request_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cancel_shift_swap_request"("requested_request_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  current_user_id uuid := auth.uid();
  request_row public.shift_swap_requests%rowtype;
begin
  if current_user_id is null then
    raise exception 'לא נמצאה התחברות פעילה.';
  end if;

  select *
  into request_row
  from public.shift_swap_requests
  where id = requested_request_id
  for update;

  if not found then
    raise exception 'בקשת ההחלפה לא נמצאה.';
  end if;

  if request_row.requester_user_id <> current_user_id then
    raise exception 'רק מגיש הבקשה יכול לבטל אותה.';
  end if;

  if request_row.status not in ('pending_counterparty', 'pending_manager') then
    raise exception 'לא ניתן לבטל בקשה שכבר נסגרה.';
  end if;

  update public.shift_swap_requests
  set
    status = 'cancelled',
    cancelled_at = now()
  where id = request_row.id
  returning * into request_row;

  return jsonb_build_object(
    'id', request_row.id,
    'status', request_row.status,
    'cancelledAt', request_row.cancelled_at
  );
end;
$$;


ALTER FUNCTION "public"."cancel_shift_swap_request"("requested_request_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."clock_my_attendance"("requested_job_type_id" "uuid", "requested_action" "text", "requested_lat" double precision, "requested_lng" double precision, "requested_accuracy_m" numeric DEFAULT NULL::numeric) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare uid uuid:=auth.uid(); jt public.job_types%rowtype; cfg jsonb; radius numeric; site_lat double precision; site_lng double precision; dist numeric; within_radius boolean; sess public.attendance_sessions%rowtype; assignment_id uuid; local_date date:=(now() at time zone 'Asia/Jerusalem')::date; allow_unscheduled boolean; outside_policy text; rate numeric;
begin
 if uid is null then raise exception 'not authenticated'; end if;
 select * into jt from public.job_types where id=requested_job_type_id;
 if jt.id is null or not coalesce((jt.scheduling_config#>>'{attendance,enabled}')::boolean,false) then raise exception 'attendance disabled'; end if;
 if not public.has_dynamic_job_type_permission('attendance.clock',jt.id,uid) then raise exception 'not allowed'; end if;
 cfg:=jt.scheduling_config->'attendance'; site_lat:=nullif(cfg->>'latitude','')::double precision; site_lng:=nullif(cfg->>'longitude','')::double precision; radius:=coalesce(nullif(cfg->>'radiusMeters','')::numeric,150); allow_unscheduled:=coalesce((cfg->>'allowUnscheduled')::boolean,false); outside_policy:=coalesce(cfg->>'outsidePolicy','flag');
 if coalesce((cfg->>'requireLocation')::boolean,true) and (requested_lat is null or requested_lng is null) then raise exception 'location required'; end if;
 dist:=public.attendance_distance_m(requested_lat,requested_lng,site_lat,site_lng); within_radius:=case when dist is null then null else dist<=radius end;
 if outside_policy='block' and within_radius=false then raise exception 'outside allowed workplace radius'; end if;
 if requested_action='in' then
   if exists(select 1 from public.attendance_sessions s where s.user_id=uid and s.job_type_id=jt.id and s.clock_out_at is null) then raise exception 'already clocked in'; end if;
   select a.id into assignment_id from public.dynamic_schedule_publications p join public.dynamic_schedule_published_assignments a on a.publication_id=p.id
   cross join lateral public.dynamic_resolve_assignment_local_interval(a.shift_date,a.start_time,a.end_time,coalesce(jt.scheduling_config#>>'{shiftPattern,workMode}','shifts'),jt.scheduling_config) iv
   where p.job_type_id=jt.id and p.status='published' and a.user_id=uid and (now() at time zone 'Asia/Jerusalem') between iv.start_at-interval '4 hours' and iv.end_at+interval '4 hours' order by abs(extract(epoch from((now() at time zone 'Asia/Jerusalem')-iv.start_at))) limit 1;
   if assignment_id is null and not allow_unscheduled then raise exception 'no scheduled shift near current time'; end if;
   select p.hourly_rate into rate from public.profiles p where p.id=uid;
   insert into public.attendance_sessions(job_type_id,user_id,assignment_id,work_date,clock_in_at,clock_in_lat,clock_in_lng,clock_in_accuracy_m,clock_in_distance_m,clock_in_within_radius,hourly_rate_snapshot)
   values(jt.id,uid,assignment_id,local_date,now(),requested_lat,requested_lng,requested_accuracy_m,dist,within_radius,rate) returning * into sess;
 elsif requested_action='out' then
   select * into sess from public.attendance_sessions s where s.user_id=uid and s.job_type_id=jt.id and s.clock_out_at is null order by s.clock_in_at desc limit 1 for update;
   if sess.id is null then raise exception 'no open attendance session'; end if;
   update public.attendance_sessions set clock_out_at=now(),clock_out_lat=requested_lat,clock_out_lng=requested_lng,clock_out_accuracy_m=requested_accuracy_m,clock_out_distance_m=dist,clock_out_within_radius=within_radius,updated_at=now() where id=sess.id returning * into sess;
 else raise exception 'invalid attendance action'; end if;
 insert into public.audit_logs(action,actor_user_id,entity_type,entity_id,summary,metadata) values('system_event',uid,'attendance_session',sess.id,case when requested_action='in' then 'דיווח כניסה' else 'דיווח יציאה' end,jsonb_build_object('job_type_id',jt.id,'distance_m',dist,'within_radius',within_radius));
 return jsonb_build_object('id',sess.id,'action',requested_action,'distanceM',dist,'withinRadius',within_radius,'clockInAt',sess.clock_in_at,'clockOutAt',sess.clock_out_at);
end; $$;


ALTER FUNCTION "public"."clock_my_attendance"("requested_job_type_id" "uuid", "requested_action" "text", "requested_lat" double precision, "requested_lng" double precision, "requested_accuracy_m" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."close_availability_period"("requested_period_id" "uuid") RETURNS TABLE("period_id" "uuid", "period_status" "text", "closed_at" timestamp with time zone, "total_dispatchers" integer, "submitted_dispatchers" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  current_user_id uuid;
  current_actor_email text;
  current_actor_display_name text;
  target_period_title text;
  target_period_year integer;
  target_period_month integer;
  target_period_status text;
  calculated_total_dispatchers integer;
  originally_submitted_dispatchers integer;
  calculated_submitted_dispatchers integer;
  target_closed_at timestamptz;
  auto_completed_entries integer := 0;
  auto_completed_users integer := 0;
  auto_note constant text :=
    'סומן כזמין אוטומטית עקב אי־הגשה עד מועד סגירת התקופה.';
begin
  current_user_id := auth.uid();

  if current_user_id is null then
    raise exception 'User is not authenticated';
  end if;

  select
    profile.email,
    profile.display_name
  into
    current_actor_email,
    current_actor_display_name
  from public.profiles profile
  where profile.id = current_user_id
    and profile.is_active = true;

  if current_actor_email is null then
    raise exception 'Authenticated user is not active';
  end if;

  if not exists (
    select 1
    from public.user_permissions permission
    where permission.user_id = current_user_id
      and permission.permission_key = 'availability.manage'
  ) then
    raise exception 'User is not allowed to manage availability periods';
  end if;

  if requested_period_id is null then
    raise exception 'Availability period id is required';
  end if;

  select
    period.title,
    period.year,
    period.month,
    period.status
  into
    target_period_title,
    target_period_year,
    target_period_month,
    target_period_status
  from public.availability_periods period
  where period.id = requested_period_id
  for update;

  if target_period_year is null then
    raise exception 'Availability period was not found';
  end if;

  if target_period_status <> 'open' then
    raise exception 'Only open availability periods can be closed';
  end if;

  select count(*)::integer
  into calculated_total_dispatchers
  from public.profiles profile
  where profile.role::text = 'dispatcher'
    and profile.is_active = true;

  select count(*)::integer
  into originally_submitted_dispatchers
  from public.availability_submissions submission
  join public.profiles profile
    on profile.id = submission.user_id
  where submission.period_id = requested_period_id
    and submission.status = 'submitted'
    and profile.role::text = 'dispatcher'
    and profile.is_active = true;

  if calculated_total_dispatchers = 0 then
    raise exception 'No active dispatchers were found';
  end if;

  target_closed_at := now();

  select count(*)::integer
  into auto_completed_users
  from public.profiles profile
  left join public.availability_submissions submission
    on submission.period_id = requested_period_id
   and submission.user_id = profile.id
  where profile.role::text = 'dispatcher'
    and profile.is_active = true
    and coalesce(submission.status, 'draft') <> 'submitted';

  insert into public.availability_submissions (
    period_id,
    user_id,
    status,
    last_saved_at,
    available_count,
    unavailable_count
  )
  select
    requested_period_id,
    profile.id,
    'draft',
    target_closed_at,
    0,
    0
  from public.profiles profile
  where profile.role::text = 'dispatcher'
    and profile.is_active = true
    and not exists (
      select 1
      from public.availability_submissions existing_submission
      where existing_submission.period_id = requested_period_id
        and existing_submission.user_id = profile.id
    );

  insert into public.dispatcher_availability (
    period_id,
    shift_slot_id,
    user_id,
    availability_status,
    note,
    is_auto_completed,
    created_at,
    updated_at
  )
  select
    requested_period_id,
    slot.id,
    profile.id,
    'available',
    auto_note,
    true,
    target_closed_at,
    target_closed_at
  from public.profiles profile
  cross join public.availability_shift_slots slot
  left join public.availability_submissions submission
    on submission.period_id = requested_period_id
   and submission.user_id = profile.id
  where slot.period_id = requested_period_id
    and profile.role::text = 'dispatcher'
    and profile.is_active = true
    and coalesce(submission.status, 'draft') <> 'submitted'
    and not exists (
      select 1
      from public.dispatcher_availability existing_entry
      where existing_entry.period_id = requested_period_id
        and existing_entry.shift_slot_id = slot.id
        and existing_entry.user_id = profile.id
    )
  on conflict on constraint dispatcher_availability_unique
  do nothing;

  get diagnostics auto_completed_entries = row_count;

  update public.availability_submissions submission
  set
    status = 'submitted',
    submitted_at = coalesce(submission.submitted_at, target_closed_at),
    reopened_at = null,
    submission_source = (
      select
        case
          when count(*) filter (where entry.is_auto_completed) = 0
            then 'manual'
          when count(*) filter (where entry.is_auto_completed) >= count(*)
            then 'auto_no_submission'
          else 'auto_partial'
        end
      from public.dispatcher_availability entry
      where entry.period_id = requested_period_id
        and entry.user_id = submission.user_id
    ),
    auto_completed_count = (
      select count(*)::integer
      from public.dispatcher_availability entry
      where entry.period_id = requested_period_id
        and entry.user_id = submission.user_id
        and entry.is_auto_completed = true
    ),
    available_count = (
      select count(*)::integer
      from public.dispatcher_availability entry
      where entry.period_id = requested_period_id
        and entry.user_id = submission.user_id
        and entry.availability_status = 'available'
    ),
    unavailable_count = (
      select count(*)::integer
      from public.dispatcher_availability entry
      where entry.period_id = requested_period_id
        and entry.user_id = submission.user_id
        and entry.availability_status = 'unavailable'
    ),
    last_saved_at = coalesce(submission.last_saved_at, target_closed_at),
    updated_at = target_closed_at
  where submission.period_id = requested_period_id
    and submission.status <> 'submitted';

  select count(*)::integer
  into calculated_submitted_dispatchers
  from public.availability_submissions submission
  join public.profiles profile
    on profile.id = submission.user_id
  where submission.period_id = requested_period_id
    and submission.status = 'submitted'
    and profile.role::text = 'dispatcher'
    and profile.is_active = true;

  update public.availability_periods period
  set
    status = 'closed',
    closed_at = target_closed_at,
    updated_by = current_user_id,
    updated_at = target_closed_at
  where period.id = requested_period_id;

  insert into public.audit_logs (
    action,
    actor_user_id,
    actor_email,
    actor_display_name,
    target_user_id,
    target_email,
    target_display_name,
    entity_type,
    entity_id,
    summary,
    old_values,
    new_values,
    metadata
  )
  values (
    'availability_period_closed',
    current_user_id,
    current_actor_email,
    current_actor_display_name,
    null,
    null,
    null,
    'availability_period',
    requested_period_id,
    format(
      'נסגרה תקופת אילוצים: %s',
      coalesce(
        target_period_title,
        format('%s/%s', target_period_month, target_period_year)
      )
    ),
    jsonb_build_object('status', 'open'),
    jsonb_build_object(
      'status', 'closed',
      'closed_at', target_closed_at,
      'total_dispatchers', calculated_total_dispatchers,
      'submitted_dispatchers', calculated_submitted_dispatchers,
      'originally_submitted_dispatchers', originally_submitted_dispatchers,
      'auto_completed_users', auto_completed_users,
      'auto_completed_entries', auto_completed_entries
    ),
    jsonb_build_object(
      'source', 'close-availability-period-rpc',
      'period_id', requested_period_id,
      'year', target_period_year,
      'month', target_period_month,
      'auto_fill_unmarked_as_available', true,
      'auto_submit_completed_forms', true
    )
  );

  return query
  select
    requested_period_id,
    'closed'::text,
    target_closed_at,
    calculated_total_dispatchers,
    calculated_submitted_dispatchers;
end;
$$;


ALTER FUNCTION "public"."close_availability_period"("requested_period_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."close_driver_availability_period"("requested_period_id" "uuid", "requested_force" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  current_user_id uuid;
  current_permissions text[];
  target_period public.driver_availability_periods%rowtype;
  total_drivers_count integer := 0;
  submitted_drivers_count integer := 0;
  missing_drivers_count integer := 0;
  auto_completed_entries integer := 0;
  auto_completed_users integer := 0;
  closed_at_value timestamptz := now();
  auto_note constant text :=
    'סומן כזמין אוטומטית עקב אי־הגשה עד מועד סגירת התקופה.';
begin
  current_user_id := auth.uid();

  if current_user_id is null then
    raise exception 'not authenticated';
  end if;

  if not exists (
    select 1
    from public.profiles
    where id = current_user_id
      and is_active = true
  ) then
    raise exception 'user not active';
  end if;

  current_permissions :=
    coalesce(
      public.get_my_permissions(),
      array[]::text[]
    );

  if not (
    'driver_availability.manage' =
      any(current_permissions)
  ) then
    raise exception 'not allowed';
  end if;

  if requested_period_id is null then
    raise exception 'driver availability period id is required';
  end if;

  select *
  into target_period
  from public.driver_availability_periods
  where id = requested_period_id
  for update;

  if not found then
    raise exception 'driver availability period not found';
  end if;

  select count(*)::integer
  into total_drivers_count
  from public.profiles
  where role = 'on_call'::public.user_role
    and is_active = true;

  select count(distinct submission.user_id)::integer
  into submitted_drivers_count
  from public.driver_availability_submissions submission
  join public.profiles profile
    on profile.id = submission.user_id
  where submission.period_id = target_period.id
    and submission.status = 'submitted'
    and profile.role = 'on_call'::public.user_role
    and profile.is_active = true;

  missing_drivers_count :=
    greatest(
      total_drivers_count - submitted_drivers_count,
      0
    );

  if target_period.status = 'closed' then
    return jsonb_build_object(
      'periodId', target_period.id,
      'year', target_period.year,
      'month', target_period.month,
      'status', target_period.status,
      'closedAt', target_period.closed_at,
      'totalDrivers', total_drivers_count,
      'submittedDrivers', submitted_drivers_count,
      'missingDrivers', missing_drivers_count,
      'autoCompletedUsers', 0,
      'autoCompletedEntries', 0,
      'forced', false,
      'alreadyClosed', true
    );
  end if;

  if target_period.status <> 'open' then
    raise exception
      'only open driver availability periods can be closed';
  end if;

  select count(*)::integer
  into auto_completed_users
  from public.profiles profile
  left join public.driver_availability_submissions submission
    on submission.period_id = target_period.id
   and submission.user_id = profile.id
  where profile.role = 'on_call'::public.user_role
    and profile.is_active = true
    and coalesce(submission.status, 'draft') <> 'submitted';

  insert into public.driver_availability_submissions (
    period_id,
    user_id,
    status,
    last_saved_at,
    available_count,
    unavailable_count
  )
  select
    target_period.id,
    profile.id,
    'draft',
    closed_at_value,
    0,
    0
  from public.profiles profile
  where profile.role = 'on_call'::public.user_role
    and profile.is_active = true
    and not exists (
      select 1
      from public.driver_availability_submissions existing_submission
      where existing_submission.period_id = target_period.id
        and existing_submission.user_id = profile.id
    );

  insert into public.driver_availability_entries (
    period_id,
    day_id,
    user_id,
    availability_status,
    note,
    updated_at
  )
  select
    target_period.id,
    day_row.id,
    profile.id,
    'available',
    auto_note,
    closed_at_value
  from public.profiles profile
  cross join public.driver_availability_days day_row
  left join public.driver_availability_submissions submission
    on submission.period_id = target_period.id
   and submission.user_id = profile.id
  where day_row.period_id = target_period.id
    and profile.role = 'on_call'::public.user_role
    and profile.is_active = true
    and coalesce(submission.status, 'draft') <> 'submitted'
    and not exists (
      select 1
      from public.driver_availability_entries existing_entry
      where existing_entry.period_id = target_period.id
        and existing_entry.day_id = day_row.id
        and existing_entry.user_id = profile.id
    )
  on conflict (day_id, user_id)
  do nothing;

  get diagnostics auto_completed_entries = row_count;

  update public.driver_availability_submissions submission
  set
    available_count = (
      select count(*)::integer
      from public.driver_availability_entries entry
      where entry.period_id = target_period.id
        and entry.user_id = submission.user_id
        and entry.availability_status = 'available'
    ),
    unavailable_count = (
      select count(*)::integer
      from public.driver_availability_entries entry
      where entry.period_id = target_period.id
        and entry.user_id = submission.user_id
        and entry.availability_status = 'unavailable'
    ),
    last_saved_at = coalesce(
      submission.last_saved_at,
      closed_at_value
    ),
    updated_at = closed_at_value
  where submission.period_id = target_period.id
    and submission.status <> 'submitted';

  update public.driver_availability_periods
  set
    status = 'closed',
    closed_at = closed_at_value,
    updated_by = current_user_id,
    updated_at = closed_at_value
  where id = target_period.id
  returning *
  into target_period;

  return jsonb_build_object(
    'periodId', target_period.id,
    'year', target_period.year,
    'month', target_period.month,
    'status', target_period.status,
    'closedAt', target_period.closed_at,
    'totalDrivers', total_drivers_count,
    'submittedDrivers', submitted_drivers_count,
    'missingDrivers', missing_drivers_count,
    'autoCompletedUsers', auto_completed_users,
    'autoCompletedEntries', auto_completed_entries,
    'forced', false,
    'alreadyClosed', false
  );
end;
$$;


ALTER FUNCTION "public"."close_driver_availability_period"("requested_period_id" "uuid", "requested_force" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."close_driver_availability_period"("requested_period_id" "uuid", "requested_force" boolean) IS 'Closes an open driver availability period. By default all active on-call users must submit; managers may force closure.';



CREATE OR REPLACE FUNCTION "public"."close_morning_driver_availability_period"("requested_period_id" "uuid", "requested_force" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  current_user_id uuid;
  current_permissions text[];
  target_period public.morning_driver_availability_periods%rowtype;
  total_drivers integer := 0;
  submitted_drivers integer := 0;
  missing_drivers integer := 0;
  auto_completed_entries integer := 0;
  auto_completed_users integer := 0;
  closed_at_value timestamptz := now();
  auto_note constant text :=
    'סומן כזמין אוטומטית עקב אי־הגשה עד מועד סגירת התקופה.';
begin
  current_user_id := auth.uid();

  if current_user_id is null then
    raise exception 'not authenticated';
  end if;

  current_permissions :=
    coalesce(
      public.get_my_permissions(),
      array[]::text[]
    );

  if not (
    'morning_driver_availability.manage' =
      any(current_permissions)
  ) then
    raise exception 'not allowed';
  end if;

  if requested_period_id is null then
    raise exception 'period id is required';
  end if;

  select *
  into target_period
  from public.morning_driver_availability_periods period
  where period.id = requested_period_id
  for update;

  if not found then
    raise exception
      'morning driver availability period not found';
  end if;

  select count(*)
  into total_drivers
  from public.profiles profile
  where profile.role =
      'morning_driver'::public.user_role
    and profile.is_active = true;

  select count(*)
  into submitted_drivers
  from public.morning_driver_availability_submissions submission
  join public.profiles profile
    on profile.id = submission.user_id
  where submission.period_id = target_period.id
    and submission.status = 'submitted'
    and profile.role =
      'morning_driver'::public.user_role
    and profile.is_active = true;

  missing_drivers :=
    greatest(
      total_drivers - submitted_drivers,
      0
    );

  if target_period.status = 'closed' then
    return jsonb_build_object(
      'periodId', target_period.id,
      'year', target_period.year,
      'month', target_period.month,
      'status', target_period.status,
      'closedAt', target_period.closed_at,
      'totalDrivers', total_drivers,
      'submittedDrivers', submitted_drivers,
      'missingDrivers', missing_drivers,
      'autoCompletedUsers', 0,
      'autoCompletedEntries', 0,
      'forced', false,
      'alreadyClosed', true
    );
  end if;

  if target_period.status <> 'open' then
    raise exception 'only open periods can be closed';
  end if;

  select count(*)::integer
  into auto_completed_users
  from public.profiles profile
  left join public.morning_driver_availability_submissions submission
    on submission.period_id = target_period.id
   and submission.user_id = profile.id
  where profile.role =
      'morning_driver'::public.user_role
    and profile.is_active = true
    and coalesce(submission.status, 'draft') <> 'submitted';

  insert into public.morning_driver_availability_submissions (
    period_id,
    user_id,
    status
  )
  select
    target_period.id,
    profile.id,
    'draft'
  from public.profiles profile
  where profile.role =
      'morning_driver'::public.user_role
    and profile.is_active = true
    and not exists (
      select 1
      from public.morning_driver_availability_submissions existing_submission
      where existing_submission.period_id = target_period.id
        and existing_submission.user_id = profile.id
    );

  insert into public.morning_driver_availability_entries (
    period_id,
    shift_id,
    user_id,
    availability_status,
    note,
    updated_at
  )
  select
    target_period.id,
    shift_item.id,
    profile.id,
    'available',
    auto_note,
    closed_at_value
  from public.profiles profile
  cross join public.morning_driver_availability_shifts shift_item
  left join public.morning_driver_availability_submissions submission
    on submission.period_id = target_period.id
   and submission.user_id = profile.id
  where shift_item.period_id = target_period.id
    and profile.role =
      'morning_driver'::public.user_role
    and profile.is_active = true
    and coalesce(submission.status, 'draft') <> 'submitted'
    and not exists (
      select 1
      from public.morning_driver_availability_entries existing_entry
      where existing_entry.period_id = target_period.id
        and existing_entry.shift_id = shift_item.id
        and existing_entry.user_id = profile.id
    )
  on conflict (shift_id, user_id)
  do nothing;

  get diagnostics auto_completed_entries = row_count;

  update public.morning_driver_availability_submissions submission
  set
    last_saved_at = coalesce(
      submission.last_saved_at,
      closed_at_value
    ),
    updated_at = closed_at_value
  where submission.period_id = target_period.id
    and submission.status <> 'submitted';

  update public.morning_driver_availability_periods
  set
    status = 'closed',
    closed_at = closed_at_value,
    updated_by = current_user_id,
    updated_at = closed_at_value
  where id = target_period.id
  returning *
  into target_period;

  return jsonb_build_object(
    'periodId', target_period.id,
    'year', target_period.year,
    'month', target_period.month,
    'status', target_period.status,
    'closedAt', target_period.closed_at,
    'totalDrivers', total_drivers,
    'submittedDrivers', submitted_drivers,
    'missingDrivers', missing_drivers,
    'autoCompletedUsers', auto_completed_users,
    'autoCompletedEntries', auto_completed_entries,
    'forced', false,
    'alreadyClosed', false
  );
end;
$$;


ALTER FUNCTION "public"."close_morning_driver_availability_period"("requested_period_id" "uuid", "requested_force" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."compare_dynamic_availability_shadow_to_legacy"("requested_job_type_id" "uuid", "requested_year" integer, "requested_month" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  current_user_id uuid := auth.uid();
  job public.job_types%rowtype;
  dynamic_period public.dynamic_availability_periods%rowtype;
  legacy_period_id uuid;
  dynamic_slots integer := 0;
  dynamic_members integer := 0;
  dynamic_entries integer := 0;
  legacy_slots integer := 0;
  legacy_entries integer := 0;
  legacy_members integer := 0;
  supported boolean := true;
  note text := null;
begin
  if current_user_id is null then
    raise exception 'not authenticated';
  end if;

  if not exists (
    select 1
    from public.user_permissions up
    where up.user_id = current_user_id
      and up.permission_key in ('users.view', 'users.manage')
  ) then
    raise exception 'not allowed';
  end if;

  select *
  into job
  from public.job_types jt
  where jt.id = requested_job_type_id;

  if job.id is null then
    raise exception 'job type not found';
  end if;

  select *
  into dynamic_period
  from public.dynamic_availability_periods dap
  where dap.job_type_id = job.id
    and dap.year = requested_year
    and dap.month = requested_month;

  if dynamic_period.id is not null then
    select count(*)::integer
    into dynamic_slots
    from public.dynamic_availability_slots das
    where das.period_id = dynamic_period.id;

    select count(*)::integer
    into dynamic_members
    from public.job_type_memberships jtm
    where jtm.job_type_id = job.id;

    select count(*)::integer
    into dynamic_entries
    from public.dynamic_availability_entries dae
    join public.dynamic_availability_submissions dasub
      on dasub.id = dae.submission_id
    where dasub.period_id = dynamic_period.id;
  end if;

  if job.legacy_role = 'dispatcher' then
    select ap.id
    into legacy_period_id
    from public.availability_periods ap
    where ap.year = requested_year
      and ap.month = requested_month
    order by ap.created_at desc
    limit 1;

    if legacy_period_id is not null then
      select count(*)::integer
      into legacy_slots
      from public.availability_shift_slots ass
      where ass.period_id = legacy_period_id;

      select
        count(distinct da.user_id)::integer,
        count(*)::integer
      into
        legacy_members,
        legacy_entries
      from public.dispatcher_availability da
      where da.period_id = legacy_period_id;
    end if;
  else
    supported := false;
    note := 'השוואה אוטומטית מלאה ל־Legacy עבור סוג תפקיד זה תתווסף בזמן הסבת ה־flow הישן. נתוני ה־Dynamic עדיין מוצגים במלואם.';
  end if;

  return jsonb_build_object(
    'mode', 'shadow',
    'supported', supported,
    'legacyRole', job.legacy_role,
    'note', note,
    'dynamic', jsonb_build_object(
      'slots', dynamic_slots,
      'members', dynamic_members,
      'entries', dynamic_entries
    ),
    'legacy', jsonb_build_object(
      'slots', legacy_slots,
      'members', legacy_members,
      'entries', legacy_entries
    ),
    'slotDelta', dynamic_slots - legacy_slots,
    'memberDelta', dynamic_members - legacy_members,
    'entryDelta', dynamic_entries - legacy_entries
  );
end;
$$;


ALTER FUNCTION "public"."compare_dynamic_availability_shadow_to_legacy"("requested_job_type_id" "uuid", "requested_year" integer, "requested_month" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."complete_initial_password_change"() RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  affected_rows integer;
begin
  if auth.uid() is null then
    raise exception 'User is not authenticated';
  end if;

  update public.profiles
  set
    must_change_password = false,
    updated_at = now()
  where id = auth.uid();

  get diagnostics affected_rows = row_count;

  if affected_rows = 0 then
    raise exception 'User profile was not found';
  end if;

  return true;
end;
$$;


ALTER FUNCTION "public"."complete_initial_password_change"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_availability_period"("requested_year" integer, "requested_month" integer, "requested_submission_deadline" timestamp with time zone DEFAULT NULL::timestamp with time zone, "requested_title" "text" DEFAULT NULL::"text", "requested_instructions" "text" DEFAULT NULL::"text") RETURNS TABLE("period_id" "uuid", "created_slots" integer, "period_status" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  current_user_id uuid;
  created_period_id uuid;
  rebuild_result record;
begin
  current_user_id := auth.uid();

  if current_user_id is null then
    raise exception
      'User is not authenticated';
  end if;

  if not exists (
    select 1
    from public.profiles profile
    where profile.id = current_user_id
      and profile.is_active = true
  ) then
    raise exception
      'Authenticated user is not active';
  end if;

  if not exists (
    select 1
    from public.user_permissions permission
    where permission.user_id =
      current_user_id
      and permission.permission_key =
        'availability.manage'
  ) then
    raise exception
      'User is not allowed to manage availability periods';
  end if;

  if requested_year is null
     or requested_year < 2020
     or requested_year > 2200 then
    raise exception
      'Invalid availability year';
  end if;

  if requested_month is null
     or requested_month < 1
     or requested_month > 12 then
    raise exception
      'Invalid availability month';
  end if;

  if exists (
    select 1
    from public.availability_periods period
    where period.year =
      requested_year
      and period.month =
        requested_month
  ) then
    raise exception
      'Availability period already exists for %/%',
      requested_month,
      requested_year;
  end if;

  insert into public.availability_periods (
    year,
    month,
    status,
    title,
    instructions,
    submission_deadline,
    created_by,
    updated_by
  )
  values (
    requested_year,
    requested_month,
    'draft',

    coalesce(
      nullif(
        trim(requested_title),
        ''
      ),

      format(
        'אילוצים לחודש %s/%s',
        lpad(
          requested_month::text,
          2,
          '0'
        ),
        requested_year
      )
    ),

    nullif(
      trim(
        coalesce(
          requested_instructions,
          ''
        )
      ),
      ''
    ),

    requested_submission_deadline,
    current_user_id,
    current_user_id
  )
  returning id
  into created_period_id;

  select *
  into rebuild_result
  from public.rebuild_availability_period_slots(
    created_period_id
  );

  return query
  select
    created_period_id,
    rebuild_result.created_slots,
    'draft'::text;
end;
$$;


ALTER FUNCTION "public"."create_availability_period"("requested_year" integer, "requested_month" integer, "requested_submission_deadline" timestamp with time zone, "requested_title" "text", "requested_instructions" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_driver_availability_period"("requested_year" integer, "requested_month" integer, "requested_title" "text" DEFAULT NULL::"text", "requested_instructions" "text" DEFAULT NULL::"text", "requested_submission_deadline" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  current_user_id uuid;
  user_permissions text[];

  created_period
    public.driver_availability_periods%rowtype;

  first_day date;
  last_day date;

  created_days_count integer;
begin
  current_user_id :=
    auth.uid();

  if current_user_id is null then
    raise exception
      'not authenticated';
  end if;

  user_permissions :=
    coalesce(
      public.get_my_permissions(),
      array[]::text[]
    );

  if not (
    'driver_availability.manage' =
    any(user_permissions)
  ) then
    raise exception
      'not allowed';
  end if;

  if requested_year
    not between 2020 and 2100
  then
    raise exception
      'invalid year';
  end if;

  if requested_month
    not between 1 and 12
  then
    raise exception
      'invalid month';
  end if;

  if exists (
    select 1
    from public.driver_availability_periods
    where year = requested_year
      and month = requested_month
  ) then
    raise exception
      'driver availability period already exists';
  end if;

  first_day :=
    make_date(
      requested_year,
      requested_month,
      1
    );

  last_day :=
    (
      first_day
      + interval '1 month'
      - interval '1 day'
    )::date;

  insert into public.driver_availability_periods (
    year,
    month,
    status,
    title,
    instructions,
    submission_deadline,
    created_by,
    updated_by
  )
  values (
    requested_year,
    requested_month,
    'draft',
    nullif(
      trim(
        coalesce(
          requested_title,
          ''
        )
      ),
      ''
    ),
    nullif(
      trim(
        coalesce(
          requested_instructions,
          ''
        )
      ),
      ''
    ),
    requested_submission_deadline,
    current_user_id,
    current_user_id
  )
  returning *
  into created_period;

  insert into public.driver_availability_days (
    period_id,
    availability_date,
    weekday_number,
    weekday_name,
    sort_order
  )
  select
    created_period.id,

    generated_day::date,

    extract(
      dow
      from generated_day
    )::integer,

    case
      extract(
        dow
        from generated_day
      )::integer

      when 0 then 'ראשון'
      when 1 then 'שני'
      when 2 then 'שלישי'
      when 3 then 'רביעי'
      when 4 then 'חמישי'
      when 5 then 'שישי'
      when 6 then 'שבת'
    end,

    extract(
      day
      from generated_day
    )::integer

  from generate_series(
    first_day::timestamp,
    last_day::timestamp,
    interval '1 day'
  ) as generated_day;

  get diagnostics
    created_days_count =
      row_count;

  return jsonb_build_object(
    'periodId',
      created_period.id,

    'year',
      created_period.year,

    'month',
      created_period.month,

    'status',
      created_period.status,

    'title',
      created_period.title,

    'submissionDeadline',
      created_period.submission_deadline,

    'createdDays',
      created_days_count,

    'createdAt',
      created_period.created_at
  );
end;
$$;


ALTER FUNCTION "public"."create_driver_availability_period"("requested_year" integer, "requested_month" integer, "requested_title" "text", "requested_instructions" "text", "requested_submission_deadline" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."create_driver_availability_period"("requested_year" integer, "requested_month" integer, "requested_title" "text", "requested_instructions" "text", "requested_submission_deadline" timestamp with time zone) IS 'Creates a monthly driver availability period and one full-day availability record for every calendar date. Requires driver_availability.manage.';



CREATE OR REPLACE FUNCTION "public"."create_driver_schedule_draft"("requested_availability_period_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  current_user_id uuid;
  current_permissions text[];

  availability_period
    public.driver_availability_periods%rowtype;

  created_schedule_period
    public.driver_schedule_periods%rowtype;

  availability_day
    public.driver_availability_days%rowtype;

  selected_user_id uuid;
  selected_original_user_id uuid;

  rotation_users uuid[];
  rotation_position integer;
  target_month_start date;
  rotation_history_rows integer := 0;

  selected_last_assignment_date date;
  selected_gap_days integer;
  selected_spacing_warning boolean;
  selected_warning_text text;

  created_days_count integer := 0;
  assigned_days_count integer := 0;
  unassigned_days_count integer := 0;
  warning_count integer := 0;

  active_drivers_count integer := 0;

  assignments_json jsonb :=
    '[]'::jsonb;
begin
  current_user_id :=
    auth.uid();

  if current_user_id is null then
    raise exception
      'not authenticated';
  end if;

  if not exists (
    select 1
    from public.profiles
    where id =
      current_user_id
      and is_active = true
  ) then
    raise exception
      'user not active';
  end if;

  current_permissions :=
    coalesce(
      public.get_my_permissions(),
      array[]::text[]
    );

  if not (
    'driver_schedule.edit' =
      any(current_permissions)
  ) then
    raise exception
      'not allowed';
  end if;

  if requested_availability_period_id
    is null
  then
    raise exception
      'driver availability period id is required';
  end if;

  select *
  into availability_period
  from public.driver_availability_periods
  where id =
    requested_availability_period_id
  for update;

  if not found then
    raise exception
      'driver availability period not found';
  end if;

  if availability_period.status <>
    'closed'
  then
    raise exception
      'driver availability period must be closed before scheduling';
  end if;

  if exists (
    select 1
    from public.driver_schedule_periods
    where availability_period_id =
      availability_period.id
  ) then
    raise exception
      'driver schedule period already exists for this availability period';
  end if;

  if exists (
    select 1
    from public.driver_schedule_periods
    where year =
      availability_period.year
      and month =
        availability_period.month
  ) then
    raise exception
      'driver schedule period already exists for this month';
  end if;

  select
    count(*)::integer
  into active_drivers_count
  from public.profiles
  where role =
    'on_call'::public.user_role
    and is_active = true;

  if active_drivers_count = 0 then
    raise exception
      'no active on-call drivers were found';
  end if;

  if not exists (
    select 1
    from public.driver_availability_days
    where period_id =
      availability_period.id
  ) then
    raise exception
      'driver availability period has no days';
  end if;

  target_month_start :=
    make_date(
      availability_period.year,
      availability_period.month,
      1
    );

  /*
   * זיהוי רוטציית 5 הכוננים מתוך ההיסטוריה.
   *
   * מקור האמת לרוטציה הוא original_user_id.
   * רק כאשר הוא חסר משתמשים ב-assigned_user_id.
   * כך החלפה ידנית חד-פעמית לא מזיזה את המחזור.
   *
   * נבדקות כל 120 הפרמוטציות האפשריות של חמשת
   * הכוננים הנפוצים ב-120 הימים שקדמו לחודש היעד.
   * לכל פרמוטציה מחושב כמה ימי עבר היא מסבירה
   * נכון לפי מחזור קבוע של חמישה ימים.
   */
  with history as (
    select
      day_row.duty_date,
      coalesce(
        day_row.original_user_id,
        day_row.assigned_user_id
      ) as rotation_user_id
    from public.driver_schedule_days day_row
    join public.profiles profile_row
      on profile_row.id =
        coalesce(
          day_row.original_user_id,
          day_row.assigned_user_id
        )
      and profile_row.role =
        'on_call'::public.user_role
      and profile_row.is_active = true
    where day_row.duty_date <
      target_month_start
      and day_row.duty_date >=
        target_month_start -
        interval '120 days'
      and coalesce(
        day_row.original_user_id,
        day_row.assigned_user_id
      ) is not null
  ),
  top_users as (
    select
      history.rotation_user_id as user_id,
      count(*)::integer as appearances
    from history
    group by
      history.rotation_user_id
    order by
      count(*) desc,
      max(history.duty_date) desc
    limit 5
  ),
  permutations as (
    select
      array[
        first_user.user_id,
        second_user.user_id,
        third_user.user_id,
        fourth_user.user_id,
        fifth_user.user_id
      ]::uuid[] as rotation
    from top_users first_user
    cross join top_users second_user
    cross join top_users third_user
    cross join top_users fourth_user
    cross join top_users fifth_user
    where first_user.user_id <>
        second_user.user_id
      and first_user.user_id <>
        third_user.user_id
      and first_user.user_id <>
        fourth_user.user_id
      and first_user.user_id <>
        fifth_user.user_id
      and second_user.user_id <>
        third_user.user_id
      and second_user.user_id <>
        fourth_user.user_id
      and second_user.user_id <>
        fifth_user.user_id
      and third_user.user_id <>
        fourth_user.user_id
      and third_user.user_id <>
        fifth_user.user_id
      and fourth_user.user_id <>
        fifth_user.user_id
  ),
  scored as (
    select
      permutation.rotation,
      sum(
        case
          when history.rotation_user_id =
            permutation.rotation[
              (
                (
                  (
                    history.duty_date -
                    target_month_start
                  ) % 5
                  + 5
                ) % 5
              ) + 1
            ]
          then 1
          else 0
        end
      )::integer as match_count,
      count(*)::integer as compared_days
    from permutations permutation
    cross join history
    group by
      permutation.rotation
    order by
      match_count desc,
      compared_days desc
    limit 1
  )
  select
    scored.rotation,
    scored.compared_days
  into
    rotation_users,
    rotation_history_rows
  from scored;

  /*
   * אם אין מספיק היסטוריה, משלימים רוטציה
   * מחמשת הכוננים הפעילים. ברגע שתצטבר
   * היסטוריה, החודשים הבאים ילמדו את המחזור
   * בפועל אוטומטית.
   */
  if rotation_users is null
     or cardinality(rotation_users) <> 5
  then
    select
      array_agg(
        profile_row.id
        order by
          coalesce(
            profile_row.schedule_name,
            profile_row.display_name
          ),
          profile_row.id
      )
    into rotation_users
    from (
      select profile.id,
             profile.schedule_name,
             profile.display_name
      from public.profiles profile
      where profile.role =
          'on_call'::public.user_role
        and profile.is_active = true
      order by
        coalesce(
          profile.schedule_name,
          profile.display_name
        ),
        profile.id
      limit 5
    ) profile_row;
  end if;

  if rotation_users is null
     or cardinality(rotation_users) <> 5
  then
    raise exception
      'driver rotation requires five active on-call drivers';
  end if;

  insert into public.driver_schedule_periods (
    year,
    month,
    status,
    availability_period_id,
    title,
    created_by,
    updated_by
  )
  values (
    availability_period.year,
    availability_period.month,
    'draft',
    availability_period.id,
    coalesce(
      availability_period.title,
      format(
        'לוח כוננים %s/%s',
        lpad(
          availability_period.month::text,
          2,
          '0'
        ),
        availability_period.year
      )
    ),
    current_user_id,
    current_user_id
  )
  returning *
  into created_schedule_period;

  for availability_day in
    select *
    from public.driver_availability_days
    where period_id =
      availability_period.id
    order by
      availability_date
  loop
    selected_user_id :=
      null;

    selected_original_user_id :=
      null;

    selected_last_assignment_date :=
      null;

    selected_gap_days :=
      null;

    selected_spacing_warning :=
      false;

    selected_warning_text :=
      null;

    /*
     * רוטציה יומית רציפה של חמישה כוננים.
     * היום הראשון בחודש אינו מאפס את המחזור:
     * המיקום מחושב מול target_month_start והפרמוטציה
     * שנלמדה מהחודשים הקודמים.
     */
    rotation_position :=
      (
        (
          availability_day.availability_date -
          target_month_start
        ) % 5
        + 5
      ) % 5
      + 1;

    selected_original_user_id :=
      rotation_users[
        rotation_position
      ];

    /*
     * אילוצים הם שכבת חריגים בלבד.
     * אין חובה להגיש אילוצים:
     * - אין רשומה = אין חסימה.
     * - available = מותר.
     * - unavailable = מחפשים מחליף.
     */
    if not exists (
      select 1
      from public.driver_availability_entries entry
      where entry.period_id =
          availability_period.id
        and entry.day_id =
          availability_day.id
        and entry.user_id =
          selected_original_user_id
        and entry.availability_status =
          'unavailable'
    ) then
      selected_user_id :=
        selected_original_user_id;
    else
      /*
       * הכונן המקורי אינו זמין.
       * בוחרים מחליף בלי לשנות את original_user_id,
       * כדי שהיום הבא ימשיך את המחזור המקורי.
       *
       * סדר העדיפויות:
       * 1. לא סימן unavailable.
       * 2. לא עבד בפועל ביום הקודם.
       * 3. מי שסימן available עדיף על מי שלא הגיש.
       * 4. פחות כוננויות בפועל בחודש.
       * 5. מרווח גדול יותר מהכוננות הקודמת.
       */
      select
        candidate.user_id,
        candidate.last_assignment_date,
        candidate.gap_days
      into
        selected_user_id,
        selected_last_assignment_date,
        selected_gap_days
      from (
        select
          profile.id as user_id,

          availability_entry.availability_status,

          (
            select max(previous_day.duty_date)
            from public.driver_schedule_days previous_day
            where previous_day.assigned_user_id =
                profile.id
              and previous_day.duty_date <
                availability_day.availability_date
          ) as last_assignment_date,

          (
            availability_day.availability_date -
            (
              select max(previous_day.duty_date)
              from public.driver_schedule_days previous_day
              where previous_day.assigned_user_id =
                  profile.id
                and previous_day.duty_date <
                  availability_day.availability_date
            )
          ) as gap_days,

          (
            select count(*)::integer
            from public.driver_schedule_days current_month_day
            where current_month_day.period_id =
                created_schedule_period.id
              and current_month_day.assigned_user_id =
                profile.id
          ) as current_month_assignments

        from public.profiles profile

        left join public.driver_availability_entries
          availability_entry
          on availability_entry.user_id =
            profile.id
          and availability_entry.period_id =
            availability_period.id
          and availability_entry.day_id =
            availability_day.id

        where profile.role =
            'on_call'::public.user_role
          and profile.is_active = true
          and profile.id <>
            selected_original_user_id
          and (
            availability_entry.availability_status
              is null
            or
            availability_entry.availability_status <>
              'unavailable'
          )
          and not exists (
            select 1
            from public.driver_schedule_days previous_actual_day
            where previous_actual_day.period_id =
                created_schedule_period.id
              and previous_actual_day.duty_date =
                availability_day.availability_date -
                1
              and previous_actual_day.assigned_user_id =
                profile.id
          )
      ) candidate

      order by
        case
          when candidate.availability_status =
            'available'
          then 0
          else 1
        end,

        candidate.current_month_assignments,

        case
          when candidate.last_assignment_date
            is null
          then 0
          when candidate.gap_days >= 5
          then 0
          else 1
        end,

        candidate.last_assignment_date
          nulls first,

        candidate.user_id

      limit 1;

      if selected_user_id is null then
        selected_warning_text :=
          'לא נמצא מחליף זמין לכונן המקורי ברוטציה.';

        warning_count :=
          warning_count + 1;
      else
        selected_warning_text :=
          'שיבוץ חלופי עקב אילוץ של הכונן המקורי ברוטציה.';

        warning_count :=
          warning_count + 1;
      end if;
    end if;

    if (
      selected_user_id is not null
      and selected_user_id is distinct from
        selected_original_user_id
      and selected_gap_days between 2 and 4
      and selected_warning_text is null
    ) then
      selected_spacing_warning :=
        true;

      selected_warning_text :=
        format(
          'אזהרה: הכונן שובץ לאחר מרווח של %s ימים בלבד מהכוננות הקודמת.',
          selected_gap_days
        );

      warning_count :=
        warning_count + 1;
    end if;

    insert into public.driver_schedule_days (
      period_id,
      duty_date,
      weekday_number,
      weekday_name,
      original_user_id,
      assigned_user_id,
      assignment_source,
      is_locked,
      notes
    )
    values (
      created_schedule_period.id,
      availability_day.availability_date,
      availability_day.weekday_number,
      availability_day.weekday_name,
      selected_original_user_id,
      selected_user_id,

      case
        when selected_user_id is null
        then null

        else
          'automatic'
            ::public.driver_assignment_source
      end,

      false,
      selected_warning_text
    );

    created_days_count :=
      created_days_count + 1;

    if selected_user_id is null then
      unassigned_days_count :=
        unassigned_days_count + 1;
    else
      assigned_days_count :=
        assigned_days_count + 1;
    end if;
  end loop;

  /*
   * הטריגר מתעד רק עדכונים.
   * לכן השיבוצים הראשוניים נרשמים כאן.
   */
  insert into
    public.driver_schedule_assignment_history (
      schedule_day_id,
      previous_user_id,
      new_user_id,
      change_type,
      changed_by,
      note
    )
  select
    schedule_day.id,
    null,
    schedule_day.assigned_user_id,
    'automatic_assignment'
      ::public.driver_assignment_change_type,
    current_user_id,

    case
      when schedule_day.notes is not null
      then
        'יצירת טיוטה אוטומטית. '
        || schedule_day.notes

      else
        'יצירת טיוטת שיבוץ אוטומטית'
    end

  from public.driver_schedule_days
    schedule_day

  where schedule_day.period_id =
    created_schedule_period.id
    and schedule_day.assigned_user_id
      is not null;

  select
    coalesce(
      jsonb_agg(
        jsonb_build_object(
          'scheduleDayId',
            schedule_day.id,

          'dutyDate',
            schedule_day.duty_date,

          'weekdayNumber',
            schedule_day.weekday_number,

          'weekdayName',
            schedule_day.weekday_name,

          'originalUserId',
            schedule_day.original_user_id,

          'assignedUserId',
            schedule_day.assigned_user_id,

          'assignmentSource',
            schedule_day.assignment_source,

          'isAssigned',
            schedule_day.assigned_user_id
              is not null,

          'notes',
            schedule_day.notes,

          'spacingWarning',
            schedule_day.notes is not null
        )
        order by
          schedule_day.duty_date
      ),
      '[]'::jsonb
    )
  into assignments_json
  from public.driver_schedule_days
    schedule_day
  where schedule_day.period_id =
    created_schedule_period.id;

  return jsonb_build_object(
    'schedulePeriodId',
      created_schedule_period.id,

    'availabilityPeriodId',
      availability_period.id,

    'year',
      created_schedule_period.year,

    'month',
      created_schedule_period.month,

    'status',
      created_schedule_period.status,

    'activeDrivers',
      active_drivers_count,

    'rotationUsers',
      to_jsonb(
        rotation_users
      ),

    'rotationHistoryRows',
      rotation_history_rows,

    'createdDays',
      created_days_count,

    'assignedDays',
      assigned_days_count,

    'unassignedDays',
      unassigned_days_count,

    'warningCount',
      warning_count,

    'hasWarnings',
      (
        warning_count > 0
        or unassigned_days_count > 0
      ),

    'createdAt',
      created_schedule_period.created_at,

    'assignments',
      assignments_json
  );
end;
$$;


ALTER FUNCTION "public"."create_driver_schedule_draft"("requested_availability_period_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."create_driver_schedule_draft"("requested_availability_period_id" "uuid") IS 'Creates an on-call schedule draft from a closed availability period. Availability is mandatory, consecutive-day assignments are prohibited, and the five-day interval is a weighted preference. Actual previous assignments are read from assigned_user_id.';



CREATE OR REPLACE FUNCTION "public"."create_dynamic_assignment_change_notification"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor uuid:=auth.uid();
  publication public.dynamic_schedule_publications%rowtype;
  job public.job_types%rowtype;
  old_user uuid; new_user uuid; shift_date_value date; shift_name_value text;
  start_time_value time; end_time_value time; shift_code_value text;
  notification_id uuid; recipient_count integer:=0; is_swap_change boolean:=false;
begin
  if tg_op='INSERT' and not coalesce(new.manager_edited,false) and new.user_edited_by is null then return new; end if;
  if tg_op='UPDATE' and new.user_id is not distinct from old.user_id then return new; end if;

  select p.* into publication from public.dynamic_schedule_publications p
  where p.id=coalesce(new.publication_id,old.publication_id);
  if publication.id is null or publication.status<>'published' then return coalesce(new,old); end if;
  if publication.year<>extract(year from (now() at time zone 'Asia/Jerusalem'))::integer
     or publication.month<>extract(month from (now() at time zone 'Asia/Jerusalem'))::integer
  then return coalesce(new,old); end if;

  select jt.* into job from public.job_types jt where jt.id=publication.job_type_id and jt.legacy_role is null;
  if job.id is null then return coalesce(new,old); end if;

  old_user:=case when tg_op in ('UPDATE','DELETE') then old.user_id else null end;
  new_user:=case when tg_op in ('UPDATE','INSERT') then new.user_id else null end;
  shift_date_value:=coalesce(new.shift_date,old.shift_date);
  shift_code_value:=coalesce(new.shift_code,old.shift_code);
  start_time_value:=coalesce(new.start_time,old.start_time);
  end_time_value:=coalesce(new.end_time,old.end_time);
  shift_name_value:=public.resolve_dynamic_shift_display_name(
    job.id,shift_date_value,shift_code_value,coalesce(new.shift_name,old.shift_name),
    start_time_value,end_time_value,'משמרת'
  );

  if tg_op='UPDATE' then
    select exists(select 1 from public.dynamic_shift_exchange_requests r
      where r.status='pending_manager' and r.publication_id=publication.id
        and (r.requester_assignment_id=old.id or r.counterparty_assignment_id=old.id))
    into is_swap_change;
    if is_swap_change then return new; end if;
  end if;

  actor:=coalesce(actor,new.user_edited_by,old.user_edited_by);
  if actor is null then return coalesce(new,old); end if;

  insert into public.notifications(type,priority,source,title,body,url,data,created_by,expires_at)
  values(
    'system','important','dynamic_schedule_edit','השיבוץ שלך השתנה',
    concat(job.name,' · ',to_char(shift_date_value,'DD/MM/YYYY'),
      case when start_time_value is not null then concat(' · ',to_char(start_time_value,'HH24:MI'),'–',to_char(end_time_value,'HH24:MI')) else '' end,
      '. השיבוץ המעודכן זמין במערכת.'),
    concat('/my-shifts?jobTypeId=',job.id,'&year=',publication.year,'&month=',publication.month),
    jsonb_build_object('workflow','dynamic_schedule','event','assignment_changed','actorUserId',actor,
      'publicationId',publication.id,'jobTypeId',job.id,'jobTypeName',job.name,
      'assignmentId',coalesce(new.id,old.id),'shiftDate',shift_date_value,'shiftName',shift_name_value,
      'startTime',start_time_value,'endTime',end_time_value,'oldUserId',old_user,'newUserId',new_user,'pushPending',true),
    actor,now()+interval '90 days'
  ) returning id into notification_id;

  insert into public.notification_recipients(notification_id,user_id)
  select notification_id,candidate.user_id
  from (select old_user user_id union select new_user user_id) candidate
  join public.profiles p on p.id=candidate.user_id and p.is_active=true
  where candidate.user_id is not null and candidate.user_id<>actor;
  get diagnostics recipient_count=row_count;
  if recipient_count=0 then delete from public.notifications where id=notification_id; end if;
  return coalesce(new,old);
end;
$$;


ALTER FUNCTION "public"."create_dynamic_assignment_change_notification"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_dynamic_availability_shadow_period"("requested_job_type_id" "uuid", "requested_year" integer, "requested_month" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  current_user_id uuid:=auth.uid();
  target_job public.job_types%rowtype;
  target_period_id uuid;
  effective_config jsonb;
  created_slots integer:=0;
begin
  if current_user_id is null then raise exception 'not authenticated'; end if;
  if not public.has_dynamic_job_type_permission('availability.open_period', requested_job_type_id, current_user_id) then
    raise exception 'not allowed';
  end if;
  if requested_year not between 2020 and 2100 or requested_month not between 1 and 12 then
    raise exception 'invalid year or month';
  end if;

  select * into target_job from public.job_types where id=requested_job_type_id;
  if target_job.id is null then raise exception 'job type not found'; end if;

  select m.source_snapshot into effective_config
  from public.job_type_schedule_materializations m
  where m.job_type_id=target_job.id
    and m.effective_month<=make_date(requested_year,requested_month,1)
  order by m.effective_month desc
  limit 1;

  if effective_config is null then
    raise exception 'no effective role configuration exists for this month';
  end if;

  if coalesce((effective_config#>>'{availabilityConfig,enabled}')::boolean,
              (target_job.availability_config->>'enabled')::boolean,
              false) is not true then
    raise exception 'availability is disabled for job type';
  end if;

  insert into public.dynamic_availability_periods(
    schedule_group_id,job_type_id,year,month,title,status,config_snapshot,source,created_by
  ) values(
    target_job.schedule_group_id,
    target_job.id,
    requested_year,
    requested_month,
    target_job.name || ' · ' || requested_month || '/' || requested_year,
    'shadow',
    coalesce(effective_config->'availabilityConfig',target_job.availability_config,'{}'::jsonb),
    'dynamic_role',
    current_user_id
  )
  on conflict(job_type_id,year,month) do update set
    schedule_group_id=excluded.schedule_group_id,
    config_snapshot=excluded.config_snapshot,
    updated_at=now()
  returning id into target_period_id;

  created_slots := public.materialize_dynamic_availability_period_slots(target_period_id);

  return jsonb_build_object(
    'periodId',target_period_id,
    'createdSlots',created_slots,
    'slotCount',(select count(*) from public.dynamic_availability_slots s where s.period_id=target_period_id),
    'mode','dynamic_role'
  );
end;
$$;


ALTER FUNCTION "public"."create_dynamic_availability_shadow_period"("requested_job_type_id" "uuid", "requested_year" integer, "requested_month" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_dynamic_exchange_approval_notification"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor uuid;
  job_name text;
  notification_id uuid;
  recipient_count integer := 0;
begin
  if tg_op <> 'UPDATE'
     or new.status <> 'approved'
     or old.status = 'approved' then
    return new;
  end if;

  actor := coalesce(new.manager_user_id, auth.uid());
  if actor is null then return new; end if;

  select jt.name into job_name
  from public.job_types jt
  where jt.id = new.job_type_id
    and jt.legacy_role is null;

  if job_name is null then return new; end if;

  insert into public.notifications(
    type, priority, source, title, body, url, data, created_by, expires_at
  ) values (
    'shift_swap',
    'important',
    'shift_swap',
    'חילוף המשמרות אושר',
    concat('החילוף בתפקיד ', job_name, ' אושר סופית והשיבוץ עודכן.'),
    '/shift-swaps',
    jsonb_build_object(
      'workflow','shift_swap',
      'event','manager_approved',
      'actorUserId',actor,
      'shiftSwapRequestId',new.id,
      'jobTypeId',new.job_type_id,
      'publicationId',new.publication_id,
      'requesterUserId',new.requester_user_id,
      'counterpartyUserId',new.counterparty_user_id,
      'pushPending',true
    ),
    actor,
    now() + interval '90 days'
  ) returning id into notification_id;

  insert into public.notification_recipients(notification_id,user_id)
  select notification_id, candidate.user_id
  from (
    select new.requester_user_id as user_id
    union
    select new.counterparty_user_id as user_id
  ) candidate
  join public.profiles p on p.id = candidate.user_id and p.is_active = true
  where candidate.user_id is not null
    and candidate.user_id <> actor;

  get diagnostics recipient_count = row_count;

  if recipient_count = 0 then
    delete from public.notifications where id = notification_id;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."create_dynamic_exchange_approval_notification"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_dynamic_monthly_rotation_draft"("requested_job_type_id" "uuid", "requested_year" integer, "requested_month" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_actor uuid:=auth.uid();
  v_job public.job_types%rowtype;
  v_period public.dynamic_availability_periods%rowtype;
  v_material public.job_type_schedule_materializations%rowtype;
  v_draft_id uuid;
  v_rotation uuid[];
  v_anchor date;
  v_source text;
  v_member_count integer:=0;
  v_rotation_count integer:=0;
  v_slot record;
  v_original uuid;
  v_assigned uuid;
  v_status text;
  v_index integer;
  v_unfilled integer:=0;
  v_substitutions integer:=0;
  v_created integer:=0;
  v_candidate record;
  v_history_rows integer:=0;
begin
  if v_actor is null then raise exception 'not authenticated'; end if;
  if not public.has_dynamic_job_type_permission('rotation.generate', requested_job_type_id, v_actor) then
    raise exception 'not allowed';
  end if;
  if requested_month not between 1 and 12 then raise exception 'invalid month'; end if;

  select * into v_job from public.job_types where id=requested_job_type_id;
  if v_job.id is null then raise exception 'job type not found'; end if;

  select * into v_material
  from public.job_type_schedule_materializations m
  where m.job_type_id=v_job.id and m.effective_month=make_date(requested_year,requested_month,1);

  if coalesce(v_material.scheduling_strategy,v_job.scheduling_strategy,'availability_optimizer') <> 'monthly_rotation_constraints' then
    raise exception 'job type is not configured for monthly rotation';
  end if;
  if coalesce(v_material.work_mode, v_job.scheduling_config#>>'{shiftPattern,workMode}') <> 'on_call_daily' then
    raise exception 'monthly rotation currently requires daily on-call work mode';
  end if;

  select * into v_period from public.dynamic_availability_periods
  where job_type_id=v_job.id and year=requested_year and month=requested_month;
  if v_period.id is null then raise exception 'dynamic availability period not found'; end if;
  if v_period.status <> 'closed' then raise exception 'availability period must be closed before scheduling'; end if;

  select count(*)::integer into v_member_count
  from public.job_type_memberships m join public.profiles p on p.id=m.user_id and p.is_active=true
  where m.job_type_id=v_job.id;
  if v_member_count < 2 then raise exception 'monthly rotation requires at least two active role members'; end if;

  select rotation_user_ids,anchor_date,source into v_rotation,v_anchor,v_source
  from public.dynamic_job_type_rotation_state where job_type_id=v_job.id for update;

  if v_rotation is null then
    -- Build candidate cycles from every historical contiguous N-row window whose
    -- original users are all distinct, then score each candidate against all imported
    -- original assignments. This is done once and persisted.
    with hist as (
      select ha.work_date,coalesce(ha.original_user_id,ha.assigned_user_id) user_id,
             row_number() over(order by ha.work_date,ha.id) rn
      from public.dynamic_historical_assignments ha
      join public.dynamic_historical_periods hp on hp.id=ha.historical_period_id
      join public.job_type_memberships jm on jm.job_type_id=hp.job_type_id and jm.user_id=coalesce(ha.original_user_id,ha.assigned_user_id)
      where hp.job_type_id=v_job.id and ha.work_date is not null and coalesce(ha.original_user_id,ha.assigned_user_id) is not null
    ), candidates as (
      select h0.work_date anchor_date,
             array_agg(h.user_id order by h.rn) rotation
      from hist h0 join hist h on h.rn between h0.rn and h0.rn+v_member_count-1
      group by h0.rn,h0.work_date
      having count(*)=v_member_count and count(distinct h.user_id)=v_member_count
    ), scored as (
      select c.anchor_date,c.rotation,
             count(*) filter(where h.user_id=c.rotation[((h.work_date-c.anchor_date)%v_member_count+v_member_count)%v_member_count+1])::integer matches,
             count(*)::integer compared
      from candidates c cross join hist h
      group by c.anchor_date,c.rotation
      order by matches desc,compared desc,c.anchor_date desc
      limit 1
    )
    select rotation,anchor_date,'historical_best_window',compared
      into v_rotation,v_anchor,v_source,v_history_rows from scored;

    if v_rotation is null or cardinality(v_rotation)<>v_member_count then
      select array_agg(x.user_id order by x.display_name,x.user_id),make_date(requested_year,requested_month,1),'membership_fallback'
      into v_rotation,v_anchor,v_source
      from (
        select m.user_id,coalesce(p.schedule_name,p.display_name,p.email,m.user_id::text) display_name
        from public.job_type_memberships m join public.profiles p on p.id=m.user_id and p.is_active=true
        where m.job_type_id=v_job.id
      ) x;
    end if;

    insert into public.dynamic_job_type_rotation_state(job_type_id,rotation_user_ids,anchor_date,source,source_metadata,created_by)
    values(v_job.id,v_rotation,v_anchor,v_source,jsonb_build_object('historicalRowsCompared',v_history_rows,'memberCount',v_member_count),v_actor);
  end if;

  v_rotation_count:=cardinality(v_rotation);
  if v_rotation_count<>v_member_count then
    raise exception 'saved rotation has % members but role currently has % active members; rotation membership changes require an explicit rotation update',v_rotation_count,v_member_count;
  end if;

  insert into public.dynamic_schedule_shadow_drafts(job_type_id,availability_period_id,year,month,status,feasibility_snapshot,rules_snapshot,metrics,created_by)
  values(v_job.id,v_period.id,requested_year,requested_month,'shadow','{}'::jsonb,
    jsonb_build_object('strategy','monthly_rotation_constraints','rotationUserIds',to_jsonb(v_rotation),'anchorDate',v_anchor,'rotationSource',v_source),
    '{}'::jsonb,v_actor) returning id into v_draft_id;

  for v_slot in
    select s.* from public.dynamic_availability_slots s where s.period_id=v_period.id order by s.shift_date,s.start_time,s.id
  loop
    v_index:=((v_slot.shift_date-v_anchor)%v_rotation_count+v_rotation_count)%v_rotation_count+1;
    v_original:=v_rotation[v_index];
    v_assigned:=null;

    select e.availability_status into v_status
    from public.dynamic_availability_submissions sub
    join public.dynamic_availability_entries e on e.submission_id=sub.id and e.slot_id=v_slot.id
    where sub.period_id=v_period.id and sub.user_id=v_original
    order by case when sub.status='submitted' then 0 else 1 end,sub.updated_at desc limit 1;

    if coalesce(v_status,'available') <> 'unavailable' then
      v_assigned:=v_original;
    else
      select c.* into v_candidate from (
        select m.user_id,e.availability_status,
          (select count(*) from public.dynamic_schedule_shadow_assignments a where a.draft_id=v_draft_id and a.user_id=m.user_id)::integer month_count,
          exists(
            select 1 from public.dynamic_schedule_shadow_assignments pa
            join public.dynamic_availability_slots ps on ps.id=pa.slot_id
            where pa.draft_id=v_draft_id and pa.user_id=m.user_id and ps.shift_date=v_slot.shift_date-1
          ) worked_previous_day
        from public.job_type_memberships m
        join public.profiles p on p.id=m.user_id and p.is_active=true
        left join public.dynamic_availability_submissions sub on sub.period_id=v_period.id and sub.user_id=m.user_id
        left join public.dynamic_availability_entries e on e.submission_id=sub.id and e.slot_id=v_slot.id
        where m.job_type_id=v_job.id and m.user_id<>v_original and coalesce(e.availability_status,'available')<>'unavailable'
      ) c
      order by c.worked_previous_day asc,
        case c.availability_status when 'preferred' then 0 when 'available' then 1 when null then 2 when 'avoid' then 3 else 2 end,
        c.month_count asc,c.user_id
      limit 1;
      v_assigned:=v_candidate.user_id;
      if v_assigned is not null then v_substitutions:=v_substitutions+1; end if;
    end if;

    if v_assigned is null then
      v_unfilled:=v_unfilled+greatest(v_slot.min_workers,1);
    else
      insert into public.dynamic_schedule_shadow_assignments(
        draft_id,slot_id,user_id,original_user_id,engine_user_id,assignment_tier,score,reasons
      ) values(
        v_draft_id,v_slot.id,v_assigned,v_original,v_assigned,'required',0,
        jsonb_build_array(
          'סבב חודשי קבוע',
          case when v_assigned=v_original then 'העובד המקורי ברוטציה' else 'מחליף עקב אילוץ של העובד המקורי' end
        )
      );
      v_created:=v_created+1;
    end if;
  end loop;

  update public.dynamic_schedule_shadow_drafts
  set status=case when v_unfilled=0 then 'generated' else 'incomplete' end,
      metrics=jsonb_build_object(
        'requiredAssignmentsCreated',v_created,'optionalAssignmentsCreated',0,
        'unfilledRequiredPositions',v_unfilled,'effectiveUnfilledRequiredPositions',v_unfilled,
        'rotationSubstitutions',v_substitutions,'algorithm','persistent_daily_rotation_v1',
        'rotationUserIds',to_jsonb(v_rotation),'rotationAnchorDate',v_anchor,'rotationSource',v_source,
        'originalRotationPreserved',true
      ),updated_at=now()
  where id=v_draft_id;

  insert into public.audit_logs(action,actor_user_id,entity_type,entity_id,summary,metadata)
  values('system_event',v_actor,'dynamic_schedule_draft',v_draft_id,'טיוטת סבב חודשי דינמי נוצרה',
    jsonb_build_object('job_type_id',v_job.id,'year',requested_year,'month',requested_month,'rotation_source',v_source,'substitutions',v_substitutions,'unfilled',v_unfilled));

  return jsonb_build_object(
    'draftId',v_draft_id,'mode','monthly_rotation','requiredAssignmentsCreated',v_created,
    'optionalAssignmentsCreated',0,'unfilledRequiredPositions',v_unfilled,
    'algorithm','persistent_daily_rotation_v1','rotationUserIds',to_jsonb(v_rotation),
    'rotationAnchorDate',v_anchor,'rotationSource',v_source,'rotationSubstitutions',v_substitutions,
    'originalRotationPreserved',true
  );
end;$$;


ALTER FUNCTION "public"."create_dynamic_monthly_rotation_draft"("requested_job_type_id" "uuid", "requested_year" integer, "requested_month" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_dynamic_schedule_publication_notification"("requested_publication_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  current_user_id uuid := auth.uid();
  target_publication public.dynamic_schedule_publications%rowtype;
  target_job public.job_types%rowtype;
  notification_id uuid;
  recipient_count integer := 0;
  notification_title text;
  notification_body text;
  notification_url text;
begin
  if current_user_id is null then
    raise exception 'not authenticated';
  end if;

  if not exists (
    select 1 from public.profiles p
    where p.id = current_user_id and p.is_active = true
  ) then
    raise exception 'user not active';
  end if;

  select * into target_publication
  from public.dynamic_schedule_publications p
  where p.id = requested_publication_id;

  if target_publication.id is null then
    raise exception 'publication not found';
  end if;

  if target_publication.status <> 'published' then
    raise exception 'schedule is not published';
  end if;

  if not public.has_dynamic_job_type_permission(
    'schedule.publish',
    target_publication.job_type_id,
    current_user_id
  ) then
    raise exception 'not allowed';
  end if;

  select * into target_job
  from public.job_types jt
  where jt.id = target_publication.job_type_id
    and jt.is_active = true
    and jt.legacy_role is null;

  if target_job.id is null then
    raise exception 'dynamic job type not found';
  end if;

  notification_title := concat('פורסם לוח ', target_job.name);
  notification_body := concat(
    'פורסם לוח ', target_job.name,
    ' לחודש ', lpad(target_publication.month::text, 2, '0'), '/', target_publication.year,
    '. ניתן לצפות בשיבוץ המעודכן במערכת.'
  );
  notification_url := concat(
    '/my-shifts?jobTypeId=', target_job.id,
    '&year=', target_publication.year,
    '&month=', target_publication.month
  );

  insert into public.notifications (
    type,
    priority,
    source,
    title,
    body,
    url,
    data,
    created_by,
    expires_at
  ) values (
    'schedule_published',
    'important',
    'dynamic_schedule_publish',
    notification_title,
    notification_body,
    notification_url,
    jsonb_build_object(
      'workflow', 'dynamic_schedule',
      'event', 'publication_published',
      'publicationId', target_publication.id,
      'jobTypeId', target_job.id,
      'jobTypeName', target_job.name,
      'year', target_publication.year,
      'month', target_publication.month
    ),
    current_user_id,
    now() + interval '90 days'
  )
  returning id into notification_id;

  insert into public.notification_recipients (
    notification_id,
    user_id
  )
  select distinct
    notification_id,
    m.user_id
  from public.job_type_memberships m
  join public.profiles p on p.id = m.user_id
  where m.job_type_id = target_job.id
    and p.is_active = true;

  get diagnostics recipient_count = row_count;

  if recipient_count = 0 then
    delete from public.notifications n where n.id = notification_id;
    return jsonb_build_object(
      'notificationId', null,
      'recipientCount', 0
    );
  end if;

  insert into public.audit_logs(
    action, actor_user_id, entity_type, entity_id, summary, metadata
  ) values (
    'system_event',
    current_user_id,
    'dynamic_schedule_publication',
    target_publication.id,
    'נשלחה התראת פרסום לוח דינמי',
    jsonb_build_object(
      'job_type_id', target_job.id,
      'notification_id', notification_id,
      'recipient_count', recipient_count,
      'year', target_publication.year,
      'month', target_publication.month
    )
  );

  return jsonb_build_object(
    'notificationId', notification_id,
    'recipientCount', recipient_count
  );
end;
$$;


ALTER FUNCTION "public"."create_dynamic_schedule_publication_notification"("requested_publication_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_dynamic_schedule_shadow_draft"("requested_job_type_id" "uuid", "requested_year" integer, "requested_month" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  current_user_id uuid := auth.uid();
  job public.job_types%rowtype;
  period public.dynamic_availability_periods%rowtype;
  v_draft_id uuid;
  feasibility jsonb;
  sl record;
  chosen_user uuid;
  chosen_score numeric;
  chosen_status text;
  chosen_assigned integer;
  chosen_min integer;
  chosen_target integer;
  chosen_max integer;
  assigned_required integer := 0;
  assigned_optional integer := 0;
  unfilled integer := 0;
  avoid_assignments integer := 0;
  above_target_assignments integer := 0;
  no_consecutive boolean;
  max_per_day integer;
  min_rest integer;
  max_hard boolean;
  coverage_weight numeric;
  fairness_weight numeric;
  preference_weight numeric;
  optional_weight numeric;
  blocked_slots uuid[] := array[]::uuid[];
  remaining_positions integer;
begin
  if current_user_id is null then raise exception 'not authenticated'; end if;
  if not public.has_dynamic_job_type_permission('schedule.create_draft', requested_job_type_id, current_user_id) then raise exception 'not allowed'; end if;
  select * into job from public.job_types where id=requested_job_type_id;
  if job.id is null then raise exception 'job type not found'; end if;
  select * into period from public.dynamic_availability_periods where job_type_id=job.id and year=requested_year and month=requested_month;
  if period.id is null then raise exception 'shadow availability period not found'; end if;

  feasibility := public.analyze_dynamic_schedule_feasibility(job.id,requested_year,requested_month);
  no_consecutive := coalesce((job.scheduling_config#>>'{rules,noConsecutive,enabled}')::boolean,true);
  max_per_day := case when coalesce((job.scheduling_config#>>'{rules,maxShiftsPerDay,enabled}')::boolean,true) then coalesce((job.scheduling_config#>>'{rules,maxShiftsPerDay,value}')::integer,1) else 999 end;
  min_rest := case when coalesce((job.scheduling_config#>>'{rules,minimumRestMinutes,enabled}')::boolean,false) then coalesce((job.scheduling_config#>>'{rules,minimumRestMinutes,value}')::integer,0) else 0 end;
  max_hard := coalesce(job.scheduling_config->>'maximumMode','hard')='hard';
  coverage_weight := coalesce((job.scheduling_config#>>'{weights,coverage}')::numeric,1000);
  fairness_weight := coalesce((job.scheduling_config#>>'{weights,proportionalFairness}')::numeric,100);
  preference_weight := coalesce((job.scheduling_config#>>'{weights,preference}')::numeric,30);
  optional_weight := coalesce((job.scheduling_config#>>'{weights,targetOptional}')::numeric,15);

  insert into public.dynamic_schedule_shadow_drafts(job_type_id,availability_period_id,year,month,status,feasibility_snapshot,rules_snapshot,created_by)
  values(job.id,period.id,requested_year,requested_month,'shadow',feasibility,job.scheduling_config,current_user_id)
  returning id into v_draft_id;

  insert into public.dynamic_schedule_shadow_targets(
    draft_id,user_id,requested_min,requested_target,requested_max,available_slots,
    proportional_weight,proportional_target,employment_scope,employment_factor
  )
  select
    v_draft_id,(m->>'userId')::uuid,(m->>'minimum')::integer,(m->>'target')::integer,
    nullif(m->>'maximum','')::integer,(m->>'availableSlots')::integer,
    coalesce((m->>'weight')::numeric,1),coalesce((m->>'proportionalTarget')::numeric,0),
    nullif(m->>'employmentScope',''),coalesce((m->>'employmentFactor')::numeric,1)
  from jsonb_array_elements(coalesce(feasibility->'members','[]'::jsonb)) m;

  loop
    select candidate_slot.* into sl
    from public.dynamic_availability_slots candidate_slot
    where candidate_slot.period_id=period.id
      and not (candidate_slot.id = any(blocked_slots))
      and (select count(*) from public.dynamic_schedule_shadow_assignments a
           where a.draft_id=v_draft_id and a.slot_id=candidate_slot.id and a.assignment_tier='required') < candidate_slot.min_workers
    order by
      (select count(*) from public.dynamic_schedule_shadow_targets t
       join public.dynamic_availability_submissions sub on sub.period_id=period.id and sub.user_id=t.user_id
       join public.dynamic_availability_entries e on e.submission_id=sub.id and e.slot_id=candidate_slot.id and e.availability_status in ('preferred','available','avoid')
       where t.draft_id=v_draft_id
         and (not max_hard or t.requested_max is null or t.assigned_count<t.requested_max)
         and public.dynamic_shadow_candidate_allowed(v_draft_id,t.user_id,candidate_slot.id,max_per_day,no_consecutive,min_rest)) asc,
      candidate_slot.shift_date,candidate_slot.start_time,candidate_slot.id
    limit 1;
    exit when not found;

    chosen_user:=null; chosen_score:=null; chosen_status:=null; chosen_assigned:=null; chosen_min:=null; chosen_target:=null; chosen_max:=null;

    select c.user_id,c.score,c.availability_status,c.assigned_count,c.requested_min,c.requested_target,c.requested_max
    into chosen_user,chosen_score,chosen_status,chosen_assigned,chosen_min,chosen_target,chosen_max
    from (
      select t.user_id,t.assigned_count,t.requested_min,t.requested_target,t.requested_max,e.availability_status,
        coverage_weight
        + greatest(t.requested_min-t.assigned_count,0)*fairness_weight*2
        -- Employment factor changes balancing pressure only. It never removes eligibility.
        + greatest(t.requested_target-t.assigned_count,0)*fairness_weight*t.employment_factor
        + greatest(t.proportional_target-t.assigned_count,0)*fairness_weight*0.5
        + case e.availability_status when 'preferred' then preference_weight when 'available' then 0 when 'avoid' then -preference_weight*4 else -1000000 end
        + case when not max_hard and t.requested_max is not null and t.assigned_count>=t.requested_max
            then -fairness_weight*4*(t.assigned_count-t.requested_max+1) else 0 end as score
      from public.dynamic_schedule_shadow_targets t
      join public.dynamic_availability_submissions sub on sub.period_id=period.id and sub.user_id=t.user_id
      join public.dynamic_availability_entries e on e.submission_id=sub.id and e.slot_id=sl.id and e.availability_status in ('preferred','available','avoid')
      where t.draft_id=v_draft_id
        and (not max_hard or t.requested_max is null or t.assigned_count<t.requested_max)
        and public.dynamic_shadow_candidate_allowed(v_draft_id,t.user_id,sl.id,max_per_day,no_consecutive,min_rest)
      order by score desc,t.assigned_count asc,t.user_id limit 1
    ) c;

    if chosen_user is null then
      select greatest(sl.min_workers-count(*),0) into remaining_positions
      from public.dynamic_schedule_shadow_assignments a
      where a.draft_id=v_draft_id and a.slot_id=sl.id and a.assignment_tier='required';
      unfilled:=unfilled+remaining_positions;
      blocked_slots:=array_append(blocked_slots,sl.id);
      continue;
    end if;

    insert into public.dynamic_schedule_shadow_assignments(draft_id,slot_id,user_id,assignment_tier,score,reasons)
    values(v_draft_id,sl.id,chosen_user,'required',chosen_score,jsonb_build_array(
      'כיסוי משמרת','קדימות למשמרות עם מעט מועמדים',
      case when chosen_assigned<coalesce(chosen_min,0) then 'השלמת מינימום חודשי'
           when chosen_assigned<coalesce(chosen_target,0) then 'איזון לכיוון היעד החודשי'
           else 'העובד נשאר מועמד גם לאחר הגעה ליעד' end,
      case chosen_status when 'preferred' then 'מעדיף' when 'available' then 'זמין' when 'avoid' then 'מעדיף שלא — נבחר רק לאחר שקלול עדיפות נמוכה' else chosen_status end
    ));
    update public.dynamic_schedule_shadow_targets t set assigned_count=t.assigned_count+1
    where t.draft_id=v_draft_id and t.user_id=chosen_user;
    if chosen_status='avoid' then avoid_assignments:=avoid_assignments+1; end if;
    if chosen_assigned>=coalesce(chosen_target,0) then above_target_assignments:=above_target_assignments+1; end if;
    assigned_required:=assigned_required+1;
  end loop;

  for sl in select * from public.dynamic_availability_slots s where s.period_id=period.id and s.target_workers>s.min_workers order by s.shift_date,s.start_time,s.id loop
    loop
      exit when (select count(*) from public.dynamic_schedule_shadow_assignments a where a.draft_id=v_draft_id and a.slot_id=sl.id)>=sl.target_workers;
      chosen_user:=null; chosen_score:=null; chosen_status:=null; chosen_assigned:=null; chosen_target:=null;
      select c.user_id,c.score,c.availability_status,c.assigned_count,c.requested_target
      into chosen_user,chosen_score,chosen_status,chosen_assigned,chosen_target
      from (
        select t.user_id,t.assigned_count,t.requested_target,e.availability_status,
          optional_weight
          + greatest(t.requested_target-t.assigned_count,0)*fairness_weight*t.employment_factor
          + greatest(t.proportional_target-t.assigned_count,0)*fairness_weight*0.5
          + case when e.availability_status='preferred' then preference_weight else 0 end
          + case when not max_hard and t.requested_max is not null and t.assigned_count>=t.requested_max
              then -fairness_weight*4*(t.assigned_count-t.requested_max+1) else 0 end as score
        from public.dynamic_schedule_shadow_targets t
        join public.dynamic_availability_submissions sub on sub.period_id=period.id and sub.user_id=t.user_id
        join public.dynamic_availability_entries e on e.submission_id=sub.id and e.slot_id=sl.id and e.availability_status in ('preferred','available')
        where t.draft_id=v_draft_id
          and (not max_hard or t.requested_max is null or t.assigned_count<t.requested_max)
          and public.dynamic_shadow_candidate_allowed(v_draft_id,t.user_id,sl.id,max_per_day,no_consecutive,min_rest)
        order by score desc,t.assigned_count asc,t.user_id limit 1
      ) c;
      exit when chosen_user is null;
      insert into public.dynamic_schedule_shadow_assignments(draft_id,slot_id,user_id,assignment_tier,score,reasons)
      values(v_draft_id,sl.id,chosen_user,'target_optional',chosen_score,jsonb_build_array(
        'עובד נוסף עד יעד האיוש למשמרת',
        case when chosen_assigned<coalesce(chosen_target,0) then 'איזון לכיוון היעד החודשי' else 'היעד החודשי הוא העדפה ולא חסם' end,
        case when chosen_status='preferred' then 'מעדיף' else 'זמין' end
      ));
      update public.dynamic_schedule_shadow_targets t set assigned_count=t.assigned_count+1
      where t.draft_id=v_draft_id and t.user_id=chosen_user;
      if chosen_assigned>=coalesce(chosen_target,0) then above_target_assignments:=above_target_assignments+1; end if;
      assigned_optional:=assigned_optional+1;
    end loop;
  end loop;

  update public.dynamic_schedule_shadow_drafts d
  set status=case when unfilled=0 then 'generated' else 'incomplete' end,
      metrics=jsonb_build_object(
        'requiredAssignmentsCreated',assigned_required,'optionalAssignmentsCreated',assigned_optional,
        'unfilledRequiredPositions',unfilled,'avoidAssignments',avoid_assignments,
        'aboveTargetAssignments',above_target_assignments,
        'algorithm','scarcity_first_soft_target_employment_v2_1','wholePeriodScarcity',true,
        'targetIsEligibilityCutoff',false,'employmentScopeIsEligibilityCutoff',false,
        'partTimeRecommendationFactor',0.5
      ),updated_at=now()
  where d.id=v_draft_id;

  return jsonb_build_object(
    'draftId',v_draft_id,'mode','shadow','requiredAssignmentsCreated',assigned_required,
    'optionalAssignmentsCreated',assigned_optional,'unfilledRequiredPositions',unfilled,
    'avoidAssignments',avoid_assignments,'aboveTargetAssignments',above_target_assignments,
    'algorithm','scarcity_first_soft_target_employment_v2_1','wholePeriodScarcity',true,
    'targetIsEligibilityCutoff',false,'employmentScopeIsEligibilityCutoff',false,
    'partTimeRecommendationFactor',0.5,'feasibility',feasibility
  );
end;
$$;


ALTER FUNCTION "public"."create_dynamic_schedule_shadow_draft"("requested_job_type_id" "uuid", "requested_year" integer, "requested_month" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_dynamic_shift_exchange_request"("requested_swap_type" "text", "requested_requester_assignment_id" "uuid", "requested_counterparty_user_id" "uuid", "requested_counterparty_assignment_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  current_user_id uuid := auth.uid();
  requester_assignment public.dynamic_schedule_published_assignments%rowtype;
  counter_assignment public.dynamic_schedule_published_assignments%rowtype;
  target_publication public.dynamic_schedule_publications%rowtype;
  target_job public.job_types%rowtype;
  created_request public.dynamic_shift_exchange_requests%rowtype;
  exchange_enabled boolean;
begin
  if current_user_id is null then raise exception 'not authenticated'; end if;
  if requested_swap_type not in ('one_way','two_way') then raise exception 'סוג ההחלפה אינו תקין.'; end if;
  if requested_counterparty_user_id=current_user_id then raise exception 'לא ניתן להגיש בקשה מול עצמך.'; end if;

  select * into requester_assignment from public.dynamic_schedule_published_assignments
  where id=requested_requester_assignment_id for update;
  if requester_assignment.id is null or requester_assignment.user_id<>current_user_id then raise exception 'המשמרת שנבחרה אינה משובצת אליך.'; end if;
  if public.dynamic_assignment_starts_at(requester_assignment)<=now() then raise exception 'לא ניתן להחליף משמרת שכבר התחילה.'; end if;

  select * into target_publication from public.dynamic_schedule_publications where id=requester_assignment.publication_id;
  select * into target_job from public.job_types where id=target_publication.job_type_id;
  exchange_enabled := (
    exists (select 1 from public.job_type_schedule_materializations mat
      where mat.job_type_id=target_publication.job_type_id
        and mat.effective_month=make_date(target_publication.year,target_publication.month,1)
        and mat.schedule_change_mode='shift_exchange')
    or coalesce(target_publication.config_snapshot #>> '{jobType,scheduleChangeMode}', 'none') = 'shift_exchange'
    or coalesce(target_job.scheduling_config #>> '{scheduleChangeMode}', 'none') = 'shift_exchange'
  );
  if target_publication.status<>'published' or not exchange_enabled then raise exception 'חילופי משמרות אינם פעילים בלוח זה.'; end if;
  if make_date(target_publication.year,target_publication.month,1) not in (
    date_trunc('month',(now() at time zone 'Asia/Jerusalem')::date)::date,
    (date_trunc('month',(now() at time zone 'Asia/Jerusalem')::date)+interval '1 month')::date
  ) then raise exception 'ניתן להגיש בקשות רק לחודש הנוכחי או לחודש הבא שפורסם.'; end if;

  if not exists(select 1 from public.job_type_memberships m join public.profiles p on p.id=m.user_id and p.is_active=true
    where m.job_type_id=target_publication.job_type_id and m.user_id=requested_counterparty_user_id) then
    raise exception 'העובד שנבחר אינו חבר פעיל בתפקיד.';
  end if;

  if requested_swap_type='two_way' then
    if requested_counterparty_assignment_id is null then raise exception 'יש לבחור משמרת נגדית.'; end if;
    select * into counter_assignment from public.dynamic_schedule_published_assignments
    where id=requested_counterparty_assignment_id and publication_id=target_publication.id for update;
    if counter_assignment.id is null or counter_assignment.user_id<>requested_counterparty_user_id then raise exception 'המשמרת הנגדית אינה משובצת לעובד שנבחר.'; end if;
    if public.dynamic_assignment_starts_at(counter_assignment)<=now() then raise exception 'המשמרת הנגדית כבר התחילה.'; end if;
  elsif requested_counterparty_assignment_id is not null then
    raise exception 'בהחלפה חד-כיוונית אין לבחור משמרת נגדית.';
  end if;

  if exists(select 1 from public.dynamic_shift_exchange_requests r
    where r.status in ('pending_counterparty','pending_manager') and (
      r.requester_assignment_id=requested_requester_assignment_id or r.counterparty_assignment_id=requested_requester_assignment_id
      or (requested_counterparty_assignment_id is not null and (r.requester_assignment_id=requested_counterparty_assignment_id or r.counterparty_assignment_id=requested_counterparty_assignment_id))
    )) then raise exception 'כבר קיימת בקשת החלפה פעילה עבור אחת המשמרות.'; end if;

  if public.dynamic_user_has_overlap(target_publication.id, requested_counterparty_user_id, requester_assignment.id,
      case when requested_swap_type='two_way' then counter_assignment.id else null end) then
    raise exception 'ההחלפה תיצור לעובד השני משמרות חופפות.';
  end if;
  if requested_swap_type='two_way' and public.dynamic_user_has_overlap(target_publication.id,current_user_id,counter_assignment.id,requester_assignment.id) then
    raise exception 'ההחלפה תיצור עבורך משמרות חופפות.';
  end if;

  insert into public.dynamic_shift_exchange_requests(publication_id,job_type_id,swap_type,requester_user_id,counterparty_user_id,requester_assignment_id,counterparty_assignment_id)
  values(target_publication.id,target_publication.job_type_id,requested_swap_type,current_user_id,requested_counterparty_user_id,requester_assignment.id,requested_counterparty_assignment_id)
  returning * into created_request;

  insert into public.audit_logs(action,actor_user_id,entity_type,entity_id,summary,metadata)
  values('shift_swap_created',current_user_id,'dynamic_shift_exchange_request',created_request.id,'נוצרה בקשת חילופי משמרות דינמית',jsonb_build_object('job_type_id',target_publication.job_type_id,'publication_id',target_publication.id,'swap_type',requested_swap_type));

  return jsonb_build_object('id',created_request.id,'status',created_request.status,'swapType',created_request.swap_type);
end;
$$;


ALTER FUNCTION "public"."create_dynamic_shift_exchange_request"("requested_swap_type" "text", "requested_requester_assignment_id" "uuid", "requested_counterparty_user_id" "uuid", "requested_counterparty_assignment_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_morning_driver_availability_period"("requested_year" integer, "requested_month" integer, "requested_title" "text" DEFAULT NULL::"text", "requested_instructions" "text" DEFAULT NULL::"text", "requested_submission_deadline" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  current_user_id uuid;
  current_permissions text[];

  created_period
    public.morning_driver_availability_periods%rowtype;

  current_date_value date;
  last_date_value date;

  weekday_number_value integer;
  weekday_name_value text;
  holiday_schedule_type_value public.schedule_type;

  created_shifts integer := 0;
  current_sort_order integer := 1;
begin
  current_user_id :=
    auth.uid();

  if current_user_id is null then
    raise exception
      'not authenticated';
  end if;

  if not exists (
    select 1
    from public.profiles
    where id = current_user_id
      and is_active = true
  ) then
    raise exception
      'user not active';
  end if;

  current_permissions :=
    coalesce(
      public.get_my_permissions(),
      array[]::text[]
    );

  if not (
    'morning_driver_availability.manage'
      = any(current_permissions)
  ) then
    raise exception
      'not allowed';
  end if;

  if requested_year is null
     or requested_year < 2020
     or requested_year > 2100
  then
    raise exception
      'invalid year';
  end if;

  if requested_month is null
     or requested_month < 1
     or requested_month > 12
  then
    raise exception
      'invalid month';
  end if;

  if requested_submission_deadline is null then
    raise exception
      'submission deadline is required';
  end if;

  if exists (
    select 1
    from public.morning_driver_availability_periods
    where year = requested_year
      and month = requested_month
  ) then
    raise exception
      'morning driver availability period already exists';
  end if;

  insert into public.morning_driver_availability_periods (
    year,
    month,
    status,
    title,
    instructions,
    submission_deadline,
    created_by,
    updated_by
  )
  values (
    requested_year,
    requested_month,
    'draft',
    nullif(
      trim(
        coalesce(
          requested_title,
          ''
        )
      ),
      ''
    ),
    nullif(
      trim(
        coalesce(
          requested_instructions,
          ''
        )
      ),
      ''
    ),
    requested_submission_deadline,
    current_user_id,
    current_user_id
  )
  returning *
  into created_period;

  current_date_value :=
    make_date(
      requested_year,
      requested_month,
      1
    );

  last_date_value :=
    (
      current_date_value
      + interval '1 month'
      - interval '1 day'
    )::date;

  while current_date_value <= last_date_value loop
    weekday_number_value :=
      extract(
        dow
        from current_date_value
      )::integer;

    weekday_name_value :=
      case weekday_number_value
        when 0 then 'ראשון'
        when 1 then 'שני'
        when 2 then 'שלישי'
        when 3 then 'רביעי'
        when 4 then 'חמישי'
        when 5 then 'שישי'
        when 6 then 'שבת'
      end;

    select holiday.schedule_type
    into holiday_schedule_type_value
    from public.holidays holiday
    where holiday.holiday_date = current_date_value
    order by
      case holiday.schedule_type::text
        when 'holiday_full' then 1
        when 'holiday_eve' then 2
        when 'holiday_end' then 3
        when 'chol_hamoed' then 4
        else 5
      end,
      holiday.name
    limit 1;

    if not found then
      holiday_schedule_type_value := null;
    end if;

    /*
     * ימים א׳–ה׳:
     * 06:00–16:00 — שני עובדים.
     * 15:00–23:00 — עובד אחד.
     */
    if holiday_schedule_type_value in (
      'holiday_full'::public.schedule_type,
      'holiday_end'::public.schedule_type
    ) then
      null;
    elsif holiday_schedule_type_value = 'holiday_eve'::public.schedule_type then
      insert into public.morning_driver_availability_shifts (
        period_id,
        shift_date,
        weekday_number,
        weekday_name,
        shift_type,
        start_time,
        end_time,
        required_workers,
        sort_order
      )
      values (
        created_period.id,
        current_date_value,
        weekday_number_value,
        weekday_name_value,
        'friday_morning',
        time '06:00',
        time '14:00',
        1,
        current_sort_order
      );

      created_shifts := created_shifts + 1;
      current_sort_order := current_sort_order + 1;
    elsif weekday_number_value between 0 and 4 then
      insert into public.morning_driver_availability_shifts (
        period_id,
        shift_date,
        weekday_number,
        weekday_name,
        shift_type,
        start_time,
        end_time,
        required_workers,
        sort_order
      )
      values (
        created_period.id,
        current_date_value,
        weekday_number_value,
        weekday_name_value,
        'weekday_morning',
        time '06:00',
        time '16:00',
        2,
        current_sort_order
      );

      created_shifts :=
        created_shifts + 1;

      current_sort_order :=
        current_sort_order + 1;

      insert into public.morning_driver_availability_shifts (
        period_id,
        shift_date,
        weekday_number,
        weekday_name,
        shift_type,
        start_time,
        end_time,
        required_workers,
        sort_order
      )
      values (
        created_period.id,
        current_date_value,
        weekday_number_value,
        weekday_name_value,
        'weekday_evening',
        time '15:00',
        time '23:00',
        1,
        current_sort_order
      );

      created_shifts :=
        created_shifts + 1;

      current_sort_order :=
        current_sort_order + 1;

    /*
     * יום שישי:
     * 06:00–14:00 — עובד אחד.
     */
    elsif weekday_number_value = 5 then
      insert into public.morning_driver_availability_shifts (
        period_id,
        shift_date,
        weekday_number,
        weekday_name,
        shift_type,
        start_time,
        end_time,
        required_workers,
        sort_order
      )
      values (
        created_period.id,
        current_date_value,
        weekday_number_value,
        weekday_name_value,
        'friday_morning',
        time '06:00',
        time '14:00',
        1,
        current_sort_order
      );

      created_shifts :=
        created_shifts + 1;

      current_sort_order :=
        current_sort_order + 1;
    end if;

    current_date_value :=
      current_date_value + 1;
  end loop;

  perform public.write_audit_log(
    requested_action :=
      'morning_driver_availability_period_created'
        ::public.audit_action_type,

    requested_target_user_id :=
      null,

    requested_summary :=
      'נוצר חודש אילוצים לכונני בוקר',

    requested_old_values :=
      null,

    requested_new_values :=
      jsonb_build_object(
        'periodId',
          created_period.id,

        'year',
          created_period.year,

        'month',
          created_period.month,

        'status',
          created_period.status,

        'createdShifts',
          created_shifts
      ),

    requested_metadata :=
      jsonb_build_object(
        'entityType',
          'morning_driver_availability_period'
      )
  );

  return jsonb_build_object(
    'periodId',
      created_period.id,

    'year',
      created_period.year,

    'month',
      created_period.month,

    'status',
      created_period.status,

    'title',
      created_period.title,

    'instructions',
      created_period.instructions,

    'submissionDeadline',
      created_period.submission_deadline,

    'createdShifts',
      created_shifts
  );
end;
$$;


ALTER FUNCTION "public"."create_morning_driver_availability_period"("requested_year" integer, "requested_month" integer, "requested_title" "text", "requested_instructions" "text", "requested_submission_deadline" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_morning_driver_schedule_draft"("requested_availability_period_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  current_user_id uuid := auth.uid();
  current_permissions text[];
  availability_period public.morning_driver_availability_periods%rowtype;
  schedule_period public.morning_driver_schedule_periods%rowtype;
  current_shift public.morning_driver_availability_shifts%rowtype;
  candidate_user_id uuid;
  slot_number integer;
  created_assignments integer := 0;
  assigned_assignments integer := 0;
  warning_count integer := 0;
begin
  if current_user_id is null then
    raise exception 'not authenticated';
  end if;

  current_permissions := coalesce(public.get_my_permissions(), array[]::text[]);
  if not ('morning_driver_schedule.edit' = any(current_permissions)) then
    raise exception 'not allowed';
  end if;

  select * into availability_period
  from public.morning_driver_availability_periods period
  where period.id = requested_availability_period_id
  for update;

  if not found then
    raise exception 'morning driver availability period not found';
  end if;
  if availability_period.status <> 'closed' then
    raise exception 'availability period must be closed before scheduling';
  end if;

  insert into public.morning_driver_schedule_periods (
    year, month, status, availability_period_id, title, created_by, updated_by
  ) values (
    availability_period.year,
    availability_period.month,
    'draft',
    availability_period.id,
    coalesce(availability_period.title, format('לוח כונני בוקר %s/%s', availability_period.month, availability_period.year)),
    current_user_id,
    current_user_id
  )
  on conflict (availability_period_id)
  do update set updated_by = excluded.updated_by, updated_at = now()
  returning * into schedule_period;

  delete from public.morning_driver_schedule_assignments assignment
  where assignment.schedule_period_id = schedule_period.id
    and assignment.is_locked = false;

  /*
   * Two-pass scheduler:
   * Pass 1 fills the minimum slot of EVERY shift first.
   * Pass 2 fills only recommended extra slots.
   * This prevents a second driver from consuming availability while another
   * shift is still left without its minimum morning driver.
   */
  for slot_number in 1..2 loop
    for current_shift in
      select *
      from public.morning_driver_availability_shifts shift_item
      where shift_item.period_id = availability_period.id
        and least(greatest(coalesce(shift_item.required_workers, 1), 1), 2) >= slot_number
      order by shift_item.shift_date, shift_item.sort_order
    loop
      candidate_user_id := null;

      select candidate.id
      into candidate_user_id
      from public.profiles candidate
      where candidate.role = 'morning_driver'::public.user_role
        and candidate.is_active = true
        and exists (
          select 1
          from public.morning_driver_availability_entries entry
          where entry.period_id = availability_period.id
            and entry.shift_id = current_shift.id
            and entry.user_id = candidate.id
            and entry.availability_status = 'available'
        )
        and not exists (
          select 1
          from public.morning_driver_schedule_assignments same_shift
          where same_shift.schedule_period_id = schedule_period.id
            and same_shift.availability_shift_id = current_shift.id
            and same_shift.assigned_user_id = candidate.id
        )
        and not exists (
          select 1
          from public.morning_driver_schedule_assignments same_day
          join public.morning_driver_availability_shifts other_shift
            on other_shift.id = same_day.availability_shift_id
          where same_day.schedule_period_id = schedule_period.id
            and same_day.assigned_user_id = candidate.id
            and other_shift.shift_date = current_shift.shift_date
        )
      order by
        (
          select count(*)
          from public.morning_driver_schedule_assignments existing_assignment
          where existing_assignment.schedule_period_id = schedule_period.id
            and existing_assignment.assigned_user_id = candidate.id
        ) asc,
        candidate.id
      limit 1;

      insert into public.morning_driver_schedule_assignments (
        schedule_period_id,
        availability_shift_id,
        assignment_slot,
        assigned_user_id,
        assignment_source,
        is_locked,
        is_intentionally_unassigned,
        notes
      ) values (
        schedule_period.id,
        current_shift.id,
        slot_number,
        candidate_user_id,
        case when candidate_user_id is null then null else 'automatic' end,
        false,
        false,
        case
          when candidate_user_id is null and slot_number = 1
            then 'לא נמצא כונן זמין למינימום הנדרש.'
          when candidate_user_id is null and slot_number > 1
            then 'לא נמצא כונן נוסף להשלמת ההמלצה.'
          else null
        end
      )
      on conflict (schedule_period_id, availability_shift_id, assignment_slot)
      do update set
        assigned_user_id = case
          when public.morning_driver_schedule_assignments.is_locked
            then public.morning_driver_schedule_assignments.assigned_user_id
          else excluded.assigned_user_id
        end,
        assignment_source = case
          when public.morning_driver_schedule_assignments.is_locked
            then public.morning_driver_schedule_assignments.assignment_source
          else excluded.assignment_source
        end,
        is_intentionally_unassigned = case
          when public.morning_driver_schedule_assignments.is_locked
            then public.morning_driver_schedule_assignments.is_intentionally_unassigned
          else false
        end,
        notes = case
          when public.morning_driver_schedule_assignments.is_locked
            then public.morning_driver_schedule_assignments.notes
          else excluded.notes
        end,
        updated_at = now();

      created_assignments := created_assignments + 1;
      if candidate_user_id is null then
        warning_count := warning_count + 1;
      else
        assigned_assignments := assigned_assignments + 1;
      end if;
    end loop;
  end loop;

  return jsonb_build_object(
    'schedulePeriodId', schedule_period.id,
    'year', schedule_period.year,
    'month', schedule_period.month,
    'status', schedule_period.status,
    'createdAssignments', created_assignments,
    'assignedAssignments', assigned_assignments,
    'warningCount', warning_count
  );
end;
$$;


ALTER FUNCTION "public"."create_morning_driver_schedule_draft"("requested_availability_period_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_operational_announcement"("requested_user_ids" "uuid"[], "requested_title" "text", "requested_body" "text", "requested_priority" "text" DEFAULT 'normal'::"text", "requested_expires_at" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_notification_id uuid;
  v_recipient_count integer;
  v_expires timestamptz := coalesce(requested_expires_at, now() + interval '7 days');
begin
  if v_actor is null then raise exception 'not authenticated'; end if;
  if not exists (select 1 from public.user_permissions up where up.user_id=v_actor and up.permission_key='announcements.send') then
    raise exception 'not allowed';
  end if;
  if nullif(trim(requested_title),'') is null then raise exception 'title required'; end if;
  if length(trim(requested_title)) > 120 then raise exception 'title too long'; end if;
  if nullif(trim(requested_body),'') is null then raise exception 'body required'; end if;
  if length(trim(requested_body)) > 500 then raise exception 'body too long'; end if;
  if requested_priority not in ('low','normal','important','urgent') then raise exception 'invalid priority'; end if;
  if v_expires <= now() then raise exception 'expiration must be in the future'; end if;

  select count(distinct p.id) into v_recipient_count
  from public.profiles p
  where p.is_active=true and p.id=any(coalesce(requested_user_ids,array[]::uuid[]));
  if v_recipient_count=0 then raise exception 'no recipients'; end if;

  insert into public.notifications(type,priority,source,title,body,url,data,created_by,expires_at)
  values('manager_message',requested_priority,'announcement',trim(requested_title),trim(requested_body),'/notifications',
    jsonb_build_object('kind','operational_announcement','sentBy',v_actor),v_actor,v_expires)
  returning id into v_notification_id;

  insert into public.notification_recipients(notification_id,user_id)
  select v_notification_id,p.id from public.profiles p
  where p.is_active=true and p.id=any(requested_user_ids)
  on conflict do nothing;

  insert into public.audit_logs(action,actor_user_id,entity_type,entity_id,summary,metadata)
  values('system_event',v_actor,'notification',v_notification_id,'נשלח עדכון יזום לעובדי המערכת',
    jsonb_build_object('recipient_count',v_recipient_count,'expires_at',v_expires,'priority',requested_priority));

  return jsonb_build_object('notificationId',v_notification_id,'recipientCount',v_recipient_count,'expiresAt',v_expires);
end;
$$;


ALTER FUNCTION "public"."create_operational_announcement"("requested_user_ids" "uuid"[], "requested_title" "text", "requested_body" "text", "requested_priority" "text", "requested_expires_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_schedule_publication_notification"("requested_schedule_kind" "text", "requested_period_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  current_user_id uuid := auth.uid();
  current_permissions text[];
  required_permission text;
  recipient_role text;
  notification_title text;
  notification_body text;
  notification_url text;
  target_year integer;
  target_month integer;
  target_status text;
  notification_id uuid;
  recipient_count integer := 0;
begin
  if current_user_id is null then
    raise exception 'not authenticated';
  end if;

  if not exists (
    select 1 from public.profiles
    where id = current_user_id and is_active = true
  ) then
    raise exception 'user not active';
  end if;

  current_permissions := coalesce(
    public.get_my_permissions(),
    array[]::text[]
  );

  case requested_schedule_kind
    when 'dispatcher' then
      required_permission := 'schedule.edit';
      recipient_role := 'dispatcher';
      notification_title := 'לוח המשמרות פורסם';

      select period.year, period.month, period.status::text
      into target_year, target_month, target_status
      from public.schedule_periods period
      where period.id = requested_period_id;

      notification_url := concat(
        '/schedule?year=', target_year,
        '&month=', target_month
      );

    when 'driver' then
      required_permission := 'driver_schedule.edit';
      recipient_role := 'on_call';
      notification_title := 'לוח הכוננויות פורסם';

      select period.year, period.month, period.status::text
      into target_year, target_month, target_status
      from public.driver_schedule_periods period
      where period.id = requested_period_id;

      notification_url := concat(
        '/driver-schedule?year=', target_year,
        '&month=', target_month
      );

    when 'morning_driver' then
      required_permission := 'morning_driver_schedule.edit';
      recipient_role := 'morning_driver';
      notification_title := 'לוח כוננויות הבוקר פורסם';

      select period.year, period.month, period.status::text
      into target_year, target_month, target_status
      from public.morning_driver_schedule_periods period
      where period.id = requested_period_id;

      notification_url := concat(
        '/morning-driver-schedule?year=', target_year,
        '&month=', target_month
      );

    else
      raise exception 'unsupported schedule kind';
  end case;

  if required_permission <> all(current_permissions) then
    raise exception 'not allowed';
  end if;

  if target_year is null or target_month is null then
    raise exception 'schedule period not found';
  end if;

  if target_status <> 'published' then
    raise exception 'schedule is not published';
  end if;

  notification_body := concat(
    'פורסם לוח לחודש ',
    lpad(target_month::text, 2, '0'),
    '/',
    target_year,
    '. ניתן לצפות בשיבוץ המעודכן במערכת.'
  );

  insert into public.notifications (
    type,
    priority,
    source,
    title,
    body,
    url,
    data,
    created_by
  )
  values (
    'schedule_published',
    'important',
    concat(requested_schedule_kind, '_schedule_publish'),
    notification_title,
    notification_body,
    notification_url,
    jsonb_build_object(
      'scheduleKind', requested_schedule_kind,
      'periodId', requested_period_id,
      'year', target_year,
      'month', target_month
    ),
    current_user_id
  )
  returning id into notification_id;

  insert into public.notification_recipients (
    notification_id,
    user_id
  )
  select
    notification_id,
    profile.id
  from public.profiles profile
  where profile.is_active = true
    and profile.role::text = recipient_role;

  get diagnostics recipient_count = row_count;

  if recipient_count = 0 then
    delete from public.notifications
    where id = notification_id;

    return jsonb_build_object(
      'notificationId', null,
      'recipientCount', 0
    );
  end if;

  return jsonb_build_object(
    'notificationId', notification_id,
    'recipientCount', recipient_count
  );
end;
$$;


ALTER FUNCTION "public"."create_schedule_publication_notification"("requested_schedule_kind" "text", "requested_period_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_shift_swap_request"("requested_swap_type" "text", "requested_requester_shift_id" "uuid", "requested_counterparty_user_id" "uuid", "requested_counterparty_shift_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  current_user_id uuid := auth.uid();
  requester_shift public.schedule_shifts%rowtype;
  counterparty_shift public.schedule_shifts%rowtype;
  requester_period public.schedule_periods%rowtype;
  requester_profile public.profiles%rowtype;
  counterparty_profile public.profiles%rowtype;
  validation_result jsonb;
  created_request public.shift_swap_requests%rowtype;
  israel_today date := (now() at time zone 'Asia/Jerusalem')::date;
  current_month_start date := date_trunc('month', israel_today)::date;
  next_month_start date := (date_trunc('month', israel_today) + interval '1 month')::date;
  month_after_next_start date := (date_trunc('month', israel_today) + interval '2 months')::date;
begin
  if current_user_id is null then
    raise exception 'לא נמצאה התחברות פעילה.';
  end if;

  if not public.current_user_has_permission('shift_swaps.view') then
    raise exception 'אין לך הרשאה להגיש בקשות להחלפת משמרות.';
  end if;

  if requested_swap_type not in ('one_way', 'two_way') then
    raise exception 'סוג ההחלפה אינו תקין.';
  end if;

  select *
  into requester_profile
  from public.profiles
  where id = current_user_id
    and is_active = true;

  if not found or requester_profile.role::text <> 'dispatcher' then
    raise exception 'בקשות להחלפת משמרות זמינות למוקדנים בלבד.';
  end if;

  select *
  into counterparty_profile
  from public.profiles
  where id = requested_counterparty_user_id
    and is_active = true;

  if not found or counterparty_profile.role::text <> 'dispatcher' then
    raise exception 'המוקדן המחליף אינו משתמש מוקדן פעיל.';
  end if;

  if requested_counterparty_user_id = current_user_id then
    raise exception 'לא ניתן להגיש בקשת החלפה מול עצמך.';
  end if;

  select *
  into requester_shift
  from public.schedule_shifts
  where id = requested_requester_shift_id;

  if not found then
    raise exception 'המשמרת שנבחרה לא נמצאה.';
  end if;

  if requester_shift.assigned_user_id is distinct from current_user_id then
    raise exception 'ניתן להגיש בקשה רק עבור משמרת שמשובצת אליך.';
  end if;

  if requester_shift.starts_at <= now() then
    raise exception 'לא ניתן להגיש בקשה עבור משמרת שכבר התחילה.';
  end if;

  select *
  into requester_period
  from public.schedule_periods
  where id = requester_shift.period_id;

  if not found or requester_period.status::text <> 'published' then
    raise exception 'ניתן להגיש בקשה רק עבור לוח שיבוצים שפורסם.';
  end if;

  if make_date(requester_period.year, requester_period.month, 1)
      < current_month_start
    or make_date(requester_period.year, requester_period.month, 1)
      >= month_after_next_start then
    raise exception 'ניתן להגיש בקשות רק עבור החודש הנוכחי או החודש הבא.';
  end if;

  if make_date(requester_period.year, requester_period.month, 1)
      = next_month_start
    and requester_period.status::text <> 'published' then
    raise exception 'בקשות לחודש הבא זמינות רק לאחר פרסום הלוח.';
  end if;

  if requested_swap_type = 'one_way' then
    if requested_counterparty_shift_id is not null then
      raise exception 'בהחלפה חד-כיוונית אין לבחור משמרת נגדית.';
    end if;
  else
    select *
    into counterparty_shift
    from public.schedule_shifts
    where id = requested_counterparty_shift_id;

    if not found then
      raise exception 'המשמרת של המוקדן השני לא נמצאה.';
    end if;

    if counterparty_shift.period_id <> requester_shift.period_id then
      raise exception 'בהחלפה דו-כיוונית שתי המשמרות חייבות להיות מאותו חודש שיבוץ.';
    end if;

    if counterparty_shift.assigned_user_id is distinct from requested_counterparty_user_id then
      raise exception 'המשמרת שנבחרה אינה משובצת כרגע למוקדן השני.';
    end if;

    if counterparty_shift.starts_at <= now() then
      raise exception 'לא ניתן להחליף משמרת שכבר התחילה.';
    end if;
  end if;

  if exists (
    select 1
    from public.shift_swap_requests r
    where r.status in ('pending_counterparty', 'pending_manager')
      and (
        r.requester_shift_id = requested_requester_shift_id
        or r.counterparty_shift_id = requested_requester_shift_id
        or (
          requested_counterparty_shift_id is not null
          and (
            r.requester_shift_id = requested_counterparty_shift_id
            or r.counterparty_shift_id = requested_counterparty_shift_id
          )
        )
      )
  ) then
    raise exception 'קיימת כבר בקשת החלפה פעילה עבור אחת המשמרות שנבחרו.';
  end if;

  validation_result := public.validate_shift_swap_final_state(
    requested_swap_type,
    current_user_id,
    requested_counterparty_user_id,
    requested_requester_shift_id,
    requested_counterparty_shift_id
  );

  if not coalesce((validation_result ->> 'valid')::boolean, false) then
    raise exception '%', validation_result ->> 'message';
  end if;

  insert into public.shift_swap_requests (
    swap_type,
    status,
    requester_user_id,
    counterparty_user_id,
    requester_shift_id,
    counterparty_shift_id
  )
  values (
    requested_swap_type,
    'pending_counterparty',
    current_user_id,
    requested_counterparty_user_id,
    requested_requester_shift_id,
    requested_counterparty_shift_id
  )
  returning * into created_request;

  return jsonb_build_object(
    'id', created_request.id,
    'swapType', created_request.swap_type,
    'status', created_request.status,
    'requesterUserId', created_request.requester_user_id,
    'counterpartyUserId', created_request.counterparty_user_id,
    'requesterShiftId', created_request.requester_shift_id,
    'counterpartyShiftId', created_request.counterparty_shift_id,
    'createdAt', created_request.created_at
  );
end;
$$;


ALTER FUNCTION "public"."create_shift_swap_request"("requested_swap_type" "text", "requested_requester_shift_id" "uuid", "requested_counterparty_user_id" "uuid", "requested_counterparty_shift_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_shift_swap_workflow_notification"("recipient_user_ids" "uuid"[], "requested_request_id" "uuid", "requested_actor_user_id" "uuid", "requested_event" "text", "requested_title" "text", "requested_body" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  created_notification_id uuid;
begin
  if recipient_user_ids is null
    or coalesce(array_length(recipient_user_ids, 1), 0) = 0 then
    return null;
  end if;

  insert into public.notifications (
    type,
    priority,
    source,
    title,
    body,
    url,
    data,
    created_by,
    expires_at
  )
  values (
    'shift_swap',
    'important',
    'shift_swap',
    requested_title,
    requested_body,
    '/shift-swaps',
    jsonb_build_object(
      'workflow', 'shift_swap',
      'shiftSwapRequestId', requested_request_id,
      'actorUserId', requested_actor_user_id,
      'event', requested_event
    ),
    requested_actor_user_id,
    now() + interval '90 days'
  )
  returning id into created_notification_id;

  insert into public.notification_recipients (
    notification_id,
    user_id
  )
  select
    created_notification_id,
    recipient_id
  from (
    select distinct unnest(recipient_user_ids) as recipient_id
  ) recipients
  join public.profiles p
    on p.id = recipients.recipient_id
   and p.is_active = true;

  if not exists (
    select 1
    from public.notification_recipients nr
    where nr.notification_id = created_notification_id
  ) then
    delete from public.notifications
    where id = created_notification_id;

    return null;
  end if;

  return created_notification_id;
end;
$$;


ALTER FUNCTION "public"."create_shift_swap_workflow_notification"("recipient_user_ids" "uuid"[], "requested_request_id" "uuid", "requested_actor_user_id" "uuid", "requested_event" "text", "requested_title" "text", "requested_body" "text") OWNER TO "postgres";


