CREATE OR REPLACE FUNCTION "public"."decorate_daily_report_notification"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare rid uuid; attachment_count_value bigint;
begin
 if new.source<>'daily_report' or not (new.data ? 'reportId') then return new; end if;
 begin rid:=(new.data->>'reportId')::uuid; exception when others then return new; end;
 select count(*) into attachment_count_value from public.daily_report_attachments a where a.report_id=rid;
 new.data:=coalesce(new.data,'{}'::jsonb)||jsonb_build_object('attachmentCount',attachment_count_value);
 return new;
end $$;


ALTER FUNCTION "public"."decorate_daily_report_notification"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."delete_availability_period"("requested_period_id" "uuid") RETURNS TABLE("deleted_period_id" "uuid", "deleted_period_title" "text", "deleted_period_year" integer, "deleted_period_month" integer, "deleted_shift_slots" integer, "deleted_availability_rows" integer, "deleted_submissions" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  current_user_id uuid;

  current_actor_email text;
  current_actor_display_name text;

  target_period_title text;
  target_period_year integer;
  target_period_month integer;
  target_period_status text;

  calculated_shift_slots integer;
  calculated_availability_rows integer;
  calculated_submissions integer;
begin
  current_user_id := auth.uid();

  if current_user_id is null then
    raise exception
      'User is not authenticated';
  end if;

  select
    profile.email,
    profile.display_name
  into
    current_actor_email,
    current_actor_display_name
  from public.profiles profile
  where profile.id =
    current_user_id
    and profile.is_active = true;

  if not found then
    raise exception
      'Authenticated user is not active';
  end if;

  if not exists (
    select 1
    from public.user_permissions permission
    where permission.user_id =
      current_user_id
      and permission.permission_key =
        'availability.manage'
  ) then
    raise exception
      'User is not allowed to delete availability periods';
  end if;

  if requested_period_id is null then
    raise exception
      'Availability period id is required';
  end if;

  select
    period.title,
    period.year,
    period.month,
    period.status
  into
    target_period_title,
    target_period_year,
    target_period_month,
    target_period_status
  from public.availability_periods period
  where period.id =
    requested_period_id
  for update;

  if not found then
    raise exception
      'Availability period was not found';
  end if;

  select
    count(*)::integer
  into
    calculated_shift_slots
  from public.availability_shift_slots slot
  where slot.period_id =
    requested_period_id;

  select
    count(*)::integer
  into
    calculated_availability_rows
  from public.dispatcher_availability availability
  where availability.period_id =
    requested_period_id;

  select
    count(*)::integer
  into
    calculated_submissions
  from public.availability_submissions submission
  where submission.period_id =
    requested_period_id;

  /*
   * סדר המחיקה חשוב:
   * קודם רשומות שתלויות במשמרות,
   * אחר כך ההגשות והמשמרות,
   * ולבסוף התקופה עצמה.
   */

  delete from
    public.dispatcher_availability
  where period_id =
    requested_period_id;

  delete from
    public.availability_submissions
  where period_id =
    requested_period_id;

  delete from
    public.availability_shift_slots
  where period_id =
    requested_period_id;

  delete from
    public.availability_periods
  where id =
    requested_period_id;

  insert into public.audit_logs (
    action,

    actor_user_id,
    actor_email,
    actor_display_name,

    target_user_id,
    target_email,
    target_display_name,

    entity_type,
    entity_id,
    summary,

    old_values,
    new_values,
    metadata
  )
  values (
    'availability_period_deleted',

    current_user_id,
    current_actor_email,
    current_actor_display_name,

    null,
    null,
    null,

    'availability_period',
    requested_period_id,

    format(
      'נמחקה תקופת אילוצים: %s',
      coalesce(
        target_period_title,
        format(
          '%s/%s',
          target_period_month,
          target_period_year
        )
      )
    ),

    jsonb_build_object(
      'id',
      requested_period_id,

      'title',
      target_period_title,

      'year',
      target_period_year,

      'month',
      target_period_month,

      'status',
      target_period_status,

      'shift_slots',
      calculated_shift_slots,

      'availability_rows',
      calculated_availability_rows,

      'submissions',
      calculated_submissions
    ),

    null,

    jsonb_build_object(
      'source',
      'delete-availability-period-rpc',

      'deleted_by',
      current_user_id
    )
  );

  return query
  select
    requested_period_id,
    target_period_title,
    target_period_year,
    target_period_month,
    calculated_shift_slots,
    calculated_availability_rows,
    calculated_submissions;
end;
$$;


ALTER FUNCTION "public"."delete_availability_period"("requested_period_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."delete_driver_availability_period"("requested_period_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  current_user_id uuid;
  period_to_delete public.driver_availability_periods%rowtype;
  deleted_days integer;
  deleted_entries integer;
  deleted_submissions integer;
begin
  current_user_id :=
    auth.uid();

  if current_user_id is null then
    raise exception
      'not authenticated';
  end if;

  if not public.is_manager_or_admin() then
    raise exception
      'not allowed';
  end if;

  if requested_period_id is null then
    raise exception
      'driver availability period id is required';
  end if;

  select *
  into period_to_delete
  from public.driver_availability_periods
  where id =
    requested_period_id
  for update;

  if not found then
    raise exception
      'driver availability period not found';
  end if;

  if exists (
    select 1
    from public.driver_schedule_periods schedule_period
    where schedule_period.availability_period_id =
      requested_period_id
  ) then
    raise exception
      'driver availability period already has a schedule';
  end if;

  select count(*)::integer
  into deleted_days
  from public.driver_availability_days
  where period_id =
    requested_period_id;

  select count(*)::integer
  into deleted_entries
  from public.driver_availability_entries availability_entry
  join public.driver_availability_days availability_day
    on availability_day.id =
      availability_entry.day_id
  where availability_day.period_id =
    requested_period_id;

  select count(*)::integer
  into deleted_submissions
  from public.driver_availability_submissions
  where period_id =
    requested_period_id;

  delete from public.driver_availability_periods
  where id =
    requested_period_id;

  perform public.write_audit_log(
    requested_action :=
      'driver_availability_period_deleted'::public.audit_action_type,
    requested_target_user_id :=
      null,
    requested_summary :=
      'Driver availability period deleted',
    requested_old_values :=
      jsonb_build_object(
        'periodId',
        period_to_delete.id,
        'year',
        period_to_delete.year,
        'month',
        period_to_delete.month,
        'status',
        period_to_delete.status
      ),
    requested_new_values :=
      null,
    requested_metadata :=
      jsonb_build_object(
        'deletedDays',
        deleted_days,
        'deletedEntries',
        deleted_entries,
        'deletedSubmissions',
        deleted_submissions
      )
  );

  return jsonb_build_object(
    'deletedPeriodId',
      period_to_delete.id,
    'year',
      period_to_delete.year,
    'month',
      period_to_delete.month,
    'title',
      period_to_delete.title,
    'deletedDays',
      deleted_days,
    'deletedEntries',
      deleted_entries,
    'deletedSubmissions',
      deleted_submissions
  );
end;
$$;


ALTER FUNCTION "public"."delete_driver_availability_period"("requested_period_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."delete_dynamic_job_type"("requested_job_type_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  current_user_id uuid := auth.uid();
  target public.job_types%rowtype;
  member_count integer;
  period_count integer;
  target_group_id uuid;
  group_is_private boolean := false;
begin
  if current_user_id is null then raise exception 'not authenticated'; end if;
  if not exists(select 1 from public.profiles p where p.id=current_user_id and p.is_active=true) then
    raise exception 'user not active';
  end if;
  if not exists(
    select 1 from public.user_permissions up
    where up.user_id=current_user_id and up.permission_key='users.manage'
  ) then
    raise exception 'not allowed';
  end if;

  select * into target from public.job_types jt where jt.id=requested_job_type_id;
  if target.id is null then raise exception 'job type not found'; end if;
  if target.legacy_role is not null then
    raise exception 'לא ניתן למחוק סוג תפקיד שהגיע מהמערכת הקיימת. ניתן להקפיא אותו בלבד';
  end if;

  select count(*) into member_count
  from public.job_type_memberships m
  where m.job_type_id=target.id;
  if member_count>0 then
    raise exception 'לא ניתן למחוק את התפקיד: משויכים אליו % עובדים. הקפא את התפקיד במקום למחוק אותו',member_count;
  end if;

  select count(*) into period_count
  from public.dynamic_availability_periods p
  where p.job_type_id=target.id;
  if period_count>0 then
    raise exception 'לא ניתן למחוק את התפקיד: קיימות עבורו תקופות אילוצים/שיבוץ. הקפא את התפקיד כדי לשמור את ההיסטוריה';
  end if;

  target_group_id := target.schedule_group_id;
  select coalesce((sg.config->>'independent')::boolean,false)
    into group_is_private
  from public.schedule_groups sg
  where sg.id=target_group_id;

  insert into public.audit_logs(action,actor_user_id,entity_type,entity_id,summary,metadata)
  values(
    'system_event',current_user_id,'dynamic_job_type',target.id,
    'סוג תפקיד דינמי נמחק',
    jsonb_build_object('job_type_id',target.id,'job_type_name',target.name,'job_type_code',target.code)
  );

  delete from public.job_types where id=target.id;

  -- Independent roles receive a private implementation group. Remove that group
  -- only when no other role points at it; group-owned templates then cascade safely.
  if group_is_private and not exists(
    select 1 from public.job_types jt where jt.schedule_group_id=target_group_id
  ) then
    delete from public.schedule_groups sg where sg.id=target_group_id;
  end if;
end;
$$;


ALTER FUNCTION "public"."delete_dynamic_job_type"("requested_job_type_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."delete_morning_driver_availability_period"("requested_period_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  current_user_id uuid;
  current_permissions text[];

  target_period
    public.morning_driver_availability_periods%rowtype;

  deleted_shifts integer;
  deleted_submissions integer;
  deleted_entries integer;
begin
  current_user_id :=
    auth.uid();

  if current_user_id is null then
    raise exception
      'not authenticated';
  end if;

  current_permissions :=
    coalesce(
      public.get_my_permissions(),
      array[]::text[]
    );

  if not (
    'morning_driver_availability.manage'
      = any(current_permissions)
  ) then
    raise exception
      'not allowed';
  end if;

  if requested_period_id is null then
    raise exception
      'period id is required';
  end if;

  select *
  into target_period
  from public.morning_driver_availability_periods
  where id = requested_period_id
  for update;

  if not found then
    raise exception
      'morning driver availability period not found';
  end if;

  if target_period.status <> 'draft' then
    raise exception
      'only draft periods can be deleted';
  end if;

  select count(*)
  into deleted_shifts
  from public.morning_driver_availability_shifts
  where period_id = target_period.id;

  select count(*)
  into deleted_submissions
  from public.morning_driver_availability_submissions
  where period_id = target_period.id;

  select count(*)
  into deleted_entries
  from public.morning_driver_availability_entries
  where period_id = target_period.id;

  perform public.write_audit_log(
    requested_action :=
      'morning_driver_availability_period_deleted'
        ::public.audit_action_type,

    requested_target_user_id :=
      null,

    requested_summary :=
      'נמחק חודש אילוצים לכונני בוקר',

    requested_old_values :=
      jsonb_build_object(
        'periodId',
          target_period.id,

        'year',
          target_period.year,

        'month',
          target_period.month,

        'status',
          target_period.status
      ),

    requested_new_values :=
      null,

    requested_metadata :=
      jsonb_build_object(
        'deletedShifts',
          deleted_shifts,

        'deletedSubmissions',
          deleted_submissions,

        'deletedEntries',
          deleted_entries
      )
  );

  delete from public.morning_driver_availability_periods
  where id = target_period.id;

  return jsonb_build_object(
    'deletedPeriodId',
      target_period.id,

    'year',
      target_period.year,

    'month',
      target_period.month,

    'deletedShifts',
      deleted_shifts,

    'deletedSubmissions',
      deleted_submissions,

    'deletedEntries',
      deleted_entries
  );
end;
$$;


ALTER FUNCTION "public"."delete_morning_driver_availability_period"("requested_period_id" "uuid") OWNER TO "postgres";

