    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select mod(
    public.dynamic_time_minutes(target_time)
      - public.dynamic_time_minutes(base_time)
      + 1440,
    1440
  );
$$;


