CREATE OR REPLACE FUNCTION "public"."dynamic_refresh_draft_metrics"("requested_draft_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_draft public.dynamic_schedule_shadow_drafts%rowtype;
  v_unfilled integer := 0;
  v_intentional integer := 0;
  v_effective integer := 0;
  v_manager_edits integer := 0;
  v_metrics jsonb;
begin
  select * into v_draft from public.dynamic_schedule_shadow_drafts where id=requested_draft_id;
  if v_draft.id is null then raise exception 'draft not found'; end if;

  select coalesce(sum(greatest(sl.min_workers - coalesce(a.cnt,0), 0)),0)::integer
  into v_unfilled
  from public.dynamic_availability_slots sl
  left join (
    select slot_id,count(*)::integer cnt
    from public.dynamic_schedule_shadow_assignments
    where draft_id=requested_draft_id and assignment_tier='required'
    group by slot_id
  ) a on a.slot_id=sl.id
  where sl.period_id=v_draft.availability_period_id;

  select coalesce(sum(least(o.intentionally_unassigned_count, greatest(sl.min_workers-coalesce(a.cnt,0),0))),0)::integer
  into v_intentional
  from public.dynamic_availability_slots sl
  left join (
    select slot_id,count(*)::integer cnt
    from public.dynamic_schedule_shadow_assignments
    where draft_id=requested_draft_id and assignment_tier='required'
    group by slot_id
  ) a on a.slot_id=sl.id
  left join public.dynamic_schedule_draft_slot_overrides o
    on o.draft_id=requested_draft_id and o.slot_id=sl.id
  where sl.period_id=v_draft.availability_period_id;

  v_effective := greatest(v_unfilled-v_intentional,0);

  select count(*)::integer into v_manager_edits
  from public.dynamic_schedule_shadow_assignments
  where draft_id=requested_draft_id
    and (manager_edited_at is not null or (engine_user_id is not null and engine_user_id<>user_id));

  v_metrics := coalesce(v_draft.metrics,'{}'::jsonb) || jsonb_build_object(
    'unfilledRequiredPositions',v_unfilled,
    'intentionalUnfilledRequiredPositions',v_intentional,
    'effectiveUnfilledRequiredPositions',v_effective,
    'managerEditedAssignments',v_manager_edits
  );

  update public.dynamic_schedule_shadow_drafts
  set metrics=v_metrics,
      status=case when v_effective>0 then 'incomplete' else 'generated' end,
      updated_at=now()
  where id=requested_draft_id;

  return v_metrics;
end;
$$;


ALTER FUNCTION "public"."dynamic_refresh_draft_metrics"("requested_draft_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."dynamic_resolve_assignment_local_interval"("requested_shift_date" "date", "requested_start_time" time without time zone, "requested_end_time" time without time zone, "requested_work_mode" "text", "requested_scheduling_config" "jsonb") RETURNS TABLE("start_at" timestamp without time zone, "end_at" timestamp without time zone)
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  with normalized as (
    select coalesce(
      requested_scheduling_config #> '{schedulingConfig,shiftPattern}',
      requested_scheduling_config -> 'shiftPattern',
      '{}'::jsonb
    ) as shift_pattern
  ), resolved as (
    select
      case
        when requested_work_mode = 'on_call_daily'
          then coalesce(
            nullif(normalized.shift_pattern #>> '{dailyOnCallWindow,startTime}', '')::time,
            '00:00'::time
          )
        else coalesce(requested_start_time, '00:00'::time)
      end as resolved_start,
      case
        when requested_work_mode = 'on_call_daily'
          then coalesce(
            nullif(normalized.shift_pattern #>> '{dailyOnCallWindow,endTime}', '')::time,
            '00:00'::time
          )
        else coalesce(requested_end_time, '00:00'::time)
      end as resolved_end
    from normalized
  )
  select
    requested_shift_date + resolved_start,
    requested_shift_date + resolved_end
      + case when resolved_end <= resolved_start then interval '1 day' else interval '0 day' end
  from resolved;
$$;


ALTER FUNCTION "public"."dynamic_resolve_assignment_local_interval"("requested_shift_date" "date", "requested_start_time" time without time zone, "requested_end_time" time without time zone, "requested_work_mode" "text", "requested_scheduling_config" "jsonb") OWNER TO "postgres";


