CREATE OR REPLACE FUNCTION "public"."dynamic_shadow_candidate_allowed"("requested_draft_id" "uuid", "requested_user_id" "uuid", "requested_slot_id" "uuid", "requested_max_shifts_per_day" integer, "requested_no_consecutive" boolean, "requested_min_rest_minutes" integer) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  candidate_slot public.dynamic_availability_slots%rowtype;
  candidate_start timestamp;
  candidate_end timestamp;
  existing record;
begin
  select * into candidate_slot from public.dynamic_availability_slots where id=requested_slot_id;
  if candidate_slot.id is null then return false; end if;

  candidate_start := candidate_slot.shift_date + candidate_slot.start_time;
  candidate_end := candidate_slot.shift_date + candidate_slot.end_time;
  if candidate_slot.end_time <= candidate_slot.start_time then candidate_end := candidate_end + interval '1 day'; end if;

  if exists(select 1 from public.dynamic_schedule_shadow_assignments a where a.draft_id=requested_draft_id and a.slot_id=requested_slot_id and a.user_id=requested_user_id) then return false; end if;

  if (select count(*) from public.dynamic_schedule_shadow_assignments a join public.dynamic_availability_slots x on x.id=a.slot_id where a.draft_id=requested_draft_id and a.user_id=requested_user_id and x.shift_date=candidate_slot.shift_date) >= requested_max_shifts_per_day then return false; end if;

  for existing in
    select x.* from public.dynamic_schedule_shadow_assignments a
    join public.dynamic_availability_slots x on x.id=a.slot_id
    where a.draft_id=requested_draft_id and a.user_id=requested_user_id
  loop
    declare
      existing_start timestamp := existing.shift_date + existing.start_time;
      existing_end timestamp := existing.shift_date + existing.end_time;
    begin
      if existing.end_time <= existing.start_time then existing_end := existing_end + interval '1 day'; end if;
      if candidate_start < existing_end and existing_start < candidate_end then return false; end if;
      if requested_no_consecutive and (candidate_start=existing_end or candidate_end=existing_start) then return false; end if;
      if requested_min_rest_minutes > 0 then
        if existing_end <= candidate_start and extract(epoch from (candidate_start-existing_end))/60 < requested_min_rest_minutes then return false; end if;
        if candidate_end <= existing_start and extract(epoch from (existing_start-candidate_end))/60 < requested_min_rest_minutes then return false; end if;
      end if;
    end;
  end loop;
  return true;
end;
$$;


ALTER FUNCTION "public"."dynamic_shadow_candidate_allowed"("requested_draft_id" "uuid", "requested_user_id" "uuid", "requested_slot_id" "uuid", "requested_max_shifts_per_day" integer, "requested_no_consecutive" boolean, "requested_min_rest_minutes" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."dynamic_shadow_candidate_block_reason"("requested_draft_id" "uuid", "requested_user_id" "uuid", "requested_slot_id" "uuid", "requested_max_shifts_per_day" integer, "requested_no_consecutive" boolean, "requested_min_rest_minutes" integer, "requested_max_hard" boolean) RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  candidate_slot public.dynamic_availability_slots%rowtype;
  candidate_start timestamp;
  candidate_end timestamp;
  existing record;
  target_row public.dynamic_schedule_shadow_targets%rowtype;
begin
  select * into candidate_slot from public.dynamic_availability_slots where id=requested_slot_id;
  if candidate_slot.id is null then return 'משמרת לא נמצאה'; end if;
  select * into target_row from public.dynamic_schedule_shadow_targets where draft_id=requested_draft_id and user_id=requested_user_id;
  if target_row.user_id is null then return 'העובד אינו חלק מטיוטת ה־Shadow'; end if;
  if requested_max_hard and target_row.requested_max is not null and target_row.assigned_count>=target_row.requested_max then return 'הגיע למקסימום החודשי (Hard)'; end if;
  if exists(select 1 from public.dynamic_schedule_shadow_assignments a where a.draft_id=requested_draft_id and a.slot_id=requested_slot_id and a.user_id=requested_user_id) then return 'כבר משובץ במשמרת'; end if;
  if (select count(*) from public.dynamic_schedule_shadow_assignments a join public.dynamic_availability_slots s on s.id=a.slot_id where a.draft_id=requested_draft_id and a.user_id=requested_user_id and s.shift_date=candidate_slot.shift_date)>=requested_max_shifts_per_day then return 'הגיע למגבלת המשמרות ליום'; end if;

  candidate_start:=candidate_slot.shift_date+candidate_slot.start_time;
  candidate_end:=candidate_slot.shift_date+candidate_slot.end_time;
  if candidate_slot.end_time<=candidate_slot.start_time then candidate_end:=candidate_end+interval '1 day'; end if;

  for existing in
    select s.* from public.dynamic_schedule_shadow_assignments a
    join public.dynamic_availability_slots s on s.id=a.slot_id
    where a.draft_id=requested_draft_id and a.user_id=requested_user_id
  loop
    declare
      existing_start timestamp := existing.shift_date+existing.start_time;
      existing_end timestamp := existing.shift_date+existing.end_time;
    begin
      if existing.end_time<=existing.start_time then existing_end:=existing_end+interval '1 day'; end if;
      if candidate_start<existing_end and existing_start<candidate_end then return 'חפיפה עם משמרת שכבר שובצה'; end if;
      if requested_no_consecutive and (candidate_start=existing_end or candidate_end=existing_start) then return 'חוק מניעת משמרות רצופות'; end if;
      if requested_min_rest_minutes>0 then
        if existing_end<=candidate_start and extract(epoch from (candidate_start-existing_end))/60<requested_min_rest_minutes then return 'אין מספיק זמן מנוחה לפני המשמרת'; end if;
        if candidate_end<=existing_start and extract(epoch from (existing_start-candidate_end))/60<requested_min_rest_minutes then return 'אין מספיק זמן מנוחה אחרי המשמרת'; end if;
      end if;
    end;
  end loop;
  return null;
end;
$$;


ALTER FUNCTION "public"."dynamic_shadow_candidate_block_reason"("requested_draft_id" "uuid", "requested_user_id" "uuid", "requested_slot_id" "uuid", "requested_max_shifts_per_day" integer, "requested_no_consecutive" boolean, "requested_min_rest_minutes" integer, "requested_max_hard" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."dynamic_time_minutes"("value_time" time without time zone) RETURNS integer
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select (extract(hour from value_time)::integer * 60)
       + extract(minute from value_time)::integer;
$$;


ALTER FUNCTION "public"."dynamic_time_minutes"("value_time" time without time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."dynamic_user_has_overlap"("requested_publication_id" "uuid", "requested_user_id" "uuid", "requested_assignment_id" "uuid", "ignored_assignment_id" "uuid" DEFAULT NULL::"uuid") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  target_assignment public.dynamic_schedule_published_assignments%rowtype;
  target_start timestamptz;
  target_end timestamptz;
begin
  select * into target_assignment
  from public.dynamic_schedule_published_assignments
  where id=requested_assignment_id and publication_id=requested_publication_id;
  if target_assignment.id is null then return true; end if;

  target_start := public.dynamic_assignment_starts_at(target_assignment);
  target_end := public.dynamic_assignment_ends_at(target_assignment);

  return exists (
    select 1
    from public.dynamic_schedule_published_assignments other_assignment
    where other_assignment.publication_id=requested_publication_id
      and other_assignment.user_id=requested_user_id
      and other_assignment.id <> requested_assignment_id
      and (ignored_assignment_id is null or other_assignment.id <> ignored_assignment_id)
      and public.dynamic_assignment_starts_at(other_assignment) < target_end
      and public.dynamic_assignment_ends_at(other_assignment) > target_start
  );
end;
$$;


ALTER FUNCTION "public"."dynamic_user_has_overlap"("requested_publication_id" "uuid", "requested_user_id" "uuid", "requested_assignment_id" "uuid", "ignored_assignment_id" "uuid") OWNER TO "postgres";


