CREATE OR REPLACE FUNCTION "public"."execute_schedule_excel_import"("requested_file_name" "text", "requested_file_size_bytes" bigint, "requested_year" integer, "requested_month" integer, "requested_period_type" "text", "requested_import_strategy" "text", "requested_dispatcher_shifts" "jsonb", "requested_driver_duties" "jsonb", "requested_warnings" "jsonb" DEFAULT '[]'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  current_user_id uuid;
  current_permissions text[];

  preview_result jsonb;

  import_run_id uuid;

  resolved_schedule_period_id uuid;
  resolved_driver_period_id uuid;

  resolved_schedule_status
    public.schedule_period_status;

  resolved_driver_status
    public.driver_schedule_period_status;

  imported_at timestamptz :=
    now();

  dispatcher_created_count integer := 0;
  dispatcher_updated_count integer := 0;
  dispatcher_skipped_count integer := 0;
  dispatcher_deleted_count integer := 0;

  driver_created_count integer := 0;
  driver_updated_count integer := 0;
  driver_skipped_count integer := 0;
  driver_deleted_count integer := 0;

  dispatcher_detected_count integer := 0;
  driver_detected_count integer := 0;

  imported_warning_count integer := 0;

  existing_schedule_period
    public.schedule_periods%rowtype;

  existing_driver_period
    public.driver_schedule_periods%rowtype;
begin
  current_user_id :=
    auth.uid();

  if current_user_id is null then
    raise exception
      'not authenticated';
  end if;

  if not exists (
    select 1
    from public.profiles profile_row
    where profile_row.id =
      current_user_id
      and profile_row.is_active = true
  ) then
    raise exception
      'user not active';
  end if;

  current_permissions :=
    coalesce(
      public.get_my_permissions(),
      array[]::text[]
    );

  if not (
    'driver_availability.manage' =
      any(current_permissions)
    or
    'schedule.edit' =
      any(current_permissions)
    or
    'users.manage' =
      any(current_permissions)
  ) then
    raise exception
      'not allowed';
  end if;

  if nullif(
    trim(
      coalesce(
        requested_file_name,
        ''
      )
    ),
    ''
  ) is null then
    raise exception
      'import file name is required';
  end if;

  if requested_file_size_bytes is null
    or requested_file_size_bytes < 0
  then
    raise exception
      'import file size is invalid';
  end if;

  if requested_warnings is null then
    requested_warnings :=
      '[]'::jsonb;
  end if;

  if jsonb_typeof(
    requested_warnings
  ) <> 'array' then
    raise exception
      'import warnings must be a json array';
  end if;

  /*
   * מריצים שוב את אותה סימולציה בצד השרת.
   * כך אי אפשר לעקוף חסימות דרך ה-Frontend.
   */
  preview_result :=
    public.preview_schedule_excel_import(
      requested_year,
      requested_month,
      requested_period_type,
      requested_import_strategy,
      requested_dispatcher_shifts,
      requested_driver_duties
    );

  if not coalesce(
    (
      preview_result
        ->> 'canImport'
    )::boolean,
    false
  ) then
    raise exception
      'import blocked: %',
      preview_result
        -> 'blockers';
  end if;

  dispatcher_detected_count :=
    jsonb_array_length(
      requested_dispatcher_shifts
    );

  driver_detected_count :=
    jsonb_array_length(
      requested_driver_duties
    );

  imported_warning_count :=
    jsonb_array_length(
      requested_warnings
    )
    +
    jsonb_array_length(
      coalesce(
        preview_result
          -> 'warnings',
        '[]'::jsonb
      )
    );

  dispatcher_created_count :=
    coalesce(
      (
        preview_result
          -> 'dispatcherShifts'
          ->> 'toCreate'
      )::integer,
      0
    );

  dispatcher_updated_count :=
    coalesce(
      (
        preview_result
          -> 'dispatcherShifts'
          ->> 'toUpdate'
      )::integer,
      0
    );

  dispatcher_skipped_count :=
    coalesce(
      (
        preview_result
          -> 'dispatcherShifts'
          ->> 'toSkip'
      )::integer,
      0
    );

  dispatcher_deleted_count :=
    coalesce(
      (
        preview_result
          -> 'dispatcherShifts'
          ->> 'toDelete'
      )::integer,
      0
    );

  driver_created_count :=
    coalesce(
      (
        preview_result
          -> 'driverDuties'
          ->> 'toCreate'
      )::integer,
      0
    );

  driver_updated_count :=
    coalesce(
      (
        preview_result
          -> 'driverDuties'
          ->> 'toUpdate'
      )::integer,
      0
    );

  driver_skipped_count :=
    coalesce(
      (
        preview_result
          -> 'driverDuties'
          ->> 'toSkip'
      )::integer,
      0
    );

  driver_deleted_count :=
    coalesce(
      (
        preview_result
          -> 'driverDuties'
          ->> 'toDelete'
      )::integer,
      0
    );

  if requested_period_type =
    'historical'
  then
    resolved_schedule_status :=
      'archived'::public.schedule_period_status;

    resolved_driver_status :=
      'archived'::public.driver_schedule_period_status;
  else
    resolved_schedule_status :=
      'published'::public.schedule_period_status;

    resolved_driver_status :=
      'published'::public.driver_schedule_period_status;
  end if;

  /*
   * פתיחת רשומת תיעוד הייבוא.
   */
  insert into public.schedule_import_runs (
    file_name,
    file_size_bytes,
    year,
    month,
    period_type,
    import_strategy,
    status,
    dispatcher_shifts_detected,
    driver_duties_detected,
    warning_count,
    warnings,
    imported_by,
    started_at,
    created_at,
    updated_at
  )
  values (
    trim(
      requested_file_name
    ),
    requested_file_size_bytes,
    requested_year,
    requested_month,
    requested_period_type,
    requested_import_strategy,
    'processing',
    dispatcher_detected_count,
    driver_detected_count,
    imported_warning_count,
    requested_warnings
      ||
      coalesce(
        preview_result
          -> 'warnings',
        '[]'::jsonb
      ),
    current_user_id,
    imported_at,
    imported_at,
    imported_at
  )
  returning id
  into import_run_id;

  /*
   * תקופת שיבוץ מוקדנים.
   */
  select *
  into existing_schedule_period
  from public.schedule_periods
  where year =
    requested_year
    and month =
      requested_month
  for update;

  if found then
    resolved_schedule_period_id :=
      existing_schedule_period.id;

    update public.schedule_periods
    set
      status =
        resolved_schedule_status,

      title =
        coalesce(
          existing_schedule_period.title,
          concat(
            'שיבוץ ',
            requested_month,
            '/',
            requested_year
          )
        ),

      published_at =
        coalesce(
          existing_schedule_period.published_at,
          imported_at
        ),

      archived_at =
        case
          when requested_period_type =
            'historical'
          then
            coalesce(
              existing_schedule_period.archived_at,
              imported_at
            )
          else
            null
        end,

      approved_by =
        coalesce(
          existing_schedule_period.approved_by,
          current_user_id
        ),

      approved_at =
        coalesce(
          existing_schedule_period.approved_at,
          imported_at
        ),

      updated_at =
        imported_at

    where id =
      resolved_schedule_period_id;
  else
    insert into public.schedule_periods (
      year,
      month,
      status,
      published_at,
      archived_at,
      title,
      created_by,
      approved_by,
      approved_at,
      created_at,
      updated_at
    )
    values (
      requested_year,
      requested_month,
      resolved_schedule_status,
      imported_at,
      case
        when requested_period_type =
          'historical'
        then imported_at
        else null
      end,
      concat(
        'שיבוץ ',
        requested_month,
        '/',
        requested_year
      ),
      current_user_id,
      current_user_id,
      imported_at,
      imported_at,
      imported_at
    )
    returning id
    into resolved_schedule_period_id;
  end if;

  /*
   * תקופת לוח כוננים.
   */
  select *
  into existing_driver_period
  from public.driver_schedule_periods
  where year =
    requested_year
    and month =
      requested_month
  for update;

  if found then
    resolved_driver_period_id :=
      existing_driver_period.id;

    update public.driver_schedule_periods
    set
      status =
        resolved_driver_status,

      title =
        coalesce(
          existing_driver_period.title,
          concat(
            'לוח כוננים ',
            requested_month,
            '/',
            requested_year
          )
        ),

      published_at =
        coalesce(
          existing_driver_period.published_at,
          imported_at
        ),

      archived_at =
        case
          when requested_period_type =
            'historical'
          then
            coalesce(
              existing_driver_period.archived_at,
              imported_at
            )
          else
            null
        end,

      updated_by =
        current_user_id,

      updated_at =
        imported_at

    where id =
      resolved_driver_period_id;
  else
    insert into public.driver_schedule_periods (
      year,
      month,
      status,
      title,
      published_at,
      archived_at,
      created_by,
      updated_by,
      created_at,
      updated_at
    )
    values (
      requested_year,
      requested_month,
      resolved_driver_status,
      concat(
        'לוח כוננים ',
        requested_month,
        '/',
        requested_year
      ),
      imported_at,
      case
        when requested_period_type =
          'historical'
        then imported_at
        else null
      end,
      current_user_id,
      current_user_id,
      imported_at,
      imported_at
    )
    returning id
    into resolved_driver_period_id;
  end if;

  /*
   * rebuild מוחק את נתוני החודש לפני הייבוא.
   */
  if requested_import_strategy =
    'rebuild'
  then
    delete from public.schedule_shifts
    where period_id =
      resolved_schedule_period_id;

    delete from public.driver_schedule_days
    where period_id =
      resolved_driver_period_id;
  end if;

  /*
   * משמרות מוקדנים.
   */
  if requested_import_strategy =
    'missing_only'
  then
    insert into public.schedule_shifts (
      period_id,
      shift_date,
      starts_at,
      ends_at,
      shift_code,
      schedule_type,
      is_premium,
      holiday_name,
      assigned_user_id,
      assignment_source,
      is_locked,
      notes,
      import_run_id,
      created_at,
      updated_at
    )
    select
      resolved_schedule_period_id,

      payload.shift_date,

      (
        payload.shift_date +
        payload.start_time
      ) at time zone
        'Asia/Jerusalem',

      (
        payload.shift_date +
        payload.end_time +
        case
          when payload.end_time <=
            payload.start_time
          then interval '1 day'
          else interval '0 day'
        end
      ) at time zone
        'Asia/Jerusalem',

      concat(
        to_char(
          payload.shift_date,
          'YYYYMMDD'
        ),
        '-',
        to_char(
          payload.start_time,
          'HH24MI'
        )
      ),

      payload.schedule_type,

      payload.is_premium,

      payload.holiday_name,

      payload.user_id,

      'import'::public.assignment_source,

      requested_period_type =
        'historical',

      null,

      import_run_id,

      imported_at,

      imported_at

    from (
      select
        (
          item ->> 'date'
        )::date as shift_date,

        (
          item ->> 'startTime'
        )::time as start_time,

        (
          item ->> 'endTime'
        )::time as end_time,

        (
          item ->> 'userId'
        )::uuid as user_id,

        coalesce(
          holiday_row.schedule_type,
          case
            when extract(
              dow from
              (
                item ->> 'date'
              )::date
            )::integer = 5
            then
              'friday'::public.schedule_type

            when extract(
              dow from
              (
                item ->> 'date'
              )::date
            )::integer = 6
            then
              'saturday'::public.schedule_type

            else
              'weekday'::public.schedule_type
          end
        ) as schedule_type,

        holiday_row.name as holiday_name,

        case
          when holiday_row.schedule_type =
            'holiday_full'::public.schedule_type
          then true

          when (
            holiday_row.schedule_type =
              'holiday_eve'::public.schedule_type
            or extract(
              dow from
              (
                item ->> 'date'
              )::date
            )::integer = 5
          )
          then
            (
              item ->> 'startTime'
            )::time >=
              time '14:00'

          when (
            holiday_row.schedule_type =
              'holiday_end'::public.schedule_type
            or extract(
              dow from
              (
                item ->> 'date'
              )::date
            )::integer = 6
          )
          then
            (
              item ->> 'startTime'
            )::time <
              time '22:00'

          else false
        end as is_premium

      from jsonb_array_elements(
        requested_dispatcher_shifts
      ) item

      left join lateral (
        select
          holiday_record.schedule_type,
          holiday_record.name
        from public.holidays holiday_record
        where holiday_record.holiday_date =
          (
            item ->> 'date'
          )::date
        order by
          holiday_record.is_manual_override desc,
          holiday_record.updated_at desc
        limit 1
      ) holiday_row
        on true
    ) payload

    on conflict (
      period_id,
      starts_at
    )
    do nothing;
  else
    insert into public.schedule_shifts (
      period_id,
      shift_date,
      starts_at,
      ends_at,
      shift_code,
      schedule_type,
      is_premium,
      holiday_name,
      assigned_user_id,
      assignment_source,
      is_locked,
      notes,
      import_run_id,
      created_at,
      updated_at
    )
    select
      resolved_schedule_period_id,

      payload.shift_date,

      (
        payload.shift_date +
        payload.start_time
      ) at time zone
        'Asia/Jerusalem',

      (
        payload.shift_date +
        payload.end_time +
        case
          when payload.end_time <=
            payload.start_time
          then interval '1 day'
          else interval '0 day'
        end
      ) at time zone
        'Asia/Jerusalem',

      concat(
        to_char(
          payload.shift_date,
          'YYYYMMDD'
        ),
        '-',
        to_char(
          payload.start_time,
          'HH24MI'
        )
      ),

      payload.schedule_type,

      payload.is_premium,

      payload.holiday_name,

      payload.user_id,

      'import'::public.assignment_source,

      requested_period_type =
        'historical',

      null,

      import_run_id,

      imported_at,

      imported_at

    from (
      select
        (
          item ->> 'date'
        )::date as shift_date,

        (
          item ->> 'startTime'
        )::time as start_time,

        (
          item ->> 'endTime'
        )::time as end_time,

        (
          item ->> 'userId'
        )::uuid as user_id,

        coalesce(
          holiday_row.schedule_type,
          case
            when extract(
              dow from
              (
                item ->> 'date'
              )::date
            )::integer = 5
            then
              'friday'::public.schedule_type

            when extract(
              dow from
              (
                item ->> 'date'
              )::date
            )::integer = 6
            then
              'saturday'::public.schedule_type

            else
              'weekday'::public.schedule_type
          end
        ) as schedule_type,

        holiday_row.name as holiday_name,

        case
          when holiday_row.schedule_type =
            'holiday_full'::public.schedule_type
          then true

          when (
            holiday_row.schedule_type =
              'holiday_eve'::public.schedule_type
            or extract(
              dow from
              (
                item ->> 'date'
              )::date
            )::integer = 5
          )
          then
            (
              item ->> 'startTime'
            )::time >=
              time '14:00'

          when (
            holiday_row.schedule_type =
              'holiday_end'::public.schedule_type
            or extract(
              dow from
              (
                item ->> 'date'
              )::date
            )::integer = 6
          )
          then
            (
              item ->> 'startTime'
            )::time <
              time '22:00'

          else false
        end as is_premium

      from jsonb_array_elements(
        requested_dispatcher_shifts
      ) item

      left join lateral (
        select
          holiday_record.schedule_type,
          holiday_record.name
        from public.holidays holiday_record
        where holiday_record.holiday_date =
          (
            item ->> 'date'
          )::date
        order by
          holiday_record.is_manual_override desc,
          holiday_record.updated_at desc
        limit 1
      ) holiday_row
        on true
    ) payload

    on conflict (
      period_id,
      starts_at
    )
    do update set
      shift_date =
        excluded.shift_date,

      ends_at =
        excluded.ends_at,

      shift_code =
        excluded.shift_code,

      schedule_type =
        excluded.schedule_type,

      is_premium =
        excluded.is_premium,

      holiday_name =
        excluded.holiday_name,

      assigned_user_id =
        excluded.assigned_user_id,

      assignment_source =
        excluded.assignment_source,

      is_locked =
        excluded.is_locked,

      notes =
        excluded.notes,

      import_run_id =
        excluded.import_run_id,

      updated_at =
        imported_at;
  end if;

  /*
   * כוננויות.
   */
  if requested_import_strategy =
    'missing_only'
  then
    insert into public.driver_schedule_days (
      period_id,
      duty_date,
      weekday_number,
      weekday_name,
      original_user_id,
      assigned_user_id,
      assignment_source,
      is_locked,
      notes,
      import_run_id,
      created_at,
      updated_at
    )
    select
      resolved_driver_period_id,

      payload.duty_date,

      extract(
        dow from
        payload.duty_date
      )::integer,

      case extract(
        dow from
        payload.duty_date
      )::integer
        when 0 then 'ראשון'
        when 1 then 'שני'
        when 2 then 'שלישי'
        when 3 then 'רביעי'
        when 4 then 'חמישי'
        when 5 then 'שישי'
        when 6 then 'שבת'
      end,

      payload.user_id,

      payload.user_id,

      'import'::public.driver_assignment_source,

      requested_period_type =
        'historical',

      payload.note,

      import_run_id,

      imported_at,

      imported_at

    from (
      select
        (
          item ->> 'date'
        )::date as duty_date,

        (
          item ->> 'userId'
        )::uuid as user_id,

        nullif(
          trim(
            coalesce(
              item ->> 'note',
              ''
            )
          ),
          ''
        ) as note

      from jsonb_array_elements(
        requested_driver_duties
      ) item
    ) payload

    on conflict (
      period_id,
      duty_date
    )
    do nothing;
  else
    insert into public.driver_schedule_days (
      period_id,
      duty_date,
      weekday_number,
      weekday_name,
      original_user_id,
      assigned_user_id,
      assignment_source,
      is_locked,
      notes,
      import_run_id,
      created_at,
      updated_at
    )
    select
      resolved_driver_period_id,

      payload.duty_date,

      extract(
        dow from
        payload.duty_date
      )::integer,

      case extract(
        dow from
        payload.duty_date
      )::integer
        when 0 then 'ראשון'
        when 1 then 'שני'
        when 2 then 'שלישי'
        when 3 then 'רביעי'
        when 4 then 'חמישי'
        when 5 then 'שישי'
        when 6 then 'שבת'
      end,

      payload.user_id,

      payload.user_id,

      'import'::public.driver_assignment_source,

      requested_period_type =
        'historical',

      payload.note,

      import_run_id,

      imported_at,

      imported_at

    from (
      select
        (
          item ->> 'date'
        )::date as duty_date,

        (
          item ->> 'userId'
        )::uuid as user_id,

        nullif(
          trim(
            coalesce(
              item ->> 'note',
              ''
            )
          ),
          ''
        ) as note

      from jsonb_array_elements(
        requested_driver_duties
      ) item
    ) payload

    on conflict (
      period_id,
      duty_date
    )
    do update set
      weekday_number =
        excluded.weekday_number,

      weekday_name =
        excluded.weekday_name,

      original_user_id =
        excluded.original_user_id,

      assigned_user_id =
        excluded.assigned_user_id,

      assignment_source =
        excluded.assignment_source,

      is_locked =
        excluded.is_locked,

      notes =
        excluded.notes,

      import_run_id =
        excluded.import_run_id,

      updated_at =
        imported_at;
  end if;

  /*
   * השלמת ריצת הייבוא.
   */
  update public.schedule_import_runs
  set
    status =
      case
        when imported_warning_count > 0
        then 'completed_with_warnings'
        else 'completed'
      end,

    dispatcher_shifts_created =
      dispatcher_created_count,

    dispatcher_shifts_updated =
      dispatcher_updated_count,

    dispatcher_shifts_skipped =
      dispatcher_skipped_count,

    driver_duties_created =
      driver_created_count,

    driver_duties_updated =
      driver_updated_count,

    driver_duties_skipped =
      driver_skipped_count,

    schedule_period_id =
      resolved_schedule_period_id,

    driver_schedule_period_id =
      resolved_driver_period_id,

    result_summary =
      jsonb_build_object(
        'dispatcherShifts',
          jsonb_build_object(
            'detected',
              dispatcher_detected_count,
            'created',
              dispatcher_created_count,
            'updated',
              dispatcher_updated_count,
            'skipped',
              dispatcher_skipped_count,
            'deleted',
              dispatcher_deleted_count
          ),

        'driverDuties',
          jsonb_build_object(
            'detected',
              driver_detected_count,
            'created',
              driver_created_count,
            'updated',
              driver_updated_count,
            'skipped',
              driver_skipped_count,
            'deleted',
              driver_deleted_count
          )
      ),

    completed_at =
      imported_at,

    updated_at =
      imported_at

  where id =
    import_run_id;

  return jsonb_build_object(
    'importRunId',
      import_run_id,

    'year',
      requested_year,

    'month',
      requested_month,

    'periodType',
      requested_period_type,

    'importStrategy',
      requested_import_strategy,

    'status',
      case
        when imported_warning_count > 0
        then 'completed_with_warnings'
        else 'completed'
      end,

    'schedulePeriodId',
      resolved_schedule_period_id,

    'driverSchedulePeriodId',
      resolved_driver_period_id,

    'dispatcherShifts',
      jsonb_build_object(
        'detected',
          dispatcher_detected_count,

        'created',
          dispatcher_created_count,

        'updated',
          dispatcher_updated_count,

        'skipped',
          dispatcher_skipped_count,

        'deleted',
          dispatcher_deleted_count
      ),

    'driverDuties',
      jsonb_build_object(
        'detected',
          driver_detected_count,

        'created',
          driver_created_count,

        'updated',
          driver_updated_count,

        'skipped',
          driver_skipped_count,

        'deleted',
          driver_deleted_count
      ),

    'warningCount',
      imported_warning_count,

    'completedAt',
      imported_at
  );
end;
$$;


ALTER FUNCTION "public"."execute_schedule_excel_import"("requested_file_name" "text", "requested_file_size_bytes" bigint, "requested_year" integer, "requested_month" integer, "requested_period_type" "text", "requested_import_strategy" "text", "requested_dispatcher_shifts" "jsonb", "requested_driver_duties" "jsonb", "requested_warnings" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."execute_schedule_excel_import"("requested_file_name" "text", "requested_file_size_bytes" bigint, "requested_year" integer, "requested_month" integer, "requested_period_type" "text", "requested_import_strategy" "text", "requested_dispatcher_shifts" "jsonb", "requested_driver_duties" "jsonb", "requested_morning_driver_shifts" "jsonb", "requested_warnings" "jsonb" DEFAULT '[]'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  preview_result jsonb;

  base_result jsonb;

  morning_result jsonb;
begin
  /*
   * סימולציה משותפת לכל שלושת
   * סוגי השיבוצים:
   *
   * - מוקדנים.
   * - כוננים טכניים.
   * - כונני בוקר.
   */
  preview_result :=
    public.preview_schedule_excel_import(
      requested_year,
      requested_month,
      requested_period_type,
      requested_import_strategy,
      requested_dispatcher_shifts,
      requested_driver_duties,
      requested_morning_driver_shifts
    );

  if not coalesce(
    (
      preview_result
        ->> 'canImport'
    )::boolean,
    false
  ) then
    raise exception
      'import blocked: %',
      preview_result
        -> 'blockers';
  end if;

  /*
   * הפונקציה הקיימת בעלת תשעת
   * הפרמטרים מטפלת במוקדנים
   * ובכוננים הטכניים.
   *
   * הקריאה נעשית באמצעות שמות
   * פרמטרים כדי למנוע דו־משמעות
   * מול הגרסה החדשה של הפונקציה.
   */
  base_result :=
    public.execute_schedule_excel_import(
      requested_file_name =>
        requested_file_name,

      requested_file_size_bytes =>
        requested_file_size_bytes,

      requested_year =>
        requested_year,

      requested_month =>
        requested_month,

      requested_period_type =>
        requested_period_type,

      requested_import_strategy =>
        requested_import_strategy,

      requested_dispatcher_shifts =>
        requested_dispatcher_shifts,

      requested_driver_duties =>
        requested_driver_duties,

      requested_warnings =>
        requested_warnings
    );

  /*
   * שמירת שיבוצי כונני הבוקר
   * כחלק מאותה טרנזקציה.
   */
  morning_result :=
    public
      .import_morning_driver_schedule_assignments(
        (
          base_result
            ->> 'importRunId'
        )::uuid,

        requested_year,

        requested_month,

        requested_period_type,

        requested_import_strategy,

        requested_morning_driver_shifts
      );

  /*
   * מחזירים תשובה משותפת הכוללת
   * את שלושת סוגי השיבוצים.
   */
  return
    base_result
    ||
    jsonb_build_object(
      'morningDriverAvailabilityPeriodId',
        morning_result
          ->> 'availabilityPeriodId',

      'morningDriverSchedulePeriodId',
        morning_result
          ->> 'schedulePeriodId',

      'morningDriverShifts',
        jsonb_build_object(
          'detected',
            coalesce(
              (
                morning_result
                  ->> 'detected'
              )::integer,
              0
            ),

          'created',
            coalesce(
              (
                morning_result
                  ->> 'created'
              )::integer,
              0
            ),

          'updated',
            coalesce(
              (
                morning_result
                  ->> 'updated'
              )::integer,
              0
            ),

          'skipped',
            coalesce(
              (
                morning_result
                  ->> 'skipped'
              )::integer,
              0
            ),

          'deleted',
            coalesce(
              (
                morning_result
                  ->> 'deleted'
              )::integer,
              0
            )
        )
    );
end;
$$;


ALTER FUNCTION "public"."execute_schedule_excel_import"("requested_file_name" "text", "requested_file_size_bytes" bigint, "requested_year" integer, "requested_month" integer, "requested_period_type" "text", "requested_import_strategy" "text", "requested_dispatcher_shifts" "jsonb", "requested_driver_duties" "jsonb", "requested_morning_driver_shifts" "jsonb", "requested_warnings" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_announcement_recipient_catalog"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_actor uuid := auth.uid();
begin
  if v_actor is null then raise exception 'not authenticated'; end if;
  if not exists (
    select 1 from public.user_permissions up
    where up.user_id=v_actor and up.permission_key in ('announcements.send','users.manage')
  ) then raise exception 'not allowed'; end if;

  return jsonb_build_object(
    'users', coalesce((
      select jsonb_agg(jsonb_build_object('id',p.id,'name',p.display_name,'scheduleName',p.schedule_name) order by p.display_name)
      from public.profiles p where p.is_active=true
    ), '[]'::jsonb),
    'jobTypes', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id',jt.id,'name',jt.name,
        'userIds',coalesce((select jsonb_agg(jtm.user_id order by jtm.user_id) from public.job_type_memberships jtm join public.profiles p on p.id=jtm.user_id and p.is_active=true where jtm.job_type_id=jt.id),'[]'::jsonb)
      ) order by jt.name)
      from public.job_types jt where jt.is_active=true
    ), '[]'::jsonb)
  );
end;
$$;


ALTER FUNCTION "public"."get_announcement_recipient_catalog"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_archive_periods"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  current_user_id uuid;

  current_permissions text[];

  archive_rows jsonb;
begin
  current_user_id :=
    auth.uid();

  if current_user_id is null then
    raise exception
      'not authenticated';
  end if;

  if not exists (
    select 1
    from public.profiles profile_row
    where profile_row.id =
      current_user_id
      and profile_row.is_active = true
  ) then
    raise exception
      'user not active';
  end if;

  current_permissions :=
    coalesce(
      public.get_my_permissions(),
      array[]::text[]
    );

  if not (
    'archive.view' =
      any(current_permissions)
    or
    'statistics.view' =
      any(current_permissions)
    or
    'users.manage' =
      any(current_permissions)
  ) then
    raise exception
      'not allowed';
  end if;

  select
    coalesce(
      jsonb_agg(
        jsonb_build_object(
          'year',
            combined_period.year,

          'month',
            combined_period.month,

          'dispatcherPeriodId',
            combined_period
              .dispatcher_period_id,

          'driverPeriodId',
            combined_period
              .driver_period_id,

          'dispatcherStatus',
            combined_period
              .dispatcher_status,

          'driverStatus',
            combined_period
              .driver_status,

          'dispatcherShiftCount',
            combined_period
              .dispatcher_shift_count,

          'driverDutyCount',
            combined_period
              .driver_duty_count,

          'dispatcherCount',
            combined_period
              .dispatcher_count,

          'driverCount',
            combined_period
              .driver_count,

          'dispatcherPublishedAt',
            combined_period
              .dispatcher_published_at,

          'driverPublishedAt',
            combined_period
              .driver_published_at,

          'dispatcherArchivedAt',
            combined_period
              .dispatcher_archived_at,

          'driverArchivedAt',
            combined_period
              .driver_archived_at,

          'importRunId',
            combined_period
              .import_run_id,

          'importFileName',
            combined_period
              .import_file_name,

          'importedAt',
            combined_period
              .imported_at,

          'importedBy',
            combined_period
              .imported_by,

          'isFullyArchived',
            (
              combined_period
                .dispatcher_status =
                'archived'
              and
              combined_period
                .driver_status =
                'archived'
            ),

          'hasDispatcherSchedule',
            combined_period
              .dispatcher_period_id
              is not null,

          'hasDriverSchedule',
            combined_period
              .driver_period_id
              is not null
        )
        order by
          combined_period.year desc,
          combined_period.month desc
      ),
      '[]'::jsonb
    )
  into archive_rows

  from (
    select
      coalesce(
        dispatcher_period.year,
        driver_period.year
      ) as year,

      coalesce(
        dispatcher_period.month,
        driver_period.month
      ) as month,

      dispatcher_period.id
        as dispatcher_period_id,

      driver_period.id
        as driver_period_id,

      dispatcher_period.status::text
        as dispatcher_status,

      driver_period.status::text
        as driver_status,

      dispatcher_period.published_at
        as dispatcher_published_at,

      driver_period.published_at
        as driver_published_at,

      dispatcher_period.archived_at
        as dispatcher_archived_at,

      driver_period.archived_at
        as driver_archived_at,

      coalesce(
        dispatcher_stats.shift_count,
        0
      )::integer
        as dispatcher_shift_count,

      coalesce(
        dispatcher_stats.dispatcher_count,
        0
      )::integer
        as dispatcher_count,

      coalesce(
        driver_stats.duty_count,
        0
      )::integer
        as driver_duty_count,

      coalesce(
        driver_stats.driver_count,
        0
      )::integer
        as driver_count,

      import_run.id
        as import_run_id,

      import_run.file_name
        as import_file_name,

      import_run.completed_at
        as imported_at,

      importer.display_name
        as imported_by

    from public.schedule_periods
      dispatcher_period

    full join public.driver_schedule_periods
      driver_period
      on driver_period.year =
        dispatcher_period.year
      and driver_period.month =
        dispatcher_period.month

    left join lateral (
      select
        count(*)::integer
          as shift_count,

        count(
          distinct
          schedule_shift
            .assigned_user_id
        ) filter (
          where schedule_shift
            .assigned_user_id
            is not null
        )::integer
          as dispatcher_count

      from public.schedule_shifts
        schedule_shift

      where schedule_shift.period_id =
        dispatcher_period.id
    ) dispatcher_stats
      on true

    left join lateral (
      select
        count(*)::integer
          as duty_count,

        count(
          distinct
          driver_day
            .assigned_user_id
        ) filter (
          where driver_day
            .assigned_user_id
            is not null
        )::integer
          as driver_count

      from public.driver_schedule_days
        driver_day

      where driver_day.period_id =
        driver_period.id
    ) driver_stats
      on true

    left join lateral (
      select
        import_record.*
      from public.schedule_import_runs
        import_record

      where
        (
          import_record
            .schedule_period_id =
            dispatcher_period.id
          or
          import_record
            .driver_schedule_period_id =
            driver_period.id
        )

      order by
        import_record.created_at desc

      limit 1
    ) import_run
      on true

    left join public.profiles
      importer
      on importer.id =
        import_run.imported_by

    where
      dispatcher_period.status =
        'archived'
      or
      driver_period.status =
        'archived'
  ) combined_period;

  return jsonb_build_object(
    'periods',
      archive_rows,

    'count',
      jsonb_array_length(
        archive_rows
      ),

    'generatedAt',
      now()
  );
end;
$$;


ALTER FUNCTION "public"."get_archive_periods"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_audit_logs"("requested_limit" integer DEFAULT 100, "requested_offset" integer DEFAULT 0, "requested_action" "text" DEFAULT NULL::"text", "requested_actor_user_id" "uuid" DEFAULT NULL::"uuid", "requested_target_user_id" "uuid" DEFAULT NULL::"uuid", "requested_search_term" "text" DEFAULT NULL::"text") RETURNS TABLE("id" "uuid", "action" "text", "actor_user_id" "uuid", "actor_email" "text", "actor_display_name" "text", "target_user_id" "uuid", "target_email" "text", "target_display_name" "text", "entity_type" "text", "summary" "text", "old_values" "jsonb", "new_values" "jsonb", "metadata" "jsonb", "created_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  normalized_limit integer;
  normalized_offset integer;
  normalized_search_term text;
begin
  if auth.uid() is null then
    raise exception
      'User is not authenticated';
  end if;

  if not exists (
    select 1
    from public.user_permissions up
    where up.user_id = auth.uid()
      and up.permission_key =
        'audit.view'
  ) then
    raise exception
      'User is not allowed to view audit logs';
  end if;

  normalized_limit :=
    greatest(
      1,
      least(
        coalesce(requested_limit, 100),
        500
      )
    );

  normalized_offset :=
    greatest(
      coalesce(requested_offset, 0),
      0
    );

  normalized_search_term :=
    nullif(
      trim(
        coalesce(
          requested_search_term,
          ''
        )
      ),
      ''
    );

  return query
  select
    log.id,
    log.action,
    log.actor_user_id,
    log.actor_email,
    log.actor_display_name,
    log.target_user_id,
    log.target_email,
    log.target_display_name,
    log.entity_type,
    log.summary,
    log.old_values,
    log.new_values,
    log.metadata,
    log.created_at
  from public.audit_logs log
  where
    (
      requested_action is null
      or log.action = requested_action
    )
    and (
      requested_actor_user_id is null
      or log.actor_user_id =
        requested_actor_user_id
    )
    and (
      requested_target_user_id is null
      or log.target_user_id =
        requested_target_user_id
    )
    and (
      normalized_search_term is null
      or log.summary ilike
        '%' || normalized_search_term || '%'
      or coalesce(
        log.actor_display_name,
        ''
      ) ilike
        '%' || normalized_search_term || '%'
      or coalesce(
        log.actor_email,
        ''
      ) ilike
        '%' || normalized_search_term || '%'
      or coalesce(
        log.target_display_name,
        ''
      ) ilike
        '%' || normalized_search_term || '%'
      or coalesce(
        log.target_email,
        ''
      ) ilike
        '%' || normalized_search_term || '%'
    )
  order by log.created_at desc
  limit normalized_limit
  offset normalized_offset;
end;
$$;


ALTER FUNCTION "public"."get_audit_logs"("requested_limit" integer, "requested_offset" integer, "requested_action" "text", "requested_actor_user_id" "uuid", "requested_target_user_id" "uuid", "requested_search_term" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_availability_assignment_candidates"("requested_period_id" "uuid") RETURNS TABLE("period_id" "uuid", "period_year" integer, "period_month" integer, "period_title" "text", "period_status" "text", "shift_slot_id" "uuid", "shift_date" "date", "weekday_number" integer, "weekday_name" "text", "start_time" time without time zone, "end_time" time without time zone, "ends_next_day" boolean, "schedule_type" "text", "holiday_name" "text", "is_premium" boolean, "sort_order" integer, "total_dispatchers" integer, "available_dispatchers" integer, "unavailable_dispatchers" integer, "assignment_state" "text", "sole_available_user_id" "uuid", "sole_available_display_name" "text", "sole_available_schedule_name" "text", "available_user_ids" "uuid"[], "available_display_names" "text"[], "available_schedule_names" "text"[])
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  current_user_id uuid;
  target_period_year integer;
  target_period_status text;
begin
  current_user_id := auth.uid();

  if current_user_id is null then
    raise exception
      'User is not authenticated';
  end if;

  if not exists (
    select 1
    from public.profiles profile
    where profile.id =
      current_user_id
      and profile.is_active = true
  ) then
    raise exception
      'Authenticated user is not active';
  end if;

  if not exists (
    select 1
    from public.user_permissions permission
    where permission.user_id =
      current_user_id
      and permission.permission_key =
        'schedule.edit'
  ) then
    raise exception
      'User is not allowed to prepare schedule assignments';
  end if;

  if requested_period_id is null then
    raise exception
      'Availability period id is required';
  end if;

  select
    period.year,
    period.status
  into
    target_period_year,
    target_period_status
  from public.availability_periods period
  where period.id =
    requested_period_id;

  if target_period_year is null then
    raise exception
      'Availability period was not found';
  end if;

  if target_period_status <> 'closed' then
    raise exception
      'Availability period must be closed before assignment analysis';
  end if;

  return query

  with active_dispatchers as (
    select
      profile.id,
      profile.display_name,
      profile.schedule_name
    from public.profiles profile
    where profile.role::text =
      'dispatcher'
      and profile.is_active = true
  ),

  submitted_dispatchers as (
    select
      submission.user_id
    from public.availability_submissions submission
    where submission.period_id =
      requested_period_id
      and submission.status =
        'submitted'
  ),

  shift_availability as (
    select
      slot.id
        as analyzed_shift_slot_id,

      count(
        dispatcher.id
      )::integer
        as total_dispatchers,

      count(*) filter (
        where
          availability.availability_status =
            'available'
          and submitted.user_id
            is not null
      )::integer
        as available_dispatchers,

      count(*) filter (
        where
          availability.availability_status =
            'unavailable'
          and submitted.user_id
            is not null
      )::integer
        as unavailable_dispatchers,

      array_agg(
        dispatcher.id
        order by
          dispatcher.display_name
      ) filter (
        where
          availability.availability_status =
            'available'
          and submitted.user_id
            is not null
      )
        as available_user_ids,

      array_agg(
        dispatcher.display_name
        order by
          dispatcher.display_name
      ) filter (
        where
          availability.availability_status =
            'available'
          and submitted.user_id
            is not null
      )
        as available_display_names,

      array_agg(
        dispatcher.schedule_name
        order by
          dispatcher.display_name
      ) filter (
        where
          availability.availability_status =
            'available'
          and submitted.user_id
            is not null
      )
        as available_schedule_names

    from public.availability_shift_slots slot

    cross join active_dispatchers
      dispatcher

    left join submitted_dispatchers
      submitted
      on submitted.user_id =
        dispatcher.id

    left join public.dispatcher_availability
      availability
      on availability.period_id =
        requested_period_id
      and availability.shift_slot_id =
        slot.id
      and availability.user_id =
        dispatcher.id

    where slot.period_id =
      requested_period_id

    group by slot.id
  )

  select
    period.id,
    period.year,
    period.month,
    period.title,
    period.status,

    slot.id,
    slot.shift_date,
    slot.weekday_number,
    slot.weekday_name,
    slot.start_time,
    slot.end_time,
    slot.ends_next_day,
    slot.schedule_type,
    slot.holiday_name,
    slot.is_premium,
    slot.sort_order,

    analysis.total_dispatchers,
    analysis.available_dispatchers,
    analysis.unavailable_dispatchers,

    case
      when analysis.available_dispatchers = 0
        then 'no_available'

      when analysis.available_dispatchers = 1
        then 'single_available'

      else 'multiple_available'
    end
      as assignment_state,

    case
      when analysis.available_dispatchers = 1
        then analysis.available_user_ids[1]
      else null
    end
      as sole_available_user_id,

    case
      when analysis.available_dispatchers = 1
        then analysis.available_display_names[1]
      else null
    end
      as sole_available_display_name,

    case
      when analysis.available_dispatchers = 1
        then analysis.available_schedule_names[1]
      else null
    end
      as sole_available_schedule_name,

    coalesce(
      analysis.available_user_ids,
      array[]::uuid[]
    ),

    coalesce(
      analysis.available_display_names,
      array[]::text[]
    ),

    coalesce(
      analysis.available_schedule_names,
      array[]::text[]
    )

  from public.availability_periods period

  join public.availability_shift_slots slot
    on slot.period_id =
      period.id

  join shift_availability analysis
    on analysis.analyzed_shift_slot_id =
      slot.id

  where period.id =
    requested_period_id

  order by
    case
      when analysis.available_dispatchers = 0
        then 1
      when analysis.available_dispatchers = 1
        then 2
      else 3
    end,
    slot.shift_date,
    slot.sort_order;
end;
$$;


ALTER FUNCTION "public"."get_availability_assignment_candidates"("requested_period_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_availability_period_matrix"("requested_period_id" "uuid") RETURNS TABLE("period_id" "uuid", "period_year" integer, "period_month" integer, "period_title" "text", "period_status" "text", "shift_slot_id" "uuid", "shift_date" "date", "weekday_number" integer, "weekday_name" "text", "start_time" time without time zone, "end_time" time without time zone, "ends_next_day" boolean, "schedule_type" "text", "holiday_name" "text", "is_premium" boolean, "sort_order" integer, "total_dispatchers" integer, "available_dispatchers" integer, "unavailable_dispatchers" integer, "unanswered_dispatchers" integer, "user_id" "uuid", "display_name" "text", "email" "text", "schedule_name" "text", "submission_status" "text", "availability_status" "text", "availability_note" "text", "availability_updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  current_user_id uuid;
  target_period_year integer;
begin
  current_user_id := auth.uid();

  if current_user_id is null then
    raise exception
      'User is not authenticated';
  end if;

  if not exists (
    select 1
    from public.profiles profile
    where profile.id =
      current_user_id
      and profile.is_active = true
  ) then
    raise exception
      'Authenticated user is not active';
  end if;

  if not exists (
    select 1
    from public.user_permissions permission
    where permission.user_id =
      current_user_id
      and permission.permission_key =
        'availability.manage'
  ) then
    raise exception
      'User is not allowed to manage availability';
  end if;

  if requested_period_id is null then
    raise exception
      'Availability period id is required';
  end if;

  select
    period.year
  into
    target_period_year
  from public.availability_periods period
  where period.id =
    requested_period_id;

  if target_period_year is null then
    raise exception
      'Availability period was not found';
  end if;

  return query

  with active_dispatchers as (
    select
      profile.id,
      profile.display_name,
      profile.email,
      profile.schedule_name
    from public.profiles profile
    where profile.role::text =
      'dispatcher'
      and profile.is_active = true
  ),

  matrix_rows as (
    select
      period.id
        as matrix_period_id,

      period.year
        as matrix_period_year,

      period.month
        as matrix_period_month,

      period.title
        as matrix_period_title,

      period.status
        as matrix_period_status,

      slot.id
        as matrix_shift_slot_id,

      slot.shift_date,
      slot.weekday_number,
      slot.weekday_name,
      slot.start_time,
      slot.end_time,
      slot.ends_next_day,
      slot.schedule_type,
      slot.holiday_name,
      slot.is_premium,
      slot.sort_order,

      dispatcher.id
        as dispatcher_user_id,

      dispatcher.display_name,
      dispatcher.email,
      dispatcher.schedule_name,

      coalesce(
        submission.status,
        'not_started'
      )
        as matrix_submission_status,

      availability.availability_status
        as matrix_availability_status,

      availability.note
        as matrix_availability_note,

      availability.updated_at
        as matrix_availability_updated_at

    from public.availability_periods period

    join public.availability_shift_slots slot
      on slot.period_id =
        period.id

    cross join active_dispatchers
      dispatcher

    left join public.availability_submissions
      submission
      on submission.period_id =
        period.id
      and submission.user_id =
        dispatcher.id

    left join public.dispatcher_availability
      availability
      on availability.period_id =
        period.id
      and availability.shift_slot_id =
        slot.id
      and availability.user_id =
        dispatcher.id

    where period.id =
      requested_period_id
  ),

  shift_summary as (
    select
      row_data.matrix_shift_slot_id,

      count(*)::integer
        as total_dispatchers,

      count(*) filter (
        where
          row_data
            .matrix_availability_status =
            'available'
      )::integer
        as available_dispatchers,

      count(*) filter (
        where
          row_data
            .matrix_availability_status =
            'unavailable'
      )::integer
        as unavailable_dispatchers,

      count(*) filter (
        where
          row_data
            .matrix_availability_status
          is null
      )::integer
        as unanswered_dispatchers

    from matrix_rows row_data

    group by
      row_data.matrix_shift_slot_id
  )

  select
    row_data.matrix_period_id,
    row_data.matrix_period_year,
    row_data.matrix_period_month,
    row_data.matrix_period_title,
    row_data.matrix_period_status,

    row_data.matrix_shift_slot_id,
    row_data.shift_date,
    row_data.weekday_number,
    row_data.weekday_name,
    row_data.start_time,
    row_data.end_time,
    row_data.ends_next_day,
    row_data.schedule_type,
    row_data.holiday_name,
    row_data.is_premium,
    row_data.sort_order,

    summary.total_dispatchers,
    summary.available_dispatchers,
    summary.unavailable_dispatchers,
    summary.unanswered_dispatchers,

    row_data.dispatcher_user_id,
    row_data.display_name,
    row_data.email,
    row_data.schedule_name,

    row_data.matrix_submission_status,
    row_data.matrix_availability_status,
    row_data.matrix_availability_note,
    row_data.matrix_availability_updated_at

  from matrix_rows row_data

  join shift_summary summary
    on summary.matrix_shift_slot_id =
      row_data.matrix_shift_slot_id

  order by
    row_data.shift_date,
    row_data.sort_order,
    row_data.display_name;
end;
$$;


ALTER FUNCTION "public"."get_availability_period_matrix"("requested_period_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_availability_period_submissions"("requested_period_id" "uuid") RETURNS TABLE("period_id" "uuid", "period_year" integer, "period_month" integer, "period_title" "text", "period_status" "text", "submission_deadline" timestamp with time zone, "total_dispatchers" integer, "submitted_dispatchers" integer, "draft_dispatchers" integer, "not_started_dispatchers" integer, "user_id" "uuid", "display_name" "text", "email" "text", "schedule_name" "text", "submission_status" "text", "submitted_at" timestamp with time zone, "last_saved_at" timestamp with time zone, "available_count" integer, "unavailable_count" integer, "answered_count" integer, "unanswered_count" integer, "total_shift_count" integer, "completion_percentage" integer)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  current_user_id uuid;

  target_period_year integer;
  target_period_month integer;
begin
  current_user_id := auth.uid();

  if current_user_id is null then
    raise exception
      'User is not authenticated';
  end if;

  if not exists (
    select 1
    from public.profiles profile
    where profile.id =
      current_user_id
      and profile.is_active = true
  ) then
    raise exception
      'Authenticated user is not active';
  end if;

  if not exists (
    select 1
    from public.user_permissions permission
    where permission.user_id =
      current_user_id
      and permission.permission_key =
        'availability.manage'
  ) then
    raise exception
      'User is not allowed to manage availability';
  end if;

  if requested_period_id is null then
    raise exception
      'Availability period id is required';
  end if;

  select
    period.year,
    period.month
  into
    target_period_year,
    target_period_month
  from public.availability_periods period
  where period.id =
    requested_period_id;

  if target_period_year is null then
    raise exception
      'Availability period was not found';
  end if;

  return query

  with period_data as (
    select
      period.id,
      period.year,
      period.month,
      period.title,
      period.status,
      period.submission_deadline,

      (
        select count(*)::integer
        from public.availability_shift_slots slot
        where slot.period_id =
          period.id
      ) as total_shift_count

    from public.availability_periods period
    where period.id =
      requested_period_id
  ),

  dispatcher_rows as (
    select
      profile.id
        as dispatcher_user_id,

      profile.display_name,
      profile.email,
      profile.schedule_name,

      submission.status
        as stored_submission_status,

      submission.submitted_at,
      submission.last_saved_at,

      coalesce(
        submission.available_count,
        0
      )::integer
        as available_count,

      coalesce(
        submission.unavailable_count,
        0
      )::integer
        as unavailable_count,

      period_data.total_shift_count,

      (
        coalesce(
          submission.available_count,
          0
        )
        +
        coalesce(
          submission.unavailable_count,
          0
        )
      )::integer
        as answered_count

    from public.profiles profile

    cross join period_data

    left join
      public.availability_submissions
        submission
      on submission.period_id =
        requested_period_id
      and submission.user_id =
        profile.id

    where profile.role::text =
      'dispatcher'
      and profile.is_active = true
  ),

  classified_dispatchers as (
    select
      dispatcher_row.*,

      case
        when dispatcher_row
          .stored_submission_status =
          'submitted'
          then 'submitted'

        when dispatcher_row
          .answered_count > 0
          then coalesce(
            dispatcher_row
              .stored_submission_status,
            'draft'
          )

        else 'not_started'
      end
        as effective_submission_status,

      greatest(
        dispatcher_row.total_shift_count
        -
        dispatcher_row.answered_count,
        0
      )::integer
        as unanswered_count,

      case
        when dispatcher_row
          .total_shift_count = 0
          then 0

        else round(
          (
            dispatcher_row
              .answered_count::numeric
            /
            dispatcher_row
              .total_shift_count::numeric
          )
          * 100
        )::integer
      end
        as completion_percentage

    from dispatcher_rows
      dispatcher_row
  ),

  summary_data as (
    select
      count(*)::integer
        as total_dispatchers,

      count(*) filter (
        where
          effective_submission_status =
            'submitted'
      )::integer
        as submitted_dispatchers,

      count(*) filter (
        where
          effective_submission_status =
            'draft'
      )::integer
        as draft_dispatchers,

      count(*) filter (
        where
          effective_submission_status =
            'not_started'
      )::integer
        as not_started_dispatchers

    from classified_dispatchers
  )

  select
    period_data.id,
    period_data.year,
    period_data.month,
    period_data.title,
    period_data.status,
    period_data.submission_deadline,

    summary_data.total_dispatchers,
    summary_data.submitted_dispatchers,
    summary_data.draft_dispatchers,
    summary_data.not_started_dispatchers,

    dispatcher.dispatcher_user_id,
    dispatcher.display_name,
    dispatcher.email,
    dispatcher.schedule_name,

    dispatcher.effective_submission_status,
    dispatcher.submitted_at,
    dispatcher.last_saved_at,

    dispatcher.available_count,
    dispatcher.unavailable_count,
    dispatcher.answered_count,
    dispatcher.unanswered_count,
    dispatcher.total_shift_count,
    dispatcher.completion_percentage

  from period_data

  cross join summary_data

  join classified_dispatchers
    dispatcher
    on true

  order by
    case
      dispatcher.effective_submission_status
        when 'not_started'
          then 1
        when 'draft'
          then 2
        when 'submitted'
          then 3
        else 4
    end,

    dispatcher.display_name;
end;
$$;


ALTER FUNCTION "public"."get_availability_period_submissions"("requested_period_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_calendar_holidays"("requested_year" integer, "requested_month" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  current_user_id uuid :=
    auth.uid();

  first_date date;
  next_month date;
begin
  if current_user_id is null then
    raise exception
      'not authenticated';
  end if;

  if not exists (
    select 1
    from public.profiles profile
    where profile.id =
        current_user_id
      and profile.is_active =
        true
  ) then
    raise exception
      'user not active';
  end if;

  if requested_year < 2020
    or requested_year > 2100
    or requested_month < 1
    or requested_month > 12
  then
    raise exception
      'invalid year or month';
  end if;

  first_date :=
    make_date(
      requested_year,
      requested_month,
      1
    );

  next_month :=
    (
      first_date +
      interval '1 month'
    )::date;


  return coalesce(
    (
      select jsonb_agg(
        jsonb_build_object(
          'date',
            holiday_source.event_date,

          'name',
            holiday_source.event_name,

          'scheduleType',
            holiday_source.schedule_type,

          'holidayGroup',
            holiday_source.holiday_group
        )
        order by
          holiday_source.event_date,
          holiday_source.event_name
      )

      from public.calendar_special_days
        holiday_source

      where holiday_source.event_date >=
          first_date

        and holiday_source.event_date <
          next_month

        and holiday_source.schedule_type
          in (
            'holiday_eve',
            'holiday_full',
            'holiday_end',
            'chol_hamoed'
          )
    ),

    '[]'::jsonb
  );
end;
$$;


ALTER FUNCTION "public"."get_calendar_holidays"("requested_year" integer, "requested_month" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_client_version_admin_overview"("requested_current_version" "text", "requested_current_build_id" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  current_user_id uuid := auth.uid();
  current_permissions text[];
  users_json jsonb;
  summary_json jsonb;
begin
  if current_user_id is null then
    raise exception 'not authenticated';
  end if;

  current_permissions := coalesce(public.get_my_permissions(), array[]::text[]);

  if not exists (
      select 1 from public.profiles p
      where p.id = current_user_id
        and p.is_active = true
        and p.role::text = 'admin'
    )
    and not ('users.manage' = any(current_permissions))
    and not ('notifications.manage' = any(current_permissions)) then
    raise exception 'not allowed';
  end if;

  with user_rows as (
    select
      p.id as user_id,
      p.display_name,
      p.email,
      p.is_active,
      p.last_login_at,
      latest.app_version as latest_version,
      latest.build_id as latest_build_id,
      latest.last_seen_at as latest_seen_at,
      latest.is_pwa as latest_is_pwa,
      coalesce(devices.device_count, 0)::int as device_count,
      coalesce(devices.current_device_count, 0)::int as current_device_count,
      coalesce(devices.outdated_device_count, 0)::int as outdated_device_count,
      case
        when coalesce(devices.device_count, 0) = 0 then 'unknown'
        when coalesce(devices.outdated_device_count, 0) = 0 then 'current'
        when coalesce(devices.current_device_count, 0) > 0 then 'mixed'
        else 'outdated'
      end as version_status,
      coalesce(job_types.items, '[]'::jsonb) as job_types
    from public.profiles p
    left join lateral (
      select s.app_version, s.build_id, s.last_seen_at, s.is_pwa
      from public.client_app_sessions s
      where s.user_id = p.id
      order by s.last_seen_at desc
      limit 1
    ) latest on true
    left join lateral (
      select
        count(*)::int as device_count,
        count(*) filter (where s.build_id = requested_current_build_id)::int as current_device_count,
        count(*) filter (where s.build_id <> requested_current_build_id)::int as outdated_device_count
      from public.client_app_sessions s
      where s.user_id = p.id
    ) devices on true
    left join lateral (
      select coalesce(
        jsonb_agg(
          distinct jsonb_build_object('id', jt.id, 'name', jt.name)
        ),
        '[]'::jsonb
      ) as items
      from public.job_type_memberships m
      join public.job_types jt on jt.id = m.job_type_id
      where m.user_id = p.id
        and jt.is_active = true
        and jt.legacy_role is null
    ) job_types on true
    where p.is_active = true
  )
  select
    coalesce(
      jsonb_agg(
        jsonb_build_object(
          'userId', u.user_id,
          'displayName', u.display_name,
          'email', u.email,
          'isActive', u.is_active,
          'lastLoginAt', u.last_login_at,
          'latestVersion', u.latest_version,
          'latestBuildId', u.latest_build_id,
          'latestSeenAt', u.latest_seen_at,
          'latestIsPwa', u.latest_is_pwa,
          'deviceCount', u.device_count,
          'currentDeviceCount', u.current_device_count,
          'outdatedDeviceCount', u.outdated_device_count,
          'status', u.version_status,
          'jobTypes', u.job_types
        )
        order by u.display_name
      ),
      '[]'::jsonb
    ),
    jsonb_build_object(
      'total', count(*),
      'current', count(*) filter (where u.version_status = 'current'),
      'mixed', count(*) filter (where u.version_status = 'mixed'),
      'outdated', count(*) filter (where u.version_status = 'outdated'),
      'unknown', count(*) filter (where u.version_status = 'unknown')
    )
  into users_json, summary_json
  from user_rows u;

  return jsonb_build_object(
    'currentVersion', requested_current_version,
    'currentBuildId', requested_current_build_id,
    'users', users_json,
    'summary', summary_json
  );
end;
$$;


ALTER FUNCTION "public"."get_client_version_admin_overview"("requested_current_version" "text", "requested_current_build_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_current_schedule"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  current_user_id uuid;

  current_profile
    public.profiles%rowtype;

  current_year integer;
  current_month integer;

  resolved_period
    public.schedule_periods%rowtype;

  user_permissions text[];

  can_view_schedule boolean := false;
  can_edit_schedule boolean := false;
  can_view_team_schedule boolean := false;

  default_view_mode text := 'personal';

  can_access_current_period boolean := false;

  all_shifts_json jsonb :=
    '[]'::jsonb;

  visible_shifts_json jsonb :=
    '[]'::jsonb;

  personal_statistics_json jsonb :=
    null;

  dispatcher_statistics_json jsonb :=
    '[]'::jsonb;

  team_statistics_json jsonb;

  generated_at timestamptz :=
    now();
begin
  current_user_id :=
    auth.uid();

  if current_user_id is null then
    raise exception
      'not authenticated';
  end if;

  select *
  into current_profile
  from public.profiles
  where id =
    current_user_id;

  if not found then
    raise exception
      'profile not found';
  end if;

  if not current_profile.is_active then
    raise exception
      'user not active';
  end if;

  user_permissions :=
    coalesce(
      public.get_my_permissions(),
      array[]::text[]
    );

  can_view_schedule :=
    (
      'schedule.view' =
      any(user_permissions)
    )
    or
    (
      'schedule.view_team' =
      any(user_permissions)
    )
    or
    (
      'schedule.edit' =
      any(user_permissions)
    );

  can_edit_schedule :=
    'schedule.edit' =
    any(user_permissions);

  can_view_team_schedule :=
    'schedule.view_team' =
    any(user_permissions);

  if not can_view_schedule then
    raise exception
      'not allowed';
  end if;

  if can_view_team_schedule then
    default_view_mode :=
      'team';
  else
    default_view_mode :=
      'personal';
  end if;

  select
    extract(
      year
      from now()
        at time zone
        'Asia/Jerusalem'
    )::integer,

    extract(
      month
      from now()
        at time zone
        'Asia/Jerusalem'
    )::integer

  into
    current_year,
    current_month;

  select *
  into resolved_period
  from public.schedule_periods
  where year =
    current_year
    and month =
      current_month
  limit 1;

  if not found then
    return jsonb_build_object(
      'access',
      jsonb_build_object(
        'userId',
          current_user_id,

        'role',
          current_profile.role::text,

        'canViewSchedule',
          can_view_schedule,

        'canEditSchedule',
          can_edit_schedule,

        'canViewTeamSchedule',
          can_view_team_schedule,

        'defaultViewMode',
          default_view_mode
      ),

      'period',
        null,

      'shifts',
        '[]'::jsonb,

      'visibleShifts',
        '[]'::jsonb,

      'personalStatistics',
        null,

      'dispatcherStatistics',
        '[]'::jsonb,

      'teamStatistics',
        jsonb_build_object(
          'totalShifts', 0,
          'completedShifts', 0,
          'remainingShifts', 0,
          'completionPercentage', 0,
          'assignedDispatchers', 0,
          'premiumShifts', 0,
          'holidayShifts', 0,
          'manualAssignments', 0,
          'automaticAssignments', 0
        ),

      'generatedAt',
        generated_at
    );
  end if;

  can_access_current_period :=
    can_view_team_schedule
    or
    resolved_period.status =
      'published'::public.schedule_period_status;

  if not can_access_current_period then
    return jsonb_build_object(
      'access',
      jsonb_build_object(
        'userId',
          current_user_id,

        'role',
          current_profile.role::text,

        'canViewSchedule',
          can_view_schedule,

        'canEditSchedule',
          can_edit_schedule,

        'canViewTeamSchedule',
          can_view_team_schedule,

        'defaultViewMode',
          default_view_mode
      ),

      'period',
      jsonb_build_object(
        'id',
          resolved_period.id,

        'availabilityPeriodId',
          resolved_period.availability_period_id,

        'year',
          resolved_period.year,

        'month',
          resolved_period.month,

        'title',
          resolved_period.title,

        'status',
          resolved_period.status::text,

        'publishedAt',
          resolved_period.published_at,

        'approvedAt',
          resolved_period.approved_at,

        'createdAt',
          resolved_period.created_at,

        'updatedAt',
          resolved_period.updated_at
      ),

      'shifts',
        '[]'::jsonb,

      'visibleShifts',
        '[]'::jsonb,

      'personalStatistics',
        null,

      'dispatcherStatistics',
        '[]'::jsonb,

      'teamStatistics',
        jsonb_build_object(
          'totalShifts', 0,
          'completedShifts', 0,
          'remainingShifts', 0,
          'completionPercentage', 0,
          'assignedDispatchers', 0,
          'premiumShifts', 0,
          'holidayShifts', 0,
          'manualAssignments', 0,
          'automaticAssignments', 0
        ),

      'generatedAt',
        generated_at
    );
  end if;

  with schedule_rows as (
    select
      schedule_shift.id,
      schedule_shift.period_id,
      schedule_shift.availability_shift_slot_id,
      schedule_shift.shift_date,
      schedule_shift.starts_at,
      schedule_shift.ends_at,
      schedule_shift.shift_code,
      schedule_shift.schedule_type,
      schedule_shift.is_premium,
      schedule_shift.holiday_name,
      schedule_shift.assigned_user_id,
      schedule_shift.assignment_source,
      schedule_shift.assignment_score,
      schedule_shift.assignment_reasons,
      schedule_shift.is_locked,
      schedule_shift.notes,

      assigned_profile.display_name,
      assigned_profile.schedule_name,
      assigned_profile.role,

      case
        when schedule_shift.ends_at <=
          generated_at
        then
          'completed'

        when schedule_shift.starts_at <=
          generated_at
          and schedule_shift.ends_at >
            generated_at
        then
          'current'

        else
          'upcoming'
      end as progress_state

    from public.schedule_shifts
      schedule_shift

    left join public.profiles
      assigned_profile
      on assigned_profile.id =
        schedule_shift.assigned_user_id

    where schedule_shift.period_id =
      resolved_period.id
  ),

  mapped_rows as (
    select
      jsonb_build_object(
        'id',
          schedule_row.id,

        'periodId',
          schedule_row.period_id,

        'availabilityShiftSlotId',
          schedule_row.availability_shift_slot_id,

        'shiftDate',
          schedule_row.shift_date,

        'startsAt',
          schedule_row.starts_at,

        'endsAt',
          schedule_row.ends_at,

        'shiftCode',
          schedule_row.shift_code,

        'scheduleType',
          schedule_row.schedule_type::text,

        'isPremium',
          schedule_row.is_premium,

        'holidayName',
          schedule_row.holiday_name,

        'assignedUser',
          case
            when schedule_row.assigned_user_id
              is null
            then null

            else jsonb_build_object(
              'id',
                schedule_row.assigned_user_id,

              'displayName',
                schedule_row.display_name,

              'scheduleName',
                schedule_row.schedule_name,

              'role',
                schedule_row.role::text
            )
          end,

        'assignmentSource',
          case
            when schedule_row.assignment_source
              is null
            then null

            else
              schedule_row.assignment_source::text
          end,

        'assignmentScore',
          schedule_row.assignment_score,

        'assignmentReasons',
          coalesce(
            schedule_row.assignment_reasons,
            '[]'::jsonb
          ),

        'isLocked',
          schedule_row.is_locked,

        'notes',
          schedule_row.notes,

        'progressState',
          schedule_row.progress_state
      ) as shift_json,

      schedule_row.assigned_user_id,
      schedule_row.shift_date,
      schedule_row.starts_at

    from schedule_rows
      schedule_row
  )

  select
    coalesce(
      jsonb_agg(
        mapped_row.shift_json
        order by
          mapped_row.shift_date,
          mapped_row.starts_at
      ),
      '[]'::jsonb
    )

  into all_shifts_json

  from mapped_rows
    mapped_row;

  if can_view_team_schedule then
    visible_shifts_json :=
      all_shifts_json;
  else
    with personal_rows as (
      select
        schedule_shift.id,
        schedule_shift.period_id,
        schedule_shift.availability_shift_slot_id,
        schedule_shift.shift_date,
        schedule_shift.starts_at,
        schedule_shift.ends_at,
        schedule_shift.shift_code,
        schedule_shift.schedule_type,
        schedule_shift.is_premium,
        schedule_shift.holiday_name,
        schedule_shift.assigned_user_id,
        schedule_shift.assignment_source,
        schedule_shift.assignment_score,
        schedule_shift.assignment_reasons,
        schedule_shift.is_locked,
        schedule_shift.notes,

        assigned_profile.display_name,
        assigned_profile.schedule_name,
        assigned_profile.role,

        case
          when schedule_shift.ends_at <=
            generated_at
          then
            'completed'

          when schedule_shift.starts_at <=
            generated_at
            and schedule_shift.ends_at >
              generated_at
          then
            'current'

          else
            'upcoming'
        end as progress_state

      from public.schedule_shifts
        schedule_shift

      left join public.profiles
        assigned_profile
        on assigned_profile.id =
          schedule_shift.assigned_user_id

      where schedule_shift.period_id =
        resolved_period.id

        and schedule_shift.assigned_user_id =
          current_user_id
    )

    select
      coalesce(
        jsonb_agg(
          jsonb_build_object(
            'id',
              personal_row.id,

            'periodId',
              personal_row.period_id,

            'availabilityShiftSlotId',
              personal_row.availability_shift_slot_id,

            'shiftDate',
              personal_row.shift_date,

            'startsAt',
              personal_row.starts_at,

            'endsAt',
              personal_row.ends_at,

            'shiftCode',
              personal_row.shift_code,

            'scheduleType',
              personal_row.schedule_type::text,

            'isPremium',
              personal_row.is_premium,

            'holidayName',
              personal_row.holiday_name,

            'assignedUser',
              jsonb_build_object(
                'id',
                  personal_row.assigned_user_id,

                'displayName',
                  personal_row.display_name,

                'scheduleName',
                  personal_row.schedule_name,

                'role',
                  personal_row.role::text
              ),

            'assignmentSource',
              case
                when personal_row.assignment_source
                  is null
                then null

                else
                  personal_row.assignment_source::text
              end,

            'assignmentScore',
              personal_row.assignment_score,

            'assignmentReasons',
              coalesce(
                personal_row.assignment_reasons,
                '[]'::jsonb
              ),

            'isLocked',
              personal_row.is_locked,

            'notes',
              personal_row.notes,

            'progressState',
              personal_row.progress_state
          )

          order by
            personal_row.shift_date,
            personal_row.starts_at
        ),
        '[]'::jsonb
      )

    into visible_shifts_json

    from personal_rows
      personal_row;
  end if;

  with user_shift_statistics as (
    select
      assigned_profile.id
        as user_id,

      assigned_profile.display_name,
      assigned_profile.schedule_name,

      count(schedule_shift.id)::integer
        as total_shifts,

      count(schedule_shift.id) filter (
        where schedule_shift.ends_at <=
          generated_at
      )::integer
        as completed_shifts,

      count(schedule_shift.id) filter (
        where schedule_shift.ends_at >
          generated_at
      )::integer
        as remaining_shifts,

      coalesce(
        round(
          sum(
            extract(
              epoch
              from (
                schedule_shift.ends_at -
                schedule_shift.starts_at
              )
            ) / 3600
          )::numeric,
          2
        ),
        0
      ) as total_scheduled_hours,

      coalesce(
        round(
          sum(
            case
              when schedule_shift.ends_at <=
                generated_at
              then
                extract(
                  epoch
                  from (
                    schedule_shift.ends_at -
                    schedule_shift.starts_at
                  )
                ) / 3600

              else 0
            end
          )::numeric,
          2
        ),
        0
      ) as completed_hours,

      coalesce(
        round(
          sum(
            case
              when schedule_shift.ends_at >
                generated_at
              then
                extract(
                  epoch
                  from (
                    schedule_shift.ends_at -
                    schedule_shift.starts_at
                  )
                ) / 3600

              else 0
            end
          )::numeric,
          2
        ),
        0
      ) as remaining_hours,

      count(schedule_shift.id) filter (
        where schedule_shift.schedule_type =
          'weekday'

          and (
            schedule_shift.starts_at
            at time zone
              'Asia/Jerusalem'
          )::time =
            time '16:00'
      )::integer
        as weekday_evening_shifts,

      count(schedule_shift.id) filter (
        where schedule_shift.schedule_type =
          'weekday'

          and (
            schedule_shift.starts_at
            at time zone
              'Asia/Jerusalem'
          )::time =
            time '23:00'
      )::integer
        as weekday_night_shifts,

      count(schedule_shift.id) filter (
        where schedule_shift.schedule_type =
          'friday'

          and (
            schedule_shift.starts_at
            at time zone
              'Asia/Jerusalem'
          )::time =
            time '06:00'
      )::integer
        as friday_morning_shifts,

      count(schedule_shift.id) filter (
        where schedule_shift.schedule_type =
          'friday'

          and (
            schedule_shift.starts_at
            at time zone
              'Asia/Jerusalem'
          )::time =
            time '14:00'
      )::integer
        as friday_afternoon_shifts,

      count(schedule_shift.id) filter (
        where schedule_shift.schedule_type =
          'friday'

          and (
            schedule_shift.starts_at
            at time zone
              'Asia/Jerusalem'
          )::time =
            time '22:00'
      )::integer
        as friday_night_shifts,

      count(schedule_shift.id) filter (
        where schedule_shift.schedule_type =
          'saturday'

          and (
            schedule_shift.starts_at
            at time zone
              'Asia/Jerusalem'
          )::time =
            time '06:00'
      )::integer
        as saturday_morning_shifts,

      count(schedule_shift.id) filter (
        where schedule_shift.schedule_type =
          'saturday'

          and (
            schedule_shift.starts_at
            at time zone
              'Asia/Jerusalem'
          )::time =
            time '14:00'
      )::integer
        as saturday_afternoon_shifts,

      count(schedule_shift.id) filter (
        where schedule_shift.schedule_type =
          'saturday'

          and (
            schedule_shift.starts_at
            at time zone
              'Asia/Jerusalem'
          )::time =
            time '22:00'
      )::integer
        as saturday_night_shifts,

      count(schedule_shift.id) filter (
        where schedule_shift.is_premium
      )::integer
        as premium_shifts,

      count(schedule_shift.id) filter (
        where schedule_shift.schedule_type
          in (
            'holiday_eve',
            'holiday_full',
            'holiday_end'
          )
      )::integer
        as holiday_shifts,

      count(schedule_shift.id) filter (
        where schedule_shift.assignment_source =
          'manual'
      )::integer
        as manual_assignments,

      count(schedule_shift.id) filter (
        where schedule_shift.assignment_source =
          'automatic'
      )::integer
        as automatic_assignments

    from public.profiles
      assigned_profile

    join public.schedule_shifts
      schedule_shift
      on schedule_shift.assigned_user_id =
        assigned_profile.id

      and schedule_shift.period_id =
        resolved_period.id

    group by
      assigned_profile.id,
      assigned_profile.display_name,
      assigned_profile.schedule_name
  ),

  mapped_statistics as (
    select
      statistics.user_id,

      jsonb_build_object(
        'userId',
          statistics.user_id,

        'displayName',
          statistics.display_name,

        'scheduleName',
          statistics.schedule_name,

        'totalShifts',
          statistics.total_shifts,

        'completedShifts',
          statistics.completed_shifts,

        'remainingShifts',
          statistics.remaining_shifts,

        'completionPercentage',
          case
            when statistics.total_shifts =
              0
            then 0

            else round(
              (
                statistics.completed_shifts::numeric /
                statistics.total_shifts::numeric
              ) * 100
            )::integer
          end,

        'totalScheduledHours',
          statistics.total_scheduled_hours,

        'completedHours',
          statistics.completed_hours,

        'remainingHours',
          statistics.remaining_hours,

        'weekdayEveningShifts',
          statistics.weekday_evening_shifts,

        'weekdayNightShifts',
          statistics.weekday_night_shifts,

        'fridayMorningShifts',
          statistics.friday_morning_shifts,

        'fridayAfternoonShifts',
          statistics.friday_afternoon_shifts,

        'fridayNightShifts',
          statistics.friday_night_shifts,

        'saturdayMorningShifts',
          statistics.saturday_morning_shifts,

        'saturdayAfternoonShifts',
          statistics.saturday_afternoon_shifts,

        'saturdayNightShifts',
          statistics.saturday_night_shifts,

        'premiumShifts',
          statistics.premium_shifts,

        'holidayShifts',
          statistics.holiday_shifts,

        'manualAssignments',
          statistics.manual_assignments,

        'automaticAssignments',
          statistics.automatic_assignments
      ) as statistics_json

    from user_shift_statistics
      statistics
  )

  select
    (
      select
        mapped.statistics_json

      from mapped_statistics
        mapped

      where mapped.user_id =
        current_user_id

      limit 1
    ),

    case
      when can_view_team_schedule
      then coalesce(
        (
          select jsonb_agg(
            mapped.statistics_json
            order by
              mapped.statistics_json
                ->> 'displayName'
          )

          from mapped_statistics
            mapped
        ),
        '[]'::jsonb
      )

      else
        '[]'::jsonb
    end

  into
    personal_statistics_json,
    dispatcher_statistics_json;

  if personal_statistics_json is null then
    personal_statistics_json :=
      jsonb_build_object(
        'userId',
          current_user_id,

        'displayName',
          current_profile.display_name,

        'scheduleName',
          current_profile.schedule_name,

        'totalShifts', 0,
        'completedShifts', 0,
        'remainingShifts', 0,
        'completionPercentage', 0,

        'totalScheduledHours', 0,
        'completedHours', 0,
        'remainingHours', 0,

        'weekdayEveningShifts', 0,
        'weekdayNightShifts', 0,

        'fridayMorningShifts', 0,
        'fridayAfternoonShifts', 0,
        'fridayNightShifts', 0,

        'saturdayMorningShifts', 0,
        'saturdayAfternoonShifts', 0,
        'saturdayNightShifts', 0,

        'premiumShifts', 0,
        'holidayShifts', 0,

        'manualAssignments', 0,
        'automaticAssignments', 0
      );
  end if;

  if can_view_team_schedule then
    select
      jsonb_build_object(
        'totalShifts',
          count(
            schedule_shift.id
          )::integer,

        'completedShifts',
          count(
            schedule_shift.id
          ) filter (
            where schedule_shift.ends_at <=
              generated_at
          )::integer,

        'remainingShifts',
          count(
            schedule_shift.id
          ) filter (
            where schedule_shift.ends_at >
              generated_at
          )::integer,

        'completionPercentage',
          case
            when count(
              schedule_shift.id
            ) = 0
            then 0

            else round(
              (
                count(
                  schedule_shift.id
                ) filter (
                  where schedule_shift.ends_at <=
                    generated_at
                )::numeric /
                count(
                  schedule_shift.id
                )::numeric
              ) * 100
            )::integer
          end,

        'assignedDispatchers',
          count(
            distinct
            schedule_shift.assigned_user_id
          ) filter (
            where schedule_shift.assigned_user_id
              is not null
          )::integer,

        'premiumShifts',
          count(
            schedule_shift.id
          ) filter (
            where schedule_shift.is_premium
          )::integer,

        'holidayShifts',
          count(
            schedule_shift.id
          ) filter (
            where schedule_shift.schedule_type
              in (
                'holiday_eve',
                'holiday_full',
                'holiday_end'
              )
          )::integer,

        'manualAssignments',
          count(
            schedule_shift.id
          ) filter (
            where schedule_shift.assignment_source =
              'manual'
          )::integer,

        'automaticAssignments',
          count(
            schedule_shift.id
          ) filter (
            where schedule_shift.assignment_source =
              'automatic'
          )::integer
      )

    into team_statistics_json

    from public.schedule_shifts
      schedule_shift

    where schedule_shift.period_id =
      resolved_period.id;
  else
    team_statistics_json :=
      jsonb_build_object(
        'totalShifts', 0,
        'completedShifts', 0,
        'remainingShifts', 0,
        'completionPercentage', 0,
        'assignedDispatchers', 0,
        'premiumShifts', 0,
        'holidayShifts', 0,
        'manualAssignments', 0,
        'automaticAssignments', 0
      );
  end if;

  return jsonb_build_object(
    'access',
    jsonb_build_object(
      'userId',
        current_user_id,

      'role',
        current_profile.role::text,

      'canViewSchedule',
        can_view_schedule,

      'canEditSchedule',
        can_edit_schedule,

      'canViewTeamSchedule',
        can_view_team_schedule,

      'defaultViewMode',
        default_view_mode
    ),

    'period',
    jsonb_build_object(
      'id',
        resolved_period.id,

      'availabilityPeriodId',
        resolved_period.availability_period_id,

      'year',
        resolved_period.year,

      'month',
        resolved_period.month,

      'title',
        resolved_period.title,

      'status',
        resolved_period.status::text,

      'publishedAt',
        resolved_period.published_at,

      'approvedAt',
        resolved_period.approved_at,

      'createdAt',
        resolved_period.created_at,

      'updatedAt',
        resolved_period.updated_at
    ),

    'shifts',
      case
        when can_view_team_schedule
        then all_shifts_json
        else visible_shifts_json
      end,

    'visibleShifts',
      visible_shifts_json,

    'personalStatistics',
      personal_statistics_json,

    'dispatcherStatistics',
      dispatcher_statistics_json,

    'teamStatistics',
      team_statistics_json,

    'generatedAt',
      generated_at
  );
end;
$$;


ALTER FUNCTION "public"."get_current_schedule"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_current_schedule"() IS 'Returns the current monthly dispatcher schedule with role-aware personal or team visibility. Dispatchers and on-call users only receive published personal assignments. Managers, admins and viewers may receive the team schedule according to schedule permissions.';



CREATE OR REPLACE FUNCTION "public"."get_current_schedule_edit_options"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_user_id uuid := (select auth.uid());
  has_schedule_edit boolean := false;
  dispatcher_rows jsonb;
begin
  if actor_user_id is null then
    raise exception 'not authenticated';
  end if;

  if not exists (
    select 1
    from public.profiles profile
    where profile.id = actor_user_id
      and profile.is_active = true
  ) then
    raise exception 'user not active';
  end if;

  select exists (
    select 1
    from public.user_permissions permission
    where permission.user_id = actor_user_id
      and permission.permission_key = 'schedule.edit'
  )
  into has_schedule_edit;

  if not has_schedule_edit then
    raise exception 'schedule edit permission required';
  end if;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'id', profile.id,
        'displayName', profile.display_name,
        'scheduleName', profile.schedule_name
      )
      order by coalesce(profile.schedule_name, profile.display_name)
    ),
    '[]'::jsonb
  )
  into dispatcher_rows
  from public.profiles profile
  where profile.is_active = true
    and profile.role = 'dispatcher';

  return jsonb_build_object(
    'dispatchers', dispatcher_rows
  );
end;
$$;


ALTER FUNCTION "public"."get_current_schedule_edit_options"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_daily_report_admin_options"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare actor uuid:=auth.uid();
begin
  if actor is null then raise exception 'not authenticated'; end if;
  if not exists(
    select 1 from public.profiles p
    where p.id=actor and p.is_active=true
      and (p.role='admin' or exists(
        select 1 from public.user_permissions up
        where up.user_id=actor and up.permission_key='users.manage'
      ))
  ) then raise exception 'not allowed'; end if;

  return jsonb_build_object(
    'users', coalesce((
      select jsonb_agg(jsonb_build_object(
        'userId',p.id,'displayName',p.display_name,'email',p.email
      ) order by p.display_name)
      from public.profiles p where p.is_active=true
    ),'[]'::jsonb)
  );
end;
$$;


ALTER FUNCTION "public"."get_daily_report_admin_options"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_daily_report_attachment_download"("requested_attachment_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare actor uuid:=auth.uid(); result jsonb;
begin
 if actor is null then raise exception 'not authenticated'; end if;
 select jsonb_build_object('storagePath',a.storage_path,'fileName',a.file_name)
 into result
 from public.daily_report_attachments a
 join public.daily_reports r on r.id=a.report_id
 join public.job_types jt on jt.id=r.job_type_id
 where a.id=requested_attachment_id and (
   r.user_id=actor
   or (jt.scheduling_config#>'{dailyReports,recipientUserIds}') ? actor::text
   or public.has_dynamic_job_type_permission('daily_reports.view_attachment',r.job_type_id,actor)
 );
 if result is null then raise exception 'not allowed'; end if;
 return result;
end $$;


ALTER FUNCTION "public"."get_daily_report_attachment_download"("requested_attachment_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_daily_report_notification_detail"("requested_report_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare actor uuid:=auth.uid();
begin
 if actor is null then raise exception 'not authenticated'; end if;
 if not exists(
   select 1 from public.daily_reports r join public.job_types jt on jt.id=r.job_type_id
   where r.id=requested_report_id and (
     r.user_id=actor
     or (jt.scheduling_config#>'{dailyReports,recipientUserIds}') ? actor::text
     or public.has_dynamic_job_type_permission('daily_reports.view_received',r.job_type_id,actor)
   )
 ) then raise exception 'not allowed'; end if;

 return (
  select jsonb_build_object(
   'id',r.id,'reportDate',r.report_date,'submittedAt',r.submitted_at,
   'jobTypeId',jt.id,'jobTypeName',jt.name,'userId',p.id,'displayName',p.display_name,
   'items',coalesce((select jsonb_agg(jsonb_build_object(
      'id',i.id,'subjectName',i.subject_name,'customerName',i.customer_name,
      'details',i.details,'sortOrder',i.sort_order) order by i.sort_order)
      from public.daily_report_items i where i.report_id=r.id),'[]'::jsonb),
   'attachments',coalesce((select jsonb_agg(jsonb_build_object(
      'id',a.id,'fileName',a.file_name,'mimeType',a.mime_type,
      'fileSize',a.file_size,'storagePath',a.storage_path) order by a.created_at)
      from public.daily_report_attachments a where a.report_id=r.id),'[]'::jsonb)
  )
  from public.daily_reports r join public.job_types jt on jt.id=r.job_type_id
  join public.profiles p on p.id=r.user_id where r.id=requested_report_id
 );
end $$;


ALTER FUNCTION "public"."get_daily_report_notification_detail"("requested_report_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_dispatcher_availability_statistics"("requested_year" integer DEFAULT NULL::integer, "requested_month" integer DEFAULT NULL::integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  current_user_id uuid := auth.uid();
  current_permissions text[];
  summary_json jsonb;
  dispatcher_json jsonb;
  monthly_json jsonb;
begin
  if current_user_id is null then
    raise exception 'not authenticated';
  end if;

  if not exists (
    select 1
    from public.profiles profile
    where profile.id = current_user_id
      and profile.is_active = true
  ) then
    raise exception 'user not active';
  end if;

  current_permissions :=
    coalesce(public.get_my_permissions(), array[]::text[]);

  if not (
    'statistics.view' = any(current_permissions)
    or 'users.manage' = any(current_permissions)
  ) then
    raise exception 'not allowed';
  end if;

  if requested_month is not null
     and (requested_month < 1 or requested_month > 12) then
    raise exception 'statistics month is invalid';
  end if;

  if requested_year is not null
     and (requested_year < 2020 or requested_year > 2100) then
    raise exception 'statistics year is invalid';
  end if;

  if requested_month is not null and requested_year is null then
    raise exception 'statistics year is required when month is selected';
  end if;

  with selected_periods as (
    select period.*
    from public.availability_periods period
    where period.status = 'closed'
      and (requested_year is null or period.year = requested_year)
      and (requested_month is null or period.month = requested_month)
  ),
  period_dispatchers as (
    select
      period.id as period_id,
      period.year,
      period.month,
      profile.id as user_id,
      profile.display_name,
      profile.schedule_name,
      coalesce(submission.submission_source, 'auto_no_submission') as submission_source
    from selected_periods period
    cross join public.profiles profile
    left join public.availability_submissions submission
      on submission.period_id = period.id
     and submission.user_id = profile.id
    where profile.role::text = 'dispatcher'
      and profile.created_at < (make_date(period.year, period.month, 1) + interval '1 month')
      and (
        profile.deactivated_at is null
        or profile.deactivated_at >= make_date(period.year, period.month, 1)
      )
  ),
  entry_stats as (
    select
      base.period_id,
      base.year,
      base.month,
      base.user_id,
      base.display_name,
      base.schedule_name,
      base.submission_source,
      count(entry.id) filter (
        where entry.availability_status = 'available'
          and not entry.is_auto_completed
      )::integer as declared_available_count,
      count(entry.id) filter (
        where entry.availability_status = 'unavailable'
          and not entry.is_auto_completed
      )::integer as declared_unavailable_count,
      count(entry.id) filter (
        where entry.availability_status = 'available'
          and entry.is_auto_completed
      )::integer as auto_completed_available_count,
      count(entry.id) filter (
        where entry.availability_status = 'available'
          and not entry.is_auto_completed
          and slot.weekday_number = 5
          and slot.start_time < time '12:00'
      )::integer as friday_morning_available_count,
      count(entry.id) filter (
        where entry.availability_status = 'available'
          and not entry.is_auto_completed
          and slot.weekday_number = 5
          and slot.start_time >= time '12:00'
          and slot.start_time < time '21:00'
      )::integer as friday_afternoon_available_count,
      count(entry.id) filter (
        where entry.availability_status = 'available'
          and not entry.is_auto_completed
          and slot.weekday_number = 5
          and slot.start_time >= time '21:00'
      )::integer as friday_night_available_count,
      count(entry.id) filter (
        where entry.availability_status = 'available'
          and not entry.is_auto_completed
          and slot.weekday_number = 6
          and slot.start_time < time '12:00'
      )::integer as saturday_morning_available_count,
      count(entry.id) filter (
        where entry.availability_status = 'available'
          and not entry.is_auto_completed
          and slot.weekday_number = 6
          and slot.start_time >= time '12:00'
          and slot.start_time < time '21:00'
      )::integer as saturday_afternoon_available_count,
      count(entry.id) filter (
        where entry.availability_status = 'available'
          and not entry.is_auto_completed
          and slot.weekday_number = 6
          and slot.start_time >= time '21:00'
      )::integer as saturday_night_available_count,
      count(entry.id) filter (
        where entry.availability_status = 'available'
          and not entry.is_auto_completed
          and (slot.start_time >= time '21:00' or slot.start_time < time '06:00')
      )::integer as night_available_count,
      count(entry.id) filter (
        where entry.availability_status = 'available'
          and not entry.is_auto_completed
          and slot.is_premium = true
      )::integer as premium_available_count,
      count(entry.id) filter (
        where entry.availability_status = 'available'
          and not entry.is_auto_completed
          and slot.schedule_type in ('holiday_eve', 'holiday_full', 'holiday_end', 'chol_hamoed')
      )::integer as holiday_available_count,
      count(entry.id) filter (
        where entry.availability_status = 'available'
          and not entry.is_auto_completed
          and slot.weekday_number in (5, 6)
      )::integer as weekend_available_count
    from period_dispatchers base
    left join public.dispatcher_availability entry
      on entry.period_id = base.period_id
     and entry.user_id = base.user_id
    left join public.availability_shift_slots slot
      on slot.id = entry.shift_slot_id
    group by
      base.period_id, base.year, base.month, base.user_id,
      base.display_name, base.schedule_name, base.submission_source
  ),
  dispatcher_totals as (
    select
      user_id,
      display_name,
      schedule_name,
      count(*)::integer as period_count,
      count(*) filter (where submission_source = 'manual')::integer as manual_submission_periods,
      count(*) filter (where submission_source = 'auto_partial')::integer as auto_partial_periods,
      count(*) filter (where submission_source = 'auto_no_submission')::integer as no_submission_periods,
      sum(declared_available_count)::integer as declared_available_count,
      sum(declared_unavailable_count)::integer as declared_unavailable_count,
      sum(auto_completed_available_count)::integer as auto_completed_available_count,
      sum(friday_morning_available_count)::integer as friday_morning_available_count,
      sum(friday_afternoon_available_count)::integer as friday_afternoon_available_count,
      sum(friday_night_available_count)::integer as friday_night_available_count,
      sum(saturday_morning_available_count)::integer as saturday_morning_available_count,
      sum(saturday_afternoon_available_count)::integer as saturday_afternoon_available_count,
      sum(saturday_night_available_count)::integer as saturday_night_available_count,
      sum(night_available_count)::integer as night_available_count,
      sum(premium_available_count)::integer as premium_available_count,
      sum(holiday_available_count)::integer as holiday_available_count,
      sum(weekend_available_count)::integer as weekend_available_count
    from entry_stats
    group by user_id, display_name, schedule_name
  )
  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'userId', user_id,
        'displayName', display_name,
        'scheduleName', schedule_name,
        'periodCount', period_count,
        'manualSubmissionPeriods', manual_submission_periods,
        'autoPartialPeriods', auto_partial_periods,
        'noSubmissionPeriods', no_submission_periods,
        'declaredAvailableCount', declared_available_count,
        'declaredUnavailableCount', declared_unavailable_count,
        'autoCompletedAvailableCount', auto_completed_available_count,
        'declaredAvailabilityRate',
          case
            when declared_available_count + declared_unavailable_count = 0 then 0
            else round(
              declared_available_count::numeric * 1000
              / (declared_available_count + declared_unavailable_count)
            ) / 10
          end,
        'fridayMorningAvailableCount', friday_morning_available_count,
        'fridayAfternoonAvailableCount', friday_afternoon_available_count,
        'fridayNightAvailableCount', friday_night_available_count,
        'saturdayMorningAvailableCount', saturday_morning_available_count,
        'saturdayAfternoonAvailableCount', saturday_afternoon_available_count,
        'saturdayNightAvailableCount', saturday_night_available_count,
        'nightAvailableCount', night_available_count,
        'premiumAvailableCount', premium_available_count,
        'holidayAvailableCount', holiday_available_count,
        'weekendAvailableCount', weekend_available_count
      )
      order by declared_available_count desc, display_name
    ),
    '[]'::jsonb
  )
  into dispatcher_json
  from dispatcher_totals;

  with selected_periods as (
    select period.*
    from public.availability_periods period
    where period.status = 'closed'
      and (requested_year is null or period.year = requested_year)
      and (requested_month is null or period.month = requested_month)
  ),
  stats as (
    select
      period.id as period_id, period.year, period.month,
      profile.id as user_id, profile.display_name, profile.schedule_name,
      coalesce(submission.submission_source, 'auto_no_submission') as submission_source,
      count(entry.id) filter (where entry.availability_status = 'available' and not entry.is_auto_completed)::integer as declared_available_count,
      count(entry.id) filter (where entry.availability_status = 'unavailable' and not entry.is_auto_completed)::integer as declared_unavailable_count,
      count(entry.id) filter (where entry.availability_status = 'available' and entry.is_auto_completed)::integer as auto_completed_available_count,
      count(entry.id) filter (where entry.availability_status = 'available' and not entry.is_auto_completed and slot.weekday_number = 5 and slot.start_time < time '12:00')::integer as friday_morning_available_count,
      count(entry.id) filter (where entry.availability_status = 'available' and not entry.is_auto_completed and (slot.start_time >= time '21:00' or slot.start_time < time '06:00'))::integer as night_available_count,
      count(entry.id) filter (where entry.availability_status = 'available' and not entry.is_auto_completed and slot.is_premium = true)::integer as premium_available_count
    from selected_periods period
    cross join public.profiles profile
    left join public.availability_submissions submission
      on submission.period_id = period.id and submission.user_id = profile.id
    left join public.dispatcher_availability entry
      on entry.period_id = period.id and entry.user_id = profile.id
    left join public.availability_shift_slots slot on slot.id = entry.shift_slot_id
    where profile.role::text = 'dispatcher' and profile.is_active = true
    group by period.id, period.year, period.month, profile.id, profile.display_name, profile.schedule_name, submission.submission_source
  )
  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'userId', user_id,
        'displayName', display_name,
        'scheduleName', schedule_name,
        'year', year,
        'month', month,
        'submissionSource', submission_source,
        'declaredAvailableCount', declared_available_count,
        'declaredUnavailableCount', declared_unavailable_count,
        'autoCompletedAvailableCount', auto_completed_available_count,
        'fridayMorningAvailableCount', friday_morning_available_count,
        'nightAvailableCount', night_available_count,
        'premiumAvailableCount', premium_available_count
      )
      order by year, month, display_name
    ),
    '[]'::jsonb
  )
  into monthly_json
  from stats;

  select jsonb_build_object(
    'periodCount', (
      select count(*)::integer from public.availability_periods period
      where period.status = 'closed'
        and (requested_year is null or period.year = requested_year)
        and (requested_month is null or period.month = requested_month)
    ),
    'dispatcherCount', jsonb_array_length(dispatcher_json),
    'manualSubmissionPeriods', coalesce((select sum((item ->> 'manualSubmissionPeriods')::integer) from jsonb_array_elements(dispatcher_json) item), 0),
    'autoPartialPeriods', coalesce((select sum((item ->> 'autoPartialPeriods')::integer) from jsonb_array_elements(dispatcher_json) item), 0),
    'noSubmissionPeriods', coalesce((select sum((item ->> 'noSubmissionPeriods')::integer) from jsonb_array_elements(dispatcher_json) item), 0),
    'declaredAvailableCount', coalesce((select sum((item ->> 'declaredAvailableCount')::integer) from jsonb_array_elements(dispatcher_json) item), 0),
    'declaredUnavailableCount', coalesce((select sum((item ->> 'declaredUnavailableCount')::integer) from jsonb_array_elements(dispatcher_json) item), 0),
    'autoCompletedAvailableCount', coalesce((select sum((item ->> 'autoCompletedAvailableCount')::integer) from jsonb_array_elements(dispatcher_json) item), 0),
    'fridayMorningAvailableCount', coalesce((select sum((item ->> 'fridayMorningAvailableCount')::integer) from jsonb_array_elements(dispatcher_json) item), 0),
    'nightAvailableCount', coalesce((select sum((item ->> 'nightAvailableCount')::integer) from jsonb_array_elements(dispatcher_json) item), 0),
    'premiumAvailableCount', coalesce((select sum((item ->> 'premiumAvailableCount')::integer) from jsonb_array_elements(dispatcher_json) item), 0),
    'holidayAvailableCount', coalesce((select sum((item ->> 'holidayAvailableCount')::integer) from jsonb_array_elements(dispatcher_json) item), 0)
  ) into summary_json;

  return jsonb_build_object(
    'summary', summary_json,
    'dispatcherStatistics', dispatcher_json,
    'monthlyBreakdown', monthly_json,
    'generatedAt', now()
  );
end;
$$;


ALTER FUNCTION "public"."get_dispatcher_availability_statistics"("requested_year" integer, "requested_month" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_dispatcher_schedule_by_month"("requested_year" integer, "requested_month" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  requesting_user_id uuid;

  current_permissions text[];

  selected_period
    public.schedule_periods%rowtype;

  can_view_team boolean :=
    false;

  can_view_personal boolean :=
    false;
begin
  requesting_user_id :=
    auth.uid();


  if requesting_user_id
    is null
  then
    raise exception
      'Authentication is required.';
  end if;


  if not exists (
    select 1

    from public.profiles

    where id =
        requesting_user_id

      and is_active = true
  ) then
    raise exception
      'Active user profile was not found.';
  end if;


  current_permissions :=
    coalesce(
      public.get_my_permissions(),
      array[]::text[]
    );


  can_view_team :=
    (
      'schedule.view_team' =
        any(current_permissions)

      or

      'schedule.edit' =
        any(current_permissions)
    );


  can_view_personal :=
    (
      'schedule.view' =
        any(current_permissions)
    );


  if not (
    can_view_team
    or can_view_personal
  ) then
    raise exception
      'not allowed';
  end if;


  if requested_year < 2020
    or requested_year > 2100
  then
    raise exception
      'Invalid schedule year.';
  end if;


  if requested_month < 1
    or requested_month > 12
  then
    raise exception
      'Invalid schedule month.';
  end if;


  select *
  into selected_period

  from public.schedule_periods

  where year =
      requested_year

    and month =
      requested_month

  limit 1;


  if not found then
    return jsonb_build_object(
      'period',
        null,

      'shifts',
        '[]'::jsonb
    );
  end if;


  /*
   * משתמש שרואה רק את הלוח האישי לא מקבל
   * טיוטה או חודש שעדיין לא פורסם.
   */
  if (
    not can_view_team

    and selected_period.status
      not in (
        'published',
        'archived'
      )
  ) then
    return jsonb_build_object(
      'period',
        null,

      'shifts',
        '[]'::jsonb
    );
  end if;


  return jsonb_build_object(

    'period',
      jsonb_build_object(

        'id',
          selected_period.id,

        'year',
          selected_period.year,

        'month',
          selected_period.month,

        'status',
          selected_period.status,

        'publishedAt',
          selected_period.published_at,

        'createdAt',
          selected_period.created_at,

        'updatedAt',
          selected_period.updated_at
      ),


    'shifts',
      coalesce(
        (
          select jsonb_agg(

            jsonb_build_object(

              'id',
                shift.id,

              'periodId',
                shift.period_id,

              'shiftDate',
                shift.shift_date,

              'startsAt',
                shift.starts_at,

              'endsAt',
                shift.ends_at,

              'shiftCode',
                shift.shift_code,

              'scheduleType',
                shift.schedule_type,

              'isPremium',
                shift.is_premium,

              'holidayName',
                shift.holiday_name,

              'assignedUserId',
                shift.assigned_user_id,

              'assignedUserName',
                coalesce(
                  assigned_profile.schedule_name,
                  assigned_profile.display_name
                ),

              'isIntentionallyUnassigned',
                shift.is_intentionally_unassigned,

              'isLocked',
                shift.is_locked,

              'notes',
                shift.notes
            )

            /*
             * סדר כרונולוגי אמיתי.
             */
            order by
              shift.shift_date asc,
              shift.starts_at asc
          )


          from public.schedule_shifts
            shift


          left join public.profiles
            assigned_profile

            on assigned_profile.id =
              shift.assigned_user_id


          where shift.period_id =
              selected_period.id

            and (
              can_view_team

              or shift.assigned_user_id =
                requesting_user_id
            )
        ),

        '[]'::jsonb
      )
  );
end;
$$;


ALTER FUNCTION "public"."get_dispatcher_schedule_by_month"("requested_year" integer, "requested_month" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_driver_availability_management"("requested_period_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  current_user_id uuid;
  current_permissions text[];

  target_period
    public.driver_availability_periods%rowtype;

  days_json jsonb :=
    '[]'::jsonb;

  drivers_json jsonb :=
    '[]'::jsonb;

  submissions_json jsonb :=
    '[]'::jsonb;

  entries_json jsonb :=
    '[]'::jsonb;
begin
  current_user_id :=
    auth.uid();

  if current_user_id is null then
    raise exception
      'not authenticated';
  end if;

  if not exists (
    select 1
    from public.profiles
    where id =
      current_user_id
      and is_active = true
  ) then
    raise exception
      'user not active';
  end if;

  current_permissions :=
    coalesce(
      public.get_my_permissions(),
      array[]::text[]
    );

  if not (
    'driver_availability.manage' =
      any(current_permissions)
  ) then
    raise exception
      'not allowed';
  end if;

  if requested_period_id is null then
    raise exception
      'driver availability period id is required';
  end if;

  select *
  into target_period
  from public.driver_availability_periods
  where id =
    requested_period_id;

  if not found then
    raise exception
      'driver availability period not found';
  end if;

  select
    coalesce(
      jsonb_agg(
        jsonb_build_object(
          'id',
            day_row.id,

          'periodId',
            day_row.period_id,

          'availabilityDate',
            day_row.availability_date,

          'weekdayNumber',
            day_row.weekday_number,

          'weekdayName',
            day_row.weekday_name,

          'sortOrder',
            day_row.sort_order,

          'createdAt',
            day_row.created_at,

          'holidayName',
            (
              select string_agg(holiday.name, ' / ' order by holiday.name)
              from public.holidays holiday
              where holiday.holiday_date = day_row.availability_date
            ),

          'holidayScheduleType',
            (
              select holiday.schedule_type::text
              from public.holidays holiday
              where holiday.holiday_date = day_row.availability_date
              order by
                case holiday.schedule_type::text
                  when 'holiday_full' then 1
                  when 'holiday_eve' then 2
                  when 'holiday_end' then 3
                  when 'chol_hamoed' then 4
                  else 5
                end,
                holiday.name
              limit 1
            )
        )
        order by
          day_row.availability_date
      ),
      '[]'::jsonb
    )
  into days_json
  from public.driver_availability_days
    day_row
  where day_row.period_id =
    target_period.id;

  select
    coalesce(
      jsonb_agg(
        jsonb_build_object(
          'id',
            profile.id,

          'displayName',
            profile.display_name,

          'scheduleName',
            profile.schedule_name,

          'email',
            profile.email,

          'role',
            profile.role::text,

          'isActive',
            profile.is_active
        )
        order by
          coalesce(
            profile.schedule_name,
            profile.display_name
          )
      ),
      '[]'::jsonb
    )
  into drivers_json
  from public.profiles
    profile
  where profile.role =
    'on_call'::public.user_role
    and profile.is_active = true;

  select
    coalesce(
      jsonb_agg(
        jsonb_build_object(
          'id',
            submission.id,

          'periodId',
            submission.period_id,

          'userId',
            submission.user_id,

          'status',
            submission.status,

          'submittedAt',
            submission.submitted_at,

          'reopenedAt',
            submission.reopened_at,

          'lastSavedAt',
            submission.last_saved_at,

          'availableCount',
            submission.available_count,

          'unavailableCount',
            submission.unavailable_count,

          'createdAt',
            submission.created_at,

          'updatedAt',
            submission.updated_at
        )
        order by
          submission.user_id
      ),
      '[]'::jsonb
    )
  into submissions_json
  from public.driver_availability_submissions
    submission
  where submission.period_id =
    target_period.id;

  select
    coalesce(
      jsonb_agg(
        jsonb_build_object(
          'id',
            entry.id,

          'periodId',
            entry.period_id,

          'dayId',
            entry.day_id,

          'userId',
            entry.user_id,

          'availabilityStatus',
            entry.availability_status,

          'note',
            entry.note,

          'createdAt',
            entry.created_at,

          'updatedAt',
            entry.updated_at
        )
        order by
          day_row.availability_date,
          entry.user_id
      ),
      '[]'::jsonb
    )
  into entries_json
  from public.driver_availability_entries
    entry
  join public.driver_availability_days
    day_row
    on day_row.id =
      entry.day_id
  where entry.period_id =
    target_period.id;

  return jsonb_build_object(
    'period',
      jsonb_build_object(
        'id',
          target_period.id,

        'year',
          target_period.year,

        'month',
          target_period.month,

        'status',
          target_period.status,

        'title',
          target_period.title,

        'instructions',
          target_period.instructions,

        'submissionDeadline',
          target_period.submission_deadline,

        'openedAt',
          target_period.opened_at,

        'closedAt',
          target_period.closed_at,

        'createdBy',
          target_period.created_by,

        'updatedBy',
          target_period.updated_by,

        'createdAt',
          target_period.created_at,

        'updatedAt',
          target_period.updated_at
      ),

    'days',
      days_json,

    'drivers',
      drivers_json,

    'submissions',
      submissions_json,

    'entries',
      entries_json,

    'statistics',
      jsonb_build_object(
        'totalDrivers',
          jsonb_array_length(
            drivers_json
          ),

        'submittedDrivers',
          (
            select
              count(*)::integer
            from public.driver_availability_submissions
            where period_id =
              target_period.id
              and status =
                'submitted'
          ),

        'draftDrivers',
          (
            select
              count(*)::integer
            from public.driver_availability_submissions
            where period_id =
              target_period.id
              and status in (
                'draft',
                'reopened'
              )
          ),

        'notStartedDrivers',
          greatest(
            jsonb_array_length(
              drivers_json
            ) -
            (
              select
                count(
                  distinct user_id
                )::integer
              from public.driver_availability_submissions
              where period_id =
                target_period.id
            ),
            0
          )
      )
  );
end;
$$;


ALTER FUNCTION "public"."get_driver_availability_management"("requested_period_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_driver_availability_management"("requested_period_id" "uuid") IS 'Returns the selected driver availability period, active on-call users, submissions and daily availability matrix. Requires driver_availability.manage.';



CREATE OR REPLACE FUNCTION "public"."get_driver_availability_periods"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  current_user_id uuid;

  current_permissions text[];

  can_view boolean := false;
  can_manage boolean := false;

  periods_json jsonb :=
    '[]'::jsonb;
begin
  current_user_id :=
    auth.uid();

  if current_user_id is null then
    raise exception
      'not authenticated';
  end if;

  if not exists (
    select 1
    from public.profiles
    where id = current_user_id
      and is_active = true
  ) then
    raise exception
      'user not active';
  end if;

  current_permissions :=
    coalesce(
      public.get_my_permissions(),
      array[]::text[]
    );

  can_view :=
    'driver_availability.view' =
      any(current_permissions);

  can_manage :=
    'driver_availability.manage' =
      any(current_permissions);

  if not (
    can_view or
    can_manage
  ) then
    raise exception
      'not allowed';
  end if;

  select
    coalesce(
      jsonb_agg(
        jsonb_build_object(
          'id',
            period.id,

          'year',
            period.year,

          'month',
            period.month,

          'status',
            period.status,

          'title',
            period.title,

          'instructions',
            period.instructions,

          'submissionDeadline',
            period.submission_deadline,

          'openedAt',
            period.opened_at,

          'closedAt',
            period.closed_at,

          'createdBy',
            period.created_by,

          'updatedBy',
            period.updated_by,

          'createdAt',
            period.created_at,

          'updatedAt',
            period.updated_at,

          'daysCount',
            (
              select
                count(*)::integer
              from public.driver_availability_days day_row
              where day_row.period_id =
                period.id
            ),

          'submissionsCount',
            (
              select
                count(*)::integer
              from public.driver_availability_submissions submission
              where submission.period_id =
                period.id
            ),

          'submittedCount',
            (
              select
                count(*)::integer
              from public.driver_availability_submissions submission
              where submission.period_id =
                period.id
                and submission.status =
                  'submitted'
            )
        )
        order by
          period.year desc,
          period.month desc
      ),
      '[]'::jsonb
    )
  into periods_json
  from public.driver_availability_periods period
  where
    can_manage
    or
    (
      can_view
      and period.status in (
        'open',
        'closed'
      )
    );

  return periods_json;
end;
$$;


