COMMENT ON FUNCTION "public"."get_driver_availability_periods"() IS 'Returns driver availability periods. Managers see all periods; regular on-call users see open and closed periods.';



CREATE OR REPLACE FUNCTION "public"."get_driver_schedule_draft"("requested_schedule_period_id" "uuid" DEFAULT NULL::"uuid", "requested_year" integer DEFAULT NULL::integer, "requested_month" integer DEFAULT NULL::integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  current_user_id uuid;
  current_permissions text[];

  target_period
    public.driver_schedule_periods%rowtype;

  days_json jsonb :=
    '[]'::jsonb;

  drivers_json jsonb :=
    '[]'::jsonb;

  assigned_days_count integer := 0;
  unassigned_days_count integer := 0;
  warning_count integer := 0;
begin
  current_user_id :=
    auth.uid();

  if current_user_id is null then
    raise exception
      'not authenticated';
  end if;

  if not exists (
    select 1
    from public.profiles
    where id =
      current_user_id
      and is_active = true
  ) then
    raise exception
      'user not active';
  end if;

  current_permissions :=
    coalesce(
      public.get_my_permissions(),
      array[]::text[]
    );

  if not (
    'driver_schedule.view' =
      any(current_permissions)
    or
    'driver_schedule.view_team' =
      any(current_permissions)
    or
    'driver_schedule.edit' =
      any(current_permissions)
    or
    'driver_schedule.edit_any' =
      any(current_permissions)
  ) then
    raise exception
      'not allowed';
  end if;

  if requested_schedule_period_id
    is not null
  then
    select *
    into target_period
    from public.driver_schedule_periods
    where id =
      requested_schedule_period_id
    limit 1;
  elsif (
    requested_year is not null
    and requested_month is not null
  ) then
    select *
    into target_period
    from public.driver_schedule_periods
    where year =
      requested_year
      and month =
        requested_month
    limit 1;
  else
    select *
    into target_period
    from public.driver_schedule_periods
    order by
      year desc,
      month desc,
      created_at desc
    limit 1;
  end if;

  if not found then
    return jsonb_build_object(
      'period',
        null,

      'days',
        '[]'::jsonb,

      'drivers',
        '[]'::jsonb,

      'statistics',
        jsonb_build_object(
          'totalDays',
            0,

          'assignedDays',
            0,

          'unassignedDays',
            0,

          'warningCount',
            0
        )
    );
  end if;

  select
    count(*) filter (
      where assigned_user_id
        is not null
    )::integer,

    count(*) filter (
      where assigned_user_id
        is null
    )::integer,

    count(*) filter (
      where notes is not null
    )::integer

  into
    assigned_days_count,
    unassigned_days_count,
    warning_count

  from public.driver_schedule_days
  where period_id =
    target_period.id;

  select
    coalesce(
      jsonb_agg(
        jsonb_build_object(
          'id',
            schedule_day.id,

          'periodId',
            schedule_day.period_id,

          'dutyDate',
            schedule_day.duty_date,

          'weekdayNumber',
            schedule_day.weekday_number,

          'weekdayName',
            schedule_day.weekday_name,

          'originalUserId',
            schedule_day.original_user_id,

          'originalUserName',
            coalesce(
              original_profile.schedule_name,
              original_profile.display_name
            ),

          'assignedUserId',
            schedule_day.assigned_user_id,

          'assignedUserName',
            coalesce(
              assigned_profile.schedule_name,
              assigned_profile.display_name
            ),

          'assignmentSource',
            schedule_day.assignment_source,

          'isLocked',
            schedule_day.is_locked,

          'notes',
            schedule_day.notes,

          'spacingWarning',
            schedule_day.notes
              is not null,

          'createdAt',
            schedule_day.created_at,

          'updatedAt',
            schedule_day.updated_at
        )
        order by
          schedule_day.duty_date
      ),
      '[]'::jsonb
    )
  into days_json
  from public.driver_schedule_days
    schedule_day

  left join public.profiles
    original_profile
    on original_profile.id =
      schedule_day.original_user_id

  left join public.profiles
    assigned_profile
    on assigned_profile.id =
      schedule_day.assigned_user_id

  where schedule_day.period_id =
    target_period.id

    and (
      'driver_schedule.view_team' =
        any(current_permissions)

      or

      'driver_schedule.edit' =
        any(current_permissions)

      or

      'driver_schedule.edit_any' =
        any(current_permissions)

      or

      schedule_day.assigned_user_id =
        current_user_id
    );

  select
    coalesce(
      jsonb_agg(
        jsonb_build_object(
          'id',
            profile.id,

          'displayName',
            profile.display_name,

          'scheduleName',
            profile.schedule_name,

          'email',
            profile.email,

          'isActive',
            profile.is_active
        )
        order by
          coalesce(
            profile.schedule_name,
            profile.display_name
          )
      ),
      '[]'::jsonb
    )
  into drivers_json
  from public.profiles
    profile
  where profile.role =
    'on_call'::public.user_role
    and (
      profile.is_active = true
      or exists (
        select 1
        from public.driver_schedule_days historical_day
        where historical_day.period_id = target_period.id
          and historical_day.assigned_user_id = profile.id
      )
      or exists (
        select 1
        from public.driver_schedule_days historical_day
        where historical_day.period_id = target_period.id
          and historical_day.original_user_id = profile.id
      )
    );

  return jsonb_build_object(
    'period',
      jsonb_build_object(
        'id',
          target_period.id,

        'year',
          target_period.year,

        'month',
          target_period.month,

        'status',
          target_period.status,

        'availabilityPeriodId',
          target_period.availability_period_id,

        'title',
          target_period.title,

        'publishedAt',
          target_period.published_at,

        'archivedAt',
          target_period.archived_at,

        'createdBy',
          target_period.created_by,

        'updatedBy',
          target_period.updated_by,

        'createdAt',
          target_period.created_at,

        'updatedAt',
          target_period.updated_at
      ),

    'days',
      days_json,

    'drivers',
      drivers_json,

    'statistics',
      jsonb_build_object(
        'totalDays',
          assigned_days_count +
          unassigned_days_count,

        'assignedDays',
          assigned_days_count,

        'unassignedDays',
          unassigned_days_count,

        'warningCount',
          warning_count
      )
  );
end;
$$;


ALTER FUNCTION "public"."get_driver_schedule_draft"("requested_schedule_period_id" "uuid", "requested_year" integer, "requested_month" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_driver_schedule_draft"("requested_schedule_period_id" "uuid", "requested_year" integer, "requested_month" integer) IS 'Loads an on-call schedule period with schedule days, assigned driver names, active drivers and summary statistics. Personal viewers receive only their assigned days; team viewers and editors receive the full schedule.';



CREATE OR REPLACE FUNCTION "public"."get_dynamic_archive_periods"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_actor uuid:=auth.uid();
begin
 if v_actor is null then raise exception 'not authenticated'; end if;
 if not (exists(select 1 from public.user_permissions up where up.user_id=v_actor and up.permission_key in ('users.view','users.manage'))
         or exists(select 1 from public.job_type_managers jm where jm.user_id=v_actor))
 then raise exception 'not allowed'; end if;
 return jsonb_build_object('generatedAt',now(),'periods',coalesce((
  with months as (
   select p.year,p.month from public.dynamic_schedule_publications p
   where make_date(p.year,p.month,1)<date_trunc('month',timezone('Asia/Jerusalem',now()))::date
   union
   select r.year,r.month from public.monthly_schedule_archive_runs r
   where r.status='sent' and make_date(r.year,r.month,1)<date_trunc('month',timezone('Asia/Jerusalem',now()))::date
  ), role_rows as (
   select p.year,p.month,p.id publication_id,p.job_type_id,jt.name job_type_name,p.status,p.published_at,p.updated_at,
          count(a.id)::integer assignment_count,count(distinct a.user_id)::integer worker_count
   from public.dynamic_schedule_publications p join public.job_types jt on jt.id=p.job_type_id
   left join public.dynamic_schedule_published_assignments a on a.publication_id=p.id
   where make_date(p.year,p.month,1)<date_trunc('month',timezone('Asia/Jerusalem',now()))::date
   group by p.year,p.month,p.id,p.job_type_id,jt.name,p.status,p.published_at,p.updated_at
  )
  select jsonb_agg(jsonb_build_object(
   'year',m.year,'month',m.month,
   'isFullyArchived',not exists(select 1 from role_rows x where x.year=m.year and x.month=m.month and x.status<>'archived')
     and (exists(select 1 from role_rows x where x.year=m.year and x.month=m.month)
       or exists(select 1 from public.monthly_schedule_archive_runs ar where ar.year=m.year and ar.month=m.month and ar.status='sent')),
   'archivedAt',coalesce(
     (select max(x.updated_at) from role_rows x where x.year=m.year and x.month=m.month and x.status='archived'),
     (select max(ar.sent_at) from public.monthly_schedule_archive_runs ar where ar.year=m.year and ar.month=m.month and ar.status='sent')),
   'archiveRun',(select jsonb_build_object('id',ar.id,'status',ar.status,'fileName',ar.file_name,'emailId',ar.email_id,
      'sentAt',ar.sent_at,'attemptCount',ar.attempt_count)
      from public.monthly_schedule_archive_runs ar where ar.year=m.year and ar.month=m.month and ar.status='sent'
      order by ar.sent_at desc nulls last,ar.updated_at desc limit 1),
   'jobTypes',coalesce((select jsonb_agg(jsonb_build_object(
      'publicationId',r.publication_id,'jobTypeId',r.job_type_id,'jobTypeName',r.job_type_name,'status',r.status,
      'assignmentCount',r.assignment_count,'workerCount',r.worker_count,'publishedAt',r.published_at,
      'archivedAt',case when r.status='archived' then r.updated_at else null end) order by r.job_type_name)
      from role_rows r where r.year=m.year and r.month=m.month),'[]'::jsonb)
  ) order by m.year desc,m.month desc) from months m
 ),'[]'::jsonb));
end;$$;


ALTER FUNCTION "public"."get_dynamic_archive_periods"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_dynamic_attendance_statistics"("requested_job_type_id" "uuid", "requested_years" integer[] DEFAULT NULL::integer[], "requested_months" integer[] DEFAULT NULL::integer[], "requested_user_ids" "uuid"[] DEFAULT NULL::"uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare uid uuid:=auth.uid();
begin
 if uid is null then raise exception 'not authenticated'; end if;
 if not (public.has_dynamic_job_type_permission('attendance.view_team',requested_job_type_id,uid) or public.has_dynamic_job_type_permission('statistics.view_job_type',requested_job_type_id,uid) or exists(select 1 from public.user_permissions up where up.user_id=uid and up.permission_key in('statistics.view','users.manage'))) then raise exception 'not allowed'; end if;
 return jsonb_build_object('rows',coalesce((select jsonb_agg(jsonb_build_object(
   'id',s.id,'userId',s.user_id,'displayName',p.display_name,'scheduleName',p.schedule_name,'workDate',s.work_date,
   'clockInAt',s.clock_in_at,'clockInLat',s.clock_in_lat,'clockInLng',s.clock_in_lng,'clockInDistanceM',s.clock_in_distance_m,'clockInWithinRadius',s.clock_in_within_radius,
   'clockOutAt',s.clock_out_at,'clockOutLat',s.clock_out_lat,'clockOutLng',s.clock_out_lng,'clockOutDistanceM',s.clock_out_distance_m,'clockOutWithinRadius',s.clock_out_within_radius,
   'workedHours',case when s.clock_out_at is null then null else round((extract(epoch from(s.clock_out_at-s.clock_in_at))/3600)::numeric,2) end,
   'hourlyRate',s.hourly_rate_snapshot,'wage',case when s.clock_out_at is null or s.hourly_rate_snapshot is null then null else round((extract(epoch from(s.clock_out_at-s.clock_in_at))/3600*s.hourly_rate_snapshot)::numeric,2) end
 ) order by s.work_date desc,s.clock_in_at desc) from public.attendance_sessions s join public.profiles p on p.id=s.user_id where s.job_type_id=requested_job_type_id
 and(requested_years is null or cardinality(requested_years)=0 or extract(year from s.work_date)::int=any(requested_years))
 and(requested_months is null or cardinality(requested_months)=0 or extract(month from s.work_date)::int=any(requested_months))
 and(requested_user_ids is null or cardinality(requested_user_ids)=0 or s.user_id=any(requested_user_ids))),'[]'::jsonb));
end; $$;


ALTER FUNCTION "public"."get_dynamic_attendance_statistics"("requested_job_type_id" "uuid", "requested_years" integer[], "requested_months" integer[], "requested_user_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_dynamic_availability_shadow_summary"("requested_job_type_id" "uuid", "requested_year" integer, "requested_month" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  current_user_id uuid := auth.uid();
  target_job public.job_types%rowtype;
  period_row public.dynamic_availability_periods%rowtype;
begin
  if current_user_id is null then raise exception 'not authenticated'; end if;
  if not exists (select 1 from public.user_permissions up where up.user_id=current_user_id and up.permission_key in ('users.view','users.manage')) then
    raise exception 'not allowed';
  end if;
  select * into target_job from public.job_types where id=requested_job_type_id;
  if target_job.id is null then raise exception 'job type not found'; end if;
  select * into period_row from public.dynamic_availability_periods where job_type_id=requested_job_type_id and year=requested_year and month=requested_month;

  return jsonb_build_object(
    'jobTypeId', target_job.id,
    'jobTypeName', target_job.name,
    'availabilityConfig', target_job.availability_config,
    'periodId', period_row.id,
    'materialized', period_row.id is not null,
    'slotCount', case when period_row.id is null then 0 else (select count(*) from public.dynamic_availability_slots s where s.period_id=period_row.id) end,
    'memberCount', (select count(*) from public.job_type_memberships m where m.job_type_id=target_job.id),
    'submissionCount', case when period_row.id is null then 0 else (select count(*) from public.dynamic_availability_submissions s where s.period_id=period_row.id) end,
    'mode', 'shadow'
  );
end;
$$;


ALTER FUNCTION "public"."get_dynamic_availability_shadow_summary"("requested_job_type_id" "uuid", "requested_year" integer, "requested_month" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_dynamic_availability_shadow_workspace"("requested_job_type_id" "uuid", "requested_year" integer, "requested_month" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  current_user_id uuid := auth.uid();
  job public.job_types%rowtype;
  period public.dynamic_availability_periods%rowtype;
  normalized_config jsonb;
begin
  if current_user_id is null then raise exception 'not authenticated'; end if;
  if not exists(select 1 from public.user_permissions up where up.user_id=current_user_id and up.permission_key in ('users.view','users.manage')) then raise exception 'not allowed'; end if;
  select * into job from public.job_types where id=requested_job_type_id;
  if job.id is null then raise exception 'job type not found'; end if;
  select * into period from public.dynamic_availability_periods where job_type_id=job.id and year=requested_year and month=requested_month;

  normalized_config := jsonb_build_object(
    'enabled', coalesce((job.availability_config->>'enabled')::boolean,true),
    'statuses', case when jsonb_typeof(job.availability_config->'statuses')='array' and jsonb_array_length(job.availability_config->'statuses')>0 then job.availability_config->'statuses' else '["available","unavailable"]'::jsonb end,
    'allowNotes', coalesce((job.availability_config->>'allowNotes')::boolean,true),
    'monthlyCapacity', coalesce(job.availability_config->'monthlyCapacity','{"enabled":false,"minEnabled":false,"targetEnabled":false,"maxEnabled":false,"defaultMin":null,"defaultTarget":null,"defaultMax":null}'::jsonb),
    'limits', coalesce(job.availability_config->'limits','{"maxNightsEnabled":false,"defaultMaxNights":null,"maxWeekendsEnabled":false,"defaultMaxWeekends":null,"maxHolidaysEnabled":false,"defaultMaxHolidays":null}'::jsonb)
  );

  return jsonb_build_object(
    'materialized', period.id is not null,'mode','shadow','periodId',period.id,'jobTypeId',job.id,'jobTypeName',job.name,
    'availabilityConfig',normalized_config,
    'slots',case when period.id is null then '[]'::jsonb else coalesce((select jsonb_agg(jsonb_build_object('id',s.id,'date',s.shift_date,'shiftCode',s.shift_code,'shiftName',s.shift_name,'startTime',s.start_time,'endTime',s.end_time,'holidayName',s.holiday_name,'sourceDayKind',s.source_day_kind,'effectiveDayKind',s.effective_day_kind,'minWorkers',s.min_workers,'targetWorkers',s.target_workers,'maxWorkers',s.max_workers) order by s.shift_date,s.start_time,s.shift_code) from public.dynamic_availability_slots s where s.period_id=period.id),'[]'::jsonb) end,
    'members',coalesce((select jsonb_agg(jsonb_build_object('userId',m.user_id,'displayName',p.display_name,'isActive',p.is_active,'submissionId',sub.id,'status',coalesce(sub.status,'draft'),'minimum',sub.min_shifts,'target',sub.target_shifts,'maximum',sub.max_shifts,'maxNights',sub.max_nights,'maxWeekends',sub.max_weekends,'maxHolidays',sub.max_holidays,'note',sub.note,'entries',coalesce((select jsonb_object_agg(e.slot_id::text,jsonb_build_object('status',e.availability_status,'note',e.note)) from public.dynamic_availability_entries e where e.submission_id=sub.id),'{}'::jsonb)) order by p.is_active desc,p.display_name) from public.job_type_memberships m join public.profiles p on p.id=m.user_id left join public.dynamic_availability_submissions sub on sub.period_id=period.id and sub.user_id=m.user_id where m.job_type_id=job.id),'[]'::jsonb)
  );
end;
$$;


ALTER FUNCTION "public"."get_dynamic_availability_shadow_workspace"("requested_job_type_id" "uuid", "requested_year" integer, "requested_month" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_dynamic_cutover_state"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_enabled boolean := false;
  v_legacy_frozen boolean := false;
  v_user uuid := auth.uid();
  v_has_membership boolean := false;
  v_is_system_admin boolean := false;
  v_is_job_type_manager boolean := false;
  v_use_dynamic boolean := false;
begin
  select coalesce(dynamic_first_enabled, false), coalesce(legacy_frozen, false)
    into v_enabled, v_legacy_frozen
  from public.dynamic_cutover_settings
  where singleton = true;

  if v_user is not null then
    select exists(
      select 1
      from public.job_type_memberships m
      join public.job_types jt
        on jt.id = m.job_type_id
       and jt.is_active = true
       and jt.legacy_role is null
      where m.user_id = v_user
    ) into v_has_membership;

    select exists(
      select 1 from public.profiles p
      where p.id = v_user and p.role = 'admin' and p.is_active = true
    ) into v_is_system_admin;

    select exists(
      select 1
      from public.job_type_managers jm
      join public.job_types jt
        on jt.id = jm.job_type_id
       and jt.is_active = true
       and jt.legacy_role is null
      where jm.user_id = v_user
    ) into v_is_job_type_manager;
  end if;

  v_use_dynamic := coalesce(v_enabled, false)
    and (v_has_membership or v_is_system_admin or v_is_job_type_manager);

  return jsonb_build_object(
    'dynamicFirstEnabled', coalesce(v_enabled, false),
    'hasDynamicMembership', v_has_membership,
    'useDynamicRuntime', v_use_dynamic,
    'legacyFrozen', coalesce(v_legacy_frozen, false)
  );
end;
$$;


ALTER FUNCTION "public"."get_dynamic_cutover_state"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_dynamic_dashboard_context_policy"("requested_job_type_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor uuid := auth.uid();
  source_name text;
begin
  if actor is null then
    raise exception 'not authenticated';
  end if;

  if not (
    public.current_user_has_permission('users.view')
    or public.current_user_has_permission('users.manage')
  ) then
    raise exception 'not allowed';
  end if;

  select jt.name
    into source_name
  from public.job_types jt
  where jt.id = requested_job_type_id
    and jt.legacy_role is null;

  if source_name is null then
    raise exception 'dynamic job type not found';
  end if;

  return jsonb_build_object(
    'jobTypeId', requested_job_type_id,
    'jobTypeName', source_name,
    'targetJobTypeIds', coalesce((
      select jsonb_agg(r.target_job_type_id order by jt.name)
      from public.job_type_dashboard_context_rules r
      join public.job_types jt on jt.id = r.target_job_type_id
      where r.source_job_type_id = requested_job_type_id
        and r.enabled = true
        and jt.is_active = true
        and jt.legacy_role is null
    ), '[]'::jsonb)
  );
end;
$$;


ALTER FUNCTION "public"."get_dynamic_dashboard_context_policy"("requested_job_type_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_dynamic_historical_slot_editor"("requested_historical_period_id" "uuid", "requested_work_date" "date", "requested_shift_code" "text", "requested_start_time" "text", "requested_end_time" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  actor uuid := auth.uid();
  target_period public.dynamic_historical_periods%rowtype;
  target_job public.job_types%rowtype;
  actor_is_admin boolean := false;
  can_view boolean := false;
  can_edit boolean := false;
  members_json jsonb := '[]'::jsonb;
  assignments_json jsonb := '[]'::jsonb;
begin
  if actor is null then
    raise exception 'not authenticated';
  end if;

  select * into target_period
  from public.dynamic_historical_periods
  where id = requested_historical_period_id;

  if target_period.id is null then
    raise exception 'historical period not found';
  end if;

  select * into target_job
  from public.job_types
  where id = target_period.job_type_id
    and legacy_role is null;

  if target_job.id is null then
    raise exception 'dynamic job type not found';
  end if;

  select exists (
    select 1
    from public.profiles p
    where p.id = actor
      and p.role::text = 'admin'
  ) into actor_is_admin;

  can_edit := actor_is_admin
    or public.has_dynamic_job_type_permission('schedule.edit_history', target_job.id, actor);

  can_view := can_edit
    or public.has_dynamic_job_type_permission('schedule.view_team', target_job.id, actor)
    or public.has_dynamic_job_type_permission('schedule.edit_published', target_job.id, actor);

  if not can_view then
    raise exception 'not allowed';
  end if;

  select coalesce(jsonb_agg(
    jsonb_build_object(
      'userId', m.user_id,
      'displayName', p.display_name
    ) order by p.display_name
  ), '[]'::jsonb)
  into members_json
  from public.job_type_memberships m
  join public.profiles p on p.id = m.user_id
  where m.job_type_id = target_job.id
    and p.is_active = true;

  select coalesce(jsonb_agg(
    jsonb_build_object(
      'id', q.id,
      'userId', q.assigned_user_id,
      'displayName', q.display_name,
      'originalUserId', q.original_user_id,
      'originalDisplayName', q.original_display_name,
      'isIntentionallyUnassigned', q.is_intentionally_unassigned
    ) order by q.display_name nulls last, q.id
  ), '[]'::jsonb)
  into assignments_json
  from (
    select
      ha.id,
      ha.assigned_user_id,
      current_profile.display_name,
      ha.original_user_id,
      original_profile.display_name as original_display_name,
      ha.is_intentionally_unassigned
    from public.dynamic_historical_assignments ha
    left join public.profiles current_profile on current_profile.id = ha.assigned_user_id
    left join public.profiles original_profile on original_profile.id = ha.original_user_id
    where ha.historical_period_id = target_period.id
      and ha.work_date = requested_work_date
      and coalesce(ha.shift_code, target_period.source_kind || '-' || ha.work_date::text) = requested_shift_code
      and coalesce(
        to_char(ha.starts_at at time zone 'Asia/Jerusalem', 'HH24:MI:SS'),
        nullif(ha.source_payload #>> '{shift,start_time}', ''),
        '00:00:00'
      ) = requested_start_time
      and coalesce(
        to_char(ha.ends_at at time zone 'Asia/Jerusalem', 'HH24:MI:SS'),
        nullif(ha.source_payload #>> '{shift,end_time}', ''),
        case when target_period.source_kind = 'on_call' then '23:59:00' else '00:00:00' end
      ) = requested_end_time
  ) q;

  if jsonb_array_length(assignments_json) = 0 then
    raise exception 'historical slot not found';
  end if;

  return jsonb_build_object(
    'historicalPeriodId', target_period.id,
    'jobTypeId', target_job.id,
    'jobTypeName', target_job.name,
    'year', target_period.year,
    'month', target_period.month,
    'editable', can_edit,
    'editabilityReason', case
      when can_edit then null
      else 'נדרשת הרשאת „עריכת שיבוצי עבר”.'
    end,
    'members', members_json,
    'assignments', assignments_json
  );
end;
$$;


ALTER FUNCTION "public"."get_dynamic_historical_slot_editor"("requested_historical_period_id" "uuid", "requested_work_date" "date", "requested_shift_code" "text", "requested_start_time" "text", "requested_end_time" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_dynamic_job_type_active_features"("requested_job_type_id" "uuid") RETURNS "text"[]
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare jt public.job_types%rowtype; features text[]:=array[]::text[]; change_mode text;
begin
 select * into jt from public.job_types where id=requested_job_type_id;
 if not found then return array[]::text[]; end if;
 if coalesce(jt.scheduling_strategy,'availability_optimizer')<>'none' then
   features:=array_append(features,'schedule');
   if coalesce((jt.availability_config->>'enabled')::boolean,false) then features:=array_append(features,'availability'); end if;
   change_mode:=coalesce(jt.scheduling_config->>'scheduleChangeMode','none');
   if change_mode='shift_exchange' then features:=array_append(features,'shift_exchange'); elsif change_mode='self_edit' then features:=array_append(features,'self_edit'); end if;
   if jt.scheduling_strategy='monthly_rotation_constraints' then features:=array_append(features,'monthly_rotation'); end if;
 end if;
 if coalesce((jt.statistics_config->>'enabled')::boolean,false) then features:=array_append(features,'statistics'); end if;
 if coalesce(jt.pay_model,'none')<>'none' then features:=array_append(features,'payroll'); end if;
 if coalesce((jt.scheduling_config#>>'{attendance,enabled}')::boolean,false) then features:=array_append(features,'attendance'); end if;
 if exists(select 1 from public.job_type_capabilities c where c.job_type_id=jt.id and c.capability_key='daily_reports' and c.enabled=true)
    or coalesce((jt.scheduling_config#>>'{dailyReports,enabled}')::boolean,false) then features:=array_append(features,'daily_reports'); end if;
 return coalesce((select array_agg(distinct x order by x) from unnest(features)x),array[]::text[]);
end; $$;


ALTER FUNCTION "public"."get_dynamic_job_type_active_features"("requested_job_type_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_dynamic_job_type_effective_config"("requested_job_type_id" "uuid", "requested_year" integer, "requested_month" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  current_user_id uuid := auth.uid();
  target_month date;
  result jsonb;
begin
  if current_user_id is null then raise exception 'not authenticated'; end if;
  if not exists (
    select 1 from public.user_permissions up
    where up.user_id=current_user_id and up.permission_key in ('users.view','users.manage')
  ) then raise exception 'not allowed'; end if;

  if requested_month not between 1 and 12 then raise exception 'invalid month'; end if;
  target_month := make_date(requested_year, requested_month, 1);

  select v.snapshot into result
  from public.job_type_configuration_versions v
  where v.job_type_id=requested_job_type_id
    and v.effective_month <= target_month
  order by v.effective_month desc
  limit 1;

  if result is null then
    result := public.dynamic_job_type_live_snapshot(requested_job_type_id);
  end if;

  if result is null then raise exception 'job type not found'; end if;

  -- Membership is operational state rather than a versioned job-type setting.
  result := result || jsonb_build_object(
    'memberCount',(select count(*) from public.job_type_memberships m where m.job_type_id=requested_job_type_id),
    'members',coalesce((
      select jsonb_agg(jsonb_build_object(
        'userId',m.user_id,
        'displayName',p.display_name,
        'isActive',p.is_active,
        'employmentScope',nullif(m.metadata->>'employmentScope',''),
        'recommendationFactor',case m.metadata->>'employmentScope' when 'part_time' then 0.5 else 1 end
      ) order by p.is_active desc,p.display_name)
      from public.job_type_memberships m
      join public.profiles p on p.id=m.user_id
      where m.job_type_id=requested_job_type_id
    ),'[]'::jsonb),
    'configurationVersions',coalesce((
      select jsonb_agg(jsonb_build_object(
        'effectiveYear',extract(year from v.effective_month)::integer,
        'effectiveMonth',extract(month from v.effective_month)::integer,
        'effectiveMonthDate',v.effective_month,
        'schedulingStrategy',coalesce(v.snapshot->>'schedulingStrategy','availability_optimizer'),
        'changeSummary',v.change_summary,
        'createdAt',v.created_at
      ) order by v.effective_month)
      from public.job_type_configuration_versions v
      where v.job_type_id=requested_job_type_id
    ),'[]'::jsonb)
  );

  return result;
end;
$$;


ALTER FUNCTION "public"."get_dynamic_job_type_effective_config"("requested_job_type_id" "uuid", "requested_year" integer, "requested_month" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_dynamic_job_type_materialization"("requested_job_type_id" "uuid", "requested_year" integer, "requested_month" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  current_user_id uuid:=auth.uid();
  target_month date;
  target_materialization_id uuid;
  result jsonb;
begin
  if current_user_id is null then raise exception 'not authenticated'; end if;
  if not exists(
    select 1 from public.user_permissions up
    where up.user_id=current_user_id and up.permission_key in ('users.view','users.manage')
  ) then raise exception 'not allowed'; end if;
  if requested_month not between 1 and 12 then raise exception 'invalid month'; end if;

  target_month:=make_date(requested_year,requested_month,1);
  select m.id into target_materialization_id
  from public.job_type_schedule_materializations m
  where m.job_type_id=requested_job_type_id and m.effective_month<=target_month
  order by m.effective_month desc
  limit 1;

  if target_materialization_id is null then return null; end if;

  select jsonb_build_object(
    'id',m.id,
    'jobTypeId',m.job_type_id,
    'effectiveMonth',m.effective_month,
    'workMode',m.work_mode,
    'schedulingStrategy',m.scheduling_strategy,
    'employmentScope',m.employment_scope,
    'schemaVersion',m.schema_version,
    'generatedAt',m.generated_at,
    'dayRules',coalesce((
      select jsonb_agg(jsonb_build_object(
        'dayKind',d.day_kind,'works',d.works,'behavior',d.behavior,
        'inheritDayKind',d.inherit_day_kind,'metadata',d.metadata
      ) order by d.day_kind)
      from public.job_type_materialized_day_rules d
      where d.materialization_id=m.id
    ),'[]'::jsonb),
    'shiftTemplates',coalesce((
      select jsonb_agg(jsonb_build_object(
        'id',s.id,'sourceShiftId',s.source_shift_id,'code',s.code,'name',s.name,
        'dayKind',s.day_kind,'startTime',s.start_time,'endTime',s.end_time,
        'requiredWorkers',s.required_workers,'sortOrder',s.sort_order,'isActive',s.is_active,
        'contains200Percent',s.contains_200_percent,'premium200Hours',s.premium_200_hours,
        'metadata',s.metadata,
        'payComponents',coalesce((
          select jsonb_agg(jsonb_build_object(
            'type',p.component_type,'multiplier',p.multiplier,'hours',p.hours,
            'label',p.label,'metadata',p.metadata
          ) order by p.created_at)
          from public.job_type_materialized_pay_components p
          where p.shift_template_id=s.id
        ),'[]'::jsonb)
      ) order by s.day_kind,s.sort_order)
      from public.job_type_materialized_shift_templates s
      where s.materialization_id=m.id
    ),'[]'::jsonb)
  ) into result
  from public.job_type_schedule_materializations m
  where m.id=target_materialization_id;

  return result;
end;
$$;


ALTER FUNCTION "public"."get_dynamic_job_type_materialization"("requested_job_type_id" "uuid", "requested_year" integer, "requested_month" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_dynamic_job_type_membership_admin"("requested_job_type_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare current_user_id uuid := auth.uid();
begin
  if current_user_id is null then raise exception 'not authenticated'; end if;
  if not exists(select 1 from public.user_permissions up where up.user_id=current_user_id and up.permission_key in ('users.view','users.manage')) then raise exception 'not allowed'; end if;
  if not exists(select 1 from public.job_types jt where jt.id=requested_job_type_id) then raise exception 'job type not found'; end if;

  return jsonb_build_object(
    'users', coalesce((
      select jsonb_agg(jsonb_build_object(
        'userId',p.id,'displayName',p.display_name,'email',p.email,'legacyRole',p.role::text,'isActive',p.is_active,
        'isMember',(m.user_id is not null),'isPrimary',coalesce(m.is_primary,false),
        'isJobTypeManager',(jm.user_id is not null),
        'employmentScope',m.metadata->>'employmentScope',
        'partTimeDefinition',coalesce(m.metadata->'partTimeDefinition','{}'::jsonb)
      ) order by p.is_active desc,p.display_name)
      from public.profiles p
      left join public.job_type_memberships m on m.user_id=p.id and m.job_type_id=requested_job_type_id
      left join public.job_type_managers jm on jm.user_id=p.id and jm.job_type_id=requested_job_type_id
    ),'[]'::jsonb)
  );
end;$$;


ALTER FUNCTION "public"."get_dynamic_job_type_membership_admin"("requested_job_type_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_dynamic_job_type_permission_editor"("requested_job_type_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  actor uuid := auth.uid();
  features text[];
begin
  if actor is null then raise exception 'not authenticated'; end if;
  if not exists (
    select 1 from public.user_permissions up
    where up.user_id = actor and up.permission_key in ('users.view','users.manage')
  ) then raise exception 'not allowed'; end if;
  if not exists (select 1 from public.job_types where id=requested_job_type_id) then
    raise exception 'job type not found';
  end if;

  perform public.sync_dynamic_job_type_permission_settings(requested_job_type_id);
  features := public.get_dynamic_job_type_active_features(requested_job_type_id);

  return jsonb_build_object(
    'jobTypeId', requested_job_type_id,
    'jobTypeName', (select name from public.job_types where id=requested_job_type_id),
    'activeFeatures', to_jsonb(features),
    'memberPermissions', coalesce((
      select jsonb_agg(jsonb_build_object(
        'permissionKey',m.permission_key,
        'featureKey',m.feature_key,
        'audience',m.audience,
        'label',m.label,
        'description',m.description,
        'defaultEnabled',m.default_enabled,
        'enabled',coalesce(s.enabled,m.default_enabled)
      ) order by m.feature_key,m.sort_order,m.label)
      from public.dynamic_permission_manifest m
      left join public.job_type_permission_settings s
        on s.job_type_id=requested_job_type_id
       and s.permission_key=m.permission_key
       and s.audience=m.audience
      where m.audience='member' and m.feature_key=any(features)
    ),'[]'::jsonb),
    'managerPermissions', coalesce((
      select jsonb_agg(jsonb_build_object(
        'permissionKey',m.permission_key,
        'featureKey',m.feature_key,
        'audience',m.audience,
        'label',m.label,
        'description',m.description,
        'defaultEnabled',m.default_enabled,
        'enabled',coalesce(s.enabled,m.default_enabled)
      ) order by m.feature_key,m.sort_order,m.label)
      from public.dynamic_permission_manifest m
      left join public.job_type_permission_settings s
        on s.job_type_id=requested_job_type_id
       and s.permission_key=m.permission_key
       and s.audience=m.audience
      where m.audience='manager' and m.feature_key=any(features)
    ),'[]'::jsonb),
    'managers', coalesce((
      select jsonb_agg(jsonb_build_object(
        'userId',p.id,'displayName',p.display_name,'email',p.email,
        'isActive',p.is_active,'isManager',(jm.user_id is not null)
      ) order by p.is_active desc,p.display_name)
      from public.profiles p
      left join public.job_type_managers jm
        on jm.user_id=p.id and jm.job_type_id=requested_job_type_id
    ),'[]'::jsonb)
  );
end;
$$;


ALTER FUNCTION "public"."get_dynamic_job_type_permission_editor"("requested_job_type_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_dynamic_job_type_rotation_workspace"("requested_job_type_id" "uuid", "requested_start_date" "date" DEFAULT CURRENT_DATE, "requested_days" integer DEFAULT 35) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_actor uuid:=auth.uid();
  v_job public.job_types%rowtype;
  v_state public.dynamic_job_type_rotation_state%rowtype;
  v_days integer:=least(greatest(coalesce(requested_days,35),1),93);
  v_members jsonb:='[]'::jsonb;
  v_preview jsonb:='[]'::jsonb;
begin
  if v_actor is null then raise exception 'not authenticated'; end if;
  if not exists(
    select 1 from public.user_permissions up
    where up.user_id=v_actor and up.permission_key='users.manage'
  ) then raise exception 'not allowed'; end if;

  select * into v_job from public.job_types where id=requested_job_type_id;
  if v_job.id is null then raise exception 'job type not found'; end if;
  if coalesce(v_job.scheduling_strategy,'availability_optimizer') <> 'monthly_rotation_constraints' then
    raise exception 'job type is not configured for monthly rotation';
  end if;

  select * into v_state
  from public.dynamic_job_type_rotation_state
  where job_type_id=v_job.id;

  select coalesce(jsonb_agg(jsonb_build_object(
    'userId',m.user_id,
    'displayName',coalesce(p.schedule_name,p.display_name,p.email,m.user_id::text),
    'isActive',p.is_active,
    'rotationIndex',case
      when v_state.rotation_user_ids is null then null
      else array_position(v_state.rotation_user_ids,m.user_id)
    end
  ) order by coalesce(array_position(v_state.rotation_user_ids,m.user_id),2147483647),
             coalesce(p.schedule_name,p.display_name,p.email,m.user_id::text)), '[]'::jsonb)
  into v_members
  from public.job_type_memberships m
  join public.profiles p on p.id=m.user_id
  where m.job_type_id=v_job.id;

  if v_state.job_type_id is not null then
    with days as (
      select d::date work_date,
             v_state.rotation_user_ids[
               ((d::date-v_state.anchor_date)%cardinality(v_state.rotation_user_ids)
                 +cardinality(v_state.rotation_user_ids))%cardinality(v_state.rotation_user_ids)+1
             ] original_user_id
      from generate_series(
        coalesce(requested_start_date,current_date)::timestamp,
        (coalesce(requested_start_date,current_date)+v_days-1)::timestamp,
        interval '1 day'
      ) d
    ), actual as (
      select s.shift_date work_date,
             pa.user_id,
             pa.original_user_id,
             row_number() over(partition by s.shift_date order by pa.created_at desc,pa.id desc) rn
      from public.dynamic_schedule_published_assignments pa
      join public.dynamic_schedule_publications pub on pub.id=pa.publication_id
      join public.dynamic_availability_slots s on s.id=pa.slot_id
      where pub.job_type_id=v_job.id
        and s.shift_date between coalesce(requested_start_date,current_date)
                             and coalesce(requested_start_date,current_date)+v_days-1
    )
    select coalesce(jsonb_agg(jsonb_build_object(
      'date',d.work_date,
      'originalUserId',d.original_user_id,
      'originalDisplayName',coalesce(op.schedule_name,op.display_name,op.email,d.original_user_id::text),
      'actualUserId',a.user_id,
      'actualDisplayName',case when a.user_id is null then null else coalesce(ap.schedule_name,ap.display_name,ap.email,a.user_id::text) end,
      'isSubstitution',case when a.user_id is null then false else a.user_id is distinct from d.original_user_id end
    ) order by d.work_date),'[]'::jsonb)
    into v_preview
    from days d
    left join public.profiles op on op.id=d.original_user_id
    left join actual a on a.work_date=d.work_date and a.rn=1
    left join public.profiles ap on ap.id=a.user_id;
  end if;

  return jsonb_build_object(
    'jobTypeId',v_job.id,
    'jobTypeName',v_job.name,
    'initialized',v_state.job_type_id is not null,
    'rotationUserIds',coalesce(to_jsonb(v_state.rotation_user_ids),'[]'::jsonb),
    'anchorDate',v_state.anchor_date,
    'source',v_state.source,
    'sourceMetadata',coalesce(v_state.source_metadata,'{}'::jsonb),
    'members',v_members,
    'preview',v_preview
  );
end;
$$;


ALTER FUNCTION "public"."get_dynamic_job_type_rotation_workspace"("requested_job_type_id" "uuid", "requested_start_date" "date", "requested_days" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_dynamic_job_type_statistics"("requested_job_type_id" "uuid", "requested_years" integer[] DEFAULT NULL::integer[], "requested_months" integer[] DEFAULT NULL::integer[], "requested_user_ids" "uuid"[] DEFAULT NULL::"uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  current_user_id uuid := auth.uid();
  target_job public.job_types%rowtype;
  result jsonb;
begin
  if current_user_id is null then
    raise exception 'not authenticated';
  end if;

  if not exists (
    select 1
    from public.user_permissions up
    where up.user_id=current_user_id
      and up.permission_key in ('statistics.view','users.manage')
  ) then
    raise exception 'not allowed';
  end if;

  select * into target_job
  from public.job_types jt
  where jt.id=requested_job_type_id;

  if target_job.id is null then
    raise exception 'job type not found';
  end if;
  if not coalesce((target_job.statistics_config->>'enabled')::boolean,false) then
    raise exception 'statistics disabled for this job type';
  end if;

  if requested_years is not null and exists (
    select 1 from unnest(requested_years) y where y not between 2020 and 2100
  ) then
    raise exception 'statistics year is invalid';
  end if;

  if requested_months is not null and exists (
    select 1 from unnest(requested_months) m where m not between 1 and 12
  ) then
    raise exception 'statistics month is invalid';
  end if;

  with
  selected_publications as (
    select p.*
    from public.dynamic_schedule_publications p
    where p.job_type_id=requested_job_type_id
      and (requested_years is null or cardinality(requested_years)=0 or p.year=any(requested_years))
      and (requested_months is null or cardinality(requested_months)=0 or p.month=any(requested_months))
  ),
  selected_history_periods as (
    select hp.*
    from public.dynamic_historical_periods hp
    where hp.job_type_id=requested_job_type_id
      and (requested_years is null or cardinality(requested_years)=0 or hp.year=any(requested_years))
      and (requested_months is null or cardinality(requested_months)=0 or hp.month=any(requested_months))
      and not exists (
        select 1
        from public.dynamic_schedule_publications p
        where p.job_type_id=hp.job_type_id
          and p.year=hp.year
          and p.month=hp.month
      )
  ),
  raw_assignments as (
    select
      p.year,
      p.month,
      a.shift_date as work_date,
      a.shift_code,
      a.shift_name,
      a.start_time,
      a.end_time,
      a.user_id,
      case
        when a.start_time is null or a.end_time is null then null::numeric
        else round((extract(epoch from (
          (a.shift_date + a.end_time + case when a.end_time <= a.start_time then interval '1 day' else interval '0 day' end)
          - (a.shift_date + a.start_time)
        )) / 3600.0)::numeric, 2)
      end as timed_hours,
      coalesce(a.manager_edited,false) as manager_edited,
      case when a.original_user_id is not null and a.original_user_id<>a.user_id then true else false end as substituted
    from selected_publications p
    join public.dynamic_schedule_published_assignments a on a.publication_id=p.id

    union all

    select
      hp.year,
      hp.month,
      ha.work_date,
      coalesce(nullif(ha.shift_code,''),'history') as shift_code,
      coalesce(
        nullif(ha.source_payload->>'shift_name',''),
        nullif(ha.source_payload->>'shiftName',''),
        nullif(ha.shift_code,''),
        'רשומה היסטורית'
      ) as shift_name,
      ha.starts_at::time as start_time,
      ha.ends_at::time as end_time,
      ha.assigned_user_id as user_id,
      case
        when ha.starts_at is null or ha.ends_at is null or ha.ends_at<=ha.starts_at then null::numeric
        else round((extract(epoch from (ha.ends_at-ha.starts_at))/3600.0)::numeric,2)
      end as timed_hours,
      false as manager_edited,
      case when ha.original_user_id is not null and ha.assigned_user_id is not null and ha.original_user_id<>ha.assigned_user_id then true else false end as substituted
    from selected_history_periods hp
    join public.dynamic_historical_assignments ha on ha.historical_period_id=hp.id
    where ha.assigned_user_id is not null
      and coalesce(ha.is_intentionally_unassigned,false)=false
  ),
  all_assignments as (
    select *
    from raw_assignments a
    where requested_user_ids is null
       or cardinality(requested_user_ids)=0
       or a.user_id=any(requested_user_ids)
  ),
  unassigned as (
    select p.year,p.month,coalesce(sum(u.intentionally_unassigned_count),0)::integer as count
    from selected_publications p
    join public.dynamic_schedule_published_unassigned u on u.publication_id=p.id
    group by p.year,p.month
  ),
  selected_live_periods as (
    select ap.*
    from public.dynamic_availability_periods ap
    where ap.job_type_id=requested_job_type_id
      and (requested_years is null or cardinality(requested_years)=0 or ap.year=any(requested_years))
      and (requested_months is null or cardinality(requested_months)=0 or ap.month=any(requested_months))
  ),
  raw_availability_rows as (
    select
      ap.id as period_id,
      s.user_id,
      e.availability_status as status,
      case when s.status='submitted' then true else false end as submitted
    from selected_live_periods ap
    join public.dynamic_availability_submissions s on s.period_id=ap.id
    join public.dynamic_availability_entries e on e.submission_id=s.id

    union all

    select
      hp.id as period_id,
      ha.user_id,
      ha.status,
      true as submitted
    from selected_history_periods hp
    join public.dynamic_historical_availability ha on ha.historical_period_id=hp.id
    where ha.user_id is not null
  ),
  availability_rows as (
    select *
    from raw_availability_rows ar
    where requested_user_ids is null
       or cardinality(requested_user_ids)=0
       or ar.user_id=any(requested_user_ids)
  ),
  candidate_users as (
    select m.user_id from public.job_type_memberships m where m.job_type_id=requested_job_type_id
    union
    select a.user_id from raw_assignments a where a.user_id is not null
    union
    select ar.user_id from raw_availability_rows ar where ar.user_id is not null
  ),
  available_periods as (
    select p.year,p.month from public.dynamic_schedule_publications p where p.job_type_id=requested_job_type_id
    union
    select hp.year,hp.month from public.dynamic_historical_periods hp where hp.job_type_id=requested_job_type_id
    union
    select ap.year,ap.month from public.dynamic_availability_periods ap where ap.job_type_id=requested_job_type_id
  )
  select jsonb_build_object(
    'jobType', jsonb_build_object(
      'jobTypeId',target_job.id,
      'name',target_job.name,
      'code',target_job.code,
      'payModel',target_job.pay_model,
      'workMode',coalesce(
        nullif(target_job.scheduling_config->'shiftPattern'->>'workMode',''),
        nullif(target_job.scheduling_config->>'workMode','')
      ),
      'availabilityEnabled',coalesce((target_job.availability_config->>'enabled')::boolean,false),
      'payrollEnabled',coalesce(target_job.pay_model,'none')<>'none',
      'baseRate',0,
      'shiftRate',0
    ),
    'filters',jsonb_build_object(
      'years',coalesce(to_jsonb(requested_years),'[]'::jsonb),
      'months',coalesce(to_jsonb(requested_months),'[]'::jsonb)
    ),
    'availablePeriods',coalesce((
      select jsonb_agg(jsonb_build_object('year',p.year,'month',p.month) order by p.year desc,p.month desc)
      from available_periods p
    ),'[]'::jsonb),
    'summary',jsonb_build_object(
      'assignmentCount',(select count(*) from all_assignments),
      'timedAssignmentCount',(select count(*) from all_assignments where timed_hours is not null),
      'untimedAssignmentCount',(select count(*) from all_assignments where timed_hours is null),
      'timedHours',coalesce((select round(sum(timed_hours),2) from all_assignments where timed_hours is not null),0),
      'uniqueWorkerCount',(select count(distinct user_id) from all_assignments),
      'monthCount',(select count(*) from (select distinct year,month from all_assignments) x),
      'intentionallyUnassignedCount',coalesce((select sum(count) from unassigned),0),
      'managerEditedCount',(select count(*) from all_assignments where manager_edited),
      'substitutionCount',(select count(*) from all_assignments where substituted)
    ),
    'people',coalesce((
      select jsonb_agg(jsonb_build_object(
        'userId',p.id,
        'displayName',p.display_name,
        'scheduleName',p.schedule_name,
        'isActive',p.is_active,
        'isMember',exists(select 1 from public.job_type_memberships m where m.job_type_id=requested_job_type_id and m.user_id=p.id),
        'assignmentCount',coalesce(stats.assignment_count,0),
        'timedHours',coalesce(stats.timed_hours,0),
        'monthsWorked',coalesce(stats.months_worked,0),
        'managerEditedCount',coalesce(stats.manager_edited_count,0),
        'substitutionCount',coalesce(stats.substitution_count,0)
      ) order by coalesce(stats.assignment_count,0) desc,p.display_name)
      from candidate_users cu
      join public.profiles p on p.id=cu.user_id
      left join lateral (
        select
          count(*)::integer assignment_count,
          coalesce(round(sum(a.timed_hours) filter(where a.timed_hours is not null),2),0) timed_hours,
          count(distinct (a.year,a.month))::integer months_worked,
          count(*) filter(where a.manager_edited)::integer manager_edited_count,
          count(*) filter(where a.substituted)::integer substitution_count
        from all_assignments a
        where a.user_id=p.id
      ) stats on true
    ),'[]'::jsonb),
    'monthly',coalesce((
      select jsonb_agg(jsonb_build_object(
        'year',m.year,
        'month',m.month,
        'assignmentCount',m.assignment_count,
        'timedHours',m.timed_hours,
        'uniqueWorkerCount',m.unique_worker_count,
        'intentionallyUnassignedCount',coalesce(u.count,0)
      ) order by m.year,m.month)
      from (
        select
          year,
          month,
          count(*)::integer assignment_count,
          coalesce(round(sum(timed_hours) filter(where timed_hours is not null),2),0) timed_hours,
          count(distinct user_id)::integer unique_worker_count
        from all_assignments
        group by year,month
      ) m
      left join unassigned u on u.year=m.year and u.month=m.month
    ),'[]'::jsonb),
    'shifts',coalesce((
      select jsonb_agg(jsonb_build_object(
        'shiftCode',s.time_key,
        'shiftName',s.time_label,
        'timeLabel',s.time_label,
        'assignmentCount',s.assignment_count,
        'timedHours',s.timed_hours
      ) order by s.start_time nulls last,s.end_time nulls last)
      from (
        select
          coalesce(to_char(start_time,'HH24:MI')||'-'||to_char(end_time,'HH24:MI'),'ללא שעות') time_key,
          coalesce(to_char(start_time,'HH24:MI')||'–'||to_char(end_time,'HH24:MI'),'ללא שעות') time_label,
          start_time,end_time,
          count(*)::integer assignment_count,
          coalesce(round(sum(timed_hours) filter(where timed_hours is not null),2),0) timed_hours
        from all_assignments
        group by start_time,end_time
      ) s
    ),'[]'::jsonb),
    'payrollPeople',coalesce((
      select jsonb_agg(jsonb_build_object(
        'userId',p.id,
        'displayName',p.display_name,
        'scheduleName',p.schedule_name,
        'assignmentCount',coalesce(x.assignment_count,0),
        'timedHours',coalesce(x.timed_hours,0),
        'workDayCount',coalesce(x.work_day_count,0),
        'hourlyRate',p.hourly_rate,
        'dailyDutyRate',p.daily_duty_rate,
        'shiftRate',p.morning_shift_rate,
        'compensationRate',case coalesce(target_job.pay_model,'none')
          when 'hourly' then p.hourly_rate when 'per_day' then p.daily_duty_rate
          when 'per_shift' then p.morning_shift_rate when 'mixed' then p.hourly_rate else null end,
        'projectedPay',coalesce(x.projected_pay,0)
      ) order by coalesce(x.projected_pay,0) desc,p.display_name)
      from candidate_users cu join public.profiles p on p.id=cu.user_id
      left join lateral (
        select count(*)::integer assignment_count,
          coalesce(round(sum(a.timed_hours) filter(where a.timed_hours is not null),2),0) timed_hours,
          count(distinct a.work_date)::integer work_day_count,
          round(case coalesce(target_job.pay_model,'none')
            when 'hourly' then coalesce(sum(a.timed_hours),0)*coalesce(p.hourly_rate,0)
            when 'per_shift' then count(*)*coalesce(p.morning_shift_rate,0)
            when 'per_day' then count(distinct a.work_date)*coalesce(p.daily_duty_rate,0)
            when 'mixed' then coalesce(sum(a.timed_hours),0)*coalesce(p.hourly_rate,0)
            else 0 end,2) projected_pay
        from all_assignments a where a.user_id=p.id
      ) x on true
    ),'[]'::jsonb),
    'payrollTotal',coalesce((
      select round(sum(person_pay.projected_pay),2) from (
        select p.id,case coalesce(target_job.pay_model,'none')
          when 'hourly' then coalesce(sum(a.timed_hours),0)*coalesce(p.hourly_rate,0)
          when 'per_shift' then count(a.user_id)*coalesce(p.morning_shift_rate,0)
          when 'per_day' then count(distinct a.work_date)*coalesce(p.daily_duty_rate,0)
          when 'mixed' then coalesce(sum(a.timed_hours),0)*coalesce(p.hourly_rate,0)
          else 0 end projected_pay
        from candidate_users cu join public.profiles p on p.id=cu.user_id
        left join all_assignments a on a.user_id=p.id
        group by p.id,p.hourly_rate,p.daily_duty_rate,p.morning_shift_rate
      ) person_pay
    ),0),
    'availabilitySummary',jsonb_build_object(
      'periodCount',(select count(distinct period_id) from availability_rows),
      'submissionCount',(select count(distinct (period_id,user_id)) from availability_rows where submitted),
      'availableCount',(select count(*) from availability_rows where status='available'),
      'unavailableCount',(select count(*) from availability_rows where status='unavailable'),
      'preferredCount',(select count(*) from availability_rows where status='preferred'),
      'avoidCount',(select count(*) from availability_rows where status='avoid')
    ),
    'availabilityPeople',coalesce((
      select jsonb_agg(jsonb_build_object(
        'userId',p.id,
        'displayName',p.display_name,
        'scheduleName',p.schedule_name,
        'isActive',p.is_active,
        'submittedPeriods',coalesce(stats.submitted_periods,0),
        'availableCount',coalesce(stats.available_count,0),
        'unavailableCount',coalesce(stats.unavailable_count,0),
        'preferredCount',coalesce(stats.preferred_count,0),
        'avoidCount',coalesce(stats.avoid_count,0),
        'totalEntries',coalesce(stats.total_entries,0)
      ) order by coalesce(stats.total_entries,0) desc,p.display_name)
      from candidate_users cu
      join public.profiles p on p.id=cu.user_id
      left join lateral (
        select
          count(distinct ar.period_id) filter(where ar.submitted)::integer submitted_periods,
          count(*) filter(where ar.status='available')::integer available_count,
          count(*) filter(where ar.status='unavailable')::integer unavailable_count,
          count(*) filter(where ar.status='preferred')::integer preferred_count,
          count(*) filter(where ar.status='avoid')::integer avoid_count,
          count(*)::integer total_entries
        from availability_rows ar
        where ar.user_id=p.id
      ) stats on true
    ),'[]'::jsonb),
    'generatedAt',now()
  ) into result;

  return result;
end;
$$;


ALTER FUNCTION "public"."get_dynamic_job_type_statistics"("requested_job_type_id" "uuid", "requested_years" integer[], "requested_months" integer[], "requested_user_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_dynamic_period_workflow"("requested_job_type_id" "uuid", "requested_year" integer, "requested_month" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  current_user_id uuid := auth.uid();
  target_job public.job_types%rowtype;
  target_period public.dynamic_availability_periods%rowtype;
  latest_draft public.dynamic_schedule_shadow_drafts%rowtype;
  publication public.dynamic_schedule_publications%rowtype;
  member_count integer := 0;
  slot_count integer := 0;
  submission_count integer := 0;
  submitted_count integer := 0;
  assignment_count integer := 0;
begin
  if current_user_id is null then raise exception 'not authenticated'; end if;
  if not (
    public.has_dynamic_job_type_permission('availability.view_team', requested_job_type_id, current_user_id)
    or public.has_dynamic_job_type_permission('schedule.view_team', requested_job_type_id, current_user_id)
  ) then raise exception 'not allowed'; end if;
  if requested_month not between 1 and 12 then raise exception 'invalid month'; end if;

  select * into target_job from public.job_types where id=requested_job_type_id and legacy_role is null;
  if target_job.id is null then raise exception 'job type not found'; end if;

  select count(*) into member_count
  from public.job_type_memberships m
  join public.profiles p on p.id=m.user_id
  where m.job_type_id=target_job.id and p.is_active=true;

  select * into target_period
  from public.dynamic_availability_periods
  where job_type_id=target_job.id and year=requested_year and month=requested_month;

  if target_period.id is not null then
    select count(*) into slot_count
    from public.dynamic_availability_slots
    where period_id=target_period.id;

    select
      count(*) filter (where sub.id is not null),
      count(*) filter (where sub.status='submitted')
    into submission_count, submitted_count
    from public.job_type_memberships m
    join public.profiles p on p.id=m.user_id and p.is_active=true
    left join public.dynamic_availability_submissions sub
      on sub.period_id=target_period.id and sub.user_id=m.user_id
    where m.job_type_id=target_job.id;

    select * into latest_draft
    from public.dynamic_schedule_shadow_drafts
    where job_type_id=target_job.id and year=requested_year and month=requested_month
    order by created_at desc limit 1;
  end if;

  select * into publication
  from public.dynamic_schedule_publications
  where job_type_id=target_job.id and year=requested_year and month=requested_month;

  if publication.id is not null then
    select count(*) into assignment_count
    from public.dynamic_schedule_published_assignments
    where publication_id=publication.id;
  end if;

  return jsonb_build_object(
    'jobTypeId', target_job.id,
    'jobTypeName', target_job.name,
    'year', requested_year,
    'month', requested_month,
    'memberCount', member_count,
    'availabilityEnabled', coalesce((target_job.availability_config->>'enabled')::boolean,false),
    'schedulingStrategy', coalesce(target_job.scheduling_strategy, target_job.scheduling_config->>'schedulingStrategy','availability_optimizer'),
    'permissions', jsonb_build_object(
      'availability.view_team', public.has_dynamic_job_type_permission('availability.view_team', target_job.id, current_user_id),
      'availability.open_period', public.has_dynamic_job_type_permission('availability.open_period', target_job.id, current_user_id),
      'availability.close_period', public.has_dynamic_job_type_permission('availability.close_period', target_job.id, current_user_id),
      'availability.manage_submissions', public.has_dynamic_job_type_permission('availability.manage_submissions', target_job.id, current_user_id),
      'schedule.view_team', public.has_dynamic_job_type_permission('schedule.view_team', target_job.id, current_user_id),
      'schedule.create_draft', public.has_dynamic_job_type_permission('schedule.create_draft', target_job.id, current_user_id),
      'schedule.edit_draft', public.has_dynamic_job_type_permission('schedule.edit_draft', target_job.id, current_user_id),
      'schedule.publish', public.has_dynamic_job_type_permission('schedule.publish', target_job.id, current_user_id),
      'schedule.edit_published', public.has_dynamic_job_type_permission('schedule.edit_published', target_job.id, current_user_id),
      'rotation.generate', public.has_dynamic_job_type_permission('rotation.generate', target_job.id, current_user_id)
    ),
    'period', case when target_period.id is null then null else jsonb_build_object(
      'id',target_period.id,
      'status',target_period.status,
      'title',target_period.title,
      'submissionDeadline',target_period.submission_deadline,
      'slotCount',slot_count,
      'submissionCount',submission_count,
      'submittedCount',submitted_count,
      'pendingCount',greatest(member_count-submitted_count,0)
    ) end,
    'draft', case when latest_draft.id is null then null else jsonb_build_object(
      'id',latest_draft.id,'status',latest_draft.status,'metrics',latest_draft.metrics,
      'createdAt',latest_draft.created_at,'updatedAt',latest_draft.updated_at
    ) end,
    'publication', case when publication.id is null then null else jsonb_build_object(
      'id',publication.id,'status',publication.status,'publishedAt',publication.published_at,
      'assignmentCount',assignment_count
    ) end
  );
end;
$$;


ALTER FUNCTION "public"."get_dynamic_period_workflow"("requested_job_type_id" "uuid", "requested_year" integer, "requested_month" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_dynamic_pilot_qa_report"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_actor uuid := auth.uid();
  v_checks jsonb := '[]'::jsonb;
  v_fail_count integer := 0;
  v_warn_count integer := 0;
  v_pass_count integer := 0;
  v_count integer := 0;
  v_cutover boolean := false;
  v_active_job_types integer := 0;
  v_active_memberships integer := 0;
  v_dynamic_users integer := 0;
  v_publications integer := 0;
  v_assignments integer := 0;
  v_pending_exchanges integer := 0;
  v_latest_run public.gvk_legacy_migration_runs%rowtype;
  v_reconciliation jsonb := '[]'::jsonb;
  v_current_ym integer := extract(year from (now() at time zone 'Asia/Jerusalem'))::integer * 100
    + extract(month from (now() at time zone 'Asia/Jerusalem'))::integer;
  v_rec record;
begin
  if v_actor is null then raise exception 'not authenticated'; end if;
  if not exists(
    select 1 from public.user_permissions up
    where up.user_id=v_actor and up.permission_key='users.manage'
  ) then raise exception 'not allowed'; end if;

  select coalesce(dynamic_first_enabled,false)
    into v_cutover
  from public.dynamic_cutover_settings
  where singleton=true;

  select count(*) into v_active_job_types
  from public.job_types jt where jt.is_active=true;

  select count(*) into v_active_memberships
  from public.job_type_memberships m
  join public.job_types jt on jt.id=m.job_type_id and jt.is_active=true
  join public.profiles p on p.id=m.user_id and p.is_active=true;

  select count(distinct m.user_id) into v_dynamic_users
  from public.job_type_memberships m
  join public.job_types jt on jt.id=m.job_type_id and jt.is_active=true
  join public.profiles p on p.id=m.user_id and p.is_active=true;

  select count(*) into v_publications from public.dynamic_schedule_publications;
  select count(*) into v_assignments from public.dynamic_schedule_published_assignments;
  select count(*) into v_pending_exchanges
  from public.dynamic_shift_exchange_requests
  where status in ('pending_counterparty','pending_manager');

  -- 1. Cutover state.
  if v_cutover then
    v_checks := v_checks || jsonb_build_array(jsonb_build_object(
      'code','cutover_enabled','status','pass','area','cutover',
      'title','Dynamic-first פעיל','message','הפיילוט משתמש ב-Dynamic-first כברירת מחדל למשתמשים עם שיוך דינמי פעיל.','count',1
    )); v_pass_count := v_pass_count + 1;
  else
    v_checks := v_checks || jsonb_build_array(jsonb_build_object(
      'code','cutover_enabled','status','warn','area','cutover',
      'title','Dynamic-first עדיין כבוי','message','הנתונים מוכנים לבדיקה, אך ברירת המחדל עדיין Legacy-first.','count',1
    )); v_warn_count := v_warn_count + 1;
  end if;

  -- 2. Active dynamic runtime exists.
  if v_active_job_types > 0 and v_dynamic_users > 0 then
    v_checks := v_checks || jsonb_build_array(jsonb_build_object(
      'code','dynamic_runtime_population','status','pass','area','memberships',
      'title','קיימים תפקידים ומשתמשים דינמיים פעילים',
      'message',format('%s תפקידים פעילים, %s משתמשים פעילים עם שיוך דינמי.',v_active_job_types,v_dynamic_users),
      'count',v_dynamic_users
    )); v_pass_count := v_pass_count + 1;
  else
    v_checks := v_checks || jsonb_build_array(jsonb_build_object(
      'code','dynamic_runtime_population','status','fail','area','memberships',
      'title','אין אוכלוסיית פיילוט דינמית מספקת','message','נדרש לפחות Job Type פעיל ומשתמש פעיל המשויך אליו.','count',0
    )); v_fail_count := v_fail_count + 1;
  end if;

  -- 3. Memberships must only point to active users and active job types for runtime.
  select count(*) into v_count
  from public.job_type_memberships m
  join public.profiles p on p.id=m.user_id
  join public.job_types jt on jt.id=m.job_type_id
  where p.is_active=false or jt.is_active=false;
  if v_count=0 then
    v_checks := v_checks || jsonb_build_array(jsonb_build_object(
      'code','inactive_memberships','status','pass','area','memberships','title','אין שיוכים פעילים לישויות מוקפאות',
      'message','לא נמצאו Memberships שמפנים למשתמש או תפקיד מוקפא.','count',0
    )); v_pass_count := v_pass_count + 1;
  else
    v_checks := v_checks || jsonb_build_array(jsonb_build_object(
      'code','inactive_memberships','status','warn','area','memberships','title','נמצאו שיוכים למשתמש/תפקיד מוקפא',
      'message','השורות אינן נכנסות ל-runtime הפעיל, אך כדאי לנקות או לאשר שהן היסטוריות.','count',v_count
    )); v_warn_count := v_warn_count + 1;
  end if;

  -- 4. At most one primary role per user.
  select count(*) into v_count
  from (
    select m.user_id
    from public.job_type_memberships m
    where m.is_primary=true
    group by m.user_id
    having count(*)>1
  ) x;
  if v_count=0 then
    v_checks := v_checks || jsonb_build_array(jsonb_build_object(
      'code','single_primary_membership','status','pass','area','memberships','title','תפקיד ראשי יחיד לכל משתמש',
      'message','לא נמצאו משתמשים עם יותר מ-Job Type ראשי אחד.','count',0
    )); v_pass_count := v_pass_count + 1;
  else
    v_checks := v_checks || jsonb_build_array(jsonb_build_object(
      'code','single_primary_membership','status','fail','area','memberships','title','יש משתמשים עם יותר מתפקיד ראשי אחד',
      'message','יש לתקן is_primary לפני Cutover מלא.','count',v_count
    )); v_fail_count := v_fail_count + 1;
  end if;

  -- 5. Every dynamic publication should have a month materialization.
  select count(*) into v_count
  from public.dynamic_schedule_publications p
  left join public.job_type_schedule_materializations m
    on m.job_type_id=p.job_type_id
   and m.effective_month=make_date(p.year,p.month,1)
  where m.id is null;
  if v_count=0 then
    v_checks := v_checks || jsonb_build_array(jsonb_build_object(
      'code','publication_materialization','status','pass','area','configuration','title','כל הלוחות המפורסמים קשורים להגדרת חודש קפואה',
      'message','לכל publication נמצא materialization של אותו Job Type וחודש.','count',0
    )); v_pass_count := v_pass_count + 1;
  else
    v_checks := v_checks || jsonb_build_array(jsonb_build_object(
      'code','publication_materialization','status','fail','area','configuration','title','יש לוחות ללא Materialization חודשי',
      'message','לוחות כאלה עלולים להשתמש בהתנהגות שאינה תואמת את ההגדרה ההיסטורית של החודש.','count',v_count
    )); v_fail_count := v_fail_count + 1;
  end if;

  -- 6. Current/future published assignments must belong to an active member of the publication job type.
  -- Historical/archived assignments may legitimately reference users who are inactive today and must not block cutover.
  select count(*) into v_count
  from public.dynamic_schedule_published_assignments a
  join public.dynamic_schedule_publications p on p.id=a.publication_id
  left join public.job_type_memberships m on m.user_id=a.user_id and m.job_type_id=p.job_type_id
  left join public.profiles pr on pr.id=a.user_id
  where p.status='published'
    and (p.year*100+p.month) >= v_current_ym
    and (m.user_id is null or coalesce(pr.is_active,false)=false);
  if v_count=0 then
    v_checks := v_checks || jsonb_build_array(jsonb_build_object(
      'code','assignment_membership','status','pass','area','schedule','title','כל השיבוצים החיים שייכים לחברי תפקיד פעילים',
      'message','לא נמצאו שיבוצים בחודש הנוכחי או בעתיד לעובד ללא membership או לפרופיל לא פעיל.','count',0
    )); v_pass_count := v_pass_count + 1;
  else
    v_checks := v_checks || jsonb_build_array(jsonb_build_object(
      'code','assignment_membership','status','fail','area','schedule','title','נמצאו שיבוצים חיים עם שיוך משתמש לא תקין',
      'message','זהו blocker ל-Cutover: בחודש הנוכחי או בעתיד יש assignment לעובד ללא membership מתאים או לפרופיל לא פעיל.','count',v_count
    )); v_fail_count := v_fail_count + 1;
  end if;

  -- 7. Published schedule should not be an empty shell.
  select count(*) into v_count
  from public.dynamic_schedule_publications p
  where not exists(select 1 from public.dynamic_schedule_published_assignments a where a.publication_id=p.id)
    and not exists(select 1 from public.dynamic_schedule_published_unassigned u where u.publication_id=p.id);
  if v_count=0 then
    v_checks := v_checks || jsonb_build_array(jsonb_build_object(
      'code','empty_publications','status','pass','area','schedule','title','אין לוחות מפורסמים ריקים',
      'message','כל publication מכיל שיבוץ או סימון מפורש של משמרת לא מאוישת.','count',0
    )); v_pass_count := v_pass_count + 1;
  else
    v_checks := v_checks || jsonb_build_array(jsonb_build_object(
      'code','empty_publications','status','warn','area','schedule','title','נמצאו לוחות מפורסמים ללא תוכן',
      'message','יש לבדוק אם אלה לוחות בדיקה/היסטוריה או פרסום שגוי.','count',v_count
    )); v_warn_count := v_warn_count + 1;
  end if;

  -- 8. Availability periods that expect work should have slots.
  select count(*) into v_count
  from public.dynamic_availability_periods p
  where p.status in ('open','closed')
    and not exists(select 1 from public.dynamic_availability_slots s where s.period_id=p.id);
  if v_count=0 then
    v_checks := v_checks || jsonb_build_array(jsonb_build_object(
      'code','availability_slots','status','pass','area','availability','title','אין תקופות אילוצים פעילות ללא משמרות',
      'message','כל תקופה פתוחה/סגורה מכילה slots.','count',0
    )); v_pass_count := v_pass_count + 1;
  else
    v_checks := v_checks || jsonb_build_array(jsonb_build_object(
      'code','availability_slots','status','fail','area','availability','title','יש תקופות אילוצים ללא Slots',
      'message','לא ניתן לסמוך על הגשה/שיבוץ בתקופה ללא משמרות ממומשות.','count',v_count
    )); v_fail_count := v_fail_count + 1;
  end if;

  -- 9. Submitted availability should cover all period slots.
  select count(*) into v_count
  from public.dynamic_availability_submissions sub
  where sub.status='submitted'
    and (
      (select count(*) from public.dynamic_availability_entries e where e.submission_id=sub.id)
      <
      (select count(*) from public.dynamic_availability_slots s where s.period_id=sub.period_id)
    );
  if v_count=0 then
    v_checks := v_checks || jsonb_build_array(jsonb_build_object(
      'code','complete_submissions','status','pass','area','availability','title','כל ההגשות הסופיות מלאות',
      'message','לא נמצאה הגשה submitted שחסרים בה סטטוסים למשמרות התקופה.','count',0
    )); v_pass_count := v_pass_count + 1;
  else
    v_checks := v_checks || jsonb_build_array(jsonb_build_object(
      'code','complete_submissions','status','fail','area','availability','title','יש הגשות סופיות חלקיות',
      'message','Submitted חייב לכסות את כל ה-slots של התקופה.','count',v_count
    )); v_fail_count := v_fail_count + 1;
  end if;

  -- 10. Pending exchange requests must still match assignment ownership.
  select count(*) into v_count
  from public.dynamic_shift_exchange_requests r
  join public.dynamic_schedule_published_assignments ra on ra.id=r.requester_assignment_id
  left join public.dynamic_schedule_published_assignments ca on ca.id=r.counterparty_assignment_id
  where r.status in ('pending_counterparty','pending_manager')
    and (
      ra.user_id<>r.requester_user_id
      or (r.swap_type='two_way' and (ca.id is null or ca.user_id<>r.counterparty_user_id))
    );
  if v_count=0 then
    v_checks := v_checks || jsonb_build_array(jsonb_build_object(
      'code','pending_exchange_ownership','status','pass','area','exchanges','title','בקשות חילוף ממתינות עקביות עם השיבוצים',
      'message','לא נמצאה בקשה פעילה שמצב הבעלות שלה השתנה מתחת ל-workflow.','count',0
    )); v_pass_count := v_pass_count + 1;
  else
    v_checks := v_checks || jsonb_build_array(jsonb_build_object(
      'code','pending_exchange_ownership','status','fail','area','exchanges','title','יש בקשות חילוף ממתינות שאינן עקביות',
      'message','יש לבטל/לתקן בקשות שהשיבוץ המקורי שלהן כבר השתנה.','count',v_count
    )); v_fail_count := v_fail_count + 1;
  end if;

  -- 11. GVK migration reconciliation. This is pilot-only and deliberately kept
  -- out of the generic runtime checks above.
  select * into v_latest_run
  from public.gvk_legacy_migration_runs
  where status='completed'
  order by completed_at desc nulls last, created_at desc
  limit 1;

  if v_latest_run.id is not null then
    -- Dispatcher months.
    for v_rec in
      select 'dispatcher'::text as source, sp.year, sp.month,
             count(ss.id)::integer as legacy_count,
             coalesce((select count(*) from public.dynamic_schedule_published_assignments da
                       join public.dynamic_schedule_publications dp on dp.id=da.publication_id
                       where dp.job_type_id=v_latest_run.dispatcher_job_type_id and dp.year=sp.year and dp.month=sp.month),0)::integer as dynamic_count,
             coalesce((select sum(du.intentionally_unassigned_count) from public.dynamic_schedule_published_unassigned du
                       join public.dynamic_schedule_publications dp on dp.id=du.publication_id
                       where dp.job_type_id=v_latest_run.dispatcher_job_type_id and dp.year=sp.year and dp.month=sp.month),0)::integer as unassigned_count
      from public.schedule_periods sp
      left join public.schedule_shifts ss on ss.period_id=sp.id
      where sp.status::text in ('published','archived') and (sp.year*100+sp.month)>=v_current_ym
      group by sp.id,sp.year,sp.month
      union all
      select 'on_call', sp.year, sp.month,
             count(d.id)::integer,
             coalesce((select count(*) from public.dynamic_schedule_published_assignments da
                       join public.dynamic_schedule_publications dp on dp.id=da.publication_id
                       where dp.job_type_id=v_latest_run.on_call_job_type_id and dp.year=sp.year and dp.month=sp.month),0)::integer,
             coalesce((select sum(du.intentionally_unassigned_count) from public.dynamic_schedule_published_unassigned du
                       join public.dynamic_schedule_publications dp on dp.id=du.publication_id
                       where dp.job_type_id=v_latest_run.on_call_job_type_id and dp.year=sp.year and dp.month=sp.month),0)::integer
      from public.driver_schedule_periods sp
      left join public.driver_schedule_days d on d.period_id=sp.id
      where sp.status::text in ('published','archived') and (sp.year*100+sp.month)>=v_current_ym
      group by sp.id,sp.year,sp.month
      union all
      select 'morning_driver', sp.year, sp.month,
             count(a.id)::integer,
             coalesce((select count(*) from public.dynamic_schedule_published_assignments da
                       join public.dynamic_schedule_publications dp on dp.id=da.publication_id
                       where dp.job_type_id=v_latest_run.morning_driver_job_type_id and dp.year=sp.year and dp.month=sp.month),0)::integer,
             coalesce((select sum(du.intentionally_unassigned_count) from public.dynamic_schedule_published_unassigned du
                       join public.dynamic_schedule_publications dp on dp.id=du.publication_id
                       where dp.job_type_id=v_latest_run.morning_driver_job_type_id and dp.year=sp.year and dp.month=sp.month),0)::integer
      from public.morning_driver_schedule_periods sp
      left join public.morning_driver_schedule_assignments a on a.schedule_period_id=sp.id
      where sp.status::text in ('published','archived') and (sp.year*100+sp.month)>=v_current_ym
      group by sp.id,sp.year,sp.month
      order by year,month,source
    loop
      v_reconciliation := v_reconciliation || jsonb_build_array(jsonb_build_object(
        'source',v_rec.source,'year',v_rec.year,'month',v_rec.month,
        'legacyCount',v_rec.legacy_count,'dynamicAssignedCount',v_rec.dynamic_count,
        'dynamicUnassignedCount',v_rec.unassigned_count,
        'coveredCount',v_rec.dynamic_count+v_rec.unassigned_count,
        'matches',v_rec.legacy_count=(v_rec.dynamic_count+v_rec.unassigned_count)
      ));
    end loop;

    select count(*) into v_count
    from jsonb_array_elements(v_reconciliation) item
    where coalesce((item->>'matches')::boolean,false)=false;

    if v_count=0 then
      v_checks := v_checks || jsonb_build_array(jsonb_build_object(
        'code','gvk_live_reconciliation','status','pass','area','migration','title','התאמת לוחות GVK החיים עברה',
        'message','בכל חודש חי שהומר, הכיסוי הדינמי (מאויש + לא מאויש במכוון) תואם לכמות רשומות Legacy.','count',0
      )); v_pass_count := v_pass_count + 1;
    else
      v_checks := v_checks || jsonb_build_array(jsonb_build_object(
        'code','gvk_live_reconciliation','status','warn','area','migration','title','יש חודשי GVK עם פער בין Legacy ל-Dynamic',
        'message','הטבלה המפורטת למטה תראה אם פער 163→68 נובע מלוחות שכבר היו בדינמי או מכיסוי חסר.','count',v_count
      )); v_warn_count := v_warn_count + 1;
    end if;
  else
    v_checks := v_checks || jsonb_build_array(jsonb_build_object(
      'code','gvk_live_reconciliation','status','warn','area','migration','title','לא נמצאה הרצת מיגרציית GVK שהושלמה',
      'message','אין נתוני reconciliation לפיילוט.','count',0
    )); v_warn_count := v_warn_count + 1;
  end if;

  return jsonb_build_object(
    'generatedAt',now(),
    'readyForFullQa',v_fail_count=0,
    'summary',jsonb_build_object(
      'passes',v_pass_count,'warnings',v_warn_count,'failures',v_fail_count,
      'dynamicFirstEnabled',v_cutover,
      'activeJobTypes',v_active_job_types,
      'activeMemberships',v_active_memberships,
      'dynamicUsers',v_dynamic_users,
      'publications',v_publications,
      'assignments',v_assignments,
      'pendingExchanges',v_pending_exchanges
    ),
    'checks',v_checks,
    'gvkReconciliation',v_reconciliation
  );
end;
$$;


ALTER FUNCTION "public"."get_dynamic_pilot_qa_report"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_dynamic_published_schedule_editor"("requested_publication_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_actor uuid := auth.uid();
  v_publication public.dynamic_schedule_publications%rowtype;
  v_job public.job_types%rowtype;
  v_current_month date := date_trunc('month', (now() at time zone 'Asia/Jerusalem')::date)::date;
  v_publication_month date;
  v_editable boolean := false;
  v_reason text := null;
  v_members jsonb := '[]'::jsonb;
  v_slots jsonb := '[]'::jsonb;
begin
  if v_actor is null then raise exception 'not authenticated'; end if;

  select * into v_publication
  from public.dynamic_schedule_publications
  where id=requested_publication_id;
  if v_publication.id is null then raise exception 'publication not found'; end if;
  if not public.has_dynamic_job_type_permission('schedule.view_team', v_publication.job_type_id, v_actor) then raise exception 'not allowed'; end if;

  select * into v_job from public.job_types where id=v_publication.job_type_id;
  if v_job.id is null then raise exception 'job type not found'; end if;

  v_publication_month := make_date(v_publication.year,v_publication.month,1);
  if v_publication.status <> 'published' then
    v_reason := 'לוח זה אינו פתוח לעריכה משום שהוא בארכיון.';
  elsif v_publication_month = v_current_month
     or v_publication_month = (v_current_month + interval '1 month')::date then
    v_editable := true;
  elsif v_publication_month < v_current_month then
    v_reason := 'לוח היסטורי נשמר לקריאה בלבד.';
  else
    v_reason := 'ניתן לערוך לוח מפורסם רק בחודש הנוכחי או בחודש הבא.';
  end if;

  select coalesce(jsonb_agg(
    jsonb_build_object('userId',m.user_id,'displayName',p.display_name)
    order by p.display_name
  ),'[]'::jsonb)
  into v_members
  from public.job_type_memberships m
  join public.profiles p on p.id=m.user_id
  where m.job_type_id=v_publication.job_type_id
    and p.is_active=true;

  select coalesce(jsonb_agg(
    jsonb_build_object(
      'slotId',sl.id,
      'shiftDate',sl.shift_date,
      'shiftCode',sl.shift_code,
      'shiftName',sl.shift_name,
      'startTime',sl.start_time,
      'endTime',sl.end_time,
      'intentionallyUnassignedCount',coalesce(pu.intentionally_unassigned_count,0),
      'assignments',coalesce((
        select jsonb_agg(
          jsonb_build_object(
            'id',a.id,
            'userId',a.user_id,
            'displayName',p.display_name,
            'userIsActive',coalesce(p.is_active,false),
            'originalUserId',a.original_user_id,
            'originalDisplayName',op.display_name,
            'managerEdited',a.manager_edited,
            'managerOverrideNote',a.manager_override_note
          ) order by p.display_name
        )
        from public.dynamic_schedule_published_assignments a
        left join public.profiles p on p.id=a.user_id
        left join public.profiles op on op.id=a.original_user_id
        where a.publication_id=v_publication.id and a.slot_id=sl.id
      ),'[]'::jsonb)
    ) order by sl.shift_date,sl.start_time,sl.shift_name
  ),'[]'::jsonb)
  into v_slots
  from public.dynamic_availability_slots sl
  left join public.dynamic_schedule_published_unassigned pu
    on pu.publication_id=v_publication.id and pu.slot_id=sl.id
  where sl.period_id=v_publication.availability_period_id;

  return jsonb_build_object(
    'publicationId',v_publication.id,
    'jobTypeId',v_job.id,
    'jobTypeName',v_job.name,
    'year',v_publication.year,
    'month',v_publication.month,
    'editable',v_editable,
    'editabilityReason',v_reason,
    'members',v_members,
    'slots',v_slots
  );
end;
$$;


ALTER FUNCTION "public"."get_dynamic_published_schedule_editor"("requested_publication_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_dynamic_role_workspace"("requested_job_type_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  current_user_id uuid := auth.uid();
  role_record public.job_types%rowtype;
  historical_period_count integer := 0;
  historical_assignment_count integer := 0;
  historical_availability_count integer := 0;
  membership_count integer := 0;
  materialization_count integer := 0;
begin
  if current_user_id is null then
    raise exception 'not authenticated';
  end if;

  if not exists (
    select 1
    from public.user_permissions up
    where up.user_id = current_user_id
      and up.permission_key in ('users.view', 'users.manage', 'statistics.view')
  ) then
    raise exception 'not allowed';
  end if;

  select * into role_record
  from public.job_types jt
  where jt.id = requested_job_type_id;

  if not found then
    raise exception 'job type not found';
  end if;

  select count(*) into membership_count
  from public.job_type_memberships m
  where m.job_type_id = requested_job_type_id;

  select count(*) into materialization_count
  from public.job_type_schedule_materializations m
  where m.job_type_id = requested_job_type_id;

  select count(*) into historical_period_count
  from public.dynamic_historical_periods hp
  where hp.job_type_id = requested_job_type_id;

  select count(*) into historical_assignment_count
  from public.dynamic_historical_assignments ha
  join public.dynamic_historical_periods hp on hp.id = ha.historical_period_id
  where hp.job_type_id = requested_job_type_id;

  select count(*) into historical_availability_count
  from public.dynamic_historical_availability hv
  join public.dynamic_historical_periods hp on hp.id = hv.historical_period_id
  where hp.job_type_id = requested_job_type_id;

  return jsonb_build_object(
    'jobTypeId', role_record.id,
    'jobTypeName', role_record.name,
    'isActive', role_record.is_active,
    'schedulingStrategy', role_record.scheduling_strategy,
    'memberCount', membership_count,
    'materializationCount', materialization_count,
    'historicalTotals', jsonb_build_object(
      'periods', historical_period_count,
      'assignments', historical_assignment_count,
      'availability', historical_availability_count
    ),
    'periods', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'id', hp.id,
          'year', hp.year,
          'month', hp.month,
          'sourceKind', hp.source_kind,
          'sourceStatus', hp.source_status,
          'importedAt', hp.imported_at,
          'assignments', (
            select count(*) from public.dynamic_historical_assignments ha
            where ha.historical_period_id = hp.id
          ),
          'availability', (
            select count(*) from public.dynamic_historical_availability hv
            where hv.historical_period_id = hp.id
          ),
          'assignedUsers', coalesce((
            select jsonb_agg(distinct jsonb_build_object(
              'userId', p.id,
              'displayName', p.display_name
            ))
            from public.dynamic_historical_assignments ha
            join public.profiles p on p.id = ha.assigned_user_id
            where ha.historical_period_id = hp.id
          ), '[]'::jsonb)
        ) order by hp.year desc, hp.month desc
      )
      from public.dynamic_historical_periods hp
      where hp.job_type_id = requested_job_type_id
    ), '[]'::jsonb)
  );
end;
$$;


ALTER FUNCTION "public"."get_dynamic_role_workspace"("requested_job_type_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_dynamic_schedule_calendar_workspace"("requested_year" integer, "requested_month" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  actor uuid := auth.uid();
  result jsonb;
begin
  if actor is null then
    raise exception 'not authenticated';
  end if;

  if requested_year not between 2020 and 2100 or requested_month not between 1 and 12 then
    raise exception 'invalid year or month';
  end if;

  if not exists (
    select 1
    from public.job_types jt
    where jt.is_active = true
      and jt.legacy_role is null
      and (
        public.has_dynamic_job_type_permission('availability.view_team', jt.id, actor)
        or public.has_dynamic_job_type_permission('availability.open_period', jt.id, actor)
        or public.has_dynamic_job_type_permission('availability.close_period', jt.id, actor)
        or public.has_dynamic_job_type_permission('availability.manage_submissions', jt.id, actor)
        or public.has_dynamic_job_type_permission('schedule.view_team', jt.id, actor)
        or public.has_dynamic_job_type_permission('schedule.create_draft', jt.id, actor)
        or public.has_dynamic_job_type_permission('schedule.edit_draft', jt.id, actor)
        or public.has_dynamic_job_type_permission('schedule.publish', jt.id, actor)
        or public.has_dynamic_job_type_permission('schedule.edit_published', jt.id, actor)
        or public.has_dynamic_job_type_permission('rotation.generate', jt.id, actor)
      )
  ) then
    raise exception 'not allowed';
  end if;

  with eligible_jobs as (
    select
      jt.id,
      jt.name,
      jt.scheduling_config,
      coalesce(
        (
          select mat.work_mode
          from public.job_type_schedule_materializations mat
          where mat.job_type_id = jt.id
            and mat.effective_month <= make_date(requested_year, requested_month, 1)
          order by mat.effective_month desc
          limit 1
        ),
        jt.scheduling_config #>> '{shiftPattern,workMode}',
        'shifts'
      ) as work_mode
    from public.job_types jt
    where jt.is_active = true
      and jt.legacy_role is null
      and (
        public.has_dynamic_job_type_permission('availability.view_team', jt.id, actor)
        or public.has_dynamic_job_type_permission('availability.open_period', jt.id, actor)
        or public.has_dynamic_job_type_permission('availability.close_period', jt.id, actor)
        or public.has_dynamic_job_type_permission('availability.manage_submissions', jt.id, actor)
        or public.has_dynamic_job_type_permission('schedule.view_team', jt.id, actor)
        or public.has_dynamic_job_type_permission('schedule.create_draft', jt.id, actor)
        or public.has_dynamic_job_type_permission('schedule.edit_draft', jt.id, actor)
        or public.has_dynamic_job_type_permission('schedule.publish', jt.id, actor)
        or public.has_dynamic_job_type_permission('schedule.edit_published', jt.id, actor)
        or public.has_dynamic_job_type_permission('rotation.generate', jt.id, actor)
      )
  ),
  live_slot_rows as (
    select
      pub.id as source_period_id,
      sl.id as source_slot_id,
      ej.id as job_type_id,
      ej.name as job_type_name,
      sl.shift_date,
      sl.shift_code,
      coalesce(nullif(tmpl.name, ''), nullif(sl.shift_name, ''), sl.shift_code) as shift_name,
      to_char(display_bounds.start_at::time, 'HH24:MI:SS') as start_time,
      to_char(display_bounds.end_at::time, 'HH24:MI:SS') as end_time,
      sl.holiday_name,
      coalesce(
        case
          when sl.metadata ? 'contains200Percent'
            and lower(coalesce(sl.metadata->>'contains200Percent','')) in ('true','false')
            then (sl.metadata->>'contains200Percent')::boolean
          else null
        end,
        tmpl.contains_200_percent,
        false
      ) as contains_200_percent,
      coalesce(
        case when sl.metadata ? 'premium200Hours' then nullif(sl.metadata->>'premium200Hours','')::numeric else null end,
        tmpl.premium_200_hours,
        0
      ) as premium_200_hours,
      coalesce(sl.target_workers, 1)::integer as target_workers,
      coalesce(slot_assignment_count.assigned_count, 0)::integer as assigned_count
    from public.dynamic_schedule_publications pub
    join eligible_jobs ej on ej.id = pub.job_type_id
    join public.dynamic_availability_periods ap on ap.id = pub.availability_period_id
    join public.dynamic_availability_slots sl on sl.period_id = ap.id
    cross join lateral public.dynamic_resolve_assignment_local_interval(
      sl.shift_date,
      sl.start_time,
      sl.end_time,
      ej.work_mode,
      ej.scheduling_config
    ) display_bounds
    left join lateral (
      select count(a.id)::integer as assigned_count
      from public.dynamic_schedule_published_assignments a
      where a.publication_id = pub.id
        and a.slot_id = sl.id
    ) slot_assignment_count on true
    left join lateral (
      select st.name, st.contains_200_percent, st.premium_200_hours
      from public.job_type_schedule_materializations mat
      left join public.job_type_materialized_day_rules dr
        on dr.materialization_id = mat.id
       and dr.day_kind = coalesce(
         nullif(sl.source_day_kind, ''),
         nullif(sl.effective_day_kind, ''),
         case extract(dow from sl.shift_date)::integer
           when 5 then 'friday'
           when 6 then 'saturday'
           else 'weekday'
         end
       )
      join public.job_type_materialized_shift_templates st
        on st.materialization_id = mat.id
       and st.is_active = true
       and st.day_kind = (
         case
           when nullif(sl.effective_day_kind, '') in ('weekday','friday','saturday','holiday_full')
             then sl.effective_day_kind
           when dr.behavior = 'inherit' and dr.inherit_day_kind is not null
             then dr.inherit_day_kind
           when dr.day_kind is not null
             then dr.day_kind
           else case extract(dow from sl.shift_date)::integer
             when 5 then 'friday'
             when 6 then 'saturday'
             else 'weekday'
           end
         end
       )
      where mat.job_type_id = ej.id
        and mat.effective_month <= make_date(requested_year, requested_month, 1)
        and st.start_time = sl.start_time
        and st.end_time = sl.end_time
      order by mat.effective_month desc,
        case when st.code = sl.shift_code then 0 else 1 end,
        st.sort_order,
        st.name
      limit 1
    ) tmpl on true
    where pub.year = requested_year
      and pub.month = requested_month
      and pub.status in ('published', 'archived')
  ),
  live_groups as (
    select
      lsr.source_period_id,
      lsr.job_type_id,
      lsr.job_type_name,
      lsr.shift_date,
      (array_agg(
        lsr.shift_code
        order by lsr.assigned_count desc, lsr.source_slot_id
      ))[1] as shift_code,
      lsr.shift_name,
      lsr.start_time,
      lsr.end_time,
      max(lsr.holiday_name) as holiday_name,
      bool_or(lsr.contains_200_percent) as contains_200_percent,
      max(lsr.premium_200_hours) as premium_200_hours,
      max(lsr.target_workers)::integer as required_count,
      array_agg(
        lsr.source_slot_id
        order by lsr.assigned_count desc, lsr.source_slot_id
      ) as source_slot_ids
    from live_slot_rows lsr
    group by
      lsr.source_period_id,
      lsr.job_type_id,
      lsr.job_type_name,
      lsr.shift_date,
      lsr.shift_name,
      lsr.start_time,
      lsr.end_time
  ),
  live_slots as (
    select
      'publication'::text as period_source,
      lg.source_period_id,
      lg.source_slot_ids[1] as source_slot_id,
      lg.job_type_id,
      lg.job_type_name,
      lg.shift_date,
      lg.shift_code,
      lg.shift_name,
      lg.start_time,
      lg.end_time,
      lg.holiday_name,
      lg.contains_200_percent,
      lg.premium_200_hours,
      coalesce(assignment_data.assignments, '[]'::jsonb) as assignments,
      greatest(lg.required_count - coalesce(assignment_data.assigned_count, 0), 0)::integer as unassigned_count,
      greatest(lg.required_count, coalesce(assignment_data.assigned_count, 0), 1)::integer as required_count
    from live_groups lg
    left join lateral (
      select
        count(*)::integer as assigned_count,
        coalesce(
          jsonb_agg(
            jsonb_build_object(
              'userId', assignee.user_id,
              'displayName', assignee.display_name,
              'scheduleName', assignee.schedule_name
            ) order by coalesce(assignee.schedule_name, assignee.display_name)
          ),
          '[]'::jsonb
        ) as assignments
      from (
        select distinct on (a.user_id)
          a.user_id,
          coalesce(p.display_name, 'משתמש לא פעיל') as display_name,
          nullif(trim(p.schedule_name), '') as schedule_name
        from public.dynamic_schedule_published_assignments a
        left join public.profiles p on p.id = a.user_id
        where a.publication_id = lg.source_period_id
          and a.slot_id = any(lg.source_slot_ids)
        order by a.user_id, coalesce(nullif(trim(p.schedule_name), ''), p.display_name, 'משתמש לא פעיל')
      ) assignee
    ) assignment_data on true
  ),
  historical_rows as (
    select
      hp.id as source_period_id,
      ej.id as job_type_id,
      ej.name as job_type_name,
      hp.source_kind,
      ha.id as historical_assignment_id,
      ha.work_date as shift_date,
      coalesce(ha.shift_code, hp.source_kind || '-' || ha.work_date::text) as shift_code,
      coalesce(
        nullif(tmpl.name, ''),
        nullif(ha.source_payload->>'shift_name', ''),
        nullif(ha.source_payload #>> '{shift,name}', ''),
        case hp.source_kind
          when 'on_call' then 'כוננות יומית'
          when 'morning_driver' then 'כוננות בוקר'
          else null
        end,
        nullif(ha.shift_code, ''),
        'שיבוץ'
      ) as shift_name,
      coalesce(
        to_char(ha.starts_at at time zone 'Asia/Jerusalem', 'HH24:MI:SS'),
        nullif(ha.source_payload #>> '{shift,start_time}', ''),
        case when hp.source_kind = 'on_call' then '00:00:00' else '00:00:00' end
      ) as start_time,
      coalesce(
        to_char(ha.ends_at at time zone 'Asia/Jerusalem', 'HH24:MI:SS'),
        nullif(ha.source_payload #>> '{shift,end_time}', ''),
        case when hp.source_kind = 'on_call' then '23:59:00' else '00:00:00' end
      ) as end_time,
      coalesce(
        nullif(ha.source_payload->>'holiday_name', ''),
        nullif(ha.source_payload #>> '{shift,holiday_name}', ''),
        holiday.event_name
      ) as holiday_name,
      coalesce(
        case
          when lower(coalesce(ha.source_payload->>'is_premium','')) in ('true','false')
            then (ha.source_payload->>'is_premium')::boolean
          else null
        end,
        case
          when lower(coalesce(ha.source_payload #>> '{shift,is_premium}','')) in ('true','false')
            then (ha.source_payload #>> '{shift,is_premium}')::boolean
          else null
        end,
        tmpl.contains_200_percent,
        false
      ) as contains_200_percent,
      coalesce(tmpl.premium_200_hours, 0) as premium_200_hours,
      ha.assigned_user_id,
      p.display_name,
      nullif(trim(p.schedule_name), '') as schedule_name,
      ha.is_intentionally_unassigned
    from public.dynamic_historical_periods hp
    join eligible_jobs ej on ej.id = hp.job_type_id
    join public.dynamic_historical_assignments ha on ha.historical_period_id = hp.id
    left join public.profiles p on p.id = ha.assigned_user_id
    left join lateral (
      select csd.event_name
      from public.calendar_special_days csd
      where csd.event_date = ha.work_date
      order by
        case when csd.source_name = 'manual' then 0 else 1 end,
        csd.event_name
      limit 1
    ) holiday on true
    left join lateral (
      select st.name, st.contains_200_percent, st.premium_200_hours
      from public.job_type_schedule_materializations mat
      join public.job_type_materialized_shift_templates st
        on st.materialization_id = mat.id
       and st.is_active = true
      where mat.job_type_id = ej.id
      order by
        case when mat.effective_month <= make_date(requested_year, requested_month, 1) then 0 else 1 end,
        abs(mat.effective_month - make_date(requested_year, requested_month, 1)),
        case when st.code = ha.shift_code then 0 else 1 end,
        case
          when ha.starts_at is not null and ha.ends_at is not null
            and st.start_time = (ha.starts_at at time zone 'Asia/Jerusalem')::time
            and st.end_time = (ha.ends_at at time zone 'Asia/Jerusalem')::time
          then 0 else 1
        end,
        case
          when ha.starts_at is not null then
            abs(extract(epoch from (st.start_time - (ha.starts_at at time zone 'Asia/Jerusalem')::time)))
          else 0
        end
        + case
            when ha.ends_at is not null then
              abs(extract(epoch from (st.end_time - (ha.ends_at at time zone 'Asia/Jerusalem')::time)))
            else 0
          end,
        st.sort_order,
        st.name
      limit 1
    ) tmpl on true
    where hp.year = requested_year
      and hp.month = requested_month
      and ha.work_date is not null
      and not exists (
        select 1
        from public.dynamic_schedule_publications pub
        where pub.job_type_id = hp.job_type_id
          and pub.year = requested_year
          and pub.month = requested_month
          and pub.status in ('published', 'archived')
      )
  ),
  historical_slots as (
    select
      'history'::text as period_source,
      hr.source_period_id,
      null::uuid as source_slot_id,
      hr.job_type_id,
      hr.job_type_name,
      hr.shift_date,
      hr.shift_code,
      hr.shift_name,
      hr.start_time,
      hr.end_time,
      max(hr.holiday_name) as holiday_name,
      bool_or(hr.contains_200_percent) as contains_200_percent,
      max(hr.premium_200_hours) as premium_200_hours,
      coalesce(
        jsonb_agg(
          jsonb_build_object(
            'userId', hr.assigned_user_id,
            'displayName', coalesce(hr.display_name, 'משתמש לא פעיל'),
            'scheduleName', hr.schedule_name
          ) order by coalesce(hr.schedule_name, hr.display_name, 'משתמש לא פעיל')
        ) filter (where hr.assigned_user_id is not null and not hr.is_intentionally_unassigned),
        '[]'::jsonb
      ) as assignments,
      count(*) filter (
        where hr.assigned_user_id is null or hr.is_intentionally_unassigned
      )::integer as unassigned_count,
      greatest(count(*)::integer, 1) as required_count
    from historical_rows hr
    group by
      hr.source_period_id,
      hr.job_type_id,
      hr.job_type_name,
      hr.shift_date,
      hr.shift_code,
      hr.shift_name,
      hr.start_time,
      hr.end_time
  ),
  all_slots as (
    select * from live_slots
    union all
    select * from historical_slots
  )
  select jsonb_build_object(
    'year', requested_year,
    'month', requested_month,
    'generatedAt', now(),
    'jobTypes', coalesce((
      select jsonb_agg(
        jsonb_build_object('id', ej.id, 'name', ej.name)
        order by ej.name
      )
      from eligible_jobs ej
      where exists (
        select 1 from all_slots s where s.job_type_id = ej.id
      )
    ), '[]'::jsonb),
    'slots', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'periodSource', s.period_source,
          'sourcePeriodId', s.source_period_id,
          'sourceSlotId', s.source_slot_id,
          'jobTypeId', s.job_type_id,
          'jobTypeName', s.job_type_name,
          'shiftDate', s.shift_date,
          'shiftCode', s.shift_code,
          'shiftName', s.shift_name,
          'startTime', s.start_time,
          'endTime', s.end_time,
          'holidayName', s.holiday_name,
          'contains200Percent', s.contains_200_percent,
          'premium200Hours', s.premium_200_hours,
          'assignments', s.assignments,
          'unassignedCount', s.unassigned_count,
          'requiredCount', s.required_count
        )
        order by s.shift_date, s.start_time, s.job_type_name, s.shift_name
      )
      from all_slots s
    ), '[]'::jsonb)
  ) into result;

  return result;
end;
$$;


ALTER FUNCTION "public"."get_dynamic_schedule_calendar_workspace"("requested_year" integer, "requested_month" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_dynamic_schedule_draft_editor"("requested_draft_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_user uuid := auth.uid();
  d public.dynamic_schedule_shadow_drafts%rowtype;
  j public.job_types%rowtype;
  p public.dynamic_availability_periods%rowtype;
  v_metrics jsonb;
begin
  if v_user is null then raise exception 'not authenticated'; end if;

  select * into d from public.dynamic_schedule_shadow_drafts where id=requested_draft_id;
  if not public.has_dynamic_job_type_permission('schedule.view_team', d.job_type_id, v_user) then raise exception 'not allowed'; end if;
  if d.id is null then raise exception 'draft not found'; end if;
  select * into j from public.job_types where id=d.job_type_id;
  select * into p from public.dynamic_availability_periods where id=d.availability_period_id;
  v_metrics := public.dynamic_refresh_draft_metrics(d.id);

  return jsonb_build_object(
    'draftId',d.id,'jobTypeId',d.job_type_id,'jobTypeName',j.name,
    'year',d.year,'month',d.month,'status',(select status from public.dynamic_schedule_shadow_drafts where id=d.id),
    'metrics',v_metrics,
    'slots',coalesce((
      select jsonb_agg(jsonb_build_object(
        'slotId',sl.id,'date',sl.shift_date,'shiftCode',sl.shift_code,'shiftName',sl.shift_name,
        'startTime',sl.start_time,'endTime',sl.end_time,
        'minWorkers',sl.min_workers,'targetWorkers',sl.target_workers,'maxWorkers',sl.max_workers,
        'intentionallyUnassignedCount',least(coalesce(o.intentionally_unassigned_count,0),greatest(sl.min_workers-coalesce(ac.required_count,0),0)),
        'overrideNote',o.note,
        'assignments',coalesce((
          select jsonb_agg(jsonb_build_object(
            'id',a.id,'userId',a.user_id,'displayName',ap.display_name,
            'engineUserId',a.engine_user_id,'engineDisplayName',ep.display_name,
            'tier',a.assignment_tier,'score',a.score,'reasons',a.reasons,
            'managerEdited',a.manager_edited_at is not null or (a.engine_user_id is not null and a.engine_user_id<>a.user_id),
            'managerOverrideNote',a.manager_override_note
          ) order by case when a.assignment_tier='required' then 0 else 1 end, ap.display_name)
          from public.dynamic_schedule_shadow_assignments a
          join public.profiles ap on ap.id=a.user_id
          left join public.profiles ep on ep.id=a.engine_user_id
          where a.draft_id=d.id and a.slot_id=sl.id
        ),'[]'::jsonb),
        'candidates',coalesce((
          select jsonb_agg(jsonb_build_object(
            'userId',m.user_id,'displayName',mp.display_name,
            'availabilityStatus',e.availability_status,
            'assignedCount',(select count(*) from public.dynamic_schedule_shadow_assignments xa where xa.draft_id=d.id and xa.user_id=m.user_id),
            'maximum',t.requested_max,
            'isAssignedHere',exists(select 1 from public.dynamic_schedule_shadow_assignments xa where xa.draft_id=d.id and xa.slot_id=sl.id and xa.user_id=m.user_id)
          ) order by
            case e.availability_status when 'preferred' then 0 when 'available' then 1 when 'avoid' then 2 when 'unavailable' then 3 else 4 end,
            mp.display_name)
          from public.job_type_memberships m
          join public.profiles mp on mp.id=m.user_id and mp.is_active=true
          left join public.dynamic_availability_submissions sub on sub.period_id=p.id and sub.user_id=m.user_id
          left join public.dynamic_availability_entries e on e.submission_id=sub.id and e.slot_id=sl.id
          left join public.dynamic_schedule_shadow_targets t on t.draft_id=d.id and t.user_id=m.user_id
          where m.job_type_id=d.job_type_id
        ),'[]'::jsonb)
      ) order by sl.shift_date,sl.start_time,sl.shift_name)
      from public.dynamic_availability_slots sl
      left join (
        select slot_id,count(*) filter(where assignment_tier='required')::integer required_count
        from public.dynamic_schedule_shadow_assignments where draft_id=d.id group by slot_id
      ) ac on ac.slot_id=sl.id
      left join public.dynamic_schedule_draft_slot_overrides o on o.draft_id=d.id and o.slot_id=sl.id
      where sl.period_id=p.id
    ),'[]'::jsonb)
  );
end;
$$;


ALTER FUNCTION "public"."get_dynamic_schedule_draft_editor"("requested_draft_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_dynamic_schedule_export_workspace"("requested_year" integer, "requested_month" integer, "requested_job_type_ids" "uuid"[] DEFAULT NULL::"uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  actor uuid := auth.uid();
  month_start date;
  month_end date;
  result jsonb;
begin
  if actor is null then raise exception 'not authenticated'; end if;
  if requested_year < 2020 or requested_year > 2100 or requested_month < 1 or requested_month > 12 then
    raise exception 'invalid month';
  end if;

  if not exists (select 1 from public.profiles p where p.id = actor and p.is_active = true) then
    raise exception 'inactive user';
  end if;

  -- Export is an administrative operation. Keep the same broad gate used by the
  -- settings/export surface while the per-job-type data remains Dynamic-only.
  if not (
    exists (select 1 from public.profiles p where p.id = actor and p.role = 'admin')
    or public.current_user_has_permission('users.manage')
    or public.current_user_has_permission('schedule.export')
  ) then
    raise exception 'permission denied';
  end if;

  month_start := make_date(requested_year, requested_month, 1);
  month_end := (month_start + interval '1 month')::date;

  with eligible_jobs as (
    select jt.id, jt.name
    from public.job_types jt
    where jt.is_active = true
      and jt.legacy_role is null
      and (requested_job_type_ids is null or cardinality(requested_job_type_ids) = 0 or jt.id = any(requested_job_type_ids))
  ),
  raw_slots as (
    select
      pub.id as publication_id,
      sl.id as slot_id,
      ej.id as job_type_id,
      ej.name as job_type_name,
      sl.shift_date,
      sl.shift_code,
      coalesce(nullif(sl.shift_name, ''), sl.shift_code) as shift_name,
      to_char(sl.start_time, 'HH24:MI:SS') as start_time,
      to_char(sl.end_time, 'HH24:MI:SS') as end_time,
      sl.holiday_name,
      coalesce(
        case when sl.metadata ? 'contains200Percent'
          and lower(coalesce(sl.metadata->>'contains200Percent','')) in ('true','false')
          then (sl.metadata->>'contains200Percent')::boolean end,
        tmpl.contains_200_percent,
        false
      ) as contains_200_percent,
      coalesce(
        case when sl.metadata ? 'premium200Hours' then nullif(sl.metadata->>'premium200Hours','')::numeric end,
        tmpl.premium_200_hours,
        0
      ) as premium_200_hours,
      greatest(coalesce(sl.target_workers, 1), 1)::integer as required_count
    from public.dynamic_schedule_publications pub
    join eligible_jobs ej on ej.id = pub.job_type_id
    join public.dynamic_availability_periods ap on ap.id = pub.availability_period_id
    join public.dynamic_availability_slots sl on sl.period_id = ap.id
    left join lateral (
      select st.contains_200_percent, st.premium_200_hours
      from public.job_type_schedule_materializations mat
      left join public.job_type_materialized_day_rules dr
        on dr.materialization_id = mat.id
       and dr.day_kind = coalesce(
         nullif(sl.source_day_kind, ''),
         nullif(sl.effective_day_kind, ''),
         case extract(dow from sl.shift_date)::integer
           when 5 then 'friday'
           when 6 then 'saturday'
           else 'weekday'
         end
       )
      join public.job_type_materialized_shift_templates st
        on st.materialization_id = mat.id
       and st.is_active = true
       and st.day_kind = (
         case
           when nullif(sl.effective_day_kind, '') in ('weekday','friday','saturday','holiday_full')
             then sl.effective_day_kind
           when dr.behavior = 'inherit' and dr.inherit_day_kind is not null
             then dr.inherit_day_kind
           when dr.day_kind is not null
             then dr.day_kind
           else case extract(dow from sl.shift_date)::integer
             when 5 then 'friday'
             when 6 then 'saturday'
             else 'weekday'
           end
         end
       )
      where mat.job_type_id = ej.id
        and mat.effective_month <= month_start
        and st.start_time = sl.start_time
        and st.end_time = sl.end_time
      order by mat.effective_month desc,
        case when st.code = sl.shift_code then 0 else 1 end,
        st.sort_order,
        st.name
      limit 1
    ) tmpl on true
    where pub.status = 'published'
      and sl.shift_date >= month_start
      and sl.shift_date < month_end
  ),
  enriched as (
    select
      rs.*,
      coalesce(a.assignments, '[]'::jsonb) as assignments,
      coalesce(a.assigned_count, 0)::integer as assigned_count
    from raw_slots rs
    left join lateral (
      select
        count(*)::integer as assigned_count,
        jsonb_agg(
          jsonb_build_object(
            'userId', x.user_id,
            'displayName', x.display_name,
            'scheduleName', x.schedule_name
          ) order by coalesce(x.schedule_name, x.display_name)
        ) as assignments
      from (
        select distinct on (pa.user_id)
          pa.user_id,
          coalesce(p.display_name, 'משתמש לא פעיל') as display_name,
          nullif(trim(p.schedule_name), '') as schedule_name
        from public.dynamic_schedule_published_assignments pa
        left join public.profiles p on p.id = pa.user_id
        where pa.publication_id = rs.publication_id
          and pa.slot_id = rs.slot_id
        order by pa.user_id
      ) x
    ) a on true
  )
  select jsonb_build_object(
    'year', requested_year,
    'month', requested_month,
    'generatedAt', now(),
    'jobTypes', coalesce((
      select jsonb_agg(jsonb_build_object('id', ej.id, 'name', ej.name) order by ej.name)
      from eligible_jobs ej
    ), '[]'::jsonb),
    'slots', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'periodSource', 'publication',
          'sourcePeriodId', e.publication_id,
          'sourceSlotId', e.slot_id,
          'jobTypeId', e.job_type_id,
          'jobTypeName', e.job_type_name,
          'shiftDate', e.shift_date,
          'shiftCode', e.shift_code,
          'shiftName', e.shift_name,
          'startTime', e.start_time,
          'endTime', e.end_time,
          'holidayName', e.holiday_name,
          'contains200Percent', e.contains_200_percent,
          'premium200Hours', e.premium_200_hours,
          'assignments', e.assignments,
          'unassignedCount', greatest(e.required_count - e.assigned_count, 0),
          'requiredCount', greatest(e.required_count, e.assigned_count, 1)
        ) order by e.shift_date, e.job_type_name, e.start_time, e.shift_code
      ) from enriched e
    ), '[]'::jsonb)
  ) into result;

  return result;
end;
$$;


ALTER FUNCTION "public"."get_dynamic_schedule_export_workspace"("requested_year" integer, "requested_month" integer, "requested_job_type_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_dynamic_schedule_group_snapshot"("requested_group_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select jsonb_build_object(
    'id', sg.id,
    'code', sg.code,
    'name', sg.name,
    'description', sg.description,
    'isActive', sg.is_active,
    'legacyKind', sg.legacy_kind,
    'config', sg.config,
    'shiftTemplates', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'id', st.id,
          'code', st.code,
          'name', st.name,
          'dayKind', st.day_kind,
          'startTime', st.start_time,
          'endTime', st.end_time,
          'minWorkers', st.required_workers,
          'targetWorkers', st.target_workers,
          'maxWorkers', st.max_workers,
          'sortOrder', st.sort_order,
          'isActive', st.is_active,
          'metadata', st.metadata,
          'paySegments', coalesce((
            select jsonb_agg(
              jsonb_build_object(
                'id', ps.id,
                'startTime', ps.start_time,
                'endTime', ps.end_time,
                'multiplier', ps.multiplier,
                'label', ps.label,
                'sortOrder', ps.sort_order
              )
              order by ps.sort_order, ps.start_time
            )
            from public.schedule_shift_pay_segments ps
            where ps.shift_template_id = st.id
          ), '[]'::jsonb)
        )
        order by st.day_kind, st.sort_order, st.start_time
      )
      from public.schedule_group_shift_templates st
      where st.schedule_group_id = sg.id
    ), '[]'::jsonb),
    'dayRules', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'dayKind', dr.day_kind,
          'behavior', dr.behavior,
          'inheritDayKind', dr.inherit_day_kind,
          'metadata', dr.metadata
        )
        order by dr.day_kind
      )
      from public.schedule_group_day_rules dr
      where dr.schedule_group_id = sg.id
    ), '[]'::jsonb)
  )
  from public.schedule_groups sg
  where sg.id = requested_group_id;
$$;


ALTER FUNCTION "public"."get_dynamic_schedule_group_snapshot"("requested_group_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_dynamic_schedule_shadow_diagnostics"("requested_draft_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  current_user_id uuid:=auth.uid();
  d public.dynamic_schedule_shadow_drafts%rowtype;
  job public.job_types%rowtype;
  period public.dynamic_availability_periods%rowtype;
  no_consecutive boolean;
  max_per_day integer;
  min_rest integer;
  max_hard boolean;
begin
  if current_user_id is null then raise exception 'not authenticated'; end if;
  if not exists(select 1 from public.user_permissions up where up.user_id=current_user_id and up.permission_key in ('users.view','users.manage')) then raise exception 'not allowed'; end if;
  select * into d from public.dynamic_schedule_shadow_drafts where id=requested_draft_id;
  if d.id is null then raise exception 'draft not found'; end if;
  select * into job from public.job_types where id=d.job_type_id;
  select * into period from public.dynamic_availability_periods where id=d.availability_period_id;

  no_consecutive:=coalesce((job.scheduling_config#>>'{rules,noConsecutive,enabled}')::boolean,true);
  max_per_day:=case when coalesce((job.scheduling_config#>>'{rules,maxShiftsPerDay,enabled}')::boolean,true) then coalesce((job.scheduling_config#>>'{rules,maxShiftsPerDay,value}')::integer,1) else 999 end;
  min_rest:=case when coalesce((job.scheduling_config#>>'{rules,minimumRestMinutes,enabled}')::boolean,false) then coalesce((job.scheduling_config#>>'{rules,minimumRestMinutes,value}')::integer,0) else 0 end;
  max_hard:=coalesce(job.scheduling_config->>'maximumMode','hard')='hard';

  return jsonb_build_object(
    'draftId',d.id,'mode','shadow',
    'unfilledSlots',coalesce((
      select jsonb_agg(jsonb_build_object(
        'slotId',sl.id,'date',sl.shift_date,'shiftName',sl.shift_name,
        'startTime',sl.start_time,'endTime',sl.end_time,'requiredWorkers',sl.min_workers,
        'assignedWorkers',(select count(*) from public.dynamic_schedule_shadow_assignments a where a.draft_id=d.id and a.slot_id=sl.id and a.assignment_tier='required'),
        'unfilledPositions',greatest(sl.min_workers-(select count(*) from public.dynamic_schedule_shadow_assignments a where a.draft_id=d.id and a.slot_id=sl.id and a.assignment_tier='required'),0),
        'assignedNames',coalesce((select jsonb_agg(p.display_name order by p.display_name) from public.dynamic_schedule_shadow_assignments a join public.profiles p on p.id=a.user_id where a.draft_id=d.id and a.slot_id=sl.id),'[]'::jsonb),
        'candidates',coalesce((
          select jsonb_agg(jsonb_build_object(
            'userId',t.user_id,'displayName',p.display_name,
            'availabilityStatus',e.availability_status,
            'assigned',t.assigned_count,'maximum',t.requested_max,
            'employmentScope',t.employment_scope,'employmentFactor',t.employment_factor,
            'eligible',case
              when e.availability_status is null then false
              when e.availability_status='unavailable' then false
              when public.dynamic_shadow_candidate_block_reason(d.id,t.user_id,sl.id,max_per_day,no_consecutive,min_rest,max_hard) is not null then false
              else true end,
            'reason',case
              when sub.id is null then 'לא הוגשו אילוצים לתקופה'
              when e.availability_status is null then 'לא סומן אילוץ למשמרת'
              when e.availability_status='unavailable' then 'סומן לא זמין'
              else coalesce(public.dynamic_shadow_candidate_block_reason(d.id,t.user_id,sl.id,max_per_day,no_consecutive,min_rest,max_hard),'כשיר כעת — אם העמדה נשארה ריקה יש מקום לשיפור נוסף באופטימיזציה') end
          ) order by p.display_name)
          from public.dynamic_schedule_shadow_targets t
          join public.profiles p on p.id=t.user_id
          left join public.dynamic_availability_submissions sub on sub.period_id=period.id and sub.user_id=t.user_id
          left join public.dynamic_availability_entries e on e.submission_id=sub.id and e.slot_id=sl.id
          where t.draft_id=d.id
        ),'[]'::jsonb)
      ) order by sl.shift_date,sl.start_time)
      from public.dynamic_availability_slots sl
      where sl.period_id=period.id
        and (select count(*) from public.dynamic_schedule_shadow_assignments a where a.draft_id=d.id and a.slot_id=sl.id and a.assignment_tier='required')<sl.min_workers
    ),'[]'::jsonb)
  );
end;
$$;


ALTER FUNCTION "public"."get_dynamic_schedule_shadow_diagnostics"("requested_draft_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_dynamic_schedule_shadow_draft"("requested_draft_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare current_user_id uuid:=auth.uid(); d public.dynamic_schedule_shadow_drafts%rowtype;
begin
  if current_user_id is null then raise exception 'not authenticated'; end if;
  if not exists(select 1 from public.user_permissions up where up.user_id=current_user_id and up.permission_key in ('users.view','users.manage')) then raise exception 'not allowed'; end if;
  select * into d from public.dynamic_schedule_shadow_drafts where id=requested_draft_id; if d.id is null then raise exception 'draft not found'; end if;
  return jsonb_build_object('draftId',d.id,'jobTypeId',d.job_type_id,'year',d.year,'month',d.month,'status',d.status,'mode','shadow','feasibility',d.feasibility_snapshot,'metrics',d.metrics,
    'targets',coalesce((select jsonb_agg(jsonb_build_object('userId',t.user_id,'displayName',p.display_name,'minimum',t.requested_min,'target',t.requested_target,'maximum',t.requested_max,'availableSlots',t.available_slots,'proportionalTarget',t.proportional_target,'assigned',t.assigned_count) order by p.display_name) from public.dynamic_schedule_shadow_targets t join public.profiles p on p.id=t.user_id where t.draft_id=d.id),'[]'::jsonb),
    'assignments',coalesce((select jsonb_agg(jsonb_build_object('slotId',a.slot_id,'date',s.shift_date,'shiftName',s.shift_name,'startTime',s.start_time,'endTime',s.end_time,'userId',a.user_id,'displayName',p.display_name,'tier',a.assignment_tier,'score',a.score,'reasons',a.reasons) order by s.shift_date,s.start_time,a.assignment_tier,p.display_name) from public.dynamic_schedule_shadow_assignments a join public.dynamic_availability_slots s on s.id=a.slot_id join public.profiles p on p.id=a.user_id where a.draft_id=d.id),'[]'::jsonb)
  );
end;$$;


ALTER FUNCTION "public"."get_dynamic_schedule_shadow_draft"("requested_draft_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_dynamic_schedule_shadow_validation"("requested_draft_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  current_user_id uuid := auth.uid();
  draft_row public.dynamic_schedule_shadow_drafts%rowtype;
  job_row public.job_types%rowtype;
  legacy_supported boolean := false;
  legacy_period_id uuid := null;
  slot_rows jsonb := '[]'::jsonb;
  worker_rows jsonb := '[]'::jsonb;
  metrics_row jsonb := '{}'::jsonb;
begin
  if current_user_id is null then
    raise exception 'not authenticated';
  end if;

  if not exists (
    select 1
    from public.user_permissions permission_row
    where permission_row.user_id=current_user_id
      and permission_row.permission_key in ('users.view','users.manage')
  ) then
    raise exception 'not allowed';
  end if;

  select draft_item.*
  into draft_row
  from public.dynamic_schedule_shadow_drafts draft_item
  where draft_item.id=requested_draft_id;

  if draft_row.id is null then
    raise exception 'draft not found';
  end if;

  select job_item.*
  into job_row
  from public.job_types job_item
  where job_item.id=draft_row.job_type_id;

  legacy_supported := job_row.legacy_role='dispatcher';

  if legacy_supported then
    select period_item.id
    into legacy_period_id
    from public.schedule_periods period_item
    where period_item.year=draft_row.year
      and period_item.month=draft_row.month
    limit 1;
  end if;

  with slot_base as (
    select
      slot_item.id as slot_id,
      slot_item.shift_date,
      slot_item.shift_code,
      slot_item.shift_name,
      slot_item.start_time,
      slot_item.end_time,
      slot_item.min_workers,
      slot_item.target_workers,
      coalesce((
        select jsonb_agg(
          jsonb_build_object(
            'userId', assignment_item.user_id,
            'displayName', profile_item.display_name,
            'tier', assignment_item.assignment_tier,
            'score', assignment_item.score,
            'reasons', assignment_item.reasons,
            'availabilityStatus', availability_entry.availability_status
          )
          order by assignment_item.assignment_tier, profile_item.display_name
        )
        from public.dynamic_schedule_shadow_assignments assignment_item
        join public.profiles profile_item on profile_item.id=assignment_item.user_id
        left join public.dynamic_availability_submissions availability_submission
          on availability_submission.period_id=draft_row.availability_period_id
         and availability_submission.user_id=assignment_item.user_id
        left join public.dynamic_availability_entries availability_entry
          on availability_entry.submission_id=availability_submission.id
         and availability_entry.slot_id=assignment_item.slot_id
        where assignment_item.draft_id=draft_row.id
          and assignment_item.slot_id=slot_item.id
      ), '[]'::jsonb) as dynamic_assignments,
      case when legacy_supported and legacy_period_id is not null then (
        select jsonb_build_object(
          'shiftId', legacy_shift.id,
          'userId', legacy_shift.assigned_user_id,
          'displayName', legacy_profile.display_name,
          'isIntentionallyUnassigned', coalesce(legacy_shift.is_intentionally_unassigned,false)
        )
        from public.schedule_shifts legacy_shift
        left join public.profiles legacy_profile on legacy_profile.id=legacy_shift.assigned_user_id
        where legacy_shift.period_id=legacy_period_id
          and legacy_shift.shift_date=slot_item.shift_date
          and legacy_shift.shift_code=slot_item.shift_code
        limit 1
      ) else null end as legacy_assignment
    from public.dynamic_availability_slots slot_item
    where slot_item.period_id=draft_row.availability_period_id
  ), classified as (
    select
      slot_base.*,
      jsonb_array_length(slot_base.dynamic_assignments) as dynamic_count,
      case
        when not legacy_supported then 'unsupported'
        when slot_base.legacy_assignment is null then 'legacy_missing_shift'
        when nullif(slot_base.legacy_assignment->>'userId','') is null
          and jsonb_array_length(slot_base.dynamic_assignments)=0 then 'match'
        when nullif(slot_base.legacy_assignment->>'userId','') is not null
          and exists (
            select 1
            from jsonb_array_elements(slot_base.dynamic_assignments) assignment_json
            where assignment_json->>'userId'=slot_base.legacy_assignment->>'userId'
          ) then 'match'
        else 'different'
      end as comparison_status
    from slot_base
  )
  select coalesce(jsonb_agg(
    jsonb_build_object(
      'slotId', classified.slot_id,
      'date', classified.shift_date,
      'shiftCode', classified.shift_code,
      'shiftName', classified.shift_name,
      'startTime', classified.start_time,
      'endTime', classified.end_time,
      'requiredWorkers', classified.min_workers,
      'targetWorkers', classified.target_workers,
      'dynamicAssignments', classified.dynamic_assignments,
      'legacyAssignment', classified.legacy_assignment,
      'comparisonStatus', classified.comparison_status
    )
    order by classified.shift_date, classified.start_time, classified.shift_code
  ), '[]'::jsonb)
  into slot_rows
  from classified;

  with worker_base as (
    select
      target_item.user_id,
      profile_item.display_name,
      target_item.requested_min,
      target_item.requested_target,
      target_item.requested_max,
      target_item.proportional_target,
      target_item.assigned_count,
      coalesce(target_item.metadata->>'employmentScope','') as employment_scope,
      coalesce((
        select count(*)::integer
        from public.dynamic_schedule_shadow_assignments assignment_item
        join public.dynamic_availability_submissions submission_item
          on submission_item.period_id=draft_row.availability_period_id
         and submission_item.user_id=assignment_item.user_id
        join public.dynamic_availability_entries entry_item
          on entry_item.submission_id=submission_item.id
         and entry_item.slot_id=assignment_item.slot_id
        where assignment_item.draft_id=draft_row.id
          and assignment_item.user_id=target_item.user_id
          and entry_item.availability_status='preferred'
      ),0) as preferred_assignments,
      coalesce((
        select count(*)::integer
        from public.dynamic_schedule_shadow_assignments assignment_item
        join public.dynamic_availability_submissions submission_item
          on submission_item.period_id=draft_row.availability_period_id
         and submission_item.user_id=assignment_item.user_id
        join public.dynamic_availability_entries entry_item
          on entry_item.submission_id=submission_item.id
         and entry_item.slot_id=assignment_item.slot_id
        where assignment_item.draft_id=draft_row.id
          and assignment_item.user_id=target_item.user_id
          and entry_item.availability_status='avoid'
      ),0) as avoid_assignments
    from public.dynamic_schedule_shadow_targets target_item
    join public.profiles profile_item on profile_item.id=target_item.user_id
    where target_item.draft_id=draft_row.id
  )
  select coalesce(jsonb_agg(
    jsonb_build_object(
      'userId', worker_base.user_id,
      'displayName', worker_base.display_name,
      'minimum', worker_base.requested_min,
      'target', worker_base.requested_target,
      'maximum', worker_base.requested_max,
      'proportionalTarget', worker_base.proportional_target,
      'assigned', worker_base.assigned_count,
      'preferredAssignments', worker_base.preferred_assignments,
      'avoidAssignments', worker_base.avoid_assignments,
      'underMinimum', worker_base.requested_min is not null and worker_base.assigned_count < worker_base.requested_min,
      'aboveTarget', worker_base.requested_target is not null and worker_base.assigned_count > worker_base.requested_target,
      'atOrAboveMaximum', worker_base.requested_max is not null and worker_base.assigned_count >= worker_base.requested_max,
      'employmentScope', nullif(worker_base.employment_scope,'')
    )
    order by worker_base.display_name
  ), '[]'::jsonb)
  into worker_rows
  from worker_base;

  with slot_metric as (
    select
      slot_item.id as slot_id,
      slot_item.min_workers,
      (select count(*)::integer from public.dynamic_schedule_shadow_assignments assignment_item
       where assignment_item.draft_id=draft_row.id and assignment_item.slot_id=slot_item.id) as dynamic_count,
      case when legacy_supported and legacy_period_id is not null then (
        select legacy_shift.assigned_user_id
        from public.schedule_shifts legacy_shift
        where legacy_shift.period_id=legacy_period_id
          and legacy_shift.shift_date=slot_item.shift_date
          and legacy_shift.shift_code=slot_item.shift_code
        limit 1
      ) else null end as legacy_user_id,
      case when legacy_supported and legacy_period_id is not null then exists (
        select 1 from public.schedule_shifts legacy_shift
        where legacy_shift.period_id=legacy_period_id
          and legacy_shift.shift_date=slot_item.shift_date
          and legacy_shift.shift_code=slot_item.shift_code
      ) else false end as legacy_shift_exists
    from public.dynamic_availability_slots slot_item
    where slot_item.period_id=draft_row.availability_period_id
  ), metric_calc as (
    select
      count(*)::integer as total_slots,
      count(*) filter (where dynamic_count >= min_workers)::integer as covered_required_slots,
      count(*) filter (where dynamic_count < min_workers)::integer as unfilled_slots,
      count(*) filter (where legacy_shift_exists)::integer as comparable_slots,
      count(*) filter (
        where legacy_shift_exists and (
          (legacy_user_id is null and dynamic_count=0)
          or (legacy_user_id is not null and exists (
            select 1 from public.dynamic_schedule_shadow_assignments assignment_item
            where assignment_item.draft_id=draft_row.id
              and assignment_item.slot_id=slot_metric.slot_id
              and assignment_item.user_id=slot_metric.legacy_user_id
          ))
        )
      )::integer as matching_slots
    from slot_metric
  )
  select jsonb_build_object(
    'totalSlots', metric_calc.total_slots,
    'coveredRequiredSlots', metric_calc.covered_required_slots,
    'unfilledSlots', metric_calc.unfilled_slots,
    'comparableSlots', metric_calc.comparable_slots,
    'matchingSlots', metric_calc.matching_slots,
    'differentSlots', greatest(metric_calc.comparable_slots-metric_calc.matching_slots,0),
    'matchPercent', case when metric_calc.comparable_slots>0 then round(metric_calc.matching_slots::numeric*100/metric_calc.comparable_slots,1) else null end,
    'preferredAssignments', (select count(*)::integer
      from public.dynamic_schedule_shadow_assignments assignment_item
      join public.dynamic_availability_submissions submission_item
        on submission_item.period_id=draft_row.availability_period_id and submission_item.user_id=assignment_item.user_id
      join public.dynamic_availability_entries entry_item
        on entry_item.submission_id=submission_item.id and entry_item.slot_id=assignment_item.slot_id
      where assignment_item.draft_id=draft_row.id and entry_item.availability_status='preferred'),
    'avoidAssignments', (select count(*)::integer
      from public.dynamic_schedule_shadow_assignments assignment_item
      join public.dynamic_availability_submissions submission_item
        on submission_item.period_id=draft_row.availability_period_id and submission_item.user_id=assignment_item.user_id
      join public.dynamic_availability_entries entry_item
        on entry_item.submission_id=submission_item.id and entry_item.slot_id=assignment_item.slot_id
      where assignment_item.draft_id=draft_row.id and entry_item.availability_status='avoid'),
    'underMinimumWorkers', (select count(*)::integer from public.dynamic_schedule_shadow_targets target_item
      where target_item.draft_id=draft_row.id and target_item.requested_min is not null and target_item.assigned_count<target_item.requested_min),
    'aboveTargetWorkers', (select count(*)::integer from public.dynamic_schedule_shadow_targets target_item
      where target_item.draft_id=draft_row.id and target_item.requested_target is not null and target_item.assigned_count>target_item.requested_target)
  )
  into metrics_row
  from metric_calc;

  return jsonb_build_object(
    'draftId', draft_row.id,
    'mode', 'shadow',
    'jobTypeId', draft_row.job_type_id,
    'jobTypeName', job_row.name,
    'year', draft_row.year,
    'month', draft_row.month,
    'algorithm', draft_row.metrics->>'algorithm',
    'legacySupported', legacy_supported,
    'legacyAvailable', legacy_period_id is not null,
    'legacyNote', case
      when not legacy_supported then 'לסוג התפקיד הזה עדיין אין מערכת Legacy מקבילה להשוואה אוטומטית.'
      when legacy_period_id is null then 'לא נמצא לוח קיים לחודש שנבחר, ולכן מוצגים מדדי איכות Dynamic בלבד.'
      else null
    end,
    'metrics', metrics_row,
    'workers', worker_rows,
    'slots', slot_rows
  );
end;
$$;


ALTER FUNCTION "public"."get_dynamic_schedule_shadow_validation"("requested_draft_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_dynamic_scheduling_admin"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  current_user_id uuid := auth.uid();
begin
  if current_user_id is null then raise exception 'not authenticated'; end if;
  if not exists(select 1 from public.profiles p where p.id=current_user_id and p.is_active=true) then raise exception 'user not active'; end if;
  if not exists(select 1 from public.user_permissions up where up.user_id=current_user_id and up.permission_key in ('users.view','users.manage')) then raise exception 'not allowed'; end if;

  return jsonb_build_object(
    'featureEnabled',coalesce((select enabled from public.scheduling_feature_flags where key='dynamic_job_types'),false),
    'featureMode',coalesce((select config->>'mode' from public.scheduling_feature_flags where key='dynamic_job_types'),'shadow'),
    'ruleRegistry',coalesce((select jsonb_agg(jsonb_build_object('key',r.rule_key,'name',r.name,'description',r.description,'category',r.category,'supportedSeverities',r.supported_severities,'parameterSchema',r.parameter_schema) order by r.category,r.name) from public.scheduling_rule_registry r where r.is_active),'[]'::jsonb),
    'scheduleGroups',coalesce((
      select jsonb_agg(jsonb_build_object(
        'id',sg.id,'code',sg.code,'name',sg.name,'description',sg.description,'isActive',sg.is_active,'legacyKind',sg.legacy_kind,'config',sg.config,
        'versionCount',(select count(*) from public.schedule_group_versions v where v.schedule_group_id=sg.id),
        'currentVersion',coalesce((select max(v.version_number) from public.schedule_group_versions v where v.schedule_group_id=sg.id),0),
        'shiftTemplates',coalesce((select jsonb_agg(jsonb_build_object(
          'id',st.id,'code',st.code,'name',st.name,'dayKind',st.day_kind,'startTime',st.start_time,'endTime',st.end_time,
          'minWorkers',st.required_workers,'targetWorkers',st.target_workers,'maxWorkers',st.max_workers,'sortOrder',st.sort_order,'isActive',st.is_active,'metadata',st.metadata,
          'paySegments',coalesce((select jsonb_agg(jsonb_build_object('id',ps.id,'startTime',ps.start_time,'endTime',ps.end_time,'multiplier',ps.multiplier,'label',ps.label,'sortOrder',ps.sort_order) order by ps.sort_order) from public.schedule_shift_pay_segments ps where ps.shift_template_id=st.id),'[]'::jsonb)
        ) order by st.day_kind,st.sort_order,st.start_time) from public.schedule_group_shift_templates st where st.schedule_group_id=sg.id),'[]'::jsonb),
        'dayRules',coalesce((select jsonb_agg(jsonb_build_object('dayKind',dr.day_kind,'behavior',dr.behavior,'inheritDayKind',dr.inherit_day_kind,'metadata',dr.metadata) order by dr.day_kind) from public.schedule_group_day_rules dr where dr.schedule_group_id=sg.id),'[]'::jsonb)
      ) order by sg.name) from public.schedule_groups sg
    ),'[]'::jsonb),
    'jobTypes',coalesce((
      select jsonb_agg(public.dynamic_job_type_live_snapshot(jt.id) order by jt.is_active desc,jt.name)
      from public.job_types jt
    ),'[]'::jsonb)
  );
end;
$$;


ALTER FUNCTION "public"."get_dynamic_scheduling_admin"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_dynamic_shift_exchange_requests"() RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select coalesce(jsonb_agg(jsonb_build_object(
    'id',r.id,'publicationId',r.publication_id,'jobTypeId',r.job_type_id,'jobTypeName',jt.name,
    'swapType',r.swap_type,'status',r.status,
    'requesterUserId',r.requester_user_id,'requesterName',requester.display_name,
    'counterpartyUserId',r.counterparty_user_id,'counterpartyName',counterparty.display_name,
    'requesterAssignmentId',r.requester_assignment_id,'requesterShiftDate',ra.shift_date,
    'requesterShiftName',ra.shift_name,'requesterStartTime',ra.start_time,'requesterEndTime',ra.end_time,
    'counterpartyAssignmentId',r.counterparty_assignment_id,'counterpartyShiftDate',ca.shift_date,
    'counterpartyShiftName',ca.shift_name,'counterpartyStartTime',ca.start_time,'counterpartyEndTime',ca.end_time,
    'rejectionReason',r.rejection_reason,'counterpartyRespondedAt',r.counterparty_responded_at,
    'managerReviewedAt',r.manager_reviewed_at,'managerUserId',r.manager_user_id,
    'createdAt',r.created_at,'updatedAt',r.updated_at
  ) order by r.created_at desc),'[]'::jsonb)
  from public.dynamic_shift_exchange_requests r
  join public.job_types jt on jt.id=r.job_type_id
  join public.profiles requester on requester.id=r.requester_user_id
  join public.profiles counterparty on counterparty.id=r.counterparty_user_id
  join public.dynamic_schedule_published_assignments ra on ra.id=r.requester_assignment_id
  left join public.dynamic_schedule_published_assignments ca on ca.id=r.counterparty_assignment_id
  where auth.uid() is not null and (
    r.requester_user_id=auth.uid() or r.counterparty_user_id=auth.uid()
    or public.current_user_has_permission('shift_swaps.approve')
  );
$$;


ALTER FUNCTION "public"."get_dynamic_shift_exchange_requests"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_dynamic_shifts_management_workspace"("requested_year" integer, "requested_month" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  actor uuid := auth.uid();
  actor_role text;
begin
  if actor is null then raise exception 'not authenticated'; end if;
  if requested_year not between 2020 and 2100 or requested_month not between 1 and 12 then
    raise exception 'invalid year or month';
  end if;

  select p.role::text into actor_role
  from public.profiles p
  where p.id = actor and p.is_active = true;
  if actor_role is null then raise exception 'user not active'; end if;

  if not exists (
    select 1
    from public.job_types jt
    where jt.is_active = true
      and jt.legacy_role is null
      and (
        public.has_dynamic_job_type_permission('availability.view_team', jt.id, actor)
        or public.has_dynamic_job_type_permission('availability.open_period', jt.id, actor)
        or public.has_dynamic_job_type_permission('availability.close_period', jt.id, actor)
        or public.has_dynamic_job_type_permission('availability.manage_submissions', jt.id, actor)
        or public.has_dynamic_job_type_permission('schedule.view_team', jt.id, actor)
        or public.has_dynamic_job_type_permission('schedule.create_draft', jt.id, actor)
        or public.has_dynamic_job_type_permission('schedule.edit_draft', jt.id, actor)
        or public.has_dynamic_job_type_permission('schedule.publish', jt.id, actor)
        or public.has_dynamic_job_type_permission('schedule.edit_published', jt.id, actor)
        or public.has_dynamic_job_type_permission('rotation.generate', jt.id, actor)
      )
  ) then
    raise exception 'not allowed';
  end if;

  return jsonb_build_object(
    'year', requested_year,
    'month', requested_month,
    'generatedAt', now(),
    'roles', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'jobType', public.dynamic_job_type_live_snapshot(jt.id),
          'isExplicitManager', exists (
            select 1 from public.job_type_managers jm
            where jm.user_id = actor and jm.job_type_id = jt.id
          ),
          'accessSource', case
            when actor_role = 'admin' then 'system_admin'
            else 'job_type_manager'
          end,
          'workflow', jsonb_build_object(
            'jobTypeId', jt.id,
            'jobTypeName', jt.name,
            'year', requested_year,
            'month', requested_month,
            'memberCount', (
              select count(*)::integer
              from public.job_type_memberships m
              join public.profiles p on p.id = m.user_id and p.is_active = true
              where m.job_type_id = jt.id
            ),
            'availabilityEnabled', coalesce((jt.availability_config->>'enabled')::boolean, false),
            'schedulingStrategy', coalesce(jt.scheduling_strategy, jt.scheduling_config->>'schedulingStrategy', 'availability_optimizer'),
            'period', (
              select jsonb_build_object(
                'id', ap.id,
                'status', ap.status,
                'title', ap.title,
                'submissionDeadline', ap.submission_deadline,
                'slotCount', (select count(*)::integer from public.dynamic_availability_slots s where s.period_id = ap.id),
                'submissionCount', (select count(*)::integer from public.dynamic_availability_submissions sub where sub.period_id = ap.id),
                'submittedCount', (select count(*)::integer from public.dynamic_availability_submissions sub where sub.period_id = ap.id and sub.status = 'submitted')
              )
              from public.dynamic_availability_periods ap
              where ap.job_type_id = jt.id and ap.year = requested_year and ap.month = requested_month
              limit 1
            ),
            'draft', (
              select jsonb_build_object('id', d.id, 'status', d.status, 'metrics', d.metrics, 'createdAt', d.created_at, 'updatedAt', d.updated_at)
              from public.dynamic_schedule_shadow_drafts d
              where d.job_type_id = jt.id and d.year = requested_year and d.month = requested_month
              order by d.created_at desc limit 1
            ),
            'publication', (
              select jsonb_build_object(
                'id', pub.id,
                'status', pub.status,
                'publishedAt', pub.published_at,
                'assignmentCount', (select count(*)::integer from public.dynamic_schedule_published_assignments a where a.publication_id = pub.id)
              )
              from public.dynamic_schedule_publications pub
              where pub.job_type_id = jt.id and pub.year = requested_year and pub.month = requested_month
              limit 1
            )
          )
        ) order by jt.name
      )
      from public.job_types jt
      where jt.is_active = true
        and jt.legacy_role is null
        and (
          public.has_dynamic_job_type_permission('availability.view_team', jt.id, actor)
          or public.has_dynamic_job_type_permission('availability.open_period', jt.id, actor)
          or public.has_dynamic_job_type_permission('availability.close_period', jt.id, actor)
          or public.has_dynamic_job_type_permission('availability.manage_submissions', jt.id, actor)
          or public.has_dynamic_job_type_permission('schedule.view_team', jt.id, actor)
          or public.has_dynamic_job_type_permission('schedule.create_draft', jt.id, actor)
          or public.has_dynamic_job_type_permission('schedule.edit_draft', jt.id, actor)
          or public.has_dynamic_job_type_permission('schedule.publish', jt.id, actor)
          or public.has_dynamic_job_type_permission('schedule.edit_published', jt.id, actor)
          or public.has_dynamic_job_type_permission('rotation.generate', jt.id, actor)
        )
    ), '[]'::jsonb)
  );
end;
$$;


ALTER FUNCTION "public"."get_dynamic_shifts_management_workspace"("requested_year" integer, "requested_month" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_dynamic_statistics_job_types"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare uid uuid:=auth.uid();
begin
 if uid is null then raise exception 'not authenticated'; end if;
 if not exists(select 1 from public.user_permissions up where up.user_id=uid and up.permission_key in('statistics.view','users.manage')) then raise exception 'not allowed'; end if;
 return coalesce((select jsonb_agg(jsonb_build_object('jobTypeId',jt.id,'name',jt.name,'code',jt.code,'isActive',jt.is_active,'payModel',jt.pay_model,'workMode',coalesce(nullif(jt.scheduling_config#>>'{shiftPattern,workMode}',''),nullif(jt.scheduling_config->>'workMode','')),'availabilityEnabled',coalesce((jt.availability_config->>'enabled')::boolean,false),'attendanceEnabled',coalesce((jt.scheduling_config#>>'{attendance,enabled}')::boolean,false),'memberCount',(select count(*) from public.job_type_memberships m join public.profiles p on p.id=m.user_id where m.job_type_id=jt.id and p.is_active=true),'payrollEnabled',coalesce(jt.pay_model,'none')<>'none','dataPeriodCount',(select count(*) from(select p.year,p.month from public.dynamic_schedule_publications p where p.job_type_id=jt.id union select hp.year,hp.month from public.dynamic_historical_periods hp where hp.job_type_id=jt.id)q)) order by jt.name) from public.job_types jt where jt.is_active=true and coalesce((jt.statistics_config->>'enabled')::boolean,false)=true),'[]'::jsonb);
end; $$;


ALTER FUNCTION "public"."get_dynamic_statistics_job_types"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_dynamic_user_assignment_editor"("target_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare actor uuid := auth.uid();
begin
  if actor is null then raise exception 'not authenticated'; end if;
  if not exists (
    select 1 from public.user_permissions up
    where up.user_id = actor and up.permission_key in ('users.view','users.manage')
  ) then raise exception 'not allowed'; end if;
  if not exists (select 1 from public.profiles p where p.id = target_user_id) then
    raise exception 'user not found';
  end if;

  return jsonb_build_object(
    'userId', target_user_id,
    'assignments', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'jobTypeId', jt.id,
          'jobTypeName', jt.name,
          'jobTypeDescription', jt.description,
          'jobTypeEmploymentScope', jt.employment_scope,
          'isMember', (m.user_id is not null),
          'isManager', (jm.user_id is not null),
          'employmentScope', m.metadata->>'employmentScope',
          'partTimeDefinition', coalesce(m.metadata->'partTimeDefinition', '{}'::jsonb)
        ) order by jt.name
      )
      from public.job_types jt
      left join public.job_type_memberships m
        on m.job_type_id = jt.id and m.user_id = target_user_id
      left join public.job_type_managers jm
        on jm.job_type_id = jt.id and jm.user_id = target_user_id
      where jt.legacy_role is null
        and (jt.is_active = true or m.user_id is not null or jm.user_id is not null)
    ), '[]'::jsonb)
  );
end;
$$;


ALTER FUNCTION "public"."get_dynamic_user_assignment_editor"("target_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_inherited_dynamic_job_type_permission"("requested_permission_key" "text", "requested_job_type_id" "uuid", "requested_user_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select coalesce(bool_or(
    s.enabled = true and (
      (dm.audience = 'member' and exists (
        select 1 from public.job_type_memberships m
        where m.user_id = requested_user_id and m.job_type_id = requested_job_type_id
      ))
      or
      (dm.audience = 'manager' and (
        exists (
          select 1 from public.profiles p
          where p.id = requested_user_id and p.role = 'admin'
        )
        or exists (
          select 1 from public.job_type_managers jm
          where jm.user_id = requested_user_id and jm.job_type_id = requested_job_type_id
        )
      ))
    )
  ), false)
  from public.dynamic_permission_manifest dm
  join public.job_type_permission_settings s
    on s.job_type_id = requested_job_type_id
   and s.permission_key = dm.permission_key
   and s.audience = dm.audience
  where dm.permission_key = requested_permission_key
    and dm.feature_key = any(public.get_dynamic_job_type_active_features(requested_job_type_id));
$$;


ALTER FUNCTION "public"."get_inherited_dynamic_job_type_permission"("requested_permission_key" "text", "requested_job_type_id" "uuid", "requested_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_legacy_freeze_readiness"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_user uuid := auth.uid();
  v_dynamic_first boolean := false;
  v_missing_count integer := 0;
  v_missing_users jsonb := '[]'::jsonb;
begin
  if v_user is null then raise exception 'not authenticated'; end if;
  if not exists (
    select 1 from public.user_permissions up
    where up.user_id = v_user and up.permission_key = 'users.manage'
  ) then raise exception 'not allowed'; end if;

  select coalesce(dynamic_first_enabled, false)
    into v_dynamic_first
  from public.dynamic_cutover_settings
  where singleton = true;

  select count(*)::integer
    into v_missing_count
  from public.profiles p
  where p.is_active = true
    and p.role::text in ('dispatcher', 'on_call', 'morning_driver')
    and not exists (
      select 1
      from public.job_type_memberships m
      join public.job_types jt
        on jt.id = m.job_type_id
       and jt.is_active = true
       and jt.legacy_role is null
      where m.user_id = p.id
    );

  select coalesce(jsonb_agg(
    jsonb_build_object(
      'userId', q.id,
      'displayName', q.display_name,
      'legacyRole', q.role_text
    ) order by q.display_name
  ), '[]'::jsonb)
  into v_missing_users
  from (
    select p.id, p.display_name, p.role::text as role_text
    from public.profiles p
    where p.is_active = true
      and p.role::text in ('dispatcher', 'on_call', 'morning_driver')
      and not exists (
        select 1
        from public.job_type_memberships m
        join public.job_types jt
          on jt.id = m.job_type_id
         and jt.is_active = true
         and jt.legacy_role is null
        where m.user_id = p.id
      )
    order by p.display_name
    limit 25
  ) q;

  return jsonb_build_object(
    'ready', v_dynamic_first and v_missing_count = 0,
    'dynamicFirstEnabled', v_dynamic_first,
    'missingLegacyMemberships', v_missing_count,
    'missingUsers', v_missing_users
  );
end;
$$;


ALTER FUNCTION "public"."get_legacy_freeze_readiness"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_morning_driver_archive_summary"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  current_user_id uuid;
  current_permissions text[];
  result_json jsonb;
begin
  current_user_id :=
    auth.uid();

  if current_user_id is null then
    raise exception
      'not authenticated';
  end if;

  if not exists (
    select 1
    from public.profiles
    where id =
      current_user_id
      and is_active = true
  ) then
    raise exception
      'user not active';
  end if;

  current_permissions :=
    coalesce(
      public.get_my_permissions(),
      array[]::text[]
    );

  if not (
    'archive.view' =
      any(current_permissions)
  ) then
    raise exception
      'not allowed';
  end if;

  select
    coalesce(
      jsonb_agg(
        jsonb_build_object(
          'year',
            period.year,

          'month',
            period.month,

          'periodId',
            period.id,

          'status',
            period.status,

          'assignmentCount',
            coalesce(
              stats.assignment_count,
              0
            ),

          'driverCount',
            coalesce(
              stats.driver_count,
              0
            ),

          /*
           * בטבלת morning_driver_schedule_periods
           * אין archived_at.
           * נשאיר null במקום להמציא תאריך ארכוב.
           */
          'archivedAt',
            null,

          'hasSchedule',
            true
        )
        order by
          period.year desc,
          period.month desc
      ),
      '[]'::jsonb
    )

  into result_json

  from public.morning_driver_schedule_periods
    period

  left join lateral (
    select
      count(*) filter (
        where
          assignment.assigned_user_id
            is not null
      )::integer
        as assignment_count,

      count(
        distinct
        assignment.assigned_user_id
      ) filter (
        where
          assignment.assigned_user_id
            is not null
      )::integer
        as driver_count

    from public.morning_driver_schedule_assignments
      assignment

    where
      assignment.schedule_period_id =
        period.id
  ) stats
    on true

  where
    period.status =
      'archived';

  return result_json;
end;
$$;


ALTER FUNCTION "public"."get_morning_driver_archive_summary"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_morning_driver_availability_management"("requested_period_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  current_user_id uuid;
  current_permissions text[];

  target_period
    public.morning_driver_availability_periods%rowtype;

  drivers_json jsonb;
  submissions_json jsonb;
  shifts_json jsonb;
  entries_json jsonb;

  total_drivers integer := 0;
  submitted_drivers integer := 0;
  draft_drivers integer := 0;
  reopened_drivers integer := 0;
  not_started_drivers integer := 0;
begin
  current_user_id := auth.uid();

  if current_user_id is null then
    raise exception 'not authenticated';
  end if;

  current_permissions :=
    coalesce(
      public.get_my_permissions(),
      array[]::text[]
    );

  if not (
    'morning_driver_availability.manage'
      = any(current_permissions)
  ) then
    raise exception 'not allowed';
  end if;

  if requested_period_id is null then
    raise exception 'period id is required';
  end if;

  select *
  into target_period
  from public.morning_driver_availability_periods period
  where period.id = requested_period_id;

  if not found then
    raise exception 'morning driver availability period not found';
  end if;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'id',
          profile.id,

        'displayName',
          profile.display_name,

        'scheduleName',
          profile.schedule_name,

        'email',
          profile.email,

        'isActive',
          profile.is_active
      )
      order by
        coalesce(
          profile.schedule_name,
          profile.display_name
        )
    ),
    '[]'::jsonb
  )
  into drivers_json
  from public.profiles profile
  where profile.role =
      'morning_driver'::public.user_role
    and profile.is_active = true;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'id',
          submission.id,

        'periodId',
          submission.period_id,

        'userId',
          submission.user_id,

        'status',
          submission.status,

        'submittedAt',
          submission.submitted_at,

        'lastSavedAt',
          submission.last_saved_at,

        'createdAt',
          submission.created_at,

        'updatedAt',
          submission.updated_at,

        'availableCount',
          (
            select count(*)
            from public.morning_driver_availability_entries entry
            where entry.period_id = target_period.id
              and entry.user_id = submission.user_id
              and entry.availability_status = 'available'
          ),

        'unavailableCount',
          (
            select count(*)
            from public.morning_driver_availability_entries entry
            where entry.period_id = target_period.id
              and entry.user_id = submission.user_id
              and entry.availability_status = 'unavailable'
          ),

        'unmarkedCount',
          (
            select count(*)
            from public.morning_driver_availability_shifts shift_item
            left join public.morning_driver_availability_entries entry
              on entry.shift_id = shift_item.id
             and entry.user_id = submission.user_id
            where shift_item.period_id = target_period.id
              and entry.id is null
          )
      )
      order by submission.created_at
    ),
    '[]'::jsonb
  )
  into submissions_json
  from public.morning_driver_availability_submissions submission
  where submission.period_id = target_period.id;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'id',
          shift_item.id,

        'periodId',
          shift_item.period_id,

        'shiftDate',
          shift_item.shift_date,

        'weekdayNumber',
          shift_item.weekday_number,

        'weekdayName',
          shift_item.weekday_name,

        'shiftType',
          shift_item.shift_type,

        'startTime',
          shift_item.start_time,

        'endTime',
          shift_item.end_time,

        'minimumWorkers',
          1,

        'recommendedWorkers',
          shift_item.required_workers,

        'sortOrder',
          shift_item.sort_order,

        'holidayName',
          holiday_row.holiday_name,

        'holidayScheduleType',
          holiday_row.schedule_type
      )
      order by
        shift_item.shift_date,
        shift_item.sort_order
    ),
    '[]'::jsonb
  )
  into shifts_json
  from public.morning_driver_availability_shifts shift_item
  left join lateral (
    select
      string_agg(holiday.name, ' / ' order by holiday.name) as holiday_name,
      case
        when bool_or(holiday.schedule_type::text = 'holiday_full') then 'holiday_full'
        when bool_or(holiday.schedule_type::text = 'holiday_end') then 'holiday_end'
        when bool_or(holiday.schedule_type::text = 'holiday_eve') then 'holiday_eve'
        else max(holiday.schedule_type::text)
      end as schedule_type
    from public.holidays holiday
    where holiday.holiday_date = shift_item.shift_date
  ) holiday_row on true
  where shift_item.period_id = target_period.id
    and coalesce(holiday_row.schedule_type, '') not in ('holiday_full', 'holiday_end');

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'id',
          entry.id,

        'periodId',
          entry.period_id,

        'shiftId',
          entry.shift_id,

        'userId',
          entry.user_id,

        'availabilityStatus',
          entry.availability_status,

        'note',
          entry.note,

        'createdAt',
          entry.created_at,

        'updatedAt',
          entry.updated_at
      )
      order by entry.created_at
    ),
    '[]'::jsonb
  )
  into entries_json
  from public.morning_driver_availability_entries entry
  where entry.period_id = target_period.id;

  select count(*)
  into total_drivers
  from public.profiles profile
  where profile.role =
      'morning_driver'::public.user_role
    and profile.is_active = true;

  select count(*)
  into submitted_drivers
  from public.morning_driver_availability_submissions submission
  where submission.period_id = target_period.id
    and submission.status = 'submitted';

  select count(*)
  into draft_drivers
  from public.morning_driver_availability_submissions submission
  where submission.period_id = target_period.id
    and submission.status = 'draft';

  select count(*)
  into reopened_drivers
  from public.morning_driver_availability_submissions submission
  where submission.period_id = target_period.id
    and submission.status = 'reopened';

  not_started_drivers :=
    greatest(
      total_drivers
      - submitted_drivers
      - draft_drivers
      - reopened_drivers,
      0
    );

  return jsonb_build_object(
    'period',
      jsonb_build_object(
        'id',
          target_period.id,

        'year',
          target_period.year,

        'month',
          target_period.month,

        'status',
          target_period.status,

        'title',
          target_period.title,

        'instructions',
          target_period.instructions,

        'submissionDeadline',
          target_period.submission_deadline,

        'openedAt',
          target_period.opened_at,

        'closedAt',
          target_period.closed_at,

        'createdAt',
          target_period.created_at
      ),

    'drivers',
      drivers_json,

    'submissions',
      submissions_json,

    'shifts',
      shifts_json,

    'entries',
      entries_json,

    'statistics',
      jsonb_build_object(
        'totalDrivers',
          total_drivers,

        'submittedDrivers',
          submitted_drivers,

        'draftDrivers',
          draft_drivers,

        'reopenedDrivers',
          reopened_drivers,

        'notStartedDrivers',
          not_started_drivers
      )
  );
end;
$$;


ALTER FUNCTION "public"."get_morning_driver_availability_management"("requested_period_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_morning_driver_availability_periods"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  current_user_id uuid;
  current_permissions text[];
  periods_json jsonb;
begin
  current_user_id :=
    auth.uid();

  if current_user_id is null then
    raise exception
      'not authenticated';
  end if;

  current_permissions :=
    coalesce(
      public.get_my_permissions(),
      array[]::text[]
    );

  if not (
    'morning_driver_availability.view'
      = any(current_permissions)
    or
    'morning_driver_availability.manage'
      = any(current_permissions)
  ) then
    raise exception
      'not allowed';
  end if;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'id',
          period.id,

        'year',
          period.year,

        'month',
          period.month,

        'status',
          period.status,

        'title',
          period.title,

        'instructions',
          period.instructions,

        'submissionDeadline',
          period.submission_deadline,

        'openedAt',
          period.opened_at,

        'closedAt',
          period.closed_at,

        'createdAt',
          period.created_at,

        'shiftsCount',
          (
            select count(*)
            from public.morning_driver_availability_shifts shift_item
            where shift_item.period_id = period.id
          ),

        'submissionsCount',
          (
            select count(*)
            from public.morning_driver_availability_submissions submission
            where submission.period_id = period.id
          ),

        'submittedCount',
          (
            select count(*)
            from public.morning_driver_availability_submissions submission
            where submission.period_id = period.id
              and submission.status = 'submitted'
          )
      )
      order by
        period.year desc,
        period.month desc
    ),
    '[]'::jsonb
  )
  into periods_json
  from public.morning_driver_availability_periods period;

  return periods_json;
end;
$$;


ALTER FUNCTION "public"."get_morning_driver_availability_periods"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_morning_driver_schedule"("requested_schedule_period_id" "uuid" DEFAULT NULL::"uuid", "requested_year" integer DEFAULT NULL::integer, "requested_month" integer DEFAULT NULL::integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  current_user_id uuid;

  current_permissions text[];

  schedule_period
    public.morning_driver_schedule_periods%rowtype;

  can_view_team boolean;

  can_edit boolean;

  can_view_personal boolean;

  drivers_json jsonb;

  assignments_json jsonb;

  total_assignments integer := 0;

  assigned_assignments integer := 0;

  minimum_unfilled integer := 0;

  recommendation_unfilled integer := 0;

  intentionally_unassigned_minimum integer := 0;
begin
  current_user_id :=
    auth.uid();

  if current_user_id is null then
    raise exception
      'not authenticated';
  end if;

  current_permissions :=
    coalesce(
      public.get_my_permissions(),
      array[]::text[]
    );

  can_view_personal :=
    'morning_driver_schedule.view'
      = any(current_permissions);

  can_view_team :=
    'morning_driver_schedule.view_team'
      = any(current_permissions);

  can_edit :=
    'morning_driver_schedule.edit'
      = any(current_permissions)
    or
    'morning_driver_schedule.edit_any'
      = any(current_permissions);

  if not (
    can_view_personal
    or can_view_team
    or can_edit
  ) then
    raise exception
      'not allowed';
  end if;

  if requested_schedule_period_id
    is not null
  then
    select *
    into schedule_period
    from public.morning_driver_schedule_periods period
    where period.id =
      requested_schedule_period_id;

  elsif requested_year is not null
    and requested_month is not null
  then
    select *
    into schedule_period
    from public.morning_driver_schedule_periods period
    where period.year =
      requested_year
      and period.month =
        requested_month
    limit 1;

  else
    select *
    into schedule_period
    from public.morning_driver_schedule_periods period
    order by
      period.year desc,
      period.month desc
    limit 1;
  end if;

  if not found then
    return null;
  end if;

  select
    coalesce(
      jsonb_agg(
        jsonb_build_object(
          'id',
            profile.id,

          'displayName',
            profile.display_name,

          'scheduleName',
            profile.schedule_name,

          'email',
            profile.email,

          'isActive',
            profile.is_active
        )
        order by
          coalesce(
            profile.schedule_name,
            profile.display_name
          )
      ),
      '[]'::jsonb
    )
  into
    drivers_json
  from public.profiles profile
  where profile.role =
      'morning_driver'
        ::public.user_role
    and (
      profile.is_active = true
      or exists (
        select 1
        from public.morning_driver_schedule_assignments historical_assignment
        where historical_assignment.schedule_period_id = schedule_period.id
          and historical_assignment.assigned_user_id = profile.id
      )
    );

  select
    coalesce(
      jsonb_agg(
        jsonb_build_object(
          'id',
            assignment.id,

          'schedulePeriodId',
            assignment.schedule_period_id,

          'availabilityShiftId',
            shift_item.id,

          'shiftDate',
            shift_item.shift_date,

          'weekdayNumber',
            shift_item.weekday_number,

          'weekdayName',
            shift_item.weekday_name,

          'shiftType',
            shift_item.shift_type,

          'startTime',
            coalesce(assignment.scheduled_start_time, shift_item.start_time),

          'endTime',
            coalesce(assignment.scheduled_end_time, shift_item.end_time),

          /*
           * במבנה הקיים:
           * המינימום הוא תמיד עובד אחד.
           */
          'minimumWorkers',
            1,

          /*
           * required_workers משמש
           * ככמות העובדים המומלצת.
           *
           * בוקר רגיל:
           * 2.
           *
           * ערב או שישי:
           * 1.
           */
          'recommendedWorkers',
            coalesce(
              shift_item.required_workers,
              1
            ),

          'assignmentSlot',
            assignment.assignment_slot,

          'assignedUserId',
            assignment.assigned_user_id,

          'assignedUserName',
            coalesce(
              assigned_profile.schedule_name,
              assigned_profile.display_name
            ),

          'assignmentSource',
            assignment.assignment_source,

          'isLocked',
            assignment.is_locked,

          'isIntentionallyUnassigned',
            coalesce(assignment.is_intentionally_unassigned, false),

          'notes',
            assignment.notes,

          'updatedAt',
            assignment.updated_at
        )
        order by
          shift_item.shift_date,
          shift_item.sort_order,
          assignment.assignment_slot
      ),
      '[]'::jsonb
    )
  into
    assignments_json
  from public.morning_driver_schedule_assignments assignment

  join public.morning_driver_availability_shifts shift_item
    on shift_item.id =
      assignment.availability_shift_id

  left join public.profiles assigned_profile
    on assigned_profile.id =
      assignment.assigned_user_id

  where assignment.schedule_period_id =
      schedule_period.id

    and (
      can_view_team
      or can_edit
      or assignment.assigned_user_id =
        current_user_id
    );

  select
    count(*)
  into
    total_assignments
  from public.morning_driver_schedule_assignments assignment
  where assignment.schedule_period_id =
    schedule_period.id;

  select
    count(*)
  into
    assigned_assignments
  from public.morning_driver_schedule_assignments assignment
  where assignment.schedule_period_id =
      schedule_period.id
    and assignment.assigned_user_id
      is not null;

  select
    count(*)
  into
    minimum_unfilled
  from public.morning_driver_schedule_assignments assignment
  where assignment.schedule_period_id =
      schedule_period.id
    and assignment.assignment_slot = 1
    and assignment.assigned_user_id
      is null
    and coalesce(assignment.is_intentionally_unassigned, false) = false;

  select
    count(*)
  into
    recommendation_unfilled
  from public.morning_driver_schedule_assignments assignment
  where assignment.schedule_period_id =
      schedule_period.id
    and assignment.assignment_slot > 1
    and assignment.assigned_user_id
      is null;

  select
    count(*)
  into
    intentionally_unassigned_minimum
  from public.morning_driver_schedule_assignments assignment
  where assignment.schedule_period_id =
      schedule_period.id
    and assignment.assignment_slot = 1
    and assignment.assigned_user_id is null
    and coalesce(assignment.is_intentionally_unassigned, false) = true;

  return jsonb_build_object(
    'period',
      jsonb_build_object(
        'id',
          schedule_period.id,

        'year',
          schedule_period.year,

        'month',
          schedule_period.month,

        'status',
          schedule_period.status,

        'availabilityPeriodId',
          schedule_period.availability_period_id,

        'title',
          schedule_period.title,

        'publishedAt',
          schedule_period.published_at,

        'createdAt',
          schedule_period.created_at,

        'updatedAt',
          schedule_period.updated_at
      ),

    'drivers',
      drivers_json,

    'assignments',
      assignments_json,

    'statistics',
      jsonb_build_object(
        'totalAssignments',
          total_assignments,

        'assignedAssignments',
          assigned_assignments,

        'unassignedAssignments',
          greatest(
            total_assignments -
            assigned_assignments,
            0
          ),

        'minimumUnfilled',
          minimum_unfilled,

        'recommendationUnfilled',
          recommendation_unfilled,

        'intentionallyUnassignedMinimum',
          intentionally_unassigned_minimum
      )
  );
end;
$$;


ALTER FUNCTION "public"."get_morning_driver_schedule"("requested_schedule_period_id" "uuid", "requested_year" integer, "requested_month" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_morning_driver_schedule_by_month"("requested_year" integer, "requested_month" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  current_user_id uuid;
  current_permissions text[];
  target_period public.morning_driver_schedule_periods%rowtype;
  assignments_json jsonb := '[]'::jsonb;
  drivers_json jsonb := '[]'::jsonb;
  total_assignments integer := 0;
  assigned_assignments integer := 0;
  unassigned_assignments integer := 0;
begin
  current_user_id := auth.uid();

  if current_user_id is null then
    raise exception 'not authenticated';
  end if;

  if not exists (
    select 1
    from public.profiles
    where id = current_user_id
      and is_active = true
  ) then
    raise exception 'user not active';
  end if;

  current_permissions :=
    coalesce(
      public.get_my_permissions(),
      array[]::text[]
    );

  if not (
    'morning_driver_schedule.view' =
      any(current_permissions)
    or
    'morning_driver_schedule.view_team' =
      any(current_permissions)
    or
    'morning_driver_schedule.edit' =
      any(current_permissions)
  ) then
    raise exception 'not allowed';
  end if;

  if requested_year < 2020
    or requested_year > 2100
    or requested_month < 1
    or requested_month > 12
  then
    raise exception 'invalid year or month';
  end if;

  select period.*
  into target_period
  from public.morning_driver_schedule_periods period
  where period.year = requested_year
    and period.month = requested_month
  order by period.created_at desc
  limit 1;

  if not found then
    return null;
  end if;

  select
    count(*)::integer,
    count(*) filter (
      where assignment.assigned_user_id is not null
    )::integer,
    count(*) filter (
      where assignment.assigned_user_id is null
    )::integer
  into
    total_assignments,
    assigned_assignments,
    unassigned_assignments
  from public.morning_driver_schedule_assignments assignment
  where assignment.schedule_period_id = target_period.id
    and (
      'morning_driver_schedule.view_team' =
        any(current_permissions)
      or
      'morning_driver_schedule.edit' =
        any(current_permissions)
      or
      assignment.assigned_user_id =
        current_user_id
    );

  select
    coalesce(
      jsonb_agg(
        jsonb_build_object(
          'id',
            assignment.id,
          'schedulePeriodId',
            assignment.schedule_period_id,
          'availabilityShiftId',
            assignment.availability_shift_id,
          'shiftDate',
            availability_shift.shift_date,
          'weekdayNumber',
            availability_shift.weekday_number,
          'weekdayName',
            availability_shift.weekday_name,
          'shiftType',
            availability_shift.shift_type,
          'startTime',
            availability_shift.start_time,
          'endTime',
            availability_shift.end_time,
          'minimumWorkers',
            availability_shift.minimum_workers,
          'recommendedWorkers',
            availability_shift.recommended_workers,
          'assignmentSlot',
            assignment.assignment_slot,
          'assignedUserId',
            assignment.assigned_user_id,
          'assignedUserName',
            coalesce(
              profile.schedule_name,
              profile.display_name
            ),
          'assignmentSource',
            assignment.assignment_source,
          'isLocked',
            assignment.is_locked,
          'notes',
            assignment.notes,
          'updatedAt',
            assignment.updated_at
        )
        order by
          availability_shift.shift_date,
          availability_shift.sort_order,
          assignment.assignment_slot
      ),
      '[]'::jsonb
    )
  into assignments_json
  from public.morning_driver_schedule_assignments assignment
  join public.morning_driver_availability_shifts availability_shift
    on availability_shift.id =
      assignment.availability_shift_id
  left join public.profiles profile
    on profile.id =
      assignment.assigned_user_id
  where assignment.schedule_period_id =
    target_period.id
    and (
      'morning_driver_schedule.view_team' =
        any(current_permissions)
      or
      'morning_driver_schedule.edit' =
        any(current_permissions)
      or
      assignment.assigned_user_id =
        current_user_id
    );

  select
    coalesce(
      jsonb_agg(
        jsonb_build_object(
          'id',
            profile.id,
          'displayName',
            profile.display_name,
          'scheduleName',
            profile.schedule_name,
          'email',
            profile.email
        )
        order by
          coalesce(
            profile.schedule_name,
            profile.display_name
          )
      ),
      '[]'::jsonb
    )
  into drivers_json
  from public.profiles profile
  where profile.role =
      'morning_driver'::public.user_role
    and profile.is_active = true;

  return jsonb_build_object(
    'period',
      jsonb_build_object(
        'id',
          target_period.id,
        'year',
          target_period.year,
        'month',
          target_period.month,
        'status',
          target_period.status,
        'availabilityPeriodId',
          target_period.availability_period_id,
        'title',
          target_period.title,
        'publishedAt',
          target_period.published_at,
        'createdAt',
          target_period.created_at,
        'updatedAt',
          target_period.updated_at
      ),
    'drivers',
      drivers_json,
    'assignments',
      assignments_json,
    'statistics',
      jsonb_build_object(
        'totalAssignments',
          total_assignments,
        'assignedAssignments',
          assigned_assignments,
        'unassignedAssignments',
          unassigned_assignments,
        'minimumUnfilled',
          0,
        'recommendationUnfilled',
          0
      )
  );
end;
$$;


ALTER FUNCTION "public"."get_morning_driver_schedule_by_month"("requested_year" integer, "requested_month" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_morning_driver_statistics"("requested_year" integer DEFAULT NULL::integer, "requested_month" integer DEFAULT NULL::integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  current_user_id uuid := auth.uid();
  current_permissions text[];
begin
  if current_user_id is null then
    raise exception 'not authenticated';
  end if;

  current_permissions := coalesce(public.get_my_permissions(), array[]::text[]);
  if not (
    'statistics.view' = any(current_permissions)
    or 'users.manage' = any(current_permissions)
  ) then
    raise exception 'not allowed';
  end if;

  return jsonb_build_object(
    'statistics', coalesce((
      select jsonb_agg(row_data order by (row_data->>'displayName'))
      from (
        select jsonb_build_object(
          'userId', profile.id,
          'displayName', profile.display_name,
          'scheduleName', profile.schedule_name,
          'totalShifts', count(shift_item.id)::integer,
          'morningShifts', count(shift_item.id) filter (where shift_item.start_time < time '12:00')::integer,
          'afternoonShifts', count(shift_item.id) filter (
            where shift_item.start_time >= time '12:00'
              and shift_item.start_time < time '18:00'
          )::integer,
          'eveningShifts', count(shift_item.id) filter (where shift_item.start_time >= time '18:00')::integer,
          'fridayShifts', count(shift_item.id) filter (where shift_item.weekday_number = 5)::integer,
          'weekendShifts', count(shift_item.id) filter (where shift_item.weekday_number in (5, 6))::integer
        ) as row_data
        from public.profiles profile
        left join public.morning_driver_schedule_assignments assignment
          on assignment.assigned_user_id = profile.id
        left join public.morning_driver_schedule_periods period
          on period.id = assignment.schedule_period_id
         and period.status in ('published', 'archived')
         and (requested_year is null or period.year = requested_year)
         and (requested_month is null or period.month = requested_month)
        left join public.morning_driver_availability_shifts shift_item
          on shift_item.id = assignment.availability_shift_id
         and period.id is not null
        where profile.role = 'morning_driver'::public.user_role
          and (
            profile.is_active = true
            or exists (
              select 1
              from public.morning_driver_schedule_assignments historical_assignment
              join public.morning_driver_schedule_periods historical_period
                on historical_period.id = historical_assignment.schedule_period_id
               and historical_period.status in ('published', 'archived')
              where historical_assignment.assigned_user_id = profile.id
                and (requested_year is null or historical_period.year = requested_year)
                and (requested_month is null or historical_period.month = requested_month)
            )
          )
        group by profile.id, profile.display_name, profile.schedule_name
      ) aggregated
    ), '[]'::jsonb),
    'monthlyBreakdown', coalesce((
      select jsonb_agg(
        row_data
        order by (row_data->>'year')::integer,
                 (row_data->>'month')::integer,
                 row_data->>'displayName'
      )
      from (
        select jsonb_build_object(
          'userId', profile.id,
          'displayName', profile.display_name,
          'scheduleName', profile.schedule_name,
          'year', period.year,
          'month', period.month,
          'totalShifts', count(assignment.id)::integer
        ) as row_data
        from public.morning_driver_schedule_assignments assignment
        join public.morning_driver_schedule_periods period
          on period.id = assignment.schedule_period_id
         and period.status in ('published', 'archived')
        join public.profiles profile
          on profile.id = assignment.assigned_user_id
        where (requested_year is null or period.year = requested_year)
          and (requested_month is null or period.month = requested_month)
        group by profile.id, profile.display_name, profile.schedule_name, period.year, period.month
      ) aggregated
    ), '[]'::jsonb),
    'generatedAt', now()
  );
end;
$$;


ALTER FUNCTION "public"."get_morning_driver_statistics"("requested_year" integer, "requested_month" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_my_attendance_workspace"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare uid uuid:=auth.uid(); now_local timestamp:=now() at time zone 'Asia/Jerusalem';
begin
 if uid is null then raise exception 'not authenticated'; end if;
 return jsonb_build_object('roles',coalesce((
   select jsonb_agg(jsonb_build_object(
     'jobTypeId',jt.id,'jobTypeName',jt.name,
     'canClock',public.has_dynamic_job_type_permission('attendance.clock',jt.id,uid),
     'config',jt.scheduling_config->'attendance',
     'openSession',case when os.id is null then null else jsonb_build_object('id',os.id,'clockInAt',os.clock_in_at,'clockInDistanceM',os.clock_in_distance_m,'clockInWithinRadius',os.clock_in_within_radius) end,
     'currentAssignment',case when ca.id is null then null else jsonb_build_object('id',ca.id,'shiftDate',ca.shift_date,'shiftName',ca.shift_name,'startTime',ca.start_time,'endTime',ca.end_time) end
   ) order by jt.name)
   from public.job_types jt
   join public.job_type_memberships m on m.job_type_id=jt.id and m.user_id=uid
   left join lateral(select s.* from public.attendance_sessions s where s.job_type_id=jt.id and s.user_id=uid and s.clock_out_at is null order by s.clock_in_at desc limit 1) os on true
   left join lateral(
     select a.* from public.dynamic_schedule_publications p join public.dynamic_schedule_published_assignments a on a.publication_id=p.id
     cross join lateral public.dynamic_resolve_assignment_local_interval(a.shift_date,a.start_time,a.end_time,coalesce(jt.scheduling_config#>>'{shiftPattern,workMode}','shifts'),jt.scheduling_config) iv
     where p.job_type_id=jt.id and p.status='published' and a.user_id=uid and now_local between iv.start_at-interval '4 hours' and iv.end_at+interval '4 hours'
     order by abs(extract(epoch from(now_local-iv.start_at))) limit 1
   ) ca on true
   where jt.is_active=true
     and coalesce((jt.scheduling_config#>>'{attendance,enabled}')::boolean,false)
 ),'[]'::jsonb));
end; $$;


ALTER FUNCTION "public"."get_my_attendance_workspace"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_my_daily_report_workspace"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare actor uuid:=auth.uid(); today_il date:=(now() at time zone 'Asia/Jerusalem')::date;
begin
 if actor is null then raise exception 'not authenticated'; end if;
 return jsonb_build_object('today',today_il,
 'customers',coalesce((select jsonb_agg(jsonb_build_object('id',c.id,'name',c.name) order by c.name) from public.daily_report_customers c where c.is_active=true),'[]'::jsonb),
 'roles',coalesce((select jsonb_agg(jsonb_build_object(
  'jobTypeId',jt.id,'jobTypeName',jt.name,
  'allowAddSubjects',coalesce((jt.scheduling_config#>>'{dailyReports,allowAddSubjects}')::boolean,true),
  'allowAddCustomers',coalesce((jt.scheduling_config#>>'{dailyReports,allowAddCustomers}')::boolean,true),
  'allowAttachments',coalesce((jt.scheduling_config#>>'{dailyReports,allowAttachments}')::boolean,true)
    and public.has_dynamic_job_type_permission('daily_reports.upload_attachment',jt.id,actor),
  'subjects',coalesce((select jsonb_agg(jsonb_build_object('id',s.id,'name',s.name) order by s.name) from public.daily_report_subjects s where s.job_type_id=jt.id and s.is_active=true),'[]'::jsonb),
  'todayReport',(select jsonb_build_object('id',r.id,'status',r.status,'submittedAt',r.submitted_at,'itemCount',(select count(*) from public.daily_report_items i where i.report_id=r.id)) from public.daily_reports r where r.job_type_id=jt.id and r.user_id=actor and r.report_date=today_il),
  'recentReports',coalesce((select jsonb_agg(x.obj order by x.report_date desc) from (
    select r.report_date,jsonb_build_object('id',r.id,'reportDate',r.report_date,'status',r.status,'submittedAt',r.submitted_at,'itemCount',(select count(*) from public.daily_report_items i where i.report_id=r.id)) obj
    from public.daily_reports r where r.job_type_id=jt.id and r.user_id=actor order by r.report_date desc limit 7
  ) x),'[]'::jsonb)
 ) order by m.is_primary desc,jt.name)
 from public.job_type_memberships m join public.job_types jt on jt.id=m.job_type_id
 where m.user_id=actor and jt.is_active=true and jt.legacy_role is null
 and (exists(select 1 from public.job_type_capabilities c where c.job_type_id=jt.id and c.capability_key='daily_reports' and c.enabled=true)
   or coalesce((jt.scheduling_config#>>'{dailyReports,enabled}')::boolean,false))
 and public.has_dynamic_job_type_permission('daily_reports.submit',jt.id,actor)),'[]'::jsonb));
end $$;


ALTER FUNCTION "public"."get_my_daily_report_workspace"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_my_dashboard"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  current_user_id uuid;
  current_user_role text;
  current_permissions text[];

  current_local_timestamp timestamp;
  current_local_date date;
  current_year integer;
  current_month integer;

  dispatcher_dashboard jsonb := null;
  driver_dashboard jsonb := null;
  manager_dashboard jsonb := null;
begin
  current_user_id :=
    auth.uid();

  if current_user_id is null then
    raise exception
      'not authenticated';
  end if;

  select
    profile_row.role::text
  into
    current_user_role
  from public.profiles profile_row
  where profile_row.id =
    current_user_id
    and profile_row.is_active = true;

  if not found then
    raise exception
      'user not active';
  end if;

  current_permissions :=
    coalesce(
      public.get_my_permissions(),
      array[]::text[]
    );

  if not (
    'dashboard.view' =
      any(current_permissions)
  ) then
    raise exception
      'not allowed';
  end if;

  current_local_timestamp :=
    now() at time zone
      'Asia/Jerusalem';

  current_local_date :=
    current_local_timestamp::date;

  current_year :=
    extract(
      year from current_local_date
    )::integer;

  current_month :=
    extract(
      month from current_local_date
    )::integer;

  if current_user_role in (
    'dispatcher',
    'admin',
    'manager'
  ) then
    with current_shift as (
      select
        schedule_shift.id,
        schedule_shift.shift_date,
        schedule_shift.starts_at,
        schedule_shift.ends_at,
        schedule_shift.shift_code,
        schedule_shift.schedule_type::text
          as schedule_type,
        schedule_shift.is_premium,
        schedule_shift.holiday_name,

        driver_day.assigned_user_id
          as driver_user_id,

        driver_profile.display_name
          as driver_display_name,

        driver_profile.schedule_name
          as driver_schedule_name

      from public.schedule_shifts
        schedule_shift

      join public.schedule_periods
        schedule_period
        on schedule_period.id =
          schedule_shift.period_id

      left join public.driver_schedule_periods
        driver_period
        on driver_period.year =
          extract(
            year from schedule_shift.shift_date
          )::integer
        and driver_period.month =
          extract(
            month from schedule_shift.shift_date
          )::integer
        and driver_period.status =
          'published'::public.driver_schedule_period_status

      left join public.driver_schedule_days
        driver_day
        on driver_day.period_id =
          driver_period.id
        and driver_day.duty_date =
          schedule_shift.shift_date

      left join public.profiles
        driver_profile
        on driver_profile.id =
          driver_day.assigned_user_id

      where schedule_period.status =
        'published'::public.schedule_period_status

        and schedule_shift.assigned_user_id =
          current_user_id

        and schedule_shift.starts_at <=
          now()

        and schedule_shift.ends_at >
          now()

      order by
        schedule_shift.starts_at

      limit 1
    ),

    next_shift as (
      select
        schedule_shift.id,
        schedule_shift.shift_date,
        schedule_shift.starts_at,
        schedule_shift.ends_at,
        schedule_shift.shift_code,
        schedule_shift.schedule_type::text
          as schedule_type,
        schedule_shift.is_premium,
        schedule_shift.holiday_name,

        driver_day.assigned_user_id
          as driver_user_id,

        driver_profile.display_name
          as driver_display_name,

        driver_profile.schedule_name
          as driver_schedule_name

      from public.schedule_shifts
        schedule_shift

      join public.schedule_periods
        schedule_period
        on schedule_period.id =
          schedule_shift.period_id

      left join public.driver_schedule_periods
        driver_period
        on driver_period.year =
          extract(
            year from schedule_shift.shift_date
          )::integer
        and driver_period.month =
          extract(
            month from schedule_shift.shift_date
          )::integer
        and driver_period.status =
          'published'::public.driver_schedule_period_status

      left join public.driver_schedule_days
        driver_day
        on driver_day.period_id =
          driver_period.id
        and driver_day.duty_date =
          schedule_shift.shift_date

      left join public.profiles
        driver_profile
        on driver_profile.id =
          driver_day.assigned_user_id

      where schedule_period.status =
        'published'::public.schedule_period_status

        and schedule_shift.assigned_user_id =
          current_user_id

        and schedule_shift.starts_at >
          now()

      order by
        schedule_shift.starts_at

      limit 1
    ),

    monthly_progress as (
      select
        count(schedule_shift.id)::integer
          as total_shifts,

        count(schedule_shift.id) filter (
          where schedule_shift.ends_at <=
            now()
        )::integer
          as completed_shifts

      from public.schedule_shifts
        schedule_shift

      join public.schedule_periods
        schedule_period
        on schedule_period.id =
          schedule_shift.period_id

      where schedule_period.year =
        current_year

        and schedule_period.month =
          current_month

        and schedule_period.status =
          'published'::public.schedule_period_status

        and schedule_shift.assigned_user_id =
          current_user_id
    )

    select
      jsonb_build_object(
        'currentShift',
          (
            select
              jsonb_build_object(
                'id',
                  current_shift.id,

                'shiftDate',
                  current_shift.shift_date,

                'startsAt',
                  current_shift.starts_at,

                'endsAt',
                  current_shift.ends_at,

                'shiftCode',
                  current_shift.shift_code,

                'scheduleType',
                  current_shift.schedule_type,

                'isPremium',
                  current_shift.is_premium,

                'holidayName',
                  current_shift.holiday_name,

                'driver',
                  case
                    when current_shift.driver_user_id
                      is null
                    then null
                    else jsonb_build_object(
                      'id',
                        current_shift.driver_user_id,

                      'displayName',
                        current_shift.driver_display_name,

                      'scheduleName',
                        current_shift.driver_schedule_name
                    )
                  end
              )
            from current_shift
          ),

        'nextShift',
          (
            select
              jsonb_build_object(
                'id',
                  next_shift.id,

                'shiftDate',
                  next_shift.shift_date,

                'startsAt',
                  next_shift.starts_at,

                'endsAt',
                  next_shift.ends_at,

                'shiftCode',
                  next_shift.shift_code,

                'scheduleType',
                  next_shift.schedule_type,

                'isPremium',
                  next_shift.is_premium,

                'holidayName',
                  next_shift.holiday_name,

                'driver',
                  case
                    when next_shift.driver_user_id
                      is null
                    then null
                    else jsonb_build_object(
                      'id',
                        next_shift.driver_user_id,

                      'displayName',
                        next_shift.driver_display_name,

                      'scheduleName',
                        next_shift.driver_schedule_name
                    )
                  end
              )
            from next_shift
          ),

        'monthlyProgress',
          (
            select
              jsonb_build_object(
                'year',
                  current_year,

                'month',
                  current_month,

                'completed',
                  monthly_progress.completed_shifts,

                'total',
                  monthly_progress.total_shifts,

                'percentage',
                  case
                    when monthly_progress.total_shifts = 0
                    then 0
                    else round(
                      (
                        monthly_progress.completed_shifts::numeric /
                        monthly_progress.total_shifts::numeric
                      ) * 100,
                      1
                    )
                  end
              )
            from monthly_progress
          )
      )
    into dispatcher_dashboard;
  end if;

  if current_user_role in (
    'on_call',
    'admin',
    'manager'
  ) then
    with current_duty as (
      select
        driver_day.id,
        driver_day.duty_date,
        driver_day.weekday_number,
        driver_day.weekday_name,
        driver_day.assigned_user_id,
        driver_day.notes

      from public.driver_schedule_days
        driver_day

      join public.driver_schedule_periods
        driver_period
        on driver_period.id =
          driver_day.period_id

      where driver_period.status =
        'published'::public.driver_schedule_period_status

        and driver_day.assigned_user_id =
          current_user_id

        and driver_day.duty_date =
          current_local_date

      limit 1
    ),

    next_duty as (
      select
        driver_day.id,
        driver_day.duty_date,
        driver_day.weekday_number,
        driver_day.weekday_name,
        driver_day.assigned_user_id,
        driver_day.notes

      from public.driver_schedule_days
        driver_day

      join public.driver_schedule_periods
        driver_period
        on driver_period.id =
          driver_day.period_id

      where driver_period.status =
        'published'::public.driver_schedule_period_status

        and driver_day.assigned_user_id =
          current_user_id

        and driver_day.duty_date >
          current_local_date

      order by
        driver_day.duty_date

      limit 1
    ),

    monthly_progress as (
      select
        count(driver_day.id)::integer
          as total_duties,

        count(driver_day.id) filter (
          where driver_day.duty_date <
            current_local_date
        )::integer
          as completed_duties

      from public.driver_schedule_days
        driver_day

      join public.driver_schedule_periods
        driver_period
        on driver_period.id =
          driver_day.period_id

      where driver_period.year =
        current_year

        and driver_period.month =
          current_month

        and driver_period.status =
          'published'::public.driver_schedule_period_status

        and driver_day.assigned_user_id =
          current_user_id
    )

    select
      jsonb_build_object(
        'currentDuty',
          (
            select
              jsonb_build_object(
                'id',
                  current_duty.id,

                'dutyDate',
                  current_duty.duty_date,

                'weekdayNumber',
                  current_duty.weekday_number,

                'weekdayName',
                  current_duty.weekday_name,

                'notes',
                  current_duty.notes,

                'dispatcherShifts',
                  coalesce(
                    (
                      select
                        jsonb_agg(
                          jsonb_build_object(
                            'id',
                              schedule_shift.id,

                            'startsAt',
                              schedule_shift.starts_at,

                            'endsAt',
                              schedule_shift.ends_at,

                            'displayName',
                              dispatcher_profile.display_name,

                            'scheduleName',
                              dispatcher_profile.schedule_name
                          )
                          order by
                            schedule_shift.starts_at
                        )

                      from public.schedule_shifts
                        schedule_shift

                      join public.schedule_periods
                        schedule_period
                        on schedule_period.id =
                          schedule_shift.period_id

                      left join public.profiles
                        dispatcher_profile
                        on dispatcher_profile.id =
                          schedule_shift.assigned_user_id

                      where schedule_period.status =
                        'published'::public.schedule_period_status

                        and schedule_shift.shift_date =
                          current_duty.duty_date
                    ),
                    '[]'::jsonb
                  )
              )
            from current_duty
          ),

        'nextDuty',
          (
            select
              jsonb_build_object(
                'id',
                  next_duty.id,

                'dutyDate',
                  next_duty.duty_date,

                'weekdayNumber',
                  next_duty.weekday_number,

                'weekdayName',
                  next_duty.weekday_name,

                'notes',
                  next_duty.notes,

                'dispatcherShifts',
                  coalesce(
                    (
                      select
                        jsonb_agg(
                          jsonb_build_object(
                            'id',
                              schedule_shift.id,

                            'startsAt',
                              schedule_shift.starts_at,

                            'endsAt',
                              schedule_shift.ends_at,

                            'displayName',
                              dispatcher_profile.display_name,

                            'scheduleName',
                              dispatcher_profile.schedule_name
                          )
                          order by
                            schedule_shift.starts_at
                        )

                      from public.schedule_shifts
                        schedule_shift

                      join public.schedule_periods
                        schedule_period
                        on schedule_period.id =
                          schedule_shift.period_id

                      left join public.profiles
                        dispatcher_profile
                        on dispatcher_profile.id =
                          schedule_shift.assigned_user_id

                      where schedule_period.status =
                        'published'::public.schedule_period_status

                        and schedule_shift.shift_date =
                          next_duty.duty_date
                    ),
                    '[]'::jsonb
                  )
              )
            from next_duty
          ),

        'monthlyProgress',
          (
            select
              jsonb_build_object(
                'year',
                  current_year,

                'month',
                  current_month,

                'completed',
                  monthly_progress.completed_duties,

                'total',
                  monthly_progress.total_duties,

                'percentage',
                  case
                    when monthly_progress.total_duties = 0
                    then 0
                    else round(
                      (
                        monthly_progress.completed_duties::numeric /
                        monthly_progress.total_duties::numeric
                      ) * 100,
                      1
                    )
                  end
              )
            from monthly_progress
          )
      )
    into driver_dashboard;
  end if;

  if current_user_role in (
    'admin',
    'manager'
  ) then
    with current_dispatcher_shift as (
      select
        schedule_shift.id,
        schedule_shift.starts_at,
        schedule_shift.ends_at,
        dispatcher_profile.id
          as user_id,
        dispatcher_profile.display_name,
        dispatcher_profile.schedule_name

      from public.schedule_shifts
        schedule_shift

      join public.schedule_periods
        schedule_period
        on schedule_period.id =
          schedule_shift.period_id

      left join public.profiles
        dispatcher_profile
        on dispatcher_profile.id =
          schedule_shift.assigned_user_id

      where schedule_period.status =
        'published'::public.schedule_period_status

        and schedule_shift.starts_at <=
          now()

        and schedule_shift.ends_at >
          now()

      order by
        schedule_shift.starts_at

      limit 1
    ),

    current_driver_duty as (
      select
        driver_day.id,
        driver_day.duty_date,
        driver_profile.id
          as user_id,
        driver_profile.display_name,
        driver_profile.schedule_name

      from public.driver_schedule_days
        driver_day

      join public.driver_schedule_periods
        driver_period
        on driver_period.id =
          driver_day.period_id

      left join public.profiles
        driver_profile
        on driver_profile.id =
          driver_day.assigned_user_id

      where driver_period.status =
        'published'::public.driver_schedule_period_status

        and driver_day.duty_date =
          current_local_date

      limit 1
    ),

    schedule_summary as (
      select
        count(schedule_shift.id)::integer
          as total_shifts,

        count(schedule_shift.id) filter (
          where schedule_shift.assigned_user_id
            is null
        )::integer
          as unassigned_shifts,

        count(schedule_shift.id) filter (
          where schedule_shift.ends_at <=
            now()
        )::integer
          as completed_shifts

      from public.schedule_shifts
        schedule_shift

      join public.schedule_periods
        schedule_period
        on schedule_period.id =
          schedule_shift.period_id

      where schedule_period.year =
        current_year

        and schedule_period.month =
          current_month

        and schedule_period.status =
          'published'::public.schedule_period_status
    ),

    driver_summary as (
      select
        count(driver_day.id)::integer
          as total_duties,

        count(driver_day.id) filter (
          where driver_day.assigned_user_id
            is null
        )::integer
          as unassigned_duties,

        count(driver_day.id) filter (
          where driver_day.duty_date <
            current_local_date
        )::integer
          as completed_duties

      from public.driver_schedule_days
        driver_day

      join public.driver_schedule_periods
        driver_period
        on driver_period.id =
          driver_day.period_id

      where driver_period.year =
        current_year

        and driver_period.month =
          current_month

        and driver_period.status =
          'published'::public.driver_schedule_period_status
    )

    select
      jsonb_build_object(
        'currentDispatcher',
          (
            select
              jsonb_build_object(
                'shiftId',
                  current_dispatcher_shift.id,

                'startsAt',
                  current_dispatcher_shift.starts_at,

                'endsAt',
                  current_dispatcher_shift.ends_at,

                'userId',
                  current_dispatcher_shift.user_id,

                'displayName',
                  current_dispatcher_shift.display_name,

                'scheduleName',
                  current_dispatcher_shift.schedule_name
              )
            from current_dispatcher_shift
          ),

        'currentDriver',
          (
            select
              jsonb_build_object(
                'dutyId',
                  current_driver_duty.id,

                'dutyDate',
                  current_driver_duty.duty_date,

                'userId',
                  current_driver_duty.user_id,

                'displayName',
                  current_driver_duty.display_name,

                'scheduleName',
                  current_driver_duty.schedule_name
              )
            from current_driver_duty
          ),

        'monthlySummary',
          jsonb_build_object(
            'year',
              current_year,

            'month',
              current_month,

            'dispatcherShifts',
              (
                select
                  jsonb_build_object(
                    'completed',
                      schedule_summary.completed_shifts,

                    'total',
                      schedule_summary.total_shifts,

                    'unassigned',
                      schedule_summary.unassigned_shifts,

                    'percentage',
                      case
                        when schedule_summary.total_shifts = 0
                        then 0
                        else round(
                          (
                            schedule_summary.completed_shifts::numeric /
                            schedule_summary.total_shifts::numeric
                          ) * 100,
                          1
                        )
                      end
                  )
                from schedule_summary
              ),

            'driverDuties',
              (
                select
                  jsonb_build_object(
                    'completed',
                      driver_summary.completed_duties,

                    'total',
                      driver_summary.total_duties,

                    'unassigned',
                      driver_summary.unassigned_duties,

                    'percentage',
                      case
                        when driver_summary.total_duties = 0
                        then 0
                        else round(
                          (
                            driver_summary.completed_duties::numeric /
                            driver_summary.total_duties::numeric
                          ) * 100,
                          1
                        )
                      end
                  )
                from driver_summary
              )
          )
      )
    into manager_dashboard;
  end if;

  return jsonb_build_object(
    'user',
      jsonb_build_object(
        'id',
          current_user_id,

        'role',
          current_user_role
      ),

    'dispatcher',
      dispatcher_dashboard,

    'driver',
      driver_dashboard,

    'manager',
      manager_dashboard,

    'generatedAt',
      now()
  );
end;
$$;


ALTER FUNCTION "public"."get_my_dashboard"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_my_dashboard_widget_settings"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_actor uuid:=auth.uid();
begin
  if not public.can_configure_manager_dashboard(v_actor) then
    raise exception 'not allowed';
  end if;

  return jsonb_build_object(
    'canConfigure', true,
    'jobTypes', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id',jt.id,
        'name',jt.name,
        'workMode',coalesce(
          mat.work_mode,
          jt.scheduling_config #>> '{shiftPattern,workMode}',
          'shifts'
        )
      ) order by jt.name)
      from public.job_types jt
      left join lateral (
        select m.work_mode
        from public.job_type_schedule_materializations m
        where m.job_type_id=jt.id
        order by m.effective_month desc
        limit 1
      ) mat on true
      where jt.is_active=true
        and coalesce(jt.scheduling_strategy,'availability_optimizer') <> 'none'
    ),'[]'::jsonb),
    'widgets',coalesce((
      select jsonb_agg(jsonb_build_object(
        'id',w.id,
        'widgetType',w.widget_type,
        'timeScope',w.time_scope,
        'jobTypeId',w.job_type_id,
        'sortOrder',w.sort_order,
        'enabled',w.enabled
      ) order by w.sort_order,w.created_at)
      from public.user_dashboard_widgets w
      where w.user_id=v_actor
    ),'[]'::jsonb)
  );
end;
$$;


ALTER FUNCTION "public"."get_my_dashboard_widget_settings"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_my_development_mode"() RETURNS TABLE("enabled" boolean, "enabled_at" timestamp with time zone, "expires_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if not exists (
    select 1
    from public.profiles p
    where p.id = auth.uid()
      and p.role = 'admin'
      and p.is_active = true
  ) then
    return query
    select false, null::timestamptz, null::timestamptz;
    return;
  end if;

  update public.admin_development_sessions as ads
  set enabled = false,
      updated_at = now()
  where ads.user_id = auth.uid()
    and ads.enabled = true
    and ads.expires_at is not null
    and ads.expires_at <= now();

  return query
  select coalesce(ads.enabled, false), ads.enabled_at, ads.expires_at
  from (select auth.uid() as user_id) as me
  left join public.admin_development_sessions as ads
    on ads.user_id = me.user_id;
end;
$$;


ALTER FUNCTION "public"."get_my_development_mode"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_my_driver_availability"("requested_period_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  current_user_id uuid;

  current_permissions text[];

  selected_period
    public.driver_availability_periods%rowtype;

  days_json jsonb :=
    '[]'::jsonb;

  entries_json jsonb :=
    '[]'::jsonb;

  submission_json jsonb :=
    null;
begin
  current_user_id :=
    auth.uid();

  if current_user_id is null then
    raise exception
      'not authenticated';
  end if;

  if not exists (
    select 1
    from public.profiles
    where id =
      current_user_id
      and is_active = true
  ) then
    raise exception
      'user not active';
  end if;

  current_permissions :=
    coalesce(
      public.get_my_permissions(),
      array[]::text[]
    );

  if not (
    'driver_availability.view' =
      any(current_permissions)
  ) then
    raise exception
      'not allowed';
  end if;

  if requested_period_id is not null then
    select *
    into selected_period
    from public.driver_availability_periods
    where id =
      requested_period_id
      and status in (
        'open',
        'closed'
      )
    limit 1;
  else
    select *
    into selected_period
    from public.driver_availability_periods
    where status =
      'open'
    order by
      year desc,
      month desc
    limit 1;
  end if;

  if not found then
    return jsonb_build_object(
      'period',
        null,

      'days',
        '[]'::jsonb,

      'entries',
        '[]'::jsonb,

      'submission',
        null
    );
  end if;

  select
    coalesce(
      jsonb_agg(
        jsonb_build_object(
          'id',
            day_row.id,

          'periodId',
            day_row.period_id,

          'availabilityDate',
            day_row.availability_date,

          'weekdayNumber',
            day_row.weekday_number,

          'weekdayName',
            day_row.weekday_name,

          'sortOrder',
            day_row.sort_order,

          'createdAt',
            day_row.created_at,

          'holidayName',
            (
              select string_agg(holiday.name, ' / ' order by holiday.name)
              from public.holidays holiday
              where holiday.holiday_date = day_row.availability_date
            ),

          'holidayScheduleType',
            (
              select holiday.schedule_type::text
              from public.holidays holiday
              where holiday.holiday_date = day_row.availability_date
              order by
                case holiday.schedule_type::text
                  when 'holiday_full' then 1
                  when 'holiday_eve' then 2
                  when 'holiday_end' then 3
                  when 'chol_hamoed' then 4
                  else 5
                end,
                holiday.name
              limit 1
            )
        )
        order by
          day_row.availability_date
      ),
      '[]'::jsonb
    )
  into days_json
  from public.driver_availability_days
    day_row
  where day_row.period_id =
    selected_period.id;

  select
    coalesce(
      jsonb_agg(
        jsonb_build_object(
          'id',
            entry.id,

          'periodId',
            entry.period_id,

          'dayId',
            entry.day_id,

          'userId',
            entry.user_id,

          'availabilityStatus',
            entry.availability_status,

          'note',
            entry.note,

          'createdAt',
            entry.created_at,

          'updatedAt',
            entry.updated_at
        )
        order by
          day_row.availability_date
      ),
      '[]'::jsonb
    )
  into entries_json
  from public.driver_availability_entries
    entry
  join public.driver_availability_days
    day_row
    on day_row.id =
      entry.day_id
  where entry.period_id =
    selected_period.id
    and entry.user_id =
      current_user_id;

  select
    jsonb_build_object(
      'id',
        submission.id,

      'periodId',
        submission.period_id,

      'userId',
        submission.user_id,

      'status',
        submission.status,

      'submittedAt',
        submission.submitted_at,

      'reopenedAt',
        submission.reopened_at,

      'lastSavedAt',
        submission.last_saved_at,

      'availableCount',
        submission.available_count,

      'unavailableCount',
        submission.unavailable_count,

      'createdAt',
        submission.created_at,

      'updatedAt',
        submission.updated_at
    )
  into submission_json
  from public.driver_availability_submissions
    submission
  where submission.period_id =
    selected_period.id
    and submission.user_id =
      current_user_id
  limit 1;

  return jsonb_build_object(
    'period',
      jsonb_build_object(
        'id',
          selected_period.id,

        'year',
          selected_period.year,

        'month',
          selected_period.month,

        'status',
          selected_period.status,

        'title',
          selected_period.title,

        'instructions',
          selected_period.instructions,

        'submissionDeadline',
          selected_period.submission_deadline,

        'openedAt',
          selected_period.opened_at,

        'closedAt',
          selected_period.closed_at,

        'createdBy',
          selected_period.created_by,

        'updatedBy',
          selected_period.updated_by,

        'createdAt',
          selected_period.created_at,

        'updatedAt',
          selected_period.updated_at
      ),

    'days',
      days_json,

    'entries',
      entries_json,

    'submission',
      submission_json
  );
end;
$$;


ALTER FUNCTION "public"."get_my_driver_availability"("requested_period_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_my_driver_availability"("requested_period_id" "uuid") IS 'Returns the selected or current open driver availability period, its days, the authenticated user availability entries, and submission status. Requires driver_availability.view.';



CREATE OR REPLACE FUNCTION "public"."get_my_dynamic_availability_periods"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  current_user_id uuid := auth.uid();
begin
  if current_user_id is null then raise exception 'not authenticated'; end if;

  return coalesce((
    select jsonb_agg(jsonb_build_object(
      'jobTypeId',jt.id,
      'jobTypeName',jt.name,
      'year',p.year,
      'month',p.month,
      'periodId',p.id,
      'periodStatus',p.status,
      'submissionDeadline',p.submission_deadline,
      'slotCount',(select count(*) from public.dynamic_availability_slots s where s.period_id=p.id),
      'submissionStatus',sub.status,
      'submittedAt',sub.submitted_at,
      'filledCount',(select count(*) from public.dynamic_availability_entries e where e.submission_id=sub.id)
    ) order by p.year desc,p.month desc,jt.name)
    from public.job_type_memberships m
    join public.job_types jt on jt.id=m.job_type_id and jt.is_active=true
    join public.dynamic_availability_periods p on p.job_type_id=jt.id
    left join public.dynamic_availability_submissions sub on sub.period_id=p.id and sub.user_id=current_user_id
    where m.user_id=current_user_id
      and coalesce((jt.availability_config->>'enabled')::boolean,true)=true
      and p.status in ('open','closed','archived')
      and make_date(p.year,p.month,1) >= (date_trunc('month',now() at time zone 'Asia/Jerusalem')::date - interval '2 months')::date
  ),'[]'::jsonb);
end;
$$;


ALTER FUNCTION "public"."get_my_dynamic_availability_periods"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_my_dynamic_availability_workspace"("requested_job_type_id" "uuid", "requested_year" integer, "requested_month" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  current_user_id uuid:=auth.uid();
  job public.job_types%rowtype;
  period public.dynamic_availability_periods%rowtype;
  sub public.dynamic_availability_submissions%rowtype;
  normalized_config jsonb;
  effective_availability_config jsonb;
begin
  if current_user_id is null then raise exception 'not authenticated'; end if;
  if not exists(
    select 1 from public.job_type_memberships m
    where m.user_id=current_user_id and m.job_type_id=requested_job_type_id
  ) then raise exception 'not a member of this job type'; end if;

  select * into job
  from public.job_types
  where id=requested_job_type_id and is_active=true;
  if job.id is null then raise exception 'job type not found'; end if;

  select * into period
  from public.dynamic_availability_periods
  where job_type_id=job.id and year=requested_year and month=requested_month;
  if period.id is null then raise exception 'dynamic period not found'; end if;
  if period.status not in ('open','closed','archived') then
    raise exception 'period is not available to employees';
  end if;

  -- Auto-heal periods that were created before this fix and therefore have
  -- no monthly slots yet. The helper never rebuilds a populated period.
  if not exists(
    select 1 from public.dynamic_availability_slots s where s.period_id=period.id
  ) then
    perform public.materialize_dynamic_availability_period_slots(period.id);
  end if;

  select * into sub
  from public.dynamic_availability_submissions
  where period_id=period.id and user_id=current_user_id;

  effective_availability_config:=coalesce(period.config_snapshot,job.availability_config,'{}'::jsonb);

  normalized_config:=jsonb_build_object(
    'enabled',coalesce((effective_availability_config->>'enabled')::boolean,true),
    'statuses',case
      when jsonb_typeof(effective_availability_config->'statuses')='array'
        and jsonb_array_length(effective_availability_config->'statuses')>0
      then effective_availability_config->'statuses'
      else '["available","unavailable"]'::jsonb
    end,
    'allowNotes',coalesce((effective_availability_config->>'allowNotes')::boolean,true),
    'monthlyCapacity',coalesce(
      effective_availability_config->'monthlyCapacity',
      '{"enabled":false,"minEnabled":false,"targetEnabled":false,"maxEnabled":false,"defaultMin":null,"defaultTarget":null,"defaultMax":null}'::jsonb
    ),
    'limits',coalesce(
      effective_availability_config->'limits',
      '{"maxNightsEnabled":false,"defaultMaxNights":null,"maxWeekendsEnabled":false,"defaultMaxWeekends":null,"maxHolidaysEnabled":false,"defaultMaxHolidays":null}'::jsonb
    )
  );

  return jsonb_build_object(
    'materialized',true,
    'mode','dynamic_role',
    'periodId',period.id,
    'jobTypeId',job.id,
    'jobTypeName',job.name,
    'availabilityConfig',normalized_config,
    'slots',coalesce((
      select jsonb_agg(jsonb_build_object(
        'id',s.id,
        'date',s.shift_date,
        'shiftCode',s.shift_code,
        'shiftName',s.shift_name,
        'startTime',s.start_time,
        'endTime',s.end_time,
        'holidayName',s.holiday_name,
        'sourceDayKind',s.source_day_kind,
        'effectiveDayKind',s.effective_day_kind,
        'minWorkers',s.min_workers,
        'targetWorkers',s.target_workers,
        'maxWorkers',s.max_workers
      ) order by s.shift_date,s.start_time,s.shift_code)
      from public.dynamic_availability_slots s
      where s.period_id=period.id
    ),'[]'::jsonb),
    'members',jsonb_build_array(jsonb_build_object(
      'userId',current_user_id,
      'displayName',(select display_name from public.profiles where id=current_user_id),
      'isActive',coalesce((select is_active from public.profiles where id=current_user_id),true),
      'submissionId',sub.id,
      'status',coalesce(sub.status,'draft'),
      'minimum',sub.min_shifts,
      'target',sub.target_shifts,
      'maximum',sub.max_shifts,
      'maxNights',sub.max_nights,
      'maxWeekends',sub.max_weekends,
      'maxHolidays',sub.max_holidays,
      'note',sub.note,
      'entries',coalesce((
        select jsonb_object_agg(
          e.slot_id::text,
          jsonb_build_object('status',e.availability_status,'note',e.note)
        )
        from public.dynamic_availability_entries e
        where e.submission_id=sub.id
      ),'{}'::jsonb)
    ))
  );
end;
$$;


ALTER FUNCTION "public"."get_my_dynamic_availability_workspace"("requested_job_type_id" "uuid", "requested_year" integer, "requested_month" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_my_dynamic_runtime_context"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  current_user_id uuid := auth.uid();
  current_month date := date_trunc('month', now() at time zone 'Asia/Jerusalem')::date;
  can_manage boolean := false;
  result jsonb;
begin
  if current_user_id is null then
    raise exception 'not authenticated';
  end if;

  can_manage :=
    public.current_user_has_permission('availability.manage')
    or public.current_user_has_permission('driver_availability.manage')
    or public.current_user_has_permission('morning_driver_availability.manage')
    or public.current_user_has_permission('users.manage');

  with memberships as (
    select
      m.job_type_id,
      m.is_primary,
      jt.name,
      jt.description,
      jt.availability_config,
      jt.scheduling_strategy,
      jt.scheduling_config,
      mat.work_mode as materialized_work_mode,
      mat.schedule_change_mode as materialized_change_mode
    from public.job_type_memberships m
    join public.job_types jt
      on jt.id = m.job_type_id
     and jt.is_active = true
     and jt.legacy_role is null
    left join public.job_type_schedule_materializations mat
      on mat.job_type_id = jt.id
     and mat.effective_month = current_month
    where m.user_id = current_user_id
  ),
  role_with_next as (
    select
      m.*,
      next_assignment.publication_id,
      next_assignment.assignment_id,
      next_assignment.assignment_year,
      next_assignment.assignment_month,
      next_assignment.shift_date,
      next_assignment.shift_code,
      next_assignment.display_shift_name,
      next_assignment.start_time,
      next_assignment.end_time,
      next_assignment.assignment_start_at,
      next_assignment.assignment_end_at
    from memberships m
    left join lateral (
      select
        p.id as publication_id,
        a.id as assignment_id,
        p.year as assignment_year,
        p.month as assignment_month,
        a.shift_date,
        a.shift_code,
        coalesce(nullif(tmpl.name,''), nullif(a.shift_name,a.shift_code), a.shift_name) as display_shift_name,
        a.start_time,
        a.end_time,
        assignment_bounds.start_at as assignment_start_at,
        assignment_bounds.end_at as assignment_end_at
      from public.dynamic_schedule_publications p
      join public.dynamic_schedule_published_assignments a
        on a.publication_id = p.id
      cross join lateral public.dynamic_resolve_assignment_local_interval(
        a.shift_date,
        a.start_time,
        a.end_time,
        coalesce(
          m.materialized_work_mode,
          m.scheduling_config #>> '{shiftPattern,workMode}',
          'shifts'
        ),
        m.scheduling_config
      ) assignment_bounds
      left join lateral (
        select st.name
        from public.job_type_schedule_materializations mat2
        join public.job_type_materialized_shift_templates st
          on st.materialization_id = mat2.id
         and st.is_active = true
        where mat2.job_type_id = m.job_type_id
          and mat2.effective_month <= make_date(p.year,p.month,1)
          and st.start_time = a.start_time
          and st.end_time = a.end_time
        order by mat2.effective_month desc,
                 case when st.code = a.shift_code then 0 else 1 end,
                 st.sort_order,
                 st.name
        limit 1
      ) tmpl on true
      where p.job_type_id = m.job_type_id
        and p.status = 'published'
        and a.user_id = current_user_id
        and assignment_bounds.end_at >= (now() at time zone 'Asia/Jerusalem')
      order by
        case
          when assignment_bounds.start_at <= (now() at time zone 'Asia/Jerusalem')
           and assignment_bounds.end_at >= (now() at time zone 'Asia/Jerusalem')
          then 0
          else 1
        end,
        assignment_bounds.start_at
      limit 1
    ) next_assignment on true
  ),
  role_rows as (
    select jsonb_build_object(
      'jobTypeId', m.job_type_id,
      'jobTypeName', m.name,
      'description', m.description,
      'isPrimary', m.is_primary,
      'workMode', coalesce(
        m.materialized_work_mode,
        m.scheduling_config #>> '{shiftPattern,workMode}',
        'shifts'
      ),
      'schedulingStrategy', coalesce(m.scheduling_strategy, 'availability_optimizer'),
      'scheduleChangeMode', coalesce(
        m.materialized_change_mode,
        m.scheduling_config #>> '{scheduleChangeMode}',
        'none'
      ),
      'availabilityEnabled', coalesce((m.availability_config->>'enabled')::boolean, true),
      'publishedAssignmentCount', (
        select count(*)::integer
        from public.dynamic_schedule_publications p
        join public.dynamic_schedule_published_assignments a
          on a.publication_id = p.id
        where p.job_type_id = m.job_type_id
          and p.status in ('published','archived')
          and a.user_id = current_user_id
          and a.shift_date >= current_month
      ),
      'nextAssignment', case when m.assignment_id is null then null else jsonb_build_object(
        'publicationId', m.publication_id,
        'assignmentId', m.assignment_id,
        'year', m.assignment_year,
        'month', m.assignment_month,
        'shiftDate', m.shift_date,
        'shiftCode', m.shift_code,
        'shiftName', m.display_shift_name,
        'startTime', to_char(m.assignment_start_at::time, 'HH24:MI:SS'),
        'endTime', to_char(m.assignment_end_at::time, 'HH24:MI:SS')
      ) end,
      'parallelAssignments', case when m.assignment_id is null then '[]'::jsonb else coalesce((
        select jsonb_agg(context_row.item order by context_row.job_type_name, context_row.shift_date, context_row.start_time, context_row.display_name)
        from (
          select
            target_jt.name as job_type_name,
            target_a.shift_date,
            target_a.start_time,
            coalesce(target_profile.display_name, 'לא משובץ') as display_name,
            jsonb_build_object(
              'jobTypeId', target_jt.id,
              'jobTypeName', target_jt.name,
              'workMode', coalesce(
                target_mode.work_mode,
                target_jt.scheduling_config #>> '{shiftPattern,workMode}',
                'shifts'
              ),
              'assignmentId', target_a.id,
              'shiftDate', target_a.shift_date,
              'shiftCode', target_a.shift_code,
              'shiftName', coalesce(nullif(target_tmpl.name,''), nullif(target_a.shift_name,target_a.shift_code), target_a.shift_name),
              'startTime', to_char(target_bounds.start_at::time, 'HH24:MI:SS'),
              'endTime', to_char(target_bounds.end_at::time, 'HH24:MI:SS'),
              'userId', target_a.user_id,
              'displayName', target_profile.display_name
            ) as item
          from public.job_type_dashboard_context_rules context_rule
          join public.job_types target_jt
            on target_jt.id = context_rule.target_job_type_id
           and target_jt.is_active = true
           and target_jt.legacy_role is null
          join public.dynamic_schedule_publications target_pub
            on target_pub.job_type_id = target_jt.id
           and target_pub.status = 'published'
          join public.dynamic_schedule_published_assignments target_a
            on target_a.publication_id = target_pub.id
          left join public.profiles target_profile
            on target_profile.id = target_a.user_id
          left join lateral (
            select mat_mode.work_mode
            from public.job_type_schedule_materializations mat_mode
            where mat_mode.job_type_id = target_jt.id
              and mat_mode.effective_month <= make_date(target_pub.year,target_pub.month,1)
            order by mat_mode.effective_month desc
            limit 1
          ) target_mode on true
          cross join lateral public.dynamic_resolve_assignment_local_interval(
            target_a.shift_date,
            target_a.start_time,
            target_a.end_time,
            coalesce(
              target_mode.work_mode,
              target_jt.scheduling_config #>> '{shiftPattern,workMode}',
              'shifts'
            ),
            target_jt.scheduling_config
          ) target_bounds
          left join lateral (
            select st.name
            from public.job_type_schedule_materializations mat3
            join public.job_type_materialized_shift_templates st
              on st.materialization_id = mat3.id
             and st.is_active = true
            where mat3.job_type_id = target_jt.id
              and mat3.effective_month <= make_date(target_pub.year,target_pub.month,1)
              and st.start_time = target_a.start_time
              and st.end_time = target_a.end_time
            order by mat3.effective_month desc,
                     case when st.code = target_a.shift_code then 0 else 1 end,
                     st.sort_order,
                     st.name
            limit 1
          ) target_tmpl on true
          where context_rule.source_job_type_id = m.job_type_id
            and context_rule.enabled = true
            and target_a.user_id is not null
            and target_bounds.start_at < m.assignment_end_at
            and target_bounds.end_at > m.assignment_start_at
        ) context_row
      ), '[]'::jsonb) end,
      'availability', (
        select jsonb_build_object(
          'periodId', ap.id,
          'year', ap.year,
          'month', ap.month,
          'status', ap.status,
          'submissionDeadline', ap.submission_deadline,
          'slotCount', (select count(*)::integer from public.dynamic_availability_slots s where s.period_id = ap.id),
          'filledCount', (
            select count(*)::integer
            from public.dynamic_availability_entries e
            where e.submission_id = sub.id
          ),
          'submissionStatus', sub.status
        )
        from public.dynamic_availability_periods ap
        left join public.dynamic_availability_submissions sub
          on sub.period_id = ap.id
         and sub.user_id = current_user_id
        where ap.job_type_id = m.job_type_id
          and ap.status in ('open','closed')
          and make_date(ap.year, ap.month, 1) >= current_month
        order by ap.year, ap.month
        limit 1
      )
    ) as item,
    m.is_primary,
    m.name
    from role_with_next m
  ),
  managed_rows as (
    select jsonb_build_object(
      'jobTypeId', jt.id,
      'jobTypeName', jt.name,
      'memberCount', (select count(*)::integer from public.job_type_memberships mm where mm.job_type_id = jt.id),
      'currentPeriodStatus', (
        select ap.status
        from public.dynamic_availability_periods ap
        where ap.job_type_id = jt.id
          and ap.year = extract(year from current_month)::integer
          and ap.month = extract(month from current_month)::integer
        limit 1
      ),
      'publishedAssignmentCount', (
        select count(*)::integer
        from public.dynamic_schedule_publications p
        join public.dynamic_schedule_published_assignments a on a.publication_id = p.id
        where p.job_type_id = jt.id
          and p.year = extract(year from current_month)::integer
          and p.month = extract(month from current_month)::integer
          and p.status = 'published'
      )
    ) as item,
    jt.name
    from public.job_types jt
    where can_manage
      and jt.is_active = true
      and jt.legacy_role is null
  )
  select jsonb_build_object(
    'hasDynamicMemberships', exists(select 1 from memberships),
    'primaryJobTypeName', (
      select m.name
      from memberships m
      order by m.is_primary desc, m.name
      limit 1
    ),
    'roles', coalesce((select jsonb_agg(r.item order by r.is_primary desc, r.name) from role_rows r), '[]'::jsonb),
    'canManageDynamicScheduling', can_manage,
    'managedRoles', coalesce((select jsonb_agg(mr.item order by mr.name) from managed_rows mr), '[]'::jsonb),
    'generatedAt', now()
  )
  into result;

  return result;
end;
$$;


ALTER FUNCTION "public"."get_my_dynamic_runtime_context"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_my_dynamic_schedule_periods"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  current_user_id uuid := auth.uid();
  result jsonb;
begin
  if current_user_id is null then
    raise exception 'not authenticated';
  end if;

  with period_rows as (
    select
      p.id as period_id,
      'publication'::text as period_source,
      jt.id as job_type_id,
      jt.name as job_type_name,
      p.year,
      p.month,
      p.status::text as status,
      p.published_at as effective_at,
      (
        select count(*)::integer
        from public.dynamic_schedule_published_assignments a
        where a.publication_id = p.id
          and (
            (public.has_dynamic_job_type_permission('schedule.view_others', p.job_type_id, current_user_id)
            or public.has_dynamic_job_type_permission('schedule.edit_all', p.job_type_id, current_user_id))
            or a.user_id = current_user_id
          )
      ) as assignment_count,
      coalesce(
        mat.work_mode,
        p.config_snapshot #>> '{jobType,shiftPattern,workMode}',
        jt.scheduling_config #>> '{shiftPattern,workMode}',
        'shifts'
      ) as work_mode,
      coalesce(
        mat.schedule_change_mode,
        p.config_snapshot #>> '{jobType,scheduleChangeMode}',
        jt.scheduling_config #>> '{scheduleChangeMode}',
        'none'
      ) as schedule_change_mode
    from public.dynamic_schedule_publications p
    join public.job_types jt
      on jt.id = p.job_type_id
     and jt.legacy_role is null
    join public.job_type_memberships membership
      on membership.job_type_id = p.job_type_id
     and membership.user_id = current_user_id
    left join public.job_type_schedule_materializations mat
      on mat.job_type_id = p.job_type_id
     and mat.effective_month = make_date(p.year, p.month, 1)
    where p.status in ('published', 'archived')

    union all

    select
      hp.id as period_id,
      'history'::text as period_source,
      jt.id as job_type_id,
      jt.name as job_type_name,
      hp.year,
      hp.month,
      'archived'::text as status,
      hp.imported_at as effective_at,
      (
        select count(*)::integer
        from public.dynamic_historical_assignments ha
        where ha.historical_period_id = hp.id
          and (
            (public.has_dynamic_job_type_permission('schedule.view_others', hp.job_type_id, current_user_id)
            or public.has_dynamic_job_type_permission('schedule.edit_all', hp.job_type_id, current_user_id))
            or ha.assigned_user_id = current_user_id
          )
      ) as assignment_count,
      coalesce(
        mat.work_mode,
        jt.scheduling_config #>> '{shiftPattern,workMode}',
        case hp.source_kind
          when 'on_call' then 'on_call_daily'
          when 'morning_driver' then 'shifts'
          else 'shifts'
        end
      ) as work_mode,
      'none'::text as schedule_change_mode
    from public.dynamic_historical_periods hp
    join public.job_types jt
      on jt.id = hp.job_type_id
     and jt.legacy_role is null
    join public.job_type_memberships membership
      on membership.job_type_id = hp.job_type_id
     and membership.user_id = current_user_id
    left join lateral (
      select m.work_mode
      from public.job_type_schedule_materializations m
      where m.job_type_id = hp.job_type_id
        and m.effective_month <= make_date(hp.year, hp.month, 1)
      order by m.effective_month desc
      limit 1
    ) mat on true
  )
  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'publicationId', row.period_id,
        'periodSource', row.period_source,
        'jobTypeId', row.job_type_id,
        'jobTypeName', row.job_type_name,
        'year', row.year,
        'month', row.month,
        'status', row.status,
        'publishedAt', row.effective_at,
        'assignmentCount', row.assignment_count,
        'workMode', row.work_mode,
        'scheduleChangeMode', row.schedule_change_mode
      )
      order by row.year desc, row.month desc, row.job_type_name
    ),
    '[]'::jsonb
  )
  into result
  from period_rows row;

  return result;
end;
$$;


ALTER FUNCTION "public"."get_my_dynamic_schedule_periods"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_my_dynamic_schedule_workspace"("requested_publication_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  current_user_id uuid := auth.uid();
  target_publication public.dynamic_schedule_publications%rowtype;
  target_history public.dynamic_historical_periods%rowtype;
  target_job public.job_types%rowtype;
  assignments_json jsonb;
  change_mode text;
  work_mode text;
  can_view_others boolean := false;
begin
  if current_user_id is null then
    raise exception 'not authenticated';
  end if;

  select * into target_publication
  from public.dynamic_schedule_publications
  where id = requested_publication_id;

  if target_publication.id is not null then
    select * into target_job
    from public.job_types
    where id = target_publication.job_type_id
      and legacy_role is null;

    if target_job.id is null then
      raise exception 'dynamic job type not found';
    end if;

    if not exists (
      select 1
      from public.job_type_memberships m
      where m.job_type_id = target_publication.job_type_id
        and m.user_id = current_user_id
    ) then
      raise exception 'not allowed';
    end if;

    can_view_others := public.has_dynamic_job_type_permission(
      'schedule.view_others',
      target_job.id,
      current_user_id
    ) or public.has_dynamic_job_type_permission(
      'schedule.edit_all',
      target_job.id,
      current_user_id
    );

    work_mode := coalesce(
      target_publication.config_snapshot #>> '{jobType,shiftPattern,workMode}',
      target_job.scheduling_config #>> '{shiftPattern,workMode}',
      'shifts'
    );

    change_mode := coalesce(
      (
        select mat.schedule_change_mode
        from public.job_type_schedule_materializations mat
        where mat.job_type_id = target_job.id
          and mat.effective_month <= make_date(target_publication.year, target_publication.month, 1)
        order by mat.effective_month desc
        limit 1
      ),
      target_publication.config_snapshot #>> '{jobType,scheduleChangeMode}',
      target_job.scheduling_config #>> '{scheduleChangeMode}',
      'none'
    );

    select coalesce(jsonb_agg(
      jsonb_build_object(
        'id', q.id,
        'shiftDate', q.shift_date,
        'shiftCode', q.shift_code,
        'shiftName', q.display_shift_name,
        'startTime', q.start_time,
        'endTime', q.end_time,
        'assignmentTier', q.assignment_tier,
        'managerEdited', q.manager_edited,
        'managerOverrideNote', q.manager_override_note,
        'holidayName', q.holiday_name,
        'sourceDayKind', q.source_day_kind,
        'contains200Percent', q.contains_200_percent,
        'premium200Hours', q.premium_200_hours,
        'userId', q.user_id,
        'displayName', q.display_name,
        'isMine', q.user_id = current_user_id
      ) order by q.shift_date, q.start_time, q.display_shift_name
    ), '[]'::jsonb)
    into assignments_json
    from (
      select
        a.id,
        a.shift_date,
        a.shift_code,
        coalesce(
          nullif(tmpl.name, ''),
          nullif(sl.shift_name, sl.shift_code),
          nullif(a.shift_name, a.shift_code),
          a.shift_name
        ) as display_shift_name,
        a.start_time,
        a.end_time,
        a.assignment_tier,
        a.manager_edited,
        a.manager_override_note,
        a.user_id,
        assignee.display_name,
        coalesce(sl.holiday_name, legacy_shift.holiday_name, holiday.event_name) as holiday_name,
        coalesce(sl.source_day_kind, legacy_shift.schedule_type::text, holiday.schedule_type) as source_day_kind,
        coalesce(
          case
            when sl.metadata ? 'contains200Percent'
              then (sl.metadata->>'contains200Percent')::boolean
            else null
          end,
          legacy_shift.is_premium,
          tmpl.contains_200_percent,
          false
        ) as contains_200_percent,
        coalesce(
          case
            when sl.metadata ? 'premium200Hours'
              then (sl.metadata->>'premium200Hours')::numeric
            else null
          end,
          tmpl.premium_200_hours,
          0
        ) as premium_200_hours
      from public.dynamic_schedule_published_assignments a
      left join public.profiles assignee
        on assignee.id = a.user_id
      left join public.dynamic_availability_slots sl
        on sl.id = a.slot_id
      left join public.schedule_shifts legacy_shift
        on legacy_shift.id = case
          when coalesce(sl.metadata->>'sourceRecordId','') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
            then (sl.metadata->>'sourceRecordId')::uuid
          else null
        end
      left join lateral (
        select csd.event_name, csd.schedule_type
        from public.calendar_special_days csd
        where csd.event_date = a.shift_date
        order by
          case when csd.source_name = 'manual' then 0 else 1 end,
          case csd.schedule_type
            when 'holiday_full' then 1
            when 'holiday_end' then 2
            when 'holiday_eve' then 3
            when 'chol_hamoed' then 4
            else 5
          end
        limit 1
      ) holiday on true
      left join lateral (
        select st.name, st.contains_200_percent, st.premium_200_hours
        from public.job_type_schedule_materializations mat
        join public.job_type_materialized_shift_templates st
          on st.materialization_id = mat.id
         and st.is_active = true
        where mat.job_type_id = target_job.id
          and mat.effective_month <= make_date(target_publication.year, target_publication.month, 1)
          and st.start_time = a.start_time
          and st.end_time = a.end_time
        order by
          mat.effective_month desc,
          case when st.code = a.shift_code then 0 else 1 end,
          st.sort_order,
          st.name
        limit 1
      ) tmpl on true
      where a.publication_id = target_publication.id
        and (can_view_others or a.user_id = current_user_id)
    ) q;

    return jsonb_build_object(
      'publicationId', target_publication.id,
      'periodSource', 'publication',
      'readOnly', false,
      'jobTypeId', target_job.id,
      'jobTypeName', target_job.name,
      'year', target_publication.year,
      'month', target_publication.month,
      'status', target_publication.status,
      'publishedAt', target_publication.published_at,
      'workMode', work_mode,
      'scheduleChangeMode', change_mode,
      'canViewOthers', can_view_others,
      'assignments', assignments_json
    );
  end if;

  select * into target_history
  from public.dynamic_historical_periods
  where id = requested_publication_id;

  if target_history.id is null then
    raise exception 'schedule period not found';
  end if;

  select * into target_job
  from public.job_types
  where id = target_history.job_type_id
    and legacy_role is null;

  if target_job.id is null then
    raise exception 'dynamic job type not found';
  end if;

  if not exists (
    select 1
    from public.job_type_memberships m
    where m.job_type_id = target_history.job_type_id
      and m.user_id = current_user_id
  ) then
    raise exception 'not allowed';
  end if;

  can_view_others := public.has_dynamic_job_type_permission(
    'schedule.view_others',
    target_job.id,
    current_user_id
  ) or public.has_dynamic_job_type_permission(
    'schedule.edit_all',
    target_job.id,
    current_user_id
  );

  select coalesce(
    (
      select mat.work_mode
      from public.job_type_schedule_materializations mat
      where mat.job_type_id = target_job.id
        and mat.effective_month <= make_date(target_history.year, target_history.month, 1)
      order by mat.effective_month desc
      limit 1
    ),
    target_job.scheduling_config #>> '{shiftPattern,workMode}',
    case target_history.source_kind
      when 'on_call' then 'on_call_daily'
      else 'shifts'
    end
  ) into work_mode;

  select coalesce(jsonb_agg(
    jsonb_build_object(
      'id', q.id,
      'shiftDate', q.shift_date,
      'shiftCode', q.shift_code,
      'shiftName', q.display_shift_name,
      'startTime', q.start_time,
      'endTime', q.end_time,
      'assignmentTier', 'historical',
      'managerEdited', false,
      'managerOverrideNote', null,
      'holidayName', q.holiday_name,
      'sourceDayKind', q.source_day_kind,
      'contains200Percent', q.contains_200_percent,
      'premium200Hours', q.premium_200_hours,
      'userId', q.user_id,
      'displayName', q.display_name,
      'isMine', q.user_id = current_user_id
    ) order by q.shift_date, q.start_time, q.display_shift_name
  ), '[]'::jsonb)
  into assignments_json
  from (
    select
      ha.id,
      ha.work_date as shift_date,
      coalesce(ha.shift_code, ha.source_kind || '-' || ha.id::text) as shift_code,
      coalesce(
        nullif(tmpl.name, ''),
        nullif(ha.source_payload->>'shift_name', ''),
        nullif(ha.source_payload #>> '{shift,name}', ''),
        case target_history.source_kind
          when 'on_call' then 'כוננות יומית'
          when 'morning_driver' then 'כוננות בוקר'
          else null
        end,
        nullif(ha.shift_code, ''),
        'שיבוץ'
      ) as display_shift_name,
      coalesce(
        to_char(ha.starts_at at time zone 'Asia/Jerusalem', 'HH24:MI:SS'),
        nullif(ha.source_payload #>> '{shift,start_time}', ''),
        case when target_history.source_kind = 'on_call' then '00:00:00' else '00:00:00' end
      ) as start_time,
      coalesce(
        to_char(ha.ends_at at time zone 'Asia/Jerusalem', 'HH24:MI:SS'),
        nullif(ha.source_payload #>> '{shift,end_time}', ''),
        case when target_history.source_kind = 'on_call' then '23:59:00' else '00:00:00' end
      ) as end_time,
      ha.assigned_user_id as user_id,
      assignee.display_name,
      coalesce(
        nullif(ha.source_payload->>'holiday_name', ''),
        nullif(ha.source_payload #>> '{shift,holiday_name}', ''),
        holiday.event_name
      ) as holiday_name,
      coalesce(
        nullif(ha.source_payload->>'schedule_type', ''),
        nullif(ha.source_payload #>> '{shift,schedule_type}', ''),
        holiday.schedule_type
      ) as source_day_kind,
      coalesce(
        case
          when lower(coalesce(ha.source_payload->>'is_premium','')) in ('true','false')
            then (ha.source_payload->>'is_premium')::boolean
          else null
        end,
        case
          when lower(coalesce(ha.source_payload #>> '{shift,is_premium}','')) in ('true','false')
            then (ha.source_payload #>> '{shift,is_premium}')::boolean
          else null
        end,
        tmpl.contains_200_percent,
        false
      ) as contains_200_percent,
      coalesce(tmpl.premium_200_hours, 0) as premium_200_hours
    from public.dynamic_historical_assignments ha
    left join public.profiles assignee
      on assignee.id = ha.assigned_user_id
    left join lateral (
      select csd.event_name, csd.schedule_type
      from public.calendar_special_days csd
      where csd.event_date = ha.work_date
      order by
        case when csd.source_name = 'manual' then 0 else 1 end,
        case csd.schedule_type
          when 'holiday_full' then 1
          when 'holiday_end' then 2
          when 'holiday_eve' then 3
          when 'chol_hamoed' then 4
          else 5
        end
      limit 1
    ) holiday on true
    left join lateral (
      select st.name, st.contains_200_percent, st.premium_200_hours
      from public.job_type_schedule_materializations mat
      join public.job_type_materialized_shift_templates st
        on st.materialization_id = mat.id
       and st.is_active = true
      where mat.job_type_id = target_job.id
      order by
        -- Prefer a template that was already effective in the historical month.
        -- If the Dynamic Job Type was created only after the imported month,
        -- fall back to its nearest later materialization instead of exposing
        -- the legacy technical shift code to the employee.
        case
          when mat.effective_month <= make_date(target_history.year, target_history.month, 1) then 0
          else 1
        end,
        case
          when mat.effective_month <= make_date(target_history.year, target_history.month, 1)
            then (make_date(target_history.year, target_history.month, 1) - mat.effective_month)
          else (mat.effective_month - make_date(target_history.year, target_history.month, 1))
        end,
        case when st.code = ha.shift_code then 0 else 1 end,
        case
          when ha.starts_at is not null and ha.ends_at is not null
            and st.start_time = (ha.starts_at at time zone 'Asia/Jerusalem')::time
            and st.end_time = (ha.ends_at at time zone 'Asia/Jerusalem')::time
          then 0
          else 1
        end,
        case
          when ha.starts_at is not null then
            abs(extract(epoch from (st.start_time - (ha.starts_at at time zone 'Asia/Jerusalem')::time)))
          else 0
        end
        + case
            when ha.ends_at is not null then
              abs(extract(epoch from (st.end_time - (ha.ends_at at time zone 'Asia/Jerusalem')::time)))
            else 0
          end,
        st.sort_order,
        st.name
      limit 1
    ) tmpl on true
    where ha.historical_period_id = target_history.id
      and (can_view_others or ha.assigned_user_id = current_user_id)
  ) q;

  return jsonb_build_object(
    'publicationId', target_history.id,
    'periodSource', 'history',
    'readOnly', true,
    'jobTypeId', target_job.id,
    'jobTypeName', target_job.name,
    'year', target_history.year,
    'month', target_history.month,
    'status', 'archived',
    'publishedAt', target_history.imported_at,
    'workMode', work_mode,
    'scheduleChangeMode', 'none',
    'canViewOthers', can_view_others,
    'assignments', assignments_json
  );
end;
$_$;


ALTER FUNCTION "public"."get_my_dynamic_schedule_workspace"("requested_publication_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_my_dynamic_self_edit_workspace"("requested_publication_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  current_user_id uuid := auth.uid();
  target_publication public.dynamic_schedule_publications%rowtype;
  target_job public.job_types%rowtype;
  current_month date := date_trunc('month', (now() at time zone 'Asia/Jerusalem')::date)::date;
  publication_month date;
  change_mode text;
  editable boolean := false;
  reason text := null;
  can_view_others boolean := false;
  can_self_edit boolean := false;
  can_edit_all boolean := false;
  members_json jsonb;
  assignments_json jsonb;
begin
  if current_user_id is null then
    raise exception 'not authenticated';
  end if;

  select * into target_publication
  from public.dynamic_schedule_publications
  where id = requested_publication_id;

  if target_publication.id is null then
    raise exception 'publication not found';
  end if;

  if not exists (
    select 1
    from public.job_type_memberships m
    join public.profiles p on p.id = m.user_id
    where m.job_type_id = target_publication.job_type_id
      and m.user_id = current_user_id
      and p.is_active = true
  ) then
    raise exception 'not allowed';
  end if;

  select * into target_job
  from public.job_types
  where id = target_publication.job_type_id
    and legacy_role is null;

  if target_job.id is null then
    raise exception 'dynamic job type not found';
  end if;

  change_mode := coalesce(
    target_publication.config_snapshot #>> '{jobType,scheduleChangeMode}',
    target_job.scheduling_config #>> '{scheduleChangeMode}',
    'none'
  );

  if change_mode <> 'self_edit' then
    raise exception 'self edit is not enabled for this role';
  end if;

  can_self_edit := public.has_dynamic_job_type_permission('schedule.self_edit', target_job.id, current_user_id);
  can_edit_all := public.has_dynamic_job_type_permission('schedule.edit_all', target_job.id, current_user_id);

  if not can_self_edit and not can_edit_all then
    raise exception 'not allowed';
  end if;

  can_view_others := can_edit_all or public.has_dynamic_job_type_permission(
    'schedule.view_others',
    target_job.id,
    current_user_id
  );

  publication_month := make_date(target_publication.year, target_publication.month, 1);

  if target_publication.status <> 'published' then
    editable := false;
    reason := 'לוח זה אינו פתוח לעריכה משום שהוא בארכיון.';
  elsif publication_month = current_month then
    editable := true;
  elsif publication_month = (current_month + interval '1 month')::date then
    editable := true;
  elsif publication_month < current_month then
    editable := false;
    reason := 'ניתן לערוך רק את החודש הנוכחי או את החודש הבא לאחר שפורסם.';
  else
    editable := false;
    reason := 'החודש הזה עדיין אינו בחלון העריכה המותר.';
  end if;

  select coalesce(jsonb_agg(
    jsonb_build_object(
      'userId', m.user_id,
      'displayName', p.display_name
    ) order by p.display_name
  ), '[]'::jsonb)
  into members_json
  from public.job_type_memberships m
  join public.profiles p on p.id = m.user_id
  where m.job_type_id = target_publication.job_type_id
    and p.is_active = true;

  select coalesce(jsonb_agg(
    jsonb_build_object(
      'id', a.id,
      'shiftDate', a.shift_date,
      'shiftCode', a.shift_code,
      'shiftName', a.shift_name,
      'startTime', a.start_time,
      'endTime', a.end_time,
      'userId', a.user_id,
      'displayName', p.display_name,
      'isMine', a.user_id = current_user_id,
      'userEditedBy', a.user_edited_by,
      'userEditedAt', a.user_edited_at
    ) order by a.shift_date, a.start_time, a.shift_name, p.display_name
  ), '[]'::jsonb)
  into assignments_json
  from public.dynamic_schedule_published_assignments a
  join public.profiles p on p.id = a.user_id
  where a.publication_id = target_publication.id
    and (can_view_others or a.user_id = current_user_id);

  return jsonb_build_object(
    'publicationId', target_publication.id,
    'jobTypeId', target_job.id,
    'jobTypeName', target_job.name,
    'year', target_publication.year,
    'month', target_publication.month,
    'editable', editable,
    'editabilityReason', reason,
    'canViewOthers', can_view_others,
    'canEditAll', can_edit_all,
    'members', members_json,
    'assignments', assignments_json
  );
end;
$$;


ALTER FUNCTION "public"."get_my_dynamic_self_edit_workspace"("requested_publication_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_my_dynamic_shift_exchange_options"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  current_user_id uuid := auth.uid();
  local_now timestamp := now() at time zone 'Asia/Jerusalem';
  current_month date := date_trunc('month', local_now::date)::date;
  next_month date := (date_trunc('month', local_now::date) + interval '1 month')::date;
  result jsonb;
begin
  if current_user_id is null then raise exception 'not authenticated'; end if;

  with eligible_publications as (
    select p.*, jt.name job_type_name,
      (coalesce(mat.schedule_change_mode, 'none') = 'shift_exchange'
       or coalesce(p.config_snapshot #>> '{jobType,scheduleChangeMode}', 'none') = 'shift_exchange'
       or coalesce(jt.scheduling_config #>> '{scheduleChangeMode}', 'none') = 'shift_exchange') as exchange_enabled
    from public.dynamic_schedule_publications p
    join public.job_types jt on jt.id=p.job_type_id
    join public.job_type_memberships m on m.job_type_id=p.job_type_id and m.user_id=current_user_id
    left join public.job_type_schedule_materializations mat
      on mat.job_type_id=p.job_type_id
     and mat.effective_month=make_date(p.year,p.month,1)
    where p.status='published'
      and make_date(p.year,p.month,1) in (current_month, next_month)
  ), eligible as (
    select e.*
    from eligible_publications e
    where e.exchange_enabled
      and exists (
        select 1
        from public.dynamic_schedule_published_assignments a
        where a.publication_id=e.id
          and a.user_id=current_user_id
          and (a.shift_date > local_now::date or (a.shift_date = local_now::date and a.start_time > local_now::time))
      )
  )
  select jsonb_build_object(
    'hasDynamicShiftExchange', exists(select 1 from eligible),
    'publications', coalesce((select jsonb_agg(jsonb_build_object(
      'publicationId',e.id,'jobTypeId',e.job_type_id,'jobTypeName',e.job_type_name,
      'year',e.year,'month',e.month
    ) order by e.year,e.month,e.job_type_name) from eligible e),'[]'::jsonb),
    'myShifts', coalesce((select jsonb_agg(jsonb_build_object(
      'id',a.id,'publicationId',a.publication_id,'jobTypeId',e.job_type_id,'jobTypeName',e.job_type_name,
      'shiftDate',a.shift_date,'shiftCode',a.shift_code,'shiftName',a.shift_name,
      'startTime',a.start_time,'endTime',a.end_time,'year',e.year,'month',e.month
    ) order by a.shift_date,a.start_time)
      from eligible e join public.dynamic_schedule_published_assignments a on a.publication_id=e.id
      where a.user_id=current_user_id
        and (a.shift_date > local_now::date or (a.shift_date = local_now::date and a.start_time > local_now::time))), '[]'::jsonb),
    'members', coalesce((select jsonb_agg(distinct jsonb_build_object(
      'userId',m.user_id,'displayName',pr.display_name,'jobTypeId',e.job_type_id
    ))
      from eligible e join public.job_type_memberships m on m.job_type_id=e.job_type_id
      join public.profiles pr on pr.id=m.user_id and pr.is_active=true
      where m.user_id<>current_user_id),'[]'::jsonb),
    'counterpartyShifts', coalesce((select jsonb_agg(jsonb_build_object(
      'id',a.id,'publicationId',a.publication_id,'jobTypeId',e.job_type_id,'jobTypeName',e.job_type_name,
      'assignedUserId',a.user_id,'shiftDate',a.shift_date,'shiftCode',a.shift_code,'shiftName',a.shift_name,
      'startTime',a.start_time,'endTime',a.end_time,'year',e.year,'month',e.month
    ) order by a.shift_date,a.start_time)
      from eligible e join public.dynamic_schedule_published_assignments a on a.publication_id=e.id
      where a.user_id<>current_user_id
        and (a.shift_date > local_now::date or (a.shift_date = local_now::date and a.start_time > local_now::time))), '[]'::jsonb)
  ) into result;

  return coalesce(result, jsonb_build_object(
    'hasDynamicShiftExchange',false,
    'publications','[]'::jsonb,
    'myShifts','[]'::jsonb,
    'members','[]'::jsonb,
    'counterpartyShifts','[]'::jsonb
  ));
end;
$$;


ALTER FUNCTION "public"."get_my_dynamic_shift_exchange_options"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_my_manager_dashboard_widgets"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_actor uuid := auth.uid();
  v_local_now timestamp := timezone('Asia/Jerusalem', now());
  v_today date := timezone('Asia/Jerusalem', now())::date;
begin
  if not public.can_configure_manager_dashboard(v_actor) then
    return '[]'::jsonb;
  end if;

  return coalesce((
    select jsonb_agg(
      jsonb_build_object(
        'id', w.id,
        'timeScope', w.time_scope,
        'jobTypeId', jt.id,
        'jobTypeName', jt.name,
        'workMode', coalesce(current_mat.work_mode, jt.scheduling_config #>> '{shiftPattern,workMode}', 'shifts'),
        'assignments', coalesce(assignments.items, '[]'::jsonb)
      )
      order by w.sort_order, w.created_at
    )
    from public.user_dashboard_widgets w
    join public.job_types jt
      on jt.id = w.job_type_id
     and jt.is_active = true
    left join lateral (
      -- Widget metadata follows the configuration effective for the current month,
      -- never a future materialization.
      select m.work_mode, m.source_snapshot
      from public.job_type_schedule_materializations m
      where m.job_type_id = jt.id
        and m.effective_month <= date_trunc('month', v_today)::date
      order by m.effective_month desc
      limit 1
    ) current_mat on true
    left join lateral (
      select jsonb_agg(
        jsonb_build_object(
          'assignmentId', candidate.assignment_id,
          'userId', candidate.user_id,
          'displayName', candidate.display_name,
          'shiftDate', candidate.shift_date,
          'shiftName', candidate.shift_name,
          'startTime', candidate.display_start_time,
          'endTime', candidate.display_end_time
        )
        order by candidate.assignment_start_at, candidate.display_name
      ) as items
      from (
        select
          a.id as assignment_id,
          a.user_id,
          coalesce(p.schedule_name, p.display_name, p.email, 'משתמש') as display_name,
          a.shift_date,
          public.resolve_dynamic_shift_display_name(
            jt.id,
            a.shift_date,
            a.shift_code,
            a.shift_name,
            a.start_time,
            a.end_time,
            case when assignment_cfg.work_mode = 'on_call_daily' then 'כוננות' else 'משמרת' end
          ) as shift_name,
          assignment_bounds.start_at as assignment_start_at,
          assignment_bounds.end_at as assignment_end_at,
          assignment_bounds.start_at::time as display_start_time,
          assignment_bounds.end_at::time as display_end_time
        from public.dynamic_schedule_published_assignments a
        join public.dynamic_schedule_publications pub
          on pub.id = a.publication_id
         and pub.job_type_id = jt.id
         and pub.status = 'published'
        join public.profiles p on p.id = a.user_id
        left join lateral (
          -- Resolve the role configuration that was effective for THIS assignment,
          -- so next-month edits cannot rewrite today's operational meaning.
          select
            m.work_mode,
            m.source_snapshot
          from public.job_type_schedule_materializations m
          where m.job_type_id = jt.id
            and m.effective_month <= date_trunc('month', a.shift_date)::date
          order by m.effective_month desc
          limit 1
        ) assignment_mat on true
        cross join lateral (
          select
            coalesce(assignment_mat.work_mode, jt.scheduling_config #>> '{shiftPattern,workMode}', 'shifts') as work_mode,
            coalesce(assignment_mat.source_snapshot, jsonb_build_object('schedulingConfig', jt.scheduling_config)) as scheduling_snapshot
        ) assignment_cfg
        cross join lateral public.dynamic_resolve_assignment_local_interval(
          a.shift_date,
          a.start_time,
          a.end_time,
          assignment_cfg.work_mode,
          assignment_cfg.scheduling_snapshot
        ) assignment_bounds
        where
          -- Keep the scan narrow while still including a duty that began yesterday
          -- and remains active after midnight.
          a.shift_date between v_today - 1 and v_today
          and (
            (w.time_scope = 'today' and a.shift_date = v_today)
            or
            (w.time_scope = 'current'
              and v_local_now >= assignment_bounds.start_at
              and v_local_now < assignment_bounds.end_at)
          )
      ) candidate
    ) assignments on true
    where w.user_id = v_actor
      and w.enabled = true
  ), '[]'::jsonb);
end;
$$;


ALTER FUNCTION "public"."get_my_manager_dashboard_widgets"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_my_morning_driver_availability"("requested_period_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  current_user_id uuid := auth.uid();
  current_permissions text[];
  target_period public.morning_driver_availability_periods%rowtype;
  target_submission public.morning_driver_availability_submissions%rowtype;
  shifts_json jsonb;
begin
  if current_user_id is null then
    raise exception 'not authenticated';
  end if;

  if not exists (
    select 1
    from public.profiles profile
    where profile.id = current_user_id
      and profile.is_active = true
  ) then
    raise exception 'user not active';
  end if;

  current_permissions :=
    coalesce(
      public.get_my_permissions(),
      array[]::text[]
    );

  if not (
    'morning_driver_availability.view'
      = any(current_permissions)
  ) then
    raise exception 'not allowed';
  end if;

  if requested_period_id is null then
    select *
    into target_period
    from public.morning_driver_availability_periods period
    where period.status = 'open'
    order by
      period.year desc,
      period.month desc,
      period.opened_at desc nulls last
    limit 1;
  else
    select *
    into target_period
    from public.morning_driver_availability_periods period
    where period.id = requested_period_id
      and period.status in (
        'open',
        'closed',
        'archived'
      )
    limit 1;
  end if;

  if not found then
    return null;
  end if;

  select *
  into target_submission
  from public.morning_driver_availability_submissions submission
  where submission.period_id = target_period.id
    and submission.user_id = current_user_id
  limit 1;

  if not found then
    insert into public.morning_driver_availability_submissions (
      period_id,
      user_id,
      status
    )
    values (
      target_period.id,
      current_user_id,
      'draft'
    )
    returning *
    into target_submission;
  end if;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'id',
          shift_item.id,
        'periodId',
          shift_item.period_id,
        'shiftDate',
          shift_item.shift_date,
        'weekdayNumber',
          shift_item.weekday_number,
        'weekdayName',
          shift_item.weekday_name,
        'shiftType',
          shift_item.shift_type,
        'startTime',
          shift_item.start_time,
        'endTime',
          shift_item.end_time,
        'minimumWorkers',
          1,

        'recommendedWorkers',
          shift_item.required_workers,
        'sortOrder',
          shift_item.sort_order,
        'holidayName',
          holiday_row.holiday_name,
        'holidayScheduleType',
          holiday_row.schedule_type,
        'availabilityStatus',
          entry.availability_status,
        'note',
          entry.note
      )
      order by
        shift_item.shift_date,
        shift_item.sort_order
    ),
    '[]'::jsonb
  )
  into shifts_json
  from public.morning_driver_availability_shifts shift_item
  left join public.morning_driver_availability_entries entry
    on entry.shift_id = shift_item.id
   and entry.user_id = current_user_id
  left join lateral (
    select
      string_agg(holiday.name, ' / ' order by holiday.name) as holiday_name,
      case
        when bool_or(holiday.schedule_type::text = 'holiday_full') then 'holiday_full'
        when bool_or(holiday.schedule_type::text = 'holiday_end') then 'holiday_end'
        when bool_or(holiday.schedule_type::text = 'holiday_eve') then 'holiday_eve'
        else max(holiday.schedule_type::text)
      end as schedule_type
    from public.holidays holiday
    where holiday.holiday_date = shift_item.shift_date
  ) holiday_row on true
  where shift_item.period_id = target_period.id
    and coalesce(holiday_row.schedule_type, '') not in ('holiday_full', 'holiday_end');

  return jsonb_build_object(
    'period',
      jsonb_build_object(
        'id',
          target_period.id,
        'year',
          target_period.year,
        'month',
          target_period.month,
        'status',
          target_period.status,
        'title',
          target_period.title,
        'instructions',
          target_period.instructions,
        'submissionDeadline',
          target_period.submission_deadline,
        'openedAt',
          target_period.opened_at,
        'closedAt',
          target_period.closed_at,
        'createdAt',
          target_period.created_at
      ),
    'submission',
      jsonb_build_object(
        'id',
          target_submission.id,
        'periodId',
          target_submission.period_id,
        'userId',
          target_submission.user_id,
        'status',
          target_submission.status,
        'submittedAt',
          target_submission.submitted_at,
        'lastSavedAt',
          target_submission.last_saved_at,
        'createdAt',
          target_submission.created_at,
        'updatedAt',
          target_submission.updated_at
      ),
    'shifts',
      shifts_json
  );
end;
$$;


ALTER FUNCTION "public"."get_my_morning_driver_availability"("requested_period_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_my_morning_driver_dashboard"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  current_user_id uuid;
  current_local_timestamp timestamp;
  current_local_date date;
  current_year integer;
  current_month integer;
  current_shift_json jsonb := null;
  next_shift_json jsonb := null;
  total_assignments integer := 0;
  completed_assignments integer := 0;
begin
  current_user_id := auth.uid();

  if current_user_id is null then
    raise exception 'not authenticated';
  end if;

  if not exists (
    select 1
    from public.profiles profile
    where profile.id = current_user_id
      and profile.is_active = true
      and profile.role = 'morning_driver'::public.user_role
  ) then
    raise exception 'morning driver profile not found';
  end if;

  if not (
    'dashboard.view' = any(
      coalesce(
        public.get_my_permissions(),
        array[]::text[]
      )
    )
  ) then
    raise exception 'not allowed';
  end if;

  current_local_timestamp :=
    now() at time zone 'Asia/Jerusalem';

  current_local_date :=
    current_local_timestamp::date;

  current_year :=
    extract(year from current_local_date)::integer;

  current_month :=
    extract(month from current_local_date)::integer;

  with personal_assignments as (
    select
      assignment.id as assignment_id,
      assignment.schedule_period_id,
      assignment.availability_shift_id,
      assignment.assignment_slot,
      shift_item.shift_date,
      shift_item.weekday_name,
      shift_item.shift_type,
      shift_item.start_time,
      shift_item.end_time,
      (
        shift_item.shift_date +
        shift_item.start_time
      ) at time zone 'Asia/Jerusalem' as starts_at,
      (
        shift_item.shift_date +
        shift_item.end_time +
        case
          when shift_item.end_time <= shift_item.start_time
          then interval '1 day'
          else interval '0 day'
        end
      ) at time zone 'Asia/Jerusalem' as ends_at
    from public.morning_driver_schedule_assignments assignment
    join public.morning_driver_schedule_periods period
      on period.id = assignment.schedule_period_id
    join public.morning_driver_availability_shifts shift_item
      on shift_item.id = assignment.availability_shift_id
    where assignment.assigned_user_id = current_user_id
      and period.status = 'published'
  ),
  current_assignment as (
    select *
    from personal_assignments
    where starts_at <= now()
      and ends_at > now()
    order by starts_at
    limit 1
  )
  select
    jsonb_build_object(
      'assignmentId', current_assignment.assignment_id,
      'shiftDate', current_assignment.shift_date,
      'weekdayName', current_assignment.weekday_name,
      'startTime', current_assignment.start_time,
      'endTime', current_assignment.end_time,
      'shiftType', current_assignment.shift_type,
      'parallelDrivers',
        coalesce(
          (
            select jsonb_agg(
              jsonb_build_object(
                'id', profile.id,
                'displayName', profile.display_name,
                'scheduleName', profile.schedule_name
              )
              order by coalesce(
                profile.schedule_name,
                profile.display_name
              )
            )
            from public.morning_driver_schedule_assignments parallel_assignment
            join public.profiles profile
              on profile.id = parallel_assignment.assigned_user_id
            where parallel_assignment.schedule_period_id = current_assignment.schedule_period_id
              and parallel_assignment.availability_shift_id = current_assignment.availability_shift_id
              and parallel_assignment.assigned_user_id is not null
              and parallel_assignment.assigned_user_id <> current_user_id
          ),
          '[]'::jsonb
        )
    )
  into current_shift_json
  from current_assignment;

  with personal_assignments as (
    select
      assignment.id as assignment_id,
      assignment.schedule_period_id,
      assignment.availability_shift_id,
      assignment.assignment_slot,
      shift_item.shift_date,
      shift_item.weekday_name,
      shift_item.shift_type,
      shift_item.start_time,
      shift_item.end_time,
      (
        shift_item.shift_date +
        shift_item.start_time
      ) at time zone 'Asia/Jerusalem' as starts_at,
      (
        shift_item.shift_date +
        shift_item.end_time +
        case
          when shift_item.end_time <= shift_item.start_time
          then interval '1 day'
          else interval '0 day'
        end
      ) at time zone 'Asia/Jerusalem' as ends_at
    from public.morning_driver_schedule_assignments assignment
    join public.morning_driver_schedule_periods period
      on period.id = assignment.schedule_period_id
    join public.morning_driver_availability_shifts shift_item
      on shift_item.id = assignment.availability_shift_id
    where assignment.assigned_user_id = current_user_id
      and period.status = 'published'
  ),
  next_assignment as (
    select *
    from personal_assignments
    where starts_at > now()
    order by starts_at
    limit 1
  )
  select
    jsonb_build_object(
      'assignmentId', next_assignment.assignment_id,
      'shiftDate', next_assignment.shift_date,
      'weekdayName', next_assignment.weekday_name,
      'startTime', next_assignment.start_time,
      'endTime', next_assignment.end_time,
      'shiftType', next_assignment.shift_type,
      'parallelDrivers',
        coalesce(
          (
            select jsonb_agg(
              jsonb_build_object(
                'id', profile.id,
                'displayName', profile.display_name,
                'scheduleName', profile.schedule_name
              )
              order by coalesce(
                profile.schedule_name,
                profile.display_name
              )
            )
            from public.morning_driver_schedule_assignments parallel_assignment
            join public.profiles profile
              on profile.id = parallel_assignment.assigned_user_id
            where parallel_assignment.schedule_period_id = next_assignment.schedule_period_id
              and parallel_assignment.availability_shift_id = next_assignment.availability_shift_id
              and parallel_assignment.assigned_user_id is not null
              and parallel_assignment.assigned_user_id <> current_user_id
          ),
          '[]'::jsonb
        )
    )
  into next_shift_json
  from next_assignment;

  select
    count(*)::integer,
    count(*) filter (
      where (
        shift_item.shift_date +
        shift_item.end_time +
        case
          when shift_item.end_time <= shift_item.start_time
          then interval '1 day'
          else interval '0 day'
        end
      ) at time zone 'Asia/Jerusalem' <= now()
    )::integer
  into
    total_assignments,
    completed_assignments
  from public.morning_driver_schedule_assignments assignment
  join public.morning_driver_schedule_periods period
    on period.id = assignment.schedule_period_id
  join public.morning_driver_availability_shifts shift_item
    on shift_item.id = assignment.availability_shift_id
  where assignment.assigned_user_id = current_user_id
    and period.status = 'published'
    and period.year = current_year
    and period.month = current_month;

  return jsonb_build_object(
    'currentShift', current_shift_json,
    'nextShift', next_shift_json,
    'monthlyProgress',
      jsonb_build_object(
        'year', current_year,
        'month', current_month,
        'completed', completed_assignments,
        'total', total_assignments,
        'percentage',
          case
            when total_assignments = 0 then 0
            else round(
              (
                completed_assignments::numeric /
                total_assignments::numeric
              ) * 100,
              1
            )
          end
      )
  );
end;
$$;


ALTER FUNCTION "public"."get_my_morning_driver_dashboard"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_my_open_availability"() RETURNS TABLE("period_id" "uuid", "period_year" integer, "period_month" integer, "period_title" "text", "period_instructions" "text", "submission_deadline" timestamp with time zone, "period_status" "text", "submission_status" "text", "submitted_at" timestamp with time zone, "last_saved_at" timestamp with time zone, "available_count" integer, "unavailable_count" integer, "shift_slot_id" "uuid", "shift_date" "date", "weekday_number" integer, "weekday_name" "text", "start_time" time without time zone, "end_time" time without time zone, "ends_next_day" boolean, "schedule_type" "text", "holiday_name" "text", "is_premium" boolean, "sort_order" integer, "availability_status" "text", "availability_note" "text", "availability_updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  current_user_id uuid;
  open_period_id uuid;
begin
  current_user_id := auth.uid();

  if current_user_id is null then
    raise exception
      'User is not authenticated';
  end if;

  if not exists (
    select 1
    from public.profiles profile
    where profile.id = current_user_id
      and profile.is_active = true
  ) then
    raise exception
      'Authenticated user is not active';
  end if;

  if not exists (
    select 1
    from public.user_permissions permission
    where permission.user_id =
      current_user_id
      and permission.permission_key =
        'availability.view'
  ) then
    raise exception
      'User is not allowed to view availability';
  end if;

  select
    period.id
  into
    open_period_id
  from public.availability_periods period
  where period.status = 'open'
  order by
    period.year desc,
    period.month desc,
    period.opened_at desc nulls last
  limit 1;

  if open_period_id is null then
    return;
  end if;

  return query
  select
    period.id,
    period.year,
    period.month,
    period.title,
    period.instructions,
    period.submission_deadline,
    period.status,

    coalesce(
      submission.status,
      'draft'
    ),
    submission.submitted_at,
    submission.last_saved_at,
    coalesce(
      submission.available_count,
      0
    ),
    coalesce(
      submission.unavailable_count,
      0
    ),

    slot.id,
    slot.shift_date,
    slot.weekday_number,
    slot.weekday_name,
    slot.start_time,
    slot.end_time,
    slot.ends_next_day,
    slot.schedule_type,
    slot.holiday_name,
    slot.is_premium,
    slot.sort_order,

    availability.availability_status,
    availability.note,
    availability.updated_at

  from public.availability_periods period

  join public.availability_shift_slots slot
    on slot.period_id =
      period.id

  left join public.availability_submissions submission
    on submission.period_id =
      period.id
    and submission.user_id =
      current_user_id

  left join public.dispatcher_availability availability
    on availability.period_id =
      period.id
    and availability.shift_slot_id =
      slot.id
    and availability.user_id =
      current_user_id

  where period.id =
    open_period_id

  order by
    slot.shift_date,
    slot.sort_order;
end;
$$;


ALTER FUNCTION "public"."get_my_open_availability"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_my_pending_operational_push_notifications"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor uuid := auth.uid();
begin
  if actor is null then raise exception 'not authenticated'; end if;

  return coalesce((
    select jsonb_agg(n.id order by n.created_at)
    from public.notifications n
    where n.created_by = actor
      and n.source in ('dynamic_schedule_edit','shift_swap')
      and coalesce((n.data->>'pushPending')::boolean,false) = true
      and n.created_at >= now() - interval '15 minutes'
  ), '[]'::jsonb);
end;
$$;


ALTER FUNCTION "public"."get_my_pending_operational_push_notifications"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_my_permissions"() RETURNS "text"[]
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select coalesce(
    array_agg(
      up.permission_key
      order by p.sort_order, up.permission_key
    ),
    array[]::text[]
  )
  from public.user_permissions up
  join public.permissions p
    on p.permission_key = up.permission_key
  where up.user_id = auth.uid();
$$;


ALTER FUNCTION "public"."get_my_permissions"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_payroll_statistics"("requested_years" integer[] DEFAULT NULL::integer[], "requested_months" integer[] DEFAULT NULL::integer[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  current_user_id uuid := auth.uid();
  current_permissions text[];
  dispatchers_json jsonb := '[]'::jsonb;
  drivers_json jsonb := '[]'::jsonb;
  morning_drivers_json jsonb := '[]'::jsonb;
  projected_dispatcher_pay numeric := 0;
  projected_driver_pay numeric := 0;
  projected_morning_driver_pay numeric := 0;
begin
  if current_user_id is null then raise exception 'not authenticated'; end if;
  current_permissions := coalesce(public.get_my_permissions(), array[]::text[]);
  if not ('payroll.view' = any(current_permissions)) then raise exception 'payroll view permission required'; end if;

  with dispatcher_totals as (
    select profile.id user_id, profile.display_name, profile.schedule_name, profile.hourly_rate,
      round(coalesce(sum(case when schedule_period.id is not null then extract(epoch from (schedule_shift.ends_at-schedule_shift.starts_at))/3600.0 else 0 end),0)::numeric,2) scheduled_hours,
      round(coalesce(sum(case when schedule_period.id is not null and schedule_shift.is_premium then extract(epoch from (schedule_shift.ends_at-schedule_shift.starts_at))/3600.0 else 0 end),0)::numeric,2) premium_hours
    from public.profiles profile
    left join public.schedule_shifts schedule_shift on schedule_shift.assigned_user_id=profile.id
    left join public.schedule_periods schedule_period on schedule_period.id=schedule_shift.period_id
      and schedule_period.status::text in ('published','archived')
      and (requested_years is null or cardinality(requested_years)=0 or schedule_period.year=any(requested_years))
      and (requested_months is null or cardinality(requested_months)=0 or schedule_period.month=any(requested_months))
    where profile.role='dispatcher'::public.user_role
      and (profile.is_active=true or schedule_period.id is not null)
    group by profile.id,profile.display_name,profile.schedule_name,profile.hourly_rate
  ), rows as (
    select *, case when hourly_rate is null then null else round(hourly_rate*(scheduled_hours+premium_hours),2) end projected_pay from dispatcher_totals
  )
  select coalesce(jsonb_agg(jsonb_build_object('userId',user_id,'displayName',display_name,'scheduleName',schedule_name,'hourlyRate',hourly_rate,'scheduledHours',scheduled_hours,'premiumHours',premium_hours,'projectedPay',projected_pay) order by coalesce(schedule_name,display_name)),'[]'::jsonb), coalesce(sum(projected_pay),0)
  into dispatchers_json,projected_dispatcher_pay from rows;

  with driver_totals as (
    select profile.id user_id, profile.display_name, profile.schedule_name, profile.daily_duty_rate,
      count(schedule_day.id) filter(where schedule_period.id is not null)::integer total_duties
    from public.profiles profile
    left join public.driver_schedule_days schedule_day on schedule_day.assigned_user_id=profile.id
    left join public.driver_schedule_periods schedule_period on schedule_period.id=schedule_day.period_id
      and schedule_period.status::text in ('published','archived')
      and (requested_years is null or cardinality(requested_years)=0 or schedule_period.year=any(requested_years))
      and (requested_months is null or cardinality(requested_months)=0 or schedule_period.month=any(requested_months))
    where profile.role='on_call'::public.user_role
      and (profile.is_active=true or schedule_period.id is not null)
    group by profile.id,profile.display_name,profile.schedule_name,profile.daily_duty_rate
  ), rows as (
    select *,case when daily_duty_rate is null then null else round(daily_duty_rate*total_duties,2) end projected_pay from driver_totals
  )
  select coalesce(jsonb_agg(jsonb_build_object('userId',user_id,'displayName',display_name,'scheduleName',schedule_name,'dailyDutyRate',daily_duty_rate,'totalDuties',total_duties,'projectedPay',projected_pay) order by coalesce(schedule_name,display_name)),'[]'::jsonb),coalesce(sum(projected_pay),0)
  into drivers_json,projected_driver_pay from rows;

  with morning_totals as (
    select profile.id user_id, profile.display_name, profile.schedule_name, profile.morning_shift_rate,
      count(assignment.id) filter(where schedule_period.id is not null)::integer total_shifts
    from public.profiles profile
    left join public.morning_driver_schedule_assignments assignment on assignment.assigned_user_id=profile.id
    left join public.morning_driver_schedule_periods schedule_period on schedule_period.id=assignment.schedule_period_id
      and schedule_period.status::text in ('published','archived')
      and (requested_years is null or cardinality(requested_years)=0 or schedule_period.year=any(requested_years))
      and (requested_months is null or cardinality(requested_months)=0 or schedule_period.month=any(requested_months))
    where profile.role='morning_driver'::public.user_role
      and (profile.is_active=true or schedule_period.id is not null)
    group by profile.id,profile.display_name,profile.schedule_name,profile.morning_shift_rate
  ), rows as (
    select *,case when morning_shift_rate is null then null else round(morning_shift_rate*total_shifts,2) end projected_pay from morning_totals
  )
  select coalesce(jsonb_agg(jsonb_build_object('userId',user_id,'displayName',display_name,'scheduleName',schedule_name,'shiftRate',morning_shift_rate,'totalShifts',total_shifts,'projectedPay',projected_pay) order by coalesce(schedule_name,display_name)),'[]'::jsonb),coalesce(sum(projected_pay),0)
  into morning_drivers_json,projected_morning_driver_pay from rows;

  return jsonb_build_object('dispatchers',dispatchers_json,'drivers',drivers_json,'morningDrivers',morning_drivers_json,'projectedDispatcherPay',projected_dispatcher_pay,'projectedDriverPay',projected_driver_pay,'projectedMorningDriverPay',projected_morning_driver_pay,'actualPayAvailable',false,'attendanceAvailable',false);
end;
$$;


ALTER FUNCTION "public"."get_payroll_statistics"("requested_years" integer[], "requested_months" integer[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_permission_admin_catalog"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_actor uuid := auth.uid();
begin
  if v_actor is null then
    raise exception 'not authenticated';
  end if;

  if not exists (
    select 1 from public.user_permissions up
    where up.user_id = v_actor and up.permission_key = 'users.manage'
  ) then
    raise exception 'not allowed';
  end if;

  return jsonb_build_object(
    'profiles', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', pp.id,
        'code', pp.code,
        'name', pp.name,
        'description', pp.description,
        'isSystem', pp.is_system,
        'permissions', coalesce((
          select jsonb_agg(ppp.permission_key order by ppp.permission_key)
          from public.permission_profile_permissions ppp
          where ppp.profile_id = pp.id
        ), '[]'::jsonb)
      ) order by case pp.code
        when 'employee' then 1
        when 'manager' then 2
        when 'system_admin' then 3
        when 'viewer' then 4
        else 5 end, pp.name)
      from public.permission_profiles pp
      where pp.is_active = true
    ), '[]'::jsonb),
    'jobTypes', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', jt.id,
        'name', jt.name,
        'code', jt.code
      ) order by jt.name)
      from public.job_types jt
      where jt.is_active = true
    ), '[]'::jsonb)
  );
end;
$$;


ALTER FUNCTION "public"."get_permission_admin_catalog"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_schedule_draft_edit_context"("requested_schedule_period_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  current_user_id uuid := auth.uid();
  target_period public.schedule_periods%rowtype;
  current_permissions text[];
begin
  if current_user_id is null then
    raise exception 'not authenticated';
  end if;

  current_permissions :=
    coalesce(
      public.get_my_permissions(),
      array[]::text[]
    );

  if not (
    'schedule.edit' =
      any(current_permissions)
  ) then
    raise exception 'not allowed';
  end if;

  select *
  into target_period
  from public.schedule_periods period
  where period.id =
    requested_schedule_period_id;

  if not found then
    raise exception
      'schedule period not found';
  end if;

  if target_period.status not in (
    'draft'::public.schedule_period_status,
    'scheduling'::public.schedule_period_status
  ) then
    raise exception
      'schedule period is not editable as draft';
  end if;

  return jsonb_build_object(
    'periodId',
      target_period.id,

    'dispatchers',
      coalesce(
        (
          select jsonb_agg(
            jsonb_build_object(
              'id',
                profile.id,
              'displayName',
                profile.display_name,
              'scheduleName',
                profile.schedule_name
            )
            order by
              coalesce(
                profile.schedule_name,
                profile.display_name
              )
          )
          from public.profiles profile
          where profile.is_active = true
            and profile.role::text = 'dispatcher'
        ),
        '[]'::jsonb
      ),

    'shifts',
      coalesce(
        (
          select jsonb_agg(
            jsonb_build_object(
              'scheduleShiftId',
                schedule_shift.id,

              'availabilityShiftSlotId',
                schedule_shift.availability_shift_slot_id,

              /*
               * Count only availability the dispatcher explicitly chose.
               * Auto-completed "available" entries are not a declaration.
               */
              'availableCount',
                (
                  select count(*)::integer
                  from public.dispatcher_availability availability
                  join public.profiles profile
                    on profile.id =
                      availability.user_id
                   and profile.is_active = true
                   and profile.role::text =
                     'dispatcher'
                  where availability.period_id =
                      target_period.availability_period_id
                    and availability.shift_slot_id =
                      schedule_shift.availability_shift_slot_id
                    and availability.availability_status =
                      'available'
                    and coalesce(
                      availability.is_auto_completed,
                      false
                    ) = false
                ),

              'totalDispatchers',
                (
                  select count(*)::integer
                  from public.profiles profile
                  where profile.is_active = true
                    and profile.role::text =
                      'dispatcher'
                ),

              'candidates',
                coalesce(
                  (
                    select jsonb_agg(
                      jsonb_build_object(
                        'userId',
                          profile.id,
                        'displayName',
                          profile.display_name,
                        'scheduleName',
                          profile.schedule_name,

                        /*
                         * isAvailable means an explicit declaration.
                         */
                        'isAvailable',
                          coalesce(
                            availability.availability_status =
                              'available'
                            and not coalesce(
                              availability.is_auto_completed,
                              false
                            ),
                            false
                          ),

                        'availabilityStatus',
                          availability.availability_status,

                        'isAutoCompleted',
                          coalesce(
                            availability.is_auto_completed,
                            false
                          )
                      )
                      order by
                        case
                          when availability.availability_status =
                                 'available'
                            and not coalesce(
                              availability.is_auto_completed,
                              false
                            )
                          then 1

                          when availability.availability_status =
                                 'unavailable'
                          then 2

                          else 3
                        end,

                        coalesce(
                          profile.schedule_name,
                          profile.display_name
                        )
                    )
                    from public.profiles profile
                    left join public.dispatcher_availability availability
                      on availability.user_id =
                        profile.id
                     and availability.period_id =
                        target_period.availability_period_id
                     and availability.shift_slot_id =
                        schedule_shift.availability_shift_slot_id
                    where profile.is_active = true
                      and profile.role::text =
                        'dispatcher'
                  ),
                  '[]'::jsonb
                )
            )
            order by
              schedule_shift.starts_at
          )
          from public.schedule_shifts schedule_shift
          where schedule_shift.period_id =
            target_period.id
        ),
        '[]'::jsonb
      )
  );
end;
$$;


ALTER FUNCTION "public"."get_schedule_draft_edit_context"("requested_schedule_period_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_schedule_import_users"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  current_user_id uuid;

  current_permissions text[];

  dispatcher_users jsonb;

  on_call_users jsonb;

  morning_driver_users jsonb;

  aliases jsonb;
begin
  current_user_id :=
    auth.uid();

  if current_user_id is null then
    raise exception
      'not authenticated';
  end if;

  if not exists (
    select 1
    from public.profiles profile_row
    where profile_row.id =
      current_user_id
      and profile_row.is_active = true
  ) then
    raise exception
      'user not active';
  end if;

  current_permissions :=
    coalesce(
      public.get_my_permissions(),
      array[]::text[]
    );

  if not (
    'driver_availability.manage' =
      any(current_permissions)
    or
    'morning_driver_availability.manage' =
      any(current_permissions)
    or
    'morning_driver_schedule.edit' =
      any(current_permissions)
    or
    'schedule.edit' =
      any(current_permissions)
    or
    'users.manage' =
      any(current_permissions)
  ) then
    raise exception
      'not allowed';
  end if;

  /*
   * מוקדנים פעילים.
   */
  select
    coalesce(
      jsonb_agg(
        jsonb_build_object(
          'id',
            profile_row.id,

          'displayName',
            profile_row.display_name,

          'scheduleName',
            profile_row.schedule_name,

          'email',
            profile_row.email,

          'role',
            profile_row.role,

          'isActive',
            profile_row.is_active
        )
        order by
          coalesce(
            profile_row.schedule_name,
            profile_row.display_name,
            profile_row.email
          )
      ),
      '[]'::jsonb
    )
  into
    dispatcher_users
  from public.profiles profile_row
  where profile_row.is_active = true
    and profile_row.role =
      'dispatcher'::public.user_role;

  /*
   * כוננים טכניים פעילים.
   */
  select
    coalesce(
      jsonb_agg(
        jsonb_build_object(
          'id',
            profile_row.id,

          'displayName',
            profile_row.display_name,

          'scheduleName',
            profile_row.schedule_name,

          'email',
            profile_row.email,

          'role',
            profile_row.role,

          'isActive',
            profile_row.is_active
        )
        order by
          coalesce(
            profile_row.schedule_name,
            profile_row.display_name,
            profile_row.email
          )
      ),
      '[]'::jsonb
    )
  into
    on_call_users
  from public.profiles profile_row
  where profile_row.is_active = true
    and profile_row.role =
      'on_call'::public.user_role;

  /*
   * כונני בוקר פעילים.
   */
  select
    coalesce(
      jsonb_agg(
        jsonb_build_object(
          'id',
            profile_row.id,

          'displayName',
            profile_row.display_name,

          'scheduleName',
            profile_row.schedule_name,

          'email',
            profile_row.email,

          'role',
            profile_row.role,

          'isActive',
            profile_row.is_active
        )
        order by
          coalesce(
            profile_row.schedule_name,
            profile_row.display_name,
            profile_row.email
          )
      ),
      '[]'::jsonb
    )
  into
    morning_driver_users
  from public.profiles profile_row
  where profile_row.is_active = true
    and profile_row.role =
      'morning_driver'::public.user_role;

  /*
   * התאמות שמות שמורות מכל סוגי המשתמשים.
   */
  select
    coalesce(
      jsonb_agg(
        jsonb_build_object(
          'id',
            alias_row.id,

          'sourceName',
            alias_row.source_name,

          'normalizedSourceName',
            alias_row.normalized_source_name,

          'userId',
            alias_row.user_id,

          'userType',
            alias_row.user_type
        )
        order by
          alias_row.user_type,
          alias_row.normalized_source_name
      ),
      '[]'::jsonb
    )
  into
    aliases
  from public.schedule_import_name_aliases alias_row;

  return jsonb_build_object(
    'dispatchers',
      dispatcher_users,

    'onCallDrivers',
      on_call_users,

    'morningDrivers',
      morning_driver_users,

    'aliases',
      aliases
  );
end;
$$;


ALTER FUNCTION "public"."get_schedule_import_users"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_shift_swap_create_options"() RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with date_bounds as (
    select
      date_trunc(
        'month',
        (now() at time zone 'Asia/Jerusalem')::date
      )::date as current_month_start,
      (
        date_trunc(
          'month',
          (now() at time zone 'Asia/Jerusalem')::date
        ) + interval '2 months'
      )::date as month_after_next_start
  ),
  eligible_periods as (
    select p.*
    from public.schedule_periods p
    cross join date_bounds b
    where p.status = 'published'
      and make_date(p.year, p.month, 1) >= b.current_month_start
      and make_date(p.year, p.month, 1) < b.month_after_next_start
  ),
  eligible_shifts as (
    select s.*
    from public.schedule_shifts s
    join eligible_periods p on p.id = s.period_id
    where s.starts_at > now()
  )
  select jsonb_build_object(
    'myShifts', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'id', s.id,
          'periodId', s.period_id,
          'shiftDate', s.shift_date,
          'startsAt', s.starts_at,
          'endsAt', s.ends_at,
          'shiftCode', s.shift_code,
          'scheduleType', s.schedule_type,
          'isPremium', s.is_premium,
          'holidayName', s.holiday_name,
          'periodYear', p.year,
          'periodMonth', p.month
        )
        order by s.starts_at
      )
      from eligible_shifts s
      join eligible_periods p on p.id = s.period_id
      where s.assigned_user_id = auth.uid()
    ), '[]'::jsonb),
    'dispatchers', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'id', profile.id,
          'displayName', profile.display_name,
          'scheduleName', profile.schedule_name
        )
        order by coalesce(profile.schedule_name, profile.display_name)
      )
      from public.profiles profile
      where profile.is_active = true
        and profile.role::text = 'dispatcher'
        and profile.id <> auth.uid()
    ), '[]'::jsonb),
    'counterpartyShifts', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'id', s.id,
          'periodId', s.period_id,
          'assignedUserId', s.assigned_user_id,
          'shiftDate', s.shift_date,
          'startsAt', s.starts_at,
          'endsAt', s.ends_at,
          'shiftCode', s.shift_code,
          'scheduleType', s.schedule_type,
          'isPremium', s.is_premium,
          'holidayName', s.holiday_name,
          'periodYear', p.year,
          'periodMonth', p.month
        )
        order by s.starts_at
      )
      from eligible_shifts s
      join eligible_periods p on p.id = s.period_id
      where s.assigned_user_id is not null
        and s.assigned_user_id <> auth.uid()
    ), '[]'::jsonb)
  )
  where auth.uid() is not null
    and public.current_user_has_permission('shift_swaps.view');
$$;


ALTER FUNCTION "public"."get_shift_swap_create_options"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_shift_swap_requests"() RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'id', r.id,
        'swapType', r.swap_type,
        'status', r.status,
        'requesterUserId', r.requester_user_id,
        'requesterName', requester.display_name,
        'counterpartyUserId', r.counterparty_user_id,
        'counterpartyName', counterparty.display_name,
        'requesterShiftId', r.requester_shift_id,
        'requesterShiftDate', requester_shift.shift_date,
        'requesterStartsAt', requester_shift.starts_at,
        'requesterEndsAt', requester_shift.ends_at,
        'counterpartyShiftId', r.counterparty_shift_id,
        'counterpartyShiftDate', counterparty_shift.shift_date,
        'counterpartyStartsAt', counterparty_shift.starts_at,
        'counterpartyEndsAt', counterparty_shift.ends_at,
        'rejectionReason', r.rejection_reason,
        'counterpartyRespondedAt', r.counterparty_responded_at,
        'managerReviewedAt', r.manager_reviewed_at,
        'managerUserId', r.manager_user_id,
        'createdAt', r.created_at,
        'updatedAt', r.updated_at
      )
      order by r.created_at desc
    ),
    '[]'::jsonb
  )
  from public.shift_swap_requests r
  join public.profiles requester
    on requester.id = r.requester_user_id
  join public.profiles counterparty
    on counterparty.id = r.counterparty_user_id
  join public.schedule_shifts requester_shift
    on requester_shift.id = r.requester_shift_id
  left join public.schedule_shifts counterparty_shift
    on counterparty_shift.id = r.counterparty_shift_id
  where
    auth.uid() is not null
    and (
      r.requester_user_id = auth.uid()
      or r.counterparty_user_id = auth.uid()
      or public.current_user_has_permission('shift_swaps.approve')
    );
$$;


ALTER FUNCTION "public"."get_shift_swap_requests"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_shift_time_distribution_statistics"("requested_year" integer DEFAULT NULL::integer, "requested_month" integer DEFAULT NULL::integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  current_user_id uuid := auth.uid();
  current_permissions text[];
  dispatcher_rows jsonb;
  morning_driver_rows jsonb;
begin
  if current_user_id is null then
    raise exception 'not authenticated';
  end if;

  if not exists (
    select 1
    from public.profiles profile_row
    where profile_row.id = current_user_id
      and profile_row.is_active = true
  ) then
    raise exception 'user not active';
  end if;

  current_permissions :=
    coalesce(public.get_my_permissions(), array[]::text[]);

  if not (
    'statistics.view' = any(current_permissions)
    or 'users.manage' = any(current_permissions)
  ) then
    raise exception 'not allowed';
  end if;

  if requested_year is not null
    and (requested_year < 2020 or requested_year > 2100)
  then
    raise exception 'statistics year is invalid';
  end if;

  if requested_month is not null
    and (requested_month < 1 or requested_month > 12)
  then
    raise exception 'statistics month is invalid';
  end if;

  if requested_month is not null
    and requested_year is null
  then
    raise exception 'statistics year is required when month is selected';
  end if;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'userId', row_data.user_id,
        'displayName', row_data.display_name,
        'scheduleName', row_data.schedule_name,
        'shiftTime', row_data.shift_time,
        'shiftCount', row_data.shift_count
      )
      order by row_data.display_name, row_data.shift_time
    ),
    '[]'::jsonb
  )
  into dispatcher_rows
  from (
    select
      profile_row.id as user_id,
      profile_row.display_name,
      profile_row.schedule_name,
      concat(
        to_char(
          (schedule_shift.starts_at at time zone 'Asia/Jerusalem')::time,
          'HH24:MI'
        ),
        '–',
        to_char(
          (schedule_shift.ends_at at time zone 'Asia/Jerusalem')::time,
          'HH24:MI'
        )
      ) as shift_time,
      count(*)::integer as shift_count
    from public.schedule_shifts schedule_shift
    join public.schedule_periods schedule_period
      on schedule_period.id = schedule_shift.period_id
    join public.profiles profile_row
      on profile_row.id = schedule_shift.assigned_user_id
    where profile_row.role = 'dispatcher'
      and schedule_shift.assigned_user_id is not null
      and schedule_period.status in (
        'published'::public.schedule_period_status,
        'archived'::public.schedule_period_status
      )
      and (
        requested_year is null
        or schedule_period.year = requested_year
      )
      and (
        requested_month is null
        or schedule_period.month = requested_month
      )
    group by
      profile_row.id,
      profile_row.display_name,
      profile_row.schedule_name,
      shift_time
  ) row_data;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'userId', row_data.user_id,
        'displayName', row_data.display_name,
        'scheduleName', row_data.schedule_name,
        'shiftTime', row_data.shift_time,
        'shiftCount', row_data.shift_count
      )
      order by row_data.display_name, row_data.shift_time
    ),
    '[]'::jsonb
  )
  into morning_driver_rows
  from (
    select
      profile_row.id as user_id,
      profile_row.display_name,
      profile_row.schedule_name,
      concat(
        to_char(
          coalesce(
            assignment.scheduled_start_time,
            shift_item.start_time
          ),
          'HH24:MI'
        ),
        '–',
        to_char(
          coalesce(
            assignment.scheduled_end_time,
            shift_item.end_time
          ),
          'HH24:MI'
        )
      ) as shift_time,
      count(*)::integer as shift_count
    from public.morning_driver_schedule_assignments assignment
    join public.morning_driver_schedule_periods schedule_period
      on schedule_period.id = assignment.schedule_period_id
    join public.morning_driver_availability_shifts shift_item
      on shift_item.id = assignment.availability_shift_id
    join public.profiles profile_row
      on profile_row.id = assignment.assigned_user_id
    where profile_row.role = 'morning_driver'
      and assignment.assigned_user_id is not null
      and schedule_period.status::text in (
        'published',
        'archived'
      )
      and (
        requested_year is null
        or schedule_period.year = requested_year
      )
      and (
        requested_month is null
        or schedule_period.month = requested_month
      )
    group by
      profile_row.id,
      profile_row.display_name,
      profile_row.schedule_name,
      shift_time
  ) row_data;

  return jsonb_build_object(
    'dispatchers', dispatcher_rows,
    'morningDrivers', morning_driver_rows,
    'generatedAt', now()
  );
end;
$$;


ALTER FUNCTION "public"."get_shift_time_distribution_statistics"("requested_year" integer, "requested_month" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_statistics_dashboard"("requested_year" integer DEFAULT NULL::integer, "requested_month" integer DEFAULT NULL::integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  current_user_id uuid;
  current_permissions text[];

  dispatcher_statistics jsonb;
  driver_statistics jsonb;
  monthly_statistics jsonb;

  dispatcher_monthly_breakdown jsonb;
  driver_monthly_breakdown jsonb;
  summary_statistics jsonb;

  selected_year integer;
  selected_month integer;
begin
  current_user_id :=
    auth.uid();

  if current_user_id is null then
    raise exception
      'not authenticated';
  end if;

  if not exists (
    select 1
    from public.profiles profile_row
    where profile_row.id =
      current_user_id
      and profile_row.is_active = true
  ) then
    raise exception
      'user not active';
  end if;

  current_permissions :=
    coalesce(
      public.get_my_permissions(),
      array[]::text[]
    );

  if not (
    'statistics.view' =
      any(current_permissions)
    or
    'users.manage' =
      any(current_permissions)
  ) then
    raise exception
      'not allowed';
  end if;

  if (
    requested_month is not null
    and (
      requested_month < 1
      or requested_month > 12
    )
  ) then
    raise exception
      'statistics month is invalid';
  end if;

  if (
    requested_year is not null
    and (
      requested_year < 2020
      or requested_year > 2100
    )
  ) then
    raise exception
      'statistics year is invalid';
  end if;

  if (
    requested_month is not null
    and requested_year is null
  ) then
    raise exception
      'statistics year is required when month is selected';
  end if;

  selected_year :=
    requested_year;

  selected_month :=
    requested_month;

  /*
   * סטטיסטיקות מוקדנים לתקופה שנבחרה.
   */
  select
    coalesce(
      jsonb_agg(
        jsonb_build_object(
          'userId',
            dispatcher_row.user_id,

          'displayName',
            dispatcher_row.display_name,

          'scheduleName',
            dispatcher_row.schedule_name,

          'totalShifts',
            dispatcher_row.total_shifts,

          'premiumShifts',
            dispatcher_row.premium_shifts,

          'regularShifts',
            dispatcher_row.regular_shifts,

          'weekdayShifts',
            dispatcher_row.weekday_shifts,

          'fridayShifts',
            dispatcher_row.friday_shifts,

          'saturdayShifts',
            dispatcher_row.saturday_shifts,

          'holidayShifts',
            dispatcher_row.holiday_shifts,

          'nightShifts',
            dispatcher_row.night_shifts,

          'importedShifts',
            dispatcher_row.imported_shifts
        )
        order by
          dispatcher_row.total_shifts desc,
          dispatcher_row.display_name
      ),
      '[]'::jsonb
    )
  into dispatcher_statistics
  from (
    select
      profile_row.id
        as user_id,

      profile_row.display_name,

      profile_row.schedule_name,

      count(schedule_shift.id)::integer
        as total_shifts,

      count(schedule_shift.id) filter (
        where schedule_shift.is_premium = true
      )::integer
        as premium_shifts,

      count(schedule_shift.id) filter (
        where schedule_shift.is_premium = false
      )::integer
        as regular_shifts,

      count(schedule_shift.id) filter (
        where schedule_shift.schedule_type =
          'weekday'::public.schedule_type
      )::integer
        as weekday_shifts,

      count(schedule_shift.id) filter (
        where schedule_shift.schedule_type =
          'friday'::public.schedule_type
      )::integer
        as friday_shifts,

      count(schedule_shift.id) filter (
        where schedule_shift.schedule_type =
          'saturday'::public.schedule_type
      )::integer
        as saturday_shifts,

      count(schedule_shift.id) filter (
        where schedule_shift.schedule_type in (
          'holiday_eve'::public.schedule_type,
          'holiday_full'::public.schedule_type,
          'holiday_end'::public.schedule_type,
          'chol_hamoed'::public.schedule_type
        )
      )::integer
        as holiday_shifts,

      count(schedule_shift.id) filter (
        where
          (
            schedule_shift.starts_at
              at time zone 'Asia/Jerusalem'
          )::time >= time '22:00'
          or
          (
            schedule_shift.starts_at
              at time zone 'Asia/Jerusalem'
          )::time < time '06:00'
      )::integer
        as night_shifts,

      count(schedule_shift.id) filter (
        where schedule_shift.assignment_source::text =
          'import'
      )::integer
        as imported_shifts

    from public.profiles profile_row

    join public.schedule_shifts schedule_shift
      on schedule_shift.assigned_user_id =
        profile_row.id

    join public.schedule_periods schedule_period
      on schedule_period.id =
        schedule_shift.period_id

    where
      profile_row.role =
        'dispatcher'

      and (
        selected_year is null
        or schedule_period.year =
          selected_year
      )

      and (
        selected_month is null
        or schedule_period.month =
          selected_month
      )

      and schedule_period.status in (
        'published'::public.schedule_period_status,
        'archived'::public.schedule_period_status
      )

    group by
      profile_row.id,
      profile_row.display_name,
      profile_row.schedule_name
  ) dispatcher_row;

  /*
   * סטטיסטיקות כוננים לתקופה שנבחרה.
   */
  select
    coalesce(
      jsonb_agg(
        jsonb_build_object(
          'userId',
            driver_row.user_id,

          'displayName',
            driver_row.display_name,

          'scheduleName',
            driver_row.schedule_name,

          'totalDuties',
            driver_row.total_duties,

          'weekdayDuties',
            driver_row.weekday_duties,

          'fridayDuties',
            driver_row.friday_duties,

          'saturdayDuties',
            driver_row.saturday_duties,

          'weekendDuties',
            driver_row.weekend_duties,

          'holidayDuties',
            driver_row.holiday_duties,

          'importedDuties',
            driver_row.imported_duties
        )
        order by
          driver_row.total_duties desc,
          driver_row.display_name
      ),
      '[]'::jsonb
    )
  into driver_statistics
  from (
    select
      profile_row.id
        as user_id,

      profile_row.display_name,

      profile_row.schedule_name,

      count(driver_day.id)::integer
        as total_duties,

      count(driver_day.id) filter (
        where driver_day.weekday_number
          between 0 and 4
      )::integer
        as weekday_duties,

      count(driver_day.id) filter (
        where driver_day.weekday_number = 5
      )::integer
        as friday_duties,

      count(driver_day.id) filter (
        where driver_day.weekday_number = 6
      )::integer
        as saturday_duties,

      count(driver_day.id) filter (
        where driver_day.weekday_number
          in (5, 6)
      )::integer
        as weekend_duties,

      count(driver_day.id) filter (
        where exists (
          select 1
          from public.schedule_periods schedule_period_for_day
          join public.schedule_shifts holiday_shift
            on holiday_shift.period_id =
              schedule_period_for_day.id
          where holiday_shift.shift_date =
            driver_day.duty_date
            and holiday_shift.schedule_type in (
              'holiday_eve'::public.schedule_type,
              'holiday_full'::public.schedule_type,
              'holiday_end'::public.schedule_type,
              'chol_hamoed'::public.schedule_type
            )
        )
      )::integer
        as holiday_duties,

      count(driver_day.id) filter (
        where driver_day.assignment_source::text =
          'import'
      )::integer
        as imported_duties

    from public.profiles profile_row

    join public.driver_schedule_days driver_day
      on driver_day.assigned_user_id =
        profile_row.id

    join public.driver_schedule_periods driver_period
      on driver_period.id =
        driver_day.period_id

    where
      profile_row.role =
        'on_call'

      and (
        selected_year is null
        or driver_period.year =
          selected_year
      )

      and (
        selected_month is null
        or driver_period.month =
          selected_month
      )

      and driver_period.status in (
        'published'::public.driver_schedule_period_status,
        'archived'::public.driver_schedule_period_status
      )

    group by
      profile_row.id,
      profile_row.display_name,
      profile_row.schedule_name
  ) driver_row;

  /*
   * סיכום לפי חודש.
   */
  select
    coalesce(
      jsonb_agg(
        jsonb_build_object(
          'year',
            monthly_row.year,

          'month',
            monthly_row.month,

          'dispatcherShiftCount',
            monthly_row.dispatcher_shift_count,

          'driverDutyCount',
            monthly_row.driver_duty_count,

          'dispatcherPeriodStatus',
            monthly_row.dispatcher_period_status,

          'driverPeriodStatus',
            monthly_row.driver_period_status
        )
        order by
          monthly_row.year desc,
          monthly_row.month desc
      ),
      '[]'::jsonb
    )
  into monthly_statistics
  from (
    select
      coalesce(
        schedule_period.year,
        driver_period.year
      ) as year,

      coalesce(
        schedule_period.month,
        driver_period.month
      ) as month,

      schedule_period.status::text
        as dispatcher_period_status,

      driver_period.status::text
        as driver_period_status,

      coalesce(
        schedule_count.shift_count,
        0
      )::integer
        as dispatcher_shift_count,

      coalesce(
        driver_count.duty_count,
        0
      )::integer
        as driver_duty_count

    from public.schedule_periods schedule_period

    full join public.driver_schedule_periods driver_period
      on driver_period.year =
        schedule_period.year
      and driver_period.month =
        schedule_period.month

    left join lateral (
      select
        count(*)::integer
          as shift_count
      from public.schedule_shifts schedule_shift
      where schedule_shift.period_id =
        schedule_period.id
    ) schedule_count
      on true

    left join lateral (
      select
        count(*)::integer
          as duty_count
      from public.driver_schedule_days driver_day
      where driver_day.period_id =
        driver_period.id
    ) driver_count
      on true

    where
      (
        selected_year is null
        or coalesce(
          schedule_period.year,
          driver_period.year
        ) = selected_year
      )

      and (
        selected_month is null
        or coalesce(
          schedule_period.month,
          driver_period.month
        ) = selected_month
      )

      and (
        schedule_period.status in (
          'published'::public.schedule_period_status,
          'archived'::public.schedule_period_status
        )
        or
        driver_period.status in (
          'published'::public.driver_schedule_period_status,
          'archived'::public.driver_schedule_period_status
        )
      )
  ) monthly_row;

  /*
   * פירוט מוקדנים לפי חודש.
   */
  select
    coalesce(
      jsonb_agg(
        jsonb_build_object(
          'userId',
            dispatcher_month_row.user_id,

          'displayName',
            dispatcher_month_row.display_name,

          'scheduleName',
            dispatcher_month_row.schedule_name,

          'year',
            dispatcher_month_row.year,

          'month',
            dispatcher_month_row.month,

          'totalShifts',
            dispatcher_month_row.total_shifts,

          'premiumShifts',
            dispatcher_month_row.premium_shifts,

          'regularShifts',
            dispatcher_month_row.regular_shifts,

          'weekdayShifts',
            dispatcher_month_row.weekday_shifts,

          'fridayShifts',
            dispatcher_month_row.friday_shifts,

          'saturdayShifts',
            dispatcher_month_row.saturday_shifts,

          'holidayShifts',
            dispatcher_month_row.holiday_shifts,

          'nightShifts',
            dispatcher_month_row.night_shifts
        )
        order by
          dispatcher_month_row.year,
          dispatcher_month_row.month,
          dispatcher_month_row.display_name
      ),
      '[]'::jsonb
    )
  into dispatcher_monthly_breakdown
  from (
    select
      profile_row.id
        as user_id,

      profile_row.display_name,

      profile_row.schedule_name,

      schedule_period.year,

      schedule_period.month,

      count(schedule_shift.id)::integer
        as total_shifts,

      count(schedule_shift.id) filter (
        where schedule_shift.is_premium = true
      )::integer
        as premium_shifts,

      count(schedule_shift.id) filter (
        where schedule_shift.is_premium = false
      )::integer
        as regular_shifts,

      count(schedule_shift.id) filter (
        where schedule_shift.schedule_type =
          'weekday'::public.schedule_type
      )::integer
        as weekday_shifts,

      count(schedule_shift.id) filter (
        where schedule_shift.schedule_type =
          'friday'::public.schedule_type
      )::integer
        as friday_shifts,

      count(schedule_shift.id) filter (
        where schedule_shift.schedule_type =
          'saturday'::public.schedule_type
      )::integer
        as saturday_shifts,

      count(schedule_shift.id) filter (
        where schedule_shift.schedule_type in (
          'holiday_eve'::public.schedule_type,
          'holiday_full'::public.schedule_type,
          'holiday_end'::public.schedule_type,
          'chol_hamoed'::public.schedule_type
        )
      )::integer
        as holiday_shifts,

      count(schedule_shift.id) filter (
        where
          (
            schedule_shift.starts_at
              at time zone 'Asia/Jerusalem'
          )::time >= time '22:00'
          or
          (
            schedule_shift.starts_at
              at time zone 'Asia/Jerusalem'
          )::time < time '06:00'
      )::integer
        as night_shifts

    from public.profiles profile_row

    join public.schedule_shifts schedule_shift
      on schedule_shift.assigned_user_id =
        profile_row.id

    join public.schedule_periods schedule_period
      on schedule_period.id =
        schedule_shift.period_id

    where
      profile_row.role =
        'dispatcher'

      and (
        selected_year is null
        or schedule_period.year =
          selected_year
      )

      and (
        selected_month is null
        or schedule_period.month =
          selected_month
      )

      and schedule_period.status in (
        'published'::public.schedule_period_status,
        'archived'::public.schedule_period_status
      )

    group by
      profile_row.id,
      profile_row.display_name,
      profile_row.schedule_name,
      schedule_period.year,
      schedule_period.month
  ) dispatcher_month_row;

  /*
   * פירוט כוננים לפי חודש.
   */
  select
    coalesce(
      jsonb_agg(
        jsonb_build_object(
          'userId',
            driver_month_row.user_id,

          'displayName',
            driver_month_row.display_name,

          'scheduleName',
            driver_month_row.schedule_name,

          'year',
            driver_month_row.year,

          'month',
            driver_month_row.month,

          'totalDuties',
            driver_month_row.total_duties,

          'weekdayDuties',
            driver_month_row.weekday_duties,

          'fridayDuties',
            driver_month_row.friday_duties,

          'saturdayDuties',
            driver_month_row.saturday_duties,

          'weekendDuties',
            driver_month_row.weekend_duties,

          'holidayDuties',
            driver_month_row.holiday_duties
        )
        order by
          driver_month_row.year,
          driver_month_row.month,
          driver_month_row.display_name
      ),
      '[]'::jsonb
    )
  into driver_monthly_breakdown
  from (
    select
      profile_row.id
        as user_id,

      profile_row.display_name,

      profile_row.schedule_name,

      driver_period.year,

      driver_period.month,

      count(driver_day.id)::integer
        as total_duties,

      count(driver_day.id) filter (
        where driver_day.weekday_number
          between 0 and 4
      )::integer
        as weekday_duties,

      count(driver_day.id) filter (
        where driver_day.weekday_number = 5
      )::integer
        as friday_duties,

      count(driver_day.id) filter (
        where driver_day.weekday_number = 6
      )::integer
        as saturday_duties,

      count(driver_day.id) filter (
        where driver_day.weekday_number
          in (5, 6)
      )::integer
        as weekend_duties,

      count(driver_day.id) filter (
        where exists (
          select 1
          from public.schedule_periods schedule_period_for_day
          join public.schedule_shifts holiday_shift
            on holiday_shift.period_id =
              schedule_period_for_day.id
          where holiday_shift.shift_date =
            driver_day.duty_date
            and holiday_shift.schedule_type in (
              'holiday_eve'::public.schedule_type,
              'holiday_full'::public.schedule_type,
              'holiday_end'::public.schedule_type,
              'chol_hamoed'::public.schedule_type
            )
        )
      )::integer
        as holiday_duties

    from public.profiles profile_row

    join public.driver_schedule_days driver_day
      on driver_day.assigned_user_id =
        profile_row.id

    join public.driver_schedule_periods driver_period
      on driver_period.id =
        driver_day.period_id

    where
      profile_row.role =
        'on_call'

      and (
        selected_year is null
        or driver_period.year =
          selected_year
      )

      and (
        selected_month is null
        or driver_period.month =
          selected_month
      )

      and driver_period.status in (
        'published'::public.driver_schedule_period_status,
        'archived'::public.driver_schedule_period_status
      )

    group by
      profile_row.id,
      profile_row.display_name,
      profile_row.schedule_name,
      driver_period.year,
      driver_period.month
  ) driver_month_row;

  /*
   * סיכום כולל לתקופה.
   */
  select
    jsonb_build_object(
      'dispatcherCount',
        (
          select count(distinct statistics_row->>'userId')
          from jsonb_array_elements(
            dispatcher_statistics
          ) statistics_row
        ),

      'driverCount',
        (
          select count(distinct statistics_row->>'userId')
          from jsonb_array_elements(
            driver_statistics
          ) statistics_row
        ),

      'totalDispatcherShifts',
        coalesce(
          (
            select sum(
              (statistics_row->>'totalShifts')::integer
            )
            from jsonb_array_elements(
              dispatcher_statistics
            ) statistics_row
          ),
          0
        ),

      'totalDriverDuties',
        coalesce(
          (
            select sum(
              (statistics_row->>'totalDuties')::integer
            )
            from jsonb_array_elements(
              driver_statistics
            ) statistics_row
          ),
          0
        ),

      'premiumShifts',
        coalesce(
          (
            select sum(
              (statistics_row->>'premiumShifts')::integer
            )
            from jsonb_array_elements(
              dispatcher_statistics
            ) statistics_row
          ),
          0
        ),

      'regularShifts',
        coalesce(
          (
            select sum(
              (statistics_row->>'regularShifts')::integer
            )
            from jsonb_array_elements(
              dispatcher_statistics
            ) statistics_row
          ),
          0
        ),

      'nightShifts',
        coalesce(
          (
            select sum(
              (statistics_row->>'nightShifts')::integer
            )
            from jsonb_array_elements(
              dispatcher_statistics
            ) statistics_row
          ),
          0
        ),

      'holidayShifts',
        coalesce(
          (
            select sum(
              (statistics_row->>'holidayShifts')::integer
            )
            from jsonb_array_elements(
              dispatcher_statistics
            ) statistics_row
          ),
          0
        ),

      'weekendShifts',
        coalesce(
          (
            select sum(
              (statistics_row->>'fridayShifts')::integer +
              (statistics_row->>'saturdayShifts')::integer
            )
            from jsonb_array_elements(
              dispatcher_statistics
            ) statistics_row
          ),
          0
        ),

      'weekdayDriverDuties',
        coalesce(
          (
            select sum(
              (statistics_row->>'weekdayDuties')::integer
            )
            from jsonb_array_elements(
              driver_statistics
            ) statistics_row
          ),
          0
        ),

      'weekendDriverDuties',
        coalesce(
          (
            select sum(
              (statistics_row->>'weekendDuties')::integer
            )
            from jsonb_array_elements(
              driver_statistics
            ) statistics_row
          ),
          0
        ),

      'holidayDriverDuties',
        coalesce(
          (
            select sum(
              (statistics_row->>'holidayDuties')::integer
            )
            from jsonb_array_elements(
              driver_statistics
            ) statistics_row
          ),
          0
        )
    )
  into summary_statistics;

  return jsonb_build_object(
    'filters',
      jsonb_build_object(
        'year',
          selected_year,

        'month',
          selected_month
      ),

    'summary',
      summary_statistics,

    'dispatcherStatistics',
      dispatcher_statistics,

    'driverStatistics',
      driver_statistics,

    'monthlyStatistics',
      monthly_statistics,

    'dispatcherMonthlyBreakdown',
      dispatcher_monthly_breakdown,

    'driverMonthlyBreakdown',
      driver_monthly_breakdown,

    'generatedAt',
      now()
  );
end;
$$;


ALTER FUNCTION "public"."get_statistics_dashboard"("requested_year" integer, "requested_month" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_statistics_people"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  current_user_id uuid := auth.uid();
  current_permissions text[];
begin
  if current_user_id is null then raise exception 'not authenticated'; end if;
  current_permissions := coalesce(public.get_my_permissions(), array[]::text[]);
  if not ('statistics.view' = any(current_permissions) or 'users.manage' = any(current_permissions)) then
    raise exception 'not allowed';
  end if;
  return coalesce((
    select jsonb_agg(
      jsonb_build_object(
        'userId', profile.id,
        'displayName', profile.display_name,
        'scheduleName', profile.schedule_name,
        'isActive', profile.is_active,
        'userType', case profile.role::text
          when 'dispatcher' then 'dispatchers'
          when 'on_call' then 'drivers'
          when 'morning_driver' then 'morning_drivers'
        end
      )
      order by
        case profile.role::text when 'dispatcher' then 1 when 'on_call' then 2 when 'morning_driver' then 3 else 4 end,
        case when profile.is_active then 0 else 1 end,
        coalesce(profile.schedule_name, profile.display_name)
    )
    from public.profiles profile
    where profile.role::text in ('dispatcher', 'on_call', 'morning_driver')
  ), '[]'::jsonb);
end;
$$;


ALTER FUNCTION "public"."get_statistics_people"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_user_dynamic_job_type_permission_editor"("target_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  actor uuid := auth.uid();
  target_role text;
begin
  if actor is null then raise exception 'not authenticated'; end if;
  if actor <> target_user_id and not exists (
    select 1 from public.user_permissions up
    where up.user_id = actor and up.permission_key in ('users.view', 'users.manage')
  ) then raise exception 'not allowed'; end if;

  select p.role::text into target_role from public.profiles p where p.id = target_user_id;
  if target_role is null then raise exception 'user not found'; end if;

  return jsonb_build_object(
    'role', target_role,
    'jobTypes', coalesce((
      select jsonb_agg(jsonb_build_object(
        'jobTypeId', jt.id,
        'jobTypeName', jt.name,
        'isMember', exists (select 1 from public.job_type_memberships m where m.job_type_id=jt.id and m.user_id=target_user_id),
        'isManager', exists (select 1 from public.job_type_managers jm where jm.job_type_id=jt.id and jm.user_id=target_user_id),
        'activeFeatures', to_jsonb(public.get_dynamic_job_type_active_features(jt.id)),
        'permissions', coalesce((
          select jsonb_agg(jsonb_build_object(
            'permissionKey', dm.permission_key,
            'featureKey', dm.feature_key,
            'audience', dm.audience,
            'label', dm.label,
            'description', dm.description,
            'defaultEnabled', dm.default_enabled,
            'inheritedEnabled', public.get_inherited_dynamic_job_type_permission(dm.permission_key, jt.id, target_user_id),
            'hasOverride', exists (
              select 1 from public.user_job_type_permissions ujtp
              where ujtp.user_id=target_user_id and ujtp.job_type_id=jt.id and ujtp.permission_key=dm.permission_key
            ),
            'defaultSource', case
              when dm.audience='manager' and target_role='admin' then 'system_admin'
              when dm.audience='manager' and exists (select 1 from public.job_type_managers jm where jm.job_type_id=jt.id and jm.user_id=target_user_id) then 'job_type_manager'
              when dm.audience='member' and exists (select 1 from public.job_type_memberships m where m.job_type_id=jt.id and m.user_id=target_user_id) then 'job_type_member'
              else 'none'
            end,
            'enabled', coalesce((
              select ujtp.enabled from public.user_job_type_permissions ujtp
              where ujtp.user_id=target_user_id and ujtp.job_type_id=jt.id and ujtp.permission_key=dm.permission_key
            ), public.get_inherited_dynamic_job_type_permission(dm.permission_key, jt.id, target_user_id))
          ) order by case dm.audience when 'member' then 0 else 1 end, dm.feature_key, dm.sort_order, dm.label)
          from public.dynamic_permission_manifest dm
          join public.job_type_permission_settings s
            on s.job_type_id=jt.id and s.permission_key=dm.permission_key and s.audience=dm.audience
          where dm.feature_key = any(public.get_dynamic_job_type_active_features(jt.id))
        ), '[]'::jsonb)
      ) order by jt.name)
      from public.job_types jt where jt.is_active=true
    ), '[]'::jsonb)
  );
end;
$$;


ALTER FUNCTION "public"."get_user_dynamic_job_type_permission_editor"("target_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_user_dynamic_permission_summary"("target_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare actor uuid := auth.uid();
begin
  if actor is null then raise exception 'not authenticated'; end if;
  if actor <> target_user_id and not exists (
    select 1 from public.user_permissions up
    where up.user_id=actor and up.permission_key='users.manage'
  ) then raise exception 'not allowed'; end if;

  return jsonb_build_object('roles',coalesce((
    select jsonb_agg(role_item order by role_item->>'jobTypeName',role_item->>'relationship')
    from (
      select jsonb_build_object(
        'jobTypeId',jt.id,'jobTypeName',jt.name,'relationship','member',
        'permissions',coalesce((
          select jsonb_agg(jsonb_build_object('permissionKey',s.permission_key,'label',dm.label,'featureKey',dm.feature_key) order by dm.feature_key,dm.sort_order)
          from public.job_type_permission_settings s
          join public.dynamic_permission_manifest dm on dm.permission_key=s.permission_key and dm.audience=s.audience
          where s.job_type_id=jt.id and s.audience='member' and s.enabled=true
        ),'[]'::jsonb)
      ) role_item
      from public.job_type_memberships m
      join public.job_types jt on jt.id=m.job_type_id and jt.is_active=true
      where m.user_id=target_user_id

      union all

      select jsonb_build_object(
        'jobTypeId',jt.id,'jobTypeName',jt.name,'relationship','manager',
        'permissions',coalesce((
          select jsonb_agg(jsonb_build_object('permissionKey',s.permission_key,'label',dm.label,'featureKey',dm.feature_key) order by dm.feature_key,dm.sort_order)
          from public.job_type_permission_settings s
          join public.dynamic_permission_manifest dm on dm.permission_key=s.permission_key and dm.audience=s.audience
          where s.job_type_id=jt.id and s.audience='manager' and s.enabled=true
        ),'[]'::jsonb)
      ) role_item
      from public.job_type_managers jm
      join public.job_types jt on jt.id=jm.job_type_id and jt.is_active=true
      where jm.user_id=target_user_id
    ) q
  ),'[]'::jsonb));
end;
$$;


ALTER FUNCTION "public"."get_user_dynamic_permission_summary"("target_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_user_permission_policy"("target_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_actor uuid := auth.uid();
begin
  if v_actor is null then raise exception 'not authenticated'; end if;
  if not exists (
    select 1 from public.user_permissions up
    where up.user_id = v_actor and up.permission_key = 'users.manage'
  ) then raise exception 'not allowed'; end if;

  return jsonb_build_object(
    'profileCode', (
      select pp.code
      from public.user_permission_policies upp
      left join public.permission_profiles pp on pp.id = upp.profile_id
      where upp.user_id = target_user_id
    ),
    'scopeMode', coalesce((
      select upp.scope_mode from public.user_permission_policies upp where upp.user_id = target_user_id
    ), 'all'),
    'jobTypeIds', coalesce((
      select jsonb_agg(ups.job_type_id order by ups.job_type_id)
      from public.user_permission_job_type_scopes ups
      where ups.user_id = target_user_id
    ), '[]'::jsonb)
  );
end;
$$;


ALTER FUNCTION "public"."get_user_permission_policy"("target_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_user_permissions"("target_user_id" "uuid") RETURNS "text"[]
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if not public.is_current_user_admin() then
    raise exception 'Only administrators can view user permissions';
  end if;

  return (
    select coalesce(
      array_agg(
        up.permission_key
        order by p.sort_order, up.permission_key
      ),
      array[]::text[]
    )
    from public.user_permissions up
    join public.permissions p
      on p.permission_key = up.permission_key
    where up.user_id = target_user_id
  );
end;
$$;


ALTER FUNCTION "public"."get_user_permissions"("target_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."guard_development_mode_production_write"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if public.is_my_development_mode() then
    raise exception 'SIMULATION_MODE: הפעולה נחסמה. מצב פיתוח פעיל ולא בוצע שינוי בנתוני המערכת.'
      using errcode = 'P0001',
            hint = 'כבה מצב פיתוח בהגדרות כדי לבצע את הפעולה ב-Production.';
  end if;
  return case when tg_op = 'DELETE' then old else new end;
end;
$$;


ALTER FUNCTION "public"."guard_development_mode_production_write"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."handle_new_auth_user"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  resolved_display_name text;
begin
  resolved_display_name :=
    coalesce(
      nullif(trim(new.raw_user_meta_data ->> 'display_name'), ''),
      nullif(trim(new.raw_user_meta_data ->> 'full_name'), ''),
      nullif(split_part(new.email, '@', 1), ''),
      'משתמש חדש'
    );

  insert into public.profiles (
    id,
    email,
    display_name,
    schedule_name,
    role,
    is_active
  )
  values (
    new.id,
    coalesce(new.email, new.id::text),
    resolved_display_name,
    resolved_display_name,
    'dispatcher',
    true
  )
  on conflict (id) do update
  set
    email = excluded.email,
    updated_at = now();

  return new;
end;
$$;


ALTER FUNCTION "public"."handle_new_auth_user"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."handle_profile_audit_update"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  current_actor_id uuid;
  current_actor_email text;
  current_actor_display_name text;

  audit_action text;
  audit_summary text;

  previous_values jsonb;
  updated_values jsonb;
begin
  /*
   * לא יוצרים Audit אם השינוי בוצע ללא משתמש מחובר,
   * למשל מתוך Edge Function עם service_role.
   *
   * יצירת משתמש כבר נרשמת בנפרד מתוך create-user.
   */
  current_actor_id := auth.uid();

  if current_actor_id is null then
    return new;
  end if;

  /*
   * מתעדים רק שינויים ניהוליים משמעותיים.
   * שינוי last_login_at או updated_at בלבד לא יירשם.
   */
  if not (
    old.display_name
      is distinct from new.display_name
    or old.schedule_name
      is distinct from new.schedule_name
    or old.role
      is distinct from new.role
    or old.is_active
      is distinct from new.is_active
    or old.must_change_password
      is distinct from new.must_change_password
  ) then
    return new;
  end if;

  select
    profile.email,
    profile.display_name
  into
    current_actor_email,
    current_actor_display_name
  from public.profiles profile
  where profile.id = current_actor_id;

  /*
   * קביעת סוג הפעולה המרכזי.
   */
  if old.is_active = true
     and new.is_active = false then
    audit_action := 'user_deactivated';

    audit_summary :=
      'המשתמש הושבת: ' ||
      coalesce(
        new.display_name,
        new.email,
        new.id::text
      );

  elsif old.is_active = false
        and new.is_active = true then
    audit_action := 'user_activated';

    audit_summary :=
      'המשתמש הופעל מחדש: ' ||
      coalesce(
        new.display_name,
        new.email,
        new.id::text
      );

  elsif old.must_change_password = false
        and new.must_change_password = true then
    audit_action :=
      'user_password_change_required';

    audit_summary :=
      'המשתמש סומן כמי שנדרש לשנות סיסמה: ' ||
      coalesce(
        new.display_name,
        new.email,
        new.id::text
      );

  elsif old.must_change_password = true
        and new.must_change_password = false then
    audit_action :=
      'user_password_change_completed';

    audit_summary :=
      'המשתמש השלים שינוי סיסמה: ' ||
      coalesce(
        new.display_name,
        new.email,
        new.id::text
      );

  else
    audit_action := 'user_updated';

    audit_summary :=
      'עודכנו פרטי המשתמש: ' ||
      coalesce(
        new.display_name,
        new.email,
        new.id::text
      );
  end if;

  previous_values :=
    jsonb_build_object(
      'display_name',
      old.display_name,

      'schedule_name',
      old.schedule_name,

      'role',
      old.role,

      'is_active',
      old.is_active,

      'must_change_password',
      old.must_change_password
    );

  updated_values :=
    jsonb_build_object(
      'display_name',
      new.display_name,

      'schedule_name',
      new.schedule_name,

      'role',
      new.role,

      'is_active',
      new.is_active,

      'must_change_password',
      new.must_change_password
    );

  insert into public.audit_logs (
    action,

    actor_user_id,
    actor_email,
    actor_display_name,

    target_user_id,
    target_email,
    target_display_name,

    entity_type,
    summary,

    old_values,
    new_values,

    metadata
  )
  values (
    audit_action,

    current_actor_id,
    current_actor_email,
    current_actor_display_name,

    new.id,
    new.email,
    new.display_name,

    'user',
    audit_summary,

    previous_values,
    updated_values,

    jsonb_build_object(
      'source',
      'profiles-update-trigger'
    )
  );

  return new;
end;
$$;


ALTER FUNCTION "public"."handle_profile_audit_update"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."handle_profile_permissions_created"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  perform public.apply_default_user_permissions(
    new.id
  );

  return new;
end;
$$;


ALTER FUNCTION "public"."handle_profile_permissions_created"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."has_dynamic_job_type_permission"("requested_permission_key" "text", "requested_job_type_id" "uuid", "requested_user_id" "uuid" DEFAULT "auth"."uid"()) RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare explicit_value boolean;
begin
  if requested_user_id is null then return false; end if;

  if not exists (
    select 1 from public.dynamic_permission_manifest dm
    where dm.permission_key = requested_permission_key
      and dm.feature_key = any(public.get_dynamic_job_type_active_features(requested_job_type_id))
  ) then return false; end if;

  select ujtp.enabled into explicit_value
  from public.user_job_type_permissions ujtp
  where ujtp.user_id = requested_user_id
    and ujtp.job_type_id = requested_job_type_id
    and ujtp.permission_key = requested_permission_key;
  if found then return explicit_value; end if;

  return public.get_inherited_dynamic_job_type_permission(
    requested_permission_key, requested_job_type_id, requested_user_id
  );
end;
$$;


ALTER FUNCTION "public"."has_dynamic_job_type_permission"("requested_permission_key" "text", "requested_job_type_id" "uuid", "requested_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."has_job_type_permission"("requested_permission_key" "text", "requested_job_type_id" "uuid", "requested_user_id" "uuid" DEFAULT "auth"."uid"()) RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select
    requested_user_id is not null
    and exists (
      select 1 from public.user_permissions up
      where up.user_id = requested_user_id
        and up.permission_key = requested_permission_key
    )
    and (
      not exists (
        select 1 from public.user_permission_policies upp
        where upp.user_id = requested_user_id
          and upp.scope_mode = 'selected'
      )
      or exists (
        select 1 from public.user_permission_job_type_scopes ups
        where ups.user_id = requested_user_id
          and ups.job_type_id = requested_job_type_id
      )
    );
$$;


ALTER FUNCTION "public"."has_job_type_permission"("requested_permission_key" "text", "requested_job_type_id" "uuid", "requested_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."import_dynamic_legacy_history"("requested_job_type_id" "uuid", "requested_source_kind" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  current_user_id uuid := auth.uid();
  batch_id uuid;
  periods_added integer := 0;
  assignments_added integer := 0;
  availability_added integer := 0;
  current_ym integer := extract(year from (now() at time zone 'Asia/Jerusalem'))::integer * 100
    + extract(month from (now() at time zone 'Asia/Jerusalem'))::integer;
begin
  if current_user_id is null then
    raise exception 'not authenticated';
  end if;

  if not exists (
    select 1
    from public.user_permissions up
    where up.user_id = current_user_id
      and up.permission_key = 'users.manage'
  ) then
    raise exception 'not allowed';
  end if;

  if requested_source_kind not in ('dispatcher','on_call','morning_driver') then
    raise exception 'invalid source kind';
  end if;

  if not exists (
    select 1 from public.job_types where id = requested_job_type_id
  ) then
    raise exception 'job type not found';
  end if;

  insert into public.dynamic_legacy_import_batches(
    job_type_id,
    source_kind,
    status,
    created_by
  )
  values (
    requested_job_type_id,
    requested_source_kind,
    'running',
    current_user_id
  )
  returning id into batch_id;

  if requested_source_kind = 'dispatcher' then
    insert into public.dynamic_historical_periods(
      job_type_id,
      source_kind,
      source_period_id,
      year,
      month,
      source_status,
      imported_batch_id,
      source_payload
    )
    select
      requested_job_type_id,
      'dispatcher',
      p.id,
      p.year,
      p.month,
      p.status::text,
      batch_id,
      to_jsonb(p)
    from public.schedule_periods p
    where p.status::text in ('published','archived')
      and (p.year * 100 + p.month) < current_ym
    on conflict(job_type_id,source_kind,source_period_id) do nothing;

    get diagnostics periods_added = row_count;

    insert into public.dynamic_historical_assignments(
      historical_period_id,
      source_kind,
      source_record_id,
      work_date,
      starts_at,
      ends_at,
      shift_code,
      assigned_user_id,
      is_intentionally_unassigned,
      source_payload
    )
    select
      hp.id,
      'dispatcher',
      s.id,
      s.shift_date,
      s.starts_at,
      s.ends_at,
      s.shift_code,
      s.assigned_user_id,
      coalesce((to_jsonb(s)->>'is_intentionally_unassigned')::boolean,false),
      to_jsonb(s)
    from public.schedule_shifts s
    join public.schedule_periods p on p.id = s.period_id
    join public.dynamic_historical_periods hp
      on hp.job_type_id = requested_job_type_id
     and hp.source_kind = 'dispatcher'
     and hp.source_period_id = p.id
    where p.status::text in ('published','archived')
      and (p.year * 100 + p.month) < current_ym
    on conflict(historical_period_id,source_kind,source_record_id) do nothing;

    get diagnostics assignments_added = row_count;

    -- Map the current availability model to the imported schedule period by month.
    -- The source payload keeps both the availability entry and its slot for auditability.
    insert into public.dynamic_historical_availability(
      historical_period_id,
      source_kind,
      source_record_id,
      user_id,
      work_date,
      status,
      note,
      source_payload
    )
    select
      hp_match.id,
      'dispatcher',
      a.id,
      a.user_id,
      slot.shift_date,
      a.availability_status::text,
      a.note,
      jsonb_build_object(
        'entry', to_jsonb(a),
        'slot', to_jsonb(slot),
        'availabilityPeriod', to_jsonb(ap)
      )
    from public.dispatcher_availability a
    join public.availability_periods ap on ap.id = a.period_id
    join public.availability_shift_slots slot on slot.id = a.shift_slot_id
    join lateral (
      select hp.id
      from public.dynamic_historical_periods hp
      where hp.job_type_id = requested_job_type_id
        and hp.source_kind = 'dispatcher'
        and hp.year = ap.year
        and hp.month = ap.month
        and hp.source_status in ('published','archived')
      order by hp.imported_at desc, hp.id
      limit 1
    ) hp_match on true
    on conflict(historical_period_id,source_kind,source_record_id) do nothing;

    get diagnostics availability_added = row_count;

  elsif requested_source_kind = 'on_call' then
    insert into public.dynamic_historical_periods(
      job_type_id,source_kind,source_period_id,year,month,source_status,imported_batch_id,source_payload
    )
    select requested_job_type_id,'on_call',p.id,p.year,p.month,p.status::text,batch_id,to_jsonb(p)
    from public.driver_schedule_periods p
    where p.status::text in ('published','archived')
      and (p.year * 100 + p.month) < current_ym
    on conflict(job_type_id,source_kind,source_period_id) do nothing;
    get diagnostics periods_added = row_count;

    insert into public.dynamic_historical_assignments(
      historical_period_id,source_kind,source_record_id,work_date,original_user_id,assigned_user_id,is_intentionally_unassigned,source_payload
    )
    select hp.id,'on_call',d.id,d.duty_date,d.original_user_id,d.assigned_user_id,
      coalesce((to_jsonb(d)->>'is_intentionally_unassigned')::boolean,false),to_jsonb(d)
    from public.driver_schedule_days d
    join public.driver_schedule_periods p on p.id=d.period_id
    join public.dynamic_historical_periods hp
      on hp.job_type_id=requested_job_type_id
     and hp.source_kind='on_call'
     and hp.source_period_id=p.id
    where p.status::text in ('published','archived')
      and (p.year * 100 + p.month) < current_ym
    on conflict(historical_period_id,source_kind,source_record_id) do nothing;
    get diagnostics assignments_added = row_count;

  else
    insert into public.dynamic_historical_periods(
      job_type_id,source_kind,source_period_id,year,month,source_status,imported_batch_id,source_payload
    )
    select requested_job_type_id,'morning_driver',p.id,p.year,p.month,p.status::text,batch_id,to_jsonb(p)
    from public.morning_driver_schedule_periods p
    where p.status::text in ('published','archived')
      and (p.year * 100 + p.month) < current_ym
    on conflict(job_type_id,source_kind,source_period_id) do nothing;
    get diagnostics periods_added = row_count;

    insert into public.dynamic_historical_assignments(
      historical_period_id,source_kind,source_record_id,work_date,starts_at,ends_at,shift_code,assigned_user_id,is_intentionally_unassigned,source_payload
    )
    select hp.id,'morning_driver',a.id,s.shift_date,
      case when s.shift_date is not null and s.start_time is not null
        then (s.shift_date + s.start_time)::timestamp at time zone 'Asia/Jerusalem'
        else null end,
      case when s.shift_date is not null and s.end_time is not null
        then ((s.shift_date + s.end_time) + case when s.end_time<=s.start_time then interval '1 day' else interval '0 day' end) at time zone 'Asia/Jerusalem'
        else null end,
      s.id::text,a.assigned_user_id,coalesce(a.is_intentionally_unassigned,false),
      jsonb_build_object('assignment',to_jsonb(a),'shift',to_jsonb(s))
    from public.morning_driver_schedule_assignments a
    join public.morning_driver_schedule_periods p on p.id=a.schedule_period_id
    join public.morning_driver_availability_shifts s on s.id=a.availability_shift_id
    join public.dynamic_historical_periods hp
      on hp.job_type_id=requested_job_type_id
     and hp.source_kind='morning_driver'
     and hp.source_period_id=p.id
    where p.status::text in ('published','archived')
      and (p.year * 100 + p.month) < current_ym
    on conflict(historical_period_id,source_kind,source_record_id) do nothing;
    get diagnostics assignments_added = row_count;

    insert into public.dynamic_historical_availability(
      historical_period_id,source_kind,source_record_id,user_id,work_date,status,note,source_payload
    )
    select hp.id,'morning_driver',e.id,e.user_id,s.shift_date,e.availability_status::text,e.note,
      jsonb_build_object('entry',to_jsonb(e),'shift',to_jsonb(s))
    from public.morning_driver_availability_entries e
    join public.morning_driver_availability_shifts s on s.id=e.shift_id
    join public.morning_driver_schedule_periods sp
      on sp.availability_period_id=e.period_id
     and sp.status::text in ('published','archived')
     and (sp.year * 100 + sp.month) < current_ym
    join public.dynamic_historical_periods hp
      on hp.job_type_id=requested_job_type_id
     and hp.source_kind='morning_driver'
     and hp.source_period_id=sp.id
    on conflict(historical_period_id,source_kind,source_record_id) do nothing;
    get diagnostics availability_added = row_count;
  end if;

  update public.dynamic_legacy_import_batches
  set status='completed',
      imported_periods=periods_added,
      imported_assignments=assignments_added,
      imported_availability=availability_added,
      completed_at=now()
  where id=batch_id;

  insert into public.audit_logs(
    user_id,action,entity_type,entity_id,summary,actor_user_id,metadata
  )
  values(
    current_user_id,
    'dynamic_job_type.legacy_history.imported',
    'job_type',
    requested_job_type_id,
    'יובאה היסטוריה מהמערכת הישנה לתפקיד דינמי',
    current_user_id,
    jsonb_build_object(
      'sourceKind',requested_source_kind,
      'batchId',batch_id,
      'periods',periods_added,
      'assignments',assignments_added,
      'availability',availability_added
    )
  );

  return jsonb_build_object(
    'batchId',batch_id,
    'periodsImported',periods_added,
    'assignmentsImported',assignments_added,
    'availabilityImported',availability_added,
    'idempotent',true
  );
exception when others then
  if batch_id is not null then
    update public.dynamic_legacy_import_batches
    set status='failed',
        completed_at=now(),
        metadata=jsonb_build_object('error',sqlerrm)
    where id=batch_id;
  end if;
  raise;
end;
$$;


ALTER FUNCTION "public"."import_dynamic_legacy_history"("requested_job_type_id" "uuid", "requested_source_kind" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."import_morning_driver_schedule_assignments"("requested_import_run_id" "uuid", "requested_year" integer, "requested_month" integer, "requested_period_type" "text", "requested_import_strategy" "text", "requested_morning_driver_shifts" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  current_user_id uuid := auth.uid();
  imported_at timestamptz := now();

  resolved_availability_period_id uuid;
  resolved_schedule_period_id uuid;

  detected_count integer := 0;
  existing_count integer := 0;
  created_count integer := 0;
  updated_count integer := 0;
  skipped_count integer := 0;
  deleted_count integer := 0;
begin
  if current_user_id is null then
    raise exception 'not authenticated';
  end if;

  if requested_morning_driver_shifts is null
     or jsonb_typeof(requested_morning_driver_shifts) <> 'array'
  then
    raise exception
      'morning driver shifts must be a json array';
  end if;

  detected_count :=
    jsonb_array_length(
      requested_morning_driver_shifts
    );

  select period.id
  into resolved_availability_period_id
  from public.morning_driver_availability_periods period
  where period.year = requested_year
    and period.month = requested_month
  for update;

  if not found then
    insert into public.morning_driver_availability_periods (
      year,
      month,
      status,
      title,
      instructions,
      submission_deadline,
      closed_at,
      archived_at,
      created_by,
      updated_by,
      created_at,
      updated_at
    )
    values (
      requested_year,
      requested_month,
      case
        when requested_period_type = 'historical'
        then 'archived'
        else 'closed'
      end,
      format(
        'כונני בוקר %s/%s',
        requested_month,
        requested_year
      ),
      'התקופה נוצרה אוטומטית מייבוא לוח שיבוצים.',
      (
        make_date(
          requested_year,
          requested_month,
          1
        )::timestamp
        at time zone 'Asia/Jerusalem'
      ),
      case
        when requested_period_type <> 'historical'
        then imported_at
        else null
      end,
      case
        when requested_period_type = 'historical'
        then imported_at
        else null
      end,
      current_user_id,
      current_user_id,
      imported_at,
      imported_at
    )
    returning id
    into resolved_availability_period_id;
  else
    update public.morning_driver_availability_periods
    set
      status =
        case
          when requested_period_type = 'historical'
          then 'archived'
          else 'closed'
        end,
      closed_at =
        case
          when requested_period_type = 'historical'
          then closed_at
          else coalesce(closed_at, imported_at)
        end,
      archived_at =
        case
          when requested_period_type = 'historical'
          then coalesce(archived_at, imported_at)
          else null
        end,
      updated_by = current_user_id,
      updated_at = imported_at
    where id = resolved_availability_period_id;
  end if;

  select period.id
  into resolved_schedule_period_id
  from public.morning_driver_schedule_periods period
  where period.year = requested_year
    and period.month = requested_month
  for update;

  if not found then
    insert into public.morning_driver_schedule_periods (
      year,
      month,
      status,
      availability_period_id,
      title,
      published_at,
      created_by,
      updated_by,
      created_at,
      updated_at
    )
    values (
      requested_year,
      requested_month,
      case
        when requested_period_type = 'historical'
        then 'archived'
        else 'published'
      end,
      resolved_availability_period_id,
      format(
        'לוח כונני בוקר %s/%s',
        requested_month,
        requested_year
      ),
      imported_at,
      current_user_id,
      current_user_id,
      imported_at,
      imported_at
    )
    returning id
    into resolved_schedule_period_id;
  else
    update public.morning_driver_schedule_periods
    set
      status =
        case
          when requested_period_type = 'historical'
          then 'archived'
          else 'published'
        end,
      availability_period_id =
        resolved_availability_period_id,
      published_at =
        coalesce(published_at, imported_at),
      updated_by =
        current_user_id,
      updated_at =
        imported_at
    where id =
      resolved_schedule_period_id;
  end if;

  if requested_import_strategy = 'rebuild' then
    select count(*)::integer
    into deleted_count
    from public.morning_driver_schedule_assignments assignment
    where assignment.schedule_period_id =
      resolved_schedule_period_id;

    delete from public.morning_driver_schedule_assignments assignment
    where assignment.schedule_period_id =
      resolved_schedule_period_id;

    delete from public.morning_driver_availability_entries entry
    where entry.period_id =
      resolved_availability_period_id;

    delete from public.morning_driver_availability_submissions submission
    where submission.period_id =
      resolved_availability_period_id;

    delete from public.morning_driver_availability_shifts shift_item
    where shift_item.period_id =
      resolved_availability_period_id;
  end if;

  /*
   * יצירת/עדכון המשמרות שאליהן משויכים ה-Slots.
   * required_workers משמש במערכת כיעד המומלץ.
   */
  insert into public.morning_driver_availability_shifts (
    period_id,
    shift_date,
    weekday_number,
    weekday_name,
    shift_type,
    start_time,
    end_time,
    required_workers,
    sort_order,
    created_at,
    updated_at
  )
  select
    resolved_availability_period_id,
    payload.shift_date,
    extract(
      dow from payload.shift_date
    )::integer,
    case extract(
      dow from payload.shift_date
    )::integer
      when 0 then 'ראשון'
      when 1 then 'שני'
      when 2 then 'שלישי'
      when 3 then 'רביעי'
      when 4 then 'חמישי'
      when 5 then 'שישי'
      when 6 then 'שבת'
    end,
    payload.shift_type,
    payload.start_time,
    payload.end_time,
    payload.recommended_workers,
    row_number() over (
      order by
        payload.shift_date,
        payload.start_time,
        payload.shift_type
    )::integer,
    imported_at,
    imported_at
  from (
    select distinct
      (item ->> 'date')::date as shift_date,
      item ->> 'shiftType' as shift_type,
      (item ->> 'startTime')::time as start_time,
      (item ->> 'endTime')::time as end_time,
      greatest(
        least(
          (item ->> 'recommendedWorkers')::integer,
          2
        ),
        1
      ) as recommended_workers
    from jsonb_array_elements(
      requested_morning_driver_shifts
    ) item
  ) payload
  on conflict (
    period_id,
    shift_date,
    shift_type
  )
  do update set
    start_time =
      excluded.start_time,
    end_time =
      excluded.end_time,
    required_workers =
      excluded.required_workers,
    sort_order =
      excluded.sort_order,
    updated_at =
      imported_at;

  select count(*)::integer
  into existing_count
  from jsonb_array_elements(
    requested_morning_driver_shifts
  ) item
  where exists (
    select 1
    from public.morning_driver_schedule_assignments assignment
    join public.morning_driver_availability_shifts shift_item
      on shift_item.id =
        assignment.availability_shift_id
    where assignment.schedule_period_id =
        resolved_schedule_period_id
      and shift_item.period_id =
        resolved_availability_period_id
      and shift_item.shift_date =
        (item ->> 'date')::date
      and shift_item.shift_type =
        item ->> 'shiftType'
      and assignment.assignment_slot =
        (item ->> 'assignmentSlot')::integer
  );

  if requested_import_strategy = 'missing_only' then
    insert into public.morning_driver_schedule_assignments (
      schedule_period_id,
      availability_shift_id,
      assignment_slot,
      assigned_user_id,
      assignment_source,
      is_locked,
      notes,
      created_at,
      updated_at
    )
    select
      resolved_schedule_period_id,
      shift_item.id,
      (item ->> 'assignmentSlot')::integer,
      (item ->> 'userId')::uuid,
      'import',
      requested_period_type = 'historical',
      null,
      imported_at,
      imported_at
    from jsonb_array_elements(
      requested_morning_driver_shifts
    ) item
    join public.morning_driver_availability_shifts shift_item
      on shift_item.period_id =
        resolved_availability_period_id
     and shift_item.shift_date =
        (item ->> 'date')::date
     and shift_item.shift_type =
        item ->> 'shiftType'
    on conflict (
      schedule_period_id,
      availability_shift_id,
      assignment_slot
    )
    do nothing;

    created_count :=
      greatest(
        detected_count - existing_count,
        0
      );
    skipped_count :=
      existing_count;

  else
    insert into public.morning_driver_schedule_assignments (
      schedule_period_id,
      availability_shift_id,
      assignment_slot,
      assigned_user_id,
      assignment_source,
      is_locked,
      notes,
      created_at,
      updated_at
    )
    select
      resolved_schedule_period_id,
      shift_item.id,
      (item ->> 'assignmentSlot')::integer,
      (item ->> 'userId')::uuid,
      'import',
      requested_period_type = 'historical',
      null,
      imported_at,
      imported_at
    from jsonb_array_elements(
      requested_morning_driver_shifts
    ) item
    join public.morning_driver_availability_shifts shift_item
      on shift_item.period_id =
        resolved_availability_period_id
     and shift_item.shift_date =
        (item ->> 'date')::date
     and shift_item.shift_type =
        item ->> 'shiftType'
    on conflict (
      schedule_period_id,
      availability_shift_id,
      assignment_slot
    )
    do update set
      assigned_user_id =
        excluded.assigned_user_id,
      assignment_source =
        excluded.assignment_source,
      is_locked =
        excluded.is_locked,
      notes =
        excluded.notes,
      updated_at =
        imported_at;

    if requested_import_strategy = 'rebuild'
       or requested_import_strategy = 'historical_archive'
    then
      created_count :=
        detected_count;
      updated_count := 0;
    else
      created_count :=
        greatest(
          detected_count - existing_count,
          0
        );
      updated_count :=
        existing_count;
    end if;
  end if;

  update public.schedule_import_runs
  set
    result_summary =
      coalesce(
        result_summary,
        '{}'::jsonb
      )
      ||
      jsonb_build_object(
        'morningDriverShifts',
          jsonb_build_object(
            'detected',
              detected_count,
            'created',
              created_count,
            'updated',
              updated_count,
            'skipped',
              skipped_count,
            'deleted',
              deleted_count
          )
      ),
    updated_at =
      imported_at
  where id =
    requested_import_run_id;

  return jsonb_build_object(
    'availabilityPeriodId',
      resolved_availability_period_id,
    'schedulePeriodId',
      resolved_schedule_period_id,
    'detected',
      detected_count,
    'created',
      created_count,
    'updated',
      updated_count,
    'skipped',
      skipped_count,
    'deleted',
      deleted_count
  );
end;
$$;


ALTER FUNCTION "public"."import_morning_driver_schedule_assignments"("requested_import_run_id" "uuid", "requested_year" integer, "requested_month" integer, "requested_period_type" "text", "requested_import_strategy" "text", "requested_morning_driver_shifts" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."initialize_dynamic_job_type_rotation_state"("requested_job_type_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_actor uuid:=auth.uid();
  v_job public.job_types%rowtype;
  v_member_count integer;
  v_rotation uuid[];
  v_anchor date;
  v_source text;
  v_history_rows integer:=0;
begin
  if v_actor is null then raise exception 'not authenticated'; end if;
  if not exists(select 1 from public.user_permissions up where up.user_id=v_actor and up.permission_key='users.manage')
    then raise exception 'not allowed'; end if;

  select * into v_job from public.job_types where id=requested_job_type_id;
  if v_job.id is null then raise exception 'job type not found'; end if;
  if coalesce(v_job.scheduling_strategy,'availability_optimizer') <> 'monthly_rotation_constraints'
    then raise exception 'job type is not configured for monthly rotation'; end if;

  if exists(select 1 from public.dynamic_job_type_rotation_state where job_type_id=v_job.id) then
    return public.get_dynamic_job_type_rotation_workspace(v_job.id,current_date,35);
  end if;

  select count(*)::integer into v_member_count
  from public.job_type_memberships m join public.profiles p on p.id=m.user_id and p.is_active=true
  where m.job_type_id=v_job.id;
  if v_member_count < 2 then raise exception 'monthly rotation requires at least two active role members'; end if;

  with hist as (
    select ha.work_date,coalesce(ha.original_user_id,ha.assigned_user_id) user_id,
           row_number() over(order by ha.work_date,ha.id) rn
    from public.dynamic_historical_assignments ha
    join public.dynamic_historical_periods hp on hp.id=ha.historical_period_id
    join public.job_type_memberships jm on jm.job_type_id=hp.job_type_id
      and jm.user_id=coalesce(ha.original_user_id,ha.assigned_user_id)
    where hp.job_type_id=v_job.id and ha.work_date is not null
      and coalesce(ha.original_user_id,ha.assigned_user_id) is not null
  ), candidates as (
    select h0.work_date anchor_date,array_agg(h.user_id order by h.rn) rotation
    from hist h0 join hist h on h.rn between h0.rn and h0.rn+v_member_count-1
    group by h0.rn,h0.work_date
    having count(*)=v_member_count and count(distinct h.user_id)=v_member_count
  ), scored as (
    select c.anchor_date,c.rotation,
           count(*) filter(where h.user_id=c.rotation[((h.work_date-c.anchor_date)%v_member_count+v_member_count)%v_member_count+1])::integer matches,
           count(*)::integer compared
    from candidates c cross join hist h
    group by c.anchor_date,c.rotation
    order by matches desc,compared desc,c.anchor_date desc
    limit 1
  )
  select rotation,anchor_date,'historical_best_window',compared
    into v_rotation,v_anchor,v_source,v_history_rows from scored;

  if v_rotation is null or cardinality(v_rotation)<>v_member_count then
    select array_agg(x.user_id order by x.display_name,x.user_id),current_date,'membership_fallback'
    into v_rotation,v_anchor,v_source
    from (
      select m.user_id,coalesce(p.schedule_name,p.display_name,p.email,m.user_id::text) display_name
      from public.job_type_memberships m join public.profiles p on p.id=m.user_id and p.is_active=true
      where m.job_type_id=v_job.id
    ) x;
  end if;

  insert into public.dynamic_job_type_rotation_state(
    job_type_id,rotation_user_ids,anchor_date,source,source_metadata,created_by
  ) values(
    v_job.id,v_rotation,v_anchor,v_source,
    jsonb_build_object('historicalRowsCompared',v_history_rows,'memberCount',v_member_count),
    v_actor
  );

  insert into public.audit_logs(action,actor_user_id,entity_type,entity_id,summary,metadata)
  values('system_event',v_actor,'job_type',v_job.id,'סבב חודשי אותחל',
    jsonb_build_object('rotationUserIds',to_jsonb(v_rotation),'anchorDate',v_anchor,'source',v_source));

  return public.get_dynamic_job_type_rotation_workspace(v_job.id,current_date,35);
end;
$$;


ALTER FUNCTION "public"."initialize_dynamic_job_type_rotation_state"("requested_job_type_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."is_admin"() RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select coalesce(
    public.current_user_role() = 'admin',
    false
  );
$$;


ALTER FUNCTION "public"."is_admin"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."is_current_user_admin"() RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select exists (
    select 1
    from public.profiles
    where id = auth.uid()
      and role::text = 'admin'
      and is_active = true
  );
$$;


ALTER FUNCTION "public"."is_current_user_admin"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."is_manager_or_admin"() RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select coalesce(
    public.current_user_role() in ('admin', 'manager'),
    false
  );
$$;


ALTER FUNCTION "public"."is_manager_or_admin"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."is_my_development_mode"() RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select exists (
    select 1
    from public.admin_development_sessions s
    join public.profiles p on p.id = s.user_id
    where s.user_id = auth.uid()
      and p.role = 'admin'
      and p.is_active = true
      and s.enabled = true
      and (s.expires_at is null or s.expires_at > now())
  );
$$;


ALTER FUNCTION "public"."is_my_development_mode"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mark_my_operational_push_dispatched"("requested_notification_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor uuid := auth.uid();
begin
  if actor is null then raise exception 'not authenticated'; end if;

  update public.notifications n
  set data = jsonb_set(
    jsonb_set(coalesce(n.data,'{}'::jsonb), '{pushPending}', 'false'::jsonb, true),
    '{pushDispatchedAt}',
    to_jsonb(now()),
    true
  )
  where n.id = requested_notification_id
    and n.created_by = actor
    and n.source in ('dynamic_schedule_edit','shift_swap');
end;
$$;


