CREATE OR REPLACE FUNCTION "public"."materialize_dynamic_availability_period_slots"("requested_period_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  period_row public.dynamic_availability_periods%rowtype;
  target_month date;
  materialization_row public.job_type_schedule_materializations%rowtype;
  day_date date;
  dow_value integer;
  source_day_kind_value text;
  base_day_kind_value text;
  effective_day_kind_value text;
  holiday_name_value text;
  day_behavior text;
  inherit_day_kind_value text;
  day_works boolean;
  shift_row public.job_type_materialized_shift_templates%rowtype;
  created_slots integer := 0;
  existing_slots integer := 0;
  pay_snapshot jsonb;
begin
  select * into period_row
  from public.dynamic_availability_periods
  where id=requested_period_id;

  if period_row.id is null then
    raise exception 'dynamic availability period not found';
  end if;

  select count(*) into existing_slots
  from public.dynamic_availability_slots
  where period_id=period_row.id;

  -- Never rebuild an already materialized period implicitly. This protects
  -- existing employee entries from being detached from their original slots.
  if existing_slots > 0 then
    return existing_slots;
  end if;

  target_month := make_date(period_row.year,period_row.month,1);

  select * into materialization_row
  from public.job_type_schedule_materializations m
  where m.job_type_id=period_row.job_type_id
    and m.effective_month<=target_month
  order by m.effective_month desc
  limit 1;

  if materialization_row.id is null then
    raise exception 'no effective role materialization exists for job type % in %/%',
      period_row.job_type_id,period_row.month,period_row.year;
  end if;

  for day_date in
    select d::date
    from generate_series(
      target_month,
      (target_month + interval '1 month - 1 day')::date,
      interval '1 day'
    ) d
  loop
    dow_value := extract(dow from day_date)::integer;
    base_day_kind_value := case
      when dow_value=5 then 'friday'
      when dow_value=6 then 'saturday'
      else 'weekday'
    end;
    holiday_name_value := null;
    source_day_kind_value := null;

    select csd.schedule_type,csd.event_name
      into source_day_kind_value,holiday_name_value
    from public.calendar_special_days csd
    where csd.event_date=day_date
    order by
      case when csd.source_name='manual' then 0 else 1 end,
      case csd.schedule_type
        when 'holiday_full' then 1
        when 'holiday_end' then 2
        when 'holiday_eve' then 3
        when 'chol_hamoed' then 4
        else 5
      end
    limit 1;

    if source_day_kind_value is null then
      source_day_kind_value := base_day_kind_value;
    end if;

    day_behavior := 'own_templates';
    inherit_day_kind_value := null;
    day_works := true;

    select d.behavior,d.inherit_day_kind,d.works
      into day_behavior,inherit_day_kind_value,day_works
    from public.job_type_materialized_day_rules d
    where d.materialization_id=materialization_row.id
      and d.day_kind=source_day_kind_value
    limit 1;

    -- If no explicit rule exists, use the source day itself.
    day_behavior := coalesce(day_behavior,'own_templates');
    day_works := coalesce(day_works,true);

    if day_works is false or day_behavior='no_work' then
      continue;
    end if;

    -- A special calendar label must not erase the structural weekday.
    -- When a special-day rule merely inherits another day pattern, Friday and
    -- Saturday keep their own configured templates. An explicit own_templates
    -- special-day rule still wins, so role authors can intentionally override it.
    effective_day_kind_value := case
      when day_behavior='inherit'
        and source_day_kind_value <> base_day_kind_value
        and base_day_kind_value in ('friday','saturday')
        then base_day_kind_value
      when day_behavior='inherit' then coalesce(inherit_day_kind_value,source_day_kind_value)
      else source_day_kind_value
    end;

    for shift_row in
      select s.*
      from public.job_type_materialized_shift_templates s
      where s.materialization_id=materialization_row.id
        and s.day_kind=effective_day_kind_value
        and s.is_active=true
      order by s.sort_order,s.start_time,s.code
    loop
      select coalesce(jsonb_agg(jsonb_build_object(
        'type',pc.component_type,
        'multiplier',pc.multiplier,
        'hours',pc.hours,
        'label',pc.label,
        'metadata',pc.metadata
      ) order by pc.created_at),'[]'::jsonb)
      into pay_snapshot
      from public.job_type_materialized_pay_components pc
      where pc.shift_template_id=shift_row.id;

      insert into public.dynamic_availability_slots(
        period_id,
        shift_date,
        template_id,
        shift_code,
        shift_name,
        start_time,
        end_time,
        source_day_kind,
        effective_day_kind,
        holiday_name,
        min_workers,
        target_workers,
        max_workers,
        pay_segments_snapshot,
        metadata
      ) values (
        period_row.id,
        day_date,
        null,
        shift_row.code,
        shift_row.name,
        shift_row.start_time,
        shift_row.end_time,
        source_day_kind_value,
        effective_day_kind_value,
        holiday_name_value,
        shift_row.required_workers,
        shift_row.required_workers,
        shift_row.required_workers,
        pay_snapshot,
        jsonb_build_object(
          'source','dynamic_role_materialization',
          'materializationId',materialization_row.id,
          'materializedTemplateId',shift_row.id,
          'workMode',materialization_row.work_mode,
          'effectiveMonth',materialization_row.effective_month,
          'contains200Percent',shift_row.contains_200_percent,
          'premium200Hours',shift_row.premium_200_hours
        )
      )
      on conflict(period_id,shift_date,shift_code) do nothing;

      if found then
        created_slots := created_slots + 1;
      end if;
    end loop;
  end loop;

  update public.dynamic_availability_periods
  set config_snapshot = coalesce(materialization_row.source_snapshot->'availabilityConfig',config_snapshot),
      updated_at=now()
  where id=period_row.id;

  return created_slots;
end;
$$;


ALTER FUNCTION "public"."materialize_dynamic_availability_period_slots"("requested_period_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."materialize_dynamic_job_type_snapshot"("requested_job_type_id" "uuid", "requested_effective_month" "date", "requested_snapshot" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  target_materialization_id uuid;
  scheduling_config jsonb := coalesce(requested_snapshot->'schedulingConfig','{}'::jsonb);
  shift_pattern jsonb := coalesce(requested_snapshot#>'{schedulingConfig,shiftPattern}','{}'::jsonb);
  work_mode text := coalesce(requested_snapshot#>>'{schedulingConfig,shiftPattern,workMode}','shifts');
  strategy text := coalesce(requested_snapshot->>'schedulingStrategy','availability_optimizer');
  employment text := coalesce(requested_snapshot->>'employmentScope','flexible');
  schedule_change_mode_value text := coalesce(requested_snapshot#>>'{schedulingConfig,scheduleChangeMode}','none');
  day_source jsonb;
  shift_value jsonb;
  target_shift_id uuid;
  day_name text;
  day_kind_value text;
  works_value boolean;
  shift_index integer;
  shift_start time;
  shift_end time;
  premium_hours numeric(6,2);
  shift_hours numeric;
  apply_holiday_eve boolean := coalesce((shift_pattern#>>'{friday,applyToHolidayEve}')::boolean,false);
  apply_holiday_end boolean := coalesce((shift_pattern#>>'{saturday,applyToHolidayEnd}')::boolean,false);
begin
  if requested_job_type_id is null then raise exception 'job type is required'; end if;
  if requested_effective_month is null then raise exception 'effective month is required'; end if;
  if jsonb_typeof(requested_snapshot)<>'object' then raise exception 'snapshot must be an object'; end if;
  if work_mode not in ('shifts','on_call_hourly','on_call_daily') then raise exception 'invalid work mode: %',work_mode; end if;
  if schedule_change_mode_value not in ('none','shift_exchange','self_edit') then raise exception 'invalid schedule change mode: %',schedule_change_mode_value; end if;

  insert into public.job_type_schedule_materializations(
    job_type_id,effective_month,work_mode,scheduling_strategy,employment_scope,schedule_change_mode,source_snapshot,schema_version,generated_at
  ) values(
    requested_job_type_id,date_trunc('month',requested_effective_month)::date,work_mode,strategy,employment,schedule_change_mode_value,requested_snapshot,2,now()
  )
  on conflict(job_type_id,effective_month) do update set
    work_mode=excluded.work_mode,
    scheduling_strategy=excluded.scheduling_strategy,
    employment_scope=excluded.employment_scope,
    schedule_change_mode=excluded.schedule_change_mode,
    source_snapshot=excluded.source_snapshot,
    schema_version=excluded.schema_version,
    generated_at=now(),
    updated_at=now()
  returning id into target_materialization_id;

  -- A re-save of the same effective month is a deterministic rebuild.
  delete from public.job_type_materialized_day_rules where materialization_id=target_materialization_id;
  delete from public.job_type_materialized_shift_templates where materialization_id=target_materialization_id;

  foreach day_name in array array['weekday','friday','saturday','holiday'] loop
    day_source := coalesce(shift_pattern->day_name,'{}'::jsonb);
    works_value := coalesce((day_source->>'works')::boolean,true);
    day_kind_value := case day_name when 'holiday' then 'holiday_full' else day_name end;

    insert into public.job_type_materialized_day_rules(materialization_id,day_kind,works,behavior,inherit_day_kind,metadata)
    values(
      target_materialization_id,
      day_kind_value,
      works_value,
      case when works_value then 'own_templates' else 'no_work' end,
      null,
      jsonb_build_object('sourceDay',day_name)
    );

    if works_value then
      if work_mode='on_call_daily' then
        insert into public.job_type_materialized_shift_templates(
          materialization_id,source_shift_id,code,name,day_kind,start_time,end_time,required_workers,sort_order,is_active,metadata
        ) values(
          target_materialization_id,day_name||'-daily',day_name||'_daily_on_call','כוננות יומית',day_kind_value,
          time '00:00',time '23:59',1,10,true,jsonb_build_object('allDay',true,'workMode',work_mode)
        );
      else
        shift_index := 0;
        for shift_value in select value from jsonb_array_elements(coalesce(day_source->'shifts','[]'::jsonb)) loop
          shift_index := shift_index + 1;
          shift_start := coalesce(nullif(shift_value->>'startTime','')::time,time '00:00');
          shift_end := coalesce(nullif(shift_value->>'endTime','')::time,time '00:00');
          premium_hours := greatest(0,coalesce(nullif(shift_value->>'premium200Hours','')::numeric,0));
          shift_hours := mod(
            (extract(hour from shift_end)::integer*60 + extract(minute from shift_end)::integer)
            - (extract(hour from shift_start)::integer*60 + extract(minute from shift_start)::integer)
            + 1440,
            1440
          ) / 60.0;
          if shift_hours=0 then shift_hours:=24; end if;
          premium_hours := least(premium_hours,shift_hours);

          insert into public.job_type_materialized_shift_templates(
            materialization_id,source_shift_id,code,name,day_kind,start_time,end_time,required_workers,sort_order,is_active,
            contains_200_percent,premium_200_hours,metadata
          ) values(
            target_materialization_id,
            nullif(shift_value->>'id',''),
            day_name||'_'||shift_index::text,
            coalesce(nullif(shift_value->>'name',''),case when work_mode='on_call_hourly' then 'חלון כוננות '||shift_index else 'משמרת '||shift_index end),
            day_kind_value,
            shift_start,
            shift_end,
            greatest(1,coalesce(nullif(shift_value->>'requiredWorkers','')::integer,1)),
            shift_index*10,
            true,
            coalesce((shift_value->>'contains200Percent')::boolean,false),
            case when coalesce((shift_value->>'contains200Percent')::boolean,false) then premium_hours else 0 end,
            jsonb_build_object('workMode',work_mode,'sourceDefinition',shift_value)
          ) returning id into target_shift_id;

          if coalesce((shift_value->>'contains200Percent')::boolean,false) and premium_hours>0 then
            insert into public.job_type_materialized_pay_components(
              shift_template_id,component_type,multiplier,hours,label,metadata
            ) values(
              target_shift_id,'premium_hours',2.0,premium_hours,'רכיב 200%',
              jsonb_build_object('boundaryKnown',false,'source','role_definition')
            );
          end if;
        end loop;
      end if;
    end if;
  end loop;

  -- Calendar-special-day inheritance is explicit and versioned with the role.
  insert into public.job_type_materialized_day_rules(materialization_id,day_kind,works,behavior,inherit_day_kind,metadata)
  values(
    target_materialization_id,'holiday_eve',true,'inherit',case when apply_holiday_eve then 'friday' else 'weekday' end,
    jsonb_build_object('usesFridayTemplate',apply_holiday_eve)
  )
  on conflict(materialization_id,day_kind) do update set
    works=excluded.works,behavior=excluded.behavior,inherit_day_kind=excluded.inherit_day_kind,metadata=excluded.metadata;

  insert into public.job_type_materialized_day_rules(materialization_id,day_kind,works,behavior,inherit_day_kind,metadata)
  values(
    target_materialization_id,'holiday_end',true,'inherit',case when apply_holiday_end then 'saturday' else 'weekday' end,
    jsonb_build_object('usesSaturdayTemplate',apply_holiday_end)
  )
  on conflict(materialization_id,day_kind) do update set
    works=excluded.works,behavior=excluded.behavior,inherit_day_kind=excluded.inherit_day_kind,metadata=excluded.metadata;

  insert into public.job_type_materialized_day_rules(materialization_id,day_kind,works,behavior,inherit_day_kind,metadata)
  values(target_materialization_id,'chol_hamoed',true,'inherit','weekday','{"source":"default"}'::jsonb)
  on conflict(materialization_id,day_kind) do update set
    works=excluded.works,behavior=excluded.behavior,inherit_day_kind=excluded.inherit_day_kind,metadata=excluded.metadata;

  return target_materialization_id;
end;
$$;


ALTER FUNCTION "public"."materialize_dynamic_job_type_snapshot"("requested_job_type_id" "uuid", "requested_effective_month" "date", "requested_snapshot" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."normalize_schedule_import_name"("requested_name" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select
    lower(
      regexp_replace(
        trim(
          coalesce(
            requested_name,
            ''
          )
        ),
        '\s+',
        ' ',
        'g'
      )
    );
$$;


ALTER FUNCTION "public"."normalize_schedule_import_name"("requested_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."open_availability_period"("requested_period_id" "uuid") RETURNS TABLE("period_id" "uuid", "period_status" "text", "opened_at" timestamp with time zone, "shift_slots_count" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  current_user_id uuid;

  current_actor_email text;
  current_actor_display_name text;

  target_period_title text;
  target_year integer;
  target_month integer;
  target_status text;

  target_opened_at timestamptz;
  target_slots_count integer;
begin
  current_user_id := auth.uid();

  if current_user_id is null then
    raise exception
      'User is not authenticated';
  end if;

  select
    profile.email,
    profile.display_name
  into
    current_actor_email,
    current_actor_display_name
  from public.profiles profile
  where profile.id = current_user_id
    and profile.is_active = true;

  if current_actor_email is null then
    raise exception
      'Authenticated user is not active';
  end if;

  if not exists (
    select 1
    from public.user_permissions permission
    where permission.user_id =
      current_user_id
      and permission.permission_key =
        'availability.manage'
  ) then
    raise exception
      'User is not allowed to manage availability periods';
  end if;

  if requested_period_id is null then
    raise exception
      'Availability period id is required';
  end if;

  select
    period.title,
    period.year,
    period.month,
    period.status
  into
    target_period_title,
    target_year,
    target_month,
    target_status
  from public.availability_periods period
  where period.id =
    requested_period_id
  for update;

  if target_year is null then
    raise exception
      'Availability period was not found';
  end if;

  if target_status <> 'draft' then
    raise exception
      'Only draft availability periods can be opened';
  end if;

  select
    count(*)::integer
  into
    target_slots_count
  from public.availability_shift_slots slot
  where slot.period_id =
    requested_period_id;

  if target_slots_count = 0 then
    raise exception
      'Availability period does not contain shift slots';
  end if;

  target_opened_at := now();

  update public.availability_periods period
  set
    status = 'open',
    opened_at = target_opened_at,
    closed_at = null,
    updated_by = current_user_id,
    updated_at = now()
  where period.id =
    requested_period_id;

  insert into public.availability_submissions (
    period_id,
    user_id,
    status,
    submitted_at,
    reopened_at,
    last_saved_at,
    available_count,
    unavailable_count
  )
  select
    requested_period_id,
    profile.id,
    'draft',
    null,
    null,
    null,
    0,
    0
  from public.profiles profile
  where profile.role::text =
    'dispatcher'
    and profile.is_active = true
  on conflict on constraint
    availability_submissions_unique
  do nothing;

  insert into public.audit_logs (
    action,

    actor_user_id,
    actor_email,
    actor_display_name,

    target_user_id,
    target_email,
    target_display_name,

    entity_type,
    summary,

    old_values,
    new_values,
    metadata
  )
  values (
    'availability_period_opened',

    current_user_id,
    current_actor_email,
    current_actor_display_name,

    null,
    null,
    null,

    'availability_period',

    format(
      'נפתחה תקופת אילוצים להגשה: %s',
      coalesce(
        target_period_title,
        format(
          '%s/%s',
          target_month,
          target_year
        )
      )
    ),

    jsonb_build_object(
      'status',
      'draft'
    ),

    jsonb_build_object(
      'status',
      'open',
      'opened_at',
      target_opened_at,
      'shift_slots_count',
      target_slots_count
    ),

    jsonb_build_object(
      'source',
      'open-availability-period-rpc',

      'period_id',
      requested_period_id,

      'year',
      target_year,

      'month',
      target_month
    )
  );

  return query
  select
    requested_period_id,
    'open'::text,
    target_opened_at,
    target_slots_count;
end;
$$;


ALTER FUNCTION "public"."open_availability_period"("requested_period_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."open_driver_availability_period"("requested_period_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  current_user_id uuid;

  current_permissions text[];

  target_period
    public.driver_availability_periods%rowtype;

  period_days_count integer;
begin
  current_user_id :=
    auth.uid();

  if current_user_id is null then
    raise exception
      'not authenticated';
  end if;

  if not exists (
    select 1
    from public.profiles
    where id = current_user_id
      and is_active = true
  ) then
    raise exception
      'user not active';
  end if;

  current_permissions :=
    coalesce(
      public.get_my_permissions(),
      array[]::text[]
    );

  if not (
    'driver_availability.manage' =
      any(current_permissions)
  ) then
    raise exception
      'not allowed';
  end if;

  if requested_period_id is null then
    raise exception
      'driver availability period id is required';
  end if;

  select *
  into target_period
  from public.driver_availability_periods
  where id =
    requested_period_id
  for update;

  if not found then
    raise exception
      'driver availability period not found';
  end if;

  if target_period.status = 'open' then
    select
      count(*)::integer
    into period_days_count
    from public.driver_availability_days
    where period_id =
      target_period.id;

    return jsonb_build_object(
      'periodId',
        target_period.id,

      'year',
        target_period.year,

      'month',
        target_period.month,

      'status',
        target_period.status,

      'openedAt',
        target_period.opened_at,

      'daysCount',
        period_days_count,

      'alreadyOpen',
        true
    );
  end if;

  if target_period.status <> 'draft' then
    raise exception
      'only draft driver availability periods can be opened';
  end if;

  select
    count(*)::integer
  into period_days_count
  from public.driver_availability_days
  where period_id =
    target_period.id;

  if period_days_count = 0 then
    raise exception
      'driver availability period has no days';
  end if;

  update public.driver_availability_periods
  set
    status =
      'open',

    opened_at =
      now(),

    closed_at =
      null,

    updated_by =
      current_user_id,

    updated_at =
      now()

  where id =
    target_period.id

  returning *
  into target_period;

  return jsonb_build_object(
    'periodId',
      target_period.id,

    'year',
      target_period.year,

    'month',
      target_period.month,

    'status',
      target_period.status,

    'openedAt',
      target_period.opened_at,

    'daysCount',
      period_days_count,

    'alreadyOpen',
      false
  );
end;
$$;


ALTER FUNCTION "public"."open_driver_availability_period"("requested_period_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."open_driver_availability_period"("requested_period_id" "uuid") IS 'Opens a draft driver availability period for submissions. Requires driver_availability.manage.';



CREATE OR REPLACE FUNCTION "public"."open_morning_driver_availability_period"("requested_period_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  current_user_id uuid;
  current_permissions text[];

  target_period
    public.morning_driver_availability_periods%rowtype;

  created_submissions integer := 0;
begin
  current_user_id :=
    auth.uid();

  if current_user_id is null then
    raise exception
      'not authenticated';
  end if;

  current_permissions :=
    coalesce(
      public.get_my_permissions(),
      array[]::text[]
    );

  if not (
    'morning_driver_availability.manage'
      = any(current_permissions)
  ) then
    raise exception
      'not allowed';
  end if;

  if requested_period_id is null then
    raise exception
      'period id is required';
  end if;

  select *
  into target_period
  from public.morning_driver_availability_periods
  where id = requested_period_id
  for update;

  if not found then
    raise exception
      'morning driver availability period not found';
  end if;

  if target_period.status <> 'draft' then
    raise exception
      'only draft periods can be opened';
  end if;

  insert into public.morning_driver_availability_submissions (
    period_id,
    user_id,
    status
  )
  select
    target_period.id,
    profile.id,
    'draft'
  from public.profiles profile
  where profile.role =
      'morning_driver'::public.user_role
    and profile.is_active = true
  on conflict (
    period_id,
    user_id
  )
  do nothing;

  get diagnostics
    created_submissions =
      row_count;

  update public.morning_driver_availability_periods
  set
    status = 'open',
    opened_at = now(),
    updated_by = current_user_id,
    updated_at = now()
  where id = target_period.id
  returning *
  into target_period;

  perform public.write_audit_log(
    requested_action :=
      'morning_driver_availability_period_opened'
        ::public.audit_action_type,

    requested_target_user_id :=
      null,

    requested_summary :=
      'נפתח חודש אילוצים לכונני בוקר',

    requested_old_values :=
      jsonb_build_object(
        'status',
          'draft'
      ),

    requested_new_values :=
      jsonb_build_object(
        'status',
          target_period.status,

        'openedAt',
          target_period.opened_at
      ),

    requested_metadata :=
      jsonb_build_object(
        'periodId',
          target_period.id,

        'year',
          target_period.year,

        'month',
          target_period.month,

        'createdSubmissions',
          created_submissions
      )
  );

  return jsonb_build_object(
    'periodId',
      target_period.id,

    'year',
      target_period.year,

    'month',
      target_period.month,

    'status',
      target_period.status,

    'openedAt',
      target_period.opened_at,

    'createdSubmissions',
      created_submissions
  );
end;
$$;


ALTER FUNCTION "public"."open_morning_driver_availability_period"("requested_period_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."prepare_my_daily_report_upload"("requested_job_type_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor uuid:=auth.uid();
  today_il date:=(now() at time zone 'Asia/Jerusalem')::date;
  target_report_id uuid;
begin
  if actor is null then raise exception 'not authenticated'; end if;

  if not public.has_dynamic_job_type_permission('daily_reports.submit',requested_job_type_id,actor)
     or not public.has_dynamic_job_type_permission('daily_reports.upload_attachment',requested_job_type_id,actor)
  then raise exception 'not allowed'; end if;

  if not exists(
    select 1 from public.job_types jt
    where jt.id=requested_job_type_id
      and jt.is_active=true
      and jt.legacy_role is null
      and coalesce((jt.scheduling_config#>>'{dailyReports,allowAttachments}')::boolean,true)
  ) then raise exception 'attachments are disabled'; end if;

  insert into public.daily_reports(
    job_type_id,user_id,report_date,status,submitted_at,updated_at
  )
  values(
    requested_job_type_id,actor,today_il,'draft',null,now()
  )
  on conflict(job_type_id,user_id,report_date)
  do update set
    status='draft',
    submitted_at=null,
    updated_at=now()
  returning daily_reports.id into target_report_id;

  return jsonb_build_object('reportId',target_report_id);
end;
$$;


ALTER FUNCTION "public"."prepare_my_daily_report_upload"("requested_job_type_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."preview_dynamic_legacy_import"("requested_job_type_id" "uuid", "requested_source_kind" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  current_user_id uuid := auth.uid();
  periods_count integer := 0;
  assignments_count integer := 0;
  availability_count integer := 0;
  imported_periods integer := 0;
  imported_assignments integer := 0;
  imported_availability integer := 0;
  expected_role text;
  period_details jsonb := '[]'::jsonb;
  user_details jsonb := '[]'::jsonb;
  issues jsonb := '[]'::jsonb;
  referenced_users integer := 0;
  missing_profiles integer := 0;
  role_mismatches integer := 0;
  current_ym integer := extract(year from (now() at time zone 'Asia/Jerusalem'))::integer * 100
    + extract(month from (now() at time zone 'Asia/Jerusalem'))::integer;
begin
  if current_user_id is null then
    raise exception 'not authenticated';
  end if;

  if not exists (
    select 1
    from public.user_permissions up
    where up.user_id = current_user_id
      and up.permission_key = 'users.manage'
  ) then
    raise exception 'not allowed';
  end if;

  if requested_source_kind not in ('dispatcher','on_call','morning_driver') then
    raise exception 'invalid source kind';
  end if;

  if not exists (select 1 from public.job_types where id = requested_job_type_id) then
    raise exception 'job type not found';
  end if;

  if requested_source_kind = 'dispatcher' then
    expected_role := 'dispatcher';

    select count(*)::integer into periods_count
    from public.schedule_periods p
    where p.status::text in ('published','archived')
      and (p.year * 100 + p.month) < current_ym;

    select count(*)::integer into assignments_count
    from public.schedule_shifts s
    join public.schedule_periods p on p.id = s.period_id
    where p.status::text in ('published','archived')
      and (p.year * 100 + p.month) < current_ym;

    select count(*)::integer into availability_count
    from public.dispatcher_availability a
    join public.availability_periods ap on ap.id = a.period_id
    join public.availability_shift_slots slot on slot.id = a.shift_slot_id
    where exists (
      select 1 from public.schedule_periods p
      where p.year = ap.year and p.month = ap.month
        and p.status::text in ('published','archived')
        and (p.year * 100 + p.month) < current_ym
    );

    select coalesce(jsonb_agg(jsonb_build_object(
      'sourcePeriodId', p.id,
      'year', p.year,
      'month', p.month,
      'label', lpad(p.month::text,2,'0') || '/' || p.year::text,
      'status', p.status::text,
      'assignments', (select count(*) from public.schedule_shifts s where s.period_id=p.id),
      'availability', (
        select count(*)
        from public.dispatcher_availability a
        join public.availability_periods ap on ap.id=a.period_id
        where ap.year=p.year and ap.month=p.month
      ),
      'alreadyImported', exists(
        select 1 from public.dynamic_historical_periods hp
        where hp.job_type_id=requested_job_type_id
          and hp.source_kind='dispatcher'
          and hp.source_period_id=p.id
      )
    ) order by p.year,p.month),'[]'::jsonb)
    into period_details
    from public.schedule_periods p
    where p.status::text in ('published','archived')
      and (p.year * 100 + p.month) < current_ym;

    with legacy_user_ids as (
      select s.assigned_user_id as user_id
      from public.schedule_shifts s
      join public.schedule_periods p on p.id=s.period_id
      where p.status::text in ('published','archived')
        and (p.year * 100 + p.month) < current_ym
        and s.assigned_user_id is not null
      union
      select a.user_id
      from public.dispatcher_availability a
      join public.availability_periods ap on ap.id=a.period_id
      where exists (
        select 1 from public.schedule_periods p
        where p.year=ap.year and p.month=ap.month
          and p.status::text in ('published','archived')
          and (p.year * 100 + p.month) < current_ym
      )
    )
    select
      count(*)::integer,
      count(*) filter (where p.id is null)::integer,
      count(*) filter (where p.id is not null and p.role::text <> expected_role)::integer,
      coalesce(jsonb_agg(jsonb_build_object(
        'userId', u.user_id,
        'displayName', coalesce(p.display_name,'משתמש שלא נמצא'),
        'email', p.email,
        'legacyRole', case when p.id is null then null else p.role::text end,
        'expectedLegacyRole', expected_role,
        'isActive', coalesce(p.is_active,false),
        'isAlreadyMember', exists(
          select 1 from public.job_type_memberships jm
          where jm.job_type_id=requested_job_type_id and jm.user_id=u.user_id
        ),
        'status', case
          when p.id is null then 'missing_profile'
          when p.role::text <> expected_role then 'role_mismatch'
          else 'matched'
        end
      ) order by coalesce(p.display_name,u.user_id::text)),'[]'::jsonb)
    into referenced_users, missing_profiles, role_mismatches, user_details
    from legacy_user_ids u
    left join public.profiles p on p.id=u.user_id;

  elsif requested_source_kind = 'on_call' then
    expected_role := 'on_call';

    select count(*)::integer into periods_count
    from public.driver_schedule_periods p where p.status::text in ('published','archived')
      and (p.year * 100 + p.month) < current_ym;

    select count(*)::integer into assignments_count
    from public.driver_schedule_days d
    join public.driver_schedule_periods p on p.id=d.period_id
    where p.status::text in ('published','archived')
      and (p.year * 100 + p.month) < current_ym;

    select coalesce(jsonb_agg(jsonb_build_object(
      'sourcePeriodId', p.id,
      'year', p.year,
      'month', p.month,
      'label', lpad(p.month::text,2,'0') || '/' || p.year::text,
      'status', p.status::text,
      'assignments', (select count(*) from public.driver_schedule_days d where d.period_id=p.id),
      'availability', 0,
      'alreadyImported', exists(
        select 1 from public.dynamic_historical_periods hp
        where hp.job_type_id=requested_job_type_id
          and hp.source_kind='on_call'
          and hp.source_period_id=p.id
      )
    ) order by p.year,p.month),'[]'::jsonb)
    into period_details
    from public.driver_schedule_periods p
    where p.status::text in ('published','archived')
      and (p.year * 100 + p.month) < current_ym;

    with legacy_user_ids as (
      select d.assigned_user_id as user_id
      from public.driver_schedule_days d
      join public.driver_schedule_periods p on p.id=d.period_id
      where p.status::text in ('published','archived')
        and (p.year * 100 + p.month) < current_ym
        and d.assigned_user_id is not null
      union
      select d.original_user_id
      from public.driver_schedule_days d
      join public.driver_schedule_periods p on p.id=d.period_id
      where p.status::text in ('published','archived')
        and (p.year * 100 + p.month) < current_ym
        and d.original_user_id is not null
    )
    select
      count(*)::integer,
      count(*) filter (where p.id is null)::integer,
      count(*) filter (where p.id is not null and p.role::text <> expected_role)::integer,
      coalesce(jsonb_agg(jsonb_build_object(
        'userId', u.user_id,
        'displayName', coalesce(p.display_name,'משתמש שלא נמצא'),
        'email', p.email,
        'legacyRole', case when p.id is null then null else p.role::text end,
        'expectedLegacyRole', expected_role,
        'isActive', coalesce(p.is_active,false),
        'isAlreadyMember', exists(
          select 1 from public.job_type_memberships jm
          where jm.job_type_id=requested_job_type_id and jm.user_id=u.user_id
        ),
        'status', case when p.id is null then 'missing_profile' when p.role::text<>expected_role then 'role_mismatch' else 'matched' end
      ) order by coalesce(p.display_name,u.user_id::text)),'[]'::jsonb)
    into referenced_users, missing_profiles, role_mismatches, user_details
    from legacy_user_ids u
    left join public.profiles p on p.id=u.user_id;

  else
    expected_role := 'morning_driver';

    select count(*)::integer into periods_count
    from public.morning_driver_schedule_periods p where p.status::text in ('published','archived')
      and (p.year * 100 + p.month) < current_ym;

    select count(*)::integer into assignments_count
    from public.morning_driver_schedule_assignments a
    join public.morning_driver_schedule_periods p on p.id=a.schedule_period_id
    where p.status::text in ('published','archived')
      and (p.year * 100 + p.month) < current_ym;

    select count(*)::integer into availability_count
    from public.morning_driver_availability_entries e
    join public.morning_driver_schedule_periods sp on sp.availability_period_id=e.period_id
    where sp.status::text in ('published','archived')
      and (sp.year * 100 + sp.month) < current_ym;

    select coalesce(jsonb_agg(jsonb_build_object(
      'sourcePeriodId', p.id,
      'year', p.year,
      'month', p.month,
      'label', lpad(p.month::text,2,'0') || '/' || p.year::text,
      'status', p.status::text,
      'assignments', (select count(*) from public.morning_driver_schedule_assignments a where a.schedule_period_id=p.id),
      'availability', (
        select count(*) from public.morning_driver_availability_entries e
        where e.period_id=p.availability_period_id
      ),
      'alreadyImported', exists(
        select 1 from public.dynamic_historical_periods hp
        where hp.job_type_id=requested_job_type_id
          and hp.source_kind='morning_driver'
          and hp.source_period_id=p.id
      )
    ) order by p.year,p.month),'[]'::jsonb)
    into period_details
    from public.morning_driver_schedule_periods p
    where p.status::text in ('published','archived')
      and (p.year * 100 + p.month) < current_ym;

    with legacy_user_ids as (
      select a.assigned_user_id as user_id
      from public.morning_driver_schedule_assignments a
      join public.morning_driver_schedule_periods p on p.id=a.schedule_period_id
      where p.status::text in ('published','archived')
        and (p.year * 100 + p.month) < current_ym
        and a.assigned_user_id is not null
      union
      select e.user_id
      from public.morning_driver_availability_entries e
      join public.morning_driver_schedule_periods sp on sp.availability_period_id=e.period_id
      where sp.status::text in ('published','archived')
      and (sp.year * 100 + sp.month) < current_ym
    )
    select
      count(*)::integer,
      count(*) filter (where p.id is null)::integer,
      count(*) filter (where p.id is not null and p.role::text <> expected_role)::integer,
      coalesce(jsonb_agg(jsonb_build_object(
        'userId', u.user_id,
        'displayName', coalesce(p.display_name,'משתמש שלא נמצא'),
        'email', p.email,
        'legacyRole', case when p.id is null then null else p.role::text end,
        'expectedLegacyRole', expected_role,
        'isActive', coalesce(p.is_active,false),
        'isAlreadyMember', exists(
          select 1 from public.job_type_memberships jm
          where jm.job_type_id=requested_job_type_id and jm.user_id=u.user_id
        ),
        'status', case when p.id is null then 'missing_profile' when p.role::text<>expected_role then 'role_mismatch' else 'matched' end
      ) order by coalesce(p.display_name,u.user_id::text)),'[]'::jsonb)
    into referenced_users, missing_profiles, role_mismatches, user_details
    from legacy_user_ids u
    left join public.profiles p on p.id=u.user_id;
  end if;

  select count(*)::integer into imported_periods
  from public.dynamic_historical_periods
  where job_type_id=requested_job_type_id and source_kind=requested_source_kind
    and (year * 100 + month) < current_ym;

  select count(*)::integer into imported_assignments
  from public.dynamic_historical_assignments a
  join public.dynamic_historical_periods p on p.id=a.historical_period_id
  where p.job_type_id=requested_job_type_id and a.source_kind=requested_source_kind
    and (p.year * 100 + p.month) < current_ym;

  select count(*)::integer into imported_availability
  from public.dynamic_historical_availability a
  join public.dynamic_historical_periods p on p.id=a.historical_period_id
  where p.job_type_id=requested_job_type_id and a.source_kind=requested_source_kind
    and (p.year * 100 + p.month) < current_ym;

  issues := issues || jsonb_build_array(jsonb_build_object(
    'severity','info',
    'code','current_month_excluded',
    'message','החודש הנוכחי אינו נכלל בייבוא היסטוריה; הוא יטופל בנפרד בעת המעבר למערכת הדינמית'
  ));

  if periods_count = 0 then
    issues := issues || jsonb_build_array(jsonb_build_object('severity','warning','code','no_periods','message','לא נמצאו תקופות מפורסמות או ארכיוניות במערכת המקור'));
  end if;
  if missing_profiles > 0 then
    issues := issues || jsonb_build_array(jsonb_build_object('severity','error','code','missing_profiles','message',missing_profiles::text || ' משתמשים שמופיעים בהיסטוריה אינם קיימים עוד בטבלת המשתמשים'));
  end if;
  if role_mismatches > 0 then
    issues := issues || jsonb_build_array(jsonb_build_object('severity','warning','code','role_mismatch','message',role_mismatches::text || ' משתמשים היסטוריים קיימים אך ה-role הישן שלהם השתנה'));
  end if;

  return jsonb_build_object(
    'sourceKind', requested_source_kind,
    'expectedLegacyRole', expected_role,
    'periods', periods_count,
    'assignments', assignments_count,
    'availability', availability_count,
    'alreadyImportedPeriods', imported_periods,
    'alreadyImportedAssignments', imported_assignments,
    'alreadyImportedAvailability', imported_availability,
    'newPeriods', greatest(periods_count-imported_periods,0),
    'newAssignments', greatest(assignments_count-imported_assignments,0),
    'newAvailability', greatest(availability_count-imported_availability,0),
    'matchingUsers', (select count(*) from public.profiles p where p.role::text=expected_role),
    'referencedUsers', referenced_users,
    'missingProfiles', missing_profiles,
    'roleMismatches', role_mismatches,
    'periodDetails', period_details,
    'userDetails', user_details,
    'issues', issues,
    'canImport', periods_count > 0 and missing_profiles = 0,
    'warning', 'הייבוא מעתיק היסטוריה בלבד ואינו מוחק או משנה נתונים במערכת הישנה'
  );
end;
$$;


ALTER FUNCTION "public"."preview_dynamic_legacy_import"("requested_job_type_id" "uuid", "requested_source_kind" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."preview_dynamic_schedule_group"("requested_group_id" "uuid", "requested_year" integer, "requested_month" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  current_user_id uuid := auth.uid();
  first_date date;
  next_month date;
begin
  if current_user_id is null then raise exception 'not authenticated'; end if;
  if not exists (select 1 from public.profiles p where p.id=current_user_id and p.is_active=true) then raise exception 'user not active'; end if;
  if not exists (select 1 from public.user_permissions up where up.user_id=current_user_id and up.permission_key in ('users.view','users.manage')) then raise exception 'not allowed'; end if;
  if not exists (select 1 from public.schedule_groups sg where sg.id=requested_group_id) then raise exception 'schedule group not found'; end if;
  if requested_year not between 2020 and 2100 or requested_month not between 1 and 12 then raise exception 'invalid year or month'; end if;

  first_date := make_date(requested_year,requested_month,1);
  next_month := (first_date + interval '1 month')::date;

  return jsonb_build_object(
    'year', requested_year,
    'month', requested_month,
    'groupId', requested_group_id,
    'days', coalesce((
      with dates as (
        select d::date as day_date, extract(dow from d)::integer as dow
        from generate_series(first_date, next_month-1, interval '1 day') d
      ), classified as (
        select d.day_date, d.dow,
          coalesce(sd.schedule_type,
            case when d.dow=5 then 'friday' when d.dow=6 then 'saturday' else 'weekday' end
          ) as source_day_kind,
          sd.event_name as holiday_name
        from dates d
        left join lateral (
          select csd.schedule_type, csd.event_name
          from public.calendar_special_days csd
          where csd.event_date=d.day_date
          order by case when csd.source_name='manual' then 0 else 1 end,
                   case csd.schedule_type when 'holiday_full' then 1 when 'holiday_end' then 2 when 'holiday_eve' then 3 when 'chol_hamoed' then 4 else 5 end
          limit 1
        ) sd on true
      ), resolved as (
        select c.*,
          coalesce(dr.behavior,'own_templates') as behavior,
          dr.inherit_day_kind,
          case
            when dr.behavior='no_work' then null
            when dr.behavior='inherit' then dr.inherit_day_kind
            else c.source_day_kind
          end as effective_day_kind
        from classified c
        left join public.schedule_group_day_rules dr
          on dr.schedule_group_id=requested_group_id and dr.day_kind=c.source_day_kind
      )
      select jsonb_agg(
        jsonb_build_object(
          'date', r.day_date,
          'weekdayName', case r.dow when 0 then 'ראשון' when 1 then 'שני' when 2 then 'שלישי' when 3 then 'רביעי' when 4 then 'חמישי' when 5 then 'שישי' when 6 then 'שבת' end,
          'sourceDayKind', r.source_day_kind,
          'effectiveDayKind', r.effective_day_kind,
          'holidayName', r.holiday_name,
          'isNoWork', r.behavior='no_work',
          'shifts', case when r.behavior='no_work' then '[]'::jsonb else coalesce((
            select jsonb_agg(
              jsonb_build_object(
                'templateId', st.id,
                'code', st.code,
                'name', st.name,
                'startTime', st.start_time,
                'endTime', st.end_time,
                'minWorkers', st.required_workers,
                'targetWorkers', st.target_workers,
                'maxWorkers', st.max_workers,
                'paySegments', coalesce((
                  select jsonb_agg(jsonb_build_object(
                    'startTime', ps.start_time,
                    'endTime', ps.end_time,
                    'multiplier', ps.multiplier,
                    'label', ps.label
                  ) order by ps.sort_order, ps.start_time)
                  from public.schedule_shift_pay_segments ps
                  where ps.shift_template_id=st.id
                ), '[]'::jsonb)
              ) order by st.sort_order, st.start_time
            )
            from public.schedule_group_shift_templates st
            where st.schedule_group_id=requested_group_id
              and st.day_kind=r.effective_day_kind
              and st.is_active=true
          ), '[]'::jsonb) end
        ) order by r.day_date
      ) from resolved r
    ), '[]'::jsonb)
  );
end;
$$;


ALTER FUNCTION "public"."preview_dynamic_schedule_group"("requested_group_id" "uuid", "requested_year" integer, "requested_month" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."preview_gvk_legacy_migration"("requested_mappings" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_actor uuid := auth.uid();
  requested_dispatcher_job_type_id uuid := nullif(requested_mappings->>'dispatcher','')::uuid;
  requested_on_call_job_type_id uuid := nullif(requested_mappings->>'on_call','')::uuid;
  requested_morning_driver_job_type_id uuid := nullif(requested_mappings->>'morning_driver','')::uuid;
  v_current_ym integer := extract(year from (now() at time zone 'Asia/Jerusalem'))::integer * 100
    + extract(month from (now() at time zone 'Asia/Jerusalem'))::integer;
  v_blockers jsonb := '[]'::jsonb;
  v_warnings jsonb := '[]'::jsonb;
  v_result jsonb;
begin
  if v_actor is null and current_user not in ('postgres','supabase_admin','service_role') then
    raise exception 'not authenticated';
  end if;
  if v_actor is not null and not exists(
    select 1 from public.user_permissions up
    where up.user_id=v_actor and up.permission_key='users.manage'
  ) then
    raise exception 'not allowed';
  end if;

  if requested_dispatcher_job_type_id is null
     or requested_on_call_job_type_id is null
     or requested_morning_driver_job_type_id is null then
    raise exception 'GVK adapter requires mappings for dispatcher, on_call and morning_driver';
  end if;

  if requested_dispatcher_job_type_id = requested_on_call_job_type_id
     or requested_dispatcher_job_type_id = requested_morning_driver_job_type_id
     or requested_on_call_job_type_id = requested_morning_driver_job_type_id then
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
      'code','duplicate_target_job_type',
      'message','כל מערכת Legacy חייבת להיות ממופה לתפקיד דינמי נפרד'
    ));
  end if;

  if exists (
    select 1 from (values
      (requested_dispatcher_job_type_id),
      (requested_on_call_job_type_id),
      (requested_morning_driver_job_type_id)
    ) x(id)
    left join public.job_types jt on jt.id=x.id
    where jt.id is null or jt.is_active=false
  ) then
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
      'code','missing_or_inactive_target',
      'message','אחד מתפקידי היעד לא קיים או מוקפא'
    ));
  end if;

  -- We do not auto-convert an unfinished live workflow. A published/archived
  -- schedule is stable and can be copied safely; an open/draft workflow must
  -- be finished or restarted in the dynamic system.
  if exists (
    select 1 from public.schedule_periods p
    where (p.year*100+p.month) >= v_current_ym
      and p.status::text not in ('published','archived')
  ) then
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
      'code','dispatcher_unfinished_period',
      'message','קיימת תקופת מוקדנים פעילה/לא מפורסמת במערכת הישנה. יש לסיים או לבטל אותה לפני המיגרציה המלאה.'
    ));
  end if;

  if exists (
    select 1 from public.driver_schedule_periods p
    where (p.year*100+p.month) >= v_current_ym
      and p.status::text not in ('published','archived')
  ) then
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
      'code','on_call_unfinished_period',
      'message','קיימת תקופת כוננים פעילה/לא מפורסמת במערכת הישנה. יש לסיים או לבטל אותה לפני המיגרציה המלאה.'
    ));
  end if;

  if exists (
    select 1 from public.morning_driver_schedule_periods p
    where (p.year*100+p.month) >= v_current_ym
      and p.status::text not in ('published','archived')
  ) then
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
      'code','morning_driver_unfinished_period',
      'message','קיימת תקופת כונני בוקר פעילה/לא מפורסמת במערכת הישנה. יש לסיים או לבטל אותה לפני המיגרציה המלאה.'
    ));
  end if;

  -- Existing dynamic publications are intentionally not overwritten.
  if exists (
    select 1
    from public.dynamic_schedule_publications dp
    join (values
      (requested_dispatcher_job_type_id),
      (requested_on_call_job_type_id),
      (requested_morning_driver_job_type_id)
    ) x(id) on x.id=dp.job_type_id
    where (dp.year*100+dp.month) >= v_current_ym
  ) then
    v_warnings := v_warnings || jsonb_build_array(jsonb_build_object(
      'code','existing_dynamic_publications',
      'message','קיימים כבר לוחות דינמיים בחודש הנוכחי או בחודשים עתידיים. המיגרציה לא תדרוס אותם ותדלג על אותם חודשים.'
    ));
  end if;

  select jsonb_build_object(
    'adapter','gvk_legacy_v1',
    'ready', jsonb_array_length(v_blockers)=0,
    'blockers', v_blockers,
    'warnings', v_warnings,
    'targets', jsonb_build_object(
      'dispatcher', (select jsonb_build_object('id',jt.id,'name',jt.name,'code',jt.code,'strategy',jt.scheduling_strategy) from public.job_types jt where jt.id=requested_dispatcher_job_type_id),
      'onCall', (select jsonb_build_object('id',jt.id,'name',jt.name,'code',jt.code,'strategy',jt.scheduling_strategy) from public.job_types jt where jt.id=requested_on_call_job_type_id),
      'morningDriver', (select jsonb_build_object('id',jt.id,'name',jt.name,'code',jt.code,'strategy',jt.scheduling_strategy) from public.job_types jt where jt.id=requested_morning_driver_job_type_id)
    ),
    'legacy', jsonb_build_object(
      'dispatcher', jsonb_build_object(
        'members', (select count(*) from public.profiles p where p.role::text='dispatcher'),
        'historicalPeriods', (select count(*) from public.schedule_periods p where p.status::text in ('published','archived') and (p.year*100+p.month)<v_current_ym),
        'livePeriods', (select count(*) from public.schedule_periods p where p.status::text in ('published','archived') and (p.year*100+p.month)>=v_current_ym),
        'liveAssignments', (select count(*) from public.schedule_shifts s join public.schedule_periods p on p.id=s.period_id where p.status::text in ('published','archived') and (p.year*100+p.month)>=v_current_ym)
      ),
      'onCall', jsonb_build_object(
        'members', (select count(*) from public.profiles p where p.role::text='on_call'),
        'historicalPeriods', (select count(*) from public.driver_schedule_periods p where p.status::text in ('published','archived') and (p.year*100+p.month)<v_current_ym),
        'livePeriods', (select count(*) from public.driver_schedule_periods p where p.status::text in ('published','archived') and (p.year*100+p.month)>=v_current_ym),
        'liveAssignments', (select count(*) from public.driver_schedule_days d join public.driver_schedule_periods p on p.id=d.period_id where p.status::text in ('published','archived') and (p.year*100+p.month)>=v_current_ym)
      ),
      'morningDriver', jsonb_build_object(
        'members', (select count(*) from public.profiles p where p.role::text='morning_driver'),
        'historicalPeriods', (select count(*) from public.morning_driver_schedule_periods p where p.status::text in ('published','archived') and (p.year*100+p.month)<v_current_ym),
        'livePeriods', (select count(*) from public.morning_driver_schedule_periods p where p.status::text in ('published','archived') and (p.year*100+p.month)>=v_current_ym),
        'liveAssignments', (select count(*) from public.morning_driver_schedule_assignments a join public.morning_driver_schedule_periods p on p.id=a.schedule_period_id where p.status::text in ('published','archived') and (p.year*100+p.month)>=v_current_ym)
      )
    )
  ) into v_result;

  return v_result;
end;
$$;


ALTER FUNCTION "public"."preview_gvk_legacy_migration"("requested_mappings" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."preview_schedule_excel_import"("requested_year" integer, "requested_month" integer, "requested_period_type" "text", "requested_import_strategy" "text", "requested_dispatcher_shifts" "jsonb", "requested_driver_duties" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  current_user_id uuid;
  current_permissions text[];

  target_schedule_period
    public.schedule_periods%rowtype;

  target_driver_period
    public.driver_schedule_periods%rowtype;

  dispatcher_detected_count integer := 0;
  dispatcher_existing_count integer := 0;
  dispatcher_create_count integer := 0;
  dispatcher_update_count integer := 0;
  dispatcher_skip_count integer := 0;
  dispatcher_delete_count integer := 0;

  driver_detected_count integer := 0;
  driver_existing_count integer := 0;
  driver_create_count integer := 0;
  driver_update_count integer := 0;
  driver_skip_count integer := 0;
  driver_delete_count integer := 0;

  invalid_dispatcher_count integer := 0;
  invalid_driver_count integer := 0;

  inactive_dispatcher_count integer := 0;
  inactive_driver_count integer := 0;

  blockers jsonb := '[]'::jsonb;
  warnings jsonb := '[]'::jsonb;

  schedule_period_exists boolean := false;
  driver_period_exists boolean := false;

  schedule_period_status text := null;
  driver_period_status text := null;

  current_period_value integer;
  requested_period_value integer;
  expected_period_type text;
begin
  current_user_id :=
    auth.uid();

  if current_user_id is null then
    raise exception
      'not authenticated';
  end if;

  if not exists (
    select 1
    from public.profiles profile_row
    where profile_row.id =
      current_user_id
      and profile_row.is_active = true
  ) then
    raise exception
      'user not active';
  end if;

  current_permissions :=
    coalesce(
      public.get_my_permissions(),
      array[]::text[]
    );

  if not (
    'driver_availability.manage' =
      any(current_permissions)
    or
    'schedule.edit' =
      any(current_permissions)
    or
    'users.manage' =
      any(current_permissions)
  ) then
    raise exception
      'not allowed';
  end if;

  if requested_year is null
    or requested_year < 2020
    or requested_year > 2100
  then
    raise exception
      'import year is invalid';
  end if;

  if requested_month is null
    or requested_month < 1
    or requested_month > 12
  then
    raise exception
      'import month is invalid';
  end if;

  if requested_period_type not in (
    'historical',
    'current',
    'future'
  ) then
    raise exception
      'import period type is invalid';
  end if;

  if requested_import_strategy not in (
    'missing_only',
    'replace',
    'rebuild',
    'historical_archive'
  ) then
    raise exception
      'import strategy is invalid';
  end if;

  if requested_dispatcher_shifts is null
    or jsonb_typeof(
      requested_dispatcher_shifts
    ) <> 'array'
  then
    raise exception
      'dispatcher shifts must be a json array';
  end if;

  if requested_driver_duties is null
    or jsonb_typeof(
      requested_driver_duties
    ) <> 'array'
  then
    raise exception
      'driver duties must be a json array';
  end if;

  current_period_value :=
    extract(
      year from
      timezone(
        'Asia/Jerusalem',
        now()
      )
    )::integer * 12
    +
    extract(
      month from
      timezone(
        'Asia/Jerusalem',
        now()
      )
    )::integer
    - 1;

  requested_period_value :=
    requested_year * 12
    + requested_month
    - 1;

  expected_period_type :=
    case
      when requested_period_value <
        current_period_value
      then
        'historical'

      when requested_period_value =
        current_period_value
      then
        'current'

      else
        'future'
    end;

  if requested_period_type <>
    expected_period_type
  then
    raise exception
      'import period type does not match requested year and month';
  end if;

  if requested_period_type =
      'current'
    and requested_import_strategy =
      'historical_archive'
  then
    raise exception
      'current imports cannot use historical_archive strategy';
  end if;

  if requested_period_type =
    'future'
  then
    blockers :=
      blockers ||
      jsonb_build_array(
        'ייבוא חודש עתידי עדיין אינו נתמך.'
      );
  end if;

  dispatcher_detected_count :=
    jsonb_array_length(
      requested_dispatcher_shifts
    );

  driver_detected_count :=
    jsonb_array_length(
      requested_driver_duties
    );

  if dispatcher_detected_count = 0 then
    warnings :=
      warnings ||
      jsonb_build_array(
        'לא התקבלו משמרות מוקדנים לייבוא.'
      );
  end if;

  if driver_detected_count = 0 then
    warnings :=
      warnings ||
      jsonb_build_array(
        'לא התקבלו ימי כוננות לייבוא.'
      );
  end if;

  /*
   * בדיקת מבנה משמרות המוקדנים.
   */
  select
    count(*)::integer
  into
    invalid_dispatcher_count
  from jsonb_array_elements(
    requested_dispatcher_shifts
  ) item
  where
    jsonb_typeof(item) <> 'object'

    or coalesce(
      item ->> 'date',
      ''
    ) !~
      '^\d{4}-\d{2}-\d{2}$'

    or coalesce(
      item ->> 'startTime',
      ''
    ) !~
      '^\d{2}:\d{2}$'

    or coalesce(
      item ->> 'endTime',
      ''
    ) !~
      '^\d{2}:\d{2}$'

    or coalesce(
      item ->> 'userId',
      ''
    ) !~
      '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'

    or extract(
      year from
      (item ->> 'date')::date
    )::integer <>
      requested_year

    or extract(
      month from
      (item ->> 'date')::date
    )::integer <>
      requested_month;

  if invalid_dispatcher_count > 0 then
    blockers :=
      blockers ||
      jsonb_build_array(
        format(
          '%s משמרות מוקדנים מכילות נתונים לא תקינים.',
          invalid_dispatcher_count
        )
      );
  end if;

  /*
   * בדיקת מבנה ימי הכוננות.
   */
  select
    count(*)::integer
  into
    invalid_driver_count
  from jsonb_array_elements(
    requested_driver_duties
  ) item
  where
    jsonb_typeof(item) <> 'object'

    or coalesce(
      item ->> 'date',
      ''
    ) !~
      '^\d{4}-\d{2}-\d{2}$'

    or coalesce(
      item ->> 'userId',
      ''
    ) !~
      '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'

    or extract(
      year from
      (item ->> 'date')::date
    )::integer <>
      requested_year

    or extract(
      month from
      (item ->> 'date')::date
    )::integer <>
      requested_month;

  if invalid_driver_count > 0 then
    blockers :=
      blockers ||
      jsonb_build_array(
        format(
          '%s ימי כוננות מכילים נתונים לא תקינים.',
          invalid_driver_count
        )
      );
  end if;

  /*
   * בדיקת משתמשי מוקדנים פעילים.
   */
  select
    count(*)::integer
  into
    inactive_dispatcher_count
  from (
    select distinct
      (
        item ->> 'userId'
      )::uuid as user_id
    from jsonb_array_elements(
      requested_dispatcher_shifts
    ) item
    where coalesce(
      item ->> 'userId',
      ''
    ) ~
      '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
  ) payload_user
  left join public.profiles profile_row
    on profile_row.id =
      payload_user.user_id
    and profile_row.is_active = true
    and profile_row.role =
      'dispatcher'
  where profile_row.id is null;

  if inactive_dispatcher_count > 0 then
    blockers :=
      blockers ||
      jsonb_build_array(
        format(
          '%s מוקדנים אינם קיימים, אינם פעילים או אינם מוגדרים כמוקדנים.',
          inactive_dispatcher_count
        )
      );
  end if;

  /*
   * בדיקת משתמשי כוננים פעילים.
   */
  select
    count(*)::integer
  into
    inactive_driver_count
  from (
    select distinct
      (
        item ->> 'userId'
      )::uuid as user_id
    from jsonb_array_elements(
      requested_driver_duties
    ) item
    where coalesce(
      item ->> 'userId',
      ''
    ) ~
      '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
  ) payload_user
  left join public.profiles profile_row
    on profile_row.id =
      payload_user.user_id
    and profile_row.is_active = true
    and profile_row.role =
      'on_call'
  where profile_row.id is null;

  if inactive_driver_count > 0 then
    blockers :=
      blockers ||
      jsonb_build_array(
        format(
          '%s כוננים אינם קיימים, אינם פעילים או אינם מוגדרים ככוננים.',
          inactive_driver_count
        )
      );
  end if;

  /*
   * בדיקת כפילויות במשמרות המוקדנים.
   */
  if exists (
    select 1
    from (
      select
        item ->> 'date' as shift_date,
        item ->> 'startTime' as start_time,
        count(*)::integer as row_count
      from jsonb_array_elements(
        requested_dispatcher_shifts
      ) item
      group by
        item ->> 'date',
        item ->> 'startTime'
      having count(*) > 1
    ) duplicate_shift
  ) then
    blockers :=
      blockers ||
      jsonb_build_array(
        'התקבלו מספר משמרות מוקדנים לאותו תאריך ושעת התחלה.'
      );
  end if;

  /*
   * בדיקת כפילויות בכוננויות.
   */
  if exists (
    select 1
    from (
      select
        item ->> 'date' as duty_date,
        count(*)::integer as row_count
      from jsonb_array_elements(
        requested_driver_duties
      ) item
      group by
        item ->> 'date'
      having count(*) > 1
    ) duplicate_duty
  ) then
    blockers :=
      blockers ||
      jsonb_build_array(
        'התקבלו מספר כוננים עבור אותו תאריך.'
      );
  end if;

  /*
   * איתור תקופות קיימות.
   */
  select *
  into target_schedule_period
  from public.schedule_periods
  where year =
    requested_year
    and month =
      requested_month;

  if found then
    schedule_period_exists :=
      true;

    schedule_period_status :=
      target_schedule_period.status::text;
  end if;

  select *
  into target_driver_period
  from public.driver_schedule_periods
  where year =
    requested_year
    and month =
      requested_month;

  if found then
    driver_period_exists :=
      true;

    driver_period_status :=
      target_driver_period.status::text;
  end if;

  /*
   * ספירת משמרות מוקדנים קיימות.
   */
  if schedule_period_exists then
    select
      count(*)::integer
    into
      dispatcher_existing_count
    from jsonb_array_elements(
      requested_dispatcher_shifts
    ) item
    where exists (
      select 1
      from public.schedule_shifts shift_row
      where shift_row.period_id =
        target_schedule_period.id
        and shift_row.starts_at =
          (
            (
              (item ->> 'date')::date
              +
              (item ->> 'startTime')::time
            )
            at time zone
              'Asia/Jerusalem'
          )
    );

    select
      count(*)::integer
    into
      dispatcher_delete_count
    from public.schedule_shifts shift_row
    where shift_row.period_id =
      target_schedule_period.id;
  end if;

  /*
   * ספירת ימי כוננות קיימים.
   */
  if driver_period_exists then
    select
      count(*)::integer
    into
      driver_existing_count
    from jsonb_array_elements(
      requested_driver_duties
    ) item
    where exists (
      select 1
      from public.driver_schedule_days day_row
      where day_row.period_id =
        target_driver_period.id
        and day_row.duty_date =
          (item ->> 'date')::date
    );

    select
      count(*)::integer
    into
      driver_delete_count
    from public.driver_schedule_days day_row
    where day_row.period_id =
      target_driver_period.id;
  end if;

  /*
   * חישוב פעולות לפי אסטרטגיה.
   */
  if requested_import_strategy =
    'missing_only'
  then
    dispatcher_create_count :=
      greatest(
        dispatcher_detected_count -
        dispatcher_existing_count,
        0
      );

    dispatcher_update_count := 0;

    dispatcher_skip_count :=
      dispatcher_existing_count;

    dispatcher_delete_count := 0;

    driver_create_count :=
      greatest(
        driver_detected_count -
        driver_existing_count,
        0
      );

    driver_update_count := 0;

    driver_skip_count :=
      driver_existing_count;

    driver_delete_count := 0;

  elsif requested_import_strategy =
    'replace'
  then
    dispatcher_create_count :=
      greatest(
        dispatcher_detected_count -
        dispatcher_existing_count,
        0
      );

    dispatcher_update_count :=
      dispatcher_existing_count;

    dispatcher_skip_count := 0;

    dispatcher_delete_count := 0;

    driver_create_count :=
      greatest(
        driver_detected_count -
        driver_existing_count,
        0
      );

    driver_update_count :=
      driver_existing_count;

    driver_skip_count := 0;

    driver_delete_count := 0;

  elsif requested_import_strategy =
    'rebuild'
  then
    dispatcher_create_count :=
      dispatcher_detected_count;

    dispatcher_update_count := 0;
    dispatcher_skip_count := 0;

    driver_create_count :=
      driver_detected_count;

    driver_update_count := 0;
    driver_skip_count := 0;

  elsif requested_import_strategy =
    'historical_archive'
  then
    dispatcher_create_count :=
      dispatcher_detected_count;

    dispatcher_update_count := 0;
    dispatcher_skip_count := 0;
    dispatcher_delete_count := 0;

    driver_create_count :=
      driver_detected_count;

    driver_update_count := 0;
    driver_skip_count := 0;
    driver_delete_count := 0;
  end if;

  if requested_period_type =
      'current'
    and schedule_period_status =
      'archived'
  then
    blockers :=
      blockers ||
      jsonb_build_array(
        'תקופת המוקדנים של החודש כבר נמצאת בארכיון.'
      );
  end if;

  if requested_period_type =
      'current'
    and driver_period_status =
      'archived'
  then
    blockers :=
      blockers ||
      jsonb_build_array(
        'תקופת הכוננים של החודש כבר נמצאת בארכיון.'
      );
  end if;

  if requested_period_type =
      'current'
    and schedule_period_status =
      'published'
    and requested_import_strategy in (
      'replace',
      'rebuild'
    )
  then
    warnings :=
      warnings ||
      jsonb_build_array(
        'לוח המוקדנים כבר פורסם. הייבוא צפוי לשנות לוח פעיל.'
      );
  end if;

  if requested_period_type =
      'current'
    and driver_period_status =
      'published'
    and requested_import_strategy in (
      'replace',
      'rebuild'
    )
  then
    warnings :=
      warnings ||
      jsonb_build_array(
        'לוח הכוננים כבר פורסם. הייבוא צפוי לשנות לוח פעיל.'
      );
  end if;

  return jsonb_build_object(
    'year',
      requested_year,

    'month',
      requested_month,

    'periodType',
      requested_period_type,

    'importStrategy',
      requested_import_strategy,

    'canImport',
      jsonb_array_length(
        blockers
      ) = 0,

    'blockers',
      blockers,

    'warnings',
      warnings,

    'schedulePeriod',
      jsonb_build_object(
        'exists',
          schedule_period_exists,

        'id',
          case
            when schedule_period_exists
            then target_schedule_period.id
            else null
          end,

        'status',
          schedule_period_status
      ),

    'driverSchedulePeriod',
      jsonb_build_object(
        'exists',
          driver_period_exists,

        'id',
          case
            when driver_period_exists
            then target_driver_period.id
            else null
          end,

        'status',
          driver_period_status
      ),

    'dispatcherShifts',
      jsonb_build_object(
        'detected',
          dispatcher_detected_count,

        'existing',
          dispatcher_existing_count,

        'toCreate',
          dispatcher_create_count,

        'toUpdate',
          dispatcher_update_count,

        'toSkip',
          dispatcher_skip_count,

        'toDelete',
          dispatcher_delete_count
      ),

    'driverDuties',
      jsonb_build_object(
        'detected',
          driver_detected_count,

        'existing',
          driver_existing_count,

        'toCreate',
          driver_create_count,

        'toUpdate',
          driver_update_count,

        'toSkip',
          driver_skip_count,

        'toDelete',
          driver_delete_count
      )
  );
end;
$_$;


ALTER FUNCTION "public"."preview_schedule_excel_import"("requested_year" integer, "requested_month" integer, "requested_period_type" "text", "requested_import_strategy" "text", "requested_dispatcher_shifts" "jsonb", "requested_driver_duties" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."preview_schedule_excel_import"("requested_year" integer, "requested_month" integer, "requested_period_type" "text", "requested_import_strategy" "text", "requested_dispatcher_shifts" "jsonb", "requested_driver_duties" "jsonb", "requested_morning_driver_shifts" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  base_preview jsonb;
  blockers jsonb := '[]'::jsonb;
  warnings jsonb := '[]'::jsonb;

  target_availability_period public.morning_driver_availability_periods%rowtype;
  target_schedule_period public.morning_driver_schedule_periods%rowtype;

  availability_period_exists boolean := false;
  schedule_period_exists boolean := false;

  detected_count integer := 0;
  existing_count integer := 0;
  create_count integer := 0;
  update_count integer := 0;
  skip_count integer := 0;
  delete_count integer := 0;

  invalid_count integer := 0;
  inactive_count integer := 0;
begin
  if requested_morning_driver_shifts is null
     or jsonb_typeof(requested_morning_driver_shifts) <> 'array'
  then
    raise exception
      'morning driver shifts must be a json array';
  end if;

  /*
   * מפעילים את הסימולציה הקיימת של מוקדנים וכוננים.
   * הפונקציה בעלת ששת הפרמטרים נשארת מקור האמת
   * לשני סוגי הנתונים הקיימים.
   */
  base_preview :=
    public.preview_schedule_excel_import(
      requested_year,
      requested_month,
      requested_period_type,
      requested_import_strategy,
      requested_dispatcher_shifts,
      requested_driver_duties
    );

  blockers :=
    coalesce(
      base_preview -> 'blockers',
      '[]'::jsonb
    );

  warnings :=
    coalesce(
      base_preview -> 'warnings',
      '[]'::jsonb
    );

  detected_count :=
    jsonb_array_length(
      requested_morning_driver_shifts
    );

  if detected_count = 0 then
    warnings :=
      warnings ||
      jsonb_build_array(
        'לא התקבלו שיבוצי כונני בוקר לייבוא.'
      );
  end if;

  /*
   * מבנה כל רשומת כונן בוקר:
   * date, startTime, endTime, userId,
   * assignmentSlot, shiftType,
   * minimumWorkers, recommendedWorkers.
   */
  select count(*)::integer
  into invalid_count
  from jsonb_array_elements(
    requested_morning_driver_shifts
  ) item
  where
    jsonb_typeof(item) <> 'object'
    or coalesce(item ->> 'date', '') !~
      '^\d{4}-\d{2}-\d{2}$'
    or coalesce(item ->> 'startTime', '') !~
      '^\d{2}:\d{2}$'
    or coalesce(item ->> 'endTime', '') !~
      '^\d{2}:\d{2}$'
    or coalesce(item ->> 'userId', '') !~
      '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
    or coalesce(item ->> 'assignmentSlot', '') !~
      '^[12]$'
    or coalesce(item ->> 'shiftType', '') not in (
      'weekday_morning',
      'weekday_evening',
      'friday_morning'
    )
    or coalesce(item ->> 'minimumWorkers', '') !~
      '^\d+$'
    or coalesce(item ->> 'recommendedWorkers', '') !~
      '^\d+$'
    or (item ->> 'minimumWorkers')::integer < 1
    or (item ->> 'minimumWorkers')::integer > 2
    or (item ->> 'recommendedWorkers')::integer < 1
    or (item ->> 'recommendedWorkers')::integer > 2
    or (item ->> 'recommendedWorkers')::integer <
      (item ->> 'minimumWorkers')::integer
    or extract(
      year from (item ->> 'date')::date
    )::integer <> requested_year
    or extract(
      month from (item ->> 'date')::date
    )::integer <> requested_month;

  if invalid_count > 0 then
    blockers :=
      blockers ||
      jsonb_build_array(
        format(
          '%s שיבוצי כונני בוקר מכילים נתונים לא תקינים.',
          invalid_count
        )
      );
  end if;

  select count(*)::integer
  into inactive_count
  from (
    select distinct
      (item ->> 'userId')::uuid as user_id
    from jsonb_array_elements(
      requested_morning_driver_shifts
    ) item
    where coalesce(item ->> 'userId', '') ~
      '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
  ) payload_user
  left join public.profiles profile_row
    on profile_row.id = payload_user.user_id
   and profile_row.is_active = true
   and profile_row.role =
     'morning_driver'::public.user_role
  where profile_row.id is null;

  if inactive_count > 0 then
    blockers :=
      blockers ||
      jsonb_build_array(
        format(
          '%s כונני בוקר אינם קיימים, אינם פעילים או אינם מוגדרים ככונני בוקר.',
          inactive_count
        )
      );
  end if;

  if exists (
    select 1
    from (
      select
        item ->> 'date' as shift_date,
        item ->> 'shiftType' as shift_type,
        item ->> 'assignmentSlot' as assignment_slot,
        count(*)::integer as row_count
      from jsonb_array_elements(
        requested_morning_driver_shifts
      ) item
      group by
        item ->> 'date',
        item ->> 'shiftType',
        item ->> 'assignmentSlot'
      having count(*) > 1
    ) duplicate_assignment
  ) then
    blockers :=
      blockers ||
      jsonb_build_array(
        'התקבלו מספר כונני בוקר לאותו תאריך, סוג משמרת ומיקום שיבוץ.'
      );
  end if;

  select *
  into target_availability_period
  from public.morning_driver_availability_periods
  where year = requested_year
    and month = requested_month;

  if found then
    availability_period_exists := true;
  end if;

  select *
  into target_schedule_period
  from public.morning_driver_schedule_periods
  where year = requested_year
    and month = requested_month;

  if found then
    schedule_period_exists := true;
  end if;

  if schedule_period_exists then
    select count(*)::integer
    into existing_count
    from jsonb_array_elements(
      requested_morning_driver_shifts
    ) item
    where exists (
      select 1
      from public.morning_driver_schedule_assignments assignment
      join public.morning_driver_availability_shifts shift_item
        on shift_item.id =
          assignment.availability_shift_id
      where assignment.schedule_period_id =
          target_schedule_period.id
        and shift_item.shift_date =
          (item ->> 'date')::date
        and shift_item.shift_type =
          item ->> 'shiftType'
        and assignment.assignment_slot =
          (item ->> 'assignmentSlot')::integer
    );

    select count(*)::integer
    into delete_count
    from public.morning_driver_schedule_assignments assignment
    where assignment.schedule_period_id =
      target_schedule_period.id;
  end if;

  if requested_import_strategy = 'missing_only' then
    create_count :=
      greatest(
        detected_count - existing_count,
        0
      );
    update_count := 0;
    skip_count := existing_count;
    delete_count := 0;

  elsif requested_import_strategy = 'replace' then
    create_count :=
      greatest(
        detected_count - existing_count,
        0
      );
    update_count := existing_count;
    skip_count := 0;
    delete_count := 0;

  elsif requested_import_strategy = 'rebuild' then
    create_count := detected_count;
    update_count := 0;
    skip_count := 0;

  elsif requested_import_strategy = 'historical_archive' then
    create_count := detected_count;
    update_count := 0;
    skip_count := 0;
    delete_count := 0;
  end if;

  if requested_period_type = 'current'
     and schedule_period_exists
     and target_schedule_period.status = 'archived'
  then
    blockers :=
      blockers ||
      jsonb_build_array(
        'תקופת כונני הבוקר של החודש כבר נמצאת בארכיון.'
      );
  end if;

  if requested_period_type = 'current'
     and schedule_period_exists
     and target_schedule_period.status = 'published'
     and requested_import_strategy in (
       'replace',
       'rebuild'
     )
  then
    warnings :=
      warnings ||
      jsonb_build_array(
        'לוח כונני הבוקר כבר פורסם. הייבוא צפוי לשנות לוח פעיל.'
      );
  end if;

  return
    base_preview
    ||
    jsonb_build_object(
      'canImport',
        jsonb_array_length(blockers) = 0,
      'blockers',
        blockers,
      'warnings',
        warnings,
      'morningDriverAvailabilityPeriod',
        jsonb_build_object(
          'exists',
            availability_period_exists,
          'id',
            case
              when availability_period_exists
              then target_availability_period.id
              else null
            end,
          'status',
            case
              when availability_period_exists
              then target_availability_period.status
              else null
            end
        ),
      'morningDriverSchedulePeriod',
        jsonb_build_object(
          'exists',
            schedule_period_exists,
          'id',
            case
              when schedule_period_exists
              then target_schedule_period.id
              else null
            end,
          'status',
            case
              when schedule_period_exists
              then target_schedule_period.status
              else null
            end
        ),
      'morningDriverShifts',
        jsonb_build_object(
          'detected',
            detected_count,
          'existing',
            existing_count,
          'toCreate',
            create_count,
          'toUpdate',
            update_count,
          'toSkip',
            skip_count,
          'toDelete',
            delete_count
        )
    );
end;
$_$;


ALTER FUNCTION "public"."preview_schedule_excel_import"("requested_year" integer, "requested_month" integer, "requested_period_type" "text", "requested_import_strategy" "text", "requested_dispatcher_shifts" "jsonb", "requested_driver_duties" "jsonb", "requested_morning_driver_shifts" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."publish_driver_schedule"("requested_schedule_period_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  current_user_id uuid;
  current_permissions text[];

  target_period
    public.driver_schedule_periods%rowtype;

  total_days_count integer := 0;
  assigned_days_count integer := 0;
  unassigned_days_count integer := 0;
  consecutive_conflicts_count integer := 0;

  published_at_value timestamptz :=
    now();
begin
  current_user_id :=
    auth.uid();

  if current_user_id is null then
    raise exception
      'not authenticated';
  end if;

  if not exists (
    select 1
    from public.profiles
    where id =
      current_user_id
      and is_active = true
  ) then
    raise exception
      'user not active';
  end if;

  current_permissions :=
    coalesce(
      public.get_my_permissions(),
      array[]::text[]
    );

  if not (
    'driver_schedule.edit' =
      any(current_permissions)
  ) then
    raise exception
      'not allowed';
  end if;

  if requested_schedule_period_id
    is null
  then
    raise exception
      'driver schedule period id is required';
  end if;

  select *
  into target_period
  from public.driver_schedule_periods
  where id =
    requested_schedule_period_id
  for update;

  if not found then
    raise exception
      'driver schedule period not found';
  end if;

  if target_period.status =
    'published'
  then
    select
      count(*)::integer,

      count(*) filter (
        where assigned_user_id
          is not null
      )::integer,

      count(*) filter (
        where assigned_user_id
          is null
      )::integer

    into
      total_days_count,
      assigned_days_count,
      unassigned_days_count

    from public.driver_schedule_days
    where period_id =
      target_period.id;

    return jsonb_build_object(
      'schedulePeriodId',
        target_period.id,

      'year',
        target_period.year,

      'month',
        target_period.month,

      'status',
        target_period.status,

      'totalDays',
        total_days_count,

      'assignedDays',
        assigned_days_count,

      'unassignedDays',
        unassigned_days_count,

      'publishedAt',
        target_period.published_at,

      'alreadyPublished',
        true
    );
  end if;

  if target_period.status <>
    'draft'
  then
    raise exception
      'only draft driver schedules can be published';
  end if;

  select
    count(*)::integer,

    count(*) filter (
      where assigned_user_id
        is not null
    )::integer,

    count(*) filter (
      where assigned_user_id
        is null
    )::integer

  into
    total_days_count,
    assigned_days_count,
    unassigned_days_count

  from public.driver_schedule_days
  where period_id =
    target_period.id;

  if total_days_count = 0 then
    raise exception
      'driver schedule has no days';
  end if;

  if unassigned_days_count > 0 then
    raise exception
      'all driver schedule days must be assigned before publishing';
  end if;

  select
    count(*)::integer
  into
    consecutive_conflicts_count

  from public.driver_schedule_days
    first_day

  join public.driver_schedule_days
    second_day

    on second_day.period_id =
      first_day.period_id

    and second_day.duty_date =
      first_day.duty_date + 1

    and second_day.assigned_user_id =
      first_day.assigned_user_id

  where first_day.period_id =
    target_period.id

    and first_day.assigned_user_id
      is not null;

  if consecutive_conflicts_count > 0 then
    raise exception
      'driver schedule contains consecutive-day assignments';
  end if;

  /*
   * Publishing no longer changes is_locked.
   * is_locked is reserved for explicit/manual locks.
   */

  update public.driver_schedule_periods
  set
    status =
      'published',

    published_at =
      published_at_value,

    updated_by =
      current_user_id,

    updated_at =
      published_at_value

  where id =
    target_period.id

  returning *
  into target_period;

  return jsonb_build_object(
    'schedulePeriodId',
      target_period.id,

    'year',
      target_period.year,

    'month',
      target_period.month,

    'status',
      target_period.status,

    'totalDays',
      total_days_count,

    'assignedDays',
      assigned_days_count,

    'unassignedDays',
      unassigned_days_count,

    'publishedAt',
      target_period.published_at,

    'alreadyPublished',
      false
  );
end;
$$;


ALTER FUNCTION "public"."publish_driver_schedule"("requested_schedule_period_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."publish_driver_schedule"("requested_schedule_period_id" "uuid") IS 'Publishes a complete on-call schedule draft. Every day must be assigned and consecutive-day assignments are prohibited. Published days are locked. Requires driver_schedule.edit.';



CREATE OR REPLACE FUNCTION "public"."publish_dynamic_schedule_draft"("requested_draft_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  current_user_id uuid:=auth.uid();
  target_draft public.dynamic_schedule_shadow_drafts%rowtype;
  target_job public.job_types%rowtype;
  target_period public.dynamic_availability_periods%rowtype;
  v_publication_id uuid;
  inserted_assignments integer:=0;
  v_metrics jsonb;
  v_unfilled integer:=0;
begin
  if current_user_id is null then raise exception 'not authenticated'; end if;

  select * into target_draft from public.dynamic_schedule_shadow_drafts where id=requested_draft_id;
  if not public.has_dynamic_job_type_permission('schedule.publish', target_draft.job_type_id, current_user_id) then raise exception 'not allowed'; end if;
  if target_draft.id is null then raise exception 'draft not found'; end if;
  select * into target_job from public.job_types where id=target_draft.job_type_id;
  select * into target_period from public.dynamic_availability_periods where id=target_draft.availability_period_id;
  if target_period.status <> 'closed' then raise exception 'availability period must be closed before publishing'; end if;
  if target_draft.status not in ('generated','incomplete') then raise exception 'draft is not ready for publishing'; end if;

  v_metrics:=public.dynamic_refresh_draft_metrics(target_draft.id);
  v_unfilled:=coalesce((v_metrics->>'effectiveUnfilledRequiredPositions')::integer,0);
  if v_unfilled>0 then raise exception 'draft has % unfilled required positions that were not intentionally left empty',v_unfilled; end if;

  insert into public.dynamic_schedule_publications(
    job_type_id,availability_period_id,draft_id,year,month,status,config_snapshot,published_by,published_at,updated_at
  ) values(
    target_draft.job_type_id,target_draft.availability_period_id,target_draft.id,target_draft.year,target_draft.month,'published',
    jsonb_build_object('jobType',target_job.scheduling_config,'draftMetrics',v_metrics),current_user_id,now(),now()
  ) on conflict(job_type_id,year,month) do update set
    availability_period_id=excluded.availability_period_id,draft_id=excluded.draft_id,status='published',
    config_snapshot=excluded.config_snapshot,published_by=excluded.published_by,published_at=now(),updated_at=now()
  returning id into v_publication_id;

  delete from public.dynamic_schedule_published_assignments where publication_id=v_publication_id;
  delete from public.dynamic_schedule_published_unassigned where publication_id=v_publication_id;

  insert into public.dynamic_schedule_published_assignments(
    publication_id,source_assignment_id,slot_id,shift_date,shift_code,shift_name,start_time,end_time,user_id,
    assignment_tier,score,reasons,engine_user_id,manager_edited,manager_override_note
  )
  select v_publication_id,a.id,s.id,s.shift_date,s.shift_code,s.shift_name,s.start_time,s.end_time,a.user_id,
         a.assignment_tier,a.score,a.reasons,a.engine_user_id,
         (a.manager_edited_at is not null or (a.engine_user_id is not null and a.engine_user_id<>a.user_id)),a.manager_override_note
  from public.dynamic_schedule_shadow_assignments a
  join public.dynamic_availability_slots s on s.id=a.slot_id
  where a.draft_id=target_draft.id;
  get diagnostics inserted_assignments = row_count;

  insert into public.dynamic_schedule_published_unassigned(
    publication_id,slot_id,shift_date,shift_code,shift_name,intentionally_unassigned_count,note
  )
  select v_publication_id,sl.id,sl.shift_date,sl.shift_code,sl.shift_name,
         least(o.intentionally_unassigned_count,greatest(sl.min_workers-coalesce(a.cnt,0),0)),o.note
  from public.dynamic_schedule_draft_slot_overrides o
  join public.dynamic_availability_slots sl on sl.id=o.slot_id
  left join (
    select slot_id,count(*) filter(where assignment_tier='required')::integer cnt
    from public.dynamic_schedule_shadow_assignments where draft_id=target_draft.id group by slot_id
  ) a on a.slot_id=sl.id
  where o.draft_id=target_draft.id
    and least(o.intentionally_unassigned_count,greatest(sl.min_workers-coalesce(a.cnt,0),0))>0;

  insert into public.audit_logs(action,actor_user_id,entity_type,entity_id,summary,metadata)
  values('system_event',current_user_id,'dynamic_schedule_publication',v_publication_id,'לוח דינמי פורסם',
    jsonb_build_object('draft_id',target_draft.id,'job_type_id',target_draft.job_type_id,'year',target_draft.year,'month',target_draft.month,'assignment_count',inserted_assignments));

  return jsonb_build_object('publicationId',v_publication_id,'published',true,'assignmentCount',inserted_assignments);
end;
$$;


ALTER FUNCTION "public"."publish_dynamic_schedule_draft"("requested_draft_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."publish_morning_driver_schedule"("requested_schedule_period_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  current_user_id uuid;
  current_permissions text[];

  target_period
    public.morning_driver_schedule_periods%rowtype;

  minimum_unfilled integer := 0;
  recommendation_unfilled integer := 0;
  published_at_value timestamptz := now();
begin
  current_user_id := auth.uid();

  if current_user_id is null then
    raise exception 'not authenticated';
  end if;

  current_permissions :=
    coalesce(
      public.get_my_permissions(),
      array[]::text[]
    );

  if not (
    'morning_driver_schedule.edit'
      = any(current_permissions)
  ) then
    raise exception 'not allowed';
  end if;

  select *
  into target_period
  from public.morning_driver_schedule_periods period
  where period.id = requested_schedule_period_id
  for update;

  if not found then
    raise exception 'morning driver schedule period not found';
  end if;

  if target_period.status = 'published' then
    return jsonb_build_object(
      'schedulePeriodId',
        target_period.id,
      'status',
        target_period.status,
      'publishedAt',
        target_period.published_at,
      'recommendationWarnings',
        0,
      'alreadyPublished',
        true
    );
  end if;

  if target_period.status <> 'draft' then
    raise exception 'only draft schedules can be published';
  end if;

  select count(*)
  into minimum_unfilled
  from public.morning_driver_schedule_assignments assignment
  where assignment.schedule_period_id = target_period.id
    and assignment.assignment_slot = 1
    and assignment.assigned_user_id is null
    and coalesce(assignment.is_intentionally_unassigned, false) = false;

  if minimum_unfilled > 0 then
    raise exception 'minimum morning driver staffing is incomplete unless explicitly marked unassigned';
  end if;

  select count(*)
  into recommendation_unfilled
  from public.morning_driver_schedule_assignments assignment
  where assignment.schedule_period_id = target_period.id
    and assignment.assignment_slot > 1
    and assignment.assigned_user_id is null;

  update public.morning_driver_schedule_periods
  set
    status = 'published',
    published_at = published_at_value,
    updated_by = current_user_id,
    updated_at = published_at_value
  where id = target_period.id
  returning *
  into target_period;

  return jsonb_build_object(
    'schedulePeriodId',
      target_period.id,
    'status',
      target_period.status,
    'publishedAt',
      target_period.published_at,
    'recommendationWarnings',
      recommendation_unfilled,
    'alreadyPublished',
      false
  );
end;
$$;


ALTER FUNCTION "public"."publish_morning_driver_schedule"("requested_schedule_period_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."publish_schedule_period"("requested_schedule_period_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  current_user_id uuid;

  current_profile
    public.profiles%rowtype;

  target_period
    public.schedule_periods%rowtype;

  user_permissions text[];

  total_shift_count integer;
  unassigned_shift_count integer;
  intentionally_unassigned_shift_count integer;
  invalid_shift_count integer;
begin
  current_user_id :=
    auth.uid();


  if current_user_id is null then
    raise exception
      'not authenticated';
  end if;


  select *
  into current_profile

  from public.profiles

  where id =
    current_user_id;


  if not found then
    raise exception
      'profile not found';
  end if;


  if not current_profile.is_active then
    raise exception
      'user not active';
  end if;


  user_permissions :=
    coalesce(
      public.get_my_permissions(),
      array[]::text[]
    );


  if not (
    'schedule.edit' =
      any(user_permissions)
  ) then
    raise exception
      'not allowed';
  end if;


  if requested_schedule_period_id
    is null
  then
    raise exception
      'schedule period id is required';
  end if;


  select *
  into target_period

  from public.schedule_periods

  where id =
    requested_schedule_period_id

  for update;


  if not found then
    raise exception
      'schedule period not found';
  end if;


  if target_period.status =
    'archived'
      ::public.schedule_period_status
  then
    raise exception
      'archived schedule cannot be published';
  end if;


  if target_period.status =
    'published'
      ::public.schedule_period_status
  then
    return jsonb_build_object(

      'schedulePeriodId',
        target_period.id,

      'year',
        target_period.year,

      'month',
        target_period.month,

      'status',
        target_period.status::text,

      'publishedAt',
        target_period.published_at,

      'publishedBy',
        null,

      'publishedShifts',
        null,

      'intentionallyUnassignedShifts',
        (
          select count(*)

          from public.schedule_shifts shift

          where shift.period_id =
              target_period.id

            and shift.is_intentionally_unassigned
        ),

      'alreadyPublished',
        true
    );
  end if;


  if target_period.status
    not in (
      'draft'
        ::public.schedule_period_status,

      'scheduling'
        ::public.schedule_period_status
    )
  then
    raise exception
      'schedule is not ready for publication';
  end if;


  -- =======================================================
  -- בדיקת שלמות הלוח
  -- =======================================================

  select

    count(*)::integer,


    /*
     * ריקה בטעות - חוסמת פרסום.
     */
    count(*) filter (
      where
        assigned_user_id is null

        and not
          is_intentionally_unassigned
    )::integer,


    /*
     * ריקה במכוון - מותרת.
     */
    count(*) filter (
      where
        assigned_user_id is null

        and
          is_intentionally_unassigned
    )::integer,


    /*
     * תאריכים לא תקינים.
     */
    count(*) filter (
      where
        starts_at is null

        or ends_at is null

        or ends_at <=
          starts_at
    )::integer


  into
    total_shift_count,
    unassigned_shift_count,
    intentionally_unassigned_shift_count,
    invalid_shift_count


  from public.schedule_shifts

  where period_id =
    target_period.id;


  if total_shift_count = 0 then
    raise exception
      'schedule has no shifts';
  end if;


  if unassigned_shift_count > 0 then
    raise exception
      'schedule contains unassigned shifts';
  end if;


  if invalid_shift_count > 0 then
    raise exception
      'schedule contains invalid shifts';
  end if;


  -- =======================================================
  -- בדיקת חפיפות
  -- =======================================================

  if exists (
    select 1

    from public.schedule_shifts
      first_shift

    join public.schedule_shifts
      second_shift

      on second_shift.period_id =
        first_shift.period_id

      and second_shift.assigned_user_id =
        first_shift.assigned_user_id

      and second_shift.id >
        first_shift.id

      and second_shift.starts_at <
        first_shift.ends_at

      and second_shift.ends_at >
        first_shift.starts_at


    where first_shift.period_id =
        target_period.id

      and first_shift.assigned_user_id
        is not null
  ) then
    raise exception
      'schedule contains overlapping shifts';
  end if;


  -- =======================================================
  -- בדיקת משמרות רצופות
  -- =======================================================

  if exists (
    select 1

    from public.schedule_shifts
      first_shift

    join public.schedule_shifts
      second_shift

      on second_shift.period_id =
        first_shift.period_id

      and second_shift.assigned_user_id =
        first_shift.assigned_user_id

      and second_shift.starts_at =
        first_shift.ends_at


    where first_shift.period_id =
        target_period.id

      and first_shift.assigned_user_id
        is not null
  ) then
    raise exception
      'schedule contains consecutive shifts';
  end if;


  -- =======================================================
  -- פרסום
  -- =======================================================

  update public.schedule_periods

  set
    status =
      'published'
        ::public.schedule_period_status,

    published_at =
      now(),

    approved_by =
      current_user_id,

    approved_at =
      coalesce(
        approved_at,
        now()
      ),

    updated_at =
      now()


  where id =
    target_period.id


  returning *
  into target_period;


  return jsonb_build_object(

    'schedulePeriodId',
      target_period.id,

    'year',
      target_period.year,

    'month',
      target_period.month,

    'status',
      target_period.status::text,

    'publishedAt',
      target_period.published_at,

    'publishedBy',
      current_user_id,

    'publishedShifts',
      total_shift_count,

    'intentionallyUnassignedShifts',
      intentionally_unassigned_shift_count,

    'alreadyPublished',
      false
  );
end;
$$;


ALTER FUNCTION "public"."publish_schedule_period"("requested_schedule_period_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."publish_schedule_period"("requested_schedule_period_id" "uuid") IS 'Publishes a complete dispatcher schedule. Requires an active manager or admin with schedule.edit permission.';



CREATE OR REPLACE FUNCTION "public"."rebuild_availability_period_slots"("requested_period_id" "uuid") RETURNS TABLE("period_id" "uuid", "created_slots" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  current_user_id uuid;
  target_year integer;
  target_month integer;
  target_status text;
  first_day_of_month date;
  last_day_of_month date;
  created_shift_count integer;
begin
  current_user_id := auth.uid();

  if current_user_id is null then
    raise exception
      'User is not authenticated';
  end if;

  if not exists (
    select 1
    from public.profiles profile
    where profile.id = current_user_id
      and profile.is_active = true
  ) then
    raise exception
      'Authenticated user is not active';
  end if;

  if not exists (
    select 1
    from public.user_permissions permission
    where permission.user_id =
      current_user_id
      and permission.permission_key =
        'availability.manage'
  ) then
    raise exception
      'User is not allowed to manage availability periods';
  end if;

  select
    period.year,
    period.month,
    period.status
  into
    target_year,
    target_month,
    target_status
  from public.availability_periods period
  where period.id =
    requested_period_id;

  if target_year is null then
    raise exception
      'Availability period was not found';
  end if;

  if target_status <> 'draft' then
    raise exception
      'Only draft availability periods can be rebuilt';
  end if;

  /*
   * לא בונים מחדש חודש לאחר שמוקדנים
   * כבר התחילו לשמור אילוצים.
   */
  if exists (
    select 1
    from public.dispatcher_availability availability
    where availability.period_id =
      requested_period_id
  ) then
    raise exception
      'Availability period already contains dispatcher responses';
  end if;

  if exists (
    select 1
    from public.availability_submissions submission
    where submission.period_id =
      requested_period_id
      and (
        submission.available_count > 0
        or submission.unavailable_count > 0
        or submission.submitted_at is not null
      )
  ) then
    raise exception
      'Availability period already contains submission data';
  end if;

  first_day_of_month :=
    make_date(
      target_year,
      target_month,
      1
    );

  last_day_of_month :=
    (
      first_day_of_month
      + interval '1 month'
      - interval '1 day'
    )::date;

  delete from
    public.availability_shift_slots
  where availability_shift_slots.period_id =
    requested_period_id;

  with month_dates as (
    select
      generated_date::date
        as shift_date,

      extract(
        dow from generated_date
      )::integer
        as weekday_number

    from generate_series(
      first_day_of_month,
      last_day_of_month,
      interval '1 day'
    ) generated_date
  ),

  classified_dates as (
    select
      month_date.shift_date,
      month_date.weekday_number,

      case
        when month_date.weekday_number = 0
          then 'ראשון'
        when month_date.weekday_number = 1
          then 'שני'
        when month_date.weekday_number = 2
          then 'שלישי'
        when month_date.weekday_number = 3
          then 'רביעי'
        when month_date.weekday_number = 4
          then 'חמישי'
        when month_date.weekday_number = 5
          then 'שישי'
        when month_date.weekday_number = 6
          then 'שבת'
      end
        as weekday_name,

      coalesce(
        special_day.schedule_type,

        case
          when month_date.weekday_number = 5
            then 'friday'
          when month_date.weekday_number = 6
            then 'saturday'
          else 'weekday'
        end
      )
        as effective_schedule_type,

      special_day.event_name
        as holiday_name

    from month_dates month_date

    left join lateral (
      select
        calendar_day.schedule_type,
        calendar_day.event_name

      from public.calendar_special_days
        calendar_day

      where calendar_day.event_date =
        month_date.shift_date

      /*
       * רשומה ידנית גוברת על Hebcal.
       * סדר הסוגים משמש הגנה במקרה
       * של יותר מרשומה אחת לאותו יום.
       */
      order by
        case
          when calendar_day.source_name =
            'manual'
            then 0
          else 1
        end,

        case calendar_day.schedule_type
          when 'holiday_full'
            then 1
          when 'holiday_end'
            then 2
          when 'holiday_eve'
            then 3
          when 'chol_hamoed'
            then 4
          else 5
        end

      limit 1
    ) special_day
      on true
  ),

  generated_shifts as (
    -- =====================================================
    -- יום חול וחול המועד
    -- =====================================================

    select
      date_row.shift_date,
      date_row.weekday_number,
      date_row.weekday_name,
      time '16:00'
        as start_time,
      time '23:00'
        as end_time,
      false
        as ends_next_day,
      date_row.effective_schedule_type
        as schedule_type,
      date_row.holiday_name,
      false
        as is_premium,
      1
        as sort_order

    from classified_dates date_row
    where date_row.effective_schedule_type
      in (
        'weekday',
        'chol_hamoed'
      )

    union all

    select
      date_row.shift_date,
      date_row.weekday_number,
      date_row.weekday_name,
      time '23:00',
      time '06:00',
      true,
      date_row.effective_schedule_type,
      date_row.holiday_name,
      false,
      2

    from classified_dates date_row
    where date_row.effective_schedule_type
      in (
        'weekday',
        'chol_hamoed'
      )

    -- =====================================================
    -- שישי רגיל
    -- =====================================================

    union all

    select
      date_row.shift_date,
      date_row.weekday_number,
      date_row.weekday_name,
      time '06:00',
      time '14:00',
      false,
      'friday',
      date_row.holiday_name,
      false,
      1

    from classified_dates date_row
    where date_row.effective_schedule_type =
      'friday'

    union all

    select
      date_row.shift_date,
      date_row.weekday_number,
      date_row.weekday_name,
      time '14:00',
      time '22:00',
      false,
      'friday',
      date_row.holiday_name,
      true,
      2

    from classified_dates date_row
    where date_row.effective_schedule_type =
      'friday'

    union all

    select
      date_row.shift_date,
      date_row.weekday_number,
      date_row.weekday_name,
      time '22:00',
      time '06:00',
      true,
      'friday',
      date_row.holiday_name,
      true,
      3

    from classified_dates date_row
    where date_row.effective_schedule_type =
      'friday'

    -- =====================================================
    -- שבת רגילה
    -- =====================================================

    union all

    select
      date_row.shift_date,
      date_row.weekday_number,
      date_row.weekday_name,
      time '06:00',
      time '14:00',
      false,
      'saturday',
      date_row.holiday_name,
      true,
      1

    from classified_dates date_row
    where date_row.effective_schedule_type =
      'saturday'

    union all

    select
      date_row.shift_date,
      date_row.weekday_number,
      date_row.weekday_name,
      time '14:00',
      time '22:00',
      false,
      'saturday',
      date_row.holiday_name,
      true,
      2

    from classified_dates date_row
    where date_row.effective_schedule_type =
      'saturday'

    union all

    select
      date_row.shift_date,
      date_row.weekday_number,
      date_row.weekday_name,
      time '22:00',
      time '06:00',
      true,
      'saturday',
      date_row.holiday_name,
      false,
      3

    from classified_dates date_row
    where date_row.effective_schedule_type =
      'saturday'

    -- =====================================================
    -- ערב חג
    -- =====================================================

    union all

    select
      date_row.shift_date,
      date_row.weekday_number,
      date_row.weekday_name,
      time '06:00',
      time '14:00',
      false,
      'holiday_eve',
      date_row.holiday_name,
      false,
      1

    from classified_dates date_row
    where date_row.effective_schedule_type =
      'holiday_eve'

    union all

    select
      date_row.shift_date,
      date_row.weekday_number,
      date_row.weekday_name,
      time '14:00',
      time '22:00',
      false,
      'holiday_eve',
      date_row.holiday_name,
      true,
      2

    from classified_dates date_row
    where date_row.effective_schedule_type =
      'holiday_eve'

    union all

    select
      date_row.shift_date,
      date_row.weekday_number,
      date_row.weekday_name,
      time '22:00',
      time '06:00',
      true,
      'holiday_eve',
      date_row.holiday_name,
      true,
      3

    from classified_dates date_row
    where date_row.effective_schedule_type =
      'holiday_eve'

    -- =====================================================
    -- חג מלא
    -- =====================================================

    union all

    select
      date_row.shift_date,
      date_row.weekday_number,
      date_row.weekday_name,
      time '06:00',
      time '14:00',
      false,
      'holiday_full',
      date_row.holiday_name,
      true,
      1

    from classified_dates date_row
    where date_row.effective_schedule_type =
      'holiday_full'

    union all

    select
      date_row.shift_date,
      date_row.weekday_number,
      date_row.weekday_name,
      time '14:00',
      time '22:00',
      false,
      'holiday_full',
      date_row.holiday_name,
      true,
      2

    from classified_dates date_row
    where date_row.effective_schedule_type =
      'holiday_full'

    union all

    select
      date_row.shift_date,
      date_row.weekday_number,
      date_row.weekday_name,
      time '22:00',
      time '06:00',
      true,
      'holiday_full',
      date_row.holiday_name,
      true,
      3

    from classified_dates date_row
    where date_row.effective_schedule_type =
      'holiday_full'

    -- =====================================================
    -- מוצאי / סיום חג
    -- =====================================================

    union all

    select
      date_row.shift_date,
      date_row.weekday_number,
      date_row.weekday_name,
      time '06:00',
      time '14:00',
      false,
      'holiday_end',
      date_row.holiday_name,
      true,
      1

    from classified_dates date_row
    where date_row.effective_schedule_type =
      'holiday_end'

    union all

    select
      date_row.shift_date,
      date_row.weekday_number,
      date_row.weekday_name,
      time '14:00',
      time '22:00',
      false,
      'holiday_end',
      date_row.holiday_name,
      true,
      2

    from classified_dates date_row
    where date_row.effective_schedule_type =
      'holiday_end'

    union all

    select
      date_row.shift_date,
      date_row.weekday_number,
      date_row.weekday_name,
      time '22:00',
      time '06:00',
      true,
      'holiday_end',
      date_row.holiday_name,
      false,
      3

    from classified_dates date_row
    where date_row.effective_schedule_type =
      'holiday_end'
  )

  insert into
    public.availability_shift_slots (
      period_id,
      shift_date,
      weekday_number,
      weekday_name,
      start_time,
      end_time,
      ends_next_day,
      schedule_type,
      holiday_name,
      is_premium,
      sort_order
    )
  select
    requested_period_id,
    generated_shift.shift_date,
    generated_shift.weekday_number,
    generated_shift.weekday_name,
    generated_shift.start_time,
    generated_shift.end_time,
    generated_shift.ends_next_day,
    generated_shift.schedule_type,
    generated_shift.holiday_name,
    generated_shift.is_premium,
    generated_shift.sort_order

  from generated_shifts
    generated_shift

  order by
    generated_shift.shift_date,
    generated_shift.sort_order;

  get diagnostics
    created_shift_count =
      row_count;

  update public.availability_periods
  set
    updated_by =
      current_user_id,
    updated_at =
      now()
  where id =
    requested_period_id;

  return query
  select
    requested_period_id,
    created_shift_count;
end;
$$;


ALTER FUNCTION "public"."rebuild_availability_period_slots"("requested_period_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_driver_schedule_assignment_change"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  resolved_change_type
    public.driver_assignment_change_type;
begin
  if old.assigned_user_id
    is not distinct from
    new.assigned_user_id
  then
    return new;
  end if;

  resolved_change_type :=
    case
      when new.assigned_user_id is null then
        'clear_assignment'
          ::public.driver_assignment_change_type

      when new.assignment_source = 'automatic' then
        'automatic_assignment'
          ::public.driver_assignment_change_type

      when new.assignment_source = 'swap' then
        'swap'
          ::public.driver_assignment_change_type

      when new.assignment_source = 'import' then
        'import'
          ::public.driver_assignment_change_type

      when old.assigned_user_id is null then
        'initial_assignment'
          ::public.driver_assignment_change_type

      else
        'manual_edit'
          ::public.driver_assignment_change_type
    end;

  insert into
    public.driver_schedule_assignment_history (
      schedule_day_id,
      previous_user_id,
      new_user_id,
      change_type,
      changed_by
    )
  values (
    new.id,
    old.assigned_user_id,
    new.assigned_user_id,
    resolved_change_type,
    auth.uid()
  );

  return new;
end;
$$;


ALTER FUNCTION "public"."record_driver_schedule_assignment_change"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_schedule_assignment_change"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  resolved_change_type public.assignment_change_type;
begin
  if old.assigned_user_id is not distinct from new.assigned_user_id then
    return new;
  end if;

  resolved_change_type :=
    case
      when new.assigned_user_id is null then
        'clear_assignment'::public.assignment_change_type

      when old.assigned_user_id is null
        and new.assignment_source = 'automatic' then
        'automatic_assignment'::public.assignment_change_type

      when old.assigned_user_id is null
        and new.assignment_source = 'import' then
        'import'::public.assignment_change_type

      when old.assigned_user_id is null
        and new.assignment_source = 'shift_swap' then
        'shift_swap'::public.assignment_change_type

      when old.assigned_user_id is null then
        'initial_assignment'::public.assignment_change_type

      when new.assignment_source = 'automatic' then
        'automatic_assignment'::public.assignment_change_type

      when new.assignment_source = 'import' then
        'import'::public.assignment_change_type

      when new.assignment_source = 'shift_swap' then
        'shift_swap'::public.assignment_change_type

      else
        'manual_edit'::public.assignment_change_type
    end;

  insert into public.schedule_assignment_history (
    shift_id,
    previous_user_id,
    new_user_id,
    change_type,
    changed_by
  )
  values (
    new.id,
    old.assigned_user_id,
    new.assigned_user_id,
    resolved_change_type,
    (select auth.uid())
  );

  return new;
end;
$$;


ALTER FUNCTION "public"."record_schedule_assignment_change"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_user_login"() RETURNS timestamp with time zone
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  login_time timestamptz := now();
  affected_rows integer;
begin
  if auth.uid() is null then
    raise exception 'User is not authenticated';
  end if;

  update public.profiles
  set
    last_login_at = login_time,
    updated_at = login_time
  where id = auth.uid();

  get diagnostics affected_rows = row_count;

  if affected_rows = 0 then
    raise exception 'User profile was not found';
  end if;

  return login_time;
end;
$$;


ALTER FUNCTION "public"."record_user_login"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."register_my_daily_report_attachment"("requested_report_id" "uuid", "requested_storage_path" "text", "requested_file_name" "text", "requested_mime_type" "text", "requested_file_size" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare actor uuid:=auth.uid(); aid uuid; jid uuid;
begin
 if actor is null then raise exception 'not authenticated'; end if;
 select r.job_type_id into jid from public.daily_reports r
 where r.id=requested_report_id and r.user_id=actor and r.status='draft';
 if jid is null or not public.has_dynamic_job_type_permission('daily_reports.upload_attachment',jid,actor)
 then raise exception 'not allowed'; end if;
 if requested_storage_path not like requested_report_id::text||'/%' then raise exception 'invalid storage path'; end if;
 if requested_file_size<=0 or requested_file_size>10485760 then raise exception 'invalid file size'; end if;
 insert into public.daily_report_attachments(report_id,storage_path,file_name,mime_type,file_size,uploaded_by)
 values(requested_report_id,requested_storage_path,left(requested_file_name,255),requested_mime_type,requested_file_size,actor)
 returning id into aid;
 return jsonb_build_object('id',aid);
end $$;


ALTER FUNCTION "public"."register_my_daily_report_attachment"("requested_report_id" "uuid", "requested_storage_path" "text", "requested_file_name" "text", "requested_mime_type" "text", "requested_file_size" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."register_push_subscription"("requested_endpoint" "text", "requested_p256dh_key" "text", "requested_auth_key" "text", "requested_user_agent" "text" DEFAULT NULL::"text", "requested_device_name" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  current_user_id uuid;
  subscription_id uuid;
begin
  current_user_id :=
    auth.uid();

  if current_user_id is null then
    raise exception
      'not authenticated';
  end if;

  if not exists (
    select 1
    from public.profiles
    where id =
      current_user_id
      and is_active = true
  ) then
    raise exception
      'user not active';
  end if;

  if nullif(
    trim(
      coalesce(
        requested_endpoint,
        ''
      )
    ),
    ''
  ) is null then
    raise exception
      'push endpoint is required';
  end if;

  if nullif(
    trim(
      coalesce(
        requested_p256dh_key,
        ''
      )
    ),
    ''
  ) is null then
    raise exception
      'p256dh key is required';
  end if;

  if nullif(
    trim(
      coalesce(
        requested_auth_key,
        ''
      )
    ),
    ''
  ) is null then
    raise exception
      'auth key is required';
  end if;

  insert into public.push_subscriptions (
    user_id,
    endpoint,
    p256dh_key,
    auth_key,
    user_agent,
    device_name,
    is_active,
    last_used_at
  )
  values (
    current_user_id,
    requested_endpoint,
    requested_p256dh_key,
    requested_auth_key,
    requested_user_agent,
    requested_device_name,
    true,
    now()
  )

  on conflict (endpoint)
  do update
  set
    user_id =
      current_user_id,

    p256dh_key =
      excluded.p256dh_key,

    auth_key =
      excluded.auth_key,

    user_agent =
      excluded.user_agent,

    device_name =
      excluded.device_name,

    is_active =
      true,

    last_used_at =
      now()

  returning id
  into subscription_id;

  return subscription_id;
end;
$$;


ALTER FUNCTION "public"."register_push_subscription"("requested_endpoint" "text", "requested_p256dh_key" "text", "requested_auth_key" "text", "requested_user_agent" "text", "requested_device_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."remove_dynamic_schedule_draft_assignment"("requested_draft_id" "uuid", "requested_assignment_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_user uuid:=auth.uid();
  d public.dynamic_schedule_shadow_drafts%rowtype;
  a public.dynamic_schedule_shadow_assignments%rowtype;
begin
  if v_user is null then raise exception 'not authenticated'; end if;
  select * into d from public.dynamic_schedule_shadow_drafts where id=requested_draft_id;
  if not public.has_dynamic_job_type_permission('schedule.edit_draft', d.job_type_id, v_user) then raise exception 'not allowed'; end if;
  if d.id is null or d.status not in ('generated','incomplete') then raise exception 'draft is not editable'; end if;
  select * into a from public.dynamic_schedule_shadow_assignments where id=requested_assignment_id and draft_id=d.id;
  if a.id is null then raise exception 'assignment not found'; end if;
  delete from public.dynamic_schedule_shadow_assignments where id=a.id;
  perform public.dynamic_refresh_draft_metrics(d.id);
  insert into public.audit_logs(action,actor_user_id,entity_type,entity_id,summary,metadata)
  values('system_event',v_user,'dynamic_schedule_draft',d.id,'שיבוץ הוסר מטיוטה דינמית',
    jsonb_build_object('draft_id',d.id,'slot_id',a.slot_id,'assignment_id',a.id,'user_id',a.user_id));
  return jsonb_build_object('removed',true,'assignmentId',a.id,'slotId',a.slot_id);
end;
$$;


ALTER FUNCTION "public"."remove_dynamic_schedule_draft_assignment"("requested_draft_id" "uuid", "requested_assignment_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reopen_availability_period"("requested_period_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  current_user_id uuid := auth.uid();
  current_actor_email text;
  current_actor_display_name text;
  target_period public.availability_periods%rowtype;
  reopened_at_value timestamptz := now();
begin
  if current_user_id is null then
    raise exception 'not authenticated';
  end if;

  select
    profile.email,
    profile.display_name
  into
    current_actor_email,
    current_actor_display_name
  from public.profiles profile
  where profile.id = current_user_id
    and profile.is_active = true;

  if current_actor_email is null then
    raise exception 'user not active';
  end if;

  if not exists (
    select 1
    from public.user_permissions permission
    where permission.user_id = current_user_id
      and permission.permission_key = 'availability.manage'
  ) then
    raise exception 'not allowed';
  end if;

  if requested_period_id is null then
    raise exception 'availability period id is required';
  end if;

  select *
  into target_period
  from public.availability_periods period
  where period.id = requested_period_id
  for update;

  if not found then
    raise exception 'availability period not found';
  end if;

  if target_period.status <> 'closed' then
    raise exception 'only closed availability periods can be reopened';
  end if;

  update public.availability_periods
  set
    status = 'open',
    opened_at = reopened_at_value,
    closed_at = null,
    updated_by = current_user_id,
    updated_at = reopened_at_value
  where id = target_period.id;

  update public.availability_submissions
  set
    status = 'reopened',
    reopened_at = reopened_at_value,
    updated_at = reopened_at_value
  where period_id = target_period.id
    and status = 'submitted';

  insert into public.audit_logs (
    action,
    actor_user_id,
    actor_email,
    actor_display_name,
    target_user_id,
    target_email,
    target_display_name,
    entity_type,
    entity_id,
    summary,
    old_values,
    new_values,
    metadata
  )
  values (
    'availability_period_opened',
    current_user_id,
    current_actor_email,
    current_actor_display_name,
    null,
    null,
    null,
    'availability_period',
    target_period.id,
    format(
      'נפתחה מחדש תקופת אילוצים: %s',
      coalesce(
        target_period.title,
        format('%s/%s', target_period.month, target_period.year)
      )
    ),
    jsonb_build_object(
      'status', 'closed',
      'closed_at', target_period.closed_at
    ),
    jsonb_build_object(
      'status', 'open',
      'opened_at', reopened_at_value,
      'closed_at', null
    ),
    jsonb_build_object(
      'source', 'reopen-availability-period-rpc',
      'period_id', target_period.id,
      'year', target_period.year,
      'month', target_period.month
    )
  );

  return jsonb_build_object(
    'periodId', target_period.id,
    'periodStatus', 'open',
    'openedAt', reopened_at_value
  );
end;
$$;


ALTER FUNCTION "public"."reopen_availability_period"("requested_period_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reopen_driver_availability_period"("requested_period_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  current_user_id uuid;
  current_permissions text[];

  reopened_period
    public.driver_availability_periods%rowtype;

  updated_submissions integer := 0;
begin
  current_user_id :=
    auth.uid();

  if current_user_id is null then
    raise exception
      'not authenticated';
  end if;

  if not exists (
    select 1
    from public.profiles
    where id =
      current_user_id
      and is_active = true
  ) then
    raise exception
      'user not active';
  end if;

  current_permissions :=
    coalesce(
      public.get_my_permissions(),
      array[]::text[]
    );

  if not (
    'driver_availability.manage' =
      any(current_permissions)
  ) then
    raise exception
      'not allowed';
  end if;

  if requested_period_id is null then
    raise exception
      'driver availability period id is required';
  end if;

  select *
  into reopened_period
  from public.driver_availability_periods
  where id =
    requested_period_id
  for update;

  if not found then
    raise exception
      'driver availability period not found';
  end if;

  if reopened_period.status::text <>
      'closed'
  then
    raise exception
      'only closed driver availability periods can be reopened';
  end if;

  /*
   * Once a schedule already exists for this availability period,
   * reopening constraints would make the schedule inconsistent.
   * Delete/rebuild the schedule first if the period must be reopened.
   */
  if exists (
    select 1
    from public.driver_schedule_periods
      schedule_period
    where schedule_period.availability_period_id =
      requested_period_id
  ) then
    raise exception
      'driver availability period already has a schedule';
  end if;

  update public.driver_availability_periods
  set
    status =
      'open',

    closed_at =
      null,

    opened_at =
      coalesce(
        opened_at,
        now()
      ),

    updated_by =
      current_user_id,

    updated_at =
      now()

  where id =
    requested_period_id

  returning *
  into reopened_period;

  update public.driver_availability_submissions
  set
    status =
      'reopened',

    submitted_at =
      null,

    updated_at =
      now()

  where period_id =
      requested_period_id
    and status::text =
      'submitted';

  get diagnostics
    updated_submissions =
      row_count;

  perform public.write_audit_log(
    requested_action :=
      'driver_availability_period_reopened'
        ::public.audit_action_type,

    requested_target_user_id :=
      null,

    requested_summary :=
      'Driver availability period reopened',

    requested_old_values :=
      jsonb_build_object(
        'status',
        'closed'
      ),

    requested_new_values :=
      jsonb_build_object(
        'status',
        'open'
      ),

    requested_metadata :=
      jsonb_build_object(
        'periodId',
          reopened_period.id,

        'year',
          reopened_period.year,

        'month',
          reopened_period.month,

        'reopenedSubmissions',
          updated_submissions
      )
  );

  return jsonb_build_object(
    'periodId',
      reopened_period.id,

    'year',
      reopened_period.year,

    'month',
      reopened_period.month,

    'status',
      reopened_period.status,

    'openedAt',
      reopened_period.opened_at,

    'reopenedSubmissions',
      updated_submissions
  );
end;
$$;


ALTER FUNCTION "public"."reopen_driver_availability_period"("requested_period_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reopen_morning_driver_availability_period"("requested_period_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_user_id uuid := auth.uid();
  current_permissions text[];
  target_period public.morning_driver_availability_periods%rowtype;
  reopened_at timestamptz := now();
begin
  if actor_user_id is null then
    raise exception 'not authenticated';
  end if;

  if not exists (
    select 1
    from public.profiles
    where id = actor_user_id
      and is_active = true
  ) then
    raise exception 'user not active';
  end if;

  current_permissions :=
    coalesce(
      public.get_my_permissions(),
      array[]::text[]
    );

  if not (
    'morning_driver_availability.manage' =
      any(current_permissions)
  ) then
    raise exception 'not allowed';
  end if;

  select *
  into target_period
  from public.morning_driver_availability_periods
  where id = requested_period_id
  for update;

  if not found then
    raise exception 'morning driver availability period not found';
  end if;

  if target_period.status <> 'closed' then
    raise exception 'only closed morning driver availability periods can be reopened';
  end if;

  update public.morning_driver_availability_periods
  set
    status = 'open',
    opened_at = reopened_at,
    closed_at = null,
    updated_by = actor_user_id,
    updated_at = reopened_at
  where id = target_period.id;

  update public.morning_driver_availability_submissions
  set
    status = 'reopened',
    updated_at = reopened_at
  where period_id = target_period.id
    and status = 'submitted';

  insert into public.audit_logs (
    user_id,
    action,
    entity_type,
    entity_id,
    summary,
    metadata
  )
  values (
    actor_user_id,
    'morning_driver_availability.period.reopened',
    'morning_driver_availability_period',
    target_period.id,
    'תקופת אילוצי כונני בוקר נפתחה מחדש',
    jsonb_build_object(
      'year', target_period.year,
      'month', target_period.month
    )
  );

  return jsonb_build_object(
    'periodId', target_period.id,
    'year', target_period.year,
    'month', target_period.month,
    'status', 'open',
    'openedAt', reopened_at
  );
end;
$$;


ALTER FUNCTION "public"."reopen_morning_driver_availability_period"("requested_period_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reopen_morning_driver_availability_submission"("requested_period_id" "uuid", "requested_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  current_user_id uuid;
  current_permissions text[];

  target_period
    public.morning_driver_availability_periods%rowtype;

  target_submission
    public.morning_driver_availability_submissions%rowtype;

  reopened_at_value timestamptz := now();
begin
  current_user_id := auth.uid();

  if current_user_id is null then
    raise exception 'not authenticated';
  end if;

  current_permissions :=
    coalesce(
      public.get_my_permissions(),
      array[]::text[]
    );

  if not (
    'morning_driver_availability.manage'
      = any(current_permissions)
  ) then
    raise exception 'not allowed';
  end if;

  if requested_period_id is null then
    raise exception 'period id is required';
  end if;

  if requested_user_id is null then
    raise exception 'user id is required';
  end if;

  select *
  into target_period
  from public.morning_driver_availability_periods period
  where period.id = requested_period_id
  for update;

  if not found then
    raise exception 'morning driver availability period not found';
  end if;

  if target_period.status <> 'open' then
    raise exception 'only open periods support reopening submissions';
  end if;

  select *
  into target_submission
  from public.morning_driver_availability_submissions submission
  where submission.period_id = target_period.id
    and submission.user_id = requested_user_id
  for update;

  if not found then
    raise exception 'morning driver availability submission not found';
  end if;

  if target_submission.status <> 'submitted' then
    raise exception 'only submitted availability can be reopened';
  end if;

  update public.morning_driver_availability_submissions
  set
    status = 'reopened',
    submitted_at = null,
    updated_at = reopened_at_value
  where id = target_submission.id
  returning *
  into target_submission;

  return jsonb_build_object(
    'periodId',
      target_period.id,

    'userId',
      requested_user_id,

    'submissionId',
      target_submission.id,

    'status',
      target_submission.status,

    'reopenedAt',
      reopened_at_value
  );
end;
$$;


ALTER FUNCTION "public"."reopen_morning_driver_availability_submission"("requested_period_id" "uuid", "requested_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."report_my_client_version"("requested_client_id" "text", "requested_app_version" "text", "requested_build_id" "text", "requested_is_pwa" boolean DEFAULT false, "requested_platform" "text" DEFAULT NULL::"text", "requested_user_agent" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  current_user_id uuid := auth.uid();
begin
  if current_user_id is null then
    raise exception 'not authenticated';
  end if;

  if not exists (
    select 1 from public.profiles p
    where p.id = current_user_id and p.is_active = true
  ) then
    raise exception 'user not active';
  end if;

  if nullif(trim(requested_client_id), '') is null
     or nullif(trim(requested_app_version), '') is null
     or nullif(trim(requested_build_id), '') is null then
    raise exception 'invalid client version payload';
  end if;

  insert into public.client_app_sessions (
    user_id,
    client_id,
    app_version,
    build_id,
    is_pwa,
    platform,
    user_agent,
    last_seen_at
  ) values (
    current_user_id,
    left(trim(requested_client_id), 160),
    left(trim(requested_app_version), 80),
    left(trim(requested_build_id), 120),
    coalesce(requested_is_pwa, false),
    nullif(left(trim(coalesce(requested_platform, '')), 160), ''),
    nullif(left(trim(coalesce(requested_user_agent, '')), 600), ''),
    now()
  )
  on conflict (user_id, client_id) do update set
    app_version = excluded.app_version,
    build_id = excluded.build_id,
    is_pwa = excluded.is_pwa,
    platform = excluded.platform,
    user_agent = excluded.user_agent,
    last_seen_at = now();
end;
$$;


ALTER FUNCTION "public"."report_my_client_version"("requested_client_id" "text", "requested_app_version" "text", "requested_build_id" "text", "requested_is_pwa" boolean, "requested_platform" "text", "requested_user_agent" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resolve_dynamic_shift_display_name"("requested_job_type_id" "uuid", "requested_shift_date" "date", "requested_shift_code" "text", "requested_shift_name" "text", "requested_start_time" time without time zone, "requested_end_time" time without time zone, "requested_fallback" "text" DEFAULT 'משמרת'::"text") RETURNS "text"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
  select coalesce(
    (
      select nullif(st.name,'')
      from public.job_type_schedule_materializations mat
      join public.job_type_materialized_shift_templates st
        on st.materialization_id=mat.id
       and st.is_active=true
      where mat.job_type_id=requested_job_type_id
        and mat.effective_month<=date_trunc('month',requested_shift_date)::date
        and st.start_time=requested_start_time
        and st.end_time=requested_end_time
      order by mat.effective_month desc,
               case when st.code=requested_shift_code then 0 else 1 end,
               st.sort_order,st.name
      limit 1
    ),
    case
      when nullif(trim(coalesce(requested_shift_name,'')),'') is null then null
      when trim(requested_shift_name) ~ '^[0-9]{8}-[0-9]{4}$' then null
      when trim(requested_shift_name) ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}[-_T ][0-9]{2}:?[0-9]{2}$' then null
      when lower(trim(requested_shift_name)) ~ '^slot[-_:]' then null
      when requested_shift_name=requested_shift_code then null
      else trim(requested_shift_name)
    end,
    nullif(trim(coalesce(requested_fallback,'')),''),
    'משמרת'
  );
$_$;


ALTER FUNCTION "public"."resolve_dynamic_shift_display_name"("requested_job_type_id" "uuid", "requested_shift_date" "date", "requested_shift_code" "text", "requested_shift_name" "text", "requested_start_time" time without time zone, "requested_end_time" time without time zone, "requested_fallback" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."respond_to_dynamic_shift_exchange_request"("requested_request_id" "uuid", "requested_approve" boolean, "requested_rejection_reason" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  current_user_id uuid := auth.uid();
  r public.dynamic_shift_exchange_requests%rowtype;
  ra public.dynamic_schedule_published_assignments%rowtype;
  ca public.dynamic_schedule_published_assignments%rowtype;
begin
  if current_user_id is null then raise exception 'not authenticated'; end if;
  select * into r from public.dynamic_shift_exchange_requests where id=requested_request_id for update;
  if r.id is null then raise exception 'הבקשה לא נמצאה.'; end if;
  if r.counterparty_user_id<>current_user_id then raise exception 'רק העובד שהתבקש להחליף יכול להגיב.'; end if;
  if r.status<>'pending_counterparty' then raise exception 'הבקשה אינה ממתינה לתגובה.'; end if;

  if requested_approve then
    select * into ra from public.dynamic_schedule_published_assignments where id=r.requester_assignment_id;
    if ra.id is null or ra.user_id<>r.requester_user_id or public.dynamic_assignment_starts_at(ra)<=now() then raise exception 'השיבוץ המקורי השתנה או כבר התחיל.'; end if;
    if r.swap_type='two_way' then
      select * into ca from public.dynamic_schedule_published_assignments where id=r.counterparty_assignment_id;
      if ca.id is null or ca.user_id<>r.counterparty_user_id or public.dynamic_assignment_starts_at(ca)<=now() then raise exception 'השיבוץ הנגדי השתנה או כבר התחיל.'; end if;
    end if;
    if public.dynamic_user_has_overlap(r.publication_id,r.counterparty_user_id,ra.id,case when r.swap_type='two_way' then ca.id else null end) then raise exception 'ההחלפה תיצור משמרות חופפות.'; end if;
    if r.swap_type='two_way' and public.dynamic_user_has_overlap(r.publication_id,r.requester_user_id,ca.id,ra.id) then raise exception 'ההחלפה תיצור משמרות חופפות.'; end if;
    update public.dynamic_shift_exchange_requests set status='pending_manager',counterparty_responded_at=now(),rejection_reason=null,updated_at=now() where id=r.id returning * into r;
    insert into public.audit_logs(action,actor_user_id,entity_type,entity_id,summary,metadata)
    values('shift_swap_counterparty_approved',current_user_id,'dynamic_shift_exchange_request',r.id,'הצד השני אישר בקשת חילופים דינמית','{}'::jsonb);
  else
    update public.dynamic_shift_exchange_requests set status='rejected_by_counterparty',counterparty_responded_at=now(),rejection_reason=nullif(trim(coalesce(requested_rejection_reason,'')) ,''),updated_at=now() where id=r.id returning * into r;
    insert into public.audit_logs(action,actor_user_id,entity_type,entity_id,summary,metadata)
    values('shift_swap_counterparty_rejected',current_user_id,'dynamic_shift_exchange_request',r.id,'הצד השני דחה בקשת חילופים דינמית','{}'::jsonb);
  end if;
  return jsonb_build_object('id',r.id,'status',r.status);
end;
$$;


ALTER FUNCTION "public"."respond_to_dynamic_shift_exchange_request"("requested_request_id" "uuid", "requested_approve" boolean, "requested_rejection_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."respond_to_shift_swap_request"("requested_request_id" "uuid", "requested_approve" boolean, "requested_rejection_reason" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  current_user_id uuid := auth.uid();
  request_row public.shift_swap_requests%rowtype;
  validation_result jsonb;
  next_status text;
begin
  if current_user_id is null then
    raise exception 'לא נמצאה התחברות פעילה.';
  end if;

  if not public.current_user_has_permission('shift_swaps.view') then
    raise exception 'אין לך הרשאה לטפל בבקשות להחלפת משמרות.';
  end if;

  select *
  into request_row
  from public.shift_swap_requests
  where id = requested_request_id
  for update;

  if not found then
    raise exception 'בקשת ההחלפה לא נמצאה.';
  end if;

  if request_row.counterparty_user_id <> current_user_id then
    raise exception 'רק המוקדן שהתבקש להחליף יכול להגיב לבקשה.';
  end if;

  if request_row.status <> 'pending_counterparty' then
    raise exception 'הבקשה אינה ממתינה עוד לאישור המוקדן.';
  end if;

  if requested_approve then
    validation_result := public.validate_shift_swap_final_state(
      request_row.swap_type,
      request_row.requester_user_id,
      request_row.counterparty_user_id,
      request_row.requester_shift_id,
      request_row.counterparty_shift_id
    );

    if not coalesce((validation_result ->> 'valid')::boolean, false) then
      raise exception '%', validation_result ->> 'message';
    end if;

    next_status := 'pending_manager';
  else
    next_status := 'rejected_by_counterparty';
  end if;

  update public.shift_swap_requests
  set
    status = next_status,
    counterparty_responded_at = now(),
    rejection_reason = case
      when requested_approve then null
      else nullif(trim(coalesce(requested_rejection_reason, '')), '')
    end
  where id = request_row.id
  returning * into request_row;

  return jsonb_build_object(
    'id', request_row.id,
    'status', request_row.status,
    'requesterUserId', request_row.requester_user_id,
    'counterpartyUserId', request_row.counterparty_user_id,
    'counterpartyRespondedAt', request_row.counterparty_responded_at
  );
end;
$$;


ALTER FUNCTION "public"."respond_to_shift_swap_request"("requested_request_id" "uuid", "requested_approve" boolean, "requested_rejection_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."review_dynamic_shift_exchange_request"("requested_request_id" "uuid", "requested_approve" boolean, "requested_rejection_reason" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  current_user_id uuid := auth.uid();
  r public.dynamic_shift_exchange_requests%rowtype;
  ra public.dynamic_schedule_published_assignments%rowtype;
  ca public.dynamic_schedule_published_assignments%rowtype;
begin
  if current_user_id is null then raise exception 'not authenticated'; end if;
  if not public.current_user_has_permission('shift_swaps.approve') then raise exception 'אין לך הרשאה לאשר חילופי משמרות.'; end if;
  select * into r from public.dynamic_shift_exchange_requests where id=requested_request_id for update;
  if r.id is null or r.status<>'pending_manager' then raise exception 'הבקשה אינה ממתינה לאישור מנהל.'; end if;

  if not requested_approve then
    update public.dynamic_shift_exchange_requests set status='rejected_by_manager',manager_user_id=current_user_id,manager_reviewed_at=now(),rejection_reason=nullif(trim(coalesce(requested_rejection_reason,'')),''),updated_at=now() where id=r.id returning * into r;
    insert into public.audit_logs(action,actor_user_id,entity_type,entity_id,summary,metadata)
    values('shift_swap_manager_rejected',current_user_id,'dynamic_shift_exchange_request',r.id,'מנהל דחה בקשת חילופים דינמית','{}'::jsonb);
    return jsonb_build_object('id',r.id,'status',r.status);
  end if;

  select * into ra from public.dynamic_schedule_published_assignments where id=r.requester_assignment_id for update;
  if ra.id is null or ra.user_id<>r.requester_user_id or public.dynamic_assignment_starts_at(ra)<=now() then raise exception 'השיבוץ המקורי השתנה או כבר התחיל.'; end if;
  if r.swap_type='two_way' then
    select * into ca from public.dynamic_schedule_published_assignments where id=r.counterparty_assignment_id for update;
    if ca.id is null or ca.user_id<>r.counterparty_user_id or public.dynamic_assignment_starts_at(ca)<=now() then raise exception 'השיבוץ הנגדי השתנה או כבר התחיל.'; end if;
  end if;

  if public.dynamic_user_has_overlap(r.publication_id,r.counterparty_user_id,ra.id,case when r.swap_type='two_way' then ca.id else null end) then raise exception 'ההחלפה תיצור משמרות חופפות.'; end if;
  if r.swap_type='two_way' and public.dynamic_user_has_overlap(r.publication_id,r.requester_user_id,ca.id,ra.id) then raise exception 'ההחלפה תיצור משמרות חופפות.'; end if;

  update public.dynamic_schedule_published_assignments set user_id=r.counterparty_user_id,user_edited_by=current_user_id,user_edited_at=now() where id=ra.id;
  if r.swap_type='two_way' then
    update public.dynamic_schedule_published_assignments set user_id=r.requester_user_id,user_edited_by=current_user_id,user_edited_at=now() where id=ca.id;
  end if;

  update public.dynamic_shift_exchange_requests set status='approved',manager_user_id=current_user_id,manager_reviewed_at=now(),rejection_reason=null,updated_at=now() where id=r.id returning * into r;
  insert into public.audit_logs(action,actor_user_id,entity_type,entity_id,summary,metadata)
  values('shift_swap_manager_approved',current_user_id,'dynamic_shift_exchange_request',r.id,'מנהל אישר חילופי משמרות דינמיים',jsonb_build_object('publication_id',r.publication_id,'job_type_id',r.job_type_id,'swap_type',r.swap_type));
  return jsonb_build_object('id',r.id,'status',r.status);
end;
$$;


ALTER FUNCTION "public"."review_dynamic_shift_exchange_request"("requested_request_id" "uuid", "requested_approve" boolean, "requested_rejection_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."review_shift_swap_request"("requested_request_id" "uuid", "requested_approve" boolean, "requested_rejection_reason" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  current_user_id uuid := auth.uid();
  request_row public.shift_swap_requests%rowtype;
  requester_shift public.schedule_shifts%rowtype;
  counterparty_shift public.schedule_shifts%rowtype;
  validation_result jsonb;
begin
  if current_user_id is null then
    raise exception 'לא נמצאה התחברות פעילה.';
  end if;

  if not public.current_user_has_permission('shift_swaps.approve') then
    raise exception 'אין לך הרשאה לאשר או לדחות בקשות החלפה.';
  end if;

  select *
  into request_row
  from public.shift_swap_requests
  where id = requested_request_id
  for update;

  if not found then
    raise exception 'בקשת ההחלפה לא נמצאה.';
  end if;

  if request_row.status <> 'pending_manager' then
    raise exception 'הבקשה אינה ממתינה לאישור מנהל.';
  end if;

  if not requested_approve then
    update public.shift_swap_requests
    set
      status = 'rejected_by_manager',
      manager_user_id = current_user_id,
      manager_reviewed_at = now(),
      rejection_reason = nullif(trim(coalesce(requested_rejection_reason, '')), '')
    where id = request_row.id
    returning * into request_row;

    return jsonb_build_object(
      'id', request_row.id,
      'status', request_row.status,
      'requesterUserId', request_row.requester_user_id,
      'counterpartyUserId', request_row.counterparty_user_id,
      'managerUserId', request_row.manager_user_id,
      'managerReviewedAt', request_row.manager_reviewed_at
    );
  end if;

  select *
  into requester_shift
  from public.schedule_shifts
  where id = request_row.requester_shift_id
  for update;

  if not found
    or requester_shift.assigned_user_id is distinct from request_row.requester_user_id then
    raise exception 'השיבוץ המקורי השתנה מאז יצירת הבקשה. יש ליצור בקשה חדשה.';
  end if;

  if requester_shift.starts_at <= now() then
    raise exception 'לא ניתן לאשר החלפה לאחר שהמשמרת התחילה.';
  end if;

  if request_row.swap_type = 'two_way' then
    select *
    into counterparty_shift
    from public.schedule_shifts
    where id = request_row.counterparty_shift_id
    for update;

    if not found
      or counterparty_shift.assigned_user_id is distinct from request_row.counterparty_user_id then
      raise exception 'השיבוץ של המוקדן השני השתנה מאז יצירת הבקשה. יש ליצור בקשה חדשה.';
    end if;

    if counterparty_shift.starts_at <= now() then
      raise exception 'לא ניתן לאשר החלפה לאחר שאחת המשמרות התחילה.';
    end if;
  end if;

  validation_result := public.validate_shift_swap_final_state(
    request_row.swap_type,
    request_row.requester_user_id,
    request_row.counterparty_user_id,
    request_row.requester_shift_id,
    request_row.counterparty_shift_id
  );

  if not coalesce((validation_result ->> 'valid')::boolean, false) then
    raise exception '%', validation_result ->> 'message';
  end if;

  update public.schedule_shifts
  set
    assigned_user_id = request_row.counterparty_user_id,
    assignment_source = 'shift_swap'
  where id = request_row.requester_shift_id;

  if request_row.swap_type = 'two_way' then
    update public.schedule_shifts
    set
      assigned_user_id = request_row.requester_user_id,
      assignment_source = 'shift_swap'
    where id = request_row.counterparty_shift_id;
  end if;

  update public.shift_swap_requests
  set
    status = 'approved',
    manager_user_id = current_user_id,
    manager_reviewed_at = now(),
    rejection_reason = null
  where id = request_row.id
  returning * into request_row;

  return jsonb_build_object(
    'id', request_row.id,
    'status', request_row.status,
    'swapType', request_row.swap_type,
    'requesterUserId', request_row.requester_user_id,
    'counterpartyUserId', request_row.counterparty_user_id,
    'requesterShiftId', request_row.requester_shift_id,
    'counterpartyShiftId', request_row.counterparty_shift_id,
    'managerUserId', request_row.manager_user_id,
    'managerReviewedAt', request_row.manager_reviewed_at
  );
end;
$$;


ALTER FUNCTION "public"."review_shift_swap_request"("requested_request_id" "uuid", "requested_approve" boolean, "requested_rejection_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."run_gvk_legacy_migration"("requested_mappings" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_actor uuid := auth.uid();
  requested_dispatcher_job_type_id uuid := nullif(requested_mappings->>'dispatcher','')::uuid;
  requested_on_call_job_type_id uuid := nullif(requested_mappings->>'on_call','')::uuid;
  requested_morning_driver_job_type_id uuid := nullif(requested_mappings->>'morning_driver','')::uuid;
  v_preview jsonb;
  v_run_id uuid;
  v_current_ym integer := extract(year from (now() at time zone 'Asia/Jerusalem'))::integer * 100
    + extract(month from (now() at time zone 'Asia/Jerusalem'))::integer;
  v_source text;
  v_job_type_id uuid;
  v_job public.job_types%rowtype;
  v_period record;
  v_dynamic_period_id uuid;
  v_draft_id uuid;
  v_publication_id uuid;
  v_hist jsonb;
  v_members_added integer := 0;
  v_live_periods_added integer := 0;
  v_live_assignments_added integer := 0;
  v_unassigned_added integer := 0;
  v_history jsonb := '{}'::jsonb;
  v_result jsonb;
begin
  -- SQL editor execution has no JWT. In that trusted context, select one active
  -- users.manage actor for audit records and seed the JWT claim so existing
  -- idempotent history-import RPCs can be reused unchanged.
  if v_actor is null and current_user in ('postgres','supabase_admin','service_role') then
    select up.user_id into v_actor
    from public.user_permissions up
    join public.profiles p on p.id=up.user_id and p.is_active=true
    where up.permission_key='users.manage'
    order by p.created_at
    limit 1;
    if v_actor is null then raise exception 'no active users.manage actor found'; end if;
    perform set_config('request.jwt.claim.sub',v_actor::text,true);
  end if;

  if v_actor is null then raise exception 'not authenticated'; end if;
  if not exists(select 1 from public.user_permissions up where up.user_id=v_actor and up.permission_key='users.manage') then
    raise exception 'not allowed';
  end if;

  v_preview := public.preview_gvk_legacy_migration(requested_mappings);
  if coalesce((v_preview->>'ready')::boolean,false)=false then
    raise exception 'migration preview contains blockers: %', v_preview->'blockers';
  end if;

  insert into public.gvk_legacy_migration_runs(
    dispatcher_job_type_id,on_call_job_type_id,morning_driver_job_type_id,status,created_by
  ) values(
    requested_dispatcher_job_type_id,requested_on_call_job_type_id,requested_morning_driver_job_type_id,'running',v_actor
  ) returning id into v_run_id;

  -- Copy role memberships first. Existing dynamic membership metadata wins.
  insert into public.job_type_memberships(user_id,job_type_id,is_primary,source,metadata)
  select p.id,requested_dispatcher_job_type_id,false,'legacy_cutover',
         jsonb_build_object('employmentScope',case when jt.employment_scope='flexible' then 'full_time' else jt.employment_scope end,'legacyRole','dispatcher')
  from public.profiles p cross join public.job_types jt
  where jt.id=requested_dispatcher_job_type_id and (
    p.role::text='dispatcher' or exists(
      select 1 from public.schedule_shifts s join public.schedule_periods sp on sp.id=s.period_id
      where s.assigned_user_id=p.id and sp.status::text in ('published','archived') and (sp.year*100+sp.month)>=v_current_ym
    )
  )
  on conflict(user_id,job_type_id) do nothing;
  get diagnostics v_members_added = row_count;

  insert into public.job_type_memberships(user_id,job_type_id,is_primary,source,metadata)
  select p.id,requested_on_call_job_type_id,false,'legacy_cutover',
         jsonb_build_object('employmentScope',case when jt.employment_scope='flexible' then 'full_time' else jt.employment_scope end,'legacyRole','on_call')
  from public.profiles p cross join public.job_types jt
  where jt.id=requested_on_call_job_type_id and (
    p.role::text='on_call' or exists(
      select 1 from public.driver_schedule_days d join public.driver_schedule_periods sp on sp.id=d.period_id
      where (d.assigned_user_id=p.id or d.original_user_id=p.id) and sp.status::text in ('published','archived') and (sp.year*100+sp.month)>=v_current_ym
    )
  )
  on conflict(user_id,job_type_id) do nothing;
  get diagnostics v_live_periods_added = row_count;
  v_members_added := v_members_added + v_live_periods_added;

  insert into public.job_type_memberships(user_id,job_type_id,is_primary,source,metadata)
  select p.id,requested_morning_driver_job_type_id,false,'legacy_cutover',
         jsonb_build_object('employmentScope',case when jt.employment_scope='flexible' then 'full_time' else jt.employment_scope end,'legacyRole','morning_driver')
  from public.profiles p cross join public.job_types jt
  where jt.id=requested_morning_driver_job_type_id and (
    p.role::text='morning_driver' or exists(
      select 1 from public.morning_driver_schedule_assignments a join public.morning_driver_schedule_periods sp on sp.id=a.schedule_period_id
      where a.assigned_user_id=p.id and sp.status::text in ('published','archived') and (sp.year*100+sp.month)>=v_current_ym
    )
  )
  on conflict(user_id,job_type_id) do nothing;
  get diagnostics v_live_periods_added = row_count;
  v_members_added := v_members_added + v_live_periods_added;
  v_live_periods_added := 0;

  -- Reuse the already-tested, idempotent history importer for every legacy area.
  v_hist := public.import_dynamic_legacy_history(requested_dispatcher_job_type_id,'dispatcher');
  v_history := v_history || jsonb_build_object('dispatcher',v_hist);
  v_hist := public.import_dynamic_legacy_history(requested_on_call_job_type_id,'on_call');
  v_history := v_history || jsonb_build_object('onCall',v_hist);
  v_hist := public.import_dynamic_legacy_history(requested_morning_driver_job_type_id,'morning_driver');
  v_history := v_history || jsonb_build_object('morningDriver',v_hist);

  -- Stable current/future schedules are copied into the real dynamic publication
  -- tables. Existing dynamic publications are never overwritten.
  for v_source,v_job_type_id in
    select * from (values
      ('dispatcher'::text,requested_dispatcher_job_type_id),
      ('on_call'::text,requested_on_call_job_type_id),
      ('morning_driver'::text,requested_morning_driver_job_type_id)
    ) m(source_kind,job_type_id)
  loop
    select * into v_job from public.job_types where id=v_job_type_id;

    if v_source='dispatcher' then
      for v_period in
        select p.id source_period_id,p.year,p.month,p.status::text source_status
        from public.schedule_periods p
        where p.status::text in ('published','archived') and (p.year*100+p.month)>=v_current_ym
        order by p.year,p.month
      loop
        if exists(select 1 from public.dynamic_schedule_publications dp where dp.job_type_id=v_job.id and dp.year=v_period.year and dp.month=v_period.month) then
          continue;
        end if;

        insert into public.dynamic_availability_periods(
          schedule_group_id,job_type_id,year,month,title,status,config_snapshot,source,created_by
        ) values(
          v_job.schedule_group_id,v_job.id,v_period.year,v_period.month,
          'מיגרציה ממערכת מוקדנים · '||lpad(v_period.month::text,2,'0')||'/'||v_period.year::text,
          'closed',jsonb_build_object('legacyCutover',true,'sourceKind','dispatcher','sourcePeriodId',v_period.source_period_id),
          'legacy_cutover',v_actor
        )
        on conflict(job_type_id,year,month) do update set updated_at=now()
        returning id into v_dynamic_period_id;

        insert into public.dynamic_availability_slots(
          period_id,shift_date,shift_code,shift_name,start_time,end_time,source_day_kind,effective_day_kind,min_workers,target_workers,max_workers,metadata
        )
        select v_dynamic_period_id,s.shift_date,s.shift_code,s.shift_code,
               (s.starts_at at time zone 'Asia/Jerusalem')::time,
               (s.ends_at at time zone 'Asia/Jerusalem')::time,
               s.schedule_type::text,s.schedule_type::text,1,1,1,
               jsonb_build_object('legacyCutover',true,'sourceRecordId',s.id)
        from public.schedule_shifts s where s.period_id=v_period.source_period_id
        on conflict(period_id,shift_date,shift_code) do update set
          start_time=excluded.start_time,end_time=excluded.end_time,metadata=excluded.metadata;

        insert into public.dynamic_schedule_shadow_drafts(
          job_type_id,availability_period_id,year,month,status,feasibility_snapshot,rules_snapshot,metrics,created_by
        ) values(
          v_job.id,v_dynamic_period_id,v_period.year,v_period.month,'generated','{}'::jsonb,
          jsonb_build_object('source','legacy_cutover'),jsonb_build_object('legacyCutover',true,'sourcePeriodId',v_period.source_period_id),v_actor
        ) returning id into v_draft_id;

        insert into public.dynamic_schedule_shadow_assignments(
          draft_id,slot_id,user_id,original_user_id,engine_user_id,assignment_tier,score,reasons
        )
        select v_draft_id,sl.id,s.assigned_user_id,s.assigned_user_id,s.assigned_user_id,'required',0,jsonb_build_array('legacy_cutover')
        from public.schedule_shifts s
        join public.dynamic_availability_slots sl on sl.period_id=v_dynamic_period_id and sl.shift_date=s.shift_date and sl.shift_code=s.shift_code
        where s.period_id=v_period.source_period_id and s.assigned_user_id is not null
        on conflict(draft_id,slot_id,user_id) do nothing;

        insert into public.dynamic_schedule_draft_slot_overrides(draft_id,slot_id,intentionally_unassigned_count,note,updated_by)
        select v_draft_id,sl.id,1,'יובא כמשמרת לא מאוישת מהמערכת הישנה',v_actor
        from public.schedule_shifts s
        join public.dynamic_availability_slots sl on sl.period_id=v_dynamic_period_id and sl.shift_date=s.shift_date and sl.shift_code=s.shift_code
        where s.period_id=v_period.source_period_id and s.assigned_user_id is null
        on conflict(draft_id,slot_id) do nothing;

      end loop;

    elsif v_source='on_call' then
      for v_period in
        select p.id source_period_id,p.year,p.month,p.status::text source_status
        from public.driver_schedule_periods p
        where p.status::text in ('published','archived') and (p.year*100+p.month)>=v_current_ym
        order by p.year,p.month
      loop
        if exists(select 1 from public.dynamic_schedule_publications dp where dp.job_type_id=v_job.id and dp.year=v_period.year and dp.month=v_period.month) then
          continue;
        end if;

        insert into public.dynamic_availability_periods(
          schedule_group_id,job_type_id,year,month,title,status,config_snapshot,source,created_by
        ) values(
          v_job.schedule_group_id,v_job.id,v_period.year,v_period.month,
          'מיגרציה ממערכת כוננים · '||lpad(v_period.month::text,2,'0')||'/'||v_period.year::text,
          'closed',jsonb_build_object('legacyCutover',true,'sourceKind','on_call','sourcePeriodId',v_period.source_period_id),
          'legacy_cutover',v_actor
        )
        on conflict(job_type_id,year,month) do update set updated_at=now()
        returning id into v_dynamic_period_id;

        insert into public.dynamic_availability_slots(
          period_id,shift_date,shift_code,shift_name,start_time,end_time,source_day_kind,effective_day_kind,min_workers,target_workers,max_workers,metadata
        )
        select v_dynamic_period_id,d.duty_date,'daily_on_call','כוננות יומית','00:00'::time,'23:59'::time,
               'weekday','weekday',1,1,1,jsonb_build_object('legacyCutover',true,'sourceRecordId',d.id)
        from public.driver_schedule_days d where d.period_id=v_period.source_period_id
        on conflict(period_id,shift_date,shift_code) do update set metadata=excluded.metadata;

        insert into public.dynamic_schedule_shadow_drafts(
          job_type_id,availability_period_id,year,month,status,feasibility_snapshot,rules_snapshot,metrics,created_by
        ) values(
          v_job.id,v_dynamic_period_id,v_period.year,v_period.month,'generated','{}'::jsonb,
          jsonb_build_object('source','legacy_cutover'),jsonb_build_object('legacyCutover',true,'sourcePeriodId',v_period.source_period_id),v_actor
        ) returning id into v_draft_id;

        insert into public.dynamic_schedule_shadow_assignments(
          draft_id,slot_id,user_id,original_user_id,engine_user_id,assignment_tier,score,reasons
        )
        select v_draft_id,sl.id,d.assigned_user_id,coalesce(d.original_user_id,d.assigned_user_id),d.assigned_user_id,'required',0,jsonb_build_array('legacy_cutover')
        from public.driver_schedule_days d
        join public.dynamic_availability_slots sl on sl.period_id=v_dynamic_period_id and sl.shift_date=d.duty_date and sl.shift_code='daily_on_call'
        where d.period_id=v_period.source_period_id and d.assigned_user_id is not null
        on conflict(draft_id,slot_id,user_id) do nothing;

        insert into public.dynamic_schedule_draft_slot_overrides(draft_id,slot_id,intentionally_unassigned_count,note,updated_by)
        select v_draft_id,sl.id,1,'יובא ככוננות לא מאוישת מהמערכת הישנה',v_actor
        from public.driver_schedule_days d
        join public.dynamic_availability_slots sl on sl.period_id=v_dynamic_period_id and sl.shift_date=d.duty_date and sl.shift_code='daily_on_call'
        where d.period_id=v_period.source_period_id and d.assigned_user_id is null
        on conflict(draft_id,slot_id) do nothing;
      end loop;

    else
      for v_period in
        select p.id source_period_id,p.year,p.month,p.status::text source_status
        from public.morning_driver_schedule_periods p
        where p.status::text in ('published','archived') and (p.year*100+p.month)>=v_current_ym
        order by p.year,p.month
      loop
        if exists(select 1 from public.dynamic_schedule_publications dp where dp.job_type_id=v_job.id and dp.year=v_period.year and dp.month=v_period.month) then
          continue;
        end if;

        insert into public.dynamic_availability_periods(
          schedule_group_id,job_type_id,year,month,title,status,config_snapshot,source,created_by
        ) values(
          v_job.schedule_group_id,v_job.id,v_period.year,v_period.month,
          'מיגרציה ממערכת כונני בוקר · '||lpad(v_period.month::text,2,'0')||'/'||v_period.year::text,
          'closed',jsonb_build_object('legacyCutover',true,'sourceKind','morning_driver','sourcePeriodId',v_period.source_period_id),
          'legacy_cutover',v_actor
        )
        on conflict(job_type_id,year,month) do update set updated_at=now()
        returning id into v_dynamic_period_id;

        insert into public.dynamic_availability_slots(
          period_id,shift_date,shift_code,shift_name,start_time,end_time,source_day_kind,effective_day_kind,min_workers,target_workers,max_workers,metadata
        )
        select v_dynamic_period_id,s.shift_date,'legacy_morning_'||s.id::text,'כונן בוקר',s.start_time,s.end_time,
               'weekday','weekday',1,1,1,jsonb_build_object('legacyCutover',true,'sourceRecordId',s.id)
        from public.morning_driver_availability_shifts s
        where exists(
          select 1 from public.morning_driver_schedule_assignments a
          where a.schedule_period_id=v_period.source_period_id and a.availability_shift_id=s.id
        )
        on conflict(period_id,shift_date,shift_code) do update set
          start_time=excluded.start_time,end_time=excluded.end_time,metadata=excluded.metadata;

        insert into public.dynamic_schedule_shadow_drafts(
          job_type_id,availability_period_id,year,month,status,feasibility_snapshot,rules_snapshot,metrics,created_by
        ) values(
          v_job.id,v_dynamic_period_id,v_period.year,v_period.month,'generated','{}'::jsonb,
          jsonb_build_object('source','legacy_cutover'),jsonb_build_object('legacyCutover',true,'sourcePeriodId',v_period.source_period_id),v_actor
        ) returning id into v_draft_id;

        insert into public.dynamic_schedule_shadow_assignments(
          draft_id,slot_id,user_id,original_user_id,engine_user_id,assignment_tier,score,reasons
        )
        select v_draft_id,sl.id,a.assigned_user_id,a.assigned_user_id,a.assigned_user_id,'required',0,jsonb_build_array('legacy_cutover')
        from public.morning_driver_schedule_assignments a
        join public.morning_driver_availability_shifts s on s.id=a.availability_shift_id
        join public.dynamic_availability_slots sl on sl.period_id=v_dynamic_period_id and sl.shift_date=s.shift_date and sl.shift_code='legacy_morning_'||s.id::text
        where a.schedule_period_id=v_period.source_period_id and a.assigned_user_id is not null
        on conflict(draft_id,slot_id,user_id) do nothing;

        insert into public.dynamic_schedule_draft_slot_overrides(draft_id,slot_id,intentionally_unassigned_count,note,updated_by)
        select v_draft_id,sl.id,1,'יובא ככוננות בוקר לא מאוישת מהמערכת הישנה',v_actor
        from public.morning_driver_schedule_assignments a
        join public.morning_driver_availability_shifts s on s.id=a.availability_shift_id
        join public.dynamic_availability_slots sl on sl.period_id=v_dynamic_period_id and sl.shift_date=s.shift_date and sl.shift_code='legacy_morning_'||s.id::text
        where a.schedule_period_id=v_period.source_period_id and a.assigned_user_id is null
        on conflict(draft_id,slot_id) do nothing;
      end loop;
    end if;

    -- Publish every legacy-cutover draft that does not yet have a publication.
    for v_period in
      select d.id draft_id,d.availability_period_id,d.year,d.month,
             dap.config_snapshot,
             coalesce(dap.config_snapshot->>'sourceKind',v_source) source_kind,
             dap.config_snapshot->>'sourcePeriodId' source_period_id,
             case
               when v_source='dispatcher' then coalesce((select p.status::text from public.schedule_periods p where p.id=(dap.config_snapshot->>'sourcePeriodId')::uuid),'published')
               when v_source='on_call' then coalesce((select p.status::text from public.driver_schedule_periods p where p.id=(dap.config_snapshot->>'sourcePeriodId')::uuid),'published')
               else coalesce((select p.status::text from public.morning_driver_schedule_periods p where p.id=(dap.config_snapshot->>'sourcePeriodId')::uuid),'published')
             end source_status
      from public.dynamic_schedule_shadow_drafts d
      join public.dynamic_availability_periods dap on dap.id=d.availability_period_id
      where d.job_type_id=v_job.id
        and dap.source='legacy_cutover'
        and (d.year*100+d.month)>=v_current_ym
        and not exists(select 1 from public.dynamic_schedule_publications dp where dp.job_type_id=v_job.id and dp.year=d.year and dp.month=d.month)
      order by d.year,d.month
    loop
      insert into public.dynamic_schedule_publications(
        job_type_id,availability_period_id,draft_id,year,month,status,config_snapshot,published_by,published_at
      ) values(
        v_job.id,v_period.availability_period_id,v_period.draft_id,v_period.year,v_period.month,
        case when v_period.source_status='archived' then 'archived' else 'published' end,
        coalesce(v_period.config_snapshot,'{}'::jsonb) || jsonb_build_object('migrationRunId',v_run_id),v_actor,now()
      ) returning id into v_publication_id;
      v_live_periods_added := v_live_periods_added + 1;

      insert into public.dynamic_schedule_published_assignments(
        publication_id,source_assignment_id,slot_id,shift_date,shift_code,shift_name,start_time,end_time,
        user_id,original_user_id,engine_user_id,assignment_tier,score,reasons,manager_edited
      )
      select v_publication_id,a.id,a.slot_id,sl.shift_date,sl.shift_code,sl.shift_name,sl.start_time,sl.end_time,
             a.user_id,a.original_user_id,a.engine_user_id,a.assignment_tier,a.score,a.reasons,false
      from public.dynamic_schedule_shadow_assignments a
      join public.dynamic_availability_slots sl on sl.id=a.slot_id
      where a.draft_id=v_period.draft_id
      on conflict(publication_id,shift_date,shift_code,user_id) do nothing;
      get diagnostics v_unassigned_added = row_count;
      v_live_assignments_added := v_live_assignments_added + v_unassigned_added;

      insert into public.dynamic_schedule_published_unassigned(
        publication_id,slot_id,shift_date,shift_code,shift_name,intentionally_unassigned_count,note
      )
      select v_publication_id,o.slot_id,sl.shift_date,sl.shift_code,sl.shift_name,o.intentionally_unassigned_count,o.note
      from public.dynamic_schedule_draft_slot_overrides o
      join public.dynamic_availability_slots sl on sl.id=o.slot_id
      where o.draft_id=v_period.draft_id and o.intentionally_unassigned_count>0
      on conflict(publication_id,shift_date,shift_code) do nothing;
      get diagnostics v_unassigned_added = row_count;
      v_unassigned_added := coalesce(v_unassigned_added,0);
    end loop;
  end loop;

  v_result := jsonb_build_object(
    'runId',v_run_id,
    'membersAdded',v_members_added,
    'history',v_history,
    'livePeriodsAdded',v_live_periods_added,
    'liveAssignmentsAdded',v_live_assignments_added,
    'legacyDataDeleted',false,
    'cutoverEnabled',false,
    'message','נתוני GVK הועתקו לתפקידי היעד שנבחרו. המערכת הישנה נשארה ללא שינוי, ו-Cutover לא הופעל.'
  );

  update public.gvk_legacy_migration_runs
  set status='completed',result=v_result,completed_at=now()
  where id=v_run_id;

  insert into public.audit_logs(user_id,action,entity_type,entity_id,summary,actor_user_id,metadata)
  values(v_actor,'gvk.legacy_migration.completed','system',v_run_id,'הושלמה העברת נתוני GVK Legacy לתפקידי Job Type דינמיים שנבחרו',v_actor,v_result);

  return v_result;
exception when others then
  if v_run_id is not null then
    update public.gvk_legacy_migration_runs
    set status='failed',result=jsonb_build_object('error',sqlerrm),completed_at=now()
    where id=v_run_id;
  end if;
  raise;
end;
$$;


ALTER FUNCTION "public"."run_gvk_legacy_migration"("requested_mappings" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_dynamic_availability_shadow_submission"("requested_job_type_id" "uuid", "requested_year" integer, "requested_month" integer, "requested_user_id" "uuid", "requested_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  current_user_id uuid:=auth.uid();
  job public.job_types%rowtype;
  period public.dynamic_availability_periods%rowtype;
  v_submission_id uuid;
  entry_item jsonb;
  allowed_statuses jsonb;
  requested_status text;
begin
  if current_user_id is null then raise exception 'not authenticated'; end if;
  if not public.has_dynamic_job_type_permission('availability.manage_submissions', requested_job_type_id, current_user_id) then raise exception 'not allowed'; end if;
  select * into job from public.job_types where id=requested_job_type_id;
  if job.id is null then raise exception 'job type not found'; end if;
  if not exists(select 1 from public.job_type_memberships m where m.job_type_id=job.id and m.user_id=requested_user_id) then raise exception 'user is not a member of this job type'; end if;
  select * into period from public.dynamic_availability_periods where job_type_id=job.id and year=requested_year and month=requested_month;
  if period.id is null then raise exception 'shadow period not materialized'; end if;

  insert into public.dynamic_availability_submissions(period_id,user_id,status,min_shifts,target_shifts,max_shifts,max_nights,max_weekends,max_holidays,note,submitted_at)
  values(period.id,requested_user_id,coalesce(requested_payload->>'submissionStatus','draft'),
    nullif(requested_payload->>'minimum','')::integer,nullif(requested_payload->>'target','')::integer,nullif(requested_payload->>'maximum','')::integer,
    nullif(requested_payload->>'maxNights','')::integer,nullif(requested_payload->>'maxWeekends','')::integer,nullif(requested_payload->>'maxHolidays','')::integer,
    nullif(trim(coalesce(requested_payload->>'note','')),''),case when coalesce(requested_payload->>'submissionStatus','draft')='submitted' then now() else null end)
  on conflict(period_id,user_id) do update set
    status=excluded.status,min_shifts=excluded.min_shifts,target_shifts=excluded.target_shifts,max_shifts=excluded.max_shifts,
    max_nights=excluded.max_nights,max_weekends=excluded.max_weekends,max_holidays=excluded.max_holidays,note=excluded.note,
    submitted_at=excluded.submitted_at,updated_at=now()
  returning id into v_submission_id;

  allowed_statuses:=coalesce(job.availability_config->'statuses','["available","unavailable"]'::jsonb);
  for entry_item in select value from jsonb_array_elements(coalesce(requested_payload->'entries','[]'::jsonb)) loop
    requested_status:=entry_item->>'status';
    if not (allowed_statuses ? requested_status) then raise exception 'availability status % is not enabled for this job type',requested_status; end if;
    if not exists(select 1 from public.dynamic_availability_slots s where s.id=(entry_item->>'slotId')::uuid and s.period_id=period.id) then raise exception 'slot does not belong to period'; end if;
    insert into public.dynamic_availability_entries(submission_id,slot_id,availability_status,note)
    values(v_submission_id,(entry_item->>'slotId')::uuid,requested_status,nullif(trim(coalesce(entry_item->>'note','')),''))
    on conflict on constraint dynamic_availability_entries_pkey do update
      set availability_status=excluded.availability_status,note=excluded.note,updated_at=now();
  end loop;

  return jsonb_build_object('saved',true,'mode','shadow','submissionId',v_submission_id);
end;
$$;


ALTER FUNCTION "public"."save_dynamic_availability_shadow_submission"("requested_job_type_id" "uuid", "requested_year" integer, "requested_month" integer, "requested_user_id" "uuid", "requested_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_dynamic_dashboard_context_policy"("requested_job_type_id" "uuid", "requested_target_job_type_ids" "uuid"[] DEFAULT ARRAY[]::"uuid"[]) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor uuid := auth.uid();
  invalid_target_count integer;
begin
  if actor is null then
    raise exception 'not authenticated';
  end if;

  if not public.current_user_has_permission('users.manage') then
    raise exception 'not allowed';
  end if;

  if not exists (
    select 1
    from public.job_types jt
    where jt.id = requested_job_type_id
      and jt.legacy_role is null
  ) then
    raise exception 'dynamic job type not found';
  end if;

  if requested_job_type_id = any(coalesce(requested_target_job_type_ids, array[]::uuid[])) then
    raise exception 'a job type cannot expose itself as additional dashboard context';
  end if;

  select count(*)::integer
    into invalid_target_count
  from unnest(coalesce(requested_target_job_type_ids, array[]::uuid[])) requested(id)
  left join public.job_types jt
    on jt.id = requested.id
   and jt.is_active = true
   and jt.legacy_role is null
  where jt.id is null;

  if invalid_target_count > 0 then
    raise exception 'one or more dashboard context job types are invalid or inactive';
  end if;

  delete from public.job_type_dashboard_context_rules r
  where r.source_job_type_id = requested_job_type_id;

  insert into public.job_type_dashboard_context_rules (
    source_job_type_id,
    target_job_type_id,
    enabled,
    created_at,
    updated_at
  )
  select distinct
    requested_job_type_id,
    requested.id,
    true,
    now(),
    now()
  from unnest(coalesce(requested_target_job_type_ids, array[]::uuid[])) requested(id);
end;
$$;


ALTER FUNCTION "public"."save_dynamic_dashboard_context_policy"("requested_job_type_id" "uuid", "requested_target_job_type_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_dynamic_job_type"("requested_payload" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  current_user_id uuid:=auth.uid();
  target_id uuid;
  target_group_id uuid;
  target_code text;
  target_name text;
  target_description text;
  target_scope text;
  target_pay_model text;
  target_strategy text;
  target_is_active boolean;
  target_pay_config jsonb;
  target_availability_config jsonb;
  target_scheduling_config jsonb;
  target_statistics_config jsonb;
  target_ai_config jsonb;
  target_legacy_role text;
  target_month date;
  current_month date := date_trunc('month', now() at time zone 'Asia/Jerusalem')::date;
  next_month date := (date_trunc('month', now() at time zone 'Asia/Jerusalem') + interval '1 month')::date;
  snapshot jsonb;
  capability_value jsonb;
  permission_value jsonb;
  is_new boolean := false;
begin
  if current_user_id is null then raise exception 'not authenticated'; end if;
  if not exists(select 1 from public.profiles p where p.id=current_user_id and p.is_active=true) then raise exception 'user not active'; end if;
  if not exists(select 1 from public.user_permissions up where up.user_id=current_user_id and up.permission_key='users.manage') then raise exception 'not allowed'; end if;

  target_id:=nullif(requested_payload->>'id','')::uuid;
  target_group_id:=nullif(requested_payload->>'scheduleGroupId','')::uuid;
  target_code:=lower(trim(coalesce(requested_payload->>'code','')));
  target_name:=trim(coalesce(requested_payload->>'name',''));
  target_description:=nullif(trim(coalesce(requested_payload->>'description','')),'');
  target_scope:=coalesce(requested_payload->>'employmentScope','flexible');
  target_pay_model:=coalesce(requested_payload->>'payModel','none');
  target_strategy:=coalesce(requested_payload->>'schedulingStrategy','availability_optimizer');
  target_is_active:=coalesce((requested_payload->>'isActive')::boolean,true);
  target_pay_config:=coalesce(requested_payload->'payConfig','{}'::jsonb);
  target_availability_config:=coalesce(requested_payload->'availabilityConfig','{}'::jsonb);
  target_scheduling_config:=coalesce(requested_payload->'schedulingConfig','{}'::jsonb);
  target_statistics_config:=coalesce(requested_payload->'statisticsConfig','{}'::jsonb);

  if nullif(requested_payload->>'effectiveYear','') is null
     or nullif(requested_payload->>'effectiveMonth','') is null then
    target_month := current_month;
  else
    target_month := make_date(
      (requested_payload->>'effectiveYear')::integer,
      (requested_payload->>'effectiveMonth')::integer,
      1
    );
  end if;

  if target_month not in (current_month,next_month) then
    raise exception 'job type changes may only target the current or next month';
  end if;

  -- New dynamic roles are independent. Their schedule group is an internal implementation detail, not a legacy affiliation.
  if target_id is null and target_group_id is null then
    insert into public.schedule_groups(code,name,description,legacy_kind,config)
    values('job_' || target_code, target_name || ' · מערך עצמאי', 'מערך פנימי שנוצר אוטומטית עבור סוג התפקיד ' || target_name, null, jsonb_build_object('ownerJobTypeCode',target_code,'independent',true))
    returning id into target_group_id;
  elsif target_group_id is null or not exists(select 1 from public.schedule_groups sg where sg.id=target_group_id) then
    raise exception 'schedule group not found';
  end if;
  if target_code='' or target_code !~ '^[a-z0-9_]+$' then raise exception 'invalid job type code'; end if;
  if target_name='' then raise exception 'job type name is required'; end if;
  if target_scope not in ('full_time','part_time','flexible') then raise exception 'invalid employment scope'; end if;
  if target_pay_model not in ('hourly','per_shift','per_day','mixed','none') then raise exception 'invalid pay model'; end if;
  if target_strategy not in ('none','availability_optimizer','monthly_rotation_constraints') then raise exception 'invalid scheduling strategy'; end if;

  if target_id is null then
    if target_month <> current_month then raise exception 'new job types must start in the current month'; end if;
    is_new := true;
    insert into public.job_types(
      schedule_group_id,code,name,description,is_active,employment_scope,pay_model,pay_config,
      availability_config,scheduling_strategy,scheduling_config,statistics_config,ai_config
    ) values(
      target_group_id,target_code,target_name,target_description,target_is_active,target_scope,target_pay_model,target_pay_config,
      target_availability_config,target_strategy,target_scheduling_config,target_statistics_config,'{"allow_suggestions":true,"auto_apply":false}'::jsonb
    ) returning id,legacy_role,ai_config into target_id,target_legacy_role,target_ai_config;
  else
    select jt.legacy_role,jt.ai_config into target_legacy_role,target_ai_config
    from public.job_types jt where jt.id=target_id;
    if not found then raise exception 'job type not found'; end if;

    if target_month=current_month then
      update public.job_types set
        schedule_group_id=target_group_id,
        code=case when legacy_role is null then target_code else code end,
        name=target_name,
        description=target_description,
        is_active=target_is_active,
        employment_scope=target_scope,
        pay_model=target_pay_model,
        pay_config=target_pay_config,
        availability_config=target_availability_config,
        scheduling_strategy=target_strategy,
        scheduling_config=target_scheduling_config,
        statistics_config=target_statistics_config
      where id=target_id;
    end if;
  end if;

  if target_month=current_month then
    delete from public.job_type_capabilities where job_type_id=target_id;
    for capability_value in select value from jsonb_array_elements(coalesce(requested_payload->'capabilities','[]'::jsonb)) loop
      insert into public.job_type_capabilities(job_type_id,capability_key,enabled,source)
      values(target_id,trim(both '"' from capability_value::text),true,'manual')
      on conflict(job_type_id,capability_key) do update set enabled=true,source='manual';
    end loop;

    delete from public.job_type_default_permissions where job_type_id=target_id;
    for permission_value in select value from jsonb_array_elements(coalesce(requested_payload->'defaultPermissions','[]'::jsonb)) loop
      insert into public.job_type_default_permissions(job_type_id,permission_key,source)
      values(target_id,trim(both '"' from permission_value::text),'manual')
      on conflict(job_type_id,permission_key) do nothing;
    end loop;

    snapshot := public.dynamic_job_type_live_snapshot(target_id);
  else
    -- Future configuration is a complete snapshot. It does not mutate the live/current row.
    snapshot := jsonb_build_object(
      'id',target_id,
      'scheduleGroupId',target_group_id,
      'code',case when target_legacy_role is null then target_code else (select code from public.job_types where id=target_id) end,
      'name',target_name,
      'description',target_description,
      'isActive',target_is_active,
      'legacyRole',target_legacy_role,
      'employmentScope',target_scope,
      'payModel',target_pay_model,
      'payConfig',target_pay_config,
      'availabilityConfig',target_availability_config,
      'schedulingStrategy',target_strategy,
      'schedulingConfig',target_scheduling_config,
      'statisticsConfig',target_statistics_config,
      'aiConfig',coalesce(target_ai_config,'{}'::jsonb),
      'capabilities',coalesce(requested_payload->'capabilities','[]'::jsonb),
      'defaultPermissions',coalesce(requested_payload->'defaultPermissions','[]'::jsonb)
    );
  end if;

  insert into public.job_type_configuration_versions(
    job_type_id,effective_month,snapshot,change_summary,created_by
  ) values(
    target_id,target_month,snapshot,nullif(trim(coalesce(requested_payload->>'changeSummary','')),''),current_user_id
  )
  on conflict(job_type_id,effective_month) do update set
    snapshot=excluded.snapshot,
    change_summary=excluded.change_summary,
    created_by=excluded.created_by,
    updated_at=now();

  return target_id;
end;
$_$;


ALTER FUNCTION "public"."save_dynamic_job_type"("requested_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_dynamic_job_type_member_employment_scope"("requested_job_type_id" "uuid", "requested_user_id" "uuid", "requested_employment_scope" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  current_user_id uuid := auth.uid();
  job public.job_types%rowtype;
  normalized_scope text := nullif(trim(coalesce(requested_employment_scope,'')),'');
begin
  if current_user_id is null then raise exception 'not authenticated'; end if;
  if not exists(
    select 1 from public.user_permissions up
    where up.user_id=current_user_id and up.permission_key='users.manage'
  ) then raise exception 'not allowed'; end if;

  select * into job from public.job_types where id=requested_job_type_id;
  if job.id is null then raise exception 'job type not found'; end if;
  if job.employment_scope <> 'flexible' then
    raise exception 'member employment scope is available only for flexible job types';
  end if;
  if normalized_scope is not null and normalized_scope not in ('full_time','part_time') then
    raise exception 'invalid member employment scope';
  end if;
  if not exists(
    select 1 from public.job_type_memberships m
    where m.job_type_id=job.id and m.user_id=requested_user_id
  ) then raise exception 'user is not a member of this job type'; end if;

  update public.job_type_memberships m
  set metadata = case
        when normalized_scope is null then m.metadata - 'employmentScope'
        else jsonb_set(m.metadata,'{employmentScope}',to_jsonb(normalized_scope),true)
      end,
      updated_at=now()
  where m.job_type_id=job.id and m.user_id=requested_user_id;

  return jsonb_build_object(
    'saved',true,
    'jobTypeId',job.id,
    'userId',requested_user_id,
    'employmentScope',normalized_scope,
    'recommendationFactor',case normalized_scope when 'part_time' then 0.5 else 1 end
  );
end;
$$;


ALTER FUNCTION "public"."save_dynamic_job_type_member_employment_scope"("requested_job_type_id" "uuid", "requested_user_id" "uuid", "requested_employment_scope" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_dynamic_job_type_membership"("requested_job_type_id" "uuid", "requested_user_id" "uuid", "requested_is_member" boolean, "requested_employment_scope" "text" DEFAULT NULL::"text", "requested_part_time_definition" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  current_user_id uuid := auth.uid();
  target_job public.job_types%rowtype;
  normalized_scope text := nullif(trim(coalesce(requested_employment_scope,'')),'');
  should_primary boolean := false;
begin
  if current_user_id is null then raise exception 'not authenticated'; end if;
  if not exists(select 1 from public.user_permissions up where up.user_id=current_user_id and up.permission_key='users.manage') then raise exception 'not allowed'; end if;
  select * into target_job from public.job_types where id=requested_job_type_id;
  if not found then raise exception 'job type not found'; end if;
  if not exists(select 1 from public.profiles p where p.id=requested_user_id) then raise exception 'user not found'; end if;

  if not requested_is_member then
    delete from public.job_type_memberships where job_type_id=requested_job_type_id and user_id=requested_user_id;
    insert into public.audit_logs(user_id,action,entity_type,entity_id,summary,actor_user_id,metadata)
    values(current_user_id,'dynamic_job_type.member.removed','job_type',requested_job_type_id,'עובד הוסר מתפקיד דינמי',current_user_id,jsonb_build_object('userId',requested_user_id));
    return jsonb_build_object('saved',true,'isMember',false);
  end if;

  if target_job.employment_scope='flexible' then
    if normalized_scope is null then normalized_scope := 'full_time'; end if;
    if normalized_scope not in ('full_time','part_time','as_much_as_possible') then raise exception 'invalid member employment scope'; end if;
  else
    normalized_scope := target_job.employment_scope;
  end if;

  should_primary := not exists(select 1 from public.job_type_memberships m where m.user_id=requested_user_id and m.is_primary=true);
  insert into public.job_type_memberships(user_id,job_type_id,is_primary,source,metadata)
  values(requested_user_id,requested_job_type_id,should_primary,'manual',
    jsonb_strip_nulls(jsonb_build_object(
      'employmentScope',normalized_scope,
      'partTimeDefinition',case when normalized_scope='part_time' then coalesce(requested_part_time_definition,'{}'::jsonb) else null end
    )))
  on conflict(user_id,job_type_id) do update set
    source='manual',
    metadata=jsonb_strip_nulls(jsonb_build_object(
      'employmentScope',normalized_scope,
      'partTimeDefinition',case when normalized_scope='part_time' then coalesce(requested_part_time_definition,'{}'::jsonb) else null end
    )),
    updated_at=now();

  insert into public.audit_logs(user_id,action,entity_type,entity_id,summary,actor_user_id,metadata)
  values(current_user_id,'dynamic_job_type.member.saved','job_type',requested_job_type_id,'עובד שויך או עודכן בתפקיד דינמי',current_user_id,jsonb_build_object('userId',requested_user_id,'employmentScope',normalized_scope));
  return jsonb_build_object('saved',true,'isMember',true,'employmentScope',normalized_scope);
end;$$;


ALTER FUNCTION "public"."save_dynamic_job_type_membership"("requested_job_type_id" "uuid", "requested_user_id" "uuid", "requested_is_member" boolean, "requested_employment_scope" "text", "requested_part_time_definition" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_dynamic_job_type_permission_policy"("requested_job_type_id" "uuid", "requested_member_permission_keys" "text"[] DEFAULT ARRAY[]::"text"[], "requested_manager_permission_keys" "text"[] DEFAULT ARRAY[]::"text"[]) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  actor uuid := auth.uid();
  features text[];
begin
  if actor is null then raise exception 'not authenticated'; end if;
  if not exists (
    select 1 from public.user_permissions up
    where up.user_id=actor and up.permission_key='users.manage'
  ) then raise exception 'not allowed'; end if;

  features := public.get_dynamic_job_type_active_features(requested_job_type_id);
  if coalesce(array_length(features,1),0)=0 then raise exception 'job type not found'; end if;
  perform public.sync_dynamic_job_type_permission_settings(requested_job_type_id);

  update public.job_type_permission_settings s
  set enabled = case
      when s.audience='member' then s.permission_key=any(coalesce(requested_member_permission_keys,array[]::text[]))
      else s.permission_key=any(coalesce(requested_manager_permission_keys,array[]::text[]))
    end,
    source='role_builder',
    updated_at=now()
  where s.job_type_id=requested_job_type_id
    and exists (
      select 1 from public.dynamic_permission_manifest m
      where m.permission_key=s.permission_key
        and m.audience=s.audience
        and m.feature_key=any(features)
    );
end;
$$;


ALTER FUNCTION "public"."save_dynamic_job_type_permission_policy"("requested_job_type_id" "uuid", "requested_member_permission_keys" "text"[], "requested_manager_permission_keys" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_dynamic_schedule_group"("requested_payload" "jsonb") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  current_user_id uuid := auth.uid();
  target_group_id uuid := nullif(requested_payload->>'id','')::uuid;
  template_value jsonb;
  rule_value jsonb;
  segment_value jsonb;
  target_template_id uuid;
  template_codes text[] := array[]::text[];
  target_code text;
  target_name text;
  target_day_kind text;
  target_start time;
  target_end time;
  min_workers integer;
  target_workers_value integer;
  max_workers_value integer;
  shift_duration integer;
  segment_start_offset integer;
  segment_end_offset integer;
  new_version integer;
begin
  if current_user_id is null then raise exception 'not authenticated'; end if;
  if not exists (select 1 from public.profiles p where p.id=current_user_id and p.is_active=true) then raise exception 'user not active'; end if;
  if not exists (select 1 from public.user_permissions up where up.user_id=current_user_id and up.permission_key='users.manage') then raise exception 'not allowed'; end if;
  if target_group_id is null or not exists (select 1 from public.schedule_groups sg where sg.id=target_group_id) then raise exception 'schedule group not found'; end if;

  target_name := trim(coalesce(requested_payload->>'name',''));
  if target_name = '' then raise exception 'schedule group name is required'; end if;

  update public.schedule_groups
  set name=target_name,
      description=nullif(trim(coalesce(requested_payload->>'description','')), ''),
      is_active=coalesce((requested_payload->>'isActive')::boolean, true)
  where id=target_group_id;

  for template_value in select value from jsonb_array_elements(coalesce(requested_payload->'shiftTemplates','[]'::jsonb)) loop
    target_code := lower(trim(coalesce(template_value->>'code','')));
    target_name := trim(coalesce(template_value->>'name',''));
    target_day_kind := coalesce(template_value->>'dayKind','weekday');
    target_start := (template_value->>'startTime')::time;
    target_end := (template_value->>'endTime')::time;
    min_workers := coalesce((template_value->>'minWorkers')::integer, 1);
    target_workers_value := coalesce((template_value->>'targetWorkers')::integer, min_workers);
    max_workers_value := coalesce((template_value->>'maxWorkers')::integer, target_workers_value);

    if target_code = '' or target_code !~ '^[a-z0-9_]+$' then raise exception 'invalid shift code: %', target_code; end if;
    if target_name = '' then raise exception 'shift name is required'; end if;
    if target_day_kind not in ('weekday','friday','saturday','holiday_eve','holiday_full','holiday_end','chol_hamoed','custom') then raise exception 'invalid day kind'; end if;
    if target_start = target_end then raise exception 'shift start and end cannot be equal'; end if;
    if min_workers < 0 or target_workers_value < min_workers or max_workers_value < target_workers_value or max_workers_value > 50 then
      raise exception 'invalid worker requirements for shift %', target_code;
    end if;

    template_codes := array_append(template_codes, target_code);

    insert into public.schedule_group_shift_templates (
      schedule_group_id, code, name, day_kind, start_time, end_time,
      sort_order, required_workers, target_workers, max_workers, is_active, metadata
    ) values (
      target_group_id, target_code, target_name, target_day_kind, target_start, target_end,
      coalesce((template_value->>'sortOrder')::integer, 0), min_workers, target_workers_value, max_workers_value,
      coalesce((template_value->>'isActive')::boolean, true), coalesce(template_value->'metadata','{}'::jsonb)
    )
    on conflict (schedule_group_id, code) do update set
      name=excluded.name, day_kind=excluded.day_kind, start_time=excluded.start_time, end_time=excluded.end_time,
      sort_order=excluded.sort_order, required_workers=excluded.required_workers,
      target_workers=excluded.target_workers, max_workers=excluded.max_workers,
      is_active=excluded.is_active, metadata=excluded.metadata, updated_at=now()
    returning id into target_template_id;

    delete from public.schedule_shift_pay_segments where shift_template_id=target_template_id;
    shift_duration := public.dynamic_minutes_after(target_start, target_end);

    for segment_value in select value from jsonb_array_elements(coalesce(template_value->'paySegments','[]'::jsonb)) loop
      segment_start_offset := public.dynamic_minutes_after(target_start, (segment_value->>'startTime')::time);
      segment_end_offset := public.dynamic_minutes_after(target_start, (segment_value->>'endTime')::time);

      if segment_end_offset <= segment_start_offset
         or segment_start_offset < 0
         or segment_end_offset > shift_duration then
        raise exception 'pay segment is outside shift %', target_code;
      end if;

      insert into public.schedule_shift_pay_segments (
        shift_template_id, start_time, end_time, multiplier, label, sort_order, metadata
      ) values (
        target_template_id,
        (segment_value->>'startTime')::time,
        (segment_value->>'endTime')::time,
        coalesce((segment_value->>'multiplier')::numeric,1),
        nullif(trim(coalesce(segment_value->>'label','')), ''),
        coalesce((segment_value->>'sortOrder')::integer,0),
        '{"source":"phase3_editor"}'::jsonb
      );
    end loop;

    if exists (
      select 1
      from public.schedule_shift_pay_segments a
      join public.schedule_shift_pay_segments b
        on a.shift_template_id=b.shift_template_id and a.id < b.id
      where a.shift_template_id=target_template_id
        and public.dynamic_minutes_after(target_start,a.start_time) < public.dynamic_minutes_after(target_start,b.end_time)
        and public.dynamic_minutes_after(target_start,b.start_time) < public.dynamic_minutes_after(target_start,a.end_time)
    ) then
      raise exception 'overlapping pay segments for shift %', target_code;
    end if;
  end loop;

  if cardinality(template_codes) = 0 then
    delete from public.schedule_group_shift_templates where schedule_group_id=target_group_id;
  else
    delete from public.schedule_group_shift_templates
    where schedule_group_id=target_group_id and not (code = any(template_codes));
  end if;

  delete from public.schedule_group_day_rules where schedule_group_id=target_group_id;
  for rule_value in select value from jsonb_array_elements(coalesce(requested_payload->'dayRules','[]'::jsonb)) loop
    if coalesce(rule_value->>'dayKind','') not in ('weekday','friday','saturday','holiday_eve','holiday_full','holiday_end','chol_hamoed','custom') then
      raise exception 'invalid rule day kind';
    end if;
    if coalesce(rule_value->>'behavior','') not in ('own_templates','inherit','no_work') then raise exception 'invalid day behavior'; end if;
    if rule_value->>'behavior'='inherit' and nullif(rule_value->>'inheritDayKind','') is null then raise exception 'inherit day kind is required'; end if;

    insert into public.schedule_group_day_rules (schedule_group_id,day_kind,behavior,inherit_day_kind,metadata)
    values (
      target_group_id,
      rule_value->>'dayKind',
      rule_value->>'behavior',
      case when rule_value->>'behavior'='inherit' then rule_value->>'inheritDayKind' else null end,
      coalesce(rule_value->'metadata','{}'::jsonb)
    );
  end loop;

  select coalesce(max(v.version_number),0)+1 into new_version
  from public.schedule_group_versions v where v.schedule_group_id=target_group_id;

  insert into public.schedule_group_versions (schedule_group_id,version_number,snapshot,change_summary,created_by)
  values (
    target_group_id,
    new_version,
    public.get_dynamic_schedule_group_snapshot(target_group_id),
    nullif(trim(coalesce(requested_payload->>'changeSummary','')), ''),
    current_user_id
  );

  update public.scheduling_feature_flags
  set config = jsonb_set(jsonb_set(config,'{phase}','3'::jsonb,true),'{mode}','"shadow"'::jsonb,true),
      updated_at=now()
  where key='dynamic_job_types';

  return new_version;
end;
$_$;


ALTER FUNCTION "public"."save_dynamic_schedule_group"("requested_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_dynamic_user_assignments"("target_user_id" "uuid", "requested_assignments" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  actor uuid := auth.uid();
  item jsonb;
  requested_job_type_id uuid;
  requested_is_member boolean;
  requested_is_manager boolean;
  requested_employment_scope text;
  requested_part_time_definition jsonb;
  configured_scope text;
  was_member boolean;
  open_period record;
  created_notification_id uuid;
begin
  if actor is null then raise exception 'not authenticated'; end if;
  if not exists (
    select 1 from public.user_permissions up
    where up.user_id = actor and up.permission_key = 'users.manage'
  ) then raise exception 'not allowed'; end if;
  if not exists (select 1 from public.profiles p where p.id = target_user_id) then
    raise exception 'user not found';
  end if;
  if jsonb_typeof(coalesce(requested_assignments, '[]'::jsonb)) <> 'array' then
    raise exception 'requested_assignments must be an array';
  end if;

  for item in select value from jsonb_array_elements(coalesce(requested_assignments, '[]'::jsonb)) loop
    requested_job_type_id := nullif(item->>'jobTypeId','')::uuid;
    requested_is_member := coalesce((item->>'isMember')::boolean, false);
    requested_is_manager := coalesce((item->>'isManager')::boolean, false);
    requested_employment_scope := nullif(trim(coalesce(item->>'employmentScope','')), '');
    requested_part_time_definition := coalesce(item->'partTimeDefinition', '{}'::jsonb);

    select exists(
      select 1 from public.job_type_memberships m
      where m.user_id=target_user_id and m.job_type_id=requested_job_type_id
    ) into was_member;

    select jt.employment_scope into configured_scope
    from public.job_types jt
    where jt.id = requested_job_type_id
      and jt.legacy_role is null;

    if configured_scope is null then raise exception 'dynamic job type not found'; end if;

    if requested_is_member then
      if configured_scope <> 'flexible' then
        requested_employment_scope := configured_scope;
      elsif requested_employment_scope not in ('full_time','part_time','as_much_as_possible') then
        requested_employment_scope := 'full_time';
      end if;

      insert into public.job_type_memberships(user_id, job_type_id, is_primary, source, metadata)
      values (
        target_user_id,
        requested_job_type_id,
        false,
        'dynamic_users',
        jsonb_build_object(
          'employmentScope', requested_employment_scope,
          'partTimeDefinition', requested_part_time_definition
        )
      )
      on conflict (user_id, job_type_id) do update
      set source = 'dynamic_users',
          metadata = jsonb_set(
            jsonb_set(coalesce(public.job_type_memberships.metadata, '{}'::jsonb), '{employmentScope}', to_jsonb(requested_employment_scope), true),
            '{partTimeDefinition}', requested_part_time_definition, true
          ),
          updated_at = now();

      -- No snapshot is created: eligibility is intentionally based on the live
      -- membership table. The notification simply tells the newly-added user
      -- that an already-open period is now available to them.
      if not was_member then
        for open_period in
          select ap.id, ap.year, ap.month, ap.submission_deadline, jt.name as job_type_name
          from public.dynamic_availability_periods ap
          join public.job_types jt on jt.id=ap.job_type_id
          where ap.job_type_id=requested_job_type_id
            and ap.status='open'
            and (ap.submission_deadline is null or ap.submission_deadline >= now())
        loop
          insert into public.notifications(
            type, priority, source, title, body, url, data, created_by, expires_at
          ) values (
            'availability_open',
            'important',
            'dynamic_membership',
            concat('תקופת אילוצים פתוחה · ', open_period.job_type_name),
            concat(
              'צורפת לתפקיד בזמן שתקופת האילוצים לחודש ',
              lpad(open_period.month::text,2,'0'),'/',open_period.year,
              ' פתוחה. ניתן להגיש אילוצים במערכת.'
            ),
            '/my-availability',
            jsonb_build_object(
              'workflow','dynamic_availability',
              'event','member_added_to_open_period',
              'jobTypeId',requested_job_type_id,
              'periodId',open_period.id,
              'year',open_period.year,
              'month',open_period.month,
              'submissionDeadline',open_period.submission_deadline
            ),
            actor,
            now() + interval '90 days'
          ) returning id into created_notification_id;

          insert into public.notification_recipients(notification_id,user_id)
          values(created_notification_id,target_user_id)
          on conflict do nothing;
        end loop;

        insert into public.audit_logs(action,actor_user_id,entity_type,entity_id,summary,metadata)
        values(
          'system_event',actor,'job_type_membership',target_user_id,
          'עובד צורף לתפקיד דינמי',
          jsonb_build_object(
            'job_type_id',requested_job_type_id,
            'user_id',target_user_id,
            'open_period_eligibility','live'
          )
        );
      end if;
    else
      delete from public.job_type_memberships
      where user_id = target_user_id and job_type_id = requested_job_type_id;
    end if;

    if requested_is_manager then
      insert into public.job_type_managers(user_id, job_type_id, created_by)
      values (target_user_id, requested_job_type_id, actor)
      on conflict (user_id, job_type_id) do nothing;
    else
      delete from public.job_type_managers
      where user_id = target_user_id and job_type_id = requested_job_type_id;
    end if;
  end loop;
end;
$$;


ALTER FUNCTION "public"."save_dynamic_user_assignments"("target_user_id" "uuid", "requested_assignments" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_my_dashboard_widget_settings"("requested_widgets" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_actor uuid:=auth.uid();
  v_item jsonb;
  v_job_type_id uuid;
  v_scope text;
  v_order integer:=0;
begin
  if not public.can_configure_manager_dashboard(v_actor) then
    raise exception 'not allowed';
  end if;
  if requested_widgets is null or jsonb_typeof(requested_widgets)<>'array' then
    raise exception 'widgets must be an array';
  end if;
  if jsonb_array_length(requested_widgets)>12 then
    raise exception 'up to 12 dashboard widgets are allowed';
  end if;

  delete from public.user_dashboard_widgets where user_id=v_actor;

  for v_item in select value from jsonb_array_elements(requested_widgets)
  loop
    v_job_type_id:=(v_item->>'jobTypeId')::uuid;
    v_scope:=v_item->>'timeScope';
    if v_scope not in ('current','today') then raise exception 'invalid time scope'; end if;
    if not exists(
      select 1 from public.job_types jt
      where jt.id=v_job_type_id and jt.is_active=true
        and coalesce(jt.scheduling_strategy,'availability_optimizer')<>'none'
    ) then raise exception 'invalid job type'; end if;

    insert into public.user_dashboard_widgets(
      user_id,widget_type,time_scope,job_type_id,sort_order,enabled
    ) values(v_actor,'staffing',v_scope,v_job_type_id,v_order,true)
    on conflict(user_id,widget_type,time_scope,job_type_id)
    do update set sort_order=excluded.sort_order,enabled=true,updated_at=now();
    v_order:=v_order+1;
  end loop;

  return public.get_my_dashboard_widget_settings();
end;
$$;


ALTER FUNCTION "public"."save_my_dashboard_widget_settings"("requested_widgets" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_my_driver_availability"("requested_period_id" "uuid", "requested_entries" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  current_user_id uuid;

  current_permissions text[];

  target_period
    public.driver_availability_periods%rowtype;

  saved_entries_count integer := 0;

  v_available_count integer := 0;
  v_unavailable_count integer := 0;

  total_period_days integer := 0;

  invalid_entries_count integer := 0;

  saved_at timestamptz :=
    now();
begin
  current_user_id :=
    auth.uid();

  if current_user_id is null then
    raise exception
      'not authenticated';
  end if;

  if not exists (
    select 1
    from public.profiles
    where id =
      current_user_id
      and is_active = true
  ) then
    raise exception
      'user not active';
  end if;

  current_permissions :=
    coalesce(
      public.get_my_permissions(),
      array[]::text[]
    );

  if not (
    'driver_availability.view' =
      any(current_permissions)
  ) then
    raise exception
      'not allowed';
  end if;

  if requested_period_id is null then
    raise exception
      'driver availability period id is required';
  end if;

  if requested_entries is null then
    raise exception
      'driver availability entries are required';
  end if;

  if jsonb_typeof(
    requested_entries
  ) <> 'array' then
    raise exception
      'driver availability entries must be an array';
  end if;

  select *
  into target_period
  from public.driver_availability_periods
  where id =
    requested_period_id
  for update;

  if not found then
    raise exception
      'driver availability period not found';
  end if;

  if target_period.status <> 'open' then
    raise exception
      'driver availability period is not open';
  end if;

  if (
    target_period.submission_deadline
      is not null
    and now() >
      target_period.submission_deadline
  ) then
    raise exception
      'driver availability submission deadline has passed';
  end if;

  if exists (
    select 1
    from public.driver_availability_submissions
    where period_id =
      target_period.id
      and user_id =
        current_user_id
      and status =
        'submitted'
  ) then
    raise exception
      'driver availability was already submitted';
  end if;

  select
    count(*)::integer
  into total_period_days
  from public.driver_availability_days
  where period_id =
    target_period.id;

  if total_period_days = 0 then
    raise exception
      'driver availability period has no days';
  end if;

  with supplied_entries as (
    select
      nullif(
        trim(
          entry_row.value
            ->> 'dayId'
        ),
        ''
      )::uuid
        as day_id,

      nullif(
        trim(
          entry_row.value
            ->> 'availabilityStatus'
        ),
        ''
      )
        as availability_status,

      nullif(
        trim(
          coalesce(
            entry_row.value
              ->> 'note',
            ''
          )
        ),
        ''
      )
        as note

    from jsonb_array_elements(
      requested_entries
    ) as entry_row(value)
  )

  select
    count(*)::integer

  into invalid_entries_count

  from supplied_entries
  left join public.driver_availability_days
    day_row
    on day_row.id =
      supplied_entries.day_id
    and day_row.period_id =
      target_period.id

  where
    supplied_entries.day_id is null

    or day_row.id is null

    or supplied_entries
      .availability_status
      not in (
        'available',
        'unavailable'
      );

  if invalid_entries_count > 0 then
    raise exception
      'one or more driver availability entries are invalid';
  end if;

  if exists (
    select 1

    from (
      select
        nullif(
          trim(
            entry_row.value
              ->> 'dayId'
          ),
          ''
        )::uuid
          as day_id,

        count(*)::integer
          as entry_count

      from jsonb_array_elements(
        requested_entries
      ) as entry_row(value)

      group by
        nullif(
          trim(
            entry_row.value
              ->> 'dayId'
          ),
          ''
        )::uuid

      having count(*) > 1
    ) duplicate_entries
  ) then
    raise exception
      'duplicate driver availability entries';
  end if;

  insert into public.driver_availability_submissions (
    period_id,
    user_id,
    status,
    last_saved_at,
    available_count,
    unavailable_count
  )
  values (
    target_period.id,
    current_user_id,
    'draft',
    saved_at,
    0,
    0
  )
  on conflict (
    period_id,
    user_id
  )
  do update set
    status =
      case
        when public.driver_availability_submissions.status =
          'reopened'
        then
          'reopened'
        else
          'draft'
      end,

    last_saved_at =
      excluded.last_saved_at,

    updated_at =
      saved_at;

  with supplied_entries as (
    select
      nullif(
        trim(
          entry_row.value
            ->> 'dayId'
        ),
        ''
      )::uuid
        as day_id,

      nullif(
        trim(
          entry_row.value
            ->> 'availabilityStatus'
        ),
        ''
      )
        as availability_status,

      nullif(
        trim(
          coalesce(
            entry_row.value
              ->> 'note',
            ''
          )
        ),
        ''
      )
        as note

    from jsonb_array_elements(
      requested_entries
    ) as entry_row(value)
  )

  insert into public.driver_availability_entries (
    period_id,
    day_id,
    user_id,
    availability_status,
    note
  )
  select
    target_period.id,

    supplied_entry.day_id,

    current_user_id,

    supplied_entry
      .availability_status,

    supplied_entry.note

  from supplied_entries
    supplied_entry

  on conflict (
    day_id,
    user_id
  )
  do update set
    availability_status =
      excluded.availability_status,

    note =
      excluded.note,

    updated_at =
      saved_at;

  get diagnostics
    saved_entries_count =
      row_count;

  select
    count(*) filter (
      where availability_status =
        'available'
    )::integer,

    count(*) filter (
      where availability_status =
        'unavailable'
    )::integer

  into
    v_available_count,
    v_unavailable_count

  from public.driver_availability_entries
  where period_id =
    target_period.id
    and user_id =
      current_user_id;

  update public.driver_availability_submissions
  set
    available_count =
      v_available_count,

    unavailable_count =
      v_unavailable_count,

    last_saved_at =
      saved_at,

    updated_at =
      saved_at

  where period_id =
    target_period.id
    and user_id =
      current_user_id;

  return jsonb_build_object(
    'periodId',
      target_period.id,

    'userId',
      current_user_id,

    'availableCount',
      v_available_count,

    'unavailableCount',
      v_unavailable_count,

    'unmarkedCount',
      greatest(
        total_period_days -
        v_available_count -
        v_unavailable_count,
        0
      ),

    'savedEntries',
      saved_entries_count,

    'savedAt',
      saved_at
  );
end;
$$;


ALTER FUNCTION "public"."save_my_driver_availability"("requested_period_id" "uuid", "requested_entries" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."save_my_driver_availability"("requested_period_id" "uuid", "requested_entries" "jsonb") IS 'Saves the authenticated on-call user daily availability selections for an open driver availability period.';



CREATE OR REPLACE FUNCTION "public"."save_my_dynamic_availability_submission"("requested_job_type_id" "uuid", "requested_year" integer, "requested_month" integer, "requested_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  current_user_id uuid:=auth.uid();
  job public.job_types%rowtype;
  period public.dynamic_availability_periods%rowtype;
  v_submission_id uuid;
  entry_item jsonb;
  allowed_statuses jsonb;
  requested_status text;
  requested_submission_status text;
  valid_entry_count integer:=0;
  total_slot_count integer:=0;
begin
  if current_user_id is null then raise exception 'not authenticated'; end if;
  if not exists(select 1 from public.job_type_memberships m where m.user_id=current_user_id and m.job_type_id=requested_job_type_id) then raise exception 'not a member of this job type'; end if;
  select * into job from public.job_types where id=requested_job_type_id and is_active=true;
  if job.id is null then raise exception 'job type not found'; end if;
  select * into period from public.dynamic_availability_periods where job_type_id=job.id and year=requested_year and month=requested_month;
  if period.id is null then raise exception 'dynamic period not found'; end if;
  if period.status <> 'open' then raise exception 'availability period is not open'; end if;
  if period.submission_deadline is not null and now()>period.submission_deadline then raise exception 'submission deadline has passed'; end if;

  requested_submission_status:=coalesce(requested_payload->>'submissionStatus','draft');
  if requested_submission_status not in ('draft','submitted','reopened') then raise exception 'invalid submission status'; end if;
  allowed_statuses:=coalesce(job.availability_config->'statuses','["available","unavailable"]'::jsonb);

  for entry_item in select value from jsonb_array_elements(coalesce(requested_payload->'entries','[]'::jsonb)) loop
    requested_status:=entry_item->>'status';
    if not (allowed_statuses ? requested_status) then raise exception 'availability status % is not enabled for this job type',requested_status; end if;
    if not exists(select 1 from public.dynamic_availability_slots s where s.id=(entry_item->>'slotId')::uuid and s.period_id=period.id) then raise exception 'slot does not belong to period'; end if;
    valid_entry_count:=valid_entry_count+1;
  end loop;

  select count(*) into total_slot_count from public.dynamic_availability_slots where period_id=period.id;
  if requested_submission_status='submitted' and valid_entry_count<>total_slot_count then
    raise exception 'all shifts must be marked before submission (% of %)',valid_entry_count,total_slot_count;
  end if;

  insert into public.dynamic_availability_submissions(period_id,user_id,status,min_shifts,target_shifts,max_shifts,max_nights,max_weekends,max_holidays,note,submitted_at)
  values(period.id,current_user_id,requested_submission_status,
    nullif(requested_payload->>'minimum','')::integer,nullif(requested_payload->>'target','')::integer,nullif(requested_payload->>'maximum','')::integer,
    nullif(requested_payload->>'maxNights','')::integer,nullif(requested_payload->>'maxWeekends','')::integer,nullif(requested_payload->>'maxHolidays','')::integer,
    nullif(trim(coalesce(requested_payload->>'note','')),''),case when requested_submission_status='submitted' then now() else null end)
  on conflict(period_id,user_id) do update set status=excluded.status,min_shifts=excluded.min_shifts,target_shifts=excluded.target_shifts,max_shifts=excluded.max_shifts,
    max_nights=excluded.max_nights,max_weekends=excluded.max_weekends,max_holidays=excluded.max_holidays,note=excluded.note,
    submitted_at=case when excluded.status='submitted' then now() else public.dynamic_availability_submissions.submitted_at end,updated_at=now()
  returning id into v_submission_id;

  for entry_item in select value from jsonb_array_elements(coalesce(requested_payload->'entries','[]'::jsonb)) loop
    insert into public.dynamic_availability_entries(submission_id,slot_id,availability_status,note)
    values(v_submission_id,(entry_item->>'slotId')::uuid,entry_item->>'status',nullif(trim(coalesce(entry_item->>'note','')),''))
    on conflict(submission_id,slot_id) do update set availability_status=excluded.availability_status,note=excluded.note,updated_at=now();
  end loop;

  return jsonb_build_object('saved',true,'submissionId',v_submission_id,'status',requested_submission_status,'filledCount',valid_entry_count,'totalSlots',total_slot_count);
end;
$$;


ALTER FUNCTION "public"."save_my_dynamic_availability_submission"("requested_job_type_id" "uuid", "requested_year" integer, "requested_month" integer, "requested_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_my_morning_driver_availability"("requested_period_id" "uuid", "requested_entries" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  current_user_id uuid := auth.uid();
  current_permissions text[];
  target_period public.morning_driver_availability_periods%rowtype;
  target_submission public.morning_driver_availability_submissions%rowtype;
  requested_entry jsonb;
  requested_shift_id uuid;
  requested_status text;
  requested_note text;
  saved_entries integer := 0;
  available_count integer := 0;
  unavailable_count integer := 0;
  unmarked_count integer := 0;
  saved_at_value timestamptz := now();
begin
  if current_user_id is null then
    raise exception 'not authenticated';
  end if;

  current_permissions :=
    coalesce(
      public.get_my_permissions(),
      array[]::text[]
    );

  if not (
    'morning_driver_availability.view'
      = any(current_permissions)
  ) then
    raise exception 'not allowed';
  end if;

  if requested_period_id is null then
    raise exception 'period id is required';
  end if;

  if requested_entries is null
     or jsonb_typeof(requested_entries) <> 'array'
  then
    raise exception 'entries must be a JSON array';
  end if;

  select *
  into target_period
  from public.morning_driver_availability_periods period
  where period.id = requested_period_id
  for update;

  if not found then
    raise exception 'morning driver availability period not found';
  end if;

  if target_period.status <> 'open' then
    raise exception 'morning driver availability period is not open';
  end if;

  select *
  into target_submission
  from public.morning_driver_availability_submissions submission
  where submission.period_id = target_period.id
    and submission.user_id = current_user_id
  for update;

  if not found then
    insert into public.morning_driver_availability_submissions (
      period_id,
      user_id,
      status
    )
    values (
      target_period.id,
      current_user_id,
      'draft'
    )
    returning *
    into target_submission;
  end if;

  if target_submission.status = 'submitted' then
    raise exception 'morning driver availability already submitted';
  end if;

  for requested_entry
  in
    select value
    from jsonb_array_elements(requested_entries)
  loop
    requested_shift_id :=
      nullif(
        trim(
          coalesce(
            requested_entry ->> 'shiftId',
            ''
          )
        ),
        ''
      )::uuid;

    requested_status :=
      nullif(
        trim(
          coalesce(
            requested_entry ->> 'availabilityStatus',
            ''
          )
        ),
        ''
      );

    requested_note :=
      nullif(
        trim(
          coalesce(
            requested_entry ->> 'note',
            ''
          )
        ),
        ''
      );

    if requested_shift_id is null then
      raise exception 'shift id is required';
    end if;

    if requested_status not in (
      'available',
      'unavailable'
    ) then
      raise exception 'invalid availability status';
    end if;

    if not exists (
      select 1
      from public.morning_driver_availability_shifts shift_item
      where shift_item.id = requested_shift_id
        and shift_item.period_id = target_period.id
    ) then
      raise exception 'shift does not belong to the requested period';
    end if;

    insert into public.morning_driver_availability_entries (
      period_id,
      shift_id,
      user_id,
      availability_status,
      note,
      updated_at
    )
    values (
      target_period.id,
      requested_shift_id,
      current_user_id,
      requested_status,
      requested_note,
      saved_at_value
    )
    on conflict (
      shift_id,
      user_id
    )
    do update
    set
      availability_status =
        excluded.availability_status,
      note =
        excluded.note,
      updated_at =
        excluded.updated_at;

    saved_entries :=
      saved_entries + 1;
  end loop;

  update public.morning_driver_availability_submissions
  set
    status =
      case
        when status = 'reopened'
          then 'reopened'
        else 'draft'
      end,
    last_saved_at =
      saved_at_value,
    updated_at =
      saved_at_value
  where id = target_submission.id;

  select
    count(*) filter (
      where entry.availability_status = 'available'
    ),
    count(*) filter (
      where entry.availability_status = 'unavailable'
    ),
    count(*) filter (
      where entry.id is null
    )
  into
    available_count,
    unavailable_count,
    unmarked_count
  from public.morning_driver_availability_shifts shift_item
  left join public.morning_driver_availability_entries entry
    on entry.shift_id = shift_item.id
   and entry.user_id = current_user_id
  where shift_item.period_id = target_period.id;

  return jsonb_build_object(
    'periodId',
      target_period.id,
    'userId',
      current_user_id,
    'availableCount',
      available_count,
    'unavailableCount',
      unavailable_count,
    'unmarkedCount',
      unmarked_count,
    'savedEntries',
      saved_entries,
    'savedAt',
      saved_at_value
  );
end;
$$;


ALTER FUNCTION "public"."save_my_morning_driver_availability"("requested_period_id" "uuid", "requested_entries" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_my_shift_availability"("requested_shift_slot_id" "uuid", "requested_availability_status" "text", "requested_note" "text" DEFAULT NULL::"text") RETURNS TABLE("shift_slot_id" "uuid", "availability_status" "text", "availability_note" "text", "availability_updated_at" timestamp with time zone, "available_count" integer, "unavailable_count" integer, "answered_count" integer, "total_shift_count" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  current_user_id uuid;

  target_period_id uuid;
  target_period_status text;
  target_submission_deadline timestamptz;

  target_submission_status text;

  normalized_note text;
  saved_at timestamptz;

  calculated_available_count integer;
  calculated_unavailable_count integer;
  calculated_total_shift_count integer;
begin
  current_user_id := auth.uid();

  if current_user_id is null then
    raise exception
      'User is not authenticated';
  end if;

  if not exists (
    select 1
    from public.profiles profile
    where profile.id = current_user_id
      and profile.is_active = true
  ) then
    raise exception
      'Authenticated user is not active';
  end if;

  if not exists (
    select 1
    from public.user_permissions permission
    where permission.user_id =
      current_user_id
      and permission.permission_key =
        'availability.view'
  ) then
    raise exception
      'User is not allowed to submit availability';
  end if;

  if requested_shift_slot_id is null then
    raise exception
      'Shift slot id is required';
  end if;

  if requested_availability_status not in (
    'available',
    'unavailable'
  ) then
    raise exception
      'Invalid availability status';
  end if;

  normalized_note :=
    nullif(
      trim(
        coalesce(
          requested_note,
          ''
        )
      ),
      ''
    );

  if (
    normalized_note is not null
    and length(normalized_note) > 1000
  ) then
    raise exception
      'Availability note is too long';
  end if;

  select
    period.id,
    period.status,
    period.submission_deadline
  into
    target_period_id,
    target_period_status,
    target_submission_deadline
  from public.availability_shift_slots slot
  join public.availability_periods period
    on period.id = slot.period_id
  where slot.id =
    requested_shift_slot_id;

  if target_period_id is null then
    raise exception
      'Shift slot was not found';
  end if;

  if target_period_status <> 'open' then
    raise exception
      'Availability period is not open';
  end if;

  if (
    target_submission_deadline is not null
    and target_submission_deadline <= now()
  ) then
    raise exception
      'Availability submission deadline has passed';
  end if;

  select
    submission.status
  into
    target_submission_status
  from public.availability_submissions submission
  where submission.period_id =
    target_period_id
    and submission.user_id =
      current_user_id
  for update;

  if target_submission_status is null then
    insert into
      public.availability_submissions (
        period_id,
        user_id,
        status,
        available_count,
        unavailable_count
      )
    values (
      target_period_id,
      current_user_id,
      'draft',
      0,
      0
    );

    target_submission_status :=
      'draft';
  end if;

  if target_submission_status =
    'submitted' then
    raise exception
      'Availability submission is already submitted';
  end if;

  saved_at := now();

  insert into
    public.dispatcher_availability (
      period_id,
      shift_slot_id,
      user_id,
      availability_status,
      note,
      is_auto_completed,
      created_at,
      updated_at
    )
  values (
    target_period_id,
    requested_shift_slot_id,
    current_user_id,
    requested_availability_status,
    normalized_note,
    false,
    saved_at,
    saved_at
  )
  on conflict on constraint
    dispatcher_availability_unique
  do update set
    availability_status =
      excluded.availability_status,

    note =
      excluded.note,

    is_auto_completed =
      false,

    updated_at =
      excluded.updated_at;

  select
    count(*) filter (
      where availability.availability_status =
        'available'
    )::integer,

    count(*) filter (
      where availability.availability_status =
        'unavailable'
    )::integer
  into
    calculated_available_count,
    calculated_unavailable_count
  from public.dispatcher_availability
    availability
  where availability.period_id =
    target_period_id
    and availability.user_id =
      current_user_id;

  select
    count(*)::integer
  into
    calculated_total_shift_count
  from public.availability_shift_slots slot
  where slot.period_id =
    target_period_id;

  update public.availability_submissions
  set
    available_count =
      calculated_available_count,

    unavailable_count =
      calculated_unavailable_count,

    last_saved_at =
      saved_at,

    submission_source =
      'manual',

    updated_at =
      saved_at
  where period_id =
    target_period_id
    and user_id =
      current_user_id;

  return query
  select
    requested_shift_slot_id,

    requested_availability_status,

    normalized_note,

    saved_at,

    calculated_available_count,

    calculated_unavailable_count,

    calculated_available_count
      + calculated_unavailable_count,

    calculated_total_shift_count;
end;
$$;


ALTER FUNCTION "public"."save_my_shift_availability"("requested_shift_slot_id" "uuid", "requested_availability_status" "text", "requested_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_schedule_draft"("requested_availability_period_id" "uuid", "requested_assignments" "jsonb", "requested_confirm_warnings" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  current_user_id uuid;

  source_period
    public.availability_periods%rowtype;

  existing_schedule_period
    public.schedule_periods%rowtype;

  resolved_schedule_period_id uuid;

  source_shift_count integer;
  payload_count integer;
  distinct_payload_count integer;

  inactive_user_count integer;
  unavailable_assignment_count integer := 0;

  overlap_count integer;
  consecutive_count integer;

  saved_shift_count integer;
  automatic_assignment_count integer;
  manual_assignment_count integer;
  intentionally_unassigned_count integer;
begin
  current_user_id :=
    auth.uid();

  if current_user_id is null then
    raise exception
      'not authenticated';
  end if;


  -- =======================================================
  -- 1. הרשאות
  -- =======================================================

  if not exists (
    select 1
    from public.profiles profile
    where profile.id =
      current_user_id
      and profile.is_active = true
  ) then
    raise exception
      'user not active';
  end if;

  if not (
    'schedule.edit' = any(
      coalesce(
        public.get_my_permissions(),
        array[]::text[]
      )
    )
  ) then
    raise exception
      'not allowed';
  end if;


  -- =======================================================
  -- 2. בדיקת קלט
  -- =======================================================

  if requested_availability_period_id
    is null
  then
    raise exception
      'availability period id is required';
  end if;

  if requested_assignments is null
    or jsonb_typeof(
      requested_assignments
    ) <> 'array'
  then
    raise exception
      'assignments must be a json array';
  end if;


  -- =======================================================
  -- 3. תקופת האילוצים
  -- =======================================================

  select *
  into source_period
  from public.availability_periods
  where id =
    requested_availability_period_id;

  if not found then
    raise exception
      'availability period not found';
  end if;

  if source_period.status <> 'closed' then
    raise exception
      'availability period must be closed';
  end if;

  select count(*)
  into source_shift_count
  from public.availability_shift_slots
  where period_id =
    requested_availability_period_id;

  if source_shift_count = 0 then
    raise exception
      'availability period has no shift slots';
  end if;

  payload_count :=
    jsonb_array_length(
      requested_assignments
    );

  if payload_count = 0 then
    raise exception
      'assignments array is empty';
  end if;


  -- =======================================================
  -- 4. בדיקת מבנה האובייקטים
  --
  -- משמרת רגילה:
  --   shiftId + userId + source
  --
  -- משמרת שסומנה במכוון כלא מאוישת:
  --   shiftId + isIntentionallyUnassigned=true
  -- =======================================================

  if exists (
    select 1
    from jsonb_array_elements(
      requested_assignments
    ) item
    where
      jsonb_typeof(item) <> 'object'

      or nullif(
        btrim(
          item ->> 'shiftId'
        ),
        ''
      ) is null

      or (
        coalesce(
          (
            item ->
            'isIntentionallyUnassigned'
          )::boolean,
          false
        ) = false

        and nullif(
          btrim(
            item ->> 'userId'
          ),
          ''
        ) is null
      )

      or (
        coalesce(
          (
            item ->
            'isIntentionallyUnassigned'
          )::boolean,
          false
        ) = false

        and nullif(
          btrim(
            item ->> 'source'
          ),
          ''
        ) is null
      )
  ) then
    raise exception
      'one or more assignment objects are invalid';
  end if;


  if exists (
    select 1
    from jsonb_array_elements(
      requested_assignments
    ) item
    where
      item ->> 'source' is not null

      and item ->> 'source'
        not in (
          'automatic_single_candidate',
          'automatic_scoring',
          'manual',
          'automatic',
          'shift_swap',
          'import'
        )
  ) then
    raise exception
      'unsupported assignment source';
  end if;


  -- =======================================================
  -- 5. מניעת UUID לא תקין
  -- =======================================================

  if exists (
    select 1
    from jsonb_array_elements(
      requested_assignments
    ) item
    where
      not (
        item ->> 'shiftId'
        ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
      )

      or (
        coalesce(
          (
            item ->
            'isIntentionallyUnassigned'
          )::boolean,
          false
        ) = false

        and not (
          item ->> 'userId'
          ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
        )
      )
  ) then
    raise exception
      'one or more assignment identifiers are invalid';
  end if;


  -- =======================================================
  -- 6. כפילויות ושלמות
  -- =======================================================

  select
    count(
      distinct (
        item ->> 'shiftId'
      )
    )
  into
    distinct_payload_count
  from jsonb_array_elements(
    requested_assignments
  ) item;

  if distinct_payload_count
    <> payload_count
  then
    raise exception
      'duplicate shift assignments were received';
  end if;


  /*
   * גם משמרת שסומנה במכוון כלא מאוישת צריכה
   * להופיע ב-payload כאובייקט.
   */
  if payload_count
    <> source_shift_count
  then
    raise exception
      'every availability shift must have exactly one assignment';
  end if;


  /*
   * מוודאים שכל shiftId באמת שייך לתקופת האילוצים.
   */
  if exists (
    with payload as (
      select
        (
          item ->> 'shiftId'
        )::uuid as shift_id
      from jsonb_array_elements(
        requested_assignments
      ) item
    )

    select 1
    from payload

    left join
      public.availability_shift_slots slot
      on slot.id =
        payload.shift_id

      and slot.period_id =
        requested_availability_period_id

    where slot.id is null
  ) then
    raise exception
      'one or more shifts do not belong to the requested availability period';
  end if;


  /*
   * מוודאים שאף משמרת מהתקופה לא חסרה מה-payload.
   */
  if exists (
    select 1

    from public.availability_shift_slots slot

    where slot.period_id =
      requested_availability_period_id

      and not exists (
        select 1

        from jsonb_array_elements(
          requested_assignments
        ) item

        where (
          item ->> 'shiftId'
        )::uuid =
          slot.id
      )
  ) then
    raise exception
      'one or more availability shifts are missing from the draft';
  end if;


  -- =======================================================
  -- 7. בדיקת מוקדנים פעילים
  --
  -- משמרת לא מאוישת במכוון לא נבדקת מול profiles.
  -- =======================================================

  with payload as (
    select distinct
      (
        item ->> 'userId'
      )::uuid as user_id

    from jsonb_array_elements(
      requested_assignments
    ) item

    where coalesce(
      (
        item ->
        'isIntentionallyUnassigned'
      )::boolean,
      false
    ) = false
  )

  select
    count(*)
  into
    inactive_user_count

  from payload

  left join public.profiles profile
    on profile.id =
      payload.user_id

  where
    profile.id is null
    or profile.is_active = false;


  if inactive_user_count > 0 then
    raise exception
      'one or more assigned dispatchers are missing or inactive';
  end if;


  -- =======================================================
  -- 8. אזהרות זמינות
  --
  -- הסכמה בפועל:
  -- dispatcher_availability.availability_status
  --
  -- אין צורך ב-Dynamic SQL.
  -- משמרת שסומנה כלא מאוישת אינה נבדקת.
  -- =======================================================

  with payload as (
    select
      (
        item ->> 'shiftId'
      )::uuid as shift_id,

      (
        item ->> 'userId'
      )::uuid as user_id

    from jsonb_array_elements(
      requested_assignments
    ) item

    where coalesce(
      (
        item ->
        'isIntentionallyUnassigned'
      )::boolean,
      false
    ) = false
  )

  select
    count(*)
  into
    unavailable_assignment_count

  from payload

  left join
    public.dispatcher_availability
      availability

    on availability.period_id =
      requested_availability_period_id

    and availability.shift_slot_id =
      payload.shift_id

    and availability.user_id =
      payload.user_id

  where
    availability.user_id is null

    or availability.availability_status
      <> 'available';


  if unavailable_assignment_count > 0
    and not requested_confirm_warnings
  then
    raise exception
      'availability warnings require confirmation';
  end if;


  -- =======================================================
  -- 9. בדיקת חפיפות ומשמרות רצופות
  --
  -- רק משמרות שבאמת משויכות למוקדן.
  -- =======================================================

  with payload as (
    select
      (
        item ->> 'shiftId'
      )::uuid as shift_id,

      (
        item ->> 'userId'
      )::uuid as user_id

    from jsonb_array_elements(
      requested_assignments
    ) item

    where coalesce(
      (
        item ->
        'isIntentionallyUnassigned'
      )::boolean,
      false
    ) = false
  ),

  intervals as (
    select
      payload.shift_id,
      payload.user_id,

      (
        slot.shift_date +
        slot.start_time
      ) at time zone
        'Asia/Jerusalem'
        as starts_at,

      (
        slot.shift_date +
        slot.end_time +

        case
          when slot.ends_next_day
            or slot.end_time <=
              slot.start_time

          then interval '1 day'
          else interval '0 day'
        end

      ) at time zone
        'Asia/Jerusalem'
        as ends_at

    from payload

    join public.availability_shift_slots slot
      on slot.id =
        payload.shift_id

      and slot.period_id =
        requested_availability_period_id
  ),

  ordered as (
    select
      intervals.*,

      lag(
        shift_id
      ) over (
        partition by user_id
        order by starts_at
      ) as previous_shift_id,

      lag(
        ends_at
      ) over (
        partition by user_id
        order by starts_at
      ) as previous_ends_at

    from intervals
  )

  select
    count(*) filter (
      where
        previous_ends_at is not null

        and starts_at <
          previous_ends_at
    ),

    count(*) filter (
      where
        previous_ends_at is not null

        and starts_at =
          previous_ends_at
    )

  into
    overlap_count,
    consecutive_count

  from ordered;


  if overlap_count > 0 then
    raise exception
      'the schedule contains overlapping shifts';
  end if;


  if consecutive_count > 0 then
    raise exception
      'the schedule contains consecutive shifts';
  end if;


  -- =======================================================
  -- 10. איתור או יצירת תקופת השיבוץ
  -- =======================================================

  select *
  into existing_schedule_period

  from public.schedule_periods

  where year =
      source_period.year

    and month =
      source_period.month

  for update;


  if found then

    /*
     * A published month may intentionally return to the scheduling
     * workflow after its availability period was reopened and closed
     * again. Saving the new draft demotes the period to `scheduling`;
     * it must be explicitly published again before regular users see
     * the revised version. Archived months remain immutable.
     */
    if existing_schedule_period.status =
      'archived'::public.schedule_period_status
    then
      raise exception
        'archived schedules cannot be overwritten';
    end if;


    resolved_schedule_period_id :=
      existing_schedule_period.id;


    update public.schedule_periods

    set
      availability_period_id =
        source_period.id,

      title =
        coalesce(
          source_period.title,

          concat(
            'שיבוץ ',
            source_period.month,
            '/',
            source_period.year
          )
        ),

      status =
        'scheduling'
          ::public.schedule_period_status,

      availability_deadline =
        source_period.submission_deadline,

      approved_by =
        current_user_id,

      approved_at =
        now(),

      updated_at =
        now()

    where id =
      resolved_schedule_period_id;


  else

    insert into public.schedule_periods (
      year,
      month,
      status,
      availability_deadline,
      availability_period_id,
      title,
      created_by,
      approved_by,
      approved_at
    )
    values (
      source_period.year,

      source_period.month,

      'scheduling'
        ::public.schedule_period_status,

      source_period.submission_deadline,

      source_period.id,

      coalesce(
        source_period.title,

        concat(
          'שיבוץ ',
          source_period.month,
          '/',
          source_period.year
        )
      ),

      current_user_id,
      current_user_id,
      now()
    )

    returning id
    into resolved_schedule_period_id;

  end if;


  -- =======================================================
  -- 11. שמירת המשמרות
  -- =======================================================

  insert into public.schedule_shifts (
    period_id,
    availability_shift_slot_id,
    shift_date,
    starts_at,
    ends_at,
    shift_code,
    schedule_type,
    is_premium,
    holiday_name,
    assigned_user_id,
    is_intentionally_unassigned,
    assignment_source,
    assignment_score,
    assignment_reasons,
    is_locked,
    notes
  )

  select
    resolved_schedule_period_id,

    slot.id,

    slot.shift_date,

    (
      slot.shift_date +
      slot.start_time
    ) at time zone
      'Asia/Jerusalem',

    (
      slot.shift_date +
      slot.end_time +

      case
        when slot.ends_next_day
          or slot.end_time <=
            slot.start_time

        then interval '1 day'
        else interval '0 day'
      end

    ) at time zone
      'Asia/Jerusalem',

    concat(
      to_char(
        slot.shift_date,
        'YYYYMMDD'
      ),
      '-',
      to_char(
        slot.start_time,
        'HH24MI'
      )
    ),

    slot.schedule_type
      ::public.schedule_type,

    slot.is_premium,

    slot.holiday_name,


    /*
     * מוקדן משויך.
     * אם המשמרת לא מאוישת במכוון - NULL.
     */
    case
      when coalesce(
        (
          item ->
          'isIntentionallyUnassigned'
        )::boolean,
        false
      )
      then null

      else (
        item ->> 'userId'
      )::uuid
    end,


    /*
     * סימון מפורש של משמרת לא מאוישת.
     */
    coalesce(
      (
        item ->
        'isIntentionallyUnassigned'
      )::boolean,
      false
    ),


    /*
     * מקור השיבוץ.
     * למשמרת לא מאוישת אין assignment_source.
     */
    case
      when coalesce(
        (
          item ->
          'isIntentionallyUnassigned'
        )::boolean,
        false
      )
      then null


      when item ->> 'source'
        in (
          'automatic_single_candidate',
          'automatic_scoring',
          'automatic'
        )
      then
        'automatic'
          ::public.assignment_source


      when item ->> 'source' =
        'shift_swap'
      then
        'shift_swap'
          ::public.assignment_source


      when item ->> 'source' =
        'import'
      then
        'import'
          ::public.assignment_source


      else
        'manual'
          ::public.assignment_source
    end,


    /*
     * ציון שיבוץ.
     */
    case
      when coalesce(
        (
          item ->
          'isIntentionallyUnassigned'
        )::boolean,
        false
      )
      then null

      when nullif(
        item ->> 'score',
        ''
      ) is null
      then null

      else (
        item ->> 'score'
      )::numeric
    end,


    /*
     * סיבות השיבוץ.
     */
    case
      when jsonb_typeof(
        item -> 'reasons'
      ) = 'array'

      then item -> 'reasons'

      else '[]'::jsonb
    end,


    false,


    /*
     * notes - גרסה קריאה של reasons.
     */
    case
      when jsonb_typeof(
        item -> 'reasons'
      ) = 'array'
      then (
        select
          string_agg(
            reason_value,
            E'\n'
          )

        from jsonb_array_elements_text(
          item -> 'reasons'
        ) reason_value
      )

      else null
    end


  from jsonb_array_elements(
    requested_assignments
  ) item


  join public.availability_shift_slots slot

    on slot.id =
      (
        item ->> 'shiftId'
      )::uuid

    and slot.period_id =
      requested_availability_period_id


  on conflict (
    period_id,
    starts_at
  )

  do update set

    availability_shift_slot_id =
      excluded.availability_shift_slot_id,

    shift_date =
      excluded.shift_date,

    ends_at =
      excluded.ends_at,

    shift_code =
      excluded.shift_code,

    schedule_type =
      excluded.schedule_type,

    is_premium =
      excluded.is_premium,

    holiday_name =
      excluded.holiday_name,

    assigned_user_id =
      excluded.assigned_user_id,

    is_intentionally_unassigned =
      excluded.is_intentionally_unassigned,

    assignment_source =
      excluded.assignment_source,

    assignment_score =
      excluded.assignment_score,

    assignment_reasons =
      excluded.assignment_reasons,

    is_locked =
      false,

    notes =
      excluded.notes,

    updated_at =
      now();


  -- =======================================================
  -- 12. בדיקת תוצאת השמירה
  -- =======================================================

  select
    count(*)

  into
    saved_shift_count

  from public.schedule_shifts shift

  where shift.period_id =
      resolved_schedule_period_id

    and shift.availability_shift_slot_id
      in (
        select slot.id

        from public.availability_shift_slots slot

        where slot.period_id =
          requested_availability_period_id
      );


  if saved_shift_count
    <> source_shift_count
  then
    raise exception
      'saved shift count does not match source shift count';
  end if;


  select
    count(*) filter (
      where shift.assignment_source =
        'automatic'
    ),

    count(*) filter (
      where shift.assignment_source =
        'manual'
    ),

    count(*) filter (
      where
        shift.is_intentionally_unassigned
    )

  into
    automatic_assignment_count,
    manual_assignment_count,
    intentionally_unassigned_count

  from public.schedule_shifts shift

  where shift.period_id =
    resolved_schedule_period_id;


  -- =======================================================
  -- 13. תשובה ללקוח
  -- =======================================================

  return jsonb_build_object(

    'schedulePeriodId',
      resolved_schedule_period_id,

    'availabilityPeriodId',
      requested_availability_period_id,

    'year',
      source_period.year,

    'month',
      source_period.month,

    'status',
      'scheduling',

    'savedShifts',
      saved_shift_count,

    'automaticAssignments',
      automatic_assignment_count,

    'manualAssignments',
      manual_assignment_count,

    'intentionallyUnassignedShifts',
      intentionally_unassigned_count,

    'warningCount',
      unavailable_assignment_count,

    'approvedBy',
      current_user_id,

    'approvedAt',
      now()
  );
end;
$_$;


ALTER FUNCTION "public"."save_schedule_draft"("requested_availability_period_id" "uuid", "requested_assignments" "jsonb", "requested_confirm_warnings" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."save_schedule_draft"("requested_availability_period_id" "uuid", "requested_assignments" "jsonb", "requested_confirm_warnings" boolean) IS 'Validates and saves an editable dispatcher schedule draft from a closed availability period. Requires schedule.edit permission.';



CREATE OR REPLACE FUNCTION "public"."save_schedule_import_name_alias"("requested_source_name" "text", "requested_user_id" "uuid", "requested_user_type" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  current_user_id uuid;

  current_permissions text[];

  normalized_name text;

  target_profile
    public.profiles%rowtype;

  saved_alias
    public.schedule_import_name_aliases%rowtype;
begin
  current_user_id :=
    auth.uid();

  if current_user_id is null then
    raise exception
      'not authenticated';
  end if;

  if not exists (
    select 1
    from public.profiles
    where id =
      current_user_id
      and is_active = true
  ) then
    raise exception
      'user not active';
  end if;

  current_permissions :=
    coalesce(
      public.get_my_permissions(),
      array[]::text[]
    );

  if not (
    'driver_availability.manage' =
      any(current_permissions)
    or
    'users.manage' =
      any(current_permissions)
  ) then
    raise exception
      'not allowed';
  end if;

  normalized_name :=
    public.normalize_schedule_import_name(
      requested_source_name
    );

  if normalized_name = '' then
    raise exception
      'source name is required';
  end if;

  if requested_user_id is null then
    raise exception
      'user id is required';
  end if;

  if requested_user_type not in (
    'dispatcher',
    'on_call'
  ) then
    raise exception
      'user type is invalid';
  end if;

  select *
  into target_profile
  from public.profiles
  where id =
    requested_user_id
    and is_active = true;

  if not found then
    raise exception
      'user not found or inactive';
  end if;

  if target_profile.role <>
    requested_user_type
  then
    raise exception
      'user role does not match import type';
  end if;

  insert into
    public.schedule_import_name_aliases (
      source_name,
      normalized_source_name,
      user_id,
      user_type,
      created_by,
      updated_by,
      created_at,
      updated_at
    )
  values (
    trim(
      requested_source_name
    ),
    normalized_name,
    requested_user_id,
    requested_user_type,
    current_user_id,
    current_user_id,
    now(),
    now()
  )
  on conflict (
    normalized_source_name,
    user_type
  )
  do update set
    source_name =
      excluded.source_name,

    user_id =
      excluded.user_id,

    updated_by =
      current_user_id,

    updated_at =
      now()

  returning *
  into saved_alias;

  return jsonb_build_object(
    'id',
      saved_alias.id,

    'sourceName',
      saved_alias.source_name,

    'normalizedSourceName',
      saved_alias.normalized_source_name,

    'userId',
      saved_alias.user_id,

    'userType',
      saved_alias.user_type,

    'updatedAt',
      saved_alias.updated_at
  );
end;
$$;


ALTER FUNCTION "public"."save_schedule_import_name_alias"("requested_source_name" "text", "requested_user_id" "uuid", "requested_user_type" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_user_dynamic_job_type_permissions"("target_user_id" "uuid", "requested_permissions" "jsonb" DEFAULT '[]'::"jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  actor uuid := auth.uid(); item jsonb; requested_job_type_id uuid;
  requested_permission_key text; requested_enabled boolean; inherited_enabled boolean;
begin
  if actor is null then raise exception 'not authenticated'; end if;
  if not exists (select 1 from public.user_permissions up where up.user_id=actor and up.permission_key='users.manage')
    then raise exception 'not allowed'; end if;
  if not exists (select 1 from public.profiles p where p.id=target_user_id) then raise exception 'user not found'; end if;

  delete from public.user_job_type_permissions where user_id=target_user_id;

  for item in select value from jsonb_array_elements(coalesce(requested_permissions,'[]'::jsonb)) loop
    requested_job_type_id := nullif(item->>'jobTypeId','')::uuid;
    requested_permission_key := nullif(item->>'permissionKey','');
    requested_enabled := coalesce((item->>'enabled')::boolean,false);
    if requested_job_type_id is null or requested_permission_key is null then continue; end if;

    if not exists (
      select 1 from public.dynamic_permission_manifest dm
      join public.job_type_permission_settings s on s.job_type_id=requested_job_type_id and s.permission_key=dm.permission_key and s.audience=dm.audience
      where dm.permission_key=requested_permission_key
        and dm.feature_key=any(public.get_dynamic_job_type_active_features(requested_job_type_id))
    ) then continue; end if;

    inherited_enabled := public.get_inherited_dynamic_job_type_permission(requested_permission_key, requested_job_type_id, target_user_id);
    if requested_enabled is distinct from inherited_enabled then
      insert into public.user_job_type_permissions(user_id,job_type_id,permission_key,enabled,source,updated_by,updated_at)
      values(target_user_id,requested_job_type_id,requested_permission_key,requested_enabled,'user_override',actor,now())
      on conflict(user_id,job_type_id,permission_key) do update set
        enabled=excluded.enabled, source=excluded.source, updated_by=excluded.updated_by, updated_at=excluded.updated_at;
    end if;
  end loop;
end;
$$;


ALTER FUNCTION "public"."save_user_dynamic_job_type_permissions"("target_user_id" "uuid", "requested_permissions" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_user_permission_policy"("target_user_id" "uuid", "requested_profile_code" "text", "requested_scope_mode" "text", "requested_job_type_ids" "uuid"[] DEFAULT ARRAY[]::"uuid"[]) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_profile_id uuid;
  v_scope_mode text := coalesce(requested_scope_mode, 'all');
begin
  if v_actor is null then raise exception 'not authenticated'; end if;
  if not exists (
    select 1 from public.user_permissions up
    where up.user_id = v_actor and up.permission_key = 'users.manage'
  ) then raise exception 'not allowed'; end if;
  if not exists (select 1 from public.profiles p where p.id = target_user_id) then
    raise exception 'target user not found';
  end if;
  if v_scope_mode not in ('all','selected') then raise exception 'invalid scope mode'; end if;

  if nullif(trim(coalesce(requested_profile_code,'')), '') is not null then
    select pp.id into v_profile_id
    from public.permission_profiles pp
    where pp.code = requested_profile_code and pp.is_active = true;
    if v_profile_id is null then raise exception 'permission profile not found'; end if;
  end if;

  insert into public.user_permission_policies (user_id, profile_id, scope_mode, updated_by, updated_at)
  values (target_user_id, v_profile_id, v_scope_mode, v_actor, now())
  on conflict (user_id) do update set
    profile_id = excluded.profile_id,
    scope_mode = excluded.scope_mode,
    updated_by = excluded.updated_by,
    updated_at = excluded.updated_at;

  delete from public.user_permission_job_type_scopes where user_id = target_user_id;

  if v_scope_mode = 'selected' then
    insert into public.user_permission_job_type_scopes (user_id, job_type_id)
    select target_user_id, jt.id
    from public.job_types jt
    where jt.is_active = true
      and jt.id = any(coalesce(requested_job_type_ids, array[]::uuid[]))
    on conflict do nothing;
  end if;
end;
$$;


ALTER FUNCTION "public"."save_user_permission_policy"("target_user_id" "uuid", "requested_profile_code" "text", "requested_scope_mode" "text", "requested_job_type_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_dynamic_cutover_state"("p_enabled" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_user uuid := auth.uid();
  v_legacy_frozen boolean := false;
begin
  if v_user is null then
    raise exception 'not authenticated';
  end if;

  if not exists (
    select 1
    from public.user_permissions up
    where up.user_id = v_user
      and up.permission_key = 'users.manage'
  ) then
    raise exception 'not allowed';
  end if;

  select coalesce(legacy_frozen, false)
    into v_legacy_frozen
  from public.dynamic_cutover_settings
  where singleton = true;

  if p_enabled = false and v_legacy_frozen then
    raise exception 'unfreeze Legacy before switching back to Legacy-first';
  end if;

  insert into public.dynamic_cutover_settings (
    singleton,
    dynamic_first_enabled,
    updated_at,
    updated_by
  )
  values (
    true,
    p_enabled,
    now(),
    v_user
  )
  on conflict (singleton) do update
    set dynamic_first_enabled = excluded.dynamic_first_enabled,
        updated_at = now(),
        updated_by = v_user;

  return public.get_dynamic_cutover_state();
end;
$$;


ALTER FUNCTION "public"."set_dynamic_cutover_state"("p_enabled" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_dynamic_historical_assignment"("requested_historical_period_id" "uuid", "requested_assignment_id" "uuid", "requested_user_id" "uuid" DEFAULT NULL::"uuid", "requested_reason" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  actor uuid := auth.uid();
  target_period public.dynamic_historical_periods%rowtype;
  target_job public.job_types%rowtype;
  target_assignment public.dynamic_historical_assignments%rowtype;
  actor_is_admin boolean := false;
  old_user_id uuid;
  old_intentionally_unassigned boolean;
begin
  if actor is null then
    raise exception 'not authenticated';
  end if;

  select * into target_period
  from public.dynamic_historical_periods
  where id = requested_historical_period_id;

  if target_period.id is null then
    raise exception 'historical period not found';
  end if;

  select * into target_job
  from public.job_types
  where id = target_period.job_type_id
    and legacy_role is null;

  if target_job.id is null then
    raise exception 'dynamic job type not found';
  end if;

  select exists (
    select 1
    from public.profiles p
    where p.id = actor
      and p.role::text = 'admin'
  ) into actor_is_admin;

  if not actor_is_admin
     and not public.has_dynamic_job_type_permission('schedule.edit_history', target_job.id, actor) then
    raise exception 'not allowed';
  end if;

  select * into target_assignment
  from public.dynamic_historical_assignments
  where id = requested_assignment_id
    and historical_period_id = target_period.id
  for update;

  if target_assignment.id is null then
    raise exception 'historical assignment not found';
  end if;

  if requested_user_id is not null and not exists (
    select 1
    from public.job_type_memberships m
    join public.profiles p on p.id = m.user_id
    where m.job_type_id = target_job.id
      and m.user_id = requested_user_id
      and p.is_active = true
  ) then
    raise exception 'requested user is not an active member of this role';
  end if;

  if target_assignment.assigned_user_id is not distinct from requested_user_id
     and target_assignment.is_intentionally_unassigned = (requested_user_id is null) then
    return jsonb_build_object(
      'saved', true,
      'changed', false,
      'assignmentId', target_assignment.id
    );
  end if;

  old_user_id := target_assignment.assigned_user_id;
  old_intentionally_unassigned := target_assignment.is_intentionally_unassigned;

  update public.dynamic_historical_assignments
  set assigned_user_id = requested_user_id,
      is_intentionally_unassigned = (requested_user_id is null)
  where id = target_assignment.id;

  insert into public.audit_logs(
    action,
    actor_user_id,
    entity_type,
    entity_id,
    summary,
    metadata
  )
  values(
    'system_event',
    actor,
    'dynamic_historical_assignment',
    target_assignment.id,
    'שיבוץ היסטורי תוקן על ידי מנהל מורשה',
    jsonb_build_object(
      'historical_period_id', target_period.id,
      'job_type_id', target_job.id,
      'assignment_id', target_assignment.id,
      'work_date', target_assignment.work_date,
      'shift_code', target_assignment.shift_code,
      'original_user_id', target_assignment.original_user_id,
      'old_user_id', old_user_id,
      'new_user_id', requested_user_id,
      'old_intentionally_unassigned', old_intentionally_unassigned,
      'new_intentionally_unassigned', (requested_user_id is null),
      'reason', nullif(btrim(coalesce(requested_reason, '')), ''),
      'source_kind', target_assignment.source_kind
    )
  );

  return jsonb_build_object(
    'saved', true,
    'changed', true,
    'assignmentId', target_assignment.id,
    'oldUserId', old_user_id,
    'newUserId', requested_user_id
  );
end;
$$;


ALTER FUNCTION "public"."set_dynamic_historical_assignment"("requested_historical_period_id" "uuid", "requested_assignment_id" "uuid", "requested_user_id" "uuid", "requested_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_dynamic_job_type_active"("requested_job_type_id" "uuid", "requested_is_active" boolean) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  current_user_id uuid := auth.uid();
  current_month date := date_trunc('month', now() at time zone 'Asia/Jerusalem')::date;
  role_name text;
begin
  if current_user_id is null then raise exception 'not authenticated'; end if;
  if not exists(select 1 from public.profiles p where p.id=current_user_id and p.is_active=true) then
    raise exception 'user not active';
  end if;
  if not exists(
    select 1 from public.user_permissions up
    where up.user_id=current_user_id and up.permission_key='users.manage'
  ) then
    raise exception 'not allowed';
  end if;

  select jt.name into role_name
  from public.job_types jt
  where jt.id=requested_job_type_id;
  if role_name is null then raise exception 'job type not found'; end if;

  update public.job_types
  set is_active=requested_is_active, updated_at=now()
  where id=requested_job_type_id;

  -- A freeze/reactivation is a lifecycle state, not a one-month configuration tweak.
  -- Keep current/future snapshots aligned so a previously prepared next-month version
  -- cannot silently reactivate a frozen role.
  update public.job_type_configuration_versions v
  set snapshot=jsonb_set(v.snapshot,'{isActive}',to_jsonb(requested_is_active),true),
      updated_at=now()
  where v.job_type_id=requested_job_type_id
    and v.effective_month>=current_month;

  insert into public.audit_logs(action,actor_user_id,entity_type,entity_id,summary,metadata)
  values(
    'system_event',current_user_id,'dynamic_job_type',requested_job_type_id,
    case when requested_is_active then 'סוג תפקיד דינמי הופעל מחדש' else 'סוג תפקיד דינמי הוקפא' end,
    jsonb_build_object('job_type_id',requested_job_type_id,'job_type_name',role_name,'is_active',requested_is_active)
  );
end;
$$;


ALTER FUNCTION "public"."set_dynamic_job_type_active"("requested_job_type_id" "uuid", "requested_is_active" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_dynamic_job_type_manager"("requested_job_type_id" "uuid", "requested_user_id" "uuid", "requested_is_manager" boolean) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare actor uuid := auth.uid();
begin
  if actor is null then raise exception 'not authenticated'; end if;
  if not exists (
    select 1 from public.user_permissions up
    where up.user_id=actor and up.permission_key='users.manage'
  ) then raise exception 'not allowed'; end if;
  if not exists (select 1 from public.job_types where id=requested_job_type_id) then raise exception 'job type not found'; end if;
  if not exists (select 1 from public.profiles where id=requested_user_id) then raise exception 'user not found'; end if;

  if requested_is_manager then
    insert into public.job_type_managers(job_type_id,user_id,created_by)
    values(requested_job_type_id,requested_user_id,actor)
    on conflict do nothing;
  else
    delete from public.job_type_managers
    where job_type_id=requested_job_type_id and user_id=requested_user_id;
  end if;
end;
$$;


ALTER FUNCTION "public"."set_dynamic_job_type_manager"("requested_job_type_id" "uuid", "requested_user_id" "uuid", "requested_is_manager" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_dynamic_period_status"("requested_job_type_id" "uuid", "requested_year" integer, "requested_month" integer, "requested_action" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  current_user_id uuid:=auth.uid();
  target_period public.dynamic_availability_periods%rowtype;
  next_status text;
  slot_count integer:=0;
begin
  if current_user_id is null then raise exception 'not authenticated'; end if;
  if requested_action = 'open' then
    if not public.has_dynamic_job_type_permission('availability.open_period', requested_job_type_id, current_user_id) then raise exception 'not allowed'; end if;
  elsif requested_action in ('close','archive') then
    if not public.has_dynamic_job_type_permission('availability.close_period', requested_job_type_id, current_user_id) then raise exception 'not allowed'; end if;
  else
    raise exception 'invalid period action';
  end if;

  select * into target_period
  from public.dynamic_availability_periods
  where job_type_id=requested_job_type_id and year=requested_year and month=requested_month;

  if target_period.id is null then raise exception 'dynamic period not found'; end if;

  if requested_action='open' and target_period.status in ('shadow','draft','closed','open') then
    -- Ensure the employee-facing month is populated before it becomes usable.
    perform public.materialize_dynamic_availability_period_slots(target_period.id);
    next_status:='open';
  elsif requested_action='close' and target_period.status='open' then
    next_status:='closed';
  elsif requested_action='archive' and target_period.status='closed' and exists(
    select 1 from public.dynamic_schedule_publications p
    where p.job_type_id=requested_job_type_id and p.year=requested_year and p.month=requested_month
  ) then
    next_status:='archived';
  else
    raise exception 'invalid period transition from % using %',target_period.status,requested_action;
  end if;

  update public.dynamic_availability_periods
  set status=next_status,updated_at=now()
  where id=target_period.id;

  select count(*) into slot_count
  from public.dynamic_availability_slots
  where period_id=target_period.id;

  return jsonb_build_object(
    'periodId',target_period.id,
    'status',next_status,
    'action',requested_action,
    'slotCount',slot_count
  );
end;
$$;


ALTER FUNCTION "public"."set_dynamic_period_status"("requested_job_type_id" "uuid", "requested_year" integer, "requested_month" integer, "requested_action" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_dynamic_period_submission_deadline"("requested_job_type_id" "uuid", "requested_year" integer, "requested_month" integer, "requested_deadline" timestamp with time zone) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare actor uuid := auth.uid(); target_period public.dynamic_availability_periods%rowtype;
begin
  if actor is null then raise exception 'not authenticated'; end if;
  if not public.has_dynamic_job_type_permission('availability.open_period', requested_job_type_id, actor) then raise exception 'not allowed'; end if;
  select * into target_period from public.dynamic_availability_periods ap
  where ap.job_type_id=requested_job_type_id and ap.year=requested_year and ap.month=requested_month;
  if target_period.id is null then raise exception 'dynamic period not found'; end if;
  if target_period.status='archived' then raise exception 'archived period cannot be changed'; end if;
  update public.dynamic_availability_periods set submission_deadline=requested_deadline,updated_at=now() where id=target_period.id;
  insert into public.audit_logs(action,actor_user_id,entity_type,entity_id,summary,metadata)
  values('system_event',actor,'dynamic_availability_period',target_period.id,'מועד אחרון להגשת אילוצים עודכן',
    jsonb_build_object('job_type_id',requested_job_type_id,'year',requested_year,'month',requested_month,'submission_deadline',requested_deadline));
end; $$;


ALTER FUNCTION "public"."set_dynamic_period_submission_deadline"("requested_job_type_id" "uuid", "requested_year" integer, "requested_month" integer, "requested_deadline" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_dynamic_published_schedule_assignment"("requested_publication_id" "uuid", "requested_slot_id" "uuid", "requested_assignment_id" "uuid" DEFAULT NULL::"uuid", "requested_user_id" "uuid" DEFAULT NULL::"uuid", "requested_reason" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_actor uuid := auth.uid();
  v_publication public.dynamic_schedule_publications%rowtype;
  v_slot public.dynamic_availability_slots%rowtype;
  v_assignment public.dynamic_schedule_published_assignments%rowtype;
  v_unassigned public.dynamic_schedule_published_unassigned%rowtype;
  v_current_month date := date_trunc('month', (now() at time zone 'Asia/Jerusalem')::date)::date;
  v_publication_month date;
  v_required_assigned integer := 0;
  v_missing integer := 0;
  v_original_user_id uuid;
  v_new_assignment_id uuid;
begin
  if v_actor is null then raise exception 'not authenticated'; end if;

  select * into v_publication
  from public.dynamic_schedule_publications
  where id=requested_publication_id
  for update;
  if v_publication.id is null then raise exception 'publication not found'; end if;
  if not public.has_dynamic_job_type_permission('schedule.edit_published', v_publication.job_type_id, v_actor) then raise exception 'not allowed'; end if;
  if v_publication.status <> 'published' then raise exception 'published schedule is not editable'; end if;

  v_publication_month := make_date(v_publication.year,v_publication.month,1);
  if v_publication_month not in (v_current_month,(v_current_month+interval '1 month')::date) then
    raise exception 'only current month or next published month can be edited';
  end if;

  select * into v_slot
  from public.dynamic_availability_slots
  where id=requested_slot_id and period_id=v_publication.availability_period_id;
  if v_slot.id is null then raise exception 'slot not found in this publication'; end if;

  if requested_user_id is not null and not exists (
    select 1
    from public.job_type_memberships m
    join public.profiles p on p.id=m.user_id
    where m.job_type_id=v_publication.job_type_id
      and m.user_id=requested_user_id
      and p.is_active=true
  ) then
    raise exception 'requested user is not an active member of this role';
  end if;

  if requested_assignment_id is not null then
    select * into v_assignment
    from public.dynamic_schedule_published_assignments
    where id=requested_assignment_id
      and publication_id=v_publication.id
      and slot_id=v_slot.id
    for update;
    if v_assignment.id is null then raise exception 'assignment not found'; end if;

    if requested_user_id is null then
      v_original_user_id := coalesce(v_assignment.original_user_id,v_assignment.engine_user_id,v_assignment.user_id);

      delete from public.dynamic_schedule_published_assignments
      where id=v_assignment.id;

      if v_assignment.assignment_tier='required' then
        select count(*)::integer into v_required_assigned
        from public.dynamic_schedule_published_assignments a
        where a.publication_id=v_publication.id
          and a.slot_id=v_slot.id
          and a.assignment_tier='required';

        v_missing := greatest(v_slot.min_workers-v_required_assigned,0);
        if v_missing>0 then
          insert into public.dynamic_schedule_published_unassigned(
            publication_id,slot_id,shift_date,shift_code,shift_name,
            intentionally_unassigned_count,note,original_user_id
          ) values(
            v_publication.id,v_slot.id,v_slot.shift_date,v_slot.shift_code,v_slot.shift_name,
            v_missing,nullif(trim(coalesce(requested_reason,'')),''),v_original_user_id
          )
          on conflict(publication_id,shift_date,shift_code) do update set
            slot_id=excluded.slot_id,
            intentionally_unassigned_count=excluded.intentionally_unassigned_count,
            note=excluded.note,
            original_user_id=coalesce(public.dynamic_schedule_published_unassigned.original_user_id,excluded.original_user_id);
        else
          delete from public.dynamic_schedule_published_unassigned
          where publication_id=v_publication.id and slot_id=v_slot.id;
        end if;
      end if;

      insert into public.audit_logs(action,actor_user_id,entity_type,entity_id,summary,old_values,new_values,metadata)
      values(
        'system_event',v_actor,'dynamic_schedule_publication',v_publication.id,
        'משמרת בלוח דינמי סומנה כלא מאוישת',
        jsonb_build_object('assignment_id',v_assignment.id,'user_id',v_assignment.user_id),
        jsonb_build_object('intentionally_unassigned',true),
        jsonb_build_object('job_type_id',v_publication.job_type_id,'slot_id',v_slot.id,'shift_date',v_slot.shift_date,'shift_code',v_slot.shift_code,'reason',nullif(trim(coalesce(requested_reason,'')),''))
      );

      update public.dynamic_schedule_publications set updated_at=now() where id=v_publication.id;
      return jsonb_build_object('saved',true,'action','unassigned','publicationId',v_publication.id,'slotId',v_slot.id);
    end if;

    if v_assignment.user_id=requested_user_id then
      return jsonb_build_object('saved',true,'changed',false,'assignmentId',v_assignment.id);
    end if;

    if exists (
      select 1 from public.dynamic_schedule_published_assignments a
      where a.publication_id=v_publication.id and a.slot_id=v_slot.id
        and a.user_id=requested_user_id and a.id<>v_assignment.id
    ) then raise exception 'requested user is already assigned to this shift'; end if;

    update public.dynamic_schedule_published_assignments
    set user_id=requested_user_id,
        manager_edited=true,
        manager_override_note=nullif(trim(coalesce(requested_reason,'')),''),
        user_edited_by=null,
        user_edited_at=null
    where id=v_assignment.id;

    insert into public.audit_logs(action,actor_user_id,entity_type,entity_id,summary,old_values,new_values,metadata)
    values(
      'system_event',v_actor,'dynamic_schedule_publication',v_publication.id,
      'שיבוץ בלוח דינמי שונה על ידי מנהל',
      jsonb_build_object('assignment_id',v_assignment.id,'user_id',v_assignment.user_id),
      jsonb_build_object('assignment_id',v_assignment.id,'user_id',requested_user_id),
      jsonb_build_object('job_type_id',v_publication.job_type_id,'slot_id',v_slot.id,'shift_date',v_slot.shift_date,'shift_code',v_slot.shift_code,'reason',nullif(trim(coalesce(requested_reason,'')),''))
    );

    update public.dynamic_schedule_publications set updated_at=now() where id=v_publication.id;
    return jsonb_build_object('saved',true,'action','reassigned','assignmentId',v_assignment.id,'oldUserId',v_assignment.user_id,'newUserId',requested_user_id);
  end if;

  if requested_user_id is null then raise exception 'requested user is required when filling an unassigned position'; end if;

  select * into v_unassigned
  from public.dynamic_schedule_published_unassigned
  where publication_id=v_publication.id and slot_id=v_slot.id
  for update;
  if v_unassigned.publication_id is null or v_unassigned.intentionally_unassigned_count<1 then
    raise exception 'there is no intentionally unassigned position in this slot';
  end if;

  if exists (
    select 1 from public.dynamic_schedule_published_assignments a
    where a.publication_id=v_publication.id and a.slot_id=v_slot.id and a.user_id=requested_user_id
  ) then raise exception 'requested user is already assigned to this shift'; end if;

  insert into public.dynamic_schedule_published_assignments(
    publication_id,source_assignment_id,slot_id,shift_date,shift_code,shift_name,start_time,end_time,
    user_id,assignment_tier,score,reasons,engine_user_id,manager_edited,manager_override_note,original_user_id
  ) values(
    v_publication.id,null,v_slot.id,v_slot.shift_date,v_slot.shift_code,v_slot.shift_name,v_slot.start_time,v_slot.end_time,
    requested_user_id,'required',0,jsonb_build_array(jsonb_build_object('source','manager_published_edit')),
    v_unassigned.original_user_id,true,nullif(trim(coalesce(requested_reason,'')),''),v_unassigned.original_user_id
  ) returning id into v_new_assignment_id;

  if v_unassigned.intentionally_unassigned_count<=1 then
    delete from public.dynamic_schedule_published_unassigned
    where publication_id=v_publication.id and slot_id=v_slot.id;
  else
    update public.dynamic_schedule_published_unassigned
    set intentionally_unassigned_count=intentionally_unassigned_count-1,
        note=nullif(trim(coalesce(requested_reason,'')),'')
    where publication_id=v_publication.id and slot_id=v_slot.id;
  end if;

  insert into public.audit_logs(action,actor_user_id,entity_type,entity_id,summary,new_values,metadata)
  values(
    'system_event',v_actor,'dynamic_schedule_publication',v_publication.id,
    'עמדה לא מאוישת בלוח דינמי אוישה על ידי מנהל',
    jsonb_build_object('assignment_id',v_new_assignment_id,'user_id',requested_user_id),
    jsonb_build_object('job_type_id',v_publication.job_type_id,'slot_id',v_slot.id,'shift_date',v_slot.shift_date,'shift_code',v_slot.shift_code,'reason',nullif(trim(coalesce(requested_reason,'')),''))
  );

  update public.dynamic_schedule_publications set updated_at=now() where id=v_publication.id;
  return jsonb_build_object('saved',true,'action','filled','assignmentId',v_new_assignment_id,'newUserId',requested_user_id);
end;
$$;


ALTER FUNCTION "public"."set_dynamic_published_schedule_assignment"("requested_publication_id" "uuid", "requested_slot_id" "uuid", "requested_assignment_id" "uuid", "requested_user_id" "uuid", "requested_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_dynamic_schedule_draft_assignment"("requested_draft_id" "uuid", "requested_slot_id" "uuid", "requested_assignment_id" "uuid", "requested_user_id" "uuid", "requested_note" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_user uuid := auth.uid();
  d public.dynamic_schedule_shadow_drafts%rowtype;
  sl public.dynamic_availability_slots%rowtype;
  a public.dynamic_schedule_shadow_assignments%rowtype;
  v_assignment_id uuid;
  v_tier text := 'required';
  v_count integer;
begin
  if v_user is null then raise exception 'not authenticated'; end if;

  select * into d from public.dynamic_schedule_shadow_drafts where id=requested_draft_id;
  if not public.has_dynamic_job_type_permission('schedule.edit_draft', d.job_type_id, v_user) then raise exception 'not allowed'; end if;
  if d.id is null then raise exception 'draft not found'; end if;
  if d.status not in ('generated','incomplete') then raise exception 'draft is not editable'; end if;
  select * into sl from public.dynamic_availability_slots where id=requested_slot_id and period_id=d.availability_period_id;
  if sl.id is null then raise exception 'slot not found'; end if;
  if not exists(
    select 1 from public.job_type_memberships m join public.profiles p on p.id=m.user_id
    where m.job_type_id=d.job_type_id and m.user_id=requested_user_id and p.is_active=true
  ) then raise exception 'user is not an active member of this role'; end if;

  if requested_assignment_id is not null then
    select * into a from public.dynamic_schedule_shadow_assignments
    where id=requested_assignment_id and draft_id=d.id and slot_id=sl.id;
    if a.id is null then raise exception 'assignment not found'; end if;
    if exists(select 1 from public.dynamic_schedule_shadow_assignments x where x.draft_id=d.id and x.slot_id=sl.id and x.user_id=requested_user_id and x.id<>a.id) then
      raise exception 'user is already assigned to this shift';
    end if;
    update public.dynamic_schedule_shadow_assignments
    set engine_user_id=coalesce(engine_user_id,user_id), user_id=requested_user_id,
        manager_edited_by=v_user,manager_edited_at=now(),manager_override_note=nullif(btrim(requested_note),'')
    where id=a.id
    returning id into v_assignment_id;
  else
    if exists(select 1 from public.dynamic_schedule_shadow_assignments x where x.draft_id=d.id and x.slot_id=sl.id and x.user_id=requested_user_id) then
      raise exception 'user is already assigned to this shift';
    end if;
    select count(*)::integer into v_count from public.dynamic_schedule_shadow_assignments x where x.draft_id=d.id and x.slot_id=sl.id;
    if v_count>=sl.max_workers then raise exception 'shift reached maximum workers'; end if;
    v_tier := case when v_count<sl.min_workers then 'required' else 'target_optional' end;
    insert into public.dynamic_schedule_shadow_assignments(
      draft_id,slot_id,user_id,engine_user_id,assignment_tier,score,reasons,manager_edited_by,manager_edited_at,manager_override_note
    ) values(
      d.id,sl.id,requested_user_id,null,v_tier,0,jsonb_build_array('נוסף ידנית על ידי מנהל'),v_user,now(),nullif(btrim(requested_note),'')
    ) returning id into v_assignment_id;
  end if;

  perform public.dynamic_refresh_draft_metrics(d.id);
  insert into public.audit_logs(action,actor_user_id,entity_type,entity_id,summary,metadata)
  values('system_event',v_user,'dynamic_schedule_draft',d.id,'שיבוץ בטיוטה הדינמית נערך ידנית',
    jsonb_build_object('draft_id',d.id,'slot_id',sl.id,'assignment_id',v_assignment_id,'user_id',requested_user_id));
  return jsonb_build_object('saved',true,'assignmentId',v_assignment_id);
end;
$$;


ALTER FUNCTION "public"."set_dynamic_schedule_draft_assignment"("requested_draft_id" "uuid", "requested_slot_id" "uuid", "requested_assignment_id" "uuid", "requested_user_id" "uuid", "requested_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_dynamic_schedule_slot_intentionally_unassigned"("requested_draft_id" "uuid", "requested_slot_id" "uuid", "requested_count" integer, "requested_note" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_user uuid:=auth.uid();
  d public.dynamic_schedule_shadow_drafts%rowtype;
  sl public.dynamic_availability_slots%rowtype;
  v_assigned integer;
  v_missing integer;
  v_count integer;
begin
  if v_user is null then raise exception 'not authenticated'; end if;
  select * into d from public.dynamic_schedule_shadow_drafts where id=requested_draft_id;
  if not public.has_dynamic_job_type_permission('schedule.edit_draft', d.job_type_id, v_user) then raise exception 'not allowed'; end if;
  if d.id is null or d.status not in ('generated','incomplete') then raise exception 'draft is not editable'; end if;
  select * into sl from public.dynamic_availability_slots where id=requested_slot_id and period_id=d.availability_period_id;
  if sl.id is null then raise exception 'slot not found'; end if;
  select count(*)::integer into v_assigned from public.dynamic_schedule_shadow_assignments where draft_id=d.id and slot_id=sl.id and assignment_tier='required';
  v_missing:=greatest(sl.min_workers-v_assigned,0);
  v_count:=greatest(least(coalesce(requested_count,0),v_missing),0);

  if v_count=0 then
    delete from public.dynamic_schedule_draft_slot_overrides where draft_id=d.id and slot_id=sl.id;
  else
    insert into public.dynamic_schedule_draft_slot_overrides(draft_id,slot_id,intentionally_unassigned_count,note,updated_by,updated_at)
    values(d.id,sl.id,v_count,nullif(btrim(requested_note),''),v_user,now())
    on conflict(draft_id,slot_id) do update set
      intentionally_unassigned_count=excluded.intentionally_unassigned_count,note=excluded.note,updated_by=excluded.updated_by,updated_at=now();
  end if;
  perform public.dynamic_refresh_draft_metrics(d.id);
  insert into public.audit_logs(action,actor_user_id,entity_type,entity_id,summary,metadata)
  values('system_event',v_user,'dynamic_schedule_draft',d.id,
    case when v_count>0 then 'חוסר בטיוטה סומן כלא מאויש בכוונה' else 'סימון לא מאויש בכוונה הוסר' end,
    jsonb_build_object('draft_id',d.id,'slot_id',sl.id,'intentionally_unassigned_count',v_count));
  return jsonb_build_object('saved',true,'slotId',sl.id,'intentionallyUnassignedCount',v_count);
end;
$$;


ALTER FUNCTION "public"."set_dynamic_schedule_slot_intentionally_unassigned"("requested_draft_id" "uuid", "requested_slot_id" "uuid", "requested_count" integer, "requested_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_legacy_freeze_state"("p_frozen" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_user uuid := auth.uid();
  v_readiness jsonb;
begin
  if v_user is null then
    raise exception 'not authenticated';
  end if;

  if not exists (
    select 1
    from public.user_permissions up
    where up.user_id = v_user
      and up.permission_key = 'users.manage'
  ) then
    raise exception 'not allowed';
  end if;

  if p_frozen then
    v_readiness := public.get_legacy_freeze_readiness();
    if not coalesce((v_readiness->>'ready')::boolean, false) then
      raise exception 'Legacy cannot be frozen yet: enable Dynamic-first and assign every active legacy worker to at least one active Job Type';
    end if;
  end if;

  insert into public.dynamic_cutover_settings (
    singleton,
    dynamic_first_enabled,
    legacy_frozen,
    updated_at,
    updated_by
  )
  values (
    true,
    true,
    p_frozen,
    now(),
    v_user
  )
  on conflict (singleton) do update
    set legacy_frozen = excluded.legacy_frozen,
        updated_at = now(),
        updated_by = v_user;

  return public.get_dynamic_cutover_state();
end;
$$;


ALTER FUNCTION "public"."set_legacy_freeze_state"("p_frozen" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_morning_driver_assignment_intentionally_unassigned"("requested_assignment_id" "uuid", "requested_is_intentionally_unassigned" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  current_user_id uuid := auth.uid();
  current_permissions text[];
  target_assignment public.morning_driver_schedule_assignments%rowtype;
  target_period public.morning_driver_schedule_periods%rowtype;
begin
  if current_user_id is null then raise exception 'not authenticated'; end if;
  current_permissions := coalesce(public.get_my_permissions(), array[]::text[]);
  if not ('morning_driver_schedule.edit' = any(current_permissions)) then raise exception 'not allowed'; end if;

  select * into target_assignment
  from public.morning_driver_schedule_assignments assignment
  where assignment.id = requested_assignment_id
  for update;
  if not found then raise exception 'morning driver schedule assignment not found'; end if;

  select * into target_period
  from public.morning_driver_schedule_periods period
  where period.id = target_assignment.schedule_period_id
  for update;
  if target_period.status <> 'draft' then raise exception 'only draft schedules can mark intentionally unassigned shifts'; end if;
  if target_assignment.assignment_slot <> 1 then raise exception 'only minimum morning driver slot can be intentionally unassigned'; end if;
  if coalesce(requested_is_intentionally_unassigned, false) and target_assignment.assigned_user_id is not null then
    raise exception 'assigned morning driver slot cannot be marked intentionally unassigned';
  end if;

  update public.morning_driver_schedule_assignments
  set is_intentionally_unassigned = coalesce(requested_is_intentionally_unassigned, false),
      updated_at = now()
  where id = target_assignment.id
  returning * into target_assignment;

  return jsonb_build_object(
    'assignmentId', target_assignment.id,
    'isIntentionallyUnassigned', target_assignment.is_intentionally_unassigned
  );
end;
$$;


ALTER FUNCTION "public"."set_morning_driver_assignment_intentionally_unassigned"("requested_assignment_id" "uuid", "requested_is_intentionally_unassigned" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_my_development_mode"("requested_enabled" boolean, "requested_duration_minutes" integer DEFAULT 60) RETURNS TABLE("enabled" boolean, "enabled_at" timestamp with time zone, "expires_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  resolved_expires_at timestamptz;
begin
  if not exists (
    select 1
    from public.profiles p
    where p.id = auth.uid()
      and p.role = 'admin'
      and p.is_active = true
  ) then
    raise exception 'development mode is available to system administrators only'
      using errcode = '42501';
  end if;

  if requested_enabled then
    if requested_duration_minutes is null
       or requested_duration_minutes < 5
       or requested_duration_minutes > 1440 then
      raise exception 'development mode duration must be between 5 and 1440 minutes';
    end if;
    resolved_expires_at := now() + make_interval(mins => requested_duration_minutes);
  end if;

  insert into public.admin_development_sessions(
    user_id,
    enabled,
    enabled_at,
    expires_at,
    updated_at
  )
  values (
    auth.uid(),
    requested_enabled,
    case when requested_enabled then now() else null end,
    case when requested_enabled then resolved_expires_at else null end,
    now()
  )
  on conflict (user_id) do update
    set enabled = excluded.enabled,
        enabled_at = excluded.enabled_at,
        expires_at = excluded.expires_at,
        updated_at = now();

  insert into public.audit_logs(action, actor_user_id, entity_type, summary, metadata)
  values (
    'system_event',
    auth.uid(),
    'development_mode',
    case
      when requested_enabled then 'מצב פיתוח אישי הופעל'
      else 'מצב פיתוח אישי כובה'
    end,
    jsonb_build_object(
      'execution_mode', 'simulation',
      'enabled', requested_enabled,
      'expires_at', resolved_expires_at
    )
  );

  return query
  select ads.enabled, ads.enabled_at, ads.expires_at
  from public.admin_development_sessions as ads
  where ads.user_id = auth.uid();
end;
$$;


ALTER FUNCTION "public"."set_my_development_mode"("requested_enabled" boolean, "requested_duration_minutes" integer) OWNER TO "postgres";


