CREATE OR REPLACE FUNCTION "public"."set_user_permissions"("target_user_id" "uuid", "requested_permissions" "text"[]) RETURNS "text"[]
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  normalized_permissions text[];
  invalid_permissions text[];
  target_exists boolean;
begin
  if not public.is_current_user_admin() then
    raise exception 'Only administrators can update user permissions';
  end if;

  select exists (
    select 1
    from public.profiles
    where id = target_user_id
  )
  into target_exists;

  if not target_exists then
    raise exception 'Target user was not found';
  end if;

  select coalesce(
    array_agg(distinct permission_key),
    array[]::text[]
  )
  into normalized_permissions
  from unnest(
    coalesce(
      requested_permissions,
      array[]::text[]
    )
  ) as permission_key;

  select coalesce(
    array_agg(requested.permission_key),
    array[]::text[]
  )
  into invalid_permissions
  from unnest(normalized_permissions)
    as requested(permission_key)
  left join public.permissions existing
    on existing.permission_key =
      requested.permission_key
  where existing.permission_key is null;

  if cardinality(invalid_permissions) > 0 then
    raise exception
      'Invalid permissions: %',
      array_to_string(
        invalid_permissions,
        ', '
      );
  end if;

  -- מניעת מצב שבו מנהל מסיר מעצמו את האפשרות לנהל משתמשים.
  if target_user_id = auth.uid() then
    if not (
      'users.manage' =
      any(normalized_permissions)
    ) then
      raise exception
        'An administrator cannot remove users.manage from their own account';
    end if;

    if not (
      'users.view' =
      any(normalized_permissions)
    ) then
      raise exception
        'An administrator cannot remove users.view from their own account';
    end if;
  end if;

  delete from public.user_permissions
  where user_id = target_user_id;

  insert into public.user_permissions (
    user_id,
    permission_key,
    granted_by
  )
  select
    target_user_id,
    permission_key,
    auth.uid()
  from unnest(normalized_permissions)
    as permission_key;

  return (
    select coalesce(
      array_agg(
        up.permission_key
        order by p.sort_order, up.permission_key
      ),
      array[]::text[]
    )
    from public.user_permissions up
    join public.permissions p
      on p.permission_key = up.permission_key
    where up.user_id = target_user_id
  );
end;
$$;


ALTER FUNCTION "public"."set_user_permissions"("target_user_id" "uuid", "requested_permissions" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."submit_dynamic_scheduling_rule_proposal"("requested_job_type_id" "uuid", "requested_text" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare current_user_id uuid:=auth.uid(); suggestion_id uuid;
begin
  if current_user_id is null then raise exception 'not authenticated'; end if;
  if not exists(select 1 from public.user_permissions up where up.user_id=current_user_id and up.permission_key='users.manage') then raise exception 'not allowed'; end if;
  if length(trim(coalesce(requested_text,'')))<5 then raise exception 'rule text is too short'; end if;
  insert into public.job_type_ai_suggestions(job_type_id,suggestion_type,status,input_context,suggestion,created_by)
  values(requested_job_type_id,'scheduling_rule_natural_language','pending',jsonb_build_object('text',trim(requested_text)),jsonb_build_object('state','awaiting_ai_interpretation','autoApply',false),current_user_id)
  returning id into suggestion_id;
  return suggestion_id;
end;$$;


ALTER FUNCTION "public"."submit_dynamic_scheduling_rule_proposal"("requested_job_type_id" "uuid", "requested_text" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."submit_my_availability"() RETURNS TABLE("period_id" "uuid", "submission_status" "text", "submitted_at" timestamp with time zone, "available_count" integer, "unavailable_count" integer, "answered_count" integer, "total_shift_count" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  current_user_id uuid;

  current_user_email text;
  current_user_display_name text;

  target_period_id uuid;
  target_period_title text;
  target_period_year integer;
  target_period_month integer;
  target_period_status text;
  target_submission_deadline timestamptz;

  current_submission_status text;

  calculated_available_count integer;
  calculated_unavailable_count integer;
  calculated_answered_count integer;
  calculated_total_shift_count integer;
  calculated_auto_completed_count integer;

  submitted_timestamp timestamptz;
begin
  current_user_id := auth.uid();

  if current_user_id is null then
    raise exception
      'User is not authenticated';
  end if;

  select
    profile.email,
    profile.display_name
  into
    current_user_email,
    current_user_display_name
  from public.profiles profile
  where profile.id = current_user_id
    and profile.is_active = true;

  if current_user_email is null then
    raise exception
      'Authenticated user is not active';
  end if;

  if not exists (
    select 1
    from public.user_permissions permission
    where permission.user_id =
      current_user_id
      and permission.permission_key =
        'availability.view'
  ) then
    raise exception
      'User is not allowed to submit availability';
  end if;

  select
    period.id,
    period.title,
    period.year,
    period.month,
    period.status,
    period.submission_deadline
  into
    target_period_id,
    target_period_title,
    target_period_year,
    target_period_month,
    target_period_status,
    target_submission_deadline
  from public.availability_periods period
  where period.status = 'open'
  order by
    period.year desc,
    period.month desc,
    period.opened_at desc nulls last
  limit 1;

  if target_period_id is null then
    raise exception
      'Open availability period was not found';
  end if;

  if target_period_status <> 'open' then
    raise exception
      'Availability period is not open';
  end if;

  if (
    target_submission_deadline is not null
    and target_submission_deadline <= now()
  ) then
    raise exception
      'Availability submission deadline has passed';
  end if;

  select
    submission.status
  into
    current_submission_status
  from public.availability_submissions submission
  where submission.period_id =
    target_period_id
    and submission.user_id =
      current_user_id
  for update;

  if current_submission_status is null then
    raise exception
      'Availability submission record was not found';
  end if;

  if current_submission_status = 'submitted' then
    raise exception
      'Availability submission is already submitted';
  end if;

  select
    count(*) filter (
      where availability.availability_status =
        'available'
    )::integer,

    count(*) filter (
      where availability.availability_status =
        'unavailable'
    )::integer
  into
    calculated_available_count,
    calculated_unavailable_count
  from public.dispatcher_availability availability
  where availability.period_id =
    target_period_id
    and availability.user_id =
      current_user_id;

  calculated_answered_count :=
    calculated_available_count
    + calculated_unavailable_count;

  select
    count(*) filter (
      where availability.is_auto_completed = true
    )::integer
  into
    calculated_auto_completed_count
  from public.dispatcher_availability availability
  where availability.period_id =
    target_period_id
    and availability.user_id =
      current_user_id;

  select
    count(*)::integer
  into
    calculated_total_shift_count
  from public.availability_shift_slots slot
  where slot.period_id =
    target_period_id;

  if calculated_total_shift_count = 0 then
    raise exception
      'Availability period does not contain shift slots';
  end if;

  if (
    calculated_answered_count <>
    calculated_total_shift_count
  ) then
    raise exception
      'All shift slots must be answered before submission';
  end if;

  submitted_timestamp := now();

  update public.availability_submissions submission
  set
    status = 'submitted',

    submitted_at =
      submitted_timestamp,

    last_saved_at =
      coalesce(
        submission.last_saved_at,
        submitted_timestamp
      ),

    available_count =
      calculated_available_count,

    unavailable_count =
      calculated_unavailable_count,

    submission_source =
      case
        when calculated_auto_completed_count = 0
          then 'manual'
        when calculated_auto_completed_count >= calculated_total_shift_count
          then 'auto_no_submission'
        else 'auto_partial'
      end,

    auto_completed_count =
      calculated_auto_completed_count,

    updated_at =
      submitted_timestamp

  where submission.period_id =
    target_period_id
    and submission.user_id =
      current_user_id;

  insert into public.audit_logs (
    action,

    actor_user_id,
    actor_email,
    actor_display_name,

    target_user_id,
    target_email,
    target_display_name,

    entity_type,
    entity_id,
    summary,

    old_values,
    new_values,
    metadata
  )
  values (
    'availability_submitted',

    current_user_id,
    current_user_email,
    current_user_display_name,

    current_user_id,
    current_user_email,
    current_user_display_name,

    'availability_submission',
    target_period_id,

    format(
      'הוגשו אילוצים לחודש %s/%s על ידי %s',
      target_period_month,
      target_period_year,
      current_user_display_name
    ),

    jsonb_build_object(
      'status',
      current_submission_status
    ),

    jsonb_build_object(
      'status',
      'submitted',

      'submitted_at',
      submitted_timestamp,

      'available_count',
      calculated_available_count,

      'unavailable_count',
      calculated_unavailable_count,

      'answered_count',
      calculated_answered_count,

      'total_shift_count',
      calculated_total_shift_count
    ),

    jsonb_build_object(
      'source',
      'submit-my-availability-rpc',

      'period_id',
      target_period_id,

      'period_title',
      target_period_title,

      'year',
      target_period_year,

      'month',
      target_period_month
    )
  );

  return query
  select
    target_period_id,
    'submitted'::text,
    submitted_timestamp,
    calculated_available_count,
    calculated_unavailable_count,
    calculated_answered_count,
    calculated_total_shift_count;
end;
$$;


ALTER FUNCTION "public"."submit_my_availability"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."submit_my_daily_report"("requested_job_type_id" "uuid", "requested_items" "jsonb", "requested_report_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor uuid := auth.uid();
  today_il date := (now() at time zone 'Asia/Jerusalem')::date;
  target_report_id uuid;
  item jsonb;
  subject_id_value uuid;
  subject_name_value text;
  customer_id_value uuid;
  customer_name_value text;
  details_value text;
  sort_value integer := 0;
  recipient uuid;
  notification_id uuid;
  notification_ids jsonb := '[]'::jsonb;
  job_name text;
  recipient_ids jsonb;
begin
  if actor is null then
    raise exception 'not authenticated';
  end if;

  if not public.has_dynamic_job_type_permission(
    'daily_reports.submit',
    requested_job_type_id,
    actor
  ) then
    raise exception 'not allowed';
  end if;

  if jsonb_typeof(requested_items) <> 'array'
     or jsonb_array_length(requested_items) = 0 then
    raise exception 'at least one report item is required';
  end if;

  select
    jt.name,
    coalesce(jt.scheduling_config #> '{dailyReports,recipientUserIds}', '[]'::jsonb)
  into job_name, recipient_ids
  from public.job_types jt
  where jt.id = requested_job_type_id
    and jt.is_active = true
    and jt.legacy_role is null;

  if job_name is null then
    raise exception 'job type not found';
  end if;

  if requested_report_id is not null then
    select r.id
    into target_report_id
    from public.daily_reports r
    where r.id = requested_report_id
      and r.job_type_id = requested_job_type_id
      and r.user_id = actor
      and r.report_date = today_il;

    if target_report_id is null then
      raise exception 'prepared report not found';
    end if;

    update public.daily_reports r
    set status = 'submitted',
        submitted_at = now(),
        updated_at = now()
    where r.id = target_report_id;
  else
    insert into public.daily_reports(
      job_type_id,
      user_id,
      report_date,
      status,
      submitted_at,
      updated_at
    )
    values(
      requested_job_type_id,
      actor,
      today_il,
      'submitted',
      now(),
      now()
    )
    on conflict(job_type_id,user_id,report_date)
    do update
      set status = 'submitted',
          submitted_at = now(),
          updated_at = now()
    returning daily_reports.id into target_report_id;
  end if;

  delete from public.daily_report_items dri
  where dri.report_id = target_report_id;

  for item in
    select e.value
    from jsonb_array_elements(requested_items) as e(value)
  loop
    sort_value := sort_value + 1;
    subject_id_value := nullif(item ->> 'subjectId', '')::uuid;
    subject_name_value := trim(coalesce(item ->> 'subjectName', ''));
    customer_id_value := nullif(item ->> 'customerId', '')::uuid;
    customer_name_value := nullif(trim(coalesce(item ->> 'customerName', '')), '');
    details_value := trim(coalesce(item ->> 'details', ''));

    if subject_name_value = '' or details_value = '' then
      raise exception 'subject and details are required';
    end if;

    insert into public.daily_report_items(
      report_id,
      subject_id,
      subject_name,
      customer_id,
      customer_name,
      details,
      sort_order
    )
    values(
      target_report_id,
      subject_id_value,
      subject_name_value,
      customer_id_value,
      customer_name_value,
      details_value,
      sort_value
    );
  end loop;

  for recipient in
    select distinct recipient_value::uuid
    from jsonb_array_elements_text(recipient_ids) as recipients(recipient_value)
  loop
    if exists(
      select 1
      from public.profiles p
      where p.id = recipient
        and p.is_active = true
    ) then
      insert into public.notifications(
        type,
        priority,
        source,
        title,
        body,
        url,
        data,
        created_by,
        expires_at
      )
      values(
        'manager_message',
        'important',
        'daily_report',
        concat('דיווח יומי חדש · ', job_name),
        concat(
          coalesce(
            (select p.display_name from public.profiles p where p.id = actor),
            'עובד'
          ),
          ' שלח/ה דיווח יומי ל-',
          to_char(today_il, 'DD/MM/YYYY'),
          ' · ',
          jsonb_array_length(requested_items),
          ' פעילויות.'
        ),
        '/notifications',
        jsonb_build_object(
          'workflow', 'daily_report',
          'event', 'submitted',
          'reportId', target_report_id,
          'jobTypeId', requested_job_type_id,
          'actorUserId', actor,
          'recipientUserId', recipient,
          'pushPending', true
        ),
        actor,
        now() + interval '90 days'
      )
      returning notifications.id into notification_id;

      insert into public.notification_recipients(notification_id,user_id)
      values(notification_id,recipient)
      on conflict do nothing;

      notification_ids := notification_ids || jsonb_build_array(notification_id);
    end if;
  end loop;

  return jsonb_build_object(
    'reportId', target_report_id,
    'notificationIds', notification_ids
  );
end;
$$;


ALTER FUNCTION "public"."submit_my_daily_report"("requested_job_type_id" "uuid", "requested_items" "jsonb", "requested_report_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."submit_my_driver_availability"("requested_period_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  current_user_id uuid;
  current_permissions text[];

  target_period
    public.driver_availability_periods%rowtype;

  target_submission
    public.driver_availability_submissions%rowtype;

  total_days_count integer := 0;
  available_days_count integer := 0;
  unavailable_days_count integer := 0;
  marked_days_count integer := 0;
  submitted_at_value timestamptz := now();
begin
  current_user_id :=
    auth.uid();

  if current_user_id is null then
    raise exception
      'not authenticated';
  end if;

  if not exists (
    select 1
    from public.profiles
    where id = current_user_id
      and is_active = true
  ) then
    raise exception
      'user not active';
  end if;

  current_permissions :=
    coalesce(
      public.get_my_permissions(),
      array[]::text[]
    );

  if not (
    'driver_availability.view' =
      any(current_permissions)
  ) then
    raise exception
      'not allowed';
  end if;

  if requested_period_id is null then
    raise exception
      'driver availability period id is required';
  end if;

  select *
  into target_period
  from public.driver_availability_periods
  where id = requested_period_id
  for update;

  if not found then
    raise exception
      'driver availability period not found';
  end if;

  if target_period.status <> 'open' then
    raise exception
      'driver availability period is not open';
  end if;

  if (
    target_period.submission_deadline is not null
    and now() >
      target_period.submission_deadline
  ) then
    raise exception
      'driver availability submission deadline has passed';
  end if;

  select
    count(*)::integer
  into total_days_count
  from public.driver_availability_days
  where period_id =
    target_period.id;

  if total_days_count = 0 then
    raise exception
      'driver availability period has no days';
  end if;

  select
    count(*) filter (
      where availability_status =
        'available'
    )::integer,

    count(*) filter (
      where availability_status =
        'unavailable'
    )::integer,

    count(*)::integer

  into
    available_days_count,
    unavailable_days_count,
    marked_days_count

  from public.driver_availability_entries
  where period_id =
    target_period.id
    and user_id =
      current_user_id;

  if marked_days_count < total_days_count then
    raise exception
      'all driver availability days must be marked before submission';
  end if;

  select *
  into target_submission
  from public.driver_availability_submissions
  where period_id =
    target_period.id
    and user_id =
      current_user_id
  for update;

  if not found then
    raise exception
      'driver availability draft was not found';
  end if;

  if target_submission.status =
    'submitted'
  then
    return jsonb_build_object(
      'periodId',
        target_period.id,

      'userId',
        current_user_id,

      'status',
        target_submission.status,

      'availableCount',
        target_submission.available_count,

      'unavailableCount',
        target_submission.unavailable_count,

      'submittedAt',
        target_submission.submitted_at,

      'alreadySubmitted',
        true
    );
  end if;

  update public.driver_availability_submissions
  set
    status =
      'submitted',

    submitted_at =
      submitted_at_value,

    available_count =
      available_days_count,

    unavailable_count =
      unavailable_days_count,

    last_saved_at =
      coalesce(
        last_saved_at,
        submitted_at_value
      ),

    updated_at =
      submitted_at_value

  where id =
    target_submission.id

  returning *
  into target_submission;

  return jsonb_build_object(
    'periodId',
      target_period.id,

    'userId',
      current_user_id,

    'status',
      target_submission.status,

    'availableCount',
      target_submission.available_count,

    'unavailableCount',
      target_submission.unavailable_count,

    'submittedAt',
      target_submission.submitted_at,

    'alreadySubmitted',
      false
  );
end;
$$;


ALTER FUNCTION "public"."submit_my_driver_availability"("requested_period_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."submit_my_driver_availability"("requested_period_id" "uuid") IS 'Submits the authenticated on-call user availability after every day in the period has been marked.';



CREATE OR REPLACE FUNCTION "public"."submit_my_morning_driver_availability"("requested_period_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  current_user_id uuid := auth.uid();
  current_permissions text[];
  target_period public.morning_driver_availability_periods%rowtype;
  target_submission public.morning_driver_availability_submissions%rowtype;
  total_shifts integer;
  available_count integer;
  unavailable_count integer;
  answered_count integer;
  submitted_at_value timestamptz := now();
begin
  if current_user_id is null then
    raise exception 'not authenticated';
  end if;

  current_permissions :=
    coalesce(
      public.get_my_permissions(),
      array[]::text[]
    );

  if not (
    'morning_driver_availability.view'
      = any(current_permissions)
  ) then
    raise exception 'not allowed';
  end if;

  select *
  into target_period
  from public.morning_driver_availability_periods period
  where period.id = requested_period_id
  for update;

  if not found then
    raise exception 'morning driver availability period not found';
  end if;

  if target_period.status <> 'open' then
    raise exception 'morning driver availability period is not open';
  end if;

  select *
  into target_submission
  from public.morning_driver_availability_submissions submission
  where submission.period_id = target_period.id
    and submission.user_id = current_user_id
  for update;

  if not found then
    raise exception 'morning driver availability submission not found';
  end if;

  select count(*)
  into total_shifts
  from public.morning_driver_availability_shifts shift_item
  where shift_item.period_id = target_period.id;

  select
    count(*) filter (
      where entry.availability_status = 'available'
    ),
    count(*) filter (
      where entry.availability_status = 'unavailable'
    ),
    count(entry.id)
  into
    available_count,
    unavailable_count,
    answered_count
  from public.morning_driver_availability_shifts shift_item
  left join public.morning_driver_availability_entries entry
    on entry.shift_id = shift_item.id
   and entry.user_id = current_user_id
  where shift_item.period_id = target_period.id;

  if answered_count <> total_shifts then
    raise exception
      'all morning driver shifts must be answered before submission';
  end if;

  update public.morning_driver_availability_submissions
  set
    status = 'submitted',
    submitted_at =
      submitted_at_value,
    last_saved_at =
      coalesce(
        last_saved_at,
        submitted_at_value
      ),
    updated_at =
      submitted_at_value
  where id = target_submission.id;

  return jsonb_build_object(
    'periodId',
      target_period.id,
    'userId',
      current_user_id,
    'status',
      'submitted',
    'availableCount',
      available_count,
    'unavailableCount',
      unavailable_count,
    'submittedAt',
      submitted_at_value,
    'alreadySubmitted',
      target_submission.status = 'submitted'
  );
end;
$$;


ALTER FUNCTION "public"."submit_my_morning_driver_availability"("requested_period_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_calendar_special_day_to_holidays"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if tg_op = 'DELETE' then
    delete from public.holidays holiday
    where holiday.holiday_date =
        old.event_date
      and holiday.name =
        old.event_name
      and holiday.source =
        'calendar_special_days'
      and holiday.is_manual_override =
        false;

    return old;
  end if;


  /*
   * If an UPDATE changed the identifying fields,
   * remove the old synchronized row first.
   */
  if tg_op = 'UPDATE'
    and (
      old.event_date is distinct from
        new.event_date
      or
      old.event_name is distinct from
        new.event_name
    )
  then
    delete from public.holidays holiday
    where holiday.holiday_date =
        old.event_date
      and holiday.name =
        old.event_name
      and holiday.source =
        'calendar_special_days'
      and holiday.is_manual_override =
        false;
  end if;


  insert into public.holidays (
    holiday_date,
    name,
    schedule_type,
    holiday_group,
    source,
    is_manual_override
  )
  values (
    new.event_date,
    new.event_name,
    new.schedule_type
      ::public.schedule_type,
    new.holiday_group,
    'calendar_special_days',
    false
  )

  on conflict (
    holiday_date,
    name
  )
  do update set
    schedule_type =
      excluded.schedule_type,

    holiday_group =
      excluded.holiday_group,

    source =
      excluded.source,

    updated_at =
      now()

  /*
   * Never overwrite an explicit manual override.
   */
  where public.holidays
    .is_manual_override =
      false;


  return new;
end;
$$;


ALTER FUNCTION "public"."sync_calendar_special_day_to_holidays"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_dynamic_job_type_permission_settings"("requested_job_type_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  features text[];
begin
  features := public.get_dynamic_job_type_active_features(requested_job_type_id);

  delete from public.job_type_permission_settings s
  where s.job_type_id = requested_job_type_id
    and not exists (
      select 1
      from public.dynamic_permission_manifest m
      where m.permission_key = s.permission_key
        and m.audience = s.audience
        and m.feature_key = any(features)
    );

  insert into public.job_type_permission_settings
    (job_type_id, permission_key, audience, enabled, source, updated_at)
  select requested_job_type_id, m.permission_key, m.audience, m.default_enabled, 'manifest', now()
  from public.dynamic_permission_manifest m
  where m.feature_key = any(features)
  on conflict (job_type_id, permission_key, audience) do nothing;
end;
$$;


ALTER FUNCTION "public"."sync_dynamic_job_type_permission_settings"("requested_job_type_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_open_dynamic_availability_after_role_version_change"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  target_period public.dynamic_availability_periods%rowtype;
  target_materialization public.job_type_schedule_materializations%rowtype;
  affected_users uuid[] := array[]::uuid[];
  affected_user uuid;
  created_notification_id uuid;
  target_year integer := extract(year from new.effective_month)::integer;
  target_month integer := extract(month from new.effective_month)::integer;
  rebuilt_slots integer := 0;
  actor uuid := coalesce(auth.uid(), new.created_by);
begin
  select ap.* into target_period
  from public.dynamic_availability_periods ap
  where ap.job_type_id=new.job_type_id
    and ap.year=target_year
    and ap.month=target_month
    and ap.status='open'
  limit 1;

  if target_period.id is null then
    return new;
  end if;

  -- The preceding materialization trigger has already rebuilt this exact
  -- effective version. Read that canonical snapshot instead of guessing paths
  -- inside the configuration-version JSON.
  select m.* into target_materialization
  from public.job_type_schedule_materializations m
  where m.job_type_id=new.job_type_id
    and m.effective_month=new.effective_month
  limit 1;

  if target_materialization.id is null then
    raise warning 'availability sync skipped: materialization missing for job type %, month %',
      new.job_type_id,new.effective_month;
    return new;
  end if;

  select coalesce(array_agg(s.user_id),array[]::uuid[])
    into affected_users
  from public.dynamic_availability_submissions s
  where s.period_id=target_period.id
    and s.status in ('submitted','reopened');

  -- Existing answers are structurally tied to the old slot ids. Slot deletion
  -- cascades availability entries and draft candidates that reference them;
  -- the canonical role materializer then creates the new form structure.
  delete from public.dynamic_availability_slots
  where period_id=target_period.id;

  rebuilt_slots := public.materialize_dynamic_availability_period_slots(target_period.id);

  update public.dynamic_availability_periods ap
  set config_snapshot=coalesce(
        target_materialization.source_snapshot->'availabilityConfig',
        ap.config_snapshot,
        '{}'::jsonb
      ),
      updated_at=now()
  where ap.id=target_period.id;

  update public.dynamic_availability_submissions s
  set status='draft',submitted_at=null,updated_at=now()
  where s.period_id=target_period.id
    and s.user_id=any(affected_users);

  foreach affected_user in array affected_users loop
    begin
      insert into public.notifications(
        type,priority,source,title,body,url,data,created_by,expires_at
      ) values (
        'system','important','dynamic_availability',
        'תקופת האילוצים עודכנה',
        concat(
          coalesce(new.snapshot->>'name','התפקיד'),
          ' · מבנה המשמרות לחודש ',lpad(target_month::text,2,'0'),'/',target_year,
          ' השתנה. ההגשה הקודמת הוחזרה לטיוטה ויש למלא ולאשר את האילוצים מחדש.'
        ),
        '/my-availability',
        jsonb_build_object(
          'workflow','dynamic_availability',
          'event','role_definition_changed',
          'jobTypeId',new.job_type_id,
          'periodId',target_period.id,
          'year',target_year,
          'month',target_month,
          'recipientUserId',affected_user,
          'pushPending',true
        ),
        actor,
        now()+interval '90 days'
      ) returning id into created_notification_id;

      insert into public.notification_recipients(notification_id,user_id)
      values(created_notification_id,affected_user)
      on conflict do nothing;
    exception when others then
      -- A notification delivery problem must not prevent an administrator from
      -- saving the role or corrupt the freshly rebuilt availability period.
      raise warning 'availability sync notification failed for user %: %',affected_user,sqlerrm;
    end;
  end loop;

  insert into public.audit_logs(action,actor_user_id,entity_type,entity_id,summary,metadata)
  values(
    'system_event',actor,'dynamic_availability_period',target_period.id,
    'תקופת אילוצים עודכנה בעקבות שינוי מבנה תפקיד',
    jsonb_build_object(
      'job_type_id',new.job_type_id,
      'effective_month',new.effective_month,
      'rebuilt_slots',rebuilt_slots,
      'reset_submissions',coalesce(array_length(affected_users,1),0)
    )
  );

  return new;
exception when others then
  -- The role configuration is the source of truth. Never make role editing
  -- impossible because a secondary open-period synchronization encountered
  -- legacy/inconsistent period data. Record a DB warning and allow the save;
  -- a subsequent save will retry after the data issue is corrected.
  raise warning 'open availability sync failed for job type %, month %: %',
    new.job_type_id,new.effective_month,sqlerrm;
  return new;
end;
$$;


ALTER FUNCTION "public"."sync_open_dynamic_availability_after_role_version_change"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."track_profile_deactivation"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  if old.is_active = true and new.is_active = false then
    new.deactivated_at := now();
  elsif old.is_active = false and new.is_active = true then
    new.deactivated_at := null;
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."track_profile_deactivation"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."transfer_my_driver_duty"("requested_schedule_day_id" "uuid", "requested_new_driver_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  current_user_id uuid;
  target_day public.driver_schedule_days%rowtype;
  target_period public.driver_schedule_periods%rowtype;
  current_driver public.profiles%rowtype;
  selected_driver public.profiles%rowtype;
  current_year integer;
  current_month integer;
  current_period_value integer;
  target_period_value integer;
  current_date_in_israel date;
  previous_assignment_date date;
  next_assignment_date date;
  previous_gap_days integer;
  next_gap_days integer;
  warning_messages text[] := array[]::text[];
begin
  current_user_id := auth.uid();

  if current_user_id is null then
    raise exception 'not authenticated';
  end if;

  select *
  into current_driver
  from public.profiles
  where id = current_user_id
    and role = 'on_call'::public.user_role
    and is_active = true;

  if not found then
    raise exception 'active on-call driver profile not found';
  end if;

  if requested_schedule_day_id is null then
    raise exception 'driver schedule day id is required';
  end if;

  if requested_new_driver_id is null then
    raise exception 'new on-call driver id is required';
  end if;

  if requested_new_driver_id = current_user_id then
    raise exception 'new on-call driver must be different';
  end if;

  current_date_in_israel :=
    (now() at time zone 'Asia/Jerusalem')::date;

  current_year :=
    extract(year from current_date_in_israel)::integer;

  current_month :=
    extract(month from current_date_in_israel)::integer;

  current_period_value :=
    current_year * 12 + current_month - 1;

  select *
  into target_day
  from public.driver_schedule_days
  where id = requested_schedule_day_id
  for update;

  if not found then
    raise exception 'driver schedule day not found';
  end if;

  select *
  into target_period
  from public.driver_schedule_periods
  where id = target_day.period_id
  for update;

  if not found then
    raise exception 'driver schedule period not found';
  end if;

  if target_period.status <>
    'published'::public.driver_schedule_period_status
  then
    raise exception
      'only published driver schedules can be changed by drivers';
  end if;

  target_period_value :=
    target_period.year * 12 +
    target_period.month - 1;

  if target_period_value not in (
    current_period_value,
    current_period_value + 1
  ) then
    raise exception
      'drivers can change duties only in the current or next month';
  end if;

  if target_day.duty_date < current_date_in_israel then
    raise exception
      'past driver duties cannot be changed';
  end if;

  if target_day.assigned_user_id <> current_user_id then
    raise exception
      'driver can transfer only their own duty';
  end if;

  if target_day.is_locked then
    raise exception
      'locked driver duty cannot be changed';
  end if;

  select *
  into selected_driver
  from public.profiles
  where id = requested_new_driver_id
    and role = 'on_call'::public.user_role
    and is_active = true;

  if not found then
    raise exception
      'selected on-call driver was not found or is inactive';
  end if;

  if exists (
    select 1
    from public.driver_schedule_days adjacent_day
    where adjacent_day.id <> target_day.id
      and adjacent_day.assigned_user_id = requested_new_driver_id
      and adjacent_day.duty_date in (
        target_day.duty_date - 1,
        target_day.duty_date + 1
      )
  ) then
    raise exception
      'driver cannot be assigned on consecutive days';
  end if;

  select max(schedule_day.duty_date)
  into previous_assignment_date
  from public.driver_schedule_days schedule_day
  where schedule_day.id <> target_day.id
    and schedule_day.assigned_user_id = requested_new_driver_id
    and schedule_day.duty_date < target_day.duty_date;

  select min(schedule_day.duty_date)
  into next_assignment_date
  from public.driver_schedule_days schedule_day
  where schedule_day.id <> target_day.id
    and schedule_day.assigned_user_id = requested_new_driver_id
    and schedule_day.duty_date > target_day.duty_date;

  if previous_assignment_date is not null then
    previous_gap_days :=
      target_day.duty_date - previous_assignment_date;

    if previous_gap_days between 2 and 4 then
      warning_messages :=
        array_append(
          warning_messages,
          format(
            'מרווח של %s ימים בלבד מהכוננות הקודמת',
            previous_gap_days
          )
        );
    end if;
  end if;

  if next_assignment_date is not null then
    next_gap_days :=
      next_assignment_date - target_day.duty_date;

    if next_gap_days between 2 and 4 then
      warning_messages :=
        array_append(
          warning_messages,
          format(
            'מרווח של %s ימים בלבד עד הכוננות הבאה',
            next_gap_days
          )
        );
    end if;
  end if;

  update public.driver_schedule_days
  set
    assigned_user_id = requested_new_driver_id,
    assignment_source = 'swap'::public.driver_assignment_source,
    updated_at = now()
  where id = target_day.id
  returning *
  into target_day;

  perform public.write_audit_log(
    requested_action :=
      'driver_schedule_duty_transferred'::public.audit_action_type,
    requested_target_user_id :=
      requested_new_driver_id,
    requested_summary :=
      'Driver duty transferred',
    requested_old_values :=
      jsonb_build_object(
        'scheduleDayId', target_day.id,
        'dutyDate', target_day.duty_date,
        'assignedUserId', current_user_id,
        'assignedUserName',
          coalesce(
            current_driver.schedule_name,
            current_driver.display_name
          )
      ),
    requested_new_values :=
      jsonb_build_object(
        'scheduleDayId', target_day.id,
        'dutyDate', target_day.duty_date,
        'assignedUserId', requested_new_driver_id,
        'assignedUserName',
          coalesce(
            selected_driver.schedule_name,
            selected_driver.display_name
          ),
        'assignmentSource', 'swap'
      ),
    requested_metadata :=
      jsonb_build_object(
        'periodId', target_period.id,
        'year', target_period.year,
        'month', target_period.month,
        'warnings', to_jsonb(warning_messages)
      )
  );

  return jsonb_build_object(
    'scheduleDayId', target_day.id,
    'periodId', target_day.period_id,
    'dutyDate', target_day.duty_date,
    'previousDriverId', current_user_id,
    'previousDriverName',
      coalesce(
        current_driver.schedule_name,
        current_driver.display_name
      ),
    'assignedUserId', target_day.assigned_user_id,
    'assignedUserName',
      coalesce(
        selected_driver.schedule_name,
        selected_driver.display_name
      ),
    'assignmentSource', target_day.assignment_source,
    'hasWarnings',
      cardinality(warning_messages) > 0,
    'warnings', to_jsonb(warning_messages)
  );
end;
$$;


ALTER FUNCTION "public"."transfer_my_driver_duty"("requested_schedule_day_id" "uuid", "requested_new_driver_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."transfer_my_morning_driver_assignment"("requested_assignment_id" "uuid", "requested_new_driver_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  current_user_id uuid := auth.uid();

  current_permissions text[];

  target_assignment
    public.morning_driver_schedule_assignments%rowtype;

  target_period
    public.morning_driver_schedule_periods%rowtype;

  target_shift
    public.morning_driver_availability_shifts%rowtype;

  current_driver
    public.profiles%rowtype;

  selected_driver
    public.profiles%rowtype;

  current_date_in_israel date;

  warning_messages text[] :=
    array[]::text[];
begin
  if current_user_id is null then
    raise exception
      'not authenticated';
  end if;

  if requested_assignment_id is null then
    raise exception
      'morning driver assignment id is required';
  end if;

  if requested_new_driver_id is null then
    raise exception
      'new morning driver id is required';
  end if;

  if requested_new_driver_id =
    current_user_id
  then
    raise exception
      'new morning driver must be different';
  end if;

  current_permissions :=
    coalesce(
      public.get_my_permissions(),
      array[]::text[]
    );

  if not (
    'morning_driver_schedule.view'
      = any(current_permissions)
  ) then
    raise exception
      'not allowed';
  end if;

  select *
  into current_driver
  from public.profiles profile
  where profile.id =
      current_user_id
    and profile.role =
      'morning_driver'
        ::public.user_role
    and profile.is_active =
      true;

  if not found then
    raise exception
      'active morning driver profile not found';
  end if;

  select *
  into target_assignment
  from public.morning_driver_schedule_assignments assignment
  where assignment.id =
    requested_assignment_id
  for update;

  if not found then
    raise exception
      'morning driver schedule assignment not found';
  end if;

  select *
  into target_period
  from public.morning_driver_schedule_periods period
  where period.id =
    target_assignment.schedule_period_id
  for update;

  if not found then
    raise exception
      'morning driver schedule period not found';
  end if;

  if target_period.status <>
    'published'
  then
    raise exception
      'only published morning driver schedules can be changed by drivers';
  end if;

  current_date_in_israel :=
    (
      now()
      at time zone
        'Asia/Jerusalem'
    )::date;

  if target_period.year <>
      extract(
        year
        from current_date_in_israel
      )::integer
     or target_period.month <>
      extract(
        month
        from current_date_in_israel
      )::integer
  then
    raise exception
      'morning drivers can change assignments only in the current month';
  end if;

  select *
  into target_shift
  from public.morning_driver_availability_shifts shift_item
  where shift_item.id =
    target_assignment.availability_shift_id;

  if not found then
    raise exception
      'morning driver availability shift not found';
  end if;

  if target_shift.shift_date <
    current_date_in_israel
  then
    raise exception
      'past morning driver assignments cannot be changed';
  end if;

  if target_assignment.assigned_user_id <>
    current_user_id
  then
    raise exception
      'morning driver can transfer only their own assignment';
  end if;

  if target_assignment.is_locked then
    raise exception
      'locked morning driver assignment cannot be changed';
  end if;

  select *
  into selected_driver
  from public.profiles profile
  where profile.id =
      requested_new_driver_id
    and profile.role =
      'morning_driver'
        ::public.user_role
    and profile.is_active =
      true;

  if not found then
    raise exception
      'selected morning driver was not found or is inactive';
  end if;

  if exists (
    select 1
    from public.morning_driver_schedule_assignments duplicate_assignment
    where duplicate_assignment.schedule_period_id =
        target_assignment.schedule_period_id
      and duplicate_assignment.availability_shift_id =
        target_assignment.availability_shift_id
      and duplicate_assignment.id <>
        target_assignment.id
      and duplicate_assignment.assigned_user_id =
        requested_new_driver_id
  ) then
    raise exception
      'selected morning driver is already assigned to this shift';
  end if;

  if exists (
    select 1
    from public.morning_driver_schedule_assignments same_day_assignment
    join public.morning_driver_availability_shifts other_shift
      on other_shift.id =
        same_day_assignment.availability_shift_id
    where same_day_assignment.schedule_period_id =
        target_assignment.schedule_period_id
      and same_day_assignment.id <>
        target_assignment.id
      and same_day_assignment.assigned_user_id =
        requested_new_driver_id
      and other_shift.shift_date =
        target_shift.shift_date
  ) then
    warning_messages :=
      array_append(
        warning_messages,
        'הכונן החלופי כבר משובץ במשמרת אחרת באותו יום'
      );
  end if;

  if not exists (
    select 1
    from public.morning_driver_availability_entries entry
    where entry.period_id =
        target_period.availability_period_id
      and entry.shift_id =
        target_shift.id
      and entry.user_id =
        requested_new_driver_id
      and entry.availability_status =
        'available'
  ) then
    warning_messages :=
      array_append(
        warning_messages,
        'הכונן החלופי לא סימן זמינות למשמרת זו'
      );
  end if;

  update public.morning_driver_schedule_assignments
  set
    assigned_user_id =
      requested_new_driver_id,

    assignment_source =
      'swap',

    notes =
      nullif(
        concat_ws(
          E'\n',
          target_assignment.notes,
          case
            when cardinality(
              warning_messages
            ) > 0
            then
              'אזהרות העברה: '
              ||
              array_to_string(
                warning_messages,
                '; '
              )
            else null
          end
        ),
        ''
      ),

    updated_at =
      now()

  where id =
    target_assignment.id

  returning *
  into target_assignment;

  return jsonb_build_object(
    'assignmentId',
      target_assignment.id,

    'schedulePeriodId',
      target_assignment.schedule_period_id,

    'shiftDate',
      target_shift.shift_date,

    'startTime',
      target_shift.start_time,

    'endTime',
      target_shift.end_time,

    'previousDriverId',
      current_user_id,

    'previousDriverName',
      coalesce(
        current_driver.schedule_name,
        current_driver.display_name
      ),

    'assignedUserId',
      target_assignment.assigned_user_id,

    'assignedUserName',
      coalesce(
        selected_driver.schedule_name,
        selected_driver.display_name
      ),

    'assignmentSource',
      target_assignment.assignment_source,

    'hasWarnings',
      cardinality(
        warning_messages
      ) > 0,

    'warnings',
      to_jsonb(
        warning_messages
      )
  );
end;
$$;


ALTER FUNCTION "public"."transfer_my_morning_driver_assignment"("requested_assignment_id" "uuid", "requested_new_driver_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."trg_sync_dynamic_job_type_permissions"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  perform public.sync_dynamic_job_type_permission_settings(new.id);
  return new;
end;
