CREATE OR REPLACE FUNCTION "public"."update_availability_submission_deadline"("requested_category" "text", "requested_period_id" "uuid", "requested_deadline" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  current_user_id uuid := auth.uid();
  required_permission text;
  resolved_status text;
  updated_at_value timestamptz := now();
begin
  if current_user_id is null then
    raise exception 'not authenticated';
  end if;

  if requested_period_id is null then
    raise exception 'period id is required';
  end if;

  if requested_deadline is null then
    raise exception 'submission deadline is required';
  end if;

  required_permission :=
    case requested_category
      when 'dispatcher'
        then 'availability.manage'
      when 'driver'
        then 'driver_availability.manage'
      when 'morning_driver'
        then 'morning_driver_availability.manage'
      else null
    end;

  if required_permission is null then
    raise exception 'invalid availability category';
  end if;

  if not (
    required_permission =
      any(
        coalesce(
          public.get_my_permissions(),
          array[]::text[]
        )
      )
  ) then
    raise exception 'not allowed';
  end if;

  if requested_category =
    'dispatcher'
  then
    select period.status::text
    into resolved_status
    from public.availability_periods period
    where period.id =
      requested_period_id
    for update;

    if not found then
      raise exception 'availability period not found';
    end if;

    if resolved_status not in (
      'draft',
      'open'
    ) then
      raise exception
        'deadline can only be changed while the period is draft or open';
    end if;

    update public.availability_periods
    set
      submission_deadline =
        requested_deadline,
      updated_by =
        current_user_id,
      updated_at =
        updated_at_value
    where id =
      requested_period_id;

  elsif requested_category =
    'driver'
  then
    select period.status::text
    into resolved_status
    from public.driver_availability_periods period
    where period.id =
      requested_period_id
    for update;

    if not found then
      raise exception 'driver availability period not found';
    end if;

    if resolved_status not in (
      'draft',
      'open'
    ) then
      raise exception
        'deadline can only be changed while the period is draft or open';
    end if;

    update public.driver_availability_periods
    set
      submission_deadline =
        requested_deadline,
      updated_by =
        current_user_id,
      updated_at =
        updated_at_value
    where id =
      requested_period_id;

  else
    select period.status::text
    into resolved_status
    from public.morning_driver_availability_periods period
    where period.id =
      requested_period_id
    for update;

    if not found then
      raise exception 'morning driver availability period not found';
    end if;

    if resolved_status not in (
      'draft',
      'open'
    ) then
      raise exception
        'deadline can only be changed while the period is draft or open';
    end if;

    update public.morning_driver_availability_periods
    set
      submission_deadline =
        requested_deadline,
      updated_by =
        current_user_id,
      updated_at =
        updated_at_value
    where id =
      requested_period_id;
  end if;

  insert into public.audit_logs (
    user_id,
    action,
    entity_type,
    entity_id,
    summary,
    actor_user_id,
    metadata
  )
  values (
    current_user_id,
    'availability.deadline.updated',
    requested_category ||
      '_availability_period',
    requested_period_id,
    'עודכן מועד אחרון להגשת אילוצים',
    current_user_id,
    jsonb_build_object(
      'category',
        requested_category,
      'submissionDeadline',
        requested_deadline
    )
  );

  return jsonb_build_object(
    'category',
      requested_category,
    'periodId',
      requested_period_id,
    'submissionDeadline',
      requested_deadline,
    'updatedAt',
      updated_at_value
  );
end;
$$;


ALTER FUNCTION "public"."update_availability_submission_deadline"("requested_category" "text", "requested_period_id" "uuid", "requested_deadline" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_current_driver_schedule_day"("requested_schedule_day_id" "uuid", "requested_assigned_user_id" "uuid" DEFAULT NULL::"uuid", "requested_is_locked" boolean DEFAULT false, "requested_note" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  current_user_id uuid;
  current_permissions text[];
  target_day public.driver_schedule_days%rowtype;
  target_period public.driver_schedule_periods%rowtype;
  selected_driver public.profiles%rowtype;
  linked_availability_day_id uuid;
  selected_availability_status text;
  previous_assignment_date date;
  next_assignment_date date;
  previous_gap_days integer;
  next_gap_days integer;
  current_date_in_israel date;
  current_year integer;
  current_month integer;
  current_period_value integer;
  target_period_value integer;
  normalized_note text;
  warning_messages text[] := array[]::text[];
  final_note text;
begin
  current_user_id := auth.uid();

  if current_user_id is null then
    raise exception 'not authenticated';
  end if;

  if not exists (
    select 1
    from public.profiles
    where id = current_user_id
      and is_active = true
  ) then
    raise exception 'user not active';
  end if;

  current_permissions :=
    coalesce(
      public.get_my_permissions(),
      array[]::text[]
    );

  if not (
    'driver_schedule.edit_any' =
      any(current_permissions)
  ) then
    raise exception 'not allowed';
  end if;

  if requested_schedule_day_id is null then
    raise exception 'driver schedule day id is required';
  end if;

  current_date_in_israel :=
    (now() at time zone 'Asia/Jerusalem')::date;
  current_year :=
    extract(year from current_date_in_israel)::integer;
  current_month :=
    extract(month from current_date_in_israel)::integer;

  current_period_value :=
    current_year * 12 +
    current_month - 1;

  select *
  into target_day
  from public.driver_schedule_days
  where id = requested_schedule_day_id
  for update;

  if not found then
    raise exception 'driver schedule day not found';
  end if;

  select *
  into target_period
  from public.driver_schedule_periods
  where id = target_day.period_id
  for update;

  if not found then
    raise exception 'driver schedule period not found';
  end if;

  if target_period.status <>
    'published'::public.driver_schedule_period_status
  then
    raise exception
      'only published current or next month driver schedules can be edited';
  end if;

  target_period_value :=
    target_period.year * 12 +
    target_period.month - 1;

  if target_period_value not in (
    current_period_value,
    current_period_value + 1
  ) then
    raise exception
      'only current or next month driver schedule can be edited';
  end if;

  normalized_note :=
    nullif(trim(coalesce(requested_note, '')), '');

  if requested_assigned_user_id is null then
    update public.driver_schedule_days
    set
      assigned_user_id = null,
      assignment_source = null,
      is_locked = coalesce(requested_is_locked, false),
      notes = normalized_note,
      updated_at = now()
    where id = target_day.id
    returning *
    into target_day;

    return jsonb_build_object(
      'scheduleDayId', target_day.id,
      'periodId', target_day.period_id,
      'dutyDate', target_day.duty_date,
      'assignedUserId', null,
      'assignedUserName', null,
      'assignmentSource', null,
      'isLocked', target_day.is_locked,
      'notes', target_day.notes,
      'hasWarnings', false,
      'warnings', '[]'::jsonb
    );
  end if;

  select *
  into selected_driver
  from public.profiles
  where id = requested_assigned_user_id
    and role = 'on_call'::public.user_role
    and is_active = true;

  if not found then
    raise exception
      'selected on-call driver was not found or is inactive';
  end if;

  if exists (
    select 1
    from public.driver_schedule_days adjacent_day
    where adjacent_day.id <> target_day.id
      and adjacent_day.assigned_user_id =
        requested_assigned_user_id
      and adjacent_day.duty_date in (
        target_day.duty_date - 1,
        target_day.duty_date + 1
      )
  ) then
    warning_messages :=
      array_append(
        warning_messages,
        'לכונן קיימת כוננות ביום סמוך'
      );
  end if;

  select max(schedule_day.duty_date)
  into previous_assignment_date
  from public.driver_schedule_days schedule_day
  where schedule_day.id <> target_day.id
    and schedule_day.assigned_user_id =
      requested_assigned_user_id
    and schedule_day.duty_date < target_day.duty_date;

  select min(schedule_day.duty_date)
  into next_assignment_date
  from public.driver_schedule_days schedule_day
  where schedule_day.id <> target_day.id
    and schedule_day.assigned_user_id =
      requested_assigned_user_id
    and schedule_day.duty_date > target_day.duty_date;

  if previous_assignment_date is not null then
    previous_gap_days :=
      target_day.duty_date - previous_assignment_date;

    if previous_gap_days between 2 and 4 then
      warning_messages :=
        array_append(
          warning_messages,
          format(
            'מרווח של %s ימים בלבד מהכוננות הקודמת',
            previous_gap_days
          )
        );
    end if;
  end if;

  if next_assignment_date is not null then
    next_gap_days :=
      next_assignment_date - target_day.duty_date;

    if next_gap_days between 2 and 4 then
      warning_messages :=
        array_append(
          warning_messages,
          format(
            'מרווח של %s ימים בלבד עד הכוננות הבאה',
            next_gap_days
          )
        );
    end if;
  end if;

  if target_period.availability_period_id is not null then
    select availability_day.id
    into linked_availability_day_id
    from public.driver_availability_days availability_day
    where availability_day.period_id =
        target_period.availability_period_id
      and availability_day.availability_date =
        target_day.duty_date
    limit 1;

    if linked_availability_day_id is not null then
      select availability_entry.availability_status
      into selected_availability_status
      from public.driver_availability_entries availability_entry
      where availability_entry.period_id =
          target_period.availability_period_id
        and availability_entry.day_id =
          linked_availability_day_id
        and availability_entry.user_id =
          requested_assigned_user_id
      limit 1;

      if selected_availability_status = 'unavailable' then
        warning_messages :=
          array_append(
            warning_messages,
            'הכונן סימן שאינו זמין בתאריך זה'
          );
      elsif selected_availability_status is null then
        warning_messages :=
          array_append(
            warning_messages,
            'לא נמצא סימון זמינות של הכונן לתאריך זה'
          );
      end if;
    end if;
  end if;

  final_note :=
    concat_ws(
      E'\n',
      normalized_note,
      case
        when cardinality(warning_messages) > 0
        then
          'אזהרות: ' ||
          array_to_string(warning_messages, '; ')
        else null
      end
    );

  update public.driver_schedule_days
  set
    assigned_user_id = requested_assigned_user_id,
    assignment_source = 'manual',
    is_locked = coalesce(requested_is_locked, false),
    notes = nullif(final_note, ''),
    updated_at = now()
  where id = target_day.id
  returning *
  into target_day;

  return jsonb_build_object(
    'scheduleDayId', target_day.id,
    'periodId', target_day.period_id,
    'dutyDate', target_day.duty_date,
    'assignedUserId', target_day.assigned_user_id,
    'assignedUserName',
      coalesce(
        selected_driver.schedule_name,
        selected_driver.display_name
      ),
    'assignmentSource', target_day.assignment_source,
    'isLocked', target_day.is_locked,
    'notes', target_day.notes,
    'hasWarnings',
      cardinality(warning_messages) > 0,
    'warnings', to_jsonb(warning_messages)
  );
end;
$$;


ALTER FUNCTION "public"."update_current_driver_schedule_day"("requested_schedule_day_id" "uuid", "requested_assigned_user_id" "uuid", "requested_is_locked" boolean, "requested_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_current_schedule_shift"("requested_shift_id" "uuid", "requested_new_user_id" "uuid", "requested_reason" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_user_id uuid :=
    (select auth.uid());

  actor_display_name text;

  has_schedule_edit boolean :=
    false;

  target_shift
    public.schedule_shifts%rowtype;

  target_period
    public.schedule_periods%rowtype;

  previous_user_id uuid;
  previous_user_name text;
  new_user_name text;

  normalized_reason text :=
    nullif(
      trim(requested_reason),
      ''
    );

  old_notification_id uuid;
  new_notification_id uuid;

  notification_ids uuid[] :=
    array[]::uuid[];

  shift_label text;

  current_year integer;
  current_month integer;

  audit_summary text;
begin
  if actor_user_id is null then
    raise exception
      'not authenticated';
  end if;

  select
    profile.display_name
  into
    actor_display_name
  from public.profiles
    profile
  where profile.id =
      actor_user_id
    and profile.is_active =
      true;

  if actor_display_name is null then
    raise exception
      'user not active';
  end if;

  select exists (
    select 1
    from public.user_permissions
      permission
    where permission.user_id =
        actor_user_id
      and permission.permission_key =
        'schedule.edit'
  )
  into
    has_schedule_edit;

  if not has_schedule_edit then
    raise exception
      'schedule edit permission required';
  end if;

  select
    shift.*
  into
    target_shift
  from public.schedule_shifts
    shift
  where shift.id =
      requested_shift_id
  for update;

  if not found then
    raise exception
      'schedule shift not found';
  end if;

  select
    period.*
  into
    target_period
  from public.schedule_periods
    period
  where period.id =
      target_shift.period_id;

  if not found then
    raise exception
      'schedule period not found';
  end if;

  current_year :=
    to_char(
      timezone(
        'Asia/Jerusalem',
        now()
      ),
      'YYYY'
    )::integer;

  current_month :=
    to_char(
      timezone(
        'Asia/Jerusalem',
        now()
      ),
      'MM'
    )::integer;

  /*
   * A user with schedule.edit may correct a published dispatcher
   * schedule in the current month or in the immediately following
   * month. Older and more distant future schedules remain read-only.
   */
  if (
    target_period.year * 12 +
    target_period.month - 1
  ) not in (
    current_year * 12 +
      current_month - 1,
    current_year * 12 +
      current_month
  ) then
    raise exception
      'only current or next month schedule can be edited';
  end if;

  if target_period.status <>
      'published'
  then
    raise exception
      'only published current or next month schedule can be edited';
  end if;

  select
    coalesce(
      profile.schedule_name,
      profile.display_name
    )
  into
    new_user_name
  from public.profiles
    profile
  where profile.id =
      requested_new_user_id
    and profile.is_active =
      true
    and profile.role =
      'dispatcher';

  if new_user_name is null then
    raise exception
      'target dispatcher is not active';
  end if;

  previous_user_id :=
    target_shift.assigned_user_id;

  if previous_user_id is not null then
    select
      coalesce(
        profile.schedule_name,
        profile.display_name
      )
    into
      previous_user_name
    from public.profiles
      profile
    where profile.id =
        previous_user_id;
  end if;

  if previous_user_id =
      requested_new_user_id
  then
    raise exception
      'dispatcher is already assigned to this shift';
  end if;

  if exists (
    select 1
    from public.schedule_shifts
      other_shift
    where other_shift.period_id =
        target_shift.period_id

      and other_shift.id <>
        target_shift.id

      and other_shift.assigned_user_id =
        requested_new_user_id

      and (
        (
          other_shift.starts_at <
            target_shift.ends_at

          and other_shift.ends_at >
            target_shift.starts_at
        )

        or

        other_shift.ends_at =
          target_shift.starts_at

        or

        other_shift.starts_at =
          target_shift.ends_at
      )
  ) then
    raise exception
      'target dispatcher has overlapping or consecutive shift';
  end if;

  update public.schedule_shifts
  set
    assigned_user_id =
      requested_new_user_id,

    assignment_source =
      'manual',

    updated_at =
      now()
  where id =
      target_shift.id;

  /*
   * ה-trigger של schedule_shifts יוצר את רשומת
   * schedule_assignment_history.
   * אם נמסרה סיבה, אנחנו מוסיפים אותה לרשומה
   * שנוצרה עכשיו.
   */
  if normalized_reason is not null then
    update public.schedule_assignment_history
      history
    set
      reason =
        normalized_reason
    where history.id = (
      select
        recent_history.id
      from public.schedule_assignment_history
        recent_history
      where recent_history.shift_id =
          target_shift.id

        and recent_history.changed_by =
          actor_user_id

        and recent_history.previous_user_id
          is not distinct from
            previous_user_id

        and recent_history.new_user_id =
          requested_new_user_id

      order by
        recent_history.created_at
          desc

      limit 1
    );
  end if;

  shift_label :=
    to_char(
      target_shift.shift_date,
      'DD/MM/YYYY'
    )
    ||
    ' '
    ||
    to_char(
      target_shift.starts_at
        at time zone
          'Asia/Jerusalem',
      'HH24:MI'
    )
    ||
    '–'
    ||
    to_char(
      target_shift.ends_at
        at time zone
          'Asia/Jerusalem',
      'HH24:MI'
    );

  /*
   * התראה למוקדן שהוסר מהמשמרת.
   */
  if previous_user_id is not null then
    insert into public.notifications (
      type,
      priority,
      source,
      title,
      body,
      url,
      data,
      created_by,
      expires_at
    )
    values (
      'system',
      'important',
      'schedule_edit',
      'שינוי בשיבוץ המשמרות',
      'הוסרת מהמשמרת '
        || shift_label
        || '. המוקדן החדש: '
        || new_user_name
        || '.',
      '/schedule',
      jsonb_build_object(
        'workflow',
          'schedule_edit',

        'event',
          'assignment_changed',

        'actorUserId',
          actor_user_id,

        'shiftId',
          target_shift.id,

        'previousUserId',
          previous_user_id,

        'newUserId',
          requested_new_user_id
      ),
      actor_user_id,
      now() +
        interval '90 days'
    )
    returning id
    into old_notification_id;

    insert into public.notification_recipients (
      notification_id,
      user_id
    )
    values (
      old_notification_id,
      previous_user_id
    );

    notification_ids :=
      array_append(
        notification_ids,
        old_notification_id
      );
  end if;

  /*
   * התראה למוקדן החדש.
   */
  insert into public.notifications (
    type,
    priority,
    source,
    title,
    body,
    url,
    data,
    created_by,
    expires_at
  )
  values (
    'system',
    'important',
    'schedule_edit',
    'שובצת למשמרת',
    'שובצת למשמרת '
      || shift_label
      || ' בעקבות שינוי בלוח.',
    '/schedule',
    jsonb_build_object(
      'workflow',
        'schedule_edit',

      'event',
        'assignment_changed',

      'actorUserId',
        actor_user_id,

      'shiftId',
        target_shift.id,

      'previousUserId',
        previous_user_id,

      'newUserId',
        requested_new_user_id
    ),
    actor_user_id,
    now() +
      interval '90 days'
  )
  returning id
  into new_notification_id;

  insert into public.notification_recipients (
    notification_id,
    user_id
  )
  values (
    new_notification_id,
    requested_new_user_id
  );

  notification_ids :=
    array_append(
      notification_ids,
      new_notification_id
    );

  /*
   * תיאור אנושי ליומן המערכת.
   * audit_logs.summary הוא NOT NULL.
   */
  audit_summary :=
    concat(
      'שינוי שיבוץ מוקדן: ',
      coalesce(
        previous_user_name,
        'ללא שיבוץ'
      ),
      ' → ',
      new_user_name,
      ' | ',
      shift_label,
      case
        when normalized_reason
          is not null
        then
          ' | סיבה: '
          || normalized_reason
        else
          ''
      end
    );

  insert into public.audit_logs (
    user_id,
    action,
    entity_type,
    entity_id,
    summary,
    old_values,
    new_values,
    metadata
  )
  values (
    actor_user_id,
    'schedule.assignment.updated',
    'schedule_shift',
    target_shift.id,
    audit_summary,
    jsonb_build_object(
      'assignedUserId',
        previous_user_id,

      'assignedUserName',
        previous_user_name
    ),
    jsonb_build_object(
      'assignedUserId',
        requested_new_user_id,

      'assignedUserName',
        new_user_name
    ),
    jsonb_build_object(
      'reason',
        normalized_reason,

      'periodId',
        target_period.id,

      'year',
        target_period.year,

      'month',
        target_period.month,

      'actorDisplayName',
        actor_display_name
    )
  );

  return jsonb_build_object(
    'shiftId',
      target_shift.id,

    'previousUserId',
      previous_user_id,

    'previousUserName',
      previous_user_name,

    'newUserId',
      requested_new_user_id,

    'newUserName',
      new_user_name,

    'shiftDate',
      target_shift.shift_date,

    'startsAt',
      target_shift.starts_at,

    'endsAt',
      target_shift.ends_at,

    'notificationIds',
      to_jsonb(
        notification_ids
      )
  );
end;
$$;


ALTER FUNCTION "public"."update_current_schedule_shift"("requested_shift_id" "uuid", "requested_new_user_id" "uuid", "requested_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_driver_schedule_day"("requested_schedule_day_id" "uuid", "requested_assigned_user_id" "uuid" DEFAULT NULL::"uuid", "requested_is_locked" boolean DEFAULT false, "requested_note" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  current_user_id uuid;
  current_permissions text[];

  target_day
    public.driver_schedule_days%rowtype;

  target_period
    public.driver_schedule_periods%rowtype;

  selected_driver
    public.profiles%rowtype;

  linked_availability_day_id uuid;

  selected_availability_status text;

  previous_assignment_date date;
  next_assignment_date date;

  previous_gap_days integer;
  next_gap_days integer;

  normalized_note text;
  warning_messages text[] :=
    array[]::text[];

  final_note text;
begin
  current_user_id :=
    auth.uid();

  if current_user_id is null then
    raise exception
      'not authenticated';
  end if;

  if not exists (
    select 1
    from public.profiles
    where id =
      current_user_id
      and is_active = true
  ) then
    raise exception
      'user not active';
  end if;

  current_permissions :=
    coalesce(
      public.get_my_permissions(),
      array[]::text[]
    );

  if not (
    'driver_schedule.edit' =
      any(current_permissions)
  ) then
    raise exception
      'not allowed';
  end if;

  if requested_schedule_day_id is null then
    raise exception
      'driver schedule day id is required';
  end if;

  select *
  into target_day
  from public.driver_schedule_days
  where id =
    requested_schedule_day_id
  for update;

  if not found then
    raise exception
      'driver schedule day not found';
  end if;

  select *
  into target_period
  from public.driver_schedule_periods
  where id =
    target_day.period_id
  for update;

  if not found then
    raise exception
      'driver schedule period not found';
  end if;

  if target_period.status <> 'draft' then
    raise exception
      'only draft driver schedules can be edited';
  end if;

  normalized_note :=
    nullif(
      trim(
        coalesce(
          requested_note,
          ''
        )
      ),
      ''
    );

  /*
   * הסרת שיבוץ מהיום.
   */
  if requested_assigned_user_id is null then
    update public.driver_schedule_days
    set
      assigned_user_id =
        null,

      assignment_source =
        null,

      is_locked =
        coalesce(
          requested_is_locked,
          false
        ),

      notes =
        normalized_note,

      updated_at =
        now()

    where id =
      target_day.id

    returning *
    into target_day;

    return jsonb_build_object(
      'scheduleDayId',
        target_day.id,

      'periodId',
        target_day.period_id,

      'dutyDate',
        target_day.duty_date,

      'assignedUserId',
        null,

      'assignedUserName',
        null,

      'assignmentSource',
        null,

      'isLocked',
        target_day.is_locked,

      'notes',
        target_day.notes,

      'hasWarnings',
        false,

      'warnings',
        '[]'::jsonb
    );
  end if;

  /*
   * בדיקת הכונן שנבחר.
   */
  select *
  into selected_driver
  from public.profiles
  where id =
    requested_assigned_user_id
    and role =
      'on_call'::public.user_role
    and is_active = true;

  if not found then
    raise exception
      'selected on-call driver was not found or is inactive';
  end if;

  /*
   * איסור קשיח על כוננות ביום רצוף.
   * הבדיקה נעשית לפי מי שמשובץ בפועל.
   */
  if exists (
    select 1
    from public.driver_schedule_days
      adjacent_day
    where adjacent_day.id <>
      target_day.id
      and adjacent_day.assigned_user_id =
        requested_assigned_user_id
      and adjacent_day.duty_date in (
        target_day.duty_date -
          1,
        target_day.duty_date +
          1
      )
  ) then
    raise exception
      'driver cannot be assigned on consecutive days';
  end if;

  /*
   * איתור הכוננות הקודמת והבאה של אותו כונן.
   */
  select
    max(schedule_day.duty_date)
  into previous_assignment_date
  from public.driver_schedule_days
    schedule_day
  where schedule_day.id <>
    target_day.id
    and schedule_day.assigned_user_id =
      requested_assigned_user_id
    and schedule_day.duty_date <
      target_day.duty_date;

  select
    min(schedule_day.duty_date)
  into next_assignment_date
  from public.driver_schedule_days
    schedule_day
  where schedule_day.id <>
    target_day.id
    and schedule_day.assigned_user_id =
      requested_assigned_user_id
    and schedule_day.duty_date >
      target_day.duty_date;

  if previous_assignment_date is not null then
    previous_gap_days :=
      target_day.duty_date -
      previous_assignment_date;

    if previous_gap_days between 2 and 4 then
      warning_messages :=
        array_append(
          warning_messages,
          format(
            'מרווח של %s ימים בלבד מהכוננות הקודמת',
            previous_gap_days
          )
        );
    end if;
  end if;

  if next_assignment_date is not null then
    next_gap_days :=
      next_assignment_date -
      target_day.duty_date;

    if next_gap_days between 2 and 4 then
      warning_messages :=
        array_append(
          warning_messages,
          format(
            'מרווח של %s ימים בלבד עד הכוננות הבאה',
            next_gap_days
          )
        );
    end if;
  end if;

  /*
   * בדיקת האילוץ שהכונן הגיש עבור היום.
   * עריכה ידנית עדיין מותרת, אך תוצג אזהרה.
   */
  if target_period.availability_period_id
    is not null
  then
    select
      availability_day.id
    into linked_availability_day_id
    from public.driver_availability_days
      availability_day
    where availability_day.period_id =
      target_period.availability_period_id
      and availability_day.availability_date =
        target_day.duty_date
    limit 1;

    if linked_availability_day_id is not null then
      select
        availability_entry.availability_status
      into selected_availability_status
      from public.driver_availability_entries
        availability_entry
      where availability_entry.period_id =
        target_period.availability_period_id
        and availability_entry.day_id =
          linked_availability_day_id
        and availability_entry.user_id =
          requested_assigned_user_id
      limit 1;

      if selected_availability_status =
        'unavailable'
      then
        warning_messages :=
          array_append(
            warning_messages,
            'הכונן סימן שאינו זמין בתאריך זה'
          );
      elsif selected_availability_status is null then
        warning_messages :=
          array_append(
            warning_messages,
            'לא נמצא סימון זמינות של הכונן לתאריך זה'
          );
      end if;
    end if;
  end if;

  final_note :=
    concat_ws(
      E'\n',
      normalized_note,
      case
        when cardinality(
          warning_messages
        ) > 0
        then
          'אזהרות: '
          ||
          array_to_string(
            warning_messages,
            '; '
          )
        else
          null
      end
    );

  final_note :=
    nullif(
      trim(
        coalesce(
          final_note,
          ''
        )
      ),
      ''
    );

  update public.driver_schedule_days
  set
    assigned_user_id =
      requested_assigned_user_id,

    assignment_source =
      'manual'
        ::public.driver_assignment_source,

    is_locked =
      coalesce(
        requested_is_locked,
        false
      ),

    notes =
      final_note,

    updated_at =
      now()

  where id =
    target_day.id

  returning *
  into target_day;

  return jsonb_build_object(
    'scheduleDayId',
      target_day.id,

    'periodId',
      target_day.period_id,

    'dutyDate',
      target_day.duty_date,

    'assignedUserId',
      target_day.assigned_user_id,

    'assignedUserName',
      coalesce(
        selected_driver.schedule_name,
        selected_driver.display_name
      ),

    'assignmentSource',
      target_day.assignment_source,

    'isLocked',
      target_day.is_locked,

    'notes',
      target_day.notes,

    'hasWarnings',
      cardinality(
        warning_messages
      ) > 0,

    'warnings',
      to_jsonb(
        warning_messages
      )
  );
end;
$$;


ALTER FUNCTION "public"."update_driver_schedule_day"("requested_schedule_day_id" "uuid", "requested_assigned_user_id" "uuid", "requested_is_locked" boolean, "requested_note" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."update_driver_schedule_day"("requested_schedule_day_id" "uuid", "requested_assigned_user_id" "uuid", "requested_is_locked" boolean, "requested_note" "text") IS 'Manually updates an on-call schedule day in a draft schedule. Consecutive-day assignments are prohibited; availability conflicts and short spacing generate warnings. Requires driver_schedule.edit.';



CREATE OR REPLACE FUNCTION "public"."update_dynamic_job_type_rotation_state"("requested_job_type_id" "uuid", "requested_rotation_user_ids" "uuid"[], "requested_anchor_date" "date", "requested_reason" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_actor uuid:=auth.uid();
  v_active_count integer;
begin
  if v_actor is null then raise exception 'not authenticated'; end if;
  if not exists(select 1 from public.user_permissions up where up.user_id=v_actor and up.permission_key='users.manage')
    then raise exception 'not allowed'; end if;
  if requested_anchor_date is null then raise exception 'anchor date is required'; end if;
  if requested_rotation_user_ids is null or cardinality(requested_rotation_user_ids)<2
    then raise exception 'rotation requires at least two members'; end if;
  if cardinality(requested_rotation_user_ids) <>
     (select count(distinct x) from unnest(requested_rotation_user_ids) x)
    then raise exception 'rotation contains duplicate members'; end if;

  select count(*)::integer into v_active_count
  from public.job_type_memberships m
  join public.profiles p on p.id=m.user_id and p.is_active=true
  where m.job_type_id=requested_job_type_id
    and m.user_id=any(requested_rotation_user_ids);

  if v_active_count<>cardinality(requested_rotation_user_ids) then
    raise exception 'rotation contains users who are not active members of this job type';
  end if;

  if v_active_count <> (
    select count(*) from public.job_type_memberships m
    join public.profiles p on p.id=m.user_id and p.is_active=true
    where m.job_type_id=requested_job_type_id
  ) then raise exception 'rotation must contain every active role member exactly once'; end if;

  insert into public.dynamic_job_type_rotation_state(
    job_type_id,rotation_user_ids,anchor_date,source,source_metadata,created_by
  ) values(
    requested_job_type_id,requested_rotation_user_ids,requested_anchor_date,'manual',
    jsonb_build_object('reason',nullif(trim(coalesce(requested_reason,'')),''),'updatedBy',v_actor,'updatedAt',now()),
    v_actor
  )
  on conflict(job_type_id) do update set
    rotation_user_ids=excluded.rotation_user_ids,
    anchor_date=excluded.anchor_date,
    source='manual',
    source_metadata=excluded.source_metadata,
    updated_at=now();

  insert into public.audit_logs(action,actor_user_id,entity_type,entity_id,summary,metadata)
  values('system_event',v_actor,'job_type',requested_job_type_id,'סבב חודשי עודכן ידנית',
    jsonb_build_object('rotationUserIds',to_jsonb(requested_rotation_user_ids),
      'anchorDate',requested_anchor_date,'reason',requested_reason));

  return public.get_dynamic_job_type_rotation_workspace(requested_job_type_id,requested_anchor_date,35);
end;
$$;


ALTER FUNCTION "public"."update_dynamic_job_type_rotation_state"("requested_job_type_id" "uuid", "requested_rotation_user_ids" "uuid"[], "requested_anchor_date" "date", "requested_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_morning_driver_schedule_assignment"("requested_assignment_id" "uuid", "requested_assigned_user_id" "uuid" DEFAULT NULL::"uuid", "requested_is_locked" boolean DEFAULT false, "requested_note" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  current_user_id uuid;
  current_permissions text[];

  target_assignment
    public.morning_driver_schedule_assignments%rowtype;

  target_period
    public.morning_driver_schedule_periods%rowtype;

  target_shift
    public.morning_driver_availability_shifts%rowtype;

  selected_driver
    public.profiles%rowtype;

  warning_messages text[] :=
    array[]::text[];

  normalized_note text;
begin
  current_user_id :=
    auth.uid();

  if current_user_id is null then
    raise exception
      'not authenticated';
  end if;

  if not exists (
    select 1
    from public.profiles profile
    where profile.id =
      current_user_id
      and profile.is_active = true
  ) then
    raise exception
      'user not active';
  end if;

  current_permissions :=
    coalesce(
      public.get_my_permissions(),
      array[]::text[]
    );

  if not (
    'morning_driver_schedule.edit' =
      any(current_permissions)
  ) then
    raise exception
      'not allowed';
  end if;

  if requested_assignment_id is null then
    raise exception
      'morning driver schedule assignment id is required';
  end if;

  select *
  into target_assignment
  from public.morning_driver_schedule_assignments
    assignment
  where assignment.id =
    requested_assignment_id
  for update;

  if not found then
    raise exception
      'morning driver schedule assignment not found';
  end if;

  select *
  into target_period
  from public.morning_driver_schedule_periods
    period
  where period.id =
    target_assignment.schedule_period_id
  for update;

  if not found then
    raise exception
      'morning driver schedule period not found';
  end if;

  /*
   * Managers with the edit permission may correct both
   * draft and already-published schedules.
   *
   * Archived historical schedules stay read-only.
   */
  if target_period.status not in (
    'draft',
    'published'
  ) then
    raise exception
      'only draft or published schedules can be edited';
  end if;

  select *
  into target_shift
  from public.morning_driver_availability_shifts
    shift_item
  where shift_item.id =
    target_assignment.availability_shift_id;

  if not found then
    raise exception
      'morning driver availability shift not found';
  end if;

  normalized_note :=
    nullif(
      trim(
        coalesce(
          requested_note,
          ''
        )
      ),
      ''
    );

  if requested_assigned_user_id is not null then
    select *
    into selected_driver
    from public.profiles profile
    where profile.id =
        requested_assigned_user_id
      and profile.role =
        'morning_driver'
          ::public.user_role
      and profile.is_active =
        true;

    if not found then
      raise exception
        'selected morning driver not found or inactive';
    end if;

    /*
     * Do not assign the same morning driver twice
     * to different slots of the same shift.
     */
    if exists (
      select 1
      from public.morning_driver_schedule_assignments
        duplicate_assignment
      where duplicate_assignment.schedule_period_id =
          target_assignment.schedule_period_id
        and duplicate_assignment.availability_shift_id =
          target_assignment.availability_shift_id
        and duplicate_assignment.id <>
          target_assignment.id
        and duplicate_assignment.assigned_user_id =
          requested_assigned_user_id
    ) then
      raise exception
        'driver is already assigned to this shift';
    end if;

    /*
     * Same-day assignment is kept as a warning,
     * matching the existing behavior.
     */
    if exists (
      select 1
      from public.morning_driver_schedule_assignments
        same_day_assignment
      join public.morning_driver_availability_shifts
        other_shift
        on other_shift.id =
          same_day_assignment.availability_shift_id
      where same_day_assignment.schedule_period_id =
          target_assignment.schedule_period_id
        and same_day_assignment.id <>
          target_assignment.id
        and same_day_assignment.assigned_user_id =
          requested_assigned_user_id
        and other_shift.shift_date =
          target_shift.shift_date
    ) then
      warning_messages :=
        array_append(
          warning_messages,
          'הכונן כבר משובץ במשמרת אחרת באותו יום'
        );
    end if;

    /*
     * Availability remains a warning for manual manager edits,
     * rather than a hard blocker.
     */
    if not exists (
      select 1
      from public.morning_driver_availability_entries
        entry
      where entry.period_id =
          target_period.availability_period_id
        and entry.shift_id =
          target_shift.id
        and entry.user_id =
          requested_assigned_user_id
        and entry.availability_status =
          'available'
    ) then
      warning_messages :=
        array_append(
          warning_messages,
          'הכונן לא סימן זמינות למשמרת זו'
        );
    end if;
  end if;

  update public.morning_driver_schedule_assignments
  set
    assigned_user_id =
      requested_assigned_user_id,

    assignment_source =
      case
        when requested_assigned_user_id
          is null
        then null

        else 'manual'
      end,

    is_intentionally_unassigned =
      case
        when requested_assigned_user_id is not null
        then false
        else coalesce(
          target_assignment.is_intentionally_unassigned,
          false
        )
      end,

    is_locked =
      coalesce(
        requested_is_locked,
        false
      ),

    notes =
      nullif(
        concat_ws(
          E'\n',
          normalized_note,
          case
            when cardinality(
              warning_messages
            ) > 0
            then
              'אזהרות: '
              ||
              array_to_string(
                warning_messages,
                '; '
              )

            else null
          end
        ),
        ''
      ),

    updated_at =
      now()

  where id =
    target_assignment.id

  returning *
  into target_assignment;

  return jsonb_build_object(
    'assignmentId',
      target_assignment.id,

    'schedulePeriodId',
      target_assignment.schedule_period_id,

    'scheduleStatus',
      target_period.status,

    'shiftDate',
      target_shift.shift_date,

    'assignedUserId',
      target_assignment.assigned_user_id,

    'assignedUserName',
      case
        when target_assignment.assigned_user_id
          is null
        then null

        else coalesce(
          selected_driver.schedule_name,
          selected_driver.display_name
        )
      end,

    'assignmentSource',
      target_assignment.assignment_source,

    'isLocked',
      target_assignment.is_locked,

    'notes',
      target_assignment.notes,

    'hasWarnings',
      cardinality(
        warning_messages
      ) > 0,

    'warnings',
      to_jsonb(
        warning_messages
      )
  );
end;
$$;


ALTER FUNCTION "public"."update_morning_driver_schedule_assignment"("requested_assignment_id" "uuid", "requested_assigned_user_id" "uuid", "requested_is_locked" boolean, "requested_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_morning_driver_schedule_shift_time"("requested_assignment_id" "uuid", "requested_start_time" time without time zone, "requested_end_time" time without time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  current_user_id uuid := auth.uid();
  current_permissions text[];
  target_assignment public.morning_driver_schedule_assignments%rowtype;
  target_period public.morning_driver_schedule_periods%rowtype;
begin
  if current_user_id is null then
    raise exception 'not authenticated';
  end if;

  current_permissions := coalesce(public.get_my_permissions(), array[]::text[]);
  if not ('morning_driver_schedule.edit' = any(current_permissions)) then
    raise exception 'not allowed';
  end if;

  if requested_start_time is null or requested_end_time is null then
    raise exception 'start and end time are required';
  end if;

  select * into target_assignment
  from public.morning_driver_schedule_assignments a
  where a.id = requested_assignment_id
  for update;

  if not found then
    raise exception 'morning driver schedule assignment not found';
  end if;

  select * into target_period
  from public.morning_driver_schedule_periods p
  where p.id = target_assignment.schedule_period_id;

  if target_period.status <> 'draft' then
    raise exception 'shift time can be changed only while schedule is draft';
  end if;

  update public.morning_driver_schedule_assignments a
  set scheduled_start_time = requested_start_time,
      scheduled_end_time = requested_end_time,
      updated_at = now()
  where a.schedule_period_id = target_assignment.schedule_period_id
    and a.availability_shift_id = target_assignment.availability_shift_id;

  return jsonb_build_object(
    'schedulePeriodId', target_assignment.schedule_period_id,
    'availabilityShiftId', target_assignment.availability_shift_id,
    'startTime', requested_start_time,
    'endTime', requested_end_time
  );
end;
$$;


ALTER FUNCTION "public"."update_morning_driver_schedule_shift_time"("requested_assignment_id" "uuid", "requested_start_time" time without time zone, "requested_end_time" time without time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_my_dynamic_published_assignment"("requested_publication_id" "uuid", "requested_assignment_id" "uuid", "requested_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  current_user_id uuid := auth.uid();
  target_publication public.dynamic_schedule_publications%rowtype;
  target_job public.job_types%rowtype;
  target_assignment public.dynamic_schedule_published_assignments%rowtype;
  current_month date := date_trunc('month', (now() at time zone 'Asia/Jerusalem')::date)::date;
  publication_month date;
  change_mode text;
  can_self_edit boolean := false;
  can_edit_all boolean := false;
  old_user_id uuid;
begin
  if current_user_id is null then
    raise exception 'not authenticated';
  end if;

  select * into target_publication
  from public.dynamic_schedule_publications
  where id = requested_publication_id
  for update;

  if target_publication.id is null then
    raise exception 'publication not found';
  end if;

  if target_publication.status <> 'published' then
    raise exception 'published schedule is not editable';
  end if;

  if not exists (
    select 1
    from public.job_type_memberships m
    join public.profiles p on p.id = m.user_id
    where m.job_type_id = target_publication.job_type_id
      and m.user_id = current_user_id
      and p.is_active = true
  ) then
    raise exception 'not allowed';
  end if;

  select * into target_job
  from public.job_types
  where id = target_publication.job_type_id
    and legacy_role is null;

  if target_job.id is null then
    raise exception 'dynamic job type not found';
  end if;

  change_mode := coalesce(
    target_publication.config_snapshot #>> '{jobType,scheduleChangeMode}',
    target_job.scheduling_config #>> '{scheduleChangeMode}',
    'none'
  );

  if change_mode <> 'self_edit' then
    raise exception 'self edit is not enabled for this role';
  end if;

  can_self_edit := public.has_dynamic_job_type_permission('schedule.self_edit', target_job.id, current_user_id);
  can_edit_all := public.has_dynamic_job_type_permission('schedule.edit_all', target_job.id, current_user_id);

  if not can_self_edit and not can_edit_all then
    raise exception 'not allowed';
  end if;

  publication_month := make_date(target_publication.year, target_publication.month, 1);
  if publication_month not in (current_month, (current_month + interval '1 month')::date) then
    raise exception 'only current month or next published month can be edited';
  end if;

  if not exists (
    select 1
    from public.job_type_memberships m
    join public.profiles p on p.id = m.user_id
    where m.job_type_id = target_publication.job_type_id
      and m.user_id = requested_user_id
      and p.is_active = true
  ) then
    raise exception 'requested user is not an active member of this role';
  end if;

  select * into target_assignment
  from public.dynamic_schedule_published_assignments
  where id = requested_assignment_id
    and publication_id = target_publication.id
  for update;

  if target_assignment.id is null then
    raise exception 'assignment not found';
  end if;

  -- Personal self-edit permits changing only the actor's current assignment.
  -- Editing another employee's assignment requires the explicit edit-all permission.
  if target_assignment.user_id <> current_user_id and not can_edit_all then
    raise exception 'editing another user''s assignment requires schedule.edit_all';
  end if;

  if target_assignment.user_id = requested_user_id then
    return jsonb_build_object('saved', true, 'changed', false, 'assignmentId', target_assignment.id);
  end if;

  if exists (
    select 1
    from public.dynamic_schedule_published_assignments a
    where a.publication_id = target_publication.id
      and a.shift_date = target_assignment.shift_date
      and a.shift_code = target_assignment.shift_code
      and a.user_id = requested_user_id
      and a.id <> target_assignment.id
  ) then
    raise exception 'requested user is already assigned to this shift';
  end if;

  old_user_id := target_assignment.user_id;

  update public.dynamic_schedule_published_assignments
  set user_id = requested_user_id,
      user_edited_by = current_user_id,
      user_edited_at = now()
  where id = target_assignment.id;

  insert into public.audit_logs(action, actor_user_id, entity_type, entity_id, summary, metadata)
  values(
    'system_event',
    current_user_id,
    'dynamic_schedule_publication',
    target_publication.id,
    case
      when old_user_id = current_user_id then 'שיבוץ אישי בלוח דינמי שונה על ידי העובד'
      else 'שיבוץ של עובד אחר בלוח דינמי שונה על ידי עובד מורשה'
    end,
    jsonb_build_object(
      'publication_id', target_publication.id,
      'job_type_id', target_publication.job_type_id,
      'assignment_id', target_assignment.id,
      'shift_date', target_assignment.shift_date,
      'shift_code', target_assignment.shift_code,
      'old_user_id', old_user_id,
      'new_user_id', requested_user_id,
      'can_view_others', can_view_others
    )
  );

  return jsonb_build_object(
    'saved', true,
    'changed', true,
    'assignmentId', target_assignment.id,
    'oldUserId', old_user_id,
    'newUserId', requested_user_id
  );
end;
$$;


ALTER FUNCTION "public"."update_my_dynamic_published_assignment"("requested_publication_id" "uuid", "requested_assignment_id" "uuid", "requested_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_schedule_draft_shift"("requested_shift_id" "uuid", "requested_new_user_id" "uuid" DEFAULT NULL::"uuid", "requested_intentionally_unassigned" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  current_user_id uuid := auth.uid();
  current_permissions text[];
  target_shift public.schedule_shifts%rowtype;
  target_period public.schedule_periods%rowtype;
  selected_name text;
begin
  if current_user_id is null then
    raise exception 'not authenticated';
  end if;

  current_permissions := coalesce(public.get_my_permissions(), array[]::text[]);
  if not ('schedule.edit' = any(current_permissions)) then
    raise exception 'not allowed';
  end if;

  select *
  into target_shift
  from public.schedule_shifts shift
  where shift.id = requested_shift_id
  for update;

  if not found then
    raise exception 'schedule shift not found';
  end if;

  select *
  into target_period
  from public.schedule_periods period
  where period.id = target_shift.period_id
  for update;

  if target_period.status not in (
    'draft'::public.schedule_period_status,
    'scheduling'::public.schedule_period_status
  ) then
    raise exception 'only draft schedules can be edited with this action';
  end if;

  if requested_intentionally_unassigned then
    update public.schedule_shifts
    set
      assigned_user_id = null,
      is_intentionally_unassigned = true,
      assignment_source = null,
      assignment_score = null,
      assignment_reasons = jsonb_build_array('המשמרת סומנה במפורש כלא מאוישת.'),
      updated_at = now()
    where id = target_shift.id;

    return jsonb_build_object(
      'shiftId', target_shift.id,
      'assignedUserId', null,
      'assignedUserName', null,
      'isIntentionallyUnassigned', true
    );
  end if;

  if requested_new_user_id is null then
    raise exception 'new user id is required';
  end if;

  select coalesce(profile.schedule_name, profile.display_name)
  into selected_name
  from public.profiles profile
  where profile.id = requested_new_user_id
    and profile.is_active = true
    and profile.role::text = 'dispatcher';

  if selected_name is null then
    raise exception 'selected dispatcher is missing, inactive, or is not a dispatcher';
  end if;

  if exists (
    select 1
    from public.schedule_shifts other_shift
    where other_shift.period_id = target_shift.period_id
      and other_shift.id <> target_shift.id
      and other_shift.assigned_user_id = requested_new_user_id
      and other_shift.starts_at < target_shift.ends_at
      and other_shift.ends_at > target_shift.starts_at
  ) then
    raise exception 'the selected dispatcher has an overlapping shift';
  end if;

  if exists (
    select 1
    from public.schedule_shifts other_shift
    where other_shift.period_id = target_shift.period_id
      and other_shift.id <> target_shift.id
      and other_shift.assigned_user_id = requested_new_user_id
      and (
        other_shift.ends_at = target_shift.starts_at
        or other_shift.starts_at = target_shift.ends_at
      )
  ) then
    raise exception 'the selected dispatcher has a consecutive shift';
  end if;

  update public.schedule_shifts
  set
    assigned_user_id = requested_new_user_id,
    is_intentionally_unassigned = false,
    assignment_source = 'manual'::public.assignment_source,
    assignment_score = null,
    assignment_reasons = jsonb_build_array('שיבוץ ידני מתוך מסך עריכת הטיוטה.'),
    updated_at = now()
  where id = target_shift.id;

  return jsonb_build_object(
    'shiftId', target_shift.id,
    'assignedUserId', requested_new_user_id,
    'assignedUserName', selected_name,
    'isIntentionallyUnassigned', false
  );
end;
$$;


ALTER FUNCTION "public"."update_schedule_draft_shift"("requested_shift_id" "uuid", "requested_new_user_id" "uuid", "requested_intentionally_unassigned" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_user_compensation"("target_user_id" "uuid", "requested_hourly_rate" numeric DEFAULT NULL::numeric, "requested_daily_duty_rate" numeric DEFAULT NULL::numeric, "requested_morning_shift_rate" numeric DEFAULT NULL::numeric) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  current_user_id uuid := auth.uid();
  current_permissions text[];
  target_role public.user_role;
begin
  if current_user_id is null then raise exception 'not authenticated'; end if;
  current_permissions := coalesce(public.get_my_permissions(), array[]::text[]);
  if not ('payroll.manage' = any(current_permissions)) then
    raise exception 'payroll manage permission required';
  end if;

  if requested_hourly_rate is not null and requested_hourly_rate < 0 then
    raise exception 'hourly rate cannot be negative';
  end if;
  if requested_daily_duty_rate is not null and requested_daily_duty_rate < 0 then
    raise exception 'daily duty rate cannot be negative';
  end if;
  if requested_morning_shift_rate is not null and requested_morning_shift_rate < 0 then
    raise exception 'morning shift rate cannot be negative';
  end if;

  select role into target_role
  from public.profiles
  where id = target_user_id
  for update;

  if not found then raise exception 'target user was not found'; end if;

  if target_role = 'dispatcher'::public.user_role then
    update public.profiles
    set hourly_rate = requested_hourly_rate,
        daily_duty_rate = null,
        morning_shift_rate = null,
        updated_at = now()
    where id = target_user_id;
  elsif target_role = 'on_call'::public.user_role then
    update public.profiles
    set hourly_rate = null,
        daily_duty_rate = requested_daily_duty_rate,
        morning_shift_rate = null,
        updated_at = now()
    where id = target_user_id;
  elsif target_role = 'morning_driver'::public.user_role then
    update public.profiles
    set hourly_rate = null,
        daily_duty_rate = null,
        morning_shift_rate = requested_morning_shift_rate,
        updated_at = now()
    where id = target_user_id;
  else
    raise exception 'compensation can be configured only for dispatchers, morning drivers and on-call drivers';
  end if;

  return true;
end;
$$;


ALTER FUNCTION "public"."update_user_compensation"("target_user_id" "uuid", "requested_hourly_rate" numeric, "requested_daily_duty_rate" numeric, "requested_morning_shift_rate" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_shift_swap_final_state"("requested_swap_type" "text", "requested_requester_user_id" "uuid", "requested_counterparty_user_id" "uuid", "requested_requester_shift_id" "uuid", "requested_counterparty_shift_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  requester_shift public.schedule_shifts%rowtype;
  counterparty_shift public.schedule_shifts%rowtype;
  target_period_id uuid;
  conflict_record record;
begin
  -- =======================================================
  -- 1. Basic input validation
  -- =======================================================

  if requested_swap_type not in ('one_way', 'two_way') then
    return jsonb_build_object(
      'valid', false,
      'code', 'invalid_swap_type',
      'message', 'סוג ההחלפה אינו תקין.'
    );
  end if;

  if requested_requester_user_id is null
    or requested_counterparty_user_id is null
    or requested_requester_user_id = requested_counterparty_user_id
  then
    return jsonb_build_object(
      'valid', false,
      'code', 'invalid_users',
      'message', 'יש לבחור שני מוקדנים שונים.'
    );
  end if;

  if requested_requester_shift_id is null then
    return jsonb_build_object(
      'valid', false,
      'code', 'missing_requester_shift',
      'message', 'יש לבחור את המשמרת שלך.'
    );
  end if;

  if requested_swap_type = 'two_way'
    and requested_counterparty_shift_id is null
  then
    return jsonb_build_object(
      'valid', false,
      'code', 'missing_counterparty_shift',
      'message', 'בהחלפה דו-כיוונית יש לבחור משמרת של המוקדן השני.'
    );
  end if;

  if requested_swap_type = 'two_way'
    and requested_counterparty_shift_id = requested_requester_shift_id
  then
    return jsonb_build_object(
      'valid', false,
      'code', 'same_shift',
      'message', 'יש לבחור שתי משמרות שונות להחלפה.'
    );
  end if;

  -- =======================================================
  -- 2. Resolve the actual schedule period and current owners
  -- =======================================================

  select *
  into requester_shift
  from public.schedule_shifts shift_row
  where shift_row.id = requested_requester_shift_id;

  if not found then
    return jsonb_build_object(
      'valid', false,
      'code', 'requester_shift_not_found',
      'message', 'המשמרת שלך לא נמצאה.'
    );
  end if;

  if requester_shift.assigned_user_id
    is distinct from requested_requester_user_id
  then
    return jsonb_build_object(
      'valid', false,
      'code', 'requester_shift_owner_changed',
      'message', 'השיבוץ של המשמרת שלך השתנה. יש לרענן ולנסות שוב.'
    );
  end if;

  target_period_id := requester_shift.period_id;

  if requested_swap_type = 'two_way' then
    select *
    into counterparty_shift
    from public.schedule_shifts shift_row
    where shift_row.id = requested_counterparty_shift_id;

    if not found then
      return jsonb_build_object(
        'valid', false,
        'code', 'counterparty_shift_not_found',
        'message', 'המשמרת של המוקדן השני לא נמצאה.'
      );
    end if;

    if counterparty_shift.period_id is distinct from target_period_id then
      return jsonb_build_object(
        'valid', false,
        'code', 'different_schedule_periods',
        'message', 'בהחלפה דו-כיוונית שתי המשמרות חייבות להיות מאותו חודש שיבוץ.'
      );
    end if;

    if counterparty_shift.assigned_user_id
      is distinct from requested_counterparty_user_id
    then
      return jsonb_build_object(
        'valid', false,
        'code', 'counterparty_shift_owner_changed',
        'message', 'השיבוץ של המוקדן השני השתנה. יש לרענן ולנסות שוב.'
      );
    end if;
  end if;

  -- =======================================================
  -- 3. Simulate the FINAL state of this schedule period
  -- =======================================================
  --
  -- Important:
  -- - Only shifts from target_period_id participate.
  -- - The two selected shifts are reassigned before checking.
  -- - Therefore two adjacent shifts that are exchanged between
  --   two dispatchers do NOT conflict with each other after the
  --   swap, because each dispatcher owns only one of them.
  -- =======================================================

  with simulated_assignments as (
    select
      shift_row.id,
      shift_row.starts_at,
      shift_row.ends_at,
      case
        when shift_row.id = requested_requester_shift_id
          then requested_counterparty_user_id

        when requested_swap_type = 'two_way'
          and shift_row.id = requested_counterparty_shift_id
          then requested_requester_user_id

        else shift_row.assigned_user_id
      end as simulated_user_id

    from public.schedule_shifts shift_row

    where shift_row.period_id = target_period_id
      and (
        shift_row.assigned_user_id in (
          requested_requester_user_id,
          requested_counterparty_user_id
        )
        or shift_row.id = requested_requester_shift_id
        or (
          requested_swap_type = 'two_way'
          and shift_row.id = requested_counterparty_shift_id
        )
      )
  ),

  relevant as (
    select *
    from simulated_assignments
    where simulated_user_id in (
      requested_requester_user_id,
      requested_counterparty_user_id
    )
  ),

  conflicts as (
    select
      first_shift.simulated_user_id as user_id,
      first_shift.id as first_shift_id,
      second_shift.id as second_shift_id,
      first_shift.starts_at as first_starts_at,
      first_shift.ends_at as first_ends_at,
      second_shift.starts_at as second_starts_at,
      second_shift.ends_at as second_ends_at,
      case
        when second_shift.starts_at < first_shift.ends_at
          then 'overlapping_shifts'
        else 'consecutive_shifts'
      end as conflict_type

    from relevant first_shift

    join relevant second_shift
      on second_shift.simulated_user_id = first_shift.simulated_user_id
      and second_shift.id <> first_shift.id
      and second_shift.starts_at >= first_shift.starts_at
      and (
        second_shift.starts_at < first_shift.ends_at
        or second_shift.starts_at = first_shift.ends_at
      )

    order by
      first_shift.starts_at,
      second_shift.starts_at

    limit 1
  )

  select *
  into conflict_record
  from conflicts;

  if found then
    return jsonb_build_object(
      'valid', false,
      'code', conflict_record.conflict_type,
      'message',
        case
          when conflict_record.conflict_type = 'overlapping_shifts'
            then 'ההחלפה יוצרת חפיפה בין משמרות של אחד המוקדנים.'
          else 'ההחלפה יוצרת משמרות רצופות לאותו מוקדן.'
        end,
      'userId', conflict_record.user_id,
      'firstShiftId', conflict_record.first_shift_id,
      'secondShiftId', conflict_record.second_shift_id
    );
  end if;

  return jsonb_build_object(
    'valid', true,
    'code', null,
    'message', null
  );
end;
$$;


ALTER FUNCTION "public"."validate_shift_swap_final_state"("requested_swap_type" "text", "requested_requester_user_id" "uuid", "requested_counterparty_user_id" "uuid", "requested_requester_shift_id" "uuid", "requested_counterparty_shift_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."write_audit_log"("requested_action" "public"."audit_action_type", "requested_target_user_id" "uuid", "requested_summary" "text", "requested_old_values" "jsonb" DEFAULT NULL::"jsonb", "requested_new_values" "jsonb" DEFAULT NULL::"jsonb", "requested_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  current_actor_id uuid;
  current_actor_email text;
  current_actor_display_name text;

  current_target_email text;
  current_target_display_name text;

  created_log_id uuid;
begin
  current_actor_id :=
    auth.uid();

  if current_actor_id is null then
    raise exception
      'User is not authenticated';
  end if;

  if requested_summary is null
     or length(
       trim(
         requested_summary
       )
     ) = 0
  then
    raise exception
      'Audit summary is required';
  end if;

  if requested_old_values is not null
     and jsonb_typeof(
       requested_old_values
     ) <> 'object'
  then
    raise exception
      'old_values must be a JSON object';
  end if;

  if requested_new_values is not null
     and jsonb_typeof(
       requested_new_values
     ) <> 'object'
  then
    raise exception
      'new_values must be a JSON object';
  end if;

  if requested_metadata is null
     or jsonb_typeof(
       requested_metadata
     ) <> 'object'
  then
    raise exception
      'metadata must be a JSON object';
  end if;

  select
    profile.email,
    profile.display_name
  into
    current_actor_email,
    current_actor_display_name
  from public.profiles profile
  where profile.id =
    current_actor_id;

  if current_actor_email is null then
    raise exception
      'Authenticated user profile was not found';
  end if;

  if requested_target_user_id
     is not null
  then
    select
      profile.email,
      profile.display_name
    into
      current_target_email,
      current_target_display_name
    from public.profiles profile
    where profile.id =
      requested_target_user_id;
  end if;

  insert into public.audit_logs (
    action,
    actor_user_id,
    actor_email,
    actor_display_name,
    target_user_id,
    target_email,
    target_display_name,
    entity_type,
    summary,
    old_values,
    new_values,
    metadata
  )
  values (
    requested_action::text,
    current_actor_id,
    current_actor_email,
    current_actor_display_name,
    requested_target_user_id,
    current_target_email,
    current_target_display_name,
    'user',
    trim(
      requested_summary
    ),
    requested_old_values,
    requested_new_values,
    requested_metadata
  )
  returning id
  into created_log_id;

  return created_log_id;
end;
$$;


ALTER FUNCTION "public"."write_audit_log"("requested_action" "public"."audit_action_type", "requested_target_user_id" "uuid", "requested_summary" "text", "requested_old_values" "jsonb", "requested_new_values" "jsonb", "requested_metadata" "jsonb") OWNER TO "postgres";


