    "file_size_bytes" bigint DEFAULT 0 NOT NULL,
    "year" integer NOT NULL,
    "month" integer NOT NULL,
    "period_type" "text" NOT NULL,
    "import_strategy" "text" NOT NULL,
    "status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "dispatcher_shifts_detected" integer DEFAULT 0 NOT NULL,
    "dispatcher_shifts_created" integer DEFAULT 0 NOT NULL,
    "dispatcher_shifts_updated" integer DEFAULT 0 NOT NULL,
    "dispatcher_shifts_skipped" integer DEFAULT 0 NOT NULL,
    "driver_duties_detected" integer DEFAULT 0 NOT NULL,
    "driver_duties_created" integer DEFAULT 0 NOT NULL,
    "driver_duties_updated" integer DEFAULT 0 NOT NULL,
    "driver_duties_skipped" integer DEFAULT 0 NOT NULL,
    "warning_count" integer DEFAULT 0 NOT NULL,
    "warnings" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "result_summary" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "error_message" "text",
    "schedule_period_id" "uuid",
    "driver_schedule_period_id" "uuid",
    "imported_by" "uuid",
    "started_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "completed_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
