    CONSTRAINT "schedule_import_runs_status_check" CHECK (("status" = ANY (ARRAY['pending'::"text", 'processing'::"text", 'completed'::"text", 'completed_with_warnings'::"text", 'failed'::"text"]))),
    CONSTRAINT "schedule_import_runs_strategy_check" CHECK (("import_strategy" = ANY (ARRAY['missing_only'::"text", 'replace'::"text", 'rebuild'::"text", 'historical_archive'::"text"]))),
